CERTS.push({"id":"tuunsa","name":"투자자산운용사","short":"투운사","cat":"금융","desc":"금융권 대표 자격증","icStyle":"black","accent":"#15171C","color":"#2F6BFF","ready":true,"info":{"org":"금융투자협회","count":100,"minutes":120,"format":"4지선다","eligibility":"응시자격 제한 없음"},"pass":{"total":70,"sub":40},"subjects":{"1":{"short":"금융상품·세제","full":"금융상품 및 세제"},"2":{"short":"투자운용·분석","full":"투자운용 및 전략 II·투자분석"},"3":{"short":"윤리·법규·운용","full":"직무윤리·법규·투자운용 I"}},"price":4900,"pdf":"#","ox":[{"s":1,"t":"증여세 납세의무는 증여계약을 체결하는 때 성립한다.","a":false,"e":"증여로 재산을 취득하는 때 성립한다."},{"s":1,"t":"직장공제회 초과반환금은 14%로 원천징수한다.","a":false,"e":"기본세율(6~45%)로 원천징수한다."},{"s":1,"t":"상속에 의한 주권 이전은 증권거래세 과세대상이 아니다.","a":true,"e":"상속·증여는 무상이전이라 증권거래세가 없다."},{"s":1,"t":"은행 RP는 예금자보호 대상이다.","a":false,"e":"은행의 CD·RP는 비보호 상품이다."},{"s":1,"t":"낙인 미발생 + 정기 조기상환 평가 구조의 ELS는 Step-down형이다.","a":true,"e":"Step-down형의 대표적인 구조다."},{"s":1,"t":"MBS는 일반적으로 회사채보다 신용등급이 낮다.","a":false,"e":"자산 담보와 신용보완으로 회사채보다 신용등급이 높다."},{"s":1,"t":"저당권 설정 여부는 등기사항증명서로 확인한다.","a":true,"e":"소유권·저당권 등 권리관계는 등기사항증명서로 확인한다."},{"s":2,"t":"리츠(REITs)는 현물출자로 설립할 수 있다.","a":false,"e":"발기설립만 가능하며 현물출자로 설립할 수 없다."},{"s":2,"t":"합병차익거래는 상황의존형(Event Driven) 전략이다.","a":true,"e":"합병차익거래·부실채권투자가 상황의존형이다."},{"s":2,"t":"MSCI는 한국을 선진시장(DM)으로 분류한다.","a":false,"e":"MSCI는 신흥시장(EM), FTSE는 선진시장(DM)으로 분류한다."},{"s":2,"t":"사무라이본드는 일본에서 비거주자가 엔화로 발행하는 외국채다.","a":true,"e":"사무라이본드 = 일본·엔화."},{"s":2,"t":"ROE = 매출액순이익률 × 총자산회전율 × (총자산/자기자본)이다.","a":true,"e":"듀퐁 분석의 3요소 분해식이다."},{"s":2,"t":"D₁ 1,000원, 요구수익률 10%, 성장률 5%면 항상성장모형 적정주가는 10,000원이다.","a":false,"e":"P = 1,000 / (0.10 − 0.05) = 20,000원."},{"s":2,"t":"배당성장률(g)은 유보율 × ROE로 구한다.","a":true,"e":"g = b × ROE."},{"s":2,"t":"두 자산의 상관계수가 0이면 포트폴리오 VaR는 두 VaR의 단순합이다.","a":false,"e":"단순합은 상관계수 1일 때. 0이면 √(VaR₁² + VaR₂²)."},{"s":2,"t":"다우이론에서 강세시장 제1국면은 과열국면이다.","a":false,"e":"1국면 매집 → 2국면 상승 → 3국면 과열."},{"s":3,"t":"순자본비율 50% 미만 ~ 0% 이상이면 경영개선요구 대상이다.","a":true,"e":"100% 미만 권고, 50% 미만 요구, 0% 미만 명령."},{"s":3,"t":"위법계약해지권은 계약 체결일로부터 3년 이내에 행사한다.","a":false,"e":"체결일로부터 5년, 안 날로부터 1년 이내."},{"s":3,"t":"전환사채 패리티 = 주식 시가 ÷ 전환가격 × 100이다.","a":true,"e":"예: 14,000 / 10,000 × 100 = 140%."},{"s":3,"t":"할인채의 듀레이션은 만기와 같다.","a":true,"e":"중간 현금흐름이 없어 듀레이션 = 만기."},{"s":3,"t":"콜옵션 매수자의 최대손실은 무한대다.","a":false,"e":"매수자의 최대손실은 지불한 프리미엄으로 한정된다."},{"s":3,"t":"CPPI 위험자산 투자액 = (포트폴리오 가치 − 최저보장가치) × 승수이다.","a":true,"e":"Cushion × 승수 = Exposure."},{"s":3,"t":"샤프비율은 초과수익률을 베타로 나눈 값이다.","a":false,"e":"표준편차로 나눈다. 베타로 나누는 건 트레이너비율."},{"s":3,"t":"기대수익률이 SML보다 위에 있으면 과소평가된 주식이다.","a":true,"e":"요구수익률보다 기대수익률이 높으므로 매수."},{"s":3,"t":"불편기대이론은 수익률곡선이 항상 우상향하는 이유를 설명한다.","a":false,"e":"우상향 경향은 유동성프리미엄이론으로 설명한다."}],"dist":{"1":20,"2":30,"3":50},"secPerQ":72,"questions":[{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"하","rev":0,"q":"다음 중 '거둔 세금을 어디에 쓸지 법으로 정해 두었는가'를 기준으로 조세를 나눈 것은?","o":["국세와 지방세","직접세와 간접세","종가세와 종량세","보통세와 목적세"],"a":3,"c":"조세는 기준에 따라 여러 쌍으로 나뉘어요. 세수의 용도, 과세주체, 부담의 전가, 과세표준 단위가 대표적인 기준이에요.","e":"세수의 쓰임새가 법으로 정해져 있으면 목적세(교육세·농어촌특별세 등), 정해져 있지 않으면 보통세예요.","w":["과세주체(국가냐 지방자치단체냐)에 따른 구분이에요.","조세부담이 다른 사람에게 넘어가는지(전가)에 따른 구분이에요.","과세표준을 가격으로 잡는지 수량으로 잡는지에 따른 구분이에요.",null],"m":"목적이 정해졌으면 목적세, 아무 데나 쓰면 보통세. 교육세·농어촌특별세가 대표 목적세예요.","t":"조세의 분류: 보통세와 목적세","k":"용돈을 '아무 데나 써도 되는 돈'과 '학원비로만 쓸 돈'으로 나누듯, 쓸 곳이 정해진 세금이 목적세예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"하","rev":0,"q":"증권거래세의 세율 구조에 관한 설명으로 가장 적절한 것은?","o":["과세표준이 커질수록 높은 세율이 적용되는 초과누진세이다","과세표준의 크기와 관계없이 같은 세율이 적용되는 비례세이다","보유기간이 길수록 낮은 세율이 적용된다","양도차익이 클수록 높은 세율이 적용된다"],"a":1,"c":"세율 구조에는 금액과 관계없이 같은 세율을 적용하는 비례세와, 금액이 클수록 세율이 오르는 누진세가 있어요.","e":"증권거래세는 양도가액에 정해진 세율을 그대로 곱하는 비례세예요.","w":["누진세는 소득세·법인세·상속세·증여세예요. 증권거래세는 해당하지 않아요.",null,"보유기간에 따라 세율이 달라지지 않아요.","증권거래세는 이익이 아니라 거래금액에 매겨서 양도차익과 무관해요."],"m":"증권거래세는 금액과 상관없이 같은 세율 = 비례세. 누진세는 소득세·상속세·증여세.","t":"증권거래세의 세율 구조(비례세)","k":"얼마를 팔든 같은 비율로 떼면 비례세, 많이 벌수록 비율이 오르면 누진세예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"거주자의 소득세 과세기간에 관한 설명으로 가장 적절하지 않은 것은?","o":["거주자가 주소를 국외로 옮겨 비거주자가 되면 1월 1일부터 출국한 날까지가 과세기간이 된다","거주자가 사망하면 1월 1일부터 사망한 날까지가 과세기간이 된다","원칙적인 과세기간은 1월 1일부터 12월 31일까지이다","연도 중에 사업을 시작했다면 사업개시일부터 12월 31일까지가 과세기간이 된다"],"a":3,"c":"소득세 과세기간은 원칙적으로 1월 1일~12월 31일이고, 예외는 사망과 출국 두 가지뿐이에요.","e":"사업을 시작하거나 그만둬도 소득세 과세기간은 바뀌지 않아요. 사업 개시·폐업에 따라 과세기간이 달라지는 건 부가가치세예요.","w":["출국으로 비거주자가 되는 경우의 예외를 정확히 설명했어요.","사망 시 예외를 정확히 설명했어요.","원칙적인 과세기간을 정확히 설명했어요.",null],"m":"과세기간 예외는 \"사·출\" 두 개뿐(사망·출국). 사업을 시작하거나 폐업해도 1/1~12/31 그대로예요.","t":"소득세 과세기간","k":"소득세의 1년은 1월 1일~12월 31일로 고정이에요. 중간에 사업을 시작해도 그대로고, 사망·출국 때만 짧아져요."},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"중","rev":0,"q":"금융소득종합과세 부담을 줄이는 방법으로 효과가 없는 것은?","o":["예금 만기를 여러 해로 나누어 이자가 한 해에 몰리지 않게 한다","소득이 생기기 전에 원금 일부를 증여재산공제 범위 안에서 배우자에게 증여해 둔다","올해 이미 받은 배당금을 연말에 자녀 계좌로 옮겨 자녀의 소득으로 신고한다","ISA처럼 비과세·분리과세 혜택이 있는 상품을 먼저 활용한다"],"a":2,"c":"금융소득은 실제로 받은 사람에게 귀속돼요. 소득을 나누려면 소득이 생기기 전에 원금을 옮겨야 해요.","e":"이미 받은 배당금은 받은 사람의 소득으로 확정돼서, 나중에 다른 사람 계좌로 옮겨도 원래 사람에게 과세돼요.","w":["이자가 한 해에 몰리지 않게 나누는 대표적인 절세 방법이에요.","원금을 미리 옮겨 두면 그 뒤 생기는 이자·배당은 배우자의 소득이 돼요.",null,"비과세·분리과세 상품은 종합과세 대상 금액을 줄여 줘요."],"m":"\"열매 말고 나무를 옮겨라\" — 이미 받은 이자·배당을 옮겨도 소용없고, 원금을 미리 옮겨야 해요.","t":"금융소득종합과세 절세 방법","k":"이미 내 통장에 들어온 이자를 가족에게 넘겨도 세금은 내 몫이에요. 나누려면 이자가 생기기 전에 원금을 줘야 해요."},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"중","rev":0,"q":"다음 중 원천징수로 납세의무가 끝나는 완납적 원천징수에 해당하는 것은?","o":["일용근로자가 받은 급여에 대한 원천징수","연간 금융소득이 2천만원을 넘는 사람의 이자소득 원천징수","인적용역 사업소득에 대한 3.3% 원천징수","상용근로자가 매달 받는 급여에 대한 원천징수"],"a":0,"c":"원천징수에는 그것으로 과세가 끝나는 완납적 원천징수와, 미리 떼고 나중에 정산하는 예납적 원천징수가 있어요.","e":"일용근로자 급여는 종합소득에 합산하지 않고 원천징수로 과세가 끝나요.","w":[null,"2천만원을 넘는 금융소득은 종합과세되어 확정신고 때 정산해요.","사업소득 3.3%는 종합소득세 신고 때 다시 정산해서 예납적이에요.","상용근로자 급여는 연말정산으로 다시 정산해서 예납적이에요."],"m":"\"일용직은 떼면 끝\" — 일용근로 급여·분리과세 이자처럼 원천징수로 끝나면 완납적, 나중에 정산하면 예납적.","t":"완납적 원천징수와 예납적 원천징수","k":"완납적은 '떼면 끝', 예납적은 '일단 떼고 나중에 정산'이에요."},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"중","rev":0,"q":"거주자의 종합소득세 계산 흐름을 순서대로 바르게 나열한 것은?","o":["종합소득금액 → 세액공제 차감 → 과세표준 → 세율 적용 → 산출세액 → 종합소득공제 차감 → 결정세액","종합소득금액 → 종합소득공제 차감 → 과세표준 → 세율 적용 → 산출세액 → 세액공제·감면 차감 → 결정세액","총수입금액 → 종합소득공제 차감 → 소득금액 → 필요경비 차감 → 과세표준 → 산출세액","산출세액 → 기납부세액 차감 → 결정세액 → 가산세 가산 → 납부할 세액"],"a":1,"c":"소득공제는 과세표준을 만들 때, 세액공제는 산출세액에서 빼는 단계에서 작동해요.","e":"종합소득금액에서 소득공제를 빼 과세표준을 만들고, 세율을 곱한 산출세액에서 세액공제·감면을 빼면 결정세액이에요.","w":["세액공제와 소득공제의 위치가 뒤바뀌었어요.",null,"필요경비는 총수입금액에서 바로 빼야 소득금액이 돼요.","기납부세액은 결정세액에 가산세를 더한 뒤 마지막에 빼요."],"m":"\"소·공·과·세·산·세\" — 소득금액 → 소득공제 → 과세표준 → 세율 → 산출세액 → 세액공제.","t":"종합소득세 계산 흐름","k":"번 돈 → 빼 주는 돈(소득공제) → 세금 매길 금액 → 세율 곱하기 → 세금 → 깎아 주는 돈(세액공제) 순서예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","rev":0,"q":"국세기본법상 납세의무의 성립시기를 바르게 연결한 것을 〈보기〉에서 모두 고른 것은?\n〈보기〉\nㄱ. 종합부동산세 — 과세기준일\nㄴ. 증여세 — 증여계약서를 작성한 때\nㄷ. 원천징수하는 소득세 — 소득금액을 지급하는 때\nㄹ. 인지세 — 과세문서를 작성한 때\nㅁ. 상속세 — 상속세 과세표준을 신고한 때","o":["ㄱ, ㄴ, ㄷ","ㄷ, ㄹ, ㅁ","ㄴ, ㄹ, ㅁ","ㄱ, ㄷ, ㄹ"],"a":3,"c":"납세의무는 법이 정한 요건이 갖춰지는 때 성립하고, 신고나 고지는 이를 확정하는 절차예요.","e":"종합부동산세는 과세기준일, 원천징수 소득세는 소득금액을 지급하는 때, 인지세는 과세문서를 작성하는 때 성립해요. 그래서 ㄱ·ㄷ·ㄹ이 맞아요.","w":["ㄴ이 틀렸어요. 증여세는 증여로 재산을 취득하는 때 성립해요.","ㅁ이 틀렸고 ㄱ이 빠졌어요.","ㄴ·ㅁ이 틀렸어요. 상속세는 상속이 개시되는 때 성립해요.",null],"m":"성립은 \"요건이 갖춰질 때\", 확정은 \"신고·고지할 때\". 소득세는 과세기간 끝, 상속세는 상속 개시, 증여세는 재산 취득 때.","t":"납세의무의 성립시기","k":"성립은 '세금이 생긴 순간', 확정은 '얼마인지 정해진 순간'이에요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","rev":0,"q":"〈보기〉 가운데 국세 납부의무의 소멸사유에 해당하는 것은 모두 몇 개인가?\n〈보기〉\nㄱ. 세금을 납부한 경우\nㄴ. 환급금을 체납세액에 충당한 경우\nㄷ. 부과처분이 취소된 경우\nㄹ. 국세부과 제척기간이 만료된 경우\nㅁ. 납세의무자인 개인이 사망한 경우\nㅂ. 납세의무가 있는 법인이 다른 법인에 흡수합병된 경우","o":["3개","4개","5개","6개"],"a":1,"c":"납부의무 소멸사유는 납부·충당·부과 취소·제척기간 만료·징수권 소멸시효 완성이에요. 사망과 합병은 의무가 넘어가는 승계예요.","e":"ㄱ~ㄹ의 4개가 소멸사유예요. ㅁ의 사망은 상속인에게, ㅂ의 합병은 합병 후 법인에게 의무가 승계돼요.","w":["ㄱ~ㄹ 4개가 모두 소멸사유인데 그중 하나를 빠뜨렸어요. 납부뿐 아니라 충당·부과 취소·제척기간 만료도 모두 소멸사유예요.",null,"ㅁ의 사망이나 ㅂ의 합병까지 소멸사유로 셌어요. 둘 다 의무가 없어지는 게 아니라 상속인·합병 후 법인에게 넘어가는(승계) 사유예요.","ㅁ·ㅂ은 모두 승계 사유라서 소멸사유가 아니에요."],"m":"소멸 5종 \"납·충·취·제·시\" — 납부·충당·부과취소·제척기간 만료·소멸시효 완성. 사망·합병은 승계.","t":"납부의무의 소멸사유","k":"세금 빚이 없어지는 건 냈을 때, 돌려받을 돈으로 퉁쳤을 때, 부과가 취소됐을 때, 기간이 지났을 때예요.","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"하","rev":0,"q":"국세기본법상 서류의 송달에 관한 설명으로 가장 적절한 것은?","o":["전자송달은 송달받을 자가 신청한 경우에만 할 수 있다","공시송달은 공고한 날부터 30일이 지나야 송달된 것으로 본다","교부송달은 송달받을 자의 주소지 외의 장소에서는 할 수 없다","납부고지서는 금액과 관계없이 모두 일반우편으로 보낼 수 있다"],"a":0,"c":"송달 방법에는 교부·우편·전자·공시송달이 있고, 방법마다 요건이 달라요.","e":"전자송달은 신청주의라 송달받을 사람이 신청한 경우에만 할 수 있어요.","w":[null,"공시송달은 공고일부터 14일이 지나면 송달된 것으로 봐요.","상대방이 거부하지 않으면 주소지 밖에서도 교부송달할 수 있어요.","납부고지·독촉 서류는 원칙적으로 등기우편이고, 일정 금액 미만만 일반우편이 허용돼요."],"m":"\"전자송달은 신청한 사람만\" — 본인이 신청해야 전자로 받을 수 있어요.","t":"서류의 송달","k":"세무서 서류는 직접·우편·전자·공고로 받을 수 있어요. 전자로 받으려면 내가 먼저 신청해야 해요."},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"상","rev":0,"q":"거주자 지수(28세)는 아버지로부터 2019년 3월에 현금 3,000만원, 2026년 5월에 현금 8,000만원을 증여받았다. 2026년 5월 증여분에 대한 증여세 과세표준은? (단, 그 밖의 증여는 없고 혼인·출산 증여재산공제와 감정평가수수료는 고려하지 않는다)","o":["3,000만원","6,000만원","8,000만원","1억 1,000만원"],"a":1,"c":"같은 사람(직계존속은 그 배우자 포함)에게서 10년 안에 받은 증여는 합산하고, 증여재산공제도 10년 합산 한도로 적용해요.","e":"과세가액은 3,000만 + 8,000만 = 1억 1,000만원이고, 성년 자녀의 공제한도 5,000만원을 빼면 과세표준은 6,000만원이에요.","w":["2026년분 8,000만원에서만 공제 5,000만원을 뺀 값이에요. 10년 합산을 빠뜨렸어요.",null,"공제가 이미 소진됐다고 보고 2026년분만 계산한 값이에요. 합산과 공제를 둘 다 잘못 적용했어요.","합산은 했지만 증여재산공제를 빼지 않은 값이에요."],"m":"\"10년 합산, 공제도 10년에 한 번\" — 성인 자녀가 직계존속에게 받으면 10년간 5,000만원 공제.","f":"과세표준 = (3,000만 + 8,000만) − 5,000만 = 6,000만원","t":"증여재산 10년 합산과 증여재산공제","k":"아버지에게 10년 동안 받은 돈은 모두 더하고, 성인 자녀 공제 5,000만원은 10년에 한 번만 빼요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"국세징수권의 소멸시효에 관한 설명으로 가장 적절하지 않은 것은?","o":["압류는 소멸시효의 중단사유에 해당한다","5억원 미만 국세의 소멸시효는 5년이다","시효가 중단되더라도 이미 지난 기간은 그대로 인정되고 남은 기간만 이어서 진행된다","5억원 이상 국세의 소멸시효는 10년이다"],"a":2,"c":"소멸시효의 '중단'과 '정지'를 구분해야 해요. 중단은 처음부터 다시, 정지는 멈췄다가 이어서 진행해요.","e":"시효가 중단되면 지난 기간은 효력을 잃고, 중단사유가 끝난 때부터 처음부터 다시 진행해요. 남은 기간만 이어지는 건 정지예요.","w":["압류는 납부고지·독촉·교부청구와 함께 대표적인 중단사유예요.","5억원 미만 국세의 소멸시효를 정확히 설명했어요.",null,"5억원 이상 국세의 소멸시효를 정확히 설명했어요."],"m":"\"중단은 0부터, 정지는 일시정지\" — 중단되면 처음부터 다시, 정지되면 멈췄다 이어서.","t":"국세징수권 소멸시효의 중단과 정지","k":"중단은 게임을 처음부터 다시 시작, 정지는 일시정지 후 이어 하기예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"금액과 관계없이 원천징수로 과세가 끝나는 무조건 분리과세 금융소득은?","o":["국내 주식형 펀드에서 받은 이익","상장법인으로부터 받은 현금배당","시중은행 정기예금 이자","직장공제회 초과반환금"],"a":3,"c":"금융소득은 무조건 분리과세, 조건부 종합과세(2천만원 기준), 무조건 종합과세로 나뉘어요.","e":"직장공제회 초과반환금은 금액과 관계없이 원천징수로 과세가 끝나는 무조건 분리과세 대상이에요.","w":["펀드 이익(배당소득)도 2천만원 기준이 적용되는 조건부 대상이에요.","일반 배당은 연 2천만원을 넘으면 종합과세되는 조건부 대상이에요.","정기예금 이자도 2천만원 기준이 적용되는 조건부 대상이에요.",null],"m":"무조건 분리과세: 직장공제회 초과반환금, 비실명 금융소득, 법원 보증금·경락대금 이자 등.","t":"무조건 분리과세 금융소득","k":"따로 신고할 필요 없이 떼는 걸로 끝나는 금융소득이에요. 직장공제회 돈이 대표적이에요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"개인이 얻은 다음 소득 가운데 양도소득세 과세대상인 것은?","o":["보유하던 국고채를 팔아 얻은 차익","보유하던 회사채를 팔아 얻은 차익","대주주가 아닌 개인이 증권시장에서 상장주식을 팔아 얻은 차익","장외에서 비상장주식을 팔아 얻은 차익"],"a":3,"c":"양도소득세는 법에 열거된 자산만 과세하는 열거주의예요.","e":"비상장주식 양도차익은 열거된 과세대상이라 양도소득세가 붙어요.","w":["국고채도 채권이라 매매차익은 과세되지 않아요.","개인의 채권 매매차익은 열거되지 않아 과세되지 않아요. 채권은 이자만 과세돼요.","소액주주가 장내에서 판 상장주식 차익은 과세되지 않아요.",null],"m":"\"양도세는 법에 적힌 것만\" — 비상장주식, 장외 양도, 대주주 상장주식은 과세.","t":"양도소득세 과세대상","k":"양도세는 '법에 적힌 것만' 걷어요. 비상장주식을 장외에서 팔면 적혀 있어서 과세돼요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"국세기본법상 조세불복절차에 관한 설명으로 가장 적절한 것은?","o":["행정소송을 하려면 이의신청을 반드시 먼저 거쳐야 한다","같은 처분에 대하여 심사청구를 거친 뒤 다시 심판청구를 할 수 있다","심사청구와 심판청구 중 하나를 거치면 행정소송을 제기할 수 있다","불복청구는 처분이 있음을 안 날부터 180일 이내에 하여야 한다"],"a":2,"c":"조세불복은 이의신청(선택) → 심사청구 또는 심판청구(택일) → 행정소송 순서예요.","e":"심사청구와 심판청구는 둘 중 하나만 고르는 관계이고, 하나를 거치면 바로 행정소송으로 갈 수 있어요.","w":["이의신청은 거치지 않아도 되는 선택 절차예요.","심사청구와 심판청구는 같은 처분에 대해 중복할 수 없어요.",null,"청구기간은 처분이 있음을 안 날부터 90일 이내예요."],"m":"\"이·심·행\" — 이의신청(선택) → 심사청구 또는 심판청구(하나만) → 행정소송.","t":"조세불복절차","k":"세금이 억울하면 이의신청(선택) → 심사나 심판 중 하나 → 법원 순서로 다퉈요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"2026년 현재 상장주식 양도소득세를 판단하는 대주주 기준으로 옳은 것은?","o":["유가증권시장 — 지분율 4% 이상 또는 종목당 시가총액 50억원 이상","코스닥시장 — 지분율 2% 이상 또는 종목당 시가총액 50억원 이상","코넥스시장 — 지분율 1% 이상 또는 종목당 시가총액 50억원 이상","코스닥시장 — 지분율 2% 이상 또는 종목당 시가총액 30억원 이상"],"a":1,"c":"대주주 기준은 지분율과 시가총액 중 하나만 넘어도 해당돼요. 시가총액 기준은 모든 시장이 같아요.","e":"코스닥시장은 지분율 2% 이상 또는 종목당 시가총액 50억원 이상이면 대주주예요.","w":["유가증권시장의 지분율 기준은 1%예요.",null,"코넥스시장의 지분율 기준은 4%예요.","시가총액 기준은 시장과 관계없이 50억원이에요."],"m":"대주주 지분율 \"1·2·4\" (코스피·코스닥·코넥스), 시가총액 기준은 모두 50억원.","t":"2026년 대주주 기준","k":"지분이 코스피 1%, 코스닥 2%, 코넥스 4% 이상이거나 한 종목을 50억원 넘게 가지면 대주주예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"상","rev":0,"q":"국내사업장이 없는 비거주자가 국내 주식을 양도한 경우, 취득가액과 양도비용이 확인될 때의 원천징수세액은?","o":["양도가액의 10%와 양도차익의 10% 중 적은 금액","양도가액의 20%","양도가액의 10%와 양도차익의 20% 중 적은 금액","양도차익의 22%"],"a":2,"c":"국내사업장이 없는 비거주자의 국내원천소득은 지급할 때 원천징수로 과세해요.","e":"주식 양도소득은 양도가액의 10%가 원칙이고, 취득가액과 양도비용이 확인되면 양도가액의 10%와 양도차익의 20% 중 적은 금액이에요.","w":["양도차익 쪽 세율은 10%가 아니라 20%예요.","양도가액 기준 세율은 20%가 아니라 10%예요.",null,"양도차익에 22%를 곱하는 방식은 비거주자 원천징수 방식이 아니에요."],"m":"비거주자 주식 양도는 \"10과 20 중 작은 것\".","f":"원천징수세액 = Min(양도가액 × 10%, 양도차익 × 20%)","t":"비거주자 주식 양도 원천징수","k":"외국인이 한국 주식을 팔면 판 금액의 10%와 번 금액의 20% 중 적은 쪽을 미리 떼요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"소득세법상 거주자에 관한 설명으로 가장 적절한 것은?","o":["외국 국적자는 국내에 주소가 있어도 비거주자로 본다","국내에 주소를 두거나 183일 이상 거소를 둔 개인은 거주자이다","국내에 90일 이상 거소를 두면 거주자로 본다","거주자는 국내에서 발생한 소득에 대해서만 소득세를 낸다"],"a":1,"c":"거주자 여부는 국적이 아니라 국내 주소나 183일 이상의 거소로 판단해요.","e":"국내에 주소를 두거나 183일 이상 거소를 둔 개인은 거주자예요.","w":["국적과 관계없이 국내 주소가 있으면 거주자예요.",null,"기준은 90일이 아니라 183일이에요.","거주자는 국내외 모든 소득에 납세의무가 있어요."],"m":"\"국적 말고 주소\" — 국내 주소나 183일 이상 거소가 있으면 거주자.","t":"거주자 판정","k":"국적이 아니라 '한국에 사는가'로 봐요. 주소가 있거나 183일 넘게 머물면 거주자예요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"다음 중 종합소득세 확정신고를 하여야 하는 사람은? (단, 각자 아래 소득 외에는 다른 소득이 없고, 고배당기업 배당소득 분리과세 특례는 적용하지 않는다)","o":["근로소득만 있고 연말정산을 마친 사람","정기예금 이자 1,500만원만 받은 사람","퇴직소득만 있는 사람","예금이자 900만원과 상장주식 배당금 1,300만원을 받은 사람"],"a":3,"c":"종합소득세 확정신고 의무는 분리과세나 연말정산으로 과세가 끝나지 않는 소득이 있을 때 생겨요.","e":"이자와 배당을 합한 금융소득이 2,200만원으로 2천만원을 넘어 종합과세되므로 확정신고를 해야 해요.","w":["연말정산을 마친 근로소득만 있으면 확정신고 의무가 없어요.","2천만원 이하 금융소득은 원천징수로 과세가 끝나요.","퇴직소득은 원천징수로 과세가 끝나 확정신고 의무가 없어요.",null],"m":"금융소득 합계가 2,000만원을 넘으면 종합과세 → 확정신고. 900만 + 1,300만 = 2,200만원.","t":"종합소득세 확정신고 의무","k":"금융소득이 1년에 2,000만원을 넘으면 다른 소득과 합쳐서 직접 신고해야 해요.","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"중","rev":0,"q":"금융소득종합과세의 과세단위에 관한 설명으로 가장 적절한 것은?","o":["금융소득이 2천만원을 넘는지는 개인별로 판단한다","같은 세대에 사는 가족 전체의 금융소득을 합산한다","부부의 금융소득을 합산해 2천만원 초과 여부를 판단한다","미성년 자녀의 금융소득은 부모의 금융소득에 합산한다"],"a":0,"c":"금융소득종합과세는 가족 단위가 아니라 개인 단위로 판단해요.","e":"2천만원 초과 여부는 개인별로 판단해요.","w":[null,"세대 단위로 합산하지 않아요.","부부 합산과세는 위헌결정으로 폐지됐어요.","자녀의 금융소득도 부모와 합산하지 않아요."],"m":"\"2천만원은 개인별\" — 부부·가족 소득을 합치지 않아요.","t":"금융소득종합과세의 과세단위","k":"2,000만원 기준은 부부나 가족을 합치지 않고 한 사람씩 따져요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","rev":0,"q":"거주자 을이 2026년 4월에 금융투자업자를 통하지 않고 장외에서 비상장주권을 다른 개인에게 직접 양도하였다. 을의 증권거래세 신고·납부 기한은?","o":["2026년 8월 31일","2026년 5월 10일","2027년 5월 31일","2026년 6월 30일"],"a":0,"c":"증권거래세 신고·납부 기한은 거래 경로에 따라 달라요. 장내거래나 금융투자업자를 통한 거래는 그 기관이 모아서 내요.","e":"금융투자업자를 거치지 않은 양도는 양도일이 속하는 반기의 말일부터 2개월 이내에 신고·납부해요. 4월 양도분은 8월 31일이 기한이에요.","w":[null,"다음 달 10일은 예탁결제원·금융투자업자가 매달 모아 신고하는 경우의 기한이에요.","5월 31일은 종합소득세 확정신고 기한이에요.","반기 말일 자체는 기한 계산의 기준일일 뿐이에요."],"m":"장외 직접 양도는 \"반기 말 + 2개월\".","f":"4월 양도 → 상반기 말(6/30) + 2개월 = 8월 31일","t":"증권거래세 신고·납부기한","k":"증권사를 거치지 않고 직접 팔았다면, 판 날이 속한 반기의 끝에서 2달 안에 신고해요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"직장인 김씨가 올해 받은 금융소득은 은행 예금이자 800만원, 지인에게 돈을 빌려주고 받은 이자 200만원, 경매에 참여하며 법원에 맡겼던 보증금의 이자 100만원이다. 이 소득들을 지급받을 때 떼인 소득세는 모두 얼마인가? (지방소득세 제외)","o":["154만원","176만원","187만원","275만원"],"a":1,"c":"금융소득 원천징수세율은 일반 이자·배당 14%, 비영업대금의 이익 25%, 비실명 45%(또는 90%)예요.","e":"800×14% + 200×25% + 100×14% = 112 + 50 + 14 = 176만원이에요.","w":["모든 소득에 14%를 적용한 값이에요. 비영업대금의 이익은 25%예요.",null,"경매보증금 이자에 25%를 적용한 값이에요. 경매보증금 이자는 14%예요.","모든 소득에 25%를 적용한 값이에요."],"m":"원천징수 세율 \"14·25·45\" — 일반 14%, 비영업대금 25%, 비실명 45%.","f":"원천징수세액 = 각 소득 × 해당 세율을 모두 더한 값","t":"금융소득 원천징수세율","k":"이자 종류마다 떼는 비율이 달라서, 각각 곱한 뒤 더하면 돼요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"2017년 12월 31일 이전에 발행된 만기 10년 이상의 채권을 3년 이상 보유한 거주자가 그 이자에 대해 분리과세를 신청한 경우 적용되는 원천징수세율은?","o":["14%","25%","30%","45%"],"a":2,"c":"요건을 갖춘 장기채권 이자는 신청하면 분리과세로 과세를 끝낼 수 있어요.","e":"2017년 이전 발행, 만기 10년 이상, 3년 이상 보유 요건을 갖추고 분리과세를 신청하면 30%로 원천징수하고 끝나요.","w":["14%는 분리과세를 신청하지 않았을 때의 일반 원천징수세율이에요.","25%는 비영업대금의 이익에 적용하는 세율이에요.",null,"45%는 비실명 금융소득에 적용하는 세율이에요."],"m":"장기채권 분리과세 신청세율은 30%.","t":"장기채권 이자 분리과세","k":"오래 묵힌 장기채권 이자는 신청하면 30%만 떼고 끝낼 수 있어요."},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"상","rev":0,"q":"거주자 무의 2026년 금융소득이 다음과 같을 때 종합소득금액에 합산되는 금융소득금액은? (Gross-up 비율은 10%, 고배당기업 배당소득 분리과세 특례는 적용하지 않으며, 다른 소득은 고려하지 않는다)\n· 정기예금 이자 1,500만원\n· 상장 내국법인의 현금배당 1,500만원\n· 비실명 이자소득 500만원","o":["3,000만원","3,100만원","3,150만원","3,600만원"],"a":1,"c":"무조건 분리과세 소득을 먼저 빼고, 2천만원을 넘으면 Gross-up(배당가산액)을 더해요. 2천만원은 이자부터 채워요.","e":"비실명 500만원을 빼면 3,000만원이고, 2천만원을 넘는 배당 1,000만원에 10%를 더해 3,100만원이에요.","w":["Gross-up을 빠뜨린 값이에요.",null,"Gross-up 비율을 15%로 잘못 적용한 값이에요. 현재 비율은 10%예요.","무조건 분리과세인 비실명 이자 500만원을 정답 3,100만원에 그대로 더한 값이에요. 비실명 이자는 종합과세 판단에서 아예 빼요."],"m":"순서: ① 무조건 분리과세 빼기 → ② 2,000만원은 이자부터 채우기 → ③ 넘는 배당에 Gross-up 10%.","t":"금융소득 종합과세 계산(Gross-up)","k":"이자·배당이 2,000만원을 넘으면 합쳐서 계산해요. 이때 넘는 배당에는 10%를 더해(Gross-up) 회사 단계에서 낸 세금을 맞춰 줘요.","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"상","rev":0,"q":"거주자 기의 2026년 소득이 다음과 같을 때 종합소득금액은?\n· 정기예금 이자 1,200만원\n· 국내 집합투자기구로부터의 이익 1,000만원\n· 직장공제회 초과반환금 1,000만원\n· 근로소득금액 3,000만원\n· 퇴직소득금액 2,000만원","o":["3,000만원","5,200만원","6,200만원","7,200만원"],"a":1,"c":"종합소득에는 분리과세 소득과 분류과세 소득(퇴직·양도)이 들어가지 않아요.","e":"금융소득은 예금이자 1,200만원과 펀드 이익 1,000만원을 합한 2,200만원이라 2천만원을 넘어 종합과세돼요. 펀드 이익은 법인세를 낸 배당이 아니라서 Gross-up을 더하지 않아요. 여기에 근로소득금액 3,000만원을 합한 5,200만원이 종합소득금액이에요.","w":["2천만원을 넘은 금융소득을 분리과세로 잘못 본 값이에요.",null,"무조건 분리과세인 직장공제회 초과반환금까지 넣은 값이에요.","분류과세인 퇴직소득까지 넣은 값이에요."],"m":"종합소득 6가지 \"이·배·사·근·연·기\" — 퇴직·양도는 따로(분류과세).","t":"종합소득의 범위","k":"1년에 번 돈 중 이자·배당·사업·근로·연금·기타 6가지만 합쳐요. 퇴직금과 양도차익은 따로 계산해요.","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":1,"lv":"상","rev":0,"q":"대주주인 거주자 경이 2026년에 상장주식을 다음과 같이 양도하였다. 양도소득 과세표준은?\n· 양도가액 5억원\n· 취득가액 3억 5천만원\n· 양도 시 낸 증권거래세와 수수료 합계 300만원","o":["1억 4,450만원","1억 4,700만원","1억 4,750만원","1억 5,000만원"],"a":0,"c":"주식 양도소득은 '양도가액 − 취득가액 − 필요경비 − 기본공제 250만원' 순서로 계산해요. 주식에는 장기보유특별공제가 없어요.","e":"5억 − 3억 5천만 − 300만 = 1억 4,700만원에서 기본공제 250만원을 빼면 과세표준은 1억 4,450만원이에요.","w":[null,"양도소득 기본공제 250만원을 빼지 않은 값이에요.","거래세·수수료를 필요경비로 빼지 않은 값이에요.","필요경비와 기본공제를 둘 다 빼지 않은 값이에요."],"m":"주식 양도 계산 \"가·취·경·250\" — 주식은 장기보유특별공제 없음.","f":"과세표준 = 양도가액 − 취득가액 − 필요경비 − 기본공제 250만원","t":"주식 양도소득 과세표준 계산","k":"판 가격에서 산 가격, 들어간 비용, 기본공제 250만원을 빼면 세금 매길 금액이 나와요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"t":"ISA의 손익통산","q":"개인종합자산관리계좌(ISA)의 과세 방식에 관한 설명으로 가장 적절한 것은?","o":["모든 이익이 한도 없이 비과세된다","계좌에서 생긴 소득은 무조건 종합과세된다","계좌 안 금융상품의 이익과 손실을 통산한 순이익을 기준으로 과세한다","상품별 이익마다 따로 과세하고 손실은 반영하지 않는다"],"a":2,"c":"ISA는 여러 금융상품을 한 계좌에 담고, 계좌 전체 기준으로 세금을 매겨요.","e":"ISA는 계좌 안의 이익과 손실을 합친 순이익에 대해 비과세 한도를 적용하고, 넘는 부분은 낮은 세율로 분리과세해요.","w":["비과세 한도가 있어요.","분리과세돼요.",null,"손실도 통산해요."],"k":"한 상품에서 잃은 돈을 다른 상품에서 번 돈과 상계해요.","m":"ISA = 손익통산 → 비과세 한도 → 초과분 9.9% 분리과세"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"ISA 의무가입기간","q":"ISA의 세제 혜택을 받기 위한 의무가입기간은?","o":["1년","3년","5년","10년"],"a":1,"c":"ISA는 일정 기간 유지해야 세제 혜택을 받아요.","e":"ISA는 의무가입기간 3년을 채워야 세제 혜택을 받을 수 있어요. 그 전에 해지하면 법정 사유가 아닌 한 감면 세액을 추징해요.","w":["기간이 더 길어요.",null,"5년은 ISA 의무가입기간보다 길어요. 의무가입기간은 3년이에요.","10년은 ISA 의무가입기간보다 훨씬 길어요. 3년만 채우면 돼요."],"k":"최소 3년은 유지해야 해요.","m":"ISA 의무가입기간 = 3년 (중도해지 시 감면세액 추징)","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"ISA 가입 제한","q":"일반 ISA에 가입할 수 없는 사람으로 가장 적절한 것은?","o":["직전 3개 과세기간 중 1회 이상 금융소득종합과세 대상자였던 사람","만 19세 이상 거주자","만 15세 이상 19세 미만이면서 직전 연도에 근로소득이 있었던 거주자","서민형 요건을 충족하는 근로자"],"a":0,"c":"ISA는 일반 국민의 자산 형성을 돕기 위한 계좌라 고액 금융소득자는 가입을 제한해요.","e":"직전 3개 과세기간 중 한 번이라도 금융소득종합과세 대상이었던 사람은 일반 ISA에 가입할 수 없어요.","w":[null,"가입할 수 있어요.","가입할 수 있어요.","서민형으로 가입할 수 있어요."],"k":"금융소득이 2,000만원을 넘었던 고액자산가는 제외돼요.","m":"ISA 가입 제한: 직전 3년 내 금융소득종합과세 대상자"},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"t":"연금계좌 세액공제율","q":"총급여 5,500만원 이하 근로자가 연금계좌(연금저축·IRP)에 납입한 금액에 적용되는 세액공제율(지방소득세 포함)은?","o":["13.2%","16.5%","9.9%","22%"],"a":1,"c":"연금계좌 세액공제율은 소득 수준에 따라 두 가지예요.","e":"총급여 5,500만원(종합소득 4,500만원) 이하이면 16.5%, 그보다 많으면 13.2%의 세액공제율이 적용돼요.","w":["소득이 기준을 넘을 때예요.",null,"9.9%는 ISA 비과세 한도를 넘는 이익에 매기는 분리과세 세율이에요.","22%는 해외주식 양도소득세율(지방소득세 포함)이에요. 연금계좌 세액공제율과 관계없어요."],"k":"소득이 적을수록 더 많이 돌려받아요.","m":"연금계좌 세액공제율: 총급여 5,500만 이하 16.5% · 초과 13.2%","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"연금소득 세율","q":"연금계좌에서 연금으로 받을 때(연금수령) 적용되는 연금소득세율(지방소득세 포함)로 옳은 것은?","o":["70세 미만 5.5%, 70세 이상 80세 미만 4.4%, 80세 이상 3.3%","나이와 관계없이 15.4%","나이와 관계없이 16.5%","70세 미만 3.3%, 80세 이상 5.5%"],"a":0,"c":"연금으로 받으면 나이가 많을수록 낮은 세율이 적용돼요.","e":"연금수령 시 연금소득세율은 70세 미만 5.5%, 70~80세 미만 4.4%, 80세 이상 3.3%예요(종신형 연금 등 일부 예외 있음).","w":[null,"이자·배당 원천징수 세율이에요.","연금외수령 시 기타소득세율이에요.","나이별 세율이 반대예요."],"k":"나이가 들수록 세율이 5.5 → 4.4 → 3.3%로 낮아져요.","m":"연금소득세: 5.5% / 4.4% / 3.3% (나이별)"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"연금외수령 과세","q":"연금계좌에서 세액공제를 받은 납입금과 운용수익을 연금이 아닌 방식으로 인출할 때(연금외수령) 적용되는 과세는?","o":["양도소득세 22%","비과세","연금소득세 5.5%","기타소득세 16.5% 분리과세"],"a":3,"c":"세액공제 혜택을 받은 돈을 연금 목적이 아닌 용도로 찾으면 혜택을 되돌려요.","e":"세액공제 받은 납입금과 운용수익을 연금외수령하면 16.5%(지방소득세 포함)의 기타소득세를 분리과세해요. 부득이한 사유가 있으면 연금소득세율을 적용해요.","w":["양도소득세가 아니에요.","과세돼요.","연금수령 시 세율이에요.",null],"k":"받은 세금 혜택(최대 16.5%)만큼 다시 내는 셈이에요.","m":"연금외수령 = 기타소득세 16.5% 분리과세"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"사적연금 분리과세 기준","q":"연금저축·IRP 등 사적연금의 연간 연금소득(공적연금 제외)이 일정 금액 이하이면 저율 분리과세를 선택할 수 있다. 그 기준 금액은?","o":["연 600만원","연 1,200만원","연 1,500만원","연 2,000만원"],"a":2,"c":"사적연금이 일정 금액 이하이면 종합소득에 합산하지 않고 낮은 세율로 끝낼 수 있어요.","e":"사적연금소득이 연 1,500만원 이하이면 분리과세(3.3~5.5%)를 선택할 수 있어요. 넘으면 종합과세나 16.5% 분리과세 중 선택해요.","w":["예전 기준이에요.","예전 기준이에요.",null,"금융소득종합과세 기준이에요."],"k":"사적연금은 1년에 1,500만원까지 저율 분리과세예요.","m":"사적연금 분리과세 기준 = 연 1,500만원"},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"t":"해외주식 양도소득세","q":"거주자의 해외 상장주식 양도차익 과세에 관한 설명으로 가장 적절한 것은?","o":["연 250만원 기본공제 후 22%(지방소득세 포함)로 과세한다","양도차익 전액이 비과세된다","금융소득종합과세에 합산된다","15.4%로 원천징수하고 끝난다"],"a":0,"c":"해외 주식은 소액주주라도 양도차익에 세금이 붙어요.","e":"해외주식 양도차익은 연 250만원 기본공제 후 양도소득세 20%와 지방소득세 2%를 합한 22%로 과세하고, 다음 해 5월에 확정신고해요.","w":[null,"과세돼요.","양도소득으로 분류과세돼요.","원천징수로 끝나지 않아요. 다음 해 5월에 본인이 직접 양도소득세를 확정신고·납부해야 해요."],"k":"1년 동안 해외주식으로 번 돈에서 250만원을 빼고, 남은 금액에 22%를 내요.","m":"해외주식: 250만 공제 · 22% · 다음 해 5월 확정신고","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"국내·해외 주식 손익통산","q":"같은 과세기간에 해외주식에서 양도차익 1,000만원, 과세 대상 국내 비상장주식(중소기업 외)에서 양도차손 400만원이 생겼다. 양도소득 과세에 관한 설명으로 가장 적절한 것은?","o":["국내·국외 주식의 양도손익을 통산할 수 있어 차익 600만원을 기준으로 과세한다","해외주식과 국내주식은 통산할 수 없어 1,000만원 전액에 과세한다","양도차손이 있으면 모두 비과세된다","국내 주식 손실만 다음 해로 이월한다"],"a":0,"c":"주식 양도소득은 국내·국외 구분 없이 같은 그룹으로 묶어 손익을 계산할 수 있어요.","e":"과세 대상 국내 주식과 국외 주식의 양도손익은 통산할 수 있어요. 1,000 − 400 = 600만원에서 기본공제 250만원을 빼고 과세해요.","w":[null,"통산할 수 있어요.","차익이 남아 과세돼요.","양도차손은 이월공제되지 않아요."],"k":"번 것과 잃은 것을 합쳐서 계산해요.","m":"국내(과세대상)·국외 주식 양도손익 통산 가능 · 결손금 이월 X"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"대주주 상장주식 양도세율","q":"상장주식 대주주(중소기업 외)의 1년 이상 보유 주식 양도소득 과세표준이 5억원일 때 적용되는 세율 구조로 옳은 것은? (지방소득세 제외)","o":["전액 10%","전액 30%","전액 45%","3억원 이하분 20%, 3억원 초과분 25%"],"a":3,"c":"대주주 주식 양도세는 과세표준 3억원을 기준으로 두 단계 세율이에요.","e":"과세표준 3억원 이하는 20%, 3억원 초과분은 25%가 적용돼요. 5억원이면 3억 × 20% + 2억 × 25% = 1.1억원이에요.","w":["중소기업 소액주주 등 다른 세율이에요.","30%는 중소기업 외 대주주가 1년 미만 보유한 주식을 팔 때의 세율이에요. 1년 이상 보유면 20%·25% 두 단계예요.","종합소득 최고세율이에요.",null],"k":"3억까지는 20%, 넘는 부분은 25%예요.","m":"대주주 양도세: 3억 이하 20% · 초과 25% (1년 미만 보유 30%)","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"상속과 증여의 비교","q":"상속세와 증여세를 비교한 설명으로 가장 적절하지 않은 것은?","o":["상속세와 증여세는 같은 세율표를 쓴다","상속세는 피상속인의 유산 전체를 기준으로 과세하는 유산과세형이다","상속세 신고기한은 증여세보다 짧다","증여세는 수증자가 받은 재산을 기준으로 과세한다"],"a":2,"c":"상속세는 \"남긴 사람\" 기준, 증여세는 \"받은 사람\" 기준으로 계산해요.","e":"상속세 신고기한은 상속개시일이 속하는 달의 말일부터 6개월로 증여세(3개월)보다 길어요.","w":["같은 세율표예요.","유산과세형이에요.",null,"취득과세형이에요."],"k":"상속은 정리할 게 많아서 더 오래(6개월) 줘요.","m":"상속세 = 유산과세형 · 6개월 / 증여세 = 취득과세형 · 3개월"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"종합소득세율 구조","q":"종합소득세 기본세율 구조로 옳은 것은? (지방소득세 제외)","o":["6%~45%의 8단계 초과누진세율","10%~50%의 5단계 초과누진세율","단일 비례세율 14%","6%~38%의 5단계 초과누진세율"],"a":0,"c":"종합소득세는 소득이 많을수록 높은 세율이 적용되는 초과누진세율이에요.","e":"종합소득세 기본세율은 6%부터 45%까지 8단계 초과누진세율이에요.","w":[null,"상속·증여세율이에요.","금융소득 원천징수 세율이에요.","예전 세율 구조예요."],"k":"6%에서 시작해 45%까지 여덟 계단이에요.","m":"종합소득세율 = 6~45% 8단계"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"조세조약 제한세율","q":"비거주자가 국내에서 받는 이자·배당소득에 대한 원천징수에 관한 설명으로 가장 적절한 것은?","o":["거주지국과 조세조약이 있으면 조약상 제한세율이 국내 세법 세율보다 우선 적용된다","조세조약이 있어도 국내 세법 세율만 적용한다","비거주자의 국내원천소득은 과세하지 않는다","비거주자는 반드시 종합소득세 확정신고를 해야 한다"],"a":0,"c":"비거주자는 국내에서 생긴 소득(국내원천소득)에 대해서만 과세돼요.","e":"비거주자의 국내원천 이자·배당은 원천징수로 과세하는데, 조세조약이 있으면 조약에서 정한 제한세율이 우선 적용돼요.","w":[null,"조약이 우선해요.","국내원천소득은 과세돼요.","대부분 원천징수로 과세가 끝나요."],"k":"나라 간 약속(조세조약)이 국내 세율보다 먼저예요.","m":"비거주자: 국내원천소득만 과세 · 조세조약 제한세율 우선"},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"t":"원천징수세액 납부기한","q":"원천징수의무자가 원천징수한 소득세를 납부하는 기한으로 원칙적인 것은?","o":["징수일이 속하는 반기의 다음 달 말일까지","징수일이 속하는 달의 다음 달 10일까지","징수일부터 3개월 이내","징수일이 속하는 해의 다음 해 5월 31일까지"],"a":1,"c":"원천징수는 소득을 지급하는 사람이 세금을 미리 떼어 대신 내는 제도예요.","e":"원천징수한 세액은 원칙적으로 징수일이 속하는 달의 다음 달 10일까지 납부해요. 소규모 사업자 등은 승인을 받아 반기별로 낼 수 있어요.","w":["반기별 납부 특례를 받아도 기한은 반기 마지막 달의 다음 달 10일이에요. '다음 달 말일'은 맞지 않아요.",null,"원천징수세액 납부기한은 '징수일부터 3개월'이 아니에요. 원칙은 징수한 달의 다음 달 10일이에요.","종합소득세 확정신고 기한이에요."],"k":"이번 달에 뗀 세금은 다음 달 10일까지 내요.","m":"원천징수 납부 = 다음 달 10일 (반기납부 특례 예외)","f":null},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","t":"증여재산공제 관계별 한도","q":"2026년에 이루어진 다음 증여에서 수증자에게 적용되는 증여재산공제 한도(10년 합산 기준)로 가장 적절하지 않은 것은? (혼인·출산 증여재산공제는 고려하지 않는다)","o":["남편에게서 아파트를 증여받은 아내 — 6억원","할아버지에게서 현금을 증여받은 15세 손자 — 5천만원","아버지에게서 주식을 증여받은 30세 아들 — 5천만원","삼촌에게서 현금을 증여받은 25세 조카 — 1천만원"],"a":1,"c":"증여재산공제는 주는 사람과의 관계에 따라 한도가 달라요. 같은 그룹에서 10년 동안 받은 금액을 합쳐 그 한도 안에서 한 번만 공제해요.","e":"미성년자가 직계존속(할아버지 포함)에게서 받으면 10년간 2천만원까지만 공제돼요. 5천만원은 성년일 때의 한도예요.","w":["배우자에게서 받으면 10년간 6억원을 공제해요.",null,"성년 자녀가 직계존속에게서 받으면 10년간 5천만원이에요.","직계존비속이 아닌 친족에게서 받으면 10년간 1천만원이에요."],"k":"가까운 사이일수록 세금 없이 줄 수 있는 몫이 커요. 배우자 몫이 가장 크고, 아이는 어른보다 작아요.","m":"증여재산공제(10년): 배우자 6억 · 직계존속→성년 5천만/미성년 2천만 · 직계비속 5천만 · 기타친족 1천만","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"경정청구 기한","q":"2024년 귀속 종합소득세를 법정신고기한 안에 신고·납부한 거주자 하준이 2026년에 확인해 보니, 받을 수 있었던 공제를 빠뜨려 세금을 실제보다 많이 냈다. 하준이 밟을 수 있는 절차와 그 기한으로 가장 적절한 것은?","o":["수정신고 — 법정신고기한이 지난 후 3년 이내","경정청구 — 법정신고기한이 지난 후 5년 이내","경정청구 — 법정신고기한이 지난 후 1년 이내","기한후신고 — 납부고지서를 받기 전까지"],"a":1,"c":"신고를 잘못했을 때 세금을 더 내야 하면 수정신고, 돌려받아야 하면 경정청구를 해요.","e":"많이 낸 세금을 줄여 달라고 하는 절차는 경정청구예요. 법정신고기한이 지난 후 5년 이내에 관할 세무서장에게 청구할 수 있어요.","w":["수정신고는 세금을 적게 신고했을 때 늘려 고치는 절차라 이 상황에 맞지 않아요.",null,"경정청구 기한은 1년이 아니라 5년이에요.","기한후신고는 법정신고기한까지 신고하지 않은 사람이 하는 절차예요. 하준은 기한 안에 신고했어요."],"k":"세금을 덜 냈으면 '더 낼게요'(수정신고), 더 냈으면 '돌려주세요'(경정청구)예요. 돌려 달라는 요청은 5년 안에 해야 해요.","m":"덜 냄 → 수정신고 · 더 냄 → 경정청구(법정신고기한 후 5년 이내)","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","t":"출자자의 제2차 납세의무","q":"비상장 법인 ㈜다온이 체납한 법인세를 법인 재산으로 모두 충당하고도 2억원이 모자란다. 그 법인세의 납세의무 성립일 현재 주주가 다음과 같을 때, 제2차 납세의무를 바르게 판단한 것은?\n· 대표이사 갑과 그 배우자: 합계 60% 보유, 경영권을 실제로 행사\n· 을: 25% 보유\n· 병: 15% 보유","o":["갑과 그 배우자는 과점주주로서 부족액 중 자신들이 실질적으로 권리를 행사하는 지분비율만큼을 한도로 제2차 납세의무를 진다","을과 병도 주주이므로 각자의 지분비율에 따라 제2차 납세의무를 진다","주식회사 주주는 유한책임이므로 어떤 주주도 제2차 납세의무를 지지 않는다","제2차 납세의무자는 부족액 2억원 전액을 한도 없이 부담한다"],"a":0,"c":"법인 재산으로 국세를 다 내지 못하면 법인과 가까운 출자자에게 부족분을 물리는데, 이것이 출자자의 제2차 납세의무예요. 대상은 무한책임사원과 과점주주예요.","e":"주주 1명과 특수관계인의 지분 합계가 50%를 넘고 실제로 권리를 행사하면 과점주주예요. 과점주주는 부족액에 자기 지분비율을 곱한 금액까지 책임져요.","w":[null,"지분 합계가 50% 이하인 일반 주주는 제2차 납세의무를 지지 않아요.","주주는 원칙적으로 유한책임이지만 과점주주는 예외로 제2차 납세의무를 져요.","과점주주의 책임은 지분비율만큼으로 한도가 있어요. 한도 없이 부족액 전액을 지는 쪽은 무한책임사원이에요."],"k":"회사가 세금을 못 내면, 회사를 사실상 쥐고 있는 큰 주주가 자기 몫만큼 대신 내요.","m":"출자자 제2차 납세의무 = 무한책임사원(부족액 전액) · 과점주주(50% 초과 + 실질 행사, 지분비율 한도)","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","t":"세목별 부과제척기간 비교","q":"국세기본법상 부과제척기간을 연결한 것으로 가장 적절하지 않은 것은? (역외거래는 없다고 가정한다)","o":["종합소득세 신고서를 법정신고기한까지 내지 않은 경우 — 7년","부정행위로 법인세를 포탈한 경우 — 10년","증여세 신고서를 법정신고기한까지 내지 않은 경우 — 10년","상속세를 법정신고기한까지 정상적으로 신고한 경우 — 10년"],"a":2,"c":"제척기간은 세무서가 세금을 매길 수 있는 기간이에요. 일반 국세는 원칙 5년·무신고 7년·부정행위 10년이고, 역외거래가 끼면 7년·10년·15년으로 늘어나요. 상속세·증여세는 정상 신고 때 10년이고, 신고를 안 하거나 부정행위·허위신고가 있으면 15년이에요.","e":"증여세 신고서를 법정신고기한까지 내지 않으면 제척기간은 15년이에요. 10년은 상속세·증여세를 정상 신고한 경우의 원칙이에요.","w":["일반 국세의 무신고 제척기간은 7년이에요.","일반 국세의 부정행위 제척기간은 10년이에요.",null,"상속세·증여세의 원칙 제척기간은 10년이에요."],"k":"세무서가 세금을 매길 수 있는 유효기간이에요. 신고를 안 하거나 속일수록, 그리고 상속·증여일수록 유효기간이 길어져요.","m":"일반: 5·7·10년(역외 7·10·15년) / 상속·증여: 10·15년 · 부정 포탈 + 재산가액 50억원 초과 등 → 안 날부터 1년","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","t":"양도소득세 과세대상 자산의 범위","q":"거주자 지훈이 2026년에 다음 자산을 넘기고 대가를 받았다. 양도소득세 과세대상이 아닌 것은?","o":["운영하던 공장의 토지·건물과 함께 넘긴 영업권의 대가","보유하던 콘도미니엄 회원권을 팔아 얻은 차익","사업용 토지·건물은 그대로 두고 영업권만 따로 넘기고 받은 대가","등기된 상가 임차권을 다른 사람에게 넘기고 받은 대가"],"a":2,"c":"양도소득세는 법에 열거된 자산만 과세해요. 토지·건물 말고도 부동산에 관한 권리와 '기타자산'이 들어가요.","e":"영업권은 사업용 고정자산(토지·건물 등)과 함께 넘길 때만 양도소득이에요. 영업권만 따로 넘기면 양도소득이 아니라 기타소득으로 과세돼요.","w":["사업용 고정자산과 함께 넘긴 영업권은 기타자산이라 양도소득이에요.","골프·콘도 회원권은 특정시설물이용권이라 '기타자산'에 들어가 과세돼요.",null,"등기된 부동산임차권은 '부동산에 관한 권리'라 양도소득세 과세대상이에요."],"k":"영업권은 가게 건물과 같이 팔면 양도소득, 간판(영업권)만 떼어 팔면 기타소득이에요.","m":"양도 과세: 토지·건물 · 부동산 권리(지상권·전세권·등기 임차권·분양권) · 기타자산(회원권·사업용 자산과 함께 넘긴 영업권) · 주식","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","t":"시장별 증권거래세 계산","q":"거주자 서윤이 2026년에 다음 주권을 양도하였다. 서윤이 부담하는 증권거래세 합계는? (농어촌특별세와 수수료는 고려하지 않는다)\n· 코스닥시장 상장주권 2,500만원\n· 코넥스시장 상장주권 1,000만원\n· 금융투자협회 장외시장(K-OTC)을 통한 비상장주권 500만원","o":["5만 5천원","7만원","7만 7,500원","8만원"],"a":1,"c":"2026년 증권거래세율은 유가증권시장 0.05%(농어촌특별세 0.15% 별도), 코스닥 0.20%, 코넥스 0.10%, K-OTC 0.20%, 그 밖의 장외 양도 0.35%예요. 이익이 아니라 양도가액에 매기므로 손해를 보고 팔아도 내요.","e":"코스닥 5만원, 코넥스 1만원, K-OTC 1만원을 더하면 7만원이에요. 코스닥·코넥스·K-OTC 양도분에는 농어촌특별세가 붙지 않아요.","w":["2025년 세율(코스닥·K-OTC 0.15%)로 계산한 값이에요.",null,"K-OTC 거래를 일반 장외 양도 세율 0.35%로 계산한 값이에요.","코넥스까지 모두 0.20%로 계산한 값이에요."],"k":"같은 주식이라도 어느 시장에서 파느냐에 따라 떼는 비율이 달라요. 코넥스가 가장 낮고, 협회 장외시장을 거치지 않은 장외 거래가 가장 높아요.","m":"2026 거래세: 코스피 0.05% + 농특세 0.15% · 코스닥 0.20% · 코넥스 0.10% · K-OTC 0.20% · 그 밖의 장외 0.35%","f":"2,500만 × 0.20% + 1,000만 × 0.10% + 500만 × 0.20% = 5만 + 1만 + 1만 = 7만원","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"증권거래세 과세 제외와 비과세","q":"다음 주권 이전 가운데 증권거래세가 과세되는 것은?","o":["뉴욕증권거래소에 상장된 주권을 그 거래소에서 매도한 경우","부모가 보유하던 비상장주권을 자녀에게 무상으로 증여한 경우","국민연금공단이 기금으로 보유하던 상장주권을 장내에서 매도한 경우","증권회사가 주권을 빌려주고 나중에 같은 종목·수량으로 돌려받기로 한 대차거래"],"a":2,"c":"증권거래세는 주권을 대가를 받고 넘길 때 매겨요. 무상 이전, 해외 거래소 상장주권의 양도, 주권 대차, 국가·지방자치단체의 양도, 자본시장법에 따른 매출 등은 과세하지 않아요.","e":"국가·지방자치단체의 양도는 비과세지만, 중앙행정기관의 장이 관리하는 법정 기금(국민연금기금 등)에서 취득한 주권을 양도하는 경우는 이 비과세에서 빠져요. 그래서 국민연금기금의 장내 매도에는 증권거래세가 붙어요.","w":["해외 거래소에 상장된 주권을 그 거래소에서 판 경우는 비과세예요.","대가 없이 넘기는 증여는 유상 양도가 아니라서 과세대상이 아니에요.",null,"주권 소비대차는 잠시 넘겼다 돌려받는 거래라 비과세예요."],"k":"증권거래세는 '팔고 돈을 받을 때' 내는 세금이에요. 공짜로 주거나 잠깐 빌려주는 건 해당이 없어요.","m":"거래세 X: 증여·상속(무상) · 해외 상장주권 · 주권 대차 · 국가·지자체(중앙행정기관 관리 기금·우정사업 제외) · 자본시장법상 매출","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"납세의무의 자동확정","q":"별도의 신고나 정부의 결정 없이 납세의무가 성립하는 때에 세액이 확정되는 국세를 〈보기〉에서 모두 고른 것은?\n〈보기〉\nㄱ. 인지세\nㄴ. 원천징수하는 소득세\nㄷ. 증여세\nㄹ. 중간예납하는 법인세\nㅁ. 부가가치세","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㅁ","ㄱ, ㄷ, ㄹ, ㅁ"],"a":1,"c":"국세의 확정 방식은 신고로 확정되는 신고납세, 정부 결정으로 확정되는 정부부과, 성립과 동시에 확정되는 자동확정의 세 가지예요.","e":"원천징수로 떼는 소득세·법인세, 인지세, 중간예납 법인세는 성립과 함께 별도 절차 없이 확정돼요. 그래서 ㄱ·ㄴ·ㄹ이 맞아요.","w":["중간예납하는 법인세(ㄹ)도 자동확정인데 빠뜨렸어요.",null,"증여세는 정부가 결정해야 확정되는 정부부과 세목이고, 부가가치세는 신고로 확정되는 신고납세 세목이에요.","증여세는 정부부과, 부가가치세는 신고납세 세목이에요."],"k":"어떤 세금은 계약서를 쓰거나 돈을 주는 순간 금액이 바로 정해져요. 신고서도 정부 통지도 필요 없어요.","m":"자동확정: 인지세 · 원천징수 소득·법인세 · 중간예납 법인세 · 납부지연가산세 / 정부부과: 상속·증여세 · 종부세(원칙) / 신고납세: 소득·법인·부가세","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"금융소득의 구분과 필요경비","q":"소득세법상 금융소득을 바르게 설명한 것은?","o":["동업에 자금만 대고 경영은 맡지 않는 출자공동사업자의 손익분배금은 배당소득에 속한다","배당소득은 그 소득을 얻기 위해 쓴 차입이자 등을 필요경비로 빼고 계산한다","연금계좌에서 받는 연금도 금융소득에 포함해 2천만원 초과 여부를 판단한다","이자소득은 법에 열거된 것만 과세하므로 열거되지 않은 비슷한 성격의 이익은 과세되지 않는다"],"a":0,"c":"금융소득은 이자소득과 배당소득을 말해요. 둘 다 필요경비를 인정하지 않아 수입금액 전체가 소득금액이 돼요.","e":"경영은 하지 않고 자금만 댄 동업자(출자공동사업자)가 받는 분배금은 사업소득이 아니라 배당소득이에요.","w":[null,"이자·배당소득에는 필요경비가 인정되지 않아요.","연금소득은 금융소득이 아니에요. 금융소득은 이자와 배당뿐이에요.","이자·배당소득은 열거된 것과 성격이 비슷한 소득도 과세하는 유형별 포괄주의를 적용해요."],"k":"돈만 넣고 일은 안 한 동업자의 몫은 '배당'처럼 봐요. 그리고 이자·배당은 비용을 빼 주지 않아요.","m":"금융소득 = 이자 + 배당 · 필요경비 X · 유형별 포괄주의 · 출자공동사업자 손익분배금 = 배당소득","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"국세기본법상 기한 특례와 제척기간","q":"국세기본법상 기한과 제척기간을 설명한 〈보기〉에서 맞는 것만 묶은 것은?\nㄱ. 종합소득세 확정신고기한의 마지막 날이 일요일이면 그다음 날까지 신고해도 기한 안에 신고한 것이 된다.\nㄴ. 납부기한 만료일에 국세정보통신망이 장애로 멈춰 전자납부를 못 했다면, 장애가 복구된 바로 그날이 새 기한이 된다.\nㄷ. 경정청구서를 우편으로 보냈다면 우편날짜도장이 찍힌 날에 청구한 것으로 본다.\nㄹ. 세무서가 체납자의 재산을 압류하면 국세부과 제척기간도 그때부터 새로 진행한다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"기한의 마지막 날이 토요일·일요일·공휴일·노동절이면 그다음 날이 기한이에요. 우편으로 낸 신고서·청구서는 우편날짜도장이 찍힌 날에 낸 것으로 봐요. 제척기간은 소멸시효와 달리 중단·정지 제도가 없어요.","e":"ㄱ은 휴일이면 다음 날로 미뤄지는 기한 특례이고, ㄷ은 우편 발신주의예요. 그래서 ㄱ·ㄷ이 옳아요.","w":["ㄴ은 틀렸어요. 국세정보통신망 장애 때는 복구되어 신고·납부할 수 있게 된 날의 다음 날이 기한이에요.",null,"ㄴ은 '복구된 날의 다음 날'이 기한이라 틀렸고, ㄹ도 틀렸어요.","ㄹ은 틀렸어요. 압류는 징수권 소멸시효의 중단사유일 뿐이고, 제척기간에는 중단·정지가 없어요."],"k":"마감일이 쉬는 날이면 다음 날까지 봐주고, 우체국 도장이 찍힌 날을 낸 날로 쳐 줘요. 하지만 제척기간이라는 시계는 한번 돌기 시작하면 멈추지 않아요.","m":"휴일 → 다음 날 · 전산 장애 → 복구 다음 날 · 우편 = 도장 찍힌 날 · 제척기간은 중단·정지 X","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","t":"거주자 판정 특례와 비거주자 원천징수세율","q":"2026년 소득세 과세에 관한 〈보기〉의 판단 중 옳은 것만 고른 것은? (조세조약은 없다고 가정한다)\nㄱ. 외교부 소속으로 주프랑스 대사관에서 근무하는 공무원 갑은 국내에 주소가 없어도 거주자로 본다.\nㄴ. 내국법인이 지분 60%를 가진 베트남 현지법인에 파견된 직원 을은 파견 특례에 따라 당연히 거주자로 본다.\nㄷ. 국내사업장이 없는 비거주자 병이 내국법인이 발행한 회사채의 이자를 받으면 14%로 원천징수된다.\nㄹ. 국내사업장이 없는 비거주자 정이 국내 은행 정기예금 이자를 받으면 14%로 원천징수된 뒤 다음 해 종합소득세로 정산한다.","o":["ㄱ, ㄷ","ㄱ, ㄴ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":0,"c":"국외에서 근무하는 공무원과, 내국법인이 지분 전부(100%)를 출자한 해외현지법인에 파견된 임직원은 국내 주소가 없어도 거주자로 봐요. 국내사업장이 없는 비거주자의 이자·배당은 원천징수로 과세가 끝나요(분리과세). 세율은 이자·배당 모두 20%가 원칙이고, 국가나 지자체, 내국법인 등이 찍은 채권에서 나온 이자만 14%예요.","e":"ㄱ은 국외 근무 공무원 특례, ㄷ은 채권이자 14% 규정이라 옳아요.","w":[null,"ㄴ은 틀렸어요. 해외현지법인 파견 특례는 내국법인이 그 법인에 100% 출자한 경우에만 적용돼요.","ㄴ·ㄹ 모두 틀렸어요.","ㄹ은 틀렸어요. 예금이자는 채권이자가 아니라서 20%로 원천징수하고, 국내사업장이 없으면 그것으로 과세가 끝나요."],"k":"나랏일로 외국에 나간 공무원, 본사가 100% 소유한 해외 법인에 나간 직원은 '잠깐 외출 중인 우리 식구'로 봐요.","m":"거주자 특례: 국외 근무 공무원 · 100% 출자 해외법인 파견 / 비거주자 이자·배당 20%(채권이자 14%) · 국내사업장 없으면 분리과세","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"상","t":"증권거래세 납세의무자와 거래징수","q":"증권거래세와 소득세의 징수 구조를 설명한 〈보기〉에서 맞는 것을 빠짐없이 고르면?\nㄱ. 국내사업장이 없는 외국법인이 증권회사를 거치지 않고 비상장주권을 거주자에게 직접 넘기면, 주권을 산 거주자가 증권거래세를 신고·납부한다.\nㄴ. 증권회사가 주권을 판 고객에게서 증권거래세를 떼어 내는 것은 소득을 지급하면서 세금을 떼는 원천징수에 해당한다.\nㄷ. 거주자의 소득세 납세지는 원칙적으로 그 사람의 주소지이다.\nㄹ. 증권시장에서 양도되어 계좌 간 대체로 결제되는 주권은 예탁결제원(또는 전자등록기관)이 거래세를 낼 의무를 진다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2,"c":"증권거래세 납세의무자는 거래 경로마다 달라요. 장내 결제분은 예탁결제원(전자등록기관), 금융투자업자를 거친 장외 양도는 그 금융투자업자, 그 밖에는 양도자가 내요. 다만 국내사업장이 없는 비거주자·외국법인이 직접 넘기면 양수인이 내요. 증권거래세는 세금을 내는 사람과 실제로 떠안는 사람이 다른 간접세이고, 시장별 세율은 시행령으로 정해요.","e":"ㄱ은 양수인 납세의무, ㄷ은 소득세 납세지, ㄹ은 장내 결제분의 납세의무자를 바르게 설명했어요.","w":["ㄴ은 틀렸어요. 거래 상대방에게서 세금을 받아 내는 것은 거래징수예요. 원천징수는 소득을 주는 쪽이 그 소득에 대한 세금을 미리 떼는 제도라 서로 달라요.","ㄴ은 거래징수라서 틀렸어요. ㄱ·ㄹ도 옳은 설명이에요.",null,"ㄴ이 틀렸어요. 증권회사가 매도자에게서 세금을 받는 것은 원천징수가 아니라 거래징수예요."],"k":"외국 회사가 중개인 없이 주식을 팔고 떠나 버리면 세금을 받을 길이 막막하니, 국내에 남아 있는 산 사람에게 세금을 맡겨요.","m":"거래세 납세의무자: 장내 결제 = 예탁결제원 · 금융투자업자 경유 = 그 업자 · 그 밖 = 양도자(국내사업장 없는 외국인 직접 양도 → 양수인) · 증권사 징수 = 거래징수 · 소득세 납세지 = 주소지","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","t":"이자·배당소득 수입시기 판단","q":"거주자 서진이 2026년에 받은 다음 소득의 수입시기를 판단한 것 중 옳은 것은?","o":["회사가 잉여금을 자본에 넣으면서 준 무상주(의제배당) — 무상주가 계좌에 들어온 날","통지예금의 이자 — 예금을 인출한 날","기명식 회사채의 이자 — 이자가 실제로 계좌에 입금된 날","주주총회에서 잉여금 처분을 결의해 받은 현금배당 — 배당금이 실제로 들어온 날"],"a":1,"c":"수입시기는 그 소득을 어느 해 소득으로 볼지 정하는 날이에요. 무기명채권 이자는 실제로 받은 날, 기명채권 이자는 약정에 따른 지급일, 잉여금 처분 배당은 처분 결의일, 잉여금 자본전입 의제배당은 자본전입 결의일, 해산으로 생긴 의제배당은 남은 재산 가액이 정해진 날이에요.","e":"통지예금은 미리 알리고 찾는 예금이라, 이자는 실제로 인출한 날이 수입시기예요.","w":["잉여금을 자본금으로 돌려 생긴 의제배당은 무상주를 받은 날이 아니라 자본전입을 결의한 날이 수입시기예요.",null,"기명채권 이자는 실제 입금일이 아니라 약정에 따른 지급일이 수입시기예요. 실제로 받은 날을 기준으로 하는 것은 무기명채권이에요.","잉여금 처분에 따른 배당은 입금일이 아니라 잉여금 처분을 결의한 날이 수입시기예요."],"k":"언제 내 소득이 되느냐는 '돈 들어온 날'이 아니라 '받을 권리가 확정된 날'이 원칙이에요. 통지예금과 무기명채권처럼 실제로 찾거나 받아야 확정되는 것만 예외예요.","m":"무기명 = 받은 날 · 기명 = 약정일 · 통지예금 = 인출일 · 처분배당 = 결의일 · 자본전입 의제배당 = 결의일 · 해산 의제배당 = 잔여재산 확정일","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"증여세 분산 증여와 차명예금","q":"자녀에게 재산을 넘기려는 거주자 부모에게 한 조언 가운데 틀린 것은?","o":["아버지와 큰아버지가 나누어 증여하면 증여자별로 따로 세율을 적용하므로, 한 사람이 몰아서 줄 때보다 누진세율 부담이 줄 수 있다","증여재산공제 범위 안이라 낼 세금이 없더라도 신고해 두면 나중에 자녀의 자금출처를 설명하는 근거가 된다","보유 주식의 시가가 일시적으로 크게 떨어졌을 때 증여하면 증여세 과세가액을 줄일 수 있다","자녀 이름으로 예금을 만들어 부모 돈을 넣어 두기만 하면 그 계좌의 이자에만 세금이 붙고 증여세 문제는 생기지 않는다"],"a":3,"c":"증여세는 받는 사람이 증여자별로 계산해요(직계존속은 그 배우자와 합산해요). 증여재산공제는 10년 동안 받은 것을 묶어 한도를 적용하고, 과세가액은 증여 시점의 시가로 정해요.","e":"자녀 명의 계좌에 넣은 돈은 자녀가 증여받은 재산으로 추정돼요. 그래서 이자에 붙는 세금과는 별개로 증여세가 과세될 수 있어요. 이름만 빌린 계좌라는 사실을 납세자가 직접 증명해야 이 추정에서 벗어날 수 있어요.","w":["증여세는 증여자마다 따로 계산해서 여러 사람이 나누어 주면 누진 부담이 줄어요. 다만 아버지와 어머니처럼 직계존속 부부는 한 사람으로 보고 합산해요.","공제 범위 안이라도 신고해 두면 정당하게 받은 돈이라는 증거가 남아요.","증여 시점의 시가로 과세하므로 값이 일시적으로 떨어졌을 때가 유리하고, 그 뒤 회복분은 세금 없이 자녀 몫이 돼요.",null],"k":"아이 이름표만 붙인 저금통에 부모 돈을 넣어도, 세무서는 그 돈이 이미 아이에게 넘어간 것으로 볼 수 있어요.","m":"증여자별 과세(직계존속 부부는 합산) · 공제 범위라도 신고 · 값 떨어졌을 때 증여 · 차명예금 → 증여세 가능 · 공제는 10년 단위","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"펀드 이익과 신탁 이익의 과세","q":"소득세법상 펀드와 신탁에서 생긴 이익에 세금을 매기는 방식을 바르게 설명한 것은?","o":["채권만 담은 펀드에서 받은 이익은 이자소득으로 과세된다","적격 펀드가 담고 있던 비상장주식을 처분해 남긴 차익은 과세 대상 이익에서 빠진다","집합투자증권을 환매하지 않고 다른 투자자에게 팔아 얻은 이익은 과세되지 않는다","집합투자기구가 아닌 특정금전신탁의 이익은 신탁재산에서 생긴 소득의 내용(이자·배당 등)에 따라 나누어 과세된다"],"a":3,"c":"펀드(적격 집합투자기구) 이익은 담은 자산과 관계없이 배당소득이에요. 다만 상장주식 등의 매매·평가손익은 빼고 계산해요. 펀드가 아닌 신탁은 소득이 생긴 원천별로 과세해요.","e":"특정금전신탁처럼 펀드가 아닌 신탁은 신탁을 소득이 지나가는 통로로 보고, 이자는 이자소득, 배당은 배당소득처럼 원천에 따라 과세해요.","w":["채권형이든 주식형이든 펀드 이익은 배당소득이에요.","과세에서 빠지는 것은 상장주식·벤처기업 주식 등의 매매·평가손익이에요. 일반 비상장주식의 매매차익은 과세 대상 이익에 들어가요.","펀드 지분을 남에게 팔아 남긴 이익도 펀드 이익으로 보고 과세해요.",null],"k":"펀드는 '배당 주머니' 하나로 묶어 과세하지만, 일반 신탁은 투명한 유리관이라 안에서 생긴 소득 종류가 그대로 보여요.","m":"펀드 이익 = 배당소득(상장주식·벤처기업 주식 등의 매매·평가손익 제외, 일반 비상장주식은 포함) · 신탁 이익 = 원천별 과세","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","t":"분리과세와 분류과세의 구분","q":"소득세를 매기는 방식에 대한 설명 중 맞는 것은?","o":["분류과세는 소득을 줄 때 세금을 떼는 것으로 과세가 끝나 따로 신고하지 않는 방식이다","퇴직소득과 양도소득은 오랜 기간 쌓인 소득이 한 해에 몰려 높은 세율을 맞는 것을 막으려고 종합소득과 따로 과세한다","사업소득과 근로소득은 분류과세 대상이라 종합소득에 합산하지 않는다","분리과세 대상 금융소득도 다음 해 5월 종합소득세 신고 때 다시 합산해 정산한다"],"a":1,"c":"종합소득 여섯 가지(이자, 배당, 사업, 근로, 연금, 기타)는 합쳐서 누진세율로 과세해요. 분리과세는 종합소득 가운데 일부를 떼어 원천징수로 끝내는 방식이고, 분류과세는 퇴직소득·양도소득을 종합소득과 따로 계산하는 방식이에요.","e":"퇴직·양도소득은 여러 해 동안 쌓인 소득이 한꺼번에 실현돼요. 종합소득에 더하면 누진세율이 지나치게 적용되는 결집효과가 생겨서 따로 과세해요.","w":["원천징수로 끝나는 것은 분리과세예요. 분류과세는 퇴직·양도소득을 따로 과세하는 방식이에요.",null,"사업소득과 근로소득은 종합소득이에요. 분류과세 대상은 퇴직소득과 양도소득이에요.","분리과세 대상 소득은 원천징수로 과세가 끝나서 종합소득에 다시 합산하지 않아요."],"k":"분리과세는 '계산대에서 바로 결제하고 끝', 분류과세는 '장바구니를 아예 따로 계산'하는 거예요.","m":"분리과세 = 원천징수로 종결 · 분류과세 = 퇴직·양도 따로(결집효과 완화) · 종합 = 이·배·사·근·연·기","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"하","t":"국세·지방세와 간접세 구분","q":"제조업체 ㈜한빛이 2026년에 낸 세금이 다음과 같다. 이 가운데 지방세만 고른 것은?\nㄱ. 새로 산 공장 부지를 취득하면서 낸 취득세\nㄴ. 투자용 비상장주권 처분분에 대해 낸 증권거래세\nㄷ. 공장이 있는 지방자치단체에 종업원 급여총액을 기준으로 낸 주민세(종업원분)\nㄹ. 물건을 팔면서 고객에게 받아 낸 부가가치세","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"국가가 걷으면 국세, 지방자치단체가 걷으면 지방세예요. 취득세·등록면허세·재산세·주민세·지방소득세는 지방세이고, 소득세, 법인세, 상속세, 증여세, 종합부동산세, 부가가치세, 증권거래세는 국세예요. 또 부담이 남에게 넘어가도록 설계된 세금은 간접세, 법인세·소득세·상속세처럼 납세의무자가 직접 부담하는 세금은 직접세예요.","e":"취득세와 주민세(종업원분)는 지방자치단체가 부과하는 지방세예요.","w":["증권거래세는 국세예요.",null,"증권거래세와 부가가치세는 모두 국세예요. 둘 다 세금을 내는 사람과 실제로 떠안는 사람이 다른 간접세예요.","부가가치세는 국세예요. 사업자가 내지만 실제 부담은 물건값에 포함되어 소비자에게 넘어가는 간접세예요."],"k":"고지서를 보낸 곳이 시청·구청이면 지방세, 세무서면 국세라고 생각하면 쉬워요.","m":"지방세 \"취·등·재·주·지\" — 취득세·등록면허세·재산세·주민세·지방소득세 / 간접세 = 부가가치세·증권거래세·개별소비세·주세","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"하","rev":0,"t":"ELD·ELS·ELF·ELB 비교","q":"주가지수 등에 수익률이 연계되는 상품 가운데 예금자보호법에 따라 보호받을 수 있는 것으로 가장 적절한 것은?","o":["ELS(주가연계증권)","ELD(주가연계예금)","ELF(주가연계펀드)","ELW(주식워런트증권)"],"a":1,"c":"이름이 비슷해도 누가 발행하고 어떤 형태인지에 따라 예금자보호 여부가 갈려요. D는 Deposit(예금), S는 Securities(증권), F는 Fund(펀드)예요.","e":"ELD는 은행이 판매하는 정기예금 형태라 예금자보호 대상이에요. ELS·ELW는 증권사가 발행하는 증권, ELF는 펀드라 보호 대상이 아니에요.","w":["ELS는 증권사가 발행하는 파생결합증권이라 보호 대상이 아니에요.",null,"ELF는 집합투자기구(펀드)라 보호 대상이 아니에요.","ELW는 증권이라 보호 대상이 아니에요."],"k":"이름 끝 글자만 보세요. D(예금)만 보호돼요.","m":"ELD(예금) = 예금자보호 O · ELS·ELF·ELW = X"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"자산유동화증권(ABS)의 신용보강","q":"자산유동화증권(ABS)의 신용보강 방법 가운데 외부 신용보강에 해당하는 것은?","o":["은행의 지급보증","선·후순위 구조로 발행","기초자산 초과 담보","현금 유보(Cash reserve) 적립"],"a":0,"c":"ABS의 신용보강은 기초자산 구조 안에서 해결하는 내부 신용보강과, 제3자의 힘을 빌리는 외부 신용보강으로 나뉘어요.","e":"은행의 지급보증, 신용공여(대출 약정), 보증보험처럼 제3자가 지원하는 것이 외부 신용보강이에요.","w":[null,"후순위 구조는 내부 신용보강이에요.","초과담보는 내부 신용보강이에요.","현금 유보도 내부 신용보강이에요."],"k":"내 힘으로(후순위·초과담보·적립금) 보강하면 내부, 남(은행 보증)의 힘을 빌리면 외부예요.","m":"내부: 후순위·초과담보·현금유보 / 외부: 지급보증·신용공여·보증보험"},{"s":1,"sec":"금융상품","star":2,"lv":"하","rev":0,"t":"랩어카운트","q":"랩어카운트(Wrap Account)에 관한 설명으로 가장 적절하지 않은 것은?","o":["증권사가 고객 자산을 하나의 계좌로 묶어 운용·자문 서비스를 제공한다","일임형은 증권사가 고객의 위임을 받아 직접 운용한다","수수료는 보통 계좌 잔고(자산 규모)에 따라 일괄 부과한다","매매할 때마다 수수료가 붙으므로 증권사가 매매를 늘릴 유인이 커진다"],"a":3,"c":"랩어카운트는 자산관리 서비스를 \"포장(wrap)\"해서 하나의 수수료로 받는 계좌예요.","e":"수수료를 잔고 기준으로 일괄 받으므로 매매 횟수를 늘려도 수수료가 늘지 않아요. 그래서 과당매매 유인이 오히려 작아요.","w":["자산을 한 계좌로 묶어 관리해요.","일임형은 증권사가 직접 운용해요.","잔고 기준 일괄 수수료가 특징이에요.",null],"k":"뷔페처럼 정해진 값만 내면 돼서, 접시(매매)를 몇 번 갖다 먹어도 값이 같아요.","m":"랩: 잔고 기준 일괄 수수료 · 일임형/자문형 · 과당매매 유인 작음"},{"s":1,"sec":"금융상품","star":3,"lv":"하","rev":0,"t":"환매조건부채권(RP)","q":"증권회사가 판매하는 환매조건부채권(RP)에 관한 설명으로 가장 적절하지 않은 것은?","o":["일정 기간 뒤 정해진 가격에 다시 사는 조건으로 채권을 사고파는 거래이다","국공채 등 신용도가 높은 채권을 주로 대상으로 한다","단기 자금을 운용하는 수단으로 많이 쓰인다","증권회사 RP도 은행 예금처럼 예금자보호법에 따라 보호된다"],"a":3,"c":"RP는 채권을 담보로 짧게 돈을 빌리고 빌려주는 거래예요. 투자자 입장에서는 짧게 이자를 받는 상품이에요.","e":"증권회사가 판매하는 RP는 예금자보호 대상이 아니에요.","w":["정해진 가격에 되사는 조건이 RP의 핵심이에요.","국공채 등 우량 채권이 주로 담보가 돼요.","단기 자금 운용 수단이에요.",null],"k":"채권을 맡기고 잠깐 돈을 빌리는 \"전당포\" 같은 구조예요. 예금이 아니라서 예금자보호는 안 돼요.","m":"RP: 되사기 조건 · 우량채 담보 · 증권사 RP 예금자보호 X"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"모자형 집합투자기구","q":"모자형 집합투자기구에 관한 설명으로 가장 적절하지 않은 것은?","o":["여러 자 집합투자기구의 자금을 모아 모 집합투자기구에서 한꺼번에 운용해 효율을 높인다","모 집합투자기구와 자 집합투자기구의 집합투자업자는 같아야 한다","자(子) 집합투자기구는 모(母) 집합투자기구의 집합투자증권을 취득하는 구조이다","자 집합투자기구는 다른 운용사가 운용하는 모 집합투자기구에도 자유롭게 투자할 수 있다"],"a":3,"c":"모자형은 판매는 여러 자펀드로, 운용은 하나의 모펀드로 하는 구조예요. 운용 효율을 높이기 위해 만들어요.","e":"모자형에서 자 집합투자기구는 같은 집합투자업자가 운용하는 모 집합투자기구에만 투자할 수 있어요.","w":["자금을 모아 운용 효율을 높여요.","모·자의 집합투자업자는 같아야 해요.","자펀드가 모펀드 증권을 사는 구조예요.",null],"k":"본점(모)과 지점(자)처럼 같은 회사 안에서만 연결돼요. 다른 회사 본점에 연결할 수는 없어요.","m":"모자형: 같은 운용사 · 자 → 모만 투자 · 운용 효율"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"예금자보호 대상","q":"예금자보호법상 보호 대상 금융상품에 해당하는 것은?","o":["증권회사 고객 계좌의 현금 투자자예탁금","주가연계증권(ELS)","환매조건부채권(RP)","양도성예금증서(CD)"],"a":0,"c":"예금자보호는 원금 손실 가능성이 없는 예금성 상품을 중심으로 적용돼요. 투자상품은 보호하지 않아요.","e":"증권사에 맡긴 현금 투자자예탁금은 보호 대상이에요. ELS·RP·CD는 보호 대상이 아니에요.","w":[null,"투자상품이라 보호되지 않아요.","보호되지 않아요.","보호되지 않아요."],"k":"증권 계좌 안에 \"현금으로\" 남아 있는 돈만 보호돼요.","m":"보호 O: 예금·적금·투자자예탁금(현금)·외화예금·표지어음 / X: ELS·RP·CD·펀드·발행어음"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"예금자보호 비대상 상품","q":"예금자보호 대상이 아닌 것은?","o":["은행의 외화예금","은행이 발행한 표지어음","주택청약종합저축","보험회사의 개인 연금보험"],"a":2,"c":"같은 은행 상품이라도 성격에 따라 보호 여부가 달라요.","e":"주택청약종합저축은 주택도시기금의 재원으로 정부가 관리해서 예금자보호 대상이 아니에요. 외화예금·표지어음·개인 연금보험은 보호 대상이에요.","w":["외화예금도 보호돼요.","표지어음은 보호돼요.",null,"개인이 가입한 보험 계약은 보호돼요."],"k":"청약저축은 정부가 따로 관리해서 예금보험 대상이 아니에요.","m":"주택청약종합저축 = 예금자보호 X (정부 관리)","f":null},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"예금자보호 한도 산정","q":"예금자보호 한도 산정 방식으로 가장 적절한 것은?","o":["예금자 1인당 금융회사별로 원금과 소정의 이자를 합산해 한도까지 보호한다","예금 계좌별로 각각 한도까지 보호한다","같은 금융그룹 계열사를 모두 합산해 한도 하나만 보호한다","원금만 보호하고 이자는 보호하지 않는다"],"a":0,"c":"예금자보호 한도는 사람·금융회사 단위로 계산해요. (2025년 9월부터 1억원)","e":"예금자 1인당, 금융회사별로, 원금과 소정의 이자를 합해 한도까지 보호해요. 같은 은행에 계좌가 여러 개면 합산해요.","w":[null,"계좌별이 아니라 금융회사별로 합산해요.","금융회사별로 각각 적용해요.","소정의 이자도 포함해요."],"k":"A은행 계좌 3개는 합쳐서, A은행과 B은행은 따로 계산해요.","m":"1인 · 금융회사별 · 원금 + 소정이자 합산"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"DC형 위험자산 한도","q":"DC형·개인형 퇴직연금(IRP)에서 주식형 펀드 등 위험자산에 투자할 수 있는 한도는 적립금의 몇 %인가?","o":["30%","50%","70%","100%"],"a":2,"c":"퇴직연금은 노후 자금이라 위험자산 투자에 한도를 두고 있어요.","e":"DC형과 IRP는 위험자산에 적립금의 70%까지 투자할 수 있어요. 나머지 30% 이상은 원리금보장상품이나 안전자산(TDF 등 적격 상품 포함)에 둬야 해요.","w":["한도가 더 높아요.","한도가 더 높아요.",null,"한도가 있어요."],"k":"노후 자금이라 적어도 30%는 안전하게 둬요.","m":"DC·IRP 위험자산 한도 = 70%"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"연금저축의 종류","q":"연금저축 상품 중 원금 손실 가능성이 있고 예금자보호 대상도 아닌 실적배당형 상품은?","o":["연금보험(생명보험사 공시이율형)","연금저축신탁(기존 가입분)","연금저축펀드","연금저축보험"],"a":2,"c":"연금저축은 운용 금융회사에 따라 펀드, 보험, 신탁으로 나뉘어요.","e":"연금저축펀드는 집합투자증권에 투자하는 실적배당형으로 예금자보호 대상이 아니에요. 연금저축보험·신탁은 보호 대상이에요.","w":["보험이라 보호돼요.","신탁은 보호돼요.",null,"보험이라 보호돼요."],"k":"펀드는 투자상품이라 보호가 없어요.","m":"연금저축펀드 = 실적배당·비보호 / 보험·신탁 = 보호","f":null},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"주택연금 가입 요건","q":"주택연금(한국주택금융공사)에 관한 설명으로 가장 적절하지 않은 것은?","o":["부부 중 1명이 만 55세 이상이면 가입할 수 있다","공시가격 12억원 이하 주택이 대상이다","가입자와 배우자 모두 평생 거주하며 연금을 받을 수 있다","주택 처분 금액이 연금 지급 총액보다 적으면 부족분을 자녀에게 청구한다"],"a":3,"c":"주택연금은 집을 담보로 맡기고 평생 연금을 받는 역모기지 상품이에요.","e":"주택연금은 비소구 방식이라 집값이 연금 총액보다 적어도 부족분을 상속인에게 청구하지 않아요. 남으면 상속인에게 돌려줘요.","w":["가입 연령이에요.","주택 가격 기준이에요.","부부 모두 종신 지급이에요.",null],"k":"집값보다 많이 받아도 자녀가 갚을 필요가 없어요.","m":"주택연금: 55세 이상 · 공시가 12억 이하 · 종신 · 비소구"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"주택연금의 지급 방식","q":"주택연금에서 매월 같은 금액을 평생 받는 대신, 필요한 목돈을 일정 한도 내에서 미리 찾아 쓰고 나머지를 평생 나눠 받는 방식은?","o":["종신혼합방식","종신지급방식","확정기간방식","일시금방식"],"a":0,"c":"주택연금은 수령 방식을 고를 수 있어요.","e":"인출 한도 안에서 목돈을 먼저 찾고 나머지를 평생 월지급금으로 받는 것은 종신혼합방식이에요.","w":[null,"평생 월지급금만 받는 방식이에요.","정해진 기간만 받는 방식이에요.","주택연금에는 없는 방식이에요."],"k":"목돈 + 평생 연금을 \"섞은\" 방식이에요.","m":"종신지급 · 종신혼합(목돈 + 연금) · 확정기간혼합"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"금전신탁과 재산신탁","q":"신탁을 맡기는 재산의 종류에 따라 분류할 때 재산신탁에 해당하지 않는 것은?","o":["증권신탁","금전채권신탁","부동산신탁","특정금전신탁"],"a":3,"c":"신탁은 처음 맡기는 재산이 금전이면 금전신탁, 금전 이외의 재산이면 재산신탁이에요.","e":"특정금전신탁은 금전을 맡기는 금전신탁이에요. 증권·금전채권·동산·부동산·무체재산권 신탁이 재산신탁이에요.","w":["재산신탁이에요.","재산신탁이에요.","재산신탁이에요.",null],"k":"\"돈\"을 맡기면 금전신탁, \"물건·권리\"를 맡기면 재산신탁이에요.","m":"금전신탁(특정·불특정) / 재산신탁(증권·금전채권·동산·부동산·무체재산권)"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"부동산신탁의 종류","q":"부동산 소유자가 부동산을 신탁하고 수익권증서를 받아 이를 담보로 금융기관에서 대출을 받을 때 활용하는 신탁은?","o":["담보신탁","관리신탁","처분신탁","개발신탁"],"a":0,"c":"부동산신탁은 목적에 따라 담보·관리·처분·개발(토지)신탁 등으로 나뉘어요.","e":"담보신탁은 부동산을 신탁하고 받은 수익권증서를 담보로 대출받는 방식이에요. 저당권보다 비용과 절차가 간편해요.","w":[null,"소유권 보존·임대 관리 목적이에요.","부동산 처분이 목적이에요.","신탁회사가 개발·분양해요."],"k":"부동산을 맡기고 그 증서로 돈을 빌려요.","m":"담보(대출) · 관리 · 처분 · 개발(토지) · 분양관리신탁"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"집합투자기구의 종류","q":"자본시장법상 집합투자기구를 투자 대상에 따라 분류한 것에 해당하지 않는 것은?","o":["증권 집합투자기구","부동산 집합투자기구","특별자산 집합투자기구","보험 집합투자기구"],"a":3,"c":"자본시장법은 집합투자기구를 주로 투자하는 자산에 따라 5가지로 나눠요.","e":"증권, 부동산, 특별자산, 혼합자산, 단기금융(MMF) 집합투자기구로 분류해요. 보험 집합투자기구는 없어요.","w":["해당해요.","해당해요.","해당해요.",null],"k":"\"증·부·특·혼·단\" 다섯 가지예요.","m":"증권 · 부동산 · 특별자산 · 혼합자산 · 단기금융(MMF)"},{"s":1,"sec":"금융상품","star":3,"lv":"상","rev":0,"t":"기준가격 계산","q":"어느 투자신탁의 순자산총액이 180억원, 발행 좌수가 150억좌일 때 기준가격(1,000좌 기준)은?","o":["833.33원","1,000원","1,200원","1,800원"],"a":2,"c":"기준가격은 펀드 1,000좌의 가치예요.","e":"기준가격 = 순자산총액 ÷ 총좌수 × 1,000 = 180억 ÷ 150억 × 1,000 = 1,200원이에요.","w":["분자·분모를 바꿨어요.","최초 설정 기준가예요.",null,"1,800원이 나오려면 좌수가 100억좌여야 해요. 180억 ÷ 150억 × 1,000 = 1,200원이에요."],"k":"1좌당 1.2원이니 1,000좌는 1,200원이에요.","m":"기준가격 = 순자산 ÷ 총좌수 × 1,000","f":"180 ÷ 150 × 1,000 = 1,200원"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"판매수수료와 판매보수","q":"펀드의 판매수수료와 판매보수를 비교한 설명으로 가장 적절한 것은?","o":["판매수수료는 매매 시점에 한 번 부과하고, 판매보수는 보유 기간 동안 펀드 재산에서 계속 차감한다","판매보수는 가입 시 한 번만 낸다","판매수수료는 펀드 재산에서 매일 차감한다","둘은 같은 개념이다"],"a":0,"c":"수수료는 \"한 번\", 보수는 \"계속\" 내는 비용이에요.","e":"판매수수료는 가입이나 환매 때 투자자가 한 번 내고, 판매보수는 펀드 재산에서 일정 비율로 계속 빠져나가요.","w":[null,"보수는 계속 부과돼요.","수수료는 매매 시점에 내요.","서로 달라요."],"k":"수수료 = 입장권, 보수 = 월 사용료예요.","m":"수수료 = 일회성(선취·후취) · 보수 = 지속(펀드 재산 차감)"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"ETF의 괴리율과 추적오차","q":"ETF에 관한 설명으로 가장 적절한 것은?","o":["괴리율은 시장가격과 순자산가치(NAV)의 차이이고, 추적오차는 NAV와 기초지수 수익률의 차이이다","괴리율은 NAV와 기초지수의 차이이다","추적오차는 시장가격과 NAV의 차이이다","ETF는 거래소에서 거래되지 않는다"],"a":0,"c":"ETF는 거래소에서 사고팔기 때문에 시장가격과 실제 가치가 조금 다를 수 있어요.","e":"괴리율은 ETF 시장가격이 NAV에서 벗어난 정도, 추적오차는 NAV가 기초지수를 얼마나 잘 따라가는지를 나타내요.","w":[null,"추적오차의 설명이에요.","괴리율의 설명이에요.","거래소에 상장돼요."],"k":"괴리율 = \"가격 vs 가치\", 추적오차 = \"가치 vs 지수\"예요.","m":"괴리율 = 시장가 − NAV · 추적오차 = NAV − 지수"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"레버리지·인버스 ETF","q":"기초지수 일간 수익률의 2배를 추구하는 레버리지 ETF에 관한 설명으로 가장 적절한 것은?","o":["장기 보유 시 누적 수익률이 기초지수 누적 수익률의 2배와 달라질 수 있다","장기 보유해도 누적 수익률은 항상 정확히 2배이다","기초지수가 하락하면 이익이 난다","가격 변동성이 기초지수보다 작다"],"a":0,"c":"레버리지 ETF는 \"하루\" 수익률의 2배를 추구해요.","e":"매일 2배를 다시 맞추기 때문에 변동이 큰 횡보장에서는 복리 효과로 장기 누적 수익률이 지수 누적 수익률의 2배보다 낮아질 수 있어요.","w":[null,"정확히 2배가 아닐 수 있어요.","인버스 ETF의 설명이에요.","변동성이 더 커요."],"k":"+10%, −10%가 반복되면 지수보다 레버리지 ETF가 더 많이 깎여요.","m":"레버리지 ETF = 일간 2배 · 장기 누적 ≠ 2배"},{"s":1,"sec":"금융상품","star":3,"lv":"상","rev":0,"t":"ELS 손익 계산","q":"〈보기〉 조건의 스텝다운 ELS에 1,000만원을 투자했다. 만기 평가 결과 원금 손실 금액은?\n• 녹인(Knock-in) 배리어: 최초 기준가의 50%\n• 만기 상환 조건: 기초자산이 최초 기준가의 85% 이상이면 원금 + 연 8%\n• 투자 기간 중 기초자산이 최초 기준가의 45%까지 떨어진 적이 있음\n• 만기 평가가격: 최초 기준가의 70%","o":["0원","150만원","300만원","550만원"],"a":2,"c":"녹인 배리어를 한 번이라도 깼고 만기에 상환 조건을 못 맞추면, 기초자산 하락률만큼 손실이 나요.","e":"기간 중 45%로 녹인(50%)을 깼고, 만기 70%로 상환 조건(85%) 미달이라 하락률 30%만큼 손실 → 1,000만 × 30% = 300만원이에요.","w":["녹인이 발생했어요.","상환 조건과의 차이(15%)로 계산했어요.",null,"최저 가격(45%)으로 계산했어요."],"k":"바닥(녹인)을 한 번 뚫었으면, 만기 가격이 떨어진 만큼 잃어요.","m":"녹인 발생 + 만기 조건 미달 → 손실 = 만기 하락률","f":"1,000만 × 30% = 300만원"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"DLS","q":"주가가 아닌 금리, 환율, 원자재, 신용 등을 기초자산으로 하는 파생결합증권은?","o":["DLS","ELS","ELW","ELD"],"a":0,"c":"파생결합증권은 기초자산 종류에 따라 이름이 달라요.","e":"주가 이외의 금리·환율·원자재·신용 등을 기초자산으로 하는 것은 DLS예요.","w":[null,"주가·주가지수가 기초자산이에요.","주식 관련 권리 증권이에요.","은행 예금 상품이에요."],"k":"E는 Equity(주식), D는 Derivatives(그 밖의 것)예요.","m":"ELS = 주가 · DLS = 금리·환율·원자재·신용"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"ELB의 특징","q":"ELB(주가연계파생결합사채)에 관한 설명으로 가장 적절한 것은?","o":["원금 보장형 구조이지만 발행회사의 신용위험은 있다","예금자보호 대상이다","원금 손실이 크게 날 수 있는 구조이다","은행만 발행할 수 있다"],"a":0,"c":"ELB는 원금보장형 ELS가 사채 형태로 바뀐 상품이에요.","e":"ELB는 원금이 보장되는 구조지만 발행 증권사가 파산하면 원금을 돌려받지 못할 수 있어요. 예금자보호 대상이 아니에요.","w":[null,"예금자보호 대상이 아니에요.","원금 보장 구조예요.","증권사가 발행해요."],"k":"약속은 원금 보장이지만, 약속한 회사가 망하면 소용없어요.","m":"ELB = 원금보장형 · 발행사 신용위험 · 비보호"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"조기상환형 ELS","q":"스텝다운형 ELS의 조기상환 구조에 관한 설명으로 가장 적절한 것은?","o":["기초자산이 오를수록 상환이 늦어진다","조기상환 조건은 시간이 갈수록 높아진다","정해진 평가일마다 기초자산 가격이 조건 이상이면 약정 수익과 함께 조기상환되고, 조건 가격은 시간이 갈수록 낮아진다","조기상환되면 원금 손실이 확정된다"],"a":2,"c":"스텝다운은 \"계단식으로 내려간다\"는 뜻이에요.","e":"평가일마다 정해진 조건(예: 90 → 85 → 80%) 이상이면 원금과 약정 수익을 받고 조기상환돼요. 조건이 갈수록 낮아져 상환 가능성이 커져요.","w":["오르면 조기상환이 쉬워져요.","갈수록 낮아져요.",null,"조기상환은 수익을 받고 끝나요."],"k":"시간이 갈수록 넘어야 할 문턱이 낮아져요.","m":"스텝다운 = 조기상환 조건이 계단식으로 하락"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"자산유동화 구조","q":"자산유동화증권(ABS) 발행 구조에 관한 설명으로 가장 적절한 것은?","o":["자산보유자가 유동화자산을 SPC에 진정 매각해 자산보유자의 파산 위험과 분리한다","SPC가 자산보유자의 영업을 직접 수행한다","ABS 상환 재원은 자산보유자의 전체 수익이다","유동화자산은 자산보유자의 재무상태표에 그대로 남아 파산 시 함께 처리된다"],"a":0,"c":"ABS는 자산에서 나오는 현금흐름을 기반으로 증권을 발행해요.","e":"자산보유자가 자산을 SPC(유동화전문회사)에 진정 매각하면, 자산보유자가 파산해도 유동화자산은 영향을 받지 않아요(파산 절연).","w":[null,"SPC는 서류상 회사예요.","유동화자산의 현금흐름이 상환 재원이에요.","진정 매각으로 분리돼요."],"k":"자산을 회사에서 \"떼어내\" 별도 상자(SPC)에 담아요.","m":"ABS: 자산보유자 → SPC 진정매각 → 파산 절연 → 증권 발행"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"이체증권(MPTS)과 저당담보부채권(MBB)","q":"주택저당 유동화증권의 종류에 관한 설명으로 가장 적절한 것은?","o":["이체증권(MPTS)은 주택대출에서 들어온 원리금을 투자자에게 그대로 넘겨주므로 조기상환 위험을 투자자가 진다","저당담보부채권(MBB)은 조기상환 위험을 투자자가 모두 진다","이체증권(MPTS)은 발행기관의 부채로 남는 채권형 증권이다","두 증권은 현금흐름 구조가 완전히 같다"],"a":0,"c":"주택저당 유동화증권은 원리금을 그대로 넘겨주는 지분형(이체증권)과, 발행기관이 채권으로 발행하는 채권형(MBB) 등으로 나뉘어요.","e":"이체증권(MPTS)은 대출자의 원리금 상환액을 투자자에게 그대로 넘기는 지분형이라 조기상환 위험을 투자자가 져요. MBB는 발행기관 부채로 남는 채권이라 조기상환 위험은 발행기관이 져요.","w":[null,"MBB는 발행기관이 조기상환 위험을 져요.","MBB의 설명이에요.","현금흐름 구조가 달라요."],"k":"받은 대로 바로 넘겨주는 구조면, 일찍 갚는 위험도 투자자에게 넘어가요.","m":"MPTS = 지분형 · 원리금 그대로 이전 · 투자자가 조기상환위험 / MBB = 채권형 · 발행자 부채 · 초과담보"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"ABCP","q":"ABCP(자산담보부기업어음)에 관한 설명으로 가장 적절한 것은?","o":["유동화 자산을 담보로 단기 기업어음을 발행하며, 만기마다 다시 발행해야 하는 차환 위험이 있다","만기가 30년 이상인 장기 채권이다","주식으로 전환할 수 있다","차환 위험이 전혀 없다"],"a":0,"c":"ABCP는 ABS 구조에 기업어음(CP)을 결합한 상품이에요.","e":"ABCP는 장기 자산을 담보로 단기 CP를 반복 발행(롤오버)하므로, 시장이 경색되면 차환하지 못하는 위험이 있어요.","w":[null,"단기 어음이에요.","전환권이 없어요.","차환 위험이 대표적 위험이에요."],"k":"긴 자산에 짧은 빚을 계속 이어 붙이는 구조예요.","m":"ABCP = 유동화자산 담보 CP · 차환(롤오버) 위험"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"커버드본드","q":"커버드본드(이중상환청구권부 채권)에 관한 설명으로 가장 적절한 것은?","o":["투자자는 발행기관에 대한 상환청구권과 담보자산에 대한 우선변제권을 함께 가진다","담보자산에 대해서만 청구할 수 있다","발행기관에 대해서만 청구할 수 있다","담보자산이 SPC로 진정 매각된다"],"a":0,"c":"커버드본드는 ABS와 달리 담보자산이 발행기관 재무상태표에 남아 있어요.","e":"투자자는 발행기관(은행 등)에 상환을 청구할 수 있고, 발행기관이 파산하면 담보자산에서 우선 변제받을 수 있어요.","w":[null,"발행기관에도 청구할 수 있어요.","담보자산에도 우선변제권이 있어요.","ABS의 설명이에요."],"k":"은행에도, 담보에도 두 번 청구할 수 있어요.","m":"커버드본드 = 발행자 청구권 + 담보 우선변제 (이중상환)"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"일임형 랩과 자문형 랩","q":"일임형 랩어카운트와 자문형 랩어카운트를 비교한 설명으로 가장 적절한 것은?","o":["일임형은 증권사가 투자 판단을 맡아 운용하고, 자문형은 자문을 받되 최종 결정은 고객이 한다","자문형은 증권사가 고객 동의 없이 매매한다","일임형은 고객이 매매를 모두 결정한다","두 방식의 차이는 없다"],"a":0,"c":"랩어카운트는 여러 서비스를 하나로 묶고 잔고 기준 수수료를 받는 계좌예요.","e":"일임형은 증권사(운용자)가 투자 판단을 위임받아 운용하고, 자문형은 자문사의 조언을 받아 고객이 최종 결정해요.","w":[null,"자문형은 고객이 결정해요.","일임형은 운용자가 결정해요.","판단 주체가 달라요."],"k":"일임 = \"알아서 해 줘\", 자문 = \"조언만 해 줘\"예요.","m":"일임형 = 운용자 판단 · 자문형 = 고객 최종 결정"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"변액보험","q":"변액보험에 관한 설명으로 가장 적절한 것은?","o":["보험료 일부를 펀드로 운용해 그 실적에 따라 보험금·해지환급금이 변한다","확정 이율로 운용되어 원금 손실이 없다","실적배당 부분까지 모두 예금자보호 대상이다","일반계정에서 운용한다"],"a":0,"c":"변액보험은 보험과 펀드를 합친 상품이에요.","e":"변액보험은 보험료를 특별계정의 펀드로 운용하고, 그 실적에 따라 보험금과 환급금이 달라져요. 실적배당 부분은 예금자보호 대상이 아니에요(최저보증 부분 제외).","w":[null,"실적에 따라 손실이 날 수 있어요.","실적배당 부분은 보호되지 않아요.","특별계정에서 운용해요."],"k":"보험 껍데기 안에 펀드가 들어 있어요.","m":"변액보험 = 특별계정 · 실적배당 · 실적 부분 비보호"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"생명보험과 손해보험","q":"생명보험과 손해보험을 비교한 설명으로 가장 적절한 것은?","o":["생명보험은 사망 등 정해진 사고에 약정 금액을 주는 정액보상이 원칙이고, 손해보험은 실제 손해를 보상하는 실손보상이 원칙이다","생명보험은 실손보상이 원칙이다","손해보험은 사람의 생존·사망만 보장한다","두 보험 모두 정액보상만 한다"],"a":0,"c":"보험은 보상 방식에 따라 정액보상과 실손보상으로 나뉘어요.","e":"생명보험은 사람의 생사에 대해 미리 정한 금액을 지급하고(정액), 손해보험은 재산상 실제 손해만큼 보상해요(실손).","w":[null,"생명보험은 정액보상이에요.","손해보험은 재산 손해를 보상해요.","손해보험은 실손보상이에요."],"k":"생명보험 = 정해진 금액, 손해보험 = 실제 손해만큼이에요.","m":"생명 = 정액 · 손해 = 실손(이득금지 원칙)"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"종합금융회사 CMA","q":"CMA 중 예금자보호 대상인 것은?","o":["종합금융회사의 종금형 CMA","증권사의 RP형 CMA","증권사의 MMF형 CMA","증권사의 MMW형 CMA"],"a":0,"c":"CMA는 운용 대상에 따라 여러 종류가 있고, 보호 여부가 달라요.","e":"종금사가 판매하는 종금형 CMA는 예금자보호 대상이에요. 증권사의 RP형·MMF형·MMW형 CMA는 보호 대상이 아니에요.","w":[null,"보호되지 않아요.","보호되지 않아요.","보호되지 않아요."],"k":"종금사가 직접 받는 CMA만 예금처럼 보호돼요.","m":"종금형 CMA = 보호 · RP·MMF·MMW형 = 비보호"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"발행어음","q":"종합금융투자사업자(대형 증권사)가 자기 신용으로 발행하는 발행어음에 관한 설명으로 가장 적절한 것은?","o":["발행 증권사의 신용으로 원리금을 지급하며, 예금자보호 대상이 아니다","예금자보호 대상이다","주가에 연동해 수익이 결정된다","모든 증권사가 발행할 수 있다"],"a":0,"c":"발행어음은 증권사가 자기 신용으로 발행하는 단기 금융상품이에요.","e":"발행어음은 발행 증권사가 원리금을 지급하지만 예금자보호 대상이 아니어서, 발행사 신용위험이 있어요.","w":[null,"보호되지 않아요.","확정금리형이에요.","인가받은 종합금융투자사업자만 발행해요."],"k":"증권사가 \"제가 갚겠습니다\"라고 약속한 어음이에요.","m":"발행어음 = 초대형 IB 발행 · 확정금리 · 비보호"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"양도성예금증서(CD)","q":"양도성예금증서(CD)에 관한 설명으로 가장 적절하지 않은 것은?","o":["은행이 발행하는 무기명 할인식 증서이다","만기 전 시장에서 양도할 수 있다","중도해지가 불가능하다","예금자보호 대상이다"],"a":3,"c":"CD는 은행 정기예금에 양도성을 준 증서예요.","e":"CD는 양도가 가능한 무기명 증서로 예금자보호 대상이 아니에요.","w":["무기명 할인식이에요.","양도할 수 있어요.","중도해지가 안 돼요(대신 매도).",null],"k":"사고팔 수 있는 예금증서지만, 보호는 안 돼요.","m":"CD: 무기명 · 할인식 · 양도 가능 · 중도해지 불가 · 비보호"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"주택청약종합저축 소득공제","q":"주택청약종합저축의 소득공제에 관한 설명으로 가장 적절한 것은?","o":["총급여 7,000만원 이하 무주택 세대주가 연 납입액 300만원 한도로 40%를 소득공제받을 수 있다","모든 가입자가 납입액 전액을 소득공제받는다","유주택자도 소득공제를 받는다","세액공제 방식이다"],"a":0,"c":"주택청약종합저축은 무주택 서민을 위해 소득공제 혜택이 있어요.","e":"총급여 7,000만원 이하 무주택 세대주는 연 300만원 한도 납입액의 40%(최대 120만원)를 소득공제받을 수 있어요.","w":[null,"요건과 한도가 있어요.","무주택 세대주만 받아요.","소득공제 방식이에요."],"k":"무주택 세대주, 300만원 × 40% = 최대 120만원이에요.","m":"청약저축 소득공제: 총급여 7천 이하 · 무주택 세대주 · 300만 × 40%"},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"t":"증권의 종류","q":"자본시장법상 증권의 종류에 해당하지 않는 것은?","o":["채무증권","지분증권","파생결합증권","선물증권"],"a":3,"c":"자본시장법은 증권을 6가지로 분류해요.","e":"증권은 채무, 지분, 수익, 투자계약, 파생결합, 증권예탁 증권의 6가지예요. 선물증권이라는 분류는 없어요.","w":["해당해요.","해당해요.","해당해요.",null],"k":"\"채·지·수·투·파·예\" 여섯 가지예요.","m":"증권 6종: 채무 · 지분 · 수익 · 투자계약 · 파생결합 · 증권예탁"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"증권과 파생상품의 구분","q":"자본시장법상 증권과 파생상품을 구분하는 기준으로 가장 적절한 것은?","o":["투자원금을 초과하는 손실 가능성(추가 지급 의무)이 있는지 여부","거래소 상장 여부","발행 회사의 규모","만기의 길이"],"a":0,"c":"자본시장법은 금융투자상품을 원본 손실 정도에 따라 증권과 파생상품으로 나눠요.","e":"투자원금까지만 손실이 날 수 있으면 증권, 원금을 넘는 손실(추가 지급 의무)이 생길 수 있으면 파생상품이에요.","w":[null,"상장 여부는 장내·장외 구분 기준이에요.","구분 기준이 아니에요.","구분 기준이 아니에요."],"k":"낸 돈보다 더 잃을 수 있으면 파생상품이에요.","m":"원본 손실 ≤ 원금 → 증권 · 원본 초과 손실 → 파생상품"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"투자성 판단 시 투자금액 산정","q":"자본시장법상 투자성(원본 손실 가능성)을 판단할 때, 투자자가 지급한 금액에서 빼고 계산하는 것은?","o":["판매수수료","투자 원금","환매수수료","발행인 신용위험에 따른 미지급액"],"a":0,"c":"투자성은 \"낸 돈(투자금액)\"이 \"돌려받는 돈(회수금액)\"보다 커질 수 있는지로 판단해요.","e":"투자금액을 셀 때는 판매수수료 같은 비용을 빼요. 환매수수료, 세금, 발행인 신용위험으로 못 받은 금액 등은 회수금액 쪽에 포함해 계산해요.","w":[null,"원금은 투자금액 그 자체예요.","회수금액 산정에 포함해요.","회수금액 산정에 포함해요."],"k":"수수료 때문에 원금이 줄어드는 건 \"투자 손실\"로 보지 않아요.","m":"투자금액에서 제외: 판매수수료 등 / 회수금액에 포함: 환매수수료·세금·미지급액"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"상장지수증권(ETN)","q":"ETN(상장지수증권)과 ETF를 비교한 설명으로 가장 적절한 것은?","o":["ETN은 증권사가 자기 신용으로 발행하는 파생결합증권이라 발행사 신용위험이 있다","ETN은 집합투자증권이다","ETN은 신탁업자가 자산을 별도 보관한다","ETN은 만기가 없다"],"a":0,"c":"ETN과 ETF는 둘 다 지수를 따라가며 거래소에서 거래되지만, 법적 성격이 달라요.","e":"ETN은 증권사가 지수 수익률 지급을 약속하는 파생결합증권이라 발행사가 파산하면 손실 위험이 있어요. ETF는 집합투자증권이에요.","w":[null,"ETF의 설명이에요.","ETF의 설명이에요.","ETN은 만기가 있어요."],"k":"ETN은 \"증권사의 약속\", ETF는 \"펀드\"예요.","m":"ETN = 파생결합증권·신용위험·만기 있음 / ETF = 집합투자증권"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"t":"부동산 집합투자기구","q":"부동산 집합투자기구에 관한 설명으로 가장 적절한 것은?","o":["집합투자재산의 50%를 초과해 부동산 및 부동산 관련 자산에 투자한다","부동산에 10% 이상만 투자하면 된다","부동산에는 투자할 수 없다","수시 환매가 원칙이다"],"a":0,"c":"집합투자기구 종류는 주로 투자하는 자산 비율로 정해요.","e":"부동산 집합투자기구는 재산의 50%를 초과해 부동산과 부동산 관련 자산에 투자해요. 유동성이 낮아 대개 환매금지형으로 만들어요.","w":[null,"50% 초과가 기준이에요.","부동산에 주로 투자해요.","대부분 환매금지형이에요."],"k":"절반 넘게 부동산이면 부동산 펀드예요.","m":"증권·부동산·특별자산 펀드 = 해당 자산 50% 초과"},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"보험사고에 따른 생명보험 분류","q":"생명보험 상품을 분류한 설명으로 가장 적절한 것은?","o":["피보험자가 만기까지 살아 있을 때만 보험금을 주는 보험은 사망보험이다","보험기간 중 사망하면 사망보험금을, 만기까지 살면 만기보험금을 주는 보험은 생사혼합보험(양로보험)이다","배상책임보험과 운송보험은 생명보험 가운데 사망보험에 속한다","체증식 보험은 시간이 지날수록 계약자가 내는 보험료가 늘어나는 보험이다"],"a":1,"c":"생명보험은 보험금을 주는 사고에 따라 생존보험·사망보험·생사혼합보험으로 나눠요. 피보험자가 2명 이상이면 연생보험, 보험금이 점점 커지면 체증식 보험이에요.","e":"양로보험은 생존보험의 약점(중간에 사망하면 보장이 없음)을 사망보장으로 메운 생사혼합보험이에요.","w":["만기까지 살아 있을 때 보험금을 주는 보험은 생존보험이에요.",null,"배상책임보험·운송보험은 재산상 손해를 보상하는 손해보험이에요.","체증식은 보험료가 아니라 보험금이 점점 늘어나는 보험이에요."],"k":"살면 받는 게 생존보험, 죽으면 받는 게 사망보험, 둘 다 되는 게 양로보험이에요.","m":"생존 / 사망(정기·종신) / 생사혼합 = 양로 · 체증식 = 보험금↑ · 연생 = 피보험자 2인 이상","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"영업보험료의 구성","q":"생명보험 영업보험료를 설명한 내용 중 틀린 것은?","o":["계약자가 실제로 내는 영업보험료는 순보험료에 부가보험료를 더한 것이다","순보험료 중 위험보험료는 사망보험금 등 보험금 지급에 쓰인다","저축보험료는 만기환급금 등의 재원이 된다","부가보험료는 예정이율을 기초로 계산되어 만기환급금 적립에 쓰인다"],"a":3,"c":"보험료는 위험률·이율·사업비율 세 가지를 미리 예상한 값(예정기초율)으로 계산해요(3이원방식). 만기환급금이 거의 없는 보장성 보험은 위험보험료 비중이, 저축성 보험은 저축보험료 비중이 커요.","e":"부가보험료는 예정사업비율을 기초로 계산하며 신계약비·유지비·수금비 같은 사업비에 써요. 만기환급금 재원은 예정이율로 계산하는 저축보험료예요.","w":["영업보험료 = 순보험료 + 부가보험료예요.","위험보험료는 예정위험률로 계산해 보험금 지급에 써요.","저축보험료는 예정이율로 계산해 만기환급금 재원이 돼요.",null],"k":"보험료는 '보험금 줄 돈(위험)' + '모아 둘 돈(저축)' + '회사 운영비(부가)'로 쪼개져요.","m":"영업보험료 = 순(위험·저축) + 부가(신계약비·유지비·수금비) · 3이원: 위험률·이율·사업비율(모두 예정치)","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"집합투자재산의 평가 원칙","q":"자본시장법상 펀드 재산을 평가하는 방법으로 가장 적절한 것은?","o":["집합투자재산은 취득원가로 평가하는 것이 원칙이다","믿을 만한 시장가격이 없는 자산은 집합투자재산평가위원회가 정한 공정가액으로 평가한다","시가가 있더라도 판매회사가 정한 가격을 우선 적용한다","MMF를 포함한 모든 집합투자기구는 장부가 평가가 금지된다"],"a":1,"c":"펀드 재산은 시가로 평가하는 것이 원칙이에요. 시가가 없으면 공정가액으로 평가하고, MMF는 예외적으로 장부가 평가가 허용돼요.","e":"믿을 만한 시장가격을 구할 수 없는 자산은 집합투자업자 안의 집합투자재산평가위원회가 정한 공정가액으로 평가해요.","w":["원칙은 시가평가예요. 취득원가(장부가)는 원칙이 아니에요.",null,"시가가 있으면 시가가 우선이고, 판매회사는 평가 주체가 아니에요.","MMF는 장부가 평가가 허용되는 대표적인 예외예요."],"k":"펀드 재산은 '오늘 시장에서 얼마에 팔리나'로 매겨요. 시장 가격이 없으면 평가위원회가 공정한 값을 정해요.","m":"펀드 평가: 시가 원칙 → 없으면 공정가액(평가위원회) · MMF = 장부가 예외","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"상","t":"과세기준가격","q":"주식형 투자신탁의 기준가격이 1,000원에서 시작해 결산 시점까지 좌당 다음과 같은 손익이 생겼다. 결산일 현재의 기준가격과 과세기준가격은 각각 얼마인가? (그 밖의 비용과 손익은 없다)\n· 채권 이자수익: +25원\n· 주식 배당금: +15원\n· 상장주식 매매·평가이익: +80원","o":["기준가격 1,120원 – 과세기준가격 1,120원","기준가격 1,040원 – 과세기준가격 1,120원","기준가격 1,120원 – 과세기준가격 1,040원","기준가격 1,040원 – 과세기준가격 1,040원"],"a":2,"c":"과세기준가격은 기준가격에서 비과세 손익(상장주식 매매·평가손익 등)을 뺀 가격이에요. 투자자의 과세 대상 이익은 이 가격으로 계산해요. 그래서 주식에서 손실이 나면 과세기준가격이 기준가격을 웃돌 수도 있어요.","e":"기준가격에는 모든 손익이 반영돼 1,120원이에요. 과세기준가격은 상장주식 매매·평가이익 80원을 빼서 1,040원이에요.","w":["상장주식 매매이익을 과세기준가격에서 빼지 않았어요.","두 가격을 거꾸로 짝지었어요.",null,"기준가격에서도 상장주식 이익을 뺐어요. 기준가격에는 모든 손익이 들어가요."],"k":"펀드 성적표(기준가격)에는 모든 수익이 들어가지만, 세금 계산용 가격(과세기준가격)에는 세금을 안 매기는 주식 차익이 빠져요.","m":"과세기준가격 = 기준가격 − 상장주식 매매·평가손익 · 이자·배당은 포함","f":"기준가격 = 1,000 + 25 + 15 + 80 = 1,120원 / 과세기준가격 = 1,000 + 25 + 15 = 1,040원","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"중","t":"신탁재산 독립성의 효과","q":"신탁재산의 독립성에 관한 〈보기〉의 설명 중 옳은 것을 모두 고른 것은?\n〈보기〉\nㄱ. 수탁자가 파산해도 신탁재산은 수탁자의 파산재단에 들어가지 않는다\nㄴ. 수탁자가 사망하면 신탁재산은 수탁자의 상속인에게 상속된다\nㄷ. 수탁자의 개인 채권자는 원칙적으로 신탁재산에 강제집행할 수 없다\nㄹ. 신탁재산에 속한 채권과 수탁자 개인의 채무는 서로 상계할 수 있다","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"신탁재산은 수탁자 명의로 되어 있어도 수탁자의 고유재산과 분리된 독립된 재산이에요. 수탁자는 이를 고유재산과 구분해 관리(분별관리)하고 선량한 관리자의 주의로 운용해야 해요. 수탁자가 바뀌어도 신탁은 끝나지 않아요.","e":"신탁재산은 수탁자의 파산재단에 들어가지 않고(ㄱ), 수탁자의 채권자가 강제집행할 수도 없어요(ㄷ).","w":["ㄴ이 틀려요. 신탁재산은 수탁자의 상속재산에 포함되지 않아요.",null,"ㄴ·ㄹ 모두 틀려요. 상속되지 않고, 상계도 금지돼요.","ㄹ이 틀려요. 신탁재산의 채권과 수탁자 고유의 채무는 상계할 수 없어요. 맞는 ㄱ도 빠졌어요."],"k":"신탁재산은 수탁자 집에 맡겨 둔 남의 금고예요. 수탁자가 망하거나 세상을 떠나도 그 금고는 수탁자 재산으로 치지 않아요.","m":"신탁재산 독립성: 강제집행 금지 · 파산재단 X · 상속재산 X · 상계 금지 · 분별관리","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"특정금전신탁의 운용과 과세","q":"특정금전신탁을 설명한 내용 중 틀린 것은?","o":["위탁자는 무엇에 투자할지와 함께 어떤 방법·조건으로 굴릴지도 정할 수 있다","수탁자는 운용 효율을 위해 여러 위탁자의 특정금전신탁 재산을 한데 모아 운용할 수 있다","편입한 자산을 팔아 현금화할 수 있으면 만기 전에 해지할 수 있다","신탁재산에서 생긴 소득은 이자·배당 등 원천별로 구분해 수익자에게 과세한다"],"a":1,"c":"특정금전신탁은 위탁자가 맡긴 돈을 어디에 어떻게 굴릴지 직접 정하는 1:1 맞춤형 신탁이에요. 수탁자가 굴릴 곳을 정하는 것은 불특정금전신탁이에요.","e":"특정금전신탁은 위탁자별로 따로 운용하는 상품이라 다른 신탁재산과 합동운용할 수 없어요.","w":["위탁자는 운용 대상·방법·조건을 지정할 수 있어요. 다만 누구에게 운용을 맡길지 담당 운용역을 고를 수는 없어요.",null,"담은 자산을 팔 수 있는 상태라면 중도해지가 돼요.","집합투자기구가 아닌 신탁의 이익은 소득 원천별로 과세해서 배당은 배당소득, 이자는 이자소득이 돼요. 상장주식 매매차익처럼 원래 비과세인 소득은 과세되지 않아요."],"k":"특정금전신탁은 맞춤 양복이에요. 고객마다 따로 재단하니 남의 옷감과 섞어 만들 수 없어요.","m":"특정금전신탁: 위탁자 운용지시 · 합동운용 X · 운용역 지정 X · 소득은 원천별 과세","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"신탁의 설정 방법과 이익향수 금지","q":"신탁의 설정과 당사자를 바르게 설명한 것은?","o":["신탁한 부동산의 소유 명의는 위탁자에게 그대로 남고 수탁자는 관리만 한다","위탁자와 수익자가 같은 사람인 자익신탁은 허용되지 않는다","수탁자는 공동수익자 가운데 한 명인 경우를 제외하면 누구의 명의로도 신탁의 이익을 누릴 수 없다","신탁은 위탁자와 수탁자의 계약으로만 설정할 수 있다"],"a":2,"c":"신탁은 위탁자(맡기는 사람)·수탁자(관리하는 사람)·수익자(이익을 받는 사람)로 이루어져요. 계약뿐 아니라 유언이나 신탁선언으로도 설정할 수 있어요.","e":"수탁자가 신탁의 이익을 챙기면 수익자를 위한 관리가 무너지므로 이익향수가 금지돼요. 다만 공동수익자 중 한 명인 경우는 예외예요.","w":["신탁하면 재산의 소유권이 수탁자에게 넘어가 등기도 수탁자 명의로 해요.","위탁자 자신이 수익자가 되는 자익신탁도, 다른 사람이 수익자가 되는 타익신탁도 가능해요.",null,"계약 외에 유언(유언신탁)이나, 위탁자가 스스로 수탁자가 되는 신탁선언으로도 설정할 수 있어요."],"k":"신탁은 내 재산을 믿을 만한 사람 이름으로 옮겨 관리를 맡기는 거예요. 맡은 사람이 그 이익을 몰래 챙기면 안 돼요.","m":"신탁 설정: 계약·유언·신탁선언 · 자익/타익 모두 가능 · 수탁자 이익향수 금지(공동수익자 예외) · 명의는 수탁자","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"역모기지의 위험 구조","q":"집을 담보로 맡기고 매달 연금처럼 돈을 받는 역모기지의 설명으로 틀린 것은?","o":["대출 원리금은 매달 갚지 않고 가입자가 사망하거나 주택을 처분할 때 한꺼번에 정산한다","대출 기간 동안 대출 잔액이 점점 늘어나는 구조이다","가입자가 기대수명보다 오래 생존해 누적 지급액이 집값을 넘어서는 위험은 대출 금융기관이 떠안는다","금리가 올라 대출 잔액이 빨리 불어나는 위험은 가입자만 지고 금융기관은 지지 않는다"],"a":3,"c":"역모기지는 집을 담보로 돈을 나눠 받는 '거꾸로 된' 주택담보대출이에요. 금융기관은 장수위험·금리위험·주택가격 하락위험 등을 떠안아요.","e":"금리가 오르면 대출 잔액이 빨리 불어나 담보가치를 넘기 쉬워지므로 금융기관도 금리위험을 져요.","w":["상환은 사망이나 주택 처분 시점에 한꺼번에 정산하는 구조예요.","원리금을 갚지 않고 계속 받으니 잔액이 점점 늘어나요.","오래 살수록 지급액이 쌓이는 장수위험은 금융기관 몫이에요.",null],"k":"집을 맡기고 매달 용돈을 받는 구조예요. 너무 오래 살거나 집값이 떨어지면 손해는 돈을 내준 쪽이 봐요.","m":"역모기지: 잔액 증가형 · 사망/처분 시 일시 정산 · 금융기관 위험 = 장수·금리·주택가격","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"ELS 수익구조 유형","q":"다음 ELS 수익구조 유형의 설명 중 틀린 것은?","o":["Knock-out형은 기초자산이 한 번이라도 미리 정한 가격에 닿으면 정해진 고정 수익(리베이트)으로 확정된다","Bull spread형은 만기 가격이 오를수록 수익이 늘지만 최대 수익과 최대 손실이 모두 정해져 있다","Digital형은 만기 가격이 기준을 넘는지 여부에 따라 미리 정한 두 가지 수익 중 하나를 준다","리버스 컨버터블형의 경우 기초자산이 크게 떨어져도 원금이 보장되는 대신 수익률이 낮다"],"a":3,"c":"ELS는 기초자산 가격과 수익을 연결하는 방식에 따라 여러 유형으로 나뉘어요. 원금보장형도 있고, 하락 시 손실이 나는 원금비보장형도 있어요.","e":"리버스 컨버터블형의 경우 기초자산이 정해진 폭 이상 떨어지지 않으면 높은 수익을 주지만, 그 이상 떨어지면 원금 손실이 나는 원금비보장형이에요. 풋옵션을 판 것과 비슷해요.","w":["투자기간 중 미리 정한 가격에 한 번이라도 닿으면 리베이트를 주고 끝나는 구조가 Knock-out형이에요.","콜 스프레드처럼 수익과 손실 범위가 모두 정해져 있어요.","수익이 둘 중 하나로 정해지는 구조가 Digital형이에요.",null],"k":"리버스 컨버터블은 '크게 안 떨어지면 높은 이자, 크게 떨어지면 손실'이에요. 보험료를 받는 쪽에 선 셈이에요.","m":"Knock-out = 정한 가격 닿으면 리베이트 · Bull spread = 수익·손실 상하한 · Digital = 둘 중 하나 · 리버스 컨버터블 = 원금비보장","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"상","t":"ELW 패리티와 내가격","q":"풋 ELW의 행사가격은 50,000원이고, 기초자산 주가는 지금 40,000원이다. 현재 패리티는 얼마이며, 이 ELW는 내가격·외가격 중 어디에 해당하는가? (패리티 = 기초자산가격 ÷ 행사가격)","o":["80% – 외가격","80% – 내가격","125% – 내가격","125% – 외가격"],"a":1,"c":"패리티는 '주가 ÷ 행사가격'으로 구해요. 콜은 패리티가 100%보다 크면 내가격, 풋은 100%보다 작으면 내가격이에요.","e":"패리티는 40,000 ÷ 50,000 = 80%예요. 풋 ELW는 주가가 행사가격보다 낮을수록 행사가치가 생기므로 지금은 내가격이에요.","w":["풋인데 콜 기준으로 판단했어요. 패리티 100% 미만은 풋에서 내가격이에요.",null,"행사가격 ÷ 주가로 거꾸로 나눴어요.","패리티를 거꾸로 계산했고 상태도 틀렸어요."],"k":"팔 권리(풋)는 시장 가격보다 비싸게 팔 수 있을 때 쓸모가 있어요. 4만원짜리를 5만원에 팔 수 있으니 이미 이득인 상태예요.","m":"패리티 = 주가 ÷ 행사가 · 콜: 100% 초과 내가격 · 풋: 100% 미만 내가격","f":"패리티 = 40,000 ÷ 50,000 = 80% → 풋은 주가 < 행사가격이므로 내가격","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"중","t":"ELW 가격 변수와 권리 범위","q":"ELW(주식워런트증권)를 설명한 내용 중 틀린 것은?","o":["시장금리가 오르면 콜 ELW 가격은 오르고 풋 ELW 가격은 내리는 경향이 있다","기초자산의 배당이 늘면 콜 ELW에는 불리하고 풋 ELW에는 유리하다","ELW를 산 투자자의 최대 손실은 ELW를 사는 데 쓴 금액으로 한정된다","ELW 보유자는 기초자산 발행회사의 주주처럼 의결권을 행사하고 배당을 받을 수 있다"],"a":3,"c":"ELW는 옵션과 같은 구조라 기초자산 가격·행사가격·변동성·잔존만기·금리·배당이 가격을 움직여요. 거래소에 상장되어 적은 돈으로 큰 레버리지를 낼 수 있고, 유동성공급자(LP)가 호가를 내요.","e":"ELW는 정해진 가격에 사거나 팔 '권리'일 뿐 주식이 아니라서 의결권도 배당도 없어요. 수익은 가격 변동에 따른 자본이득뿐이에요.","w":["금리가 오르면 행사가격의 현재가치가 낮아져 콜은 오르고 풋은 내려요.","배당이 나가면 주가가 떨어지는 효과가 있어 콜에는 불리하고 풋에는 유리해요.","매수자는 권리를 포기하면 그만이라 손실이 투자금으로 한정돼요. 그렇다고 원금이 보장되는 것은 아니에요.",null],"k":"ELW는 '살 권리'나 '팔 권리'를 담은 쿠폰이에요. 쿠폰을 가졌다고 회사 주인(주주)이 되지는 않아요.","m":"콜 ELW↑: 주가↑·행사가↓·변동성↑·만기↑·금리↑·배당↓ (풋은 주가·행사가·금리·배당이 반대) · 의결권·배당 X · 대용증권 X","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"ETF 상장 요건과 지정참가회사","q":"자본시장법상 ETF 규제를 설명한 내용 중 틀린 것은?","o":["추종하는 지수는 10종목 이상으로 구성되고 한 종목의 비중이 30%를 넘지 않아야 한다","설정한 뒤 30일 안에 거래소에 상장되어야 한다","지정참가회사는 설정·해지를 통해 ETF 시장가격이 순자산가치에 가깝게 유지되도록 돕는다","ETF가 상장폐지되더라도 집합투자업자는 그 ETF를 계속 운용할 수 있다"],"a":3,"c":"ETF는 지수를 따라가며 거래소에 상장되어 장중에 사고파는 펀드예요. 금전납입 원칙의 예외로 주식 실물로 설정할 수 있고, 지정참가회사(AP)는 설정·해지를, 유동성공급자(LP)는 호가 제시를 맡아 괴리를 줄여요.","e":"ETF가 상장폐지되면 집합투자업자는 상장이 폐지된 날부터 10일 안에 그 ETF를 해지하거나 해산해야 해요.","w":["ETF가 추종할 지수는 10종목 이상, 한 종목 비중 30% 이하 요건을 갖춰야 해요.","설정일부터 30일 이내 상장이 의무예요. 공모 환매금지형 펀드의 90일과 헷갈리지 마세요.","AP가 설정·해지로 수량을 조절하면 시장가격이 NAV에 수렴해요.",null],"k":"ETF는 '주식처럼 사고파는 펀드'예요. 거래소에서 내려오면 더 이상 ETF로 존재할 수 없어 정리해야 해요.","m":"ETF: 10종목 이상·1종목 30% 이하 · 설정 후 30일 내 상장 · 실물납입 가능 · AP = 설정·해지 · LP = 호가 · 상장폐지 → 10일 내 해지","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"MMF의 운용 제한","q":"MMF 운용 규제를 설명한 내용 중 틀린 것은?","o":["채무증권은 사들이는 시점의 신용등급 기준으로 상위 2개 등급에 드는 것만 담을 수 있다","증권을 빌려주거나 빌려 오는 방식으로 운용할 수 없다","원화 자산과 외화 자산을 하나의 MMF 안에서 함께 운용할 수 없다","국채는 신용위험이 없으므로 남은 만기와 관계없이 제한 없이 편입할 수 있다"],"a":3,"c":"MMF는 짧은 만기의 우량 자산에 투자해 수시 입출금에 대비하는 펀드예요. 그래서 편입 자산의 만기·등급·운용 방법을 엄격히 제한하고, 장부가 평가가 허용돼요.","e":"국채도 남은 만기 5년 이내만 편입할 수 있고, 남은 만기 1년 이상인 국채는 집합투자재산의 5% 이내로 제한돼요.","w":["취득 시점 기준 상위 2개 등급 이내의 채무증권만 담을 수 있어요.","증권 대여·차입은 MMF 운용 방법으로 허용되지 않아요.","원화 MMF와 외화 MMF는 따로 운용해야 해요.",null],"k":"MMF는 '잠깐 맡겨 두는 돈'을 굴리는 펀드라 오래 묶이는 자산을 많이 담을 수 없어요. 그래도 펀드라서 예금자보호는 안 돼요.","m":"MMF: 상위 2개 등급 · 대여·차입 X · 원화/외화 분리 · 국채 남은 만기 5년 이내(1년 이상은 5% 이내) · 장부가 평가 · 예금자보호 X","rev":0},{"s":1,"sec":"금융상품","star":1,"lv":"중","t":"표지어음·금융채·후순위채","q":"은행이 파는 목돈 운용 상품의 설명 중 틀린 것은?","o":["표지어음은 은행이 할인해 보유한 어음을 바탕으로 새로 발행하는 어음으로, 만기 전 중도해지는 할 수 없다","표지어음의 만기는 바탕이 된 원어음의 남은 만기 범위 안에서 정해진다","금융채는 만기 전에 돈이 필요하면 발행은행에 중도환매를 요청해 원금을 돌려받을 수 있다","후순위채는 발행 은행이 파산하면 일반 채권자보다 나중에 변제받아 금리가 높은 편이다"],"a":2,"c":"은행은 예금 외에도 표지어음·금융채·후순위채로 목돈을 모아요. 상품마다 중도해지 가능 여부와 예금자보호 여부가 달라요.","e":"금융채는 중도환매가 되지 않아요. 만기 전에 현금이 필요하면 시장에 팔아야 하고, 이때 금리 변동에 따라 가격 손실이 날 수 있어요.","w":["표지어음은 중도해지가 안 되지만 배서로 남에게 넘길 수 있고, 예금자보호 대상이에요.","원어음보다 만기를 길게 잡을 수 없어요.",null,"후순위채는 위험이 큰 만큼 금리가 높고, 예금자보호 대상이 아니에요."],"k":"표지어음은 은행이 갖고 있던 어음을 새 포장지에 싸서 파는 상품이에요. 포장 안의 어음보다 만기가 길 수는 없어요.","m":"표지어음: 중도해지 X·배서양도 O·예금자보호 O / 금융채: 중도환매 X / 후순위채: 고금리·예금자보호 X","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"DC형 사용자 최소부담금","q":"DC형 퇴직연금에 1년간 가입한 근로자 을의 연간 임금총액은 6,000만원이다. 사용자가 을의 계정에 납입해야 하는 최소 부담금과 적립금 운용 결과를 책임지는 자를 바르게 짝지은 것은?","o":["500만원 – 근로자","500만원 – 사용자","600만원 – 근로자","250만원 – 사용자"],"a":0,"c":"DC형은 회사가 해마다 1년 임금총액을 12로 나눈 금액 이상을 넣어 주고, 근로자가 직접 운용해 그 결과를 책임지는 퇴직연금이에요. 부담금은 정해져 있지만 받을 퇴직급여는 운용 결과에 따라 달라져요.","e":"6,000만원의 12분의 1인 500만원 이상을 사용자가 내야 해요. 운용 지시와 결과 책임은 근로자에게 있어요.","w":[null,"부담금은 맞지만 DC형의 운용 책임은 근로자에게 있어요.","임금총액의 10%로 계산했어요. 기준은 12분의 1이에요.","24분의 1로 잘못 계산했고 운용 책임자도 틀렸어요."],"k":"회사는 1년에 한 달 치 월급 정도를 계좌에 넣어 주고, 그 돈을 굴리는 건 근로자 몫이에요.","m":"DC 최소부담금 = 연간 임금총액 × 1/12 · 운용 책임 = 근로자 / DB = 급여 확정·회사가 운용 책임","f":"최소 부담금 = 6,000만원 × 1/12 = 500만원","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"투자신탁·투자회사의 관계회사","q":"펀드 관계회사가 맡는 역할을 바르게 설명한 것은?","o":["투자신탁에서 신탁업자는 신탁재산을 보관·관리하면서 집합투자업자의 운용지시가 법령과 규약에 맞는지 감시한다","투자회사의 주식 발행·명의개서 등 사무는 채권평가회사가 맡는다","투자회사의 이사회는 감독이사 1인만으로 구성할 수 있다","투자신탁은 법인격이 있어 그 이름으로 직접 계약을 맺는다"],"a":0,"c":"투자신탁은 집합투자업자와 신탁업자의 신탁계약으로 만드는 계약형이고, 투자회사는 주식회사 형태의 회사형이에요. 투자회사는 직원이 없는 서류상 회사라 업무를 외부 회사에 맡겨요.","e":"신탁업자는 신탁재산을 보관·관리하고, 운용지시가 법령을 어기지 않는지와 기준가격이 제대로 산정됐는지 확인하는 감시자 역할을 해요.","w":[null,"투자회사의 주식 발행·명의개서·재산 계산 같은 사무는 일반사무관리회사가 대행해요.","투자회사 이사회는 법인이사(집합투자업자) 1명과 감독이사 2명 이상으로 꾸려요.","투자신탁은 계약일 뿐이라 법인격이 없고, 투자자는 수익증권을 받는 수익자예요. 법인격이 있어 투자자가 주주가 되는 것은 투자회사예요."],"k":"투자신탁에서 신탁업자는 금고지기 겸 감시자예요. 투자회사는 껍데기 회사라 서류 업무는 일반사무관리회사가 대신해요.","m":"신탁업자 = 보관·감시 · 일반사무관리회사 = 투자회사 사무 대행 · 투자회사 이사회 = 법인이사 1명 + 감독이사 2명 이상","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"연금저축계좌의 수령·이체·승계","q":"연금저축계좌를 설명한 〈보기〉에서 맞는 것을 빠짐없이 고르면?\nㄱ. 연금으로 받으려면 만 55세 이후, 가입일부터 5년이 지난 뒤 연금수령한도 안에서 인출해야 한다.\nㄴ. 연말정산 때 공제받는 납입 한도는 연금저축만으로는 연 600만원, IRP와 합치면 연 900만원까지이다.\nㄷ. 만 55세 이상이고 가입 후 5년이 지난 가입자는 연금저축 적립금을 개인형 퇴직연금(IRP)으로 옮길 수 있다.\nㄹ. 가입자가 사망하면 배우자뿐 아니라 자녀도 계좌를 그대로 이어받아 연금으로 받을 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":1,"c":"연금저축계좌는 가입 자격 제한이 없고, IRP와 합쳐 연 1,800만원까지 넣을 수 있어요. 연금수령 요건을 지키면 낮은 연금소득세율이 적용돼요. 계좌를 이어받는 승계는 배우자만 할 수 있어요.","e":"ㄱ은 연금수령 요건, ㄴ은 세액공제 한도, ㄷ은 연금저축에서 IRP로 옮기는 이체 요건을 바르게 설명했어요.","w":["ㄷ도 옳아요. 만 55세 이상·가입 5년 경과 요건을 갖추면 연금저축 적립금을 IRP로 옮길 수 있어요.",null,"ㄹ은 틀렸어요. 연금계좌 승계는 배우자만 가능하고, 가입자가 숨진 달의 마지막 날부터 6개월 안에 신청해야 해요. ㄱ도 옳은 설명이에요.","ㄹ은 틀렸어요. 자녀는 연금계좌를 승계할 수 없어요."],"k":"연금저축은 '노후용 금고'라서 55세·5년이라는 열쇠가 있어야 연금으로 열 수 있고, 주인이 떠나면 배우자만 금고를 물려받아요.","m":"연금수령: 55세·5년·한도 내 · 세액공제 600(IRP 합산 900) · 납입 1,800 · 55세·5년이면 IRP로 이체 · 승계는 배우자만(6개월 내)","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"중","t":"종류형·전환형 펀드와 환매수수료","q":"종류형 집합투자기구와 전환형 집합투자기구를 설명한 〈보기〉에서 맞는 것을 빠짐없이 고르면?\nㄱ. 종류형 펀드에서 클래스별로 차이를 둘 수 있는 항목은 판매보수와 판매수수료, 환매수수료로 한정된다.\nㄴ. 전환형 세트에 속한 다른 펀드로 갈아탈 때는 환매수수료를 떼지 않는다.\nㄷ. 투자자가 낸 환매수수료는 판매회사의 수입이 된다.\nㄹ. 특정 클래스 투자자에게만 관련된 안건은 그 클래스 투자자끼리만 따로 총회(종류집합투자자총회)를 열어 결의할 수 있다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":2,"c":"종류형은 한 펀드를 판매 비용 구조만 다른 여러 클래스로 나눈 것이에요. 운용보수 같은 나머지 비용은 클래스와 관계없이 같아요. A클래스는 선취수수료를 내는 대신 판매보수가 낮아 장기 투자에, C클래스는 선취수수료가 없고 판매보수가 높아 단기 투자에 맞고, e클래스는 온라인 전용이에요. 전환형은 법적 형태가 같은 여러 펀드를 한 세트로 묶어 투자자에게 갈아탈 권리(전환권)를 주는 구조예요.","e":"ㄱ·ㄴ·ㄹ이 옳아요. 환매수수료는 정해진 기간 안에 환매할 때만 물리는 단기 환매 억제 장치라, 받은 돈을 펀드 재산에 다시 넣어 남은 투자자에게 돌려줘요.","w":["ㄹ도 옳아요. 특정 클래스에만 해당하는 안건은 그 클래스 투자자만으로 총회를 열 수 있어요.","ㄷ은 틀렸어요. 환매수수료는 판매회사가 아니라 펀드 재산에 들어가요. ㄱ·ㄴ도 옳은 설명이에요.",null,"ㄷ은 틀렸어요. 환매수수료는 펀드 재산에 들어가요."],"k":"같은 기차라도 일반석·특실처럼 표값(판매 비용)만 다르고 달리는 기관차(운용)는 하나예요. 환매수수료는 일찍 내리는 사람이 남는 승객에게 주는 위로금이에요.","m":"종류형 차등 가능 = 판매보수, 판매수수료, 환매수수료 · A(선취·저보수, 장기) / C(수수료 없음·고보수, 단기) / e(온라인) · 전환형 = 전환권, 전환 시 환매수수료 X · 환매수수료 → 펀드 재산","rev":0},{"s":1,"sec":"금융상품","star":1,"lv":"하","t":"금융기관의 분류","q":"한국은행의 금융기관 분류상 '비은행 예금취급기관'에 해당하는 것끼리만 묶은 것은?","o":["상호저축은행, 우체국예금","한국수출입은행, 신용협동조합","지방은행, 새마을금고","신용카드회사, 종합금융회사"],"a":0,"c":"금융기관은 은행(일반은행·특수은행), 비은행 예금취급기관, 금융투자업자, 보험회사, 기타 금융기관 등으로 나눠요. 비은행 예금취급기관은 은행은 아니지만 예금을 받는 곳으로 상호저축은행, 신용협동기구(신협·새마을금고·상호금융), 우체국예금, 종합금융회사가 있어요.","e":"상호저축은행과 우체국예금은 둘 다 예금을 받지만 은행은 아닌 비은행 예금취급기관이에요.","w":[null,"한국수출입은행은 개별 법으로 세운 특수은행이에요. 신용협동조합만 비은행 예금취급기관이에요.","지방은행은 일반은행에 속해요(시중은행과 같은 그룹). 새마을금고만 비은행 예금취급기관이에요.","신용카드회사는 예금을 받지 않는 여신전문금융회사예요. 종합금융회사만 비은행 예금취급기관이에요."],"k":"'예금을 받는가'와 '은행인가' 두 가지로 가르면 돼요. 예금은 받지만 은행이 아니면 비은행 예금취급기관이에요.","m":"일반은행 = 시중·지방·외은지점 · 특수은행 = 산업·수출입·기업·농협·수협 · 비은행 예금취급 = 저축은행·신협·새마을금고·우체국예금·종금 · 여전사 = 예금 X","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"보험약관 해석과 보험가입금액 자동복원","q":"보험계약을 설명한 〈보기〉에서 맞는 것만 묶은 것은?\nㄱ. 약관 조항의 뜻이 여러 가지로 읽힐 수 있으면 약관을 만든 보험회사에 불리하게 해석한다.\nㄴ. 보험회사와 계약자가 약관과 다른 내용을 따로 합의했더라도 약관 내용이 먼저 적용된다.\nㄷ. 보험가입금액 1억원인 장기손해보험에서 한 번의 사고로 보험금 7,000만원을 받았다면 보험가입금액은 1억원으로 자동복원된다.\nㄹ. ㄷ의 계약에서 한 번의 사고로 보험금 9,000만원을 받았더라도 보험가입금액은 1억원으로 자동복원된다.","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":0,"c":"약관은 보험회사가 미리 만든 계약서라서, 뜻이 애매하면 작성자인 보험회사에 불리하게 풀이하고(작성자 불이익 원칙), 따로 합의한 내용이 있으면 그것이 약관보다 우선해요(개별약정 우선). 장기손해보험은 한 번의 사고로 나간 보험금이 가입금액의 80%에 못 미치면 가입금액이 줄지 않고 그대로 복원돼요.","e":"ㄱ은 작성자 불이익 원칙이에요. ㄷ은 7,000만 ÷ 1억 = 70%로 80% 미만이라 자동복원돼요.","w":[null,"ㄹ은 틀렸어요. 9,000만 ÷ 1억 = 90%로 80% 이상이라 자동복원되지 않아요.","ㄴ은 틀렸어요. 따로 합의한 내용이 약관보다 우선해요.","ㄴ·ㄹ 모두 틀렸어요."],"k":"애매한 계약서는 쓴 사람이 책임져요. 그리고 작은 사고 한 번으로는 보장 그릇이 줄지 않지만, 거의 다 쓸 만큼 큰 사고가 나면 그릇이 다시 채워지지 않아요.","m":"약관: 작성자 불이익 · 개별약정 우선 / 장기손해보험: 1회 보험금 < 가입금액의 80% → 자동복원","f":"7,000만 ÷ 1억 = 70% < 80% → 자동복원 / 9,000만 ÷ 1억 = 90% ≥ 80% → 자동복원 X","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"MBS·CBO의 특성과 ABS 신용등급","q":"유동화증권을 설명한 내용 중 틀린 것은?","o":["주택저당대출은 차주 신용평가와 담보 감정 같은 사무가 많아 노동집약적인 상품으로 분류된다","MBS는 조기상환 때문에 현금흐름이 불확실해 국채보다 높은 수익률로 발행되는 편이다","CBO는 여러 회사채를 모아 그 현금흐름을 바탕으로 발행하는 CDO의 한 종류이다","ABS의 신용등급은 자산을 넘긴 자산보유자의 신용등급을 그대로 따른다"],"a":3,"c":"ABS는 자산보유자와 절연된 기초자산의 현금흐름으로 갚는 증권이에요. 그래서 등급도 바구니에 담긴 자산의 신용과 보강 장치의 정도로 매기고, 선·후순위마다 등급이 달라요. CDO는 회사채나 대출을 모아 발행하는데, 회사채를 모으면 CBO, 대출을 모으면 CLO예요.","e":"ABS 신용등급은 자산보유자 등급과 분리해 기초자산의 질과 신용보강 정도로 정해요. 그래서 자산보유자보다 높은 등급을 받을 수도 있어요.","w":["저당대출은 심사·감정·관리 사무가 많아 노동집약적이에요.","MBS는 만기가 길고 조기상환 위험이 있어 국채나 우량 회사채보다 금리를 높게 쳐 줘요.","CBO는 회사채를, CLO는 대출채권을 기초로 한 CDO예요.",null],"k":"ABS는 '회사 얼굴'이 아니라 '바구니 속 과일 품질'로 값을 매겨요. 과일이 좋고 포장(신용보강)이 튼튼하면 회사보다 등급이 높을 수도 있어요.","m":"ABS 등급 = 기초자산 신용도 + 신용보강(자산보유자 등급과 분리) · MBS: 장기·조기상환위험·국채보다 고수익 · CBO = 회사채 CDO, CLO = 대출 CDO","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"IRP 추가납입과 기업형 IRP","q":"IRP(개인형 퇴직연금)를 설명한 내용 중 틀린 것은?","o":["이직하면서 받은 퇴직급여를 IRP로 옮기면 퇴직소득세를 바로 내지 않고 계속 운용할 수 있다","확정급여형(DB)에 가입한 근로자도 IRP를 따로 열어 자기 돈을 추가로 납입할 수 있다","상시근로자 10명 미만 사업장은 근로자 동의를 받아 근로자별로 IRP를 설정하는 기업형 IRP로 퇴직급여제도를 갈음할 수 있다","계좌에 돈이 충분하면 법에서 정한 사유가 없어도 원하는 만큼 일부만 중도인출할 수 있다"],"a":3,"c":"IRP는 퇴직급여를 모아 두거나 본인이 추가로 넣어 노후 자금을 쌓는 계좌예요. DB·DC 가입 근로자와 자영업자 등 소득이 있는 사람이 가입할 수 있고, 연금저축과 합쳐 세액공제를 받아요.","e":"IRP 중도인출은 무주택자의 주택 구입, 6개월 이상 요양 같은 법정 사유가 있을 때만 가능해요. 사유가 없으면 일부만 빼는 것은 안 되고 계좌를 해지해야 해요.","w":["퇴직급여를 IRP로 옮기면 과세가 미뤄져요(과세이연).","IRP 추가납입은 DC형뿐 아니라 DB형 가입자도 할 수 있어요. 자영업자도 가입할 수 있어요.","10명 미만 사업장 특례인 기업형 IRP예요.",null],"k":"IRP는 '퇴직금 저금통'이라 깨려면 정해진 이유가 있어야 하고, 이유 없이 조금만 빼 쓰는 건 안 돼요.","m":"IRP: 퇴직급여 이전·과세이연 · DB·DC·자영업자 모두 추가납입 가능 · 10명 미만 = 기업형 IRP · 중도인출은 법정 사유만","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"중","t":"DB형·DC형의 운용위험과 연금계리","q":"퇴직연금 DB형(확정급여)과 DC형(확정기여)을 비교해 바르게 설명한 것은?","o":["DC형도 근로자가 받을 퇴직급여를 미리 계산해야 하므로 연금계리가 필요하다","DB형은 받을 퇴직급여가 미리 정해져 있어 운용 위험을 회사가 지며, 적립금이 법에서 정한 최소적립금 이상이 되도록 관리해야 한다","DC형은 적립금 운용 결과에 대한 책임을 회사가 진다","DB형은 근로자가 직접 운용 상품을 골라 그 결과에 따라 퇴직급여가 달라진다"],"a":1,"c":"DB형은 '받을 돈'이, DC형은 '회사가 낼 돈'이 정해져 있어요. DB형은 미래 급여를 맞추려고 연금계리와 최소적립 의무가 따르고, DC형은 회사가 부담금만 내면 되므로 연금계리가 필요 없어요.","e":"DB형은 퇴직급여가 확정돼 있어 운용 결과가 나빠도 회사가 부족분을 채워야 해요. 그래서 적립금을 최소적립금 이상으로 쌓아 두게 해요.","w":["DC형은 회사 부담금이 정해져 있고 급여는 운용 결과에 따라 달라져서, 미래 급여를 추정하는 연금계리가 필요 없어요.",null,"DC형은 근로자가 운용하고 그 결과도 근로자가 져요.","DC형의 설명이에요. DB형은 회사가 운용해요."],"k":"DB형은 '정해진 퇴직금 약속', DC형은 '매년 정해진 돈만 넣어 주고 불리는 건 각자 알아서'인 셈이에요.","m":"DB = 급여 확정 · 회사 운용위험 · 연금계리·최소적립 의무 / DC = 부담금 확정 · 근로자 운용위험 · 연금계리 X","rev":0},{"s":1,"sec":"금융상품","star":3,"lv":"상","t":"환매금지형 의무 설정과 집합투자증권 발행","q":"집합투자기구의 설정과 집합투자증권 발행을 설명한 내용 중 틀린 것은?","o":["시장에서 쉽게 팔 수 없는 자산을 펀드 재산의 20% 넘게 담으려면 처음부터 환매금지형으로 만들어야 한다","환매금지형 펀드라도 운용사가 돈을 더 모아야겠다고 판단하면 그것만으로 언제든 지분을 추가 발행할 수 있다","투자신탁 수익증권에는 액면금액을 적지 않고, 투자자 이름을 적는 방식으로 발행한다","투자회사가 설립된 뒤 신주를 발행할 때는 이사회가 결의한다"],"a":1,"c":"환매금지형은 중간에 환매할 수 없는 펀드라 존속기간을 정한 경우에만 만들 수 있고, 공모형은 최초 발행일부터 90일 이내에 상장해 투자자가 시장에서 팔 수 있게 해요. 추가 발행은 기존 투자자를 해치지 않는 경우로 제한해요.","e":"환매금지형은 이익분배금 범위 안에서 발행하거나, 기존 투자자 이익을 해칠 염려가 없다고 신탁업자가 확인하거나, 기존 투자자 전원이 동의하거나, 기존 투자자에게 보유 비율대로 우선 매수 기회를 줄 때 등에만 추가 발행할 수 있어요. 운용사 판단만으로는 안 돼요.","w":["부동산처럼 현금화가 어려운 자산 위주이거나 시장성 없는 자산 비중이 20%를 넘으면 환매금지형이어야 해요.",null,"수익증권은 무액면·기명식이고, 맡긴 돈이 모두 들어온 것을 신탁업자가 확인한 뒤에 발행해요.","투자회사 신주 발행은 주주총회가 아니라 이사회가 결의해요."],"k":"중간에 내릴 수 없는 버스(환매금지형)에 새 승객을 마음대로 태우면 기존 승객 몫이 줄어요. 그래서 기존 승객이 손해 보지 않는 경우에만 태워요.","m":"환매금지형: 존속기간 필수 · 시장성 없는 자산 20% 초과 시 의무 · 공모 90일 내 상장 · 추가발행 제한 / 수익증권 = 무액면·기명 / 투자회사 신주 = 이사회","rev":0},{"s":1,"sec":"금융상품","star":2,"lv":"중","t":"ISA와 비과세종합저축의 가입 요건","q":"2026년 현재 절세형 금융상품을 설명한 〈보기〉에서 맞는 것을 빠짐없이 고르면?\nㄱ. ISA(개인종합자산관리계좌)는 모든 금융회사를 통틀어 한 사람이 하나의 계좌만 가질 수 있다.\nㄴ. ISA의 비과세 한도는 일반형 200만원, 서민형·농어민형 400만원이다.\nㄷ. 2026년에 비과세종합저축에 새로 가입하려는 65세 이상 거주자는 기초연금 수급자여야 한다.\nㄹ. 비과세종합저축은 한 사람당 저축원금 1억원까지 가입할 수 있다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":2,"c":"ISA는 만 19세 이상(직전 연도 근로소득이 있으면 만 15세 이상) 거주자가 1인 1계좌로 가입하고, 비과세 한도를 넘는 순이익은 9.9%로 분리과세해요. 비과세종합저축은 65세 이상 기초연금 수급자, 장애인, 기초생활수급자 등이 가입할 수 있고, 직전 3년 중 금융소득종합과세 대상이었던 사람은 가입할 수 없어요.","e":"ㄱ·ㄴ·ㄷ이 옳아요. 비과세종합저축 한도는 전 금융기관 합산 1인당 원금 5,000만원이에요.","w":["ㄷ도 옳아요. 2026년부터 65세 이상은 기초연금 수급자만 새로 가입할 수 있어요.","ㄹ은 틀렸어요. 한도는 1억원이 아니라 5,000만원이에요. ㄱ·ㄴ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 비과세종합저축 한도는 1인당 원금 5,000만원이에요."],"k":"ISA는 '한 사람 한 통장'인 절세 바구니이고, 비과세종합저축은 형편이 어려운 어르신·장애인 등을 위한 이자 면세 통장이에요.","m":"ISA: 1인 1계좌 · 비과세 200만(서민·농어민 400만) · 초과분 9.9% / 비과세종합저축: 65세 이상은 기초연금 수급자(2026~) · 장애인 등 · 1인 원금 5,000만","rev":0},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"용도지역별 용적률","q":"국토계획법상 용도지역별 최대 용적률이 높은 것부터 바르게 나열한 것은?","o":["중심상업지역 > 일반상업지역 > 준주거지역 > 제3종 일반주거지역","일반상업지역 > 중심상업지역 > 준주거지역 > 제3종 일반주거지역","중심상업지역 > 준주거지역 > 일반상업지역 > 제3종 일반주거지역","중심상업지역 > 일반상업지역 > 제3종 일반주거지역 > 준주거지역"],"a":0,"c":"용적률은 대지 면적 대비 건물 연면적 비율이에요. 도심일수록 높게, 주거지일수록 낮게 정해요.","e":"최대 용적률은 중심상업(1,500%) > 일반상업(1,300%) > 준주거(500%) > 제3종 일반주거(300%) 순이에요.","w":[null,"중심상업지역이 일반상업지역보다 높아요.","일반상업지역이 준주거지역보다 높아요.","준주거지역이 제3종 일반주거지역보다 높아요."],"k":"도심 한가운데(중심상업)일수록 건물을 높게 지을 수 있어요.","m":"중심상업 1,500 > 일반상업 1,300 > 준주거 500 > 3종주거 300"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"하","rev":0,"t":"용익물권과 담보물권","q":"민법상 용익물권에 해당하지 않는 것은?","o":["지상권","저당권","지역권","전세권"],"a":1,"c":"제한물권은 남의 물건을 \"쓰는\" 용익물권과, 돈을 받기 위해 \"담보로 잡는\" 담보물권으로 나뉘어요.","e":"저당권은 채권 회수를 위한 담보물권이에요. 지상권·지역권·전세권이 용익물권이에요.","w":["지상권은 남의 땅에 건물 등을 소유하려고 쓰는 권리예요.",null,"지역권은 내 땅의 편의를 위해 남의 땅을 쓰는 권리예요.","전세권은 남의 부동산을 쓰고 수익하는 권리예요."],"k":"\"쓰는 권리\"는 용익(지상·지역·전세), \"돈 받으려 잡아 두는 권리\"는 담보(유치·질·저당)예요.","m":"용익 = 지상·지역·전세 / 담보 = 유치·질·저당"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"거래사례비교법","q":"부동산 감정평가 방법 가운데 거래사례비교법에 관한 설명으로 가장 거리가 먼 것은?","o":["비슷한 부동산의 실제 거래 가격을 기준으로 가치를 구한다","사정보정, 시점수정, 지역요인·개별요인 비교 과정을 거친다","비교할 만한 거래 사례가 거의 없는 부동산에는 적용하기 어렵다","부동산이 앞으로 벌어들일 순수익을 환원이율로 나누어 가치를 구한다"],"a":3,"c":"감정평가 3방식은 원가방식(복성식), 비교방식(거래사례비교법), 수익방식(수익환원법)이에요.","e":"순수익을 환원이율로 나누는 것은 수익환원법이에요. 거래사례비교법은 시장에서 실제 거래된 비슷한 사례와 비교해요.","w":["실제 거래 사례가 기준이에요.","사정보정·시점수정·요인 비교를 해요.","사례가 없으면 쓰기 어려운 것이 한계예요.",null],"k":"\"옆집이 얼마에 팔렸지?\"를 보고 조건 차이를 보정해서 값을 매기는 방법이에요.","m":"비교방식 = 거래사례 · 수익방식 = 순수익 ÷ 환원이율 · 원가방식 = 재조달원가"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"수익가치 계산","q":"어느 상가의 연간 총수익이 500억원, 연간 운영경비가 200억원이고 환원이율이 6%일 때, 직접환원법으로 구한 수익가치로 가장 적절한 것은?","o":["3,333억원","5,000억원","8,333억원","18억원"],"a":1,"c":"직접환원법은 1년 동안의 순영업소득을 환원이율로 나눠 부동산 가치를 구해요.","e":"순영업소득 = 500 − 200 = 300억원, 수익가치 = 300 ÷ 0.06 = 5,000억원이에요.","w":["운영경비(200억원)를 순영업소득처럼 환원이율로 나눴어요(200 ÷ 0.06 ≈ 3,333억원).",null,"운영경비를 빼지 않고 총수익을 그대로 나눴어요(500 ÷ 0.06 ≈ 8,333억원).","순영업소득을 환원이율로 나누지 않고 곱했어요(300 × 0.06 = 18억원)."],"k":"해마다 300억씩 남는 상가를 6% 수익률로 산다면, 5,000억까지 낼 만하다는 뜻이에요.","m":"수익가치 = (총수익 − 운영경비) ÷ 환원이율","f":"(500 − 200) ÷ 0.06 = 5,000억원"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"리츠(REITs)의 유형","q":"부동산투자회사(리츠)에 관한 설명으로 가장 적절하지 않은 것은?","o":["위탁관리 리츠는 자산운용을 자산관리회사(AMC)에 맡긴다","위탁관리 리츠는 상근 임직원을 두고 자산을 직접 운용해야 한다","기업구조조정 리츠는 기업이 구조조정으로 내놓은 부동산에 주로 투자한다","자기관리 리츠는 상근 임직원을 두고 자산을 직접 운용하는 실체회사이다"],"a":1,"c":"리츠는 운용 방식에 따라 자기관리 리츠(직접 운용)와 위탁관리 리츠·기업구조조정 리츠(외부 위탁)로 나뉘어요.","e":"위탁관리 리츠는 상근 임직원이 없는 명목회사(서류상 회사)이고, 자산운용은 자산관리회사에 맡겨요.","w":["위탁관리 리츠는 AMC에 운용을 맡겨요.",null,"기업구조조정 리츠의 투자 대상이 맞아요.","자기관리 리츠는 실체회사예요."],"k":"자기관리 리츠는 \"직원이 있는 진짜 회사\", 위탁관리 리츠는 \"이름만 있는 회사 + 외부 운용사\"예요.","m":"자기관리 = 실체회사 / 위탁관리·CR = 명목회사 + AMC"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"지주공동사업의 등가교환방식","q":"〈보기〉에서 설명하는 부동산 개발 방식으로 가장 적절한 것은?\n〈보기〉 토지 소유자는 토지를 내놓고 개발업자는 건축비를 부담해 건물을 짓는다. 완공 후 각자 투자한 비율에 따라 토지와 건물을 나누어 갖는다.","o":["등가교환방식","사업수탁방식","토지신탁방식","차지(借地)방식"],"a":0,"c":"지주공동사업은 땅 주인이 다른 사업자와 함께 개발하는 방식이에요. 누가 무엇을 내고 결과를 어떻게 나누는지로 구분해요.","e":"토지와 건축비를 각각 내고, 완공 후 투자 비율대로 토지·건물을 나눠 갖는 것은 등가교환방식이에요.","w":[null,"사업수탁방식은 개발업자가 사업을 대행하고 땅 주인이 소유권을 유지하며 수수료를 줘요.","토지신탁방식은 신탁회사에 토지를 맡겨 개발하고 수익을 배당받아요.","차지방식은 토지를 빌려주고 지대를 받는 방식이에요."],"k":"\"내 땅 + 네 건축비 = 완성되면 비율대로 나눠 갖기\"가 등가교환이에요.","m":"등가교환 = 비율대로 나눔 · 사업수탁 = 대행 · 토지신탁 = 신탁사 개발"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"상","rev":0,"t":"부동산 투자의 레버리지 효과","q":"〈보기〉의 부동산 투자에서 자기자본수익률로 가장 적절한 것은? (세금은 고려하지 않는다)\n• 부동산 매입가격: 10억원(자기자본 4억원, 차입금 6억원)\n• 차입 이자율: 연 5%\n• 연간 순영업소득: 8,000만원","o":["8.0%","12.5%","20.0%","5.0%"],"a":1,"c":"빌린 돈의 이자율이 부동산 수익률보다 낮으면, 빌린 돈이 자기자본수익률을 끌어올려요(정의 레버리지).","e":"이자 = 6억 × 5% = 3,000만원, 자기자본 몫 이익 = 8,000만 − 3,000만 = 5,000만원, 자기자본수익률 = 5,000만 ÷ 4억 = 12.5%예요.","w":["전체 투자수익률(8,000만 ÷ 10억)이에요.",null,"이자를 빼지 않고 자기자본으로 나눴어요.","차입 이자율을 그대로 골랐어요."],"k":"5%에 빌려서 8%를 버는 곳에 넣으면, 남는 3%p가 내 몫으로 쌓여 내 돈 수익률이 올라가요.","m":"자기자본수익률 = (순영업소득 − 이자) ÷ 자기자본","f":"(8,000만 − 6억 × 5%) ÷ 4억 = 12.5%"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"상","rev":0,"t":"건폐율과 용적률 계산","q":"대지면적 500㎡, 건폐율 60%, 용적률 300%가 적용되는 토지에 각 층 바닥면적이 같은 건물을 최대 건축면적으로 지을 때, 지을 수 있는 최대 지상 층수는?","o":["8층","6층","5층","3층"],"a":2,"c":"건폐율은 대지 중 건물이 덮는 면적 비율, 용적률은 대지 대비 지상층 연면적 비율이에요.","e":"최대 건축면적 = 500 × 60% = 300㎡, 최대 연면적 = 500 × 300% = 1,500㎡, 층수 = 1,500 ÷ 300 = 5층이에요.","w":["계산이 맞지 않아요.","건폐율과 용적률을 단순 비교한 값이 아니에요.",null,"용적률 300%를 그대로 3층으로 봤어요."],"k":"바닥 300㎡짜리 층을 연면적 1,500㎡까지 쌓으면 5층이에요.","m":"건폐율 = 건축면적 ÷ 대지 · 용적률 = 지상 연면적 ÷ 대지","f":"1,500 ÷ 300 = 5층"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"상업지역의 세분","q":"국토계획법 시행령상 상업지역의 세분에 해당하지 않는 것은?","o":["중심상업지역","일반상업지역","근린상업지역","준상업지역"],"a":3,"c":"도시지역 안의 상업지역은 기능에 따라 네 가지로 나눠요.","e":"상업지역은 중심상업, 일반상업, 근린상업, 유통상업지역으로 나뉘어요. 준상업지역은 없어요(\"준\"은 준주거·준공업지역에 붙어요).","w":["해당해요.","해당해요.","해당해요.",null],"k":"상업지역 = \"중심·일반·근린·유통\"이에요.","m":"상업지역 = 중심 · 일반 · 근린 · 유통 / 준주거 · 준공업은 있음"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"지상권과 지역권","q":"타인의 토지에 건물이나 공작물, 수목을 소유하기 위해 그 토지를 사용하는 물권은?","o":["지상권","지역권","전세권","저당권"],"a":0,"c":"용익물권은 남의 부동산을 쓰는 권리로, 목적에 따라 지상권·지역권·전세권으로 나뉘어요.","e":"남의 땅 위에 건물·공작물·수목을 소유하려고 토지를 쓰는 권리는 지상권이에요. 지역권은 내 땅의 편익(통행 등)을 위해 남의 땅을 이용하는 권리예요.","w":[null,"자기 토지의 편익을 위해 남의 토지를 이용하는 권리예요.","전세금을 내고 부동산을 사용·수익하는 권리예요.","담보물권이에요."],"k":"남의 땅 \"위에(地上)\" 내 건물을 두는 권리예요.","m":"지상권 = 건물·공작물·수목 소유 목적 · 지역권 = 편익(통행 등) 목적"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"물권과 채권","q":"물권과 채권을 비교한 설명으로 가장 적절한 것은?","o":["물권은 모든 사람에게 주장할 수 있는 배타적 권리이고, 채권은 특정인에게만 주장할 수 있다","채권은 물권보다 항상 우선한다","임차권은 원칙적으로 물권이다","물권은 당사자가 자유롭게 새로 만들 수 있다"],"a":0,"c":"물권은 물건을 직접 지배하는 권리, 채권은 특정인에게 행위를 요구하는 권리예요.","e":"물권은 누구에게나 주장할 수 있는 대세적·배타적 권리이고, 원칙적으로 채권보다 우선해요. 물권은 법률로만 정할 수 있어요(물권법정주의).","w":[null,"물권이 원칙적으로 우선해요.","임차권은 채권이에요.","물권법정주의로 법률로만 정해요."],"k":"물권은 \"세상 모두에게\", 채권은 \"그 사람에게만\" 주장해요.","m":"물권 = 대세적·배타적·우선 · 물권법정주의 / 채권 = 상대적"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"전세권의 성격","q":"전세권에 관한 설명으로 가장 적절한 것은?","o":["용익물권이면서 전세금 반환을 위한 담보물권의 성격도 함께 가진다","등기 없이도 성립하는 채권이다","임차권과 법적 성격이 완전히 같다","전세권자는 경매를 청구할 수 없다"],"a":0,"c":"민법상 전세권은 주택임대차의 \"전세\"와는 다른 등기된 물권이에요.","e":"전세권은 남의 부동산을 사용·수익하는 용익물권이면서, 전세금을 돌려받지 못하면 경매를 청구하고 우선변제받을 수 있는 담보물권의 성격도 있어요.","w":[null,"등기해야 하는 물권이에요.","임차권은 채권이에요.","경매를 청구할 수 있어요."],"k":"쓰는 권리 + 보증금 지키는 권리, 둘 다예요.","m":"전세권 = 용익물권 + 담보물권 성격(경매청구·우선변제)"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"감정평가 3방식","q":"감정평가 방식과 그로 구한 가액의 연결이 가장 적절하지 않은 것은?","o":["거래사례비교법 – 비준가액","원가법 – 적산가액","임대사례비교법 – 적산임료","수익환원법 – 수익가액"],"a":2,"c":"감정평가는 원가·비교·수익 방식으로 가격과 임료를 구해요.","e":"임대사례비교법으로 구한 임료는 비준임료예요. 적산임료는 적산법으로 구해요.","w":["맞아요.","맞아요.",null,"맞아요."],"k":"\"비교\"로 구하면 이름에 \"비준\"이 붙어요.","m":"원가: 원가법(적산가액)·적산법(적산임료) / 비교: 거래사례(비준가액)·임대사례(비준임료) / 수익: 수익환원법(수익가액)·수익분석법(수익임료)"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"상","rev":0,"t":"순영업소득 계산","q":"〈보기〉 임대 건물의 순영업소득(NOI)은?\n• 가능총소득: 10억원\n• 공실 및 대손: 가능총소득의 10%\n• 운영경비: 2억원\n• 대출 이자: 1억원","o":["6억원","7억원","8억원","9억원"],"a":1,"c":"NOI는 운영으로 버는 순소득이에요. 대출 이자 같은 금융비용은 빼지 않아요.","e":"유효총소득 = 10 − 1 = 9억원, NOI = 9 − 2 = 7억원이에요. 대출 이자는 NOI 계산에 넣지 않아요.","w":["대출 이자까지 뺐어요. 이자는 NOI 계산에 넣지 않아요.",null,"공실·대손을 빼지 않고 운영경비만 뺐어요(10 − 2 = 8억원).","공실·대손만 빼고 운영경비를 빼지 않았어요(10 − 1 = 9억원)."],"k":"받을 수 있는 돈 − 공실 − 관리비 = NOI예요. 대출은 별개예요.","m":"NOI = 가능총소득 − 공실·대손 − 운영경비 (이자·감가상각 제외)","f":"10 − 1 − 2 = 7억원"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"정(+)의 레버리지 조건","q":"부동산 투자에서 차입을 늘릴수록 자기자본수익률이 높아지는 정(+)의 레버리지가 나타나는 조건은?","o":["총자본수익률이 차입 이자율보다 높을 때","총자본수익률이 차입 이자율보다 낮을 때","총자본수익률과 차입 이자율이 같을 때","차입 이자율과 관계없이 항상"],"a":0,"c":"빌린 돈으로 번 수익이 이자보다 크면 그 차이가 내 몫이 돼요.","e":"총자본수익률 > 차입 이자율이면 정(+)의 레버리지, 작으면 부(−)의 레버리지, 같으면 중립이에요.","w":[null,"부(−)의 레버리지예요.","중립 레버리지예요.","조건이 있어요."],"k":"이자 5%로 빌려서 7% 벌면 남는 장사예요.","m":"총자본수익률 > 이자율 → 정(+) · < → 부(−) · = → 중립"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"상","rev":0,"t":"수익성지수 계산","q":"초기 투자액 50억원인 부동산 개발사업의 미래 현금흐름 현재가치 합이 60억원일 때 수익성지수(PI)와 순현재가치(NPV)로 옳은 것은?","o":["PI 10, NPV 1.2억원","PI 1.2, NPV 60억원","PI 1.2, NPV 10억원","PI 0.83, NPV −10억원"],"a":2,"c":"수익성지수는 현금흐름 현재가치를 초기 투자액으로 나눈 값이에요.","e":"PI = 60 ÷ 50 = 1.2, NPV = 60 − 50 = 10억원이에요. PI > 1이면 NPV > 0이라 투자 가치가 있어요.","w":["두 값을 뒤섞었어요.","NPV에서 투자액을 빼지 않았어요.",null,"분자·분모를 바꿨어요."],"k":"50억을 넣어 지금 가치로 60억을 돌려받으니 1.2배예요.","m":"PI = PV(CF) ÷ 초기투자 · NPV = PV(CF) − 초기투자 · PI > 1 ⇔ NPV > 0","f":"60 ÷ 50 = 1.2"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"LTV와 DTI","q":"담보인정비율(LTV)과 총부채상환비율(DTI)에 관한 설명으로 가장 적절한 것은?","o":["LTV는 주택 가치 대비 대출금 비율이고, DTI는 소득 대비 연간 부채 상환액 비율이다","LTV는 소득 대비 대출 비율이다","DTI는 주택 가격 대비 대출 비율이다","둘 다 임대 수익을 기준으로 한다"],"a":0,"c":"대출 규제는 담보 가치와 상환 능력 두 측면에서 이루어져요.","e":"LTV = 대출금 ÷ 담보 가치, DTI = 연간 원리금(주담대) 및 기타 이자 상환액 ÷ 연소득이에요.","w":[null,"DTI의 개념에 가까워요.","LTV의 개념이에요.","담보 가치와 소득을 기준으로 해요."],"k":"LTV는 \"집값 대비\", DTI는 \"소득 대비\"예요.","m":"LTV = 대출 ÷ 담보가치 · DTI = 연 상환액 ÷ 연소득"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"리츠의 주식 분산 요건","q":"부동산투자회사법상 리츠의 주주 1인과 그 특별관계자가 보유할 수 있는 주식 한도로 가장 적절한 것은?","o":["발행주식 총수의 50%를 초과해 소유할 수 없다","발행주식 총수의 10%를 초과해 소유할 수 없다","발행주식 총수의 90%까지 소유할 수 있다","소유 한도가 없다"],"a":0,"c":"리츠는 여러 투자자가 함께 부동산에 투자하는 회사라서, 한 사람이 회사를 독차지하지 못하게 주식 분산 요건을 둬요.","e":"주주 1인과 특별관계자는 리츠 발행주식 총수의 50%를 초과해 소유할 수 없어요. 기업구조조정 리츠 등 일부는 예외가 있어요.","w":[null,"한도가 더 높아요.","50%를 넘을 수 없어요.","분산 요건이 있어요."],"k":"한 사람이 절반 넘게 가질 수 없어요.","m":"리츠 1인 소유한도 = 발행주식 50% 초과 금지"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"리츠의 배당 의무","q":"위탁관리 리츠가 법인세를 감면받기 위한 배당 요건으로 가장 적절한 것은?","o":["배당가능이익의 90% 이상을 배당한다","배당가능이익의 50% 이상을 배당한다","배당 의무가 없다","배당가능이익의 30% 이상을 배당한다"],"a":0,"c":"리츠는 이익 대부분을 투자자에게 나눠 주는 구조예요.","e":"위탁관리·기업구조조정 리츠는 배당가능이익의 90% 이상을 배당하면 그 금액을 소득에서 공제받아 사실상 법인세를 내지 않아요.","w":[null,"기준이 더 높아요.","배당 의무가 있어요.","기준이 더 높아요."],"k":"번 돈 거의 다(90%) 나눠 줘요.","m":"리츠 배당 = 배당가능이익의 90% 이상"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"리츠의 자산 구성","q":"부동산투자회사(리츠)의 자산 구성 요건으로 가장 적절한 것은?","o":["총자산의 70% 이상을 부동산으로 구성해야 한다","총자산의 10% 이상만 부동산이면 된다","부동산에는 투자할 수 없다","자산 구성 요건이 없다"],"a":0,"c":"리츠는 부동산에 투자하는 회사라서 자산 대부분이 부동산이어야 해요.","e":"리츠는 총자산의 80% 이상을 부동산·부동산 관련 증권·현금으로, 그중 70% 이상을 부동산(건축 중인 건물 포함)으로 구성해야 해요.","w":[null,"기준이 훨씬 높아요.","부동산에 투자하는 회사예요.","요건이 있어요."],"k":"자산의 70% 이상이 진짜 부동산이에요.","m":"리츠 자산: 80% 이상 부동산 등 · 그중 70% 이상 부동산"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"리츠와 부동산펀드 비교","q":"리츠와 부동산 집합투자기구(부동산펀드)를 비교한 설명으로 가장 적절한 것은?","o":["리츠는 부동산투자회사법, 부동산펀드는 자본시장법의 적용을 받는다","두 상품 모두 부동산투자회사법만 적용받는다","리츠는 상장할 수 없다","부동산펀드는 주식회사 형태만 가능하다"],"a":0,"c":"리츠와 부동산펀드는 모두 부동산 간접투자 상품이지만 근거 법률이 달라요.","e":"리츠는 부동산투자회사법에 따른 주식회사이고, 부동산펀드는 자본시장법에 따른 집합투자기구예요. 리츠는 상장해 주식처럼 거래할 수 있어요.","w":[null,"근거 법률이 달라요.","상장할 수 있어요.","투자신탁 등 여러 형태가 있어요."],"k":"리츠 = 회사(부투법), 부동산펀드 = 펀드(자본시장법)예요.","m":"리츠 = 부동산투자회사법·주식회사 · 부동산펀드 = 자본시장법·집합투자기구"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"t":"프로젝트 파이낸싱","q":"부동산 프로젝트 파이낸싱(PF)에 관한 설명으로 가장 적절하지 않은 것은?","o":["사업에서 나올 미래 현금흐름을 상환 재원으로 한다","사업주의 다른 자산에 대한 상환청구가 제한되는 비소구 또는 제한소구 금융이다","사업주의 재무상태표에 부채로 나타나지 않는 부외금융 효과가 있다","사업주의 신용만으로 대출하므로 시공사의 신용보강이 필요 없다"],"a":3,"c":"PF는 기업이 아니라 \"사업\"을 보고 돈을 빌려주는 금융이에요.","e":"국내 부동산 PF는 사업 위험이 커서 시공사의 책임준공·채무인수·연대보증 같은 신용보강이 흔히 붙어요.","w":["사업 현금흐름이 상환 재원이에요.","비소구·제한소구가 특징이에요.","부외금융 효과가 있어요.",null],"k":"사업이 잘될지 불확실해서 시공사가 \"끝까지 짓겠다\"는 약속을 해 줘요.","m":"PF: 사업 현금흐름 · 비소구/제한소구 · 부외금융 · 시공사 신용보강"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"부동산 투자의 위험","q":"부동산 투자 위험 중 사업위험에 해당하지 않는 것은?","o":["임대 수요 감소에 따른 시장위험","관리 부실에 따른 운영위험","주변 환경 변화에 따른 위치적 위험","차입금이 많아 생기는 금융위험"],"a":3,"c":"부동산 투자 위험은 사업위험, 금융위험, 법적위험, 인플레이션위험, 유동성위험 등으로 나눠요.","e":"차입금이 많아 원리금 부담이 커지는 위험은 금융위험이에요. 시장·운영·위치적 위험이 사업위험이에요.","w":["사업위험이에요.","사업위험이에요.","사업위험이에요.",null],"k":"\"빚\" 때문에 생기는 위험은 금융위험이에요.","m":"사업위험(시장·운영·위치) · 금융위험 · 법적위험 · 인플레이션 · 유동성"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"부동산펀드의 유형","q":"부동산 개발사업의 시행사에 PF 대출을 해 주고 이자를 받는 부동산펀드는?","o":["대출형 부동산펀드","임대형 부동산펀드","경공매형 부동산펀드","개량형 부동산펀드"],"a":0,"c":"부동산펀드는 투자 방식에 따라 여러 유형으로 나눠요.","e":"개발 시행사에 PF 대출을 하고 대출 이자로 수익을 내는 것은 대출형 부동산펀드예요.","w":[null,"건물을 사서 임대료를 받아요.","경매·공매로 부동산을 싸게 사요.","부동산을 고쳐 가치를 높여요."],"k":"부동산을 사는 게 아니라 \"돈을 빌려줘서\" 이자를 받아요.","m":"대출형(PF 이자) · 임대형(임대료) · 경공매형 · 개량형 · 개발형"},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"t":"임대형 부동산펀드의 위험","q":"임대형 부동산펀드의 주요 위험으로 가장 적절하지 않은 것은?","o":["공실 증가에 따른 임대 수익 감소","임대료 하락","펀드 만기 시 매각 가격 하락","시공사 부도로 인한 준공 지연"],"a":3,"c":"임대형 펀드는 이미 지어진 건물을 사서 임대하는 구조예요.","e":"시공사 부도에 따른 준공 지연은 개발형이나 대출형(PF) 펀드의 주요 위험이에요. 임대형은 공실, 임대료, 매각 가격 위험이 중요해요.","w":["주요 위험이에요.","주요 위험이에요.","주요 위험이에요.",null],"k":"이미 지은 건물에는 \"공사\" 위험이 없어요.","m":"임대형 위험: 공실 · 임대료 · 매각가격 / 개발·대출형: 인허가 · 시공사 · 분양"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"상","t":"운영단계 세전현금흐름 계산","q":"다음 자료에 따른 임대용 부동산의 세전현금흐름은?\n· 가능총소득: 12억원\n· 공실 및 회수불능: 가능총소득의 5%\n· 주차장 등 기타소득: 0.4억원\n· 영업경비: 3.5억원\n· 연간 부채서비스액(원리금 상환액): 4억원\n· 영업소득세: 0.8억원","o":["3.5억원","4.3억원","4.9억원","8.3억원"],"a":1,"c":"운영 현금흐름은 가능총소득 → 유효총소득 → 순영업소득 → 세전현금흐름 → 세후현금흐름 순서로 내려가요. 운영단계에서 빼는 세금은 영업소득세이고, 양도소득세는 처분 단계에서 따져요.","e":"공실을 빼고 기타소득을 더한 유효총소득 11.8억원에서 영업경비를 빼면 순영업소득 8.3억원, 다시 부채서비스액 4억원을 빼면 세전현금흐름 4.3억원이에요.","w":["영업소득세까지 뺀 세후현금흐름이에요.",null,"공실 및 회수불능 0.6억원을 빼지 않았어요.","부채서비스액을 빼기 전의 순영업소득이에요."],"k":"받을 수 있는 최대 임대료에서 빈 방·관리비·대출 상환을 차례로 빼면 세금 내기 전 내 손에 남는 돈이 나와요.","m":"가능총소득 − 공실 + 기타소득 = 유효총소득 → − 영업경비 = 순영업소득 → − 부채서비스액 = 세전현금흐름 → − 영업소득세 = 세후현금흐름","f":"유효총소득 = 12 − 0.6 + 0.4 = 11.8억 → 순영업소득 = 11.8 − 3.5 = 8.3억 → 세전현금흐름 = 8.3 − 4 = 4.3억원","rev":0},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","t":"등기 없이 성립하는 권리","q":"부동산을 사기 전에 등기사항전부증명서만 확인해서는 존재를 알 수 없는 권리를 〈보기〉에서 모두 고른 것은?\n〈보기〉\nㄱ. 근저당권\nㄴ. 분묘기지권\nㄷ. 법정지상권\nㄹ. 전세권\nㅁ. 유치권","o":["ㄱ, ㄹ","ㄴ, ㄷ, ㅁ","ㄷ, ㄹ, ㅁ","ㄱ, ㄴ, ㄷ, ㅁ"],"a":1,"c":"대부분의 물권은 등기해야 효력이 생기지만, 법률 규정이나 관습으로 등기 없이 성립하는 권리도 있어요. 예를 들어 유치권은 남의 물건을 점유한 사람이 그 물건에 관해 생긴 채권을 받을 때까지 물건을 붙잡아 둘 수 있는 법정 담보물권이에요. 이런 권리는 현장 조사(임장활동)로 확인해야 해요.","e":"분묘기지권·법정지상권·유치권은 등기 없이 성립해요. 그래서 등기부만 보고는 알 수 없어요.","w":["근저당권과 전세권은 등기해야 성립하는 권리라 등기부 을구에서 확인할 수 있어요.",null,"전세권은 등기로 성립하는 권리예요.","근저당권은 등기로 성립하는 권리예요."],"k":"등기부는 부동산의 공식 이력서지만 모든 걸 담지는 않아요. 땅 위의 묘지나 공사대금을 못 받아 버티는 사람은 직접 가 봐야 알아요.","m":"등기 없이 성립: 점유권 · 유치권 · 분묘기지권 · (관습법상) 법정지상권","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"리츠의 설립과 자본금","q":"부동산투자회사법상 리츠의 설립과 자본금을 바르게 설명한 것은?","o":["리츠는 모집설립과 발기설립 가운데 하나를 골라 설립할 수 있다","설립할 때 부동산을 현물로 출자받아 회사를 세울 수 있다","자기관리 리츠의 설립자본금은 5억원 이상이고, 위탁관리 리츠의 설립자본금은 3억원 이상이다","위탁관리 리츠는 영업인가·등록 후 6개월이 지나면 자본금이 70억원 이상이어야 한다"],"a":2,"c":"리츠는 발기설립만 가능하고, 설립 단계에서는 현물출자를 받을 수 없어요. 설립자본금과 최저자본금은 회사 종류마다 달라요. 영업인가·등록 후 2년 안에 주식의 30% 이상을 일반에 공모해야 해요(일부 예외 있음).","e":"설립자본금은 자기관리 리츠 5억원 이상, 위탁관리·기업구조조정 리츠 3억원 이상이에요.","w":["리츠는 발기설립 방법으로만 설립해요.","설립 시 현물출자에 의한 설립은 금지돼요.",null,"70억원은 자기관리 리츠의 최저자본금이고, 위탁관리·기업구조조정 리츠는 50억원이에요."],"k":"리츠는 처음엔 작게(3억~5억원) 시작해도 되지만, 영업을 시작하고 반년 뒤에는 정해진 몸집(50억~70억원)을 갖춰야 해요.","m":"리츠 설립: 발기설립만 · 설립 시 현물출자 X · 설립자본금 자기관리 5억/위탁·CR 3억 · 최저자본금 70억/50억 · 2년 내 30% 이상 공모 · 국토교통부 인가·등록","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"부동산 공부서류의 확인 사항","q":"부동산 관련 공적 서류와 그 서류로 확인할 내용의 연결로 가장 적절한 것은?","o":["등기사항전부증명서 을구 – 소유권의 이전 내역","지적도 – 근저당권의 채권최고액","토지이용계획확인서 – 용도지역·지구 같은 공법상의 토지 이용 규제","건축물대장 – 전세권 설정 여부"],"a":2,"c":"등기부는 권리관계를, 대장은 물리적 현황을, 지적도는 경계와 위치를, 토지이용계획확인서는 공법상 제한을 보여 줘요.","e":"용도지역·지구·구역 같은 공법상 이용 제한은 토지이용계획확인서로 확인해요.","w":["소유권에 관한 사항은 갑구에 있어요. 을구에는 저당권·전세권 같은 소유권 이외의 권리가 있어요.","지적도는 토지의 경계·지번·모양을 보여 줄 뿐 권리관계는 나오지 않아요.",null,"건축물대장은 건물의 구조·면적·용도 등 물리적 현황을 보여 줘요. 전세권은 등기부 을구에서 확인해요."],"k":"누가 주인인지는 등기부, 몇 평짜리인지는 대장, 어디까지가 내 땅인지는 지적도, 무엇을 지을 수 있는지는 토지이용계획확인서예요.","m":"등기부: 표제부(표시) · 갑구(소유권) · 을구(그 외 권리) / 대장 = 물리적 현황 / 지적도 = 경계 / 토지이용계획확인서 = 공법상 제한","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"용도지역의 세분과 지정","q":"국토계획법상 용도지역을 바르게 설명한 것은?","o":["하나의 토지에 용도지역을 둘 이상 겹쳐 지정할 수 있다","관리지역은 계획관리·생산관리·보전관리지역의 셋으로 세분된다","도시지역은 주거지역·상업지역·공업지역·관리지역으로 나뉜다","준농림지역은 지금도 관리지역과 나란히 쓰이는 용도지역의 하나이다"],"a":1,"c":"용도지역은 전 국토를 도시·관리·농림·자연환경보전의 4가지로 나누고, 한 토지에는 하나만 지정해요.","e":"관리지역은 보전관리·생산관리·계획관리지역으로 세분돼요.","w":["용도지역은 서로 겹치지 않게 하나만 지정해요. 용도지역 위에 겹쳐 지정하는 것은 용도지구·용도구역이에요.",null,"도시지역은 주거·상업·공업·녹지지역으로 나뉘어요. 관리지역은 도시지역과 나란한 별도의 용도지역이에요.","준농림지역은 예전 제도로, 지금은 관리지역으로 바뀌었어요."],"k":"나라 땅을 큰 칸 4개(도시·관리·농림·자연환경보전)로 나누고, 도시는 다시 4칸, 관리는 3칸으로 나눠요.","m":"용도지역 4개: 도시(주거·상업·공업·녹지) · 관리(보전·생산·계획) · 농림 · 자연환경보전 · 중복 지정 X","rev":0},{"s":1,"sec":"부동산관련 상품","star":1,"lv":"중","t":"용도구역의 지정 목적","q":"국토계획법상 용도구역을 설명한 내용 중 틀린 것은?","o":["개발제한구역은 도시의 무분별한 확산을 막고 도시 주변의 자연환경을 보전하기 위해 지정한다","시가화조정구역은 일정 기간 시가화를 유보하기 위해 지정하며, 유보기간은 5년 이상 20년 이내이다","도시자연공원구역은 도시 안에서 숲이 잘 보존된 산지를 지키려고 개발을 막는 구역이다","용도구역이 지정되면 그 토지의 용도지역은 효력을 잃고 용도구역의 제한만 적용된다"],"a":3,"c":"용도구역은 용도지역·용도지구의 제한을 강화하거나 완화해 따로 정하는 지역이에요. 시가지 확산 방지, 계획적 개발 등 특별한 목적이 있어요.","e":"용도구역은 용도지역·지구 위에 겹쳐 제한을 강화하거나 완화할 뿐, 용도지역을 없애지 않아요.","w":["개발제한구역(그린벨트)의 지정 목적이에요.","시가화조정구역의 유보기간은 5년 이상 20년 이내예요.","도시자연공원구역의 지정 목적이에요.",null],"k":"용도지역이 기본 옷이라면 용도구역은 그 위에 덧입는 조끼예요. 조끼를 입는다고 기본 옷이 사라지지는 않아요.","m":"용도구역: 개발제한(확산 방지) · 시가화조정(5~20년 유보) · 도시자연공원(도시 내 산지) · 수산자원보호 등","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"부동산 포트폴리오의 위험","q":"부동산 포트폴리오를 바르게 설명한 것은?","o":["각 부동산의 기대수익률에 투자비중을 곱해 더하면 포트폴리오 기대수익률이 된다","편입 부동산 수를 충분히 늘리면 금리 변동과 인플레이션에 따른 위험까지 없앨 수 있다","특정 건물의 주요 임차인이 나가서 생기는 위험은 체계적 위험이다","같은 지역·같은 용도의 부동산만 모을수록 분산효과가 커진다"],"a":0,"c":"분산투자로 줄일 수 있는 위험은 개별 부동산 고유의 비체계적 위험이고, 금리·인플레이션·경기처럼 시장 전체에 영향을 주는 체계적 위험은 줄일 수 없어요. 부동산은 주식·채권과 상관관계가 낮아 분산효과와 인플레이션 헤지 효과가 있지만 유동성이 낮아요.","e":"기대수익률은 각 자산의 기대수익률 × 투자비중을 더한 값이에요. 반면 포트폴리오 위험(분산)은 자산 간 공분산까지 반영해야 해서 단순 가중평균이 아니에요.","w":[null,"금리·인플레이션 위험은 체계적 위험이라 분산해도 남아요.","개별 건물의 임차인 이탈은 비체계적 위험이에요.","상관관계가 낮은 지역·용도를 섞어야 분산효과가 커요."],"k":"여러 건물에 나눠 담으면 한 건물의 사고는 묻히지만, 금리가 오르는 것처럼 모두에게 내리는 비는 피할 수 없어요.","m":"기대수익률 = 가중평균 · 분산 ≠ 가중평균(공분산 반영) · 체계적 위험(금리·인플레·경기)은 분산 불가","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"할인현금흐름 분석의 채택 기준","q":"요구수익률이 연 8%인 투자자가 다음 네 부동산 투자안을 검토하고 있다. 할인현금흐름 분석 결과에 따를 때 채택하기 어려운 투자안은?","o":["A안: 순현재가치 3억원","B안: 내부수익률 9.5%","C안: 수익성지수 0.92","D안: 수익성지수 1.15"],"a":2,"c":"할인현금흐름 기법은 투자기간 전체의 현금흐름을 현재가치로 바꿔 판단해요. 순현재가치(NPV) > 0, 내부수익률(IRR) > 요구수익률, 수익성지수(PI) > 1이면 채택해요.","e":"수익성지수는 들어올 현금의 현재가치를 나갈 현금의 현재가치로 나눈 값이라서 1보다 작으면 들어올 돈이 나갈 돈보다 적다는 뜻이에요. 0.92는 기각 대상이에요.","w":["순현재가치가 0보다 크면 채택해요.","내부수익률(9.5%)이 요구수익률(8%)보다 높으면 채택해요.",null,"수익성지수가 1보다 크면 채택해요."],"k":"100원을 넣고 현재가치로 92원만 돌아오는 사업은 하지 않는 게 맞아요.","m":"채택: NPV > 0 · IRR > 요구수익률 · PI > 1 (PI 기준은 0이 아니라 1)","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"상","t":"부채감당률과 순소득승수","q":"다음 자료에 따른 대상 부동산의 부채감당률(DCR)과 순소득승수를 바르게 짝지은 것은?\n· 총투자액: 120억원(자기자본 50억원)\n· 연간 순영업소득: 10억원\n· 연간 부채서비스액(원리금): 8억원","o":["DCR 0.8 — 순소득승수 12","DCR 1.25 — 순소득승수 12","DCR 1.25 — 순소득승수 5","DCR 0.8 — 순소득승수 5"],"a":1,"c":"부채감당률은 순영업소득으로 원리금을 몇 배 갚을 수 있는지, 순소득승수는 총투자액이 순영업소득의 몇 배인지를 보여 줘요.","e":"DCR은 10 ÷ 8 = 1.25로 1보다 커서 원리금을 갚을 여력이 있어요. 순소득승수는 120 ÷ 10 = 12예요.","w":["DCR을 부채서비스액 ÷ 순영업소득으로 거꾸로 계산했어요.",null,"순소득승수를 자기자본 ÷ 순영업소득으로 계산했어요. 분자는 총투자액이에요.","두 지표를 모두 잘못 계산했어요."],"k":"버는 돈(10억원)이 갚을 돈(8억원)의 1.25배라 여유가 있어요. 투자한 돈은 1년 순수익의 12배예요.","m":"DCR = 순영업소득 ÷ 부채서비스액(1 초과면 상환 여력) · 순소득승수 = 총투자액 ÷ 순영업소득","f":"DCR = 10 ÷ 8 = 1.25 · 순소득승수 = 120 ÷ 10 = 12","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"가치발생요인과 감정평가 방식의 한계","q":"부동산 감정평가를 설명한 내용 중 틀린 것은?","o":["효용, 상대적 희소성, 유효수요가 함께 갖춰져야 부동산의 가치가 생긴다","원가법은 재조달원가에서 감가수정을 해 적산가액을 구하는데, 새로 만들어 낼 수 없는 토지에는 적용하기 어렵다","수익방식은 임대료가 생기지 않는 주거용·공공용 부동산이나 시장이 크게 흔들리는 지역에서는 신뢰도가 떨어진다","역세권처럼 좋은 입지는 그 자체가 가치발생요인이므로, 입지가 나쁘면 효용과 수요가 있어도 가치가 생기지 않는다"],"a":3,"c":"가치발생요인은 가치가 '생기느냐'를 정하는 요인으로 효용·상대적 희소성·유효수요예요. 위치(입지)는 가치의 크기에 영향을 주는 가치형성요인이에요. 감정평가 3방식은 각각 쓰기 어려운 경우가 있어요.","e":"입지는 가치를 높이거나 낮추는 가치형성요인이지, 가치가 있고 없음을 정하는 가치발생요인이 아니에요.","w":["세 가지 중 하나라도 없으면 가치가 성립하지 않아요. 유효수요는 구매력이 뒷받침된 수요예요.","원가법은 건물처럼 다시 지을 수 있는 물건에 맞아요. 토지는 주로 공시지가기준법·거래사례비교법으로 평가해요.","수익방식은 수익이 없거나 순수익·환원이율을 잡기 어려우면 한계가 있어요. 비교방식은 비슷한 거래가 거의 없거나 시장이 지나치게 달아오르거나 얼어붙으면 쓰기 어려워요.",null],"k":"쓸모(효용), 귀함(희소성), 살 돈 있는 손님(유효수요) 세 박자가 맞아야 값이 생겨요. 위치는 그 값을 얼마로 할지 정하는 요소예요.","m":"가치발생요인 = 효용·상대적 희소성·유효수요(위치 X) · 원가법 = 재조달원가 − 감가수정(토지 부적합) · 수익방식 한계 = 비수익·불안정 시장","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"담보신탁과 저당권의 비교","q":"부동산 PF에서 토지를 저당권 대신 담보신탁으로 잡는 경우를 저당권과 견주어 본 내용 중 틀린 것은?","o":["신탁된 땅은 땅 주인(위탁자)의 다른 재산과 따로 관리돼 그의 다른 채권자가 압류하기 어렵다","채무를 갚지 못하면 법원 경매 대신 신탁회사의 공매로 처분해 회수 기간을 줄일 수 있다","신탁 후에는 위탁자가 그 부동산에 후순위 담보를 마음대로 설정하기 어려워 담보가치를 지키기 쉽다","신탁보수를 내야 하므로 저당권보다 설정 비용이 많이 들고 채권 회수 기간도 더 길다"],"a":3,"c":"담보신탁은 부동산을 신탁회사에 맡기고(신탁등기) 대출기관이 우선수익자가 되는 방식이에요. 신탁회사가 담보물을 관리하고, 문제가 생기면 공매로 처분해요. 원리금을 보장해 주거나 사업 위험을 없애 주는 것은 아니에요.","e":"담보신탁은 저당권보다 설정 비용이 적게 들고, 공매로 처분해 경매보다 회수가 빨라요. 비용도 크고 기간도 길다는 설명은 반대예요.","w":["신탁재산 독립성 덕분에 위탁자가 파산하거나 다른 채권자가 압류해도 보호받기 쉬워요.","경매보다 절차가 간단한 공매로 처분해요.","후순위 권리 설정을 막아 담보가치가 떨어지지 않게 해요.",null],"k":"저당권이 '내 집 등기에 빨간 줄 긋기'라면, 담보신탁은 '집을 아예 금고(신탁회사)에 맡기기'예요. 맡겨 두면 남이 손대기 어렵고 팔 때도 빨라요.","m":"담보신탁 vs 저당권: 비용↓ · 공매로 회수 빠름 · 후순위 권리 배제 · 신탁재산 독립성 · 대출기관 = 우선수익자 · 원리금 보장 X","rev":0},{"s":1,"sec":"부동산관련 상품","star":1,"lv":"하","t":"부동산 개발사업의 단계","q":"다음은 부동산 개발사업이 흘러가는 일반적인 순서이다. 빈칸 (가)·(나)에 맞는 단계는?\n구상 → (가) → 부지 확보 → (나) → 금융 → 건설 → 마케팅","o":["(가) 예비적 타당성분석 – (나) 타당성분석","(가) 타당성분석 – (나) 예비적 타당성분석","(가) 자금 조달 – (나) 예비적 타당성분석","(가) 분양 마케팅 – (나) 타당성분석"],"a":0,"c":"개발사업은 아이디어(구상)를 세운 뒤 대략적인 수익성을 먼저 따져 보고(예비적 타당성분석), 땅을 확보한 다음 구체적인 사업성을 다시 검토해요(타당성분석). 그 뒤 자금을 조달하고 건설·마케팅으로 이어져요.","e":"예비적 타당성분석으로 사업 가능성을 걸러 낸 뒤 부지를 확보하고, 확보한 부지를 기준으로 정밀한 타당성분석을 해요.","w":[null,"순서가 바뀌었어요. 대략적인 검토(예비적)가 먼저, 정밀한 검토가 나중이에요.","자금 조달(금융)은 타당성분석이 끝난 뒤, 건설 바로 앞 단계예요.","마케팅은 마지막 단계예요."],"k":"집 짓기 전에 '될까?' 하고 대충 계산해 보고, 땅을 잡은 뒤 '정말 될까?' 하고 꼼꼼히 계산해요. 돈 빌리기와 공사는 그다음이에요.","m":"구상 → 예비적 타당성 → 부지 확보 → 타당성 → 금융 → 건설 → 마케팅","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","t":"부동산 경기 국면과 안정시장","q":"부동산 경기변동을 설명한 〈보기〉에서 맞는 것을 빠짐없이 고르면?\nㄱ. 회복시장과 상향시장에서는 과거 거래가격이 새 거래가격의 하한선이 되는 경향이 있고 매도자가 거래를 주도한다.\nㄴ. 후퇴시장에서는 과거 거래가격이 새 거래가격의 상한선이 되는 경향이 있어 매수자가 유리해진다.\nㄷ. 안정시장은 위치가 좋은 소규모 주택처럼 경기 영향을 덜 받는 시장으로, 4개 순환 국면과 별도로 나타난다.\nㄹ. 부동산 경기는 일반 경기보다 순환 주기가 짧고 진폭이 작다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":2,"c":"부동산 경기는 회복 → 상향(호황) → 후퇴 → 하향(불황) 국면을 거치고, 이와 별도로 안정시장이 있어요. 부동산 경기는 일반 경기보다 늦게 움직이고(후행), 주기가 길며 진폭이 크고, 지역마다 다르게 움직여요. 거래가 가장 적은 국면은 하향시장이에요.","e":"ㄱ·ㄴ·ㄷ이 옳아요. 부동산 경기는 일반 경기보다 주기가 길고 진폭이 커요.","w":["ㄷ도 옳아요. 안정시장은 불황에 강한 시장으로 순환 국면과 별도로 봐요.","ㄹ은 틀렸어요. 부동산 경기는 주기가 길고 진폭이 커요. ㄱ·ㄴ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 주기가 길고 진폭이 커요."],"k":"오르막(회복·상향)에선 '전에 이 값에 팔렸으니 그 이상'이 되고, 내리막(후퇴·하향)에선 '전에 그 값이었으니 그 이하'가 돼요.","m":"회복·상향: 과거 사례 = 하한 · 매도자 주도 / 후퇴·하향: 상한 · 매수자 우위 · 하향 = 거래 최소 / 안정시장 = 별도 · 부동산 경기 = 후행·장주기·큰 진폭·지역별 차이","rev":0},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"하","t":"토지 특성에서 생기는 현상","q":"토지의 자연적 특성 가운데 '개별성'에서 비롯되는 현상으로 가장 적절한 것은?","o":["땅은 써도 닳아 없어지지 않아 물리적 감가상각을 하지 않는다","수요가 늘어도 땅의 물리적 양을 늘릴 수 없어 가격 상승 압력이 생긴다","땅을 옮길 수 없어 지역마다 따로 시장이 생기고, 거래 전에 현장을 직접 확인하는 임장활동이 필요하다","면적과 용도가 같아 보여도 땅마다 값이 달라 일물일가의 법칙이 통하지 않고, 평가할 때 개별요인을 따로 비교해야 한다"],"a":3,"c":"토지의 자연적 특성은 부동성·부증성·영속성·개별성이에요. 용도의 다양성, 병합·분할 가능성, 위치의 가변성은 인문적 특성이에요. 이런 특성 때문에 부동산 시장은 지역적이고, 정보가 잘 공개되지 않으며, 거래 비용이 크고, 공급 조절이 어려운 불완전경쟁 시장이에요.","e":"똑같은 땅은 하나도 없다는 개별성 때문에 같은 상품에 같은 값이 매겨지지 않고, 표준화와 비교가 어려워요.","w":["영속성에서 생기는 현상이에요.","부증성에서 생기는 현상이에요. 땅의 양 자체가 늘지 않아 공급 곡선이 수직이에요.","부동성에서 생기는 현상이에요. 시장이 국지적으로 나뉘는 이유이기도 해요.",null],"k":"세상에 똑같은 얼굴이 없듯 똑같은 땅도 없어요. 그래서 '이 동네 땅값'을 하나로 정하기 어려워요.","m":"부동성 → 국지적 시장·임장활동 · 부증성 → 공급 비탄력·지가 상승 · 영속성 → 감가상각 X · 개별성 → 일물일가 X / 인문적: 용도 다양성·병합분할·위치 가변성","rev":0},{"s":1,"sec":"부동산관련 상품","star":1,"lv":"중","t":"개발행위허가와 건축법상 용어","q":"개발행위허가(국토계획법)와 건축법 용어를 설명한 내용 중 틀린 것은?","o":["녹지지역에 자재 같은 물건을 1개월 이상 쌓아 두려면 개발행위허가를 받아야 한다","도시·군계획사업의 일부로 땅을 나누는 경우에도 일반 분할처럼 별도의 개발행위허가가 필요하다","건축법에서 말하는 '건축'에는 신축, 증축, 개축, 재축과 건축물 이전이 들어간다","용적률을 계산할 때 연면적에는 지하층 바닥면적을 넣지 않는다"],"a":1,"c":"건축물 건축·공작물 설치, 토지 형질변경, 토석 채취, 토지 분할, 녹지·관리·자연환경보전지역의 물건 적치는 개발행위허가 대상이에요. 다만 도시·군계획사업으로 하는 행위는 그 사업 절차를 거치므로 따로 허가받지 않아요. 용도변경은 사용승인을 받은 건축물의 용도를 다른 용도로 바꾸는 것이에요.","e":"도시·군계획사업에 따른 행위는 개발행위허가 대상에서 빠져요.","w":["녹지·관리·자연환경보전지역에서 한 달 이상 물건을 쌓아 두는 일은 허가를 받아야 해요.",null,"신축·증축·개축·재축·이전 다섯 가지가 '건축'이에요.","용적률은 지상층 연면적 기준이라 지하층 면적은 빼요."],"k":"나라 계획대로 하는 공사는 이미 큰 허락을 받은 셈이라, 작은 허락(개발행위허가)을 또 받지 않아도 돼요.","m":"개발행위허가: 건축·공작물 · 형질변경 · 토석채취 · 토지분할 · 물건 적치(1개월 이상) / 도시·군계획사업은 제외 · 건축 = 신축·증축·개축·재축·이전 · 용도변경 = 사용승인 받은 건축물 대상","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"대안투자의 특징","q":"대안투자의 일반적인 특징으로 가장 거리가 먼 것은?","o":["유동성이 낮고 투자 기간이 긴 편이다","운용 보수와 성과보수 등 수수료 수준이 높은 편이다","전통 자산(주식·채권)과의 상관관계가 낮은 편이다","거래가 활발해 가격 발견이 쉽고 공정가치 평가가 간편하다"],"a":3,"c":"대안투자는 부동산, 사모펀드, 헤지펀드, 인프라, 원자재 등 전통 자산이 아닌 투자를 말해요.","e":"대안투자는 거래가 드물어 가격 발견이 어렵고 공정가치를 평가하기 어려운 것이 특징이에요.","w":["유동성이 낮고 장기 투자가 많아요.","수수료 수준이 높은 편이에요.","전통 자산과 상관관계가 낮아 분산효과가 있어요.",null],"k":"부동산이나 비상장 회사는 매일 시세가 나오지 않아요. 그래서 \"지금 얼마냐\"를 매기기가 어려워요.","m":"대안투자: 저상관 · 저유동성 · 고수수료 · 가치평가 어려움"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"허들레이트","q":"사모펀드·헤지펀드 성과보수 체계에서 허들레이트(hurdle rate)의 의미로 가장 적절한 것은?","o":["펀드 환매를 제한하는 기간이다","투자자에게 원금을 보장하는 수익률이다","미리 정한 최소 수익률을 넘는 성과에 대해서만 성과보수를 받는 기준 수익률이다","운용보수를 면제하는 기준 금액이다"],"a":2,"c":"대안투자 운용사는 보통 운용보수와 함께 성과보수를 받아요. 성과보수에는 투자자를 보호하는 장치가 붙어요.","e":"허들레이트는 성과보수를 받기 위해 넘어야 하는 최소 수익률이에요. 예를 들어 허들레이트가 8%이면 8%를 넘는 성과부터 성과보수를 계산해요.","w":["락업(환매 제한) 기간의 설명이에요.","보장 수익률이 아니에요.",null,"운용보수와 관계없는 개념이에요."],"k":"\"이 정도는 넘어야 보너스를 준다\"는 문턱이에요.","m":"허들레이트 = 성과보수 기준 최소 수익률 · 하이워터마크 = 과거 최고 NAV 기준"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"대안투자 수익률 분포","q":"대안투자 수익률 자료의 특징으로 가장 적절한 것은?","o":["과거 수익률 자료가 풍부해 성과 비교가 쉽다","시가평가가 매일 이루어져 가격 정보가 투명하다","평가 주기가 길고 감정평가에 의존해 변동성이 실제보다 낮게 나타날 수 있다","정규분포를 따르는 경우가 많아 표준편차만으로 위험을 충분히 설명할 수 있다"],"a":2,"c":"대안투자 자산은 시장에서 매일 거래되지 않는 경우가 많아요.","e":"부동산·PE 등은 감정평가로 가치를 매겨 가격이 매끄럽게 나타나므로, 변동성과 상관관계가 실제보다 낮게 보일 수 있어요.","w":["자료가 부족한 편이에요.","매일 시가평가되지 않는 경우가 많아요.",null,"꼬리가 두꺼운 등 정규분포를 벗어나는 경우가 많아요."],"k":"가끔 매긴 값만 보면 실제보다 덜 흔들리는 것처럼 보여요.","m":"평가 스무딩 → 변동성 과소 측정"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"J-커브 효과","q":"사모투자(PE) 펀드의 연도별 누적 수익률이 초기에는 음(−)을 보이다가 투자 회수기에 양(+)으로 돌아서는 현상은?","o":["J-커브 효과","레버리지 효과","캐리 효과","롤오버 효과"],"a":0,"c":"PE 펀드는 처음에 보수와 투자 비용이 먼저 나가고, 수익은 투자 회수 때 들어와요.","e":"초기에는 보수·비용 때문에 수익률이 음수였다가 회수기에 크게 개선되는 모양이 J자를 닮아 J-커브 효과라고 해요.","w":[null,"차입으로 수익을 키우는 효과예요.","금리차 수익이에요.","만기 연장과 관련된 개념이에요."],"k":"처음에 살짝 내려갔다가 크게 올라가는 J 모양이에요.","m":"J-커브 = 초기 비용 → 음(−) / 회수기 → 양(+)"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"헤지펀드 전략 분류","q":"헤지펀드 전략 중 방향성 전략에 해당하는 것은?","o":["전환사채 차익거래","합병 차익거래","글로벌 매크로","채권 차익거래"],"a":2,"c":"헤지펀드 전략은 차익거래형, 이벤트 드리븐형, 방향성 전략 등으로 나눠요.","e":"글로벌 매크로는 금리·환율·경기 같은 거시 흐름을 예측해 방향성 베팅을 하는 대표적 방향성 전략이에요.","w":["차익거래형이에요.","이벤트 드리븐형이에요.",null,"차익거래형이에요."],"k":"\"시장이 어디로 갈지\" 맞히려는 전략이 방향성 전략이에요.","m":"차익거래: CB·채권·주식시장중립 / 이벤트: 합병·부실채권 / 방향성: 매크로·롱숏·이머징·섹터"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"주식시장중립 전략","q":"주식시장중립(equity market neutral) 전략에 관한 설명으로 가장 적절한 것은?","o":["포트폴리오 베타를 0에 가깝게 맞춰 시장 방향과 무관한 수익을 노린다","시장 상승에 크게 베팅해 수익을 극대화한다","공매도를 전혀 사용하지 않는다","채권만 투자한다"],"a":0,"c":"시장중립 전략은 매수와 공매도를 함께 써서 시장 전체 움직임의 영향을 없애요.","e":"저평가 종목 매수와 고평가 종목 공매도로 베타를 0 근처로 맞춰, 종목 선택에서 나오는 수익만 얻으려는 전략이에요.","w":[null,"방향성 전략의 설명이에요.","공매도를 반드시 써요.","주식 전략이에요."],"k":"시장이 오르든 내리든, 고른 종목끼리의 차이만 먹어요.","m":"시장중립 = 롱 + 숏 · 베타 ≈ 0 · 종목선택 수익"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"롱숏 순노출 계산","q":"자본 100억원으로 주식 130억원을 매수하고 70억원을 공매도한 롱숏 펀드의 총노출(gross)과 순노출(net)은?","o":["총노출 130%, 순노출 70%","총노출 60%, 순노출 200%","총노출 200%, 순노출 60%","총노출 200%, 순노출 −60%"],"a":2,"c":"총노출은 매수와 공매도 금액을 더하고, 순노출은 매수에서 공매도를 빼서 자본 대비 비율로 나타내요.","e":"총노출 = (130 + 70) ÷ 100 = 200%, 순노출 = (130 − 70) ÷ 100 = 60%예요.","w":["각 포지션 비율일 뿐이에요.","둘을 바꿨어요.",null,"순노출 부호가 틀렸어요."],"k":"모두 합치면 200억, 시장 방향으로는 60억만 걸려 있어요.","m":"총노출 = 롱 + 숏 · 순노출 = 롱 − 숏","f":"200% · 60%"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"펀드오브헤지펀드","q":"여러 헤지펀드에 나눠 투자하는 펀드오브헤지펀드(FoHF)에 관한 설명으로 가장 적절하지 않은 것은?","o":["여러 운용사와 전략에 분산투자할 수 있다","전문가가 운용사를 골라 주는 효과가 있다","하위 펀드 보수와 상위 펀드 보수가 이중으로 붙는다","보수 부담이 단일 헤지펀드보다 항상 낮다"],"a":3,"c":"FoHF는 분산과 실사 기능이 장점이지만, 펀드 위에 펀드가 하나 더 있는 구조예요.","e":"하위 헤지펀드 보수에 FoHF 자체 보수가 더해져 보수가 이중으로 부과되므로 단일 펀드보다 부담이 커요.","w":["분산이 장점이에요.","운용사 선별·실사 효과가 있어요.","이중 보수가 단점이에요.",null],"k":"중개인을 한 번 더 거치면 수수료도 한 번 더 내요.","m":"FoHF: 분산·실사 장점 / 이중 보수 단점"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"LBO","q":"인수 대상 기업의 자산이나 미래 현금흐름을 담보로 자금을 차입해 기업을 인수하는 방식은?","o":["LBO(차입매수)","IPO","블록딜","유상증자"],"a":0,"c":"PEF는 적은 자기자본에 차입을 더해 큰 기업을 인수하는 경우가 많아요.","e":"인수 대상의 자산·현금흐름을 담보로 빌린 돈으로 인수하는 것이 LBO예요. 레버리지로 자기자본 수익률을 높여요.","w":[null,"주식 상장이에요.","대량 주식 일괄 매매예요.","신주 발행이에요."],"k":"살 회사를 담보로 돈을 빌려 그 회사를 사요.","m":"LBO = 대상 기업 자산·현금흐름 담보 차입 인수"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"PE 투자 단계","q":"사모투자 중 창업 초기·성장 단계의 비상장 기업에 투자하는 것은?","o":["벤처캐피탈","바이아웃","메자닌","부실채권 투자"],"a":0,"c":"사모투자는 투자 대상 기업의 성장 단계에 따라 나눌 수 있어요.","e":"창업 초기·성장 단계 기업에 투자하는 것은 벤처캐피탈이에요. 바이아웃은 성숙 기업의 경영권 인수예요.","w":[null,"성숙 기업 경영권 인수예요.","채권과 주식 중간 성격 증권 투자예요.","부실기업 투자예요."],"k":"갓 태어난 회사에 씨앗을 뿌리는 투자예요.","m":"벤처캐피탈(초기·성장) · 바이아웃(성숙·경영권) · 메자닌(중간 위험)"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"메자닌 투자","q":"메자닌 투자에 관한 설명으로 가장 적절한 것은?","o":["선순위 채권과 보통주 사이의 위험·수익을 가진 전환사채·신주인수권부사채 등에 투자한다","국채에만 투자한다","보통주에만 투자해 경영권을 확보한다","부동산 실물에만 투자한다"],"a":0,"c":"메자닌은 건물의 1층과 2층 사이 중간층을 뜻하는 말이에요.","e":"메자닌은 선순위 채권보다 위험하고 보통주보다 안전한 중간 단계 자본(CB·BW·후순위채·상환전환우선주 등)에 투자해요.","w":[null,"국채는 메자닌이 아니에요.","보통주 투자는 지분 투자예요.","부동산 실물 투자예요."],"k":"채권과 주식 사이의 \"중간층\"이에요.","m":"메자닌 = 채권과 주식 사이(CB·BW·RCPS·후순위채)"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"캐피탈 콜","q":"PE 펀드에서 투자자가 약정한 금액을 한 번에 내지 않고, 투자 대상이 생길 때마다 운용사의 요청에 따라 나눠 납입하는 방식은?","o":["캐피탈 콜(capital call)","하이워터마크","락업","클로백"],"a":0,"c":"PE 펀드는 처음에 약정만 받고 실제 돈은 투자할 때 받는 경우가 많아요.","e":"운용사가 투자 시점마다 약정액 중 일부 납입을 요청하는 것을 캐피탈 콜이라고 해요.","w":[null,"성과보수 기준이에요.","환매 제한 기간이에요.","초과 지급된 성과보수를 돌려받는 장치예요."],"k":"\"이번에 쓸 돈 보내 주세요\"라는 요청이에요.","m":"캐피탈 콜 = 약정액 분할 납입 요청"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"상관관계와 CDO 트랜치 가치","q":"기초자산들 사이의 부도 상관관계가 높아질 때 CDO 트랜치 가치 변화로 가장 적절한 것은?","o":["모든 트랜치 가치가 오른다","에쿼티 트랜치 가치는 내리고, 선순위 트랜치 가치는 오른다","에쿼티 트랜치 가치는 오르고, 선순위 트랜치 가치는 내린다","모든 트랜치 가치가 내린다"],"a":2,"c":"상관관계가 높으면 \"다 같이 괜찮거나, 다 같이 망하는\" 극단적인 결과가 늘어요.","e":"상관관계가 높아지면 아무 부도도 없을 가능성이 커져 에쿼티에 유리하고, 한꺼번에 부도날 가능성도 커져 선순위에 불리해요.","w":["트랜치마다 방향이 달라요.","방향이 반대예요.",null,"트랜치마다 방향이 달라요."],"k":"모두 살거나 모두 죽으면, 맨 아래층은 살아날 기회가, 맨 위층은 잠길 위험이 커져요.","m":"부도 상관↑ → 에쿼티 가치↑ · 선순위 가치↓"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"합성 CDO","q":"기초자산을 실제로 양도하지 않고 신용부도스왑(CDS)을 이용해 신용위험만 SPC로 이전하는 CDO는?","o":["시장가치 CDO","현금흐름 CDO","합성 CDO","차익거래 CDO"],"a":2,"c":"CDO는 위험 이전 방식에 따라 자산을 실제로 넘기는 방식과 신용파생상품으로 위험만 넘기는 방식으로 나눠요.","e":"자산은 그대로 두고 CDS로 신용위험만 이전하는 것은 합성 CDO예요.","w":["기초자산 시장가치로 상환해요.","기초자산 현금흐름으로 상환해요.",null,"발행 목적에 따른 구분이에요."],"k":"물건은 그대로, \"위험\"만 보험처럼 넘겨요.","m":"합성 CDO = CDS로 신용위험만 이전"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"CDS 프리미엄 결정 요인","q":"CDS 프리미엄이 높아지는 경우로 가장 적절하지 않은 것은?","o":["준거기업의 신용등급이 낮아진다","부도 시 회수율이 낮아진다","보장매도자의 신용등급이 높아진다","보장매도자와 준거기업의 부도 상관관계가 높아진다"],"a":3,"c":"CDS 프리미엄은 보장매입자가 보장매도자에게 내는 보험료예요.","e":"보장매도자와 준거기업이 함께 부도날 가능성이 커지면 보장의 가치가 떨어져 프리미엄이 낮아져요.","w":["신용위험이 커지면 프리미엄이 올라요.","손실이 커지니 올라요.","보장이 믿을 만하면 더 받을 수 있어요.",null],"k":"보험회사가 나랑 같이 망할 수 있다면, 그 보험은 싸야 해요.","m":"CDS 프리미엄↑: 준거 신용↓ · 회수율↓ · 만기↑ · 매도자 신용↑ · 상관관계↓"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"CLN(신용연계증권)","q":"CLN(신용연계증권)에 관한 설명으로 가장 적절한 것은?","o":["일반 채권에 CDS를 결합한 것으로, CLN 투자자는 보장매도자 역할을 한다","CLN 투자자는 신용위험을 전혀 지지 않는다","CLN 발행자는 보장매도자이다","준거기업이 부도나도 원금을 모두 돌려받는다"],"a":0,"c":"CLN은 신용위험을 증권 형태로 투자자에게 넘기는 상품이에요.","e":"CLN 발행자는 보장매입자, 투자자는 보장매도자예요. 준거기업이 부도나면 투자자는 원금 일부나 전부를 잃는 대신 높은 이자를 받아요.","w":[null,"투자자가 신용위험을 져요.","발행자는 보장매입자예요.","부도 시 원금 손실이 생겨요."],"k":"높은 이자를 받는 대신 남의 부도 위험을 대신 떠안는 채권이에요.","m":"CLN = 채권 + CDS · 발행자 = 보장매입 · 투자자 = 보장매도"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"부동산 투자 전략 분류","q":"부동산 대안투자 전략 중 위험과 기대수익이 가장 높은 것은?","o":["코어(core)","코어플러스(core-plus)","밸류애드(value-added)","오퍼튜니스틱(opportunistic)"],"a":3,"c":"부동산 투자 전략은 위험·수익 수준에 따라 코어 → 코어플러스 → 밸류애드 → 오퍼튜니스틱으로 나눠요.","e":"오퍼튜니스틱은 개발, 부실자산, 높은 레버리지 등을 활용해 가장 높은 위험과 기대수익을 추구해요.","w":["안정적 임대수익 중심으로 위험이 가장 낮아요.","코어보다 약간 위험이 높아요.","개보수 등으로 가치를 높이는 중간 위험이에요.",null],"k":"\"좋은 건물 사서 세 받기\"(코어)부터 \"개발·부실 자산 뒤집기\"(오퍼튜니스틱)까지예요.","m":"코어 < 코어플러스 < 밸류애드 < 오퍼튜니스틱"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"인프라 투자의 특징","q":"인프라(사회기반시설) 투자의 일반적 특징으로 가장 적절하지 않은 것은?","o":["투자 기간이 길다","독점적 성격으로 현금흐름이 비교적 안정적이다","물가와 연동된 수익 구조를 가진 경우가 많다","단기 매매로 시세차익을 얻기 쉽다"],"a":3,"c":"도로·항만·발전소 같은 인프라는 초기 투자 규모가 크고 오래 운영돼요.","e":"인프라는 장기 보유로 안정적 현금흐름을 얻는 자산이라 단기 매매에 적합하지 않고 유동성도 낮아요.","w":["장기 투자예요.","대체재가 적어 안정적이에요.","요금이 물가와 연동되는 경우가 많아요.",null],"k":"도로는 수십 년 통행료를 받는 자산이지, 사고팔며 차익을 노리는 자산이 아니에요.","m":"인프라: 장기 · 독점·안정 현금흐름 · 물가연동 · 저유동성"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"콘탱고와 롤 수익","q":"원자재 선물에 투자하면서 만기가 다가올 때마다 다음 월물로 바꿔 타는(롤오버) 경우, 시장이 콘탱고 상태라면 롤 수익은?","o":["음(−)이 된다","양(+)이 된다","항상 0이다","현물 가격과 같다"],"a":0,"c":"콘탱고는 먼 월물 가격이 가까운 월물보다 높은 상태, 백워데이션은 그 반대예요.","e":"콘탱고에서는 싼 근월물을 팔고 비싼 원월물을 사야 하므로 롤 수익이 음(−)이에요. 백워데이션에서는 양(+)이에요.","w":[null,"백워데이션일 때예요.","0이 아니에요.","관계없어요."],"k":"싸게 팔고 비싸게 다시 사는 걸 반복하면 손해예요.","m":"콘탱고(원월물 > 근월물) → 롤 수익 (−) · 백워데이션 → (+)"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"원자재 투자의 장점","q":"포트폴리오에 원자재를 편입하는 이유로 가장 적절한 것은?","o":["인플레이션 헤지 효과와 주식·채권과의 낮은 상관관계","확정된 이자 수익","원금 보장","높은 배당수익"],"a":0,"c":"원자재는 이자나 배당이 없지만, 다른 이유로 포트폴리오에 담아요.","e":"원자재 가격은 물가와 함께 움직이는 경향이 있어 인플레이션 헤지가 되고, 주식·채권과 상관관계가 낮아 분산효과가 있어요.","w":[null,"이자가 없어요.","원금 보장이 아니에요.","배당이 없어요."],"k":"물가가 오를 때 같이 오르는 자산이에요.","m":"원자재: 인플레이션 헤지 · 낮은 상관관계 · 이자·배당 없음"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"사모펀드와 헤지펀드의 차이","q":"사모투자펀드(PE)와 헤지펀드를 비교한 설명으로 가장 적절한 것은?","o":["PE는 주로 비상장 기업 지분에 장기 투자하고, 헤지펀드는 주로 유동성 있는 상장 자산을 거래한다","PE는 매일 환매가 가능하다","헤지펀드는 경영권 인수만 목적으로 한다","두 펀드는 투자 기간과 대상이 같다"],"a":0,"c":"PE와 헤지펀드는 모두 사모 형태지만 투자 방식이 많이 달라요.","e":"PE는 비상장 기업 지분을 장기 보유해 가치를 높인 뒤 회수하고, 헤지펀드는 상장 주식·채권·파생상품 등을 비교적 짧은 기간에 거래해요.","w":[null,"PE는 장기간 환매가 제한돼요.","PE의 특징에 가까워요.","기간과 대상이 달라요."],"k":"PE는 회사를 키워서 팔고, 헤지펀드는 시장에서 사고팔아요.","m":"PE = 비상장·장기·경영참여 · 헤지펀드 = 상장자산·단기·다양한 전략"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"대안투자 실사","q":"대안투자 운용사를 선정할 때 실사(due diligence) 항목으로 가장 적절하지 않은 것은?","o":["운용 전략과 과거 성과의 일관성","위험관리 체계와 내부통제","운용 인력의 경력과 이직 현황","투자자 개인의 소득세율"],"a":3,"c":"대안투자는 운용사 역량에 따라 성과 차이가 매우 커서 운용사 실사가 중요해요.","e":"투자자 개인의 소득세율은 운용사 실사 항목이 아니에요. 전략, 성과, 위험관리, 인력, 운영 체계 등을 점검해요.","w":["핵심 실사 항목이에요.","핵심 실사 항목이에요.","핵심 실사 항목이에요.",null],"k":"실사는 \"이 운용사 믿을 만한가?\"를 따지는 거예요.","m":"실사: 전략·성과 · 위험관리 · 인력 · 운영·내부통제"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"매니지드 퓨처스(CTA) 전략","q":"상품투자자문업자(CTA)가 주로 선물시장에서 가격 추세를 따라 매매하는 헤지펀드 전략에 관한 설명으로 가장 적절한 것은?","o":["현물 주식만 사서 오래 보유하는 전략이다","합병·파산 같은 기업 사건에 투자하는 이벤트 드리븐 전략이다","추세추종형 방향성 전략으로, 시장이 크게 한 방향으로 움직일 때 성과가 좋은 경향이 있다","두 증권의 가격 차이만 노리는 차익거래형 전략이다"],"a":2,"c":"매니지드 퓨처스는 원자재·금리·통화·주가지수 선물을 사고팔며 추세를 따라가는 전략이에요.","e":"이 전략은 오르는 시장은 사고 내리는 시장은 파는 추세추종형 방향성 전략이라, 위기처럼 시장이 한쪽으로 크게 움직일 때 성과가 좋은 경향이 있어요.","w":["주로 선물로 사고팔아요.","기업 사건이 아니라 가격 추세를 따라가요.",null,"가격 차이를 노리는 전략과 달라요."],"k":"바람 부는 방향으로 돛을 다는 전략이에요.","m":"매니지드 퓨처스(CTA) = 선물 · 추세추종 · 방향성"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"대안투자 벤치마크의 한계","q":"헤지펀드 지수를 벤치마크로 쓸 때의 문제점으로 가장 적절한 것은?","o":["실패한 펀드가 지수에서 빠져 성과가 실제보다 높게 나타나는 생존자 편의가 있다","모든 헤지펀드가 의무적으로 성과를 공시한다","전략 간 차이가 없어 하나의 지수로 충분하다","지수 구성 종목이 매일 공시된다"],"a":0,"c":"헤지펀드 지수는 운용사가 자발적으로 보고한 자료로 만들어요.","e":"청산된 펀드는 빠지고 살아남은 펀드만 남아 지수 성과가 부풀려지는 생존자 편의가 생겨요. 성과가 좋은 펀드만 보고하는 자기선택 편의도 있어요.","w":[null,"자발적으로 보고해요.","전략별 차이가 커요.","구성 정보가 제한적이에요."],"k":"살아남은 사람 이야기만 들으면 성공률이 높아 보여요.","m":"헤지펀드 지수 편의: 생존자 · 자기선택 · 소급(backfill)"},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"상","t":"기관전용 사모집합투자기구의 규제","q":"자본시장법상 기관전용 사모집합투자기구의 규제로 틀린 것은?","o":["GP와 LP를 합한 사원 수는 100인을 넘을 수 없다","GP(무한책임사원)도 노무나 신용을 출자 대상으로 삼을 수 없다","연기금·보험회사 같은 기관은 보통 유한책임사원으로 출자한다","경영참여 목적으로 투자하려면 반드시 투자대상 회사의 의결권 있는 주식을 10% 이상 취득해야 한다"],"a":3,"c":"기관전용 사모펀드(PEF)는 합자회사 형태로, 운용을 맡는 무한책임사원(GP)과 돈을 대는 유한책임사원(LP)으로 이루어져요. 클로백(clawback)은 GP가 성과보수를 지나치게 받아 간 경우 돌려받는 장치예요.","e":"예전 경영참여형 PEF에 있던 '의결권 있는 지분 10% 이상 취득' 의무는 2021년 제도 개편으로 없어졌어요. 지금은 메자닌·대출 등 다양한 방식으로 운용할 수 있어요(금융회사가 GP인 경우 등은 예외).","w":["사원 총수는 100인 이하예요.","무한책임사원의 노무·신용 출자는 허용되지 않아요.","기관투자자는 운용에 관여하지 않고 약정한 출자액까지만 책임지는 LP로 들어가요.",null],"k":"PEF는 운전하는 사람(GP)과 차비를 대는 사람들(LP)이 함께 탄 차예요. 예전 같은 '지분 10% 이상'이라는 승차 조건은 이제 없어요.","m":"기관전용 PEF: 사원 100인 이하 · GP 무한책임·업무집행(노무·신용 출자 X) · LP 유한책임 · 10% 룰 폐지 · 차입 순자산 400% 이내","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","t":"PEF가 노리는 투자대상 기업","q":"PEF(기관전용 사모펀드)가 경영권을 사들일 대상으로 선호하는 기업과 가장 거리가 먼 것은?","o":["경영난에 빠졌지만 구조조정으로 정상화하면 가치가 크게 오를 수 있는 기업","보유 부동산 등 자산가치에 비해 주가가 크게 낮게 거래되는 기업","쌓아 둔 이익잉여금은 많지만 배당을 거의 하지 않는 기업","업황에 따라 이익이 크게 출렁여 미래 현금흐름을 예측하기 어려운 기업"],"a":3,"c":"PEF는 인수 후 경영을 바꿔 가치를 높이고 되팔아 수익을 내요. 그래서 개선 여지가 크고 현금흐름이 안정적인 기업을 선호해요.","e":"PEF는 인수자금의 상당 부분을 빌려(LBO) 대상 기업의 현금흐름으로 갚는 경우가 많아요. 이익이 경기에 따라 크게 출렁이는 기업은 상환 계획을 세우기 어려워 선호하지 않아요.","w":["구조조정으로 가치를 올릴 수 있는 부실기업은 대표적인 투자대상이에요.","자산가치보다 싸게 거래되는 저평가 기업은 매력적인 대상이에요.","유보이익이 많으면 인수 뒤 배당·감자 등으로 투자금을 회수하기 좋아요.",null],"k":"PEF는 싸게 사서 고쳐 팔 수 있는 집을 찾아요. 매달 수입이 들쭉날쭉한 집은 대출 갚기가 불안해서 피해요.","m":"PEF 선호: 회생 가능한 부실기업 · 자산 대비 저평가 · 유보이익 많고 저배당 / 기피: 경기민감·현금흐름 불안정","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","t":"방향성 전략의 세부 유형","q":"방향성 헤지펀드 전략을 설명한 내용 중 틀린 것은?","o":["글로벌 매크로는 성장률·물가·환율 같은 거시 변수를 먼저 분석해 국가와 자산을 고르는 하향식(Top-down) 접근을 쓴다","글로벌 매크로는 주로 외환·국채·원자재처럼 유동성이 풍부한 자산을 거래한다","매도전문(Dedicated short) 펀드는 고평가된 주식을 빌려 판 뒤 주가가 떨어지면 이익을 얻는다","이머징마켓 헤지펀드는 신흥국의 주식 대차시장이 잘 발달해 있어 공매도 중심으로 운용한다"],"a":3,"c":"방향성 전략은 시장이 오를지 내릴지에 베팅하는 전략이에요. 글로벌 매크로, 주식 롱숏(한쪽으로 비중을 기울인 경우), 이머징마켓, 매도전문, 매니지드 퓨처스 등이 있어요.","e":"신흥국은 공매도나 주식 대차가 제한되거나 인프라가 부족한 경우가 많아요. 그래서 이머징마켓 헤지펀드는 매수(롱) 위주로 운용하는 것이 일반적이에요.","w":["거시 흐름에서 출발해 내려오는 하향식이 글로벌 매크로의 특징이에요. 개별 기업부터 보는 것은 상향식(Bottom-up)이에요.","큰 포지션을 빠르게 사고팔아야 해서 유동성이 큰 자산을 선호해요.","주식을 빌려 먼저 팔고, 싸게 되사서 갚아 이익을 내는 구조예요.",null],"k":"신흥국 시장은 주식을 빌려 파는 길이 좁아요. 그래서 그곳에서는 주로 사서 오르길 기다려요.","m":"매크로 = Top-down·고유동성 자산 · 이머징 = 롱 위주(공매도 제약) · 매도전문 = 숏 위주 · 롱숏도 비중이 쏠리면 방향성","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","t":"부동산 개발금융의 위험관리","q":"부동산 PF 개발사업에서 대주단이 사업 위험을 줄이기 위해 취하는 조치로 가장 적절하지 않은 것은?","o":["분양대금을 에스크로 계좌로 받아 정해진 사업 용도로만 쓰이게 한다","인허가가 약정 기한까지 나지 않으면 시공사가 대출채무를 인수하도록 하는 조건을 둔다","사업부지에 담보신탁 등 채권 보전 장치를 미리 설정한다","토지주가 여럿이면 일부 필지부터 먼저 사들이고 나머지는 사업 진행을 보며 천천히 매입한다"],"a":3,"c":"PF는 사업 자체의 현금흐름으로 상환하는 금융이라 사업이 멈추지 않게 하는 장치가 중요해요. 선순위 자금은 주로 금융기관이 대고, 시행사의 신용이 약한 경우가 많아 시공사의 책임준공·채무인수·연대보증으로 보강해요.","e":"토지를 나눠 사면 남은 토지주가 값을 올리거나 매도를 거부해 사업이 멈출 수 있어요. 그래서 사업부지는 한꺼번에 확보하는 것이 위험을 줄이는 방법이에요.","w":["에스크로 계좌의 돈은 사업 참여자 모두가 동의해야 인출할 수 있어 자금 유용을 막아요.","인허가 지연 같은 사건이 생기면 시공사가 채무를 인수하도록 걸어 두는 트리거 조건이에요.","부지에 대한 담보권 확보는 기본적인 채권 보전 장치예요.",null],"k":"땅을 여러 조각으로 나눠 사면 마지막 땅 주인이 버티며 값을 올릴 수 있어요. 그래서 한 번에 사야 해요.","m":"PF 위험관리: 부지 일괄 확보 · 담보신탁 · 에스크로 · 시공사 책임준공·채무인수·연대보증 · 트리거 조건 · 선순위 = 금융기관","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","t":"전통 펀드와 헤지펀드 비교","q":"전통적인 공모펀드와 비교한 헤지펀드의 특징으로 가장 적절하지 않은 것은?","o":["벤치마크 대비 초과수익보다 시장 상황과 관계없는 절대수익을 목표로 한다","현금 차입과 주식 대차를 활용해 보유하지 않은 자산도 매도할 수 있다","운용자가 자기 돈을 펀드에 함께 넣으면 이해상충이 생기므로 금지된다","운용 내용 공시의무가 약해 투명성에 한계가 있고 환매가 일정 기간 제한되기도 한다"],"a":2,"c":"헤지펀드는 공매도·차입·파생상품을 자유롭게 써서 시장 방향과 무관한 절대수익을 노려요. 대신 규제가 느슨해 투명성이 낮고, 레버리지 때문에 손실이 커질 수 있어요.","e":"헤지펀드 운용자는 자기 자금을 펀드에 함께 넣는 경우가 많아요. 투자자와 같은 배를 타서 오히려 이해관계를 일치시키는 장치예요.","w":["시장 베타가 낮고 절대수익을 추구하는 것이 헤지펀드의 특징이에요.","프라임브로커를 통한 차입·대차, 파생상품으로 레버리지와 매도 포지션을 만들어요.",null,"공시의무가 약하고, 최초 환매금지기간(락업)이 지난 뒤에도 분기 단위로만 환매를 허용하는 경우가 많아요."],"k":"헤지펀드 매니저는 자기 돈도 같은 배에 싣는 경우가 많아요. 배가 가라앉으면 자기도 손해라 더 신중해져요.","m":"헤지펀드: 절대수익 · 낮은 베타 · 차입·대차·파생 · 운용자 자기자금 투자 · 락업·분기 환매 · 낮은 투명성 · 성과보수","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"상","t":"FTD 스왑 프리미엄 범위","q":"준거자산 X·Y·Z를 묶은 바스켓에 대해 First to Default 거래를 하려고 한다. X·Y·Z의 개별 CDS 프리미엄은 각각 90bp, 60bp, 40bp이다. 세 자산 간 부도 상관관계가 0과 1 사이라면 이 바스켓 스왑의 프리미엄이 놓일 수 있는 범위는?","o":["40bp 초과 90bp 미만","90bp 초과 190bp 미만","40bp 초과 190bp 미만","190bp 초과 270bp 미만"],"a":1,"c":"FTD 스왑은 바스켓 중 첫 번째 부도가 나면 보장매도자가 그 자산을 정산하고 계약이 끝나요. 부도 상관관계가 1이면 가장 위험한 자산의 프리미엄과 같고, 0이면 개별 프리미엄의 합과 같아요.","e":"부도 상관관계가 0과 1 사이이면 FTD 프리미엄은 가장 큰 개별 프리미엄(90bp)보다 크고 개별 프리미엄의 합(190bp)보다 작아요.","w":["가장 낮은 프리미엄을 하한으로 잡았고, 상한도 너무 낮아요. 하한은 가장 높은 개별 프리미엄이에요.",null,"하한을 가장 낮은 프리미엄으로 잡았어요.","합계(190bp)는 하한이 아니라 상한이에요."],"k":"셋 중 하나만 먼저 쓰러져도 보상해야 하니, 가장 위험한 하나를 보장하는 것보다는 비싸고 셋을 따로따로 보장하는 것보다는 싸요.","m":"FTD 프리미엄: 최대 개별 프리미엄 < FTD < 합계 · 상관관계↓ → 프리미엄↑ · 자산 수↑ → 프리미엄↑ · 첫 부도 정산 후 소멸","f":"하한 = 가장 큰 개별 프리미엄 90bp · 상한 = 90 + 60 + 40 = 190bp","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","t":"CDO 트랜치 손실 배분 계산","q":"어느 CDO가 손실을 흡수하는 순서대로 에쿼티 5%, 메자닌 10%, 시니어 25%, 슈퍼시니어 60%의 트랜치로 나뉘어 있다. 기초자산 풀에서 원금의 12%에 해당하는 손실이 생겼을 때 트랜치별 손실 배분을 바르게 설명한 것은?","o":["에쿼티 트랜치는 원금이 모두 없어지고, 메자닌 트랜치는 원금의 70%를 잃는다","모든 트랜치가 원금의 12%씩 똑같이 손실을 본다","슈퍼시니어 트랜치가 가장 먼저 손실을 흡수한다","메자닌 트랜치는 원금이 모두 없어지고 시니어 트랜치도 손실을 본다"],"a":0,"c":"CDO는 손실을 가장 아래 트랜치부터 차례로 떠안아요. 에쿼티는 원금 보장이 없는 대신 잔여 이익을 갖고 기대수익률이 가장 높으며, 위로 갈수록 안전한 대신 금리가 낮아요.","e":"12% 손실 가운데 5%는 에쿼티가 모두 떠안고, 남은 7%를 메자닌이 흡수해요. 메자닌 규모가 10%라서 원금의 70%를 잃고, 시니어 이상은 손실이 없어요.","w":[null,"손실은 비율대로 나누지 않고 아래 트랜치부터 차례로 흡수해요.","슈퍼시니어는 가장 마지막에 손실을 흡수해요.","메자닌이 모두 없어지려면 손실이 15%를 넘어야 해요."],"k":"아래층부터 물이 차오르는 건물과 같아요. 12%만큼 물이 들면 1층(에쿼티)은 잠기고 2층(메자닌)은 70%까지 차요.","m":"손실은 아래부터: 에쿼티 먼저, 다음 메자닌, 그다음 시니어, 마지막 슈퍼시니어 · 시니어도 신용 악화 시 시가평가 손실 가능","f":"에쿼티 5% 전액 손실 → 남은 7%를 메자닌(10%)이 흡수 → 7 ÷ 10 = 70% 손실","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","t":"수익률곡선 스티프너 전략","q":"현재 국고채 3년물 금리는 2.80%, 20년물 금리는 3.40%로 두 금리 차는 60bp다. 채권운용역 을은 경기 회복 기대가 커지면서 이 금리 차가 100bp 수준으로 벌어질 것이라고 본다. 을이 두 종목만으로 이 전망에 투자할 때의 포지션과 전략 이름으로 옳은 것은?","o":["3년물 매수 + 20년물 매도 — 스티프너(Steepener)","3년물 매도 + 20년물 매수 — 스티프너(Steepener)","3년물 매수 + 20년물 매도 — 플래트너(Flattener)","3년물 매도 + 20년물 매수 — 플래트너(Flattener)"],"a":0,"c":"수익률곡선 전략은 장단기 금리 차(곡선의 기울기) 변화에 베팅해요. 금리 차가 벌어질 것으로 보면 스티프너, 좁혀질 것으로 보면 플래트너예요.","e":"금리 차가 커진다는 것은 장기 금리가 단기 금리보다 상대적으로 더 오른다는 뜻이에요. 장기채 가격이 상대적으로 더 떨어지므로 장기채를 팔고 단기채를 사는 스티프너가 맞아요.","w":[null,"이 포지션은 금리 차가 좁혀질 때 이익을 내요.","포지션은 맞지만 이름이 틀렸어요. 금리 차 확대에 거는 전략은 스티프너예요.","금리 차 축소에 거는 플래트너 포지션이에요."],"k":"곡선이 가팔라질(steep) 것 같으면 단기채를 사고 장기채를 팔아요. 평평해질(flat) 것 같으면 반대로 해요.","m":"Steepener = 금리 차 확대 기대: 단기 매수 + 장기 매도 · Flattener = 축소 기대: 단기 매도 + 장기 매수","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"상","t":"Equity 배당률 계산","q":"투자자 병이 물류센터를 80억원에 매입하면서 50억원을 대출받았다. 초년도 순영업소득은 5.6억원이고, 같은 해 대출 원리금 상환액은 2.6억원이다. 병의 Equity 배당률(지분배당률)은 얼마인가? (세금·취득 부대비용은 무시한다)","o":["7.0%","8.7%","10.0%","18.7%"],"a":2,"c":"Equity 배당률은 자기자본 투자자가 첫해에 실제로 손에 쥐는 현금의 수익률이에요. 순영업소득에서 원리금을 갚고 남은 세전현금흐름을 자기자본으로 나눠요.","e":"세전현금흐름 = 5.6억 − 2.6억 = 3.0억원, 자기자본 = 80억 − 50억 = 30억원이라 3.0 ÷ 30 = 10.0%예요.","w":["순영업소득을 매입가격으로 나눈 자본환원율(Cap rate)이에요.","원리금 상환액을 자기자본으로 나눴어요.",null,"원리금을 빼지 않고 순영업소득을 자기자본으로 나눴어요."],"k":"대출을 갚고 남은 돈 3억원을 내 돈 30억원으로 나누면, 내 돈이 1년에 10%를 벌어 준 셈이에요.","m":"Equity 배당률 = (순영업소득 − 원리금 상환액) ÷ 자기자본 · Cap rate = 순영업소득 ÷ 매입가격","f":"(5.6 − 2.6) ÷ (80 − 50) = 3.0 ÷ 30 = 10.0%","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","t":"CDO 신용등급 평가와 발행 목적","q":"CDO를 설명한 〈보기〉에서 맞는 것만 묶은 것은?\nㄱ. CDO 신용등급을 매길 때는 기초자산의 질, 거래구조와 신용보강 수준, 자산운용 매니저의 역량을 함께 본다.\nㄴ. 발행 창구인 SPV가 재무적으로 얼마나 튼튼한지가 등급을 가르는 핵심이다.\nㄷ. 은행이 보유 대출을 넘겨 자기자본비율을 높이려고 발행하면 Balance sheet CDO, 기초자산 수익률과 조달금리의 차이를 노리면 Arbitrage CDO이다.\nㄹ. 메자닌 트랜치는 약정 이자에 더해 에쿼티 트랜치처럼 잔여이익도 나누어 받는다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"CDO는 회사채·대출을 모아 트랜치로 나눠 발행하는 유동화증권이에요. SPV는 껍데기 회사라서 등급은 SPV가 아니라 기초자산과 구조로 매겨요. 발행 목적에 따라 위험 전가형(Balance sheet)과 차익거래형(Arbitrage)으로 나누고, Single tranche나 Market value 같은 이름은 구조·운용 방식에 따른 구분이에요.","e":"ㄱ은 CDO 등급 평가 요소, ㄷ은 목적별 구분을 바르게 설명했어요.","w":["ㄴ은 틀렸어요. SPV는 도관일 뿐이라 재무건전성은 등급 평가 요소가 아니에요.",null,"ㄴ·ㄹ 모두 틀렸어요.","ㄹ은 틀렸어요. 잔여이익은 원금 보장이 없는 에쿼티 트랜치 몫이고, 메자닌은 약정 이자를 받아요."],"k":"CDO 등급은 '포장 상자(SPV)'가 아니라 '안에 든 물건(기초자산)', '포장 방식(구조·신용보강)', '관리하는 사람(매니저)'을 보고 매겨요.","m":"CDO 등급 = 기초자산 질 · 구조·신용보강 · 매니저 역량(SPV 재무 X) · Balance sheet = 위험전가 · Arbitrage = 금리차 수익 · 잔여이익 = 에쿼티","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","t":"PEF 투자회수 방법의 선호 순서","q":"사모투자펀드(PEF)의 투자회수(Exit) 방법을 설명한 내용 중 틀린 것은?","o":["같은 업종 회사나 새 사업에 진출하려는 회사(전략적 투자자)에 지분을 통째로 파는 방식이 보통 가장 선호된다","IPO는 거래소 심사와 공모를 거쳐야 하고 증시 분위기를 타기 때문에 매각보다 뒤 순위로 꼽힌다","유상감자나 배당으로 회수하면 투자기업의 자금이 빠져나가 장기 성장성이 약해질 수 있다","투자기업에 대한 유상증자나 추가 대출은 돈을 더 넣지 않고도 지분가치를 실현하는 대표적인 회수 방법이다"],"a":3,"c":"PEF는 기업을 사서 가치를 높인 뒤 팔고 나와야(엑시트) 수익이 확정돼요. 선호 순서는 대체로 매각 > IPO > 유상감자·배당이에요.","e":"증자나 추가 대출은 오히려 돈을 더 넣는 것이라 투자회수 방법이 아니에요.","w":["매각은 빠르고 한 번에 회수할 수 있어 가장 선호돼요. 다른 기업이나 다른 PEF에 파는 것도 매각이에요.","IPO는 절차가 길고 시장에 좌우돼 매각 다음 순서예요.","유상감자·배당은 기업 체력을 깎을 수 있어 선호도가 가장 낮아요.",null],"k":"고친 집을 통째로 사 줄 사람(매각)이 제일 좋고, 공개 판매(IPO)는 그다음, 집 안 물건을 빼서 파는 것(감자·배당)은 집을 상하게 해요.","m":"PEF 엑시트: 매각 > IPO > 유상감자·배당 · 증자·추가 대출은 회수 X","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","t":"합병차익거래 포지션 구성","q":"A사가 B사를 흡수합병하면서 B사 주식 1주당 A사 주식 0.5주를 주기로 공시하였다. 현재 A사 주가는 40,000원, B사 주가는 18,000원이다. 헤지펀드가 공시를 확인한 뒤 합병차익거래를 할 때의 포지션으로 가장 적절한 것은?","o":["A사 주식 500주 매수 + B사 주식 1,000주 공매도","A사 주식 1,000주 매수 + B사 주식 500주 공매도","B사 주식 1,000주 매수 + A사 주식 1,000주 공매도","B사 주식 1,000주 매수 + A사 주식 500주 공매도"],"a":3,"c":"합병이 공시되면 피인수기업 주가는 교환비율로 계산한 가치보다 조금 낮게 거래되는 경우가 많아요. 피인수기업 주식을 사고 인수기업 주식을 교환비율만큼 공매도해 이 차이(스프레드)를 얻는 전략이에요. 포지션은 합병이 공시로 확정된 다음에 잡아요.","e":"B사 1주는 A사 0.5주(20,000원)로 바뀌는데 지금은 18,000원이에요. B사 1,000주를 사고 교환비율에 맞춰 A사 500주를 공매도하면, 합병이 성사될 때 주가 방향과 관계없이 주당 2,000원, 모두 200만원의 스프레드를 얻어요.","w":["매수·매도 방향이 반대예요.","인수기업을 사고 피인수기업을 파는 반대 포지션이에요.","공매도 수량이 교환비율(0.5)에 맞지 않아 A사 주가 변동 위험이 남아요.",null],"k":"곧 'A 쿠폰 0.5장'으로 바뀔 B 쿠폰을 싸게 사 두고, 받게 될 A 쿠폰을 미리 팔아 두는 거예요. 위험은 쿠폰 교환(합병)이 취소되는 경우예요.","m":"합병차익: 공시 후 진입 · 피인수 매수 + 인수 공매도(교환비율만큼) · 위험 = 합병 무산","f":"B 1주 가치 = 40,000 × 0.5 = 20,000원 · 스프레드 = 20,000 − 18,000 = 2,000원 · 1,000주 × 2,000원 = 200만원 · 공매도 수량 = 1,000 × 0.5 = 500주","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","t":"전환사채 차익거래의 포지션과 선호 속성","q":"전환사채 차익거래를 설명한 내용 중 틀린 것은?","o":["저평가된 전환사채를 사고, 주가 위험을 줄이기 위해 델타만큼 기초 주식을 공매도하는 것이 기본 포지션이다","채권 가격의 볼록성이 커서 주가가 오를 때와 내릴 때의 가격 반응이 비대칭적인 전환사채를 선호한다","기초 주식의 변동성이 크고 주식을 빌리기 쉬우며 전환프리미엄이 낮은 전환사채가 유리하다","공매도한 기초 주식의 배당수익률이 높을수록 차익거래자에게 유리하다"],"a":3,"c":"전환사채는 채권에 주식 전환권(콜옵션)이 붙은 증권이에요. 차익거래자는 전환사채를 사고 주식을 공매도해 주가 방향 위험을 줄이고, 변동성에서 수익을 얻어요.","e":"공매도한 주식에서 배당이 나오면 공매도자가 그 배당을 물어줘야 해요. 그래서 배당수익률이 낮은 주식을 선호해요.","w":["CB 매수 + 주식 공매도(델타 헤지)가 기본이에요. 반대로 하거나 둘 다 사면 주가 위험이 헤지되지 않아요.","볼록성이 크면 주가가 오를 땐 많이 오르고 내릴 땐 덜 내려 헤지 포지션에 유리해요.","변동성이 커야 옵션 가치와 감마 수익이 커지고, 대차가 쉬워야 공매도할 수 있어요.",null],"k":"전환사채는 '주식으로 바꿀 수 있는 채권'이에요. 오를 땐 주식처럼, 내릴 땐 채권처럼 움직이는 휘어진 모양(볼록성)이 클수록 차익거래자에게 좋아요.","m":"CB 차익 = CB 매수 + 주식 공매도(델타 헤지) · 선호: 볼록성↑ · 고변동성 · 대차 쉬움 · 저배당 · 낮은 전환프리미엄 · 고유동성","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"상","t":"TRS의 권리 이전 범위와 신용파생의 한계","q":"신용파생상품을 설명한 〈보기〉에서 맞는 것은 몇 개인가?\nㄱ. CDS에서 보장매입자는 프리미엄을 내고 준거자산의 신용위험을 보장매도자에게 넘긴다.\nㄴ. TRS에서 총수익지급자는 준거자산의 이자와 가격 변동분을 넘기고 약정 금리를 받으므로 신용위험과 시장위험을 함께 넘긴다.\nㄷ. TRS를 맺으면 준거자산의 법적 소유권과 의결권도 총수익수취자에게 넘어간다.\nㄹ. 신용파생상품을 이용하면 거래상대방 위험까지 완전히 없앨 수 있다.","o":["1개","2개","3개","4개"],"a":1,"c":"신용파생상품은 대출 같은 자산을 그대로 가진 채 신용위험만 떼어 사고팔게 해 줘요. CDS는 신용위험만 넘기고 신용사건이 생기면 보장매도자가 손실을 메워요. TRS는 준거자산의 총수익(이자 + 가격 변동)을 넘겨요.","e":"ㄱ·ㄴ이 옳아 2개예요. TRS는 현금흐름과 위험만 넘길 뿐 소유권·의결권은 총수익지급자에게 남고, 보장매도자가 약속을 못 지킬 수 있어 거래상대방 위험도 남아요.","w":["ㄴ도 옳아요. TRS는 시장위험까지 넘겨요.",null,"ㄷ은 틀렸어요. TRS는 현금흐름과 위험만 넘기고, 준거자산의 소유권과 의결권은 총수익지급자에게 그대로 남아요. ㄹ도 틀려서 옳은 것은 2개예요.","ㄷ·ㄹ은 틀렸어요."],"k":"TRS는 '집주인은 그대로 두고 집에서 나오는 월세와 집값 변동만 남에게 넘기는 계약'이에요.","m":"CDS = 신용위험만 · TRS = 신용 + 시장위험(총수익), 소유권·의결권 X · 거래상대방 위험은 남음","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":1,"lv":"중","t":"상품연계채권의 특징","q":"원자재 가격에 연동되는 채권(Commodity-Linked Note)을 설명한 내용 중 틀린 것은?","o":["원자재 가격에 따라 이자나 상환금액이 달라지도록 금융공학 구조를 넣은 중기 채무증권이다","원자재 선물에 직접 투자할 때와 달리 투자자가 증거금을 따로 관리할 필요가 없다","발행자가 돈을 갚지 못하면 손실을 볼 수 있어 발행자의 신용위험을 진다","원자재 실물을 직접 사서 보관하는 방식이라 보관비와 운송비를 투자자가 부담한다"],"a":3,"c":"원자재에 투자하는 방법에는 실물 매입, 선물, 원자재 펀드·ETF, 원자재 관련 기업 주식, 상품연계채권 등이 있어요. 상품연계채권은 채권 형태로 원자재 가격 움직임을 받아요.","e":"상품연계채권은 채권이라 투자자가 실물을 보관할 필요가 없어요. 보관·운송비 부담은 실물 투자의 단점이에요.","w":["원자재 가격에 연동된 중기 채무증권이에요. 공개시장에서 얻기 어려운 추가수익을 노릴 수도 있어요.","채권을 사는 것이라 선물 증거금을 넣고 관리할 일이 없어요.","채권이라 발행자 신용위험이 있어요.",null],"k":"금을 직접 금고에 넣는 대신 '금값 따라 이자를 주는 차용증'을 사는 셈이에요. 금고비는 안 들지만 차용증 쓴 사람이 망하면 손해예요.","m":"상품연계채권: 원자재 연동 중기 채무증권 · 롤링·추적오차 위험 X · 발행자 신용위험 O · 실물 보관비 X","rev":0},{"s":2,"sec":"대안투자운용/투자전략","star":1,"lv":"하","t":"부동산금융의 분류","q":"부동산금융의 분류를 설명한 내용 중 틀린 것은?","o":["이미 지어진 오피스 빌딩을 사면서 앞으로 받을 임대료를 상환 재원으로 돈을 빌리는 것은 수익형 부동산금융이다","개인이 살 집을 사면서 그 집을 담보로 은행에서 대출받는 것은 주택금융이다","아파트를 새로 짓는 사업에서 미래 분양수입을 근거로 자금을 조달하는 것은 개발금융(PF)이다","리츠는 연기금 같은 기관만 투자할 수 있어서 개인이 적은 돈으로 부동산에 투자하는 수단이 되지 못한다"],"a":3,"c":"부동산금융은 갚는 재원과 대상에 따라 수익형 부동산금융(임대수익), 주택금융(주택 구입·담보), 개발금융(개발사업의 미래 현금흐름)으로 나눠요.","e":"공모 리츠는 증권시장에 상장되어 개인도 소액으로 사고팔 수 있어요. 부동산 간접투자의 대표적인 통로예요.","w":["임대수익으로 갚는 금융이라 수익형 부동산금융이에요.","주택을 사거나 주택을 담보로 하는 금융은 주택금융이에요.","개발사업 자체의 미래 현금흐름으로 갚는 개발금융이에요.",null],"k":"갚을 돈이 '월세'에서 나오면 수익형, '내 집 마련'이면 주택금융, '앞으로 지어서 팔 돈'이면 개발금융이에요.","m":"부동산금융: 수익형(임대료) · 주택금융(주택 구입·담보) · 개발금융(PF, 분양수입) · 리츠 = 개인 소액투자 가능","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"MSCI 지수","q":"MSCI 지수에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 한국은 MSCI 신흥시장(EM) 지수에 속해 있다.\nㄴ. MSCI 지수는 유동주식 수를 반영한 시가총액 방식으로 산출한다.\nㄷ. 한국은 MSCI 선진국(World) 지수에 포함되어 있다.\nㄹ. 어느 국가의 지수 편입 비중이 커지면 그 시장으로 패시브 자금이 들어올 수 있다.","o":["1개","2개","3개","4개"],"a":2,"c":"MSCI 지수는 글로벌 펀드들이 많이 따라가는 기준지표라서, 국가 분류와 비중이 자금 흐름에 큰 영향을 줘요.","e":"ㄱ, ㄴ, ㄹ이 옳아 3개예요. 한국은 MSCI에서 아직 신흥시장으로 분류되어 선진국 지수에는 포함되어 있지 않아요.","w":["ㄱ, ㄴ, ㄹ 세 개가 옳아요.","ㄹ도 옳은 설명이에요.",null,"ㄷ은 틀렸어요. 한국은 MSCI 신흥시장 지수에 속해요."],"k":"MSCI 지수에서 비중이 커지면 그 지수를 따라 하는 돈이 \"자동으로\" 들어와요.","m":"MSCI: 한국 = EM · 유동시가총액 방식 · 비중↑ → 패시브 자금 유입"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"유로채의 특징","q":"유로채(Eurobond)에 관한 설명으로 가장 적절하지 않은 것은?","o":["표시통화 국가 밖에서 발행되는 채권이다","외국채에 비해 발행 규제와 공시 부담이 적은 편이다","대부분 무기명식으로 발행된다","발행 국가 감독당국에 반드시 등록하고 그 나라 규제를 똑같이 받아야 한다"],"a":3,"c":"국제채권은 외국채와 유로채로 나눠요. 외국채는 \"그 나라 통화로 그 나라에서\", 유로채는 \"표시통화 나라 밖에서\" 발행해요.","e":"유로채는 특정 국가 규제를 덜 받는 역외 채권이라 등록·공시 부담이 적어요. 발행국 규제를 그대로 받는 것은 외국채예요.","w":["표시통화 국가 밖에서 발행되는 것이 유로채예요.","규제가 적은 것이 유로채의 장점이에요.","무기명식 발행이 일반적이에요.",null],"k":"달러 채권을 미국이 아닌 런던에서 발행하면 유로채예요. 미국 규제를 덜 받아요.","m":"외국채 = 그 나라 통화·그 나라 규제 / 유로채 = 역외·규제 적음·무기명"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"미국 국채의 종류","q":"미국 국채에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. T-Bill은 이자를 정기적으로 지급하는 이표채이다.\nㄴ. T-Note는 만기가 1년 초과 10년 이하인 이표채이다.\nㄷ. T-Bond는 만기가 10년을 넘는 장기 국채이다.\nㄹ. TIPS는 물가 상승에 맞춰 원금이 조정되는 물가연동국채이다.","o":["1개","2개","3개","4개"],"a":2,"c":"미국 국채는 만기와 구조에 따라 T-Bill, T-Note, T-Bond, TIPS 등으로 나뉘어요.","e":"ㄴ, ㄷ, ㄹ이 옳아 3개예요. T-Bill은 만기 1년 이하의 할인채라 이표가 없어요.","w":["ㄴ, ㄷ, ㄹ 세 개가 옳아요.","ㄹ도 옳은 설명이에요.",null,"ㄱ은 틀렸어요. T-Bill은 할인채예요."],"k":"Bill은 짧은 \"할인 쿠폰\", Note는 중간, Bond는 긴 채권, TIPS는 물가를 따라가는 채권이에요.","m":"T-Bill(1년↓ 할인) · T-Note(1~10년) · T-Bond(10년↑) · TIPS(물가연동)"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"예탁증서(DR)","q":"예탁증서(DR)에 관한 설명으로 가장 거리가 먼 것은?","o":["DR 투자자는 배당을 반드시 원주 발행국 통화로만 받아야 한다","미국 시장에서 발행되면 ADR, 여러 나라 시장에서 발행되면 GDR이라고 한다","원주를 해외로 옮기지 않고도 해외 투자자가 거래할 수 있게 해 준다","발행회사의 원주를 예탁기관에 맡기고 이를 근거로 해외에서 발행하는 증서이다"],"a":0,"c":"DR은 해외 투자자가 외국 주식을 자기 나라 시장에서 편하게 사고팔 수 있도록 만든 대체 증서예요.","e":"DR의 배당은 예탁기관이 DR 표시통화로 바꿔서 지급하는 것이 일반적이에요. 원주 발행국 통화로만 받을 필요가 없어요.","w":[null,"ADR과 GDR 구분이 맞아요.","원주 이동 없이 해외 거래가 가능해요.","원주를 예탁하고 발행하는 것이 DR이에요."],"k":"한국 회사 주식을 미국에서 달러로 사고팔 수 있게 만든 \"교환권\"이라고 생각하면 돼요.","m":"DR: 원주 예탁 → 해외 발행 · ADR(미국) / GDR(여러 나라)"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"해외투자의 환헤지","q":"해외투자의 환위험 관리에 관한 설명으로 가장 적절하지 않은 것은?","o":["해외 주식을 보유한 국내 투자자는 선물환을 매도해 환율 하락 위험을 줄일 수 있다","통화선물이나 통화스왑으로도 환위험을 줄일 수 있다","현지 주가와 환율이 반대로 움직이는 경향이 있으면 환헤지의 필요성이 줄어든다","해외 주식을 보유한 국내 투자자는 환율 하락에 대비해 선물환을 매수해야 한다"],"a":3,"c":"해외 자산을 가진 국내 투자자는 나중에 외화를 팔아 원화로 바꿔야 해요. 그래서 외화 가치(환율)가 떨어지는 것이 위험이에요.","e":"외화를 나중에 팔 사람이므로 지금 선물환을 \"매도\"해 파는 가격을 고정해야 해요. 선물환 매수는 반대 방향이에요.","w":["선물환 매도가 맞는 헤지 방향이에요.","통화선물·통화스왑도 헤지 수단이에요.","주가와 환율이 반대로 움직이면 자연스럽게 위험이 줄어요.",null],"k":"나중에 달러를 팔 사람은 \"지금 미리 팔 가격을 정해 두는 것(선물환 매도)\"이 안전해요.","m":"해외자산 보유 → 외화 선물환 매도로 헤지"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"국제분산투자의 효과","q":"국제분산투자에 관한 설명으로 가장 적절하지 않은 것은?","o":["국가 간 주식시장의 상관관계가 낮을수록 분산효과가 크다","국내 투자만으로는 없앨 수 없는 국내 체계적 위험의 일부를 줄일 수 있다","세계 금융시장의 통합이 진행될수록 분산효과는 줄어드는 경향이 있다","금융위기 때 국가 간 상관관계가 낮아져 분산효과가 더 커진다"],"a":3,"c":"국제분산투자는 서로 다르게 움직이는 여러 나라 시장에 나눠 투자해 위험을 줄여요.","e":"금융위기 때는 여러 나라 시장이 함께 급락해 상관관계가 높아지고, 오히려 분산효과가 필요한 순간에 줄어드는 경향이 있어요.","w":["상관관계가 낮을수록 좋아요.","한 나라의 체계적 위험은 다른 나라에서는 분산될 수 있어요.","시장 통합 → 상관관계 상승이에요.",null],"k":"비가 크게 오면 모든 우산이 젖어요.","m":"국제분산: 낮은 상관관계 / 위기 시 상관관계↑ · 시장 통합 → 효과↓"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"홈바이어스","q":"투자자가 국제분산투자의 이점에도 불구하고 자국 자산에 지나치게 많이 투자하는 현상은?","o":["생존자 편의","캘린더 효과","역선택","홈바이어스(home bias)"],"a":3,"c":"이론상 세계 시가총액 비중만큼 담는 게 효율적이지만, 실제로는 자국 비중이 훨씬 높아요.","e":"자국 자산을 과도하게 보유하는 현상을 홈바이어스라고 해요. 정보 비대칭, 거래비용, 환위험, 친숙함 등이 원인이에요.","w":["살아남은 대상만 보는 편의예요.","특정 시기 수익률 이상현상이에요.","정보 비대칭으로 불리한 상대만 남는 현상이에요.",null],"k":"익숙한 동네 가게만 가는 것과 비슷해요.","m":"홈바이어스 원인: 정보비대칭·거래비용·환위험·제도·친숙함"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"환율을 반영한 해외투자 수익률","q":"미국 주식에 투자해 달러 기준 10% 수익을 냈고, 같은 기간 원/달러 환율이 5% 하락했다. 원화 기준 수익률에 가장 가까운 것은?","o":["4.5%","5.0%","15.0%","15.5%"],"a":0,"c":"해외투자 원화 수익률은 현지 수익률과 환율 변동률을 곱해서 구해요.","e":"(1 + 0.10) × (1 − 0.05) − 1 = 1.045 − 1 = 4.5%예요. 근사적으로는 10% − 5% = 5%이지만 정확히는 4.5%예요.","w":[null,"교차항을 무시한 근사치예요.","환율 하락을 더했어요.","환율 하락을 이익으로 계산했어요."],"k":"주식으로 10% 벌었지만, 달러 값이 5% 떨어져서 일부를 잃었어요.","m":"원화 수익률 = (1 + 현지수익률)(1 + 환율변동률) − 1","f":"1.1 × 0.95 − 1 = 4.5%"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"국가위험","q":"해외투자 시 고려하는 국가위험(country risk)에 해당하지 않는 것은?","o":["외환 송금 제한","자산 국유화·몰수","정권 교체에 따른 정책 급변","투자 대상 기업의 개별 신제품 실패"],"a":3,"c":"국가위험은 투자 대상 나라의 정치·경제·제도 때문에 생기는 위험이에요.","e":"개별 기업의 신제품 실패는 그 기업 고유의 위험(비체계적 위험)이에요.","w":["송금 제한은 국가위험이에요.","국유화는 국가위험이에요.","정치 위험이에요.",null],"k":"\"그 나라라서\" 생기는 위험인지, \"그 회사라서\" 생기는 위험인지 구분해요.","m":"국가위험: 송금 제한 · 국유화 · 정치 불안 · 외채 위기"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"이머징마켓 투자의 특징","q":"신흥시장(이머징마켓) 투자의 일반적 특징으로 가장 적절하지 않은 것은?","o":["높은 경제성장 잠재력","높은 변동성","선진시장보다 낮은 유동성","선진시장보다 높은 정보 투명성과 낮은 거래비용"],"a":3,"c":"신흥시장은 성장성이 높은 대신 위험도 커요.","e":"신흥시장은 대체로 정보 투명성이 낮고 거래비용이 높은 편이에요.","w":["성장 잠재력이 커요.","변동성이 커요.","유동성이 낮은 편이에요.",null],"k":"빠르게 크지만, 그만큼 덜 정비된 시장이에요.","m":"신흥시장: 고성장 · 고변동 · 저유동성 · 낮은 투명성 · 높은 거래비용"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"MSCI 시장 분류 기준","q":"MSCI가 국가를 선진·신흥·프런티어 시장으로 분류할 때 고려하는 요소로 가장 적절하지 않은 것은?","o":["경제 발전 수준","시장 규모와 유동성","외국인 투자자의 시장 접근성","해당 국가의 인구 증가율"],"a":3,"c":"MSCI는 경제 수준만이 아니라 외국인이 실제로 투자하기 쉬운지를 중요하게 봐요.","e":"시장 분류는 경제 발전 수준, 시장 규모·유동성, 시장 접근성(외국인 소유 제한, 외환 거래 자유도, 제도 등)으로 판단해요. 인구 증가율은 기준이 아니에요.","w":["분류 기준이에요.","분류 기준이에요.","핵심 기준이에요.",null],"k":"\"외국인이 얼마나 쉽게 사고팔 수 있나\"가 중요한 잣대예요.","m":"MSCI 분류: 경제 발전 · 규모·유동성 · 시장 접근성"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"지수 편입과 자금 흐름","q":"어느 나라가 MSCI 신흥시장 지수에서 선진시장 지수로 옮겨 갈 때 예상되는 현상으로 가장 적절한 것은?","o":["해당 국가 주식은 어떤 지수 추종 자금도 받지 못한다","신흥시장 지수 내 비중이 더 커진다","신흥시장 추종 자금은 빠져나가고 선진시장 추종 자금이 들어와, 지수 내 비중이 작아져도 자금 유출입이 함께 일어난다","지수 이동은 자금 흐름에 아무 영향이 없다"],"a":2,"c":"지수를 그대로 따라가는 패시브 자금은 지수 구성이 바뀌면 그에 맞춰 사고팔아요.","e":"신흥시장을 추종하던 자금은 빠지고 선진시장 추종 자금이 새로 들어와요. 선진시장 지수 안에서는 비중이 작아질 수 있어요.","w":["선진시장 추종 자금을 받아요.","신흥시장 지수에서는 빠져요.",null,"패시브 자금 흐름에 영향을 줘요."],"k":"반이 바뀌면 그 반 담임(추종 자금)도 바뀌어요.","m":"지수 편입·편출 → 패시브 자금 유출입"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"외국채의 명칭","q":"외국 기업이 미국 시장에서 달러로 발행하는 외국채의 명칭은?","o":["양키본드","사무라이본드","불독본드","아리랑본드"],"a":0,"c":"외국채는 발행 국가 통화로, 그 나라 시장에서 외국 기업이 발행하는 채권이에요. 나라마다 별명이 있어요.","e":"미국에서 달러로 발행하는 외국채는 양키본드예요. 일본(엔) 사무라이, 영국(파운드) 불독, 한국(원) 아리랑본드예요.","w":[null,"일본 엔화 외국채예요.","영국 파운드 외국채예요.","한국 원화 외국채예요."],"k":"미국 = 양키예요.","m":"양키(미국) · 사무라이(일본) · 불독(영국) · 아리랑(한국) · 판다(중국)"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"김치본드","q":"국내 시장에서 원화가 아닌 외화(예: 달러)로 표시해 발행하는 채권은?","o":["아리랑본드","양키본드","김치본드","딤섬본드"],"a":2,"c":"국내에서 발행되더라도 표시 통화가 무엇인지에 따라 이름이 달라져요.","e":"국내에서 외화로 발행하는 채권은 김치본드예요. 외국 기업이 국내에서 원화로 발행하면 아리랑본드예요.","w":["국내에서 원화로 발행하는 외국채예요.","미국 달러 외국채예요.",null,"홍콩에서 위안화로 발행하는 채권이에요."],"k":"한국 시장 + 외화 표시 = 김치본드, 한국 시장 + 원화 = 아리랑본드예요.","m":"김치본드 = 국내 · 외화표시 / 아리랑본드 = 국내 · 원화 · 외국 발행자"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"글로벌본드","q":"여러 나라 시장에서 동시에 발행·유통되며 유로채와 외국채의 성격을 함께 가진 채권은?","o":["글로벌본드","양키본드","쿠폰채","전환사채"],"a":0,"c":"대형 발행자는 한 번에 여러 시장에서 채권을 팔기도 해요.","e":"미국, 유럽, 아시아 등 여러 시장에서 동시에 발행·유통되는 채권은 글로벌본드예요.","w":[null,"미국 시장 외국채예요.","이자 지급 방식에 따른 분류예요.","주식 전환권이 붙은 채권이에요."],"k":"한 번에 세계 여러 시장에서 파는 채권이에요.","m":"글로벌본드 = 다수 시장 동시 발행·유통"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"ADR 가격 계산","q":"1 ADR이 국내 주식 4주를 나타낸다. 국내 주가가 30,000원, 원/달러 환율이 1,200원일 때 ADR의 이론가격은?","o":["25달러","100달러","144달러","6.25달러"],"a":1,"c":"ADR 가격은 대응하는 원주 가치를 달러로 바꾼 값이에요.","e":"원주 가치 = 30,000 × 4 = 120,000원, 달러 환산 = 120,000 ÷ 1,200 = 100달러예요.","w":["1주 기준으로 계산했어요.",null,"원화 가치를 환율로 나누지 않고 환율을 곱하는 식으로 계산했어요. 달러로 바꾸려면 환율로 나눠요.","4주를 곱하지 않고 나눴어요(30,000 ÷ 4 ÷ 1,200 = 6.25달러)."],"k":"주식 4주 = 12만원, 환율로 나누면 100달러예요.","m":"ADR 가격 = 주가 × 교환비율 ÷ 환율","f":"30,000 × 4 ÷ 1,200 = 100달러"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"ADR 레벨","q":"미국 증권거래소에 상장하면서 신주를 발행해 자금을 조달할 수 있는 ADR은?","o":["레벨 1 ADR","레벨 2 ADR","레벨 3 ADR","사모 ADR(Rule 144A)"],"a":2,"c":"ADR은 상장 여부와 자금 조달 가능 여부에 따라 레벨이 나뉘어요.","e":"레벨 3 ADR은 미국 거래소에 상장하고 공모로 신규 자금을 조달할 수 있어요. 레벨 1은 장외 거래, 레벨 2는 상장하지만 신규 자금 조달은 하지 않아요.","w":["장외(OTC) 거래만 가능해요.","상장하지만 신규 자금 조달은 없어요.",null,"적격 기관투자자 대상 사모 발행이에요."],"k":"숫자가 커질수록 공시 부담과 할 수 있는 일이 커져요.","m":"ADR 레벨1 = 장외 · 레벨2 = 상장 · 레벨3 = 상장 + 신규 자금조달"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"통화옵션을 이용한 환헤지","q":"달러 자산을 가진 국내 투자자가 환율 하락(달러 약세) 위험은 막으면서 환율 상승 시 이익 기회는 남겨 두고 싶다. 가장 적절한 방법은?","o":["달러 풋옵션 매수","달러 선물환 매도","달러 콜옵션 매도","달러 선물 매수"],"a":0,"c":"선물환은 손실과 이익을 모두 고정하지만, 옵션은 프리미엄을 내고 한쪽 위험만 막을 수 있어요.","e":"달러 풋옵션을 사면 환율이 떨어질 때 행사가격에 달러를 팔 수 있어 손실을 막고, 환율이 오르면 행사하지 않아 이익을 누릴 수 있어요. 대신 프리미엄을 내요.","w":[null,"환율 상승 이익까지 포기해요.","프리미엄만 받고 하락 위험은 남아요.","달러 롱 위험이 더 커져요."],"k":"보험료(프리미엄)를 내고 \"떨어질 때만\" 보호받아요.","m":"달러 롱 헤지: 선물환 매도(양방향 고정) · 풋 매수(하방만 보호, 프리미엄 비용)"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"구매력평가이론","q":"한국의 기대 물가상승률이 연 4%, 미국이 연 1%일 때 상대적 구매력평가이론에 따른 원/달러 환율 변화로 가장 적절한 것은?","o":["원/달러 환율이 약 3% 오른다(원화 약세)","원/달러 환율이 약 3% 내린다(원화 강세)","원/달러 환율이 약 5% 오른다","환율은 변하지 않는다"],"a":0,"c":"구매력평가이론은 물가가 더 많이 오르는 나라의 통화 가치가 그만큼 떨어진다고 봐요.","e":"물가상승률 차이 4% − 1% = 3%만큼 원화 가치가 떨어져, 원/달러 환율이 약 3% 올라요.","w":[null,"방향이 반대예요.","두 물가상승률을 더했어요.","물가 차이만큼 변해요."],"k":"한국 물건값이 더 빨리 오르면 원화 1원의 힘이 약해져요.","m":"상대 PPP: 환율 변화율 ≈ 국내 물가상승률 − 해외 물가상승률","f":"4% − 1% = 3% 원화 약세"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"국제피셔효과","q":"두 나라 명목금리 차이가 미래 환율 변화율과 같아진다는 이론은?","o":["국제피셔효과","헥셔-올린 정리","리카도의 비교우위론","레온티예프의 역설"],"a":0,"c":"환율 결정 이론에는 금리와 물가를 이용한 여러 평가이론이 있어요.","e":"명목금리 차이가 기대 환율 변화율과 같아진다는 것은 국제피셔효과예요. 금리가 높은 나라의 통화는 그만큼 약세가 예상돼요.","w":[null,"생산요소 부존량으로 무역 패턴을 설명해요.","비교우위로 무역 이익을 설명해요.","헥셔-올린 정리에 반하는 실증 결과예요."],"k":"이자를 더 주는 나라 돈은 그만큼 값이 떨어질 거라고 봐요.","m":"국제피셔효과: 기대 환율변화율 = 명목금리 차이"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"헥셔-올린 정리","q":"각 나라는 상대적으로 풍부한 생산요소를 많이 사용하는 재화를 수출한다는 무역 이론은?","o":["헥셔-올린 정리","리카도의 비교우위론","구매력평가이론","국제피셔효과"],"a":0,"c":"무역이 왜 생기는지 설명하는 대표적 이론들이 있어요.","e":"노동이 풍부한 나라는 노동집약재를, 자본이 풍부한 나라는 자본집약재를 수출한다는 것이 헥셔-올린 정리(요소부존이론)예요.","w":[null,"노동생산성 차이에 따른 비교우위를 강조해요.","환율 이론이에요.","금리와 환율의 관계예요."],"k":"사람이 많은 나라는 사람 손이 많이 가는 물건을 수출해요.","m":"헥셔-올린 = 요소부존 · 리카도 = 노동생산성 비교우위"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"환헤지 비용과 금리차","q":"원화 금리가 달러 금리보다 낮은 상황에서 달러 자산을 선물환 매도로 헤지할 때의 효과로 가장 적절한 것은?","o":["선물환율이 현물환율보다 낮아 헤지 비용(손실)이 발생한다","선물환율이 현물환율보다 높아 헤지 프리미엄(이익)이 발생한다","금리차와 헤지 비용은 관계없다","헤지 비용이 항상 0이다"],"a":0,"c":"이자율평가에 따르면 선물환율은 두 나라 금리차를 반영해요.","e":"원화 금리 < 달러 금리면 선물환율이 현물환율보다 낮게(달러 할인) 형성되어, 달러를 선물환으로 팔면 그만큼 헤지 비용이 생겨요.","w":[null,"원화 금리가 더 높을 때예요.","금리차가 헤지 비용을 결정해요.","금리차가 있으면 0이 아니에요."],"k":"달러 이자를 더 받는 만큼, 미리 팔 때는 더 싸게 팔아야 해요.","m":"원화 금리 < 달러 금리 → 선물환 할인 → 매도 헤지 비용 발생"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"통화스왑","q":"두 당사자가 서로 다른 통화의 원금과 이자를 교환하는 거래로, 외화 차입의 환위험을 장기적으로 관리하는 데 쓰이는 것은?","o":["통화스왑","금리스왑","신용부도스왑","주식스왑"],"a":0,"c":"스왑은 미래 현금흐름을 교환하는 계약이에요. 교환 대상에 따라 종류가 나뉘어요.","e":"서로 다른 통화의 원금과 이자를 교환하는 것은 통화스왑이에요. 보통 만기에 원금을 다시 교환해요.","w":[null,"같은 통화의 고정·변동 금리를 교환해요.","신용위험을 이전해요.","주식 수익을 교환해요."],"k":"달러 빚과 원화 빚을 서로 바꿔 갚는 거예요.","m":"통화스왑 = 이종통화 원금 + 이자 교환"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"ADR 차익거래","q":"1 ADR = 원주 2주이다. 원주 가격 40,000원, 원/달러 환율 1,250원일 때 ADR이 뉴욕에서 70달러에 거래되고 있다. 거래비용이 없다면 차익거래 전략으로 가장 적절한 것은?","o":["ADR 매도 + 국내 원주 매수","ADR 매수 + 국내 원주 매도","ADR과 원주 모두 매수","차익거래 기회가 없다"],"a":0,"c":"ADR 이론가격은 원주 가치를 달러로 바꾼 값이에요. 시장가격이 이보다 높으면 ADR이 비싼 거예요.","e":"이론가격 = 40,000 × 2 ÷ 1,250 = 64달러예요. ADR이 70달러로 비싸므로 ADR을 팔고 싼 원주를 사서 ADR로 전환하면 차익을 얻어요.","w":[null,"반대 방향이에요.","가격 차이를 이용하지 못해요.","6달러 차이가 있어요."],"k":"같은 물건이 뉴욕에서 6달러 더 비싸요. 비싼 곳에서 팔고 싼 곳에서 사요.","m":"ADR 이론가 = 원주가 × 비율 ÷ 환율 · 비싼 쪽 매도 · 싼 쪽 매수","f":"80,000 ÷ 1,250 = 64달러 < 70달러"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"해외주식 양도소득세 계산","q":"국내 거주자 A가 올해 미국 상장주식을 팔아 양도차익 2,050만원을 얻었다. 필요경비는 이미 빼 준 금액이며 그 해의 다른 양도소득은 없다. A가 내야 할 양도소득세(지방소득세 포함)는? (단, 감면 특례는 고려하지 않는다)","o":["451만원","360만원","396만원","410만원"],"a":2,"c":"해외주식을 직접 사고판 이익은 양도소득이에요. 1년에 250만원을 빼 준 나머지에 22%(양도소득세 20% + 지방소득세 2%)를 매겨요.","e":"과세표준 = 2,050만원 − 250만원 = 1,800만원이고, 세액 = 1,800만원 × 22% = 396만원이에요. 이듬해 5월에 직접 신고·납부해요. 참고로 국내에서 설정된 해외주식형 펀드의 환매이익은 양도소득이 아니라 배당소득(15.4%)으로 과세돼요.","w":["기본공제 250만원을 빼지 않고 22%를 곱했어요.","지방소득세 2%를 빠뜨리고 20%만 곱했어요.",null,"기본공제도 빼지 않고, 지방소득세도 빠뜨렸어요."],"k":"1년에 250만원까지는 '세금 없는 구간'이고, 그 위로 번 돈에만 22%를 떼요.","m":"해외주식 양도세 = (양도차익 − 250만원) × 22%","f":"(2,050 − 250) × 0.22 = 396만원"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"환헤지 기법의 구분","q":"환위험 헤지 방법에 관한 설명으로 가장 적절한 것은?","o":["롤링헤지는 투자기간과 만기가 같은 장기 계약 한 건으로 전체 기간을 한 번에 헤지하는 방법이다","내재적 헤지는 통화선물을 따로 매도해 환노출을 줄이는 방법이다","최소분산헤지는 현물 가격과 선물 가격의 관계를 통계적으로 추정해 헤지 후 분산이 가장 작아지는 헤지비율을 찾는 방법이다","내재적 헤지는 투자국 통화의 가치와 현지 주가가 같은 방향으로 움직일 때 잘 작동한다"],"a":2,"c":"환헤지에는 계약을 맺는 방식(선물환·롤링헤지·최소분산헤지)도 있고, 따로 계약 없이 자산의 성질 때문에 환위험이 줄어드는 내재적 헤지도 있어요.","e":"최소분산헤지는 현물 가격과 선물 가격의 움직임을 회귀분석 등으로 추정해, 헤지한 뒤 포트폴리오 분산이 최소가 되는 비율만큼 선물을 거래하는 방법이에요.","w":["롤링헤지는 만기가 투자기간보다 짧은 계약을 만기 때마다 갈아타며 이어 가는 방법이에요. 거래가 쉬운 대신 헤지효과는 만기를 맞춘 계약보다 약해요.","내재적 헤지는 따로 계약을 맺지 않아요. 통화가치와 주가가 반대로 움직여 환손익과 주가손익이 저절로 상쇄되는 효과예요.",null,"내재적 헤지는 통화가치와 주가가 음(−)의 관계일 때 작동해요. 같은 방향이면 환손실과 주가손실이 겹쳐요."],"k":"롤링헤지는 짧은 우산을 계속 바꿔 쓰는 것, 내재적 헤지는 우산 없이도 비를 덜 맞는 체질이에요.","m":"롤링 = 단기계약 이어 붙이기 · 내재적 = 통화·주가 음(−)의 관계 · 최소분산 = 분산 최소 헤지비율"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"해외펀드 환위험 관리 실무","q":"해외주식형 펀드의 환위험 관리에 관한 설명으로 가장 적절하지 않은 것은?","o":["현지 주식을 직접 사는 대신 현지 주가지수선물을 사 두면 증거금을 뺀 나머지 돈은 원화로 운용할 수 있어 환노출이 줄어든다","환위험을 기꺼이 떠안을 투자자라면 허용위험한도(익스포저 한도)를 높게 잡는다","선물환으로 헤지하더라도 계약 기간 중 환율 변동에 따라 평가손익이 생기고, 상대방이 담보나 증거금을 요구할 수 있다","실무에서 대부분의 국제투자펀드는 환노출을 100% 헤지해 환율 영향을 완전히 없애는 것을 원칙으로 한다"],"a":3,"c":"해외펀드는 감수할 환위험의 크기를 미리 한도로 정해 두고, 선물환·통화선물·주가지수선물 같은 수단으로 관리해요.","e":"실제로는 많은 국제투자펀드가 환위험을 아예 헤지하지 않거나 일부만 헤지해요. 헤지 비용이 들고, 주요 통화가 아니면 파생상품의 유동성이 부족하고 거래비용도 높기 때문이에요.","w":["주가지수선물은 증거금만 현지 통화로 내면 되므로 나머지 돈은 원화로 운용할 수 있어 환노출이 작아져요.","허용위험한도는 감수하기로 한 환위험의 크기라서, 위험을 더 지려는 투자자일수록 높게 잡아요.","선물환도 계약 기간 중 환율이 움직인 만큼 평가손익이 쌓이고, 거래상대방이 담보나 증거금을 요구할 수 있어요.",null],"k":"환헤지는 공짜 보험이 아니라서, 많은 펀드가 전부 들지 않고 일부만 들어요.","m":"환위험 관리: 한도 먼저 · 무헤지·부분헤지가 흔함 · 지수선물 활용 시 환노출↓"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"벤치마크 복제 방법","q":"국제 포트폴리오를 벤치마크 지수에 맞춰 소극적으로 운용할 때 쓰는 복제 방법에 관한 설명으로 가장 적절한 것은?","o":["완전복제법은 지수에 들어 있는 종목 전부를 편입하므로 추적오차는 작지만 거래비용과 관리 부담이 크다","부분복제법은 일부 종목만 담으므로 완전복제법보다 추적오차가 더 작아진다","최적화법은 과거 데이터로 만든 통계 모형에 의존하므로 모형이 틀려도 추적오차는 늘지 않는다","소극적 운용은 벤치마크와 관계없이 절대수익률을 최대로 높이는 것이 목표다"],"a":0,"c":"패시브 운용은 벤치마크를 얼마나 똑같이 따라가는지(추적오차)가 핵심이에요. 복제 방식에 따라 비용과 추적오차가 서로 맞바뀌어요.","e":"완전복제법은 지수의 모든 종목을 지수 비중대로 담아 추적오차가 가장 작아요. 대신 편입 종목 수가 많아서 매매 비용과 관리 부담이 커요.","w":[null,"부분복제법은 일부 종목만 담아 비용은 줄지만 추적오차는 커져요.","최적화법은 모형에 의존하므로 모형이 현실과 어긋나면 추적오차가 커져요.","소극적 운용은 낮은 비용으로 벤치마크 수익률을 따라가는 것이 목표예요."],"k":"완전복제는 원본을 통째로 베끼기, 부분복제는 요약본 만들기예요. 요약할수록 싸지만 원본과 차이가 나요.","m":"완전복제: 추적오차↓ 비용↑ · 부분복제·최적화: 비용↓ 추적오차↑"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"상","rev":0,"t":"시장 통합화와 동조화","q":"국제 자본시장의 통합화와 각국 주가의 동조화에 대한 설명으로 가장 적절하지 않은 것은?","o":["두 나라 시장이 분리되어 있다면, 미국 투자자는 한국주식의 체계적 위험을 미국 시장포트폴리오와의 관계로 잰다","투자자들이 여전히 자국 주식을 지나치게 많이 보유하는 현상은 시장이 완전히 통합되지 않았다는 근거가 된다","각국 주가가 함께 움직이는 동조화가 나타났다면 두 시장은 반드시 완전히 통합된 것이다","시장이 통합되었다는 것은 국경과 관계없이 같은 위험에 같은 기대수익률이 매겨진다는 뜻이다"],"a":2,"c":"통합화는 '같은 위험엔 같은 값'이 붙는 상태이고, 동조화는 각국 주가가 '같이 움직이는' 현상이에요.","e":"동조화는 유가나 미국 금리 같은 세계 공통 요인 때문에도 생겨서, 시장이 통합되지 않아도 나타날 수 있어요. 그래서 두 개념은 달라요. 다만 동조화가 강해지면 국제분산투자 효과는 줄어들어요.","w":["분리된 시장에서는 투자자가 이미 가진 본국 시장포트폴리오가 기준이에요. 그래서 미국 투자자는 한국주식과 미국 시장의 상관관계로 체계적 위험을 재요.","외국주식 비중이 여전히 낮은 자국편향은 환위험·정보비용·제도 차이가 남아 있다는 뜻이라, 시장이 덜 통합되었다는 근거예요.",null,"통합된 시장에서는 일물일가가 성립해 같은 위험에 같은 기대수익률이 매겨져요."],"k":"같이 춤춘다고(동조화) 같은 학교(통합)에 다니는 건 아니에요.","m":"통합화 = 같은 위험 같은 수익(제도) · 동조화 = 같이 움직임(상관) → 별개 개념"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"하향식·상향식과 운용 스타일","q":"국제 주식 포트폴리오 운용에 관한 설명으로 가장 적절하지 않은 것은?","o":["하향식 접근은 세계 경제를 나라별로 나뉜 경제들의 모음으로 보고, 국가 배분 → 산업 → 종목 순으로 내려간다","상향식 접근은 세계 경제를 글로벌화된 산업들의 집합으로 보고, 경쟁력 있는 기업을 고른 결과로 국가 비중이 정해진다","공격적(적극적) 운용은 각국 시장이 서로 밀접하게 통합되어 함께 움직일수록 초과수익을 낼 기회가 커진다","방어적(소극적) 운용은 환율·주가 전망을 포트폴리오에 담지 않고 벤치마크 비중을 그대로 따라간다"],"a":2,"c":"하향식은 '나라 먼저', 상향식은 '기업 먼저'예요. 운용 스타일은 전망을 적극 반영하는 공격적 운용과 벤치마크를 따라가는 방어적 운용으로 나뉘어요.","e":"공격적 운용은 나라마다 시장이 따로 움직일 때, 즉 국제시장이 분리되어 있을 때 국가·통화 선택으로 초과수익을 낼 여지가 커요. 시장이 통합될수록 그런 기회는 줄어요.","w":["하향식은 각국 거시경제를 먼저 분석해 국가 비중을 정한 뒤 산업과 종목으로 내려가요.","상향식에서는 국가 비중이 목표가 아니라 종목 선택의 결과예요.",null,"방어적 운용은 주관적 전망 대신 벤치마크를 모방해 벤치마크와의 성과 차이를 작게 유지하는 데 집중해요."],"k":"하향식은 지도에서 나라부터 찍는 것, 상향식은 맛집(기업)부터 찾고 그 맛집이 있는 나라에 가는 것이에요.","m":"하향식 = 나라별 경제의 모음·국가→산업→종목 · 상향식 = 글로벌 산업 집합 · 공격적 운용은 시장 분리 시 유리"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"유로채의 발행·유통 관행","q":"미달러화 표시 유로채를 설명한 〈보기〉에서 옳은 것만 묶은 것은?\nㄱ. 보통 여러 나라 금융기관으로 꾸려진 국제 인수단이 발행을 맡는다.\nㄴ. 미국 SEC 등록을 거치지 않으므로 발행 직후 일정 기간은 미국 투자자에게 파는 것이 제한된다.\nㄷ. 고정금리 유로채는 보통 이자를 6개월마다 지급하고 실제일수/365 방식으로 계산한다.\nㄹ. 유통 단계에서는 실물을 주고받지 않고 유로클리어 같은 국제 결제기구의 장부로 결제한다.","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1,"c":"유로채는 표시통화 나라 밖에서 발행되는 '역외 채권'이라 규제가 적고, 국제 관행에 따라 발행·결제돼요.","e":"ㄱ, ㄴ, ㄹ이 옳아요. 고정금리 유로채는 보통 연 1회 이자를 주고, 한 달을 30일·1년을 360일로 보는 30/360 방식을 써요. 외국채는 발행국 규제를 받고 기명식이 일반적인 반면, 유로채는 무기명식이 일반적이고 규제 부담이 적어 조달비용도 낮은 편이에요.","w":["ㄹ도 옳아요. 유로채는 국제 결제기구의 장부로 결제해요.",null,"ㄷ은 틀렸어요. 연 1회 지급, 30/360 방식이 일반적이에요.","ㄷ은 틀렸고, ㄴ은 옳은 설명이에요."],"k":"유로채는 '국제 표준 규칙'으로 움직이는 채권이라, 이자도 1년에 한 번, 결제도 장부로 깔끔하게 해요.","m":"유로채: 국제 인수단 · SEC 미등록(미국 판매 제한) · 연 1회·30/360 · 장부결제 · 무기명"},{"s":2,"sec":"해외증권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"글로벌 지수와 한국의 위치","q":"글로벌 주가지수와 채권지수에 관한 설명으로 가장 적절하지 않은 것은?","o":["한국 국채는 아직 FTSE 러셀이 관리하는 WGBI(세계국채지수)에 들어가지 못해 지수 추종 자금의 유입을 기대하기 어렵다","한국은 FTSE 주가지수에서는 선진시장, MSCI 지수에서는 신흥시장으로 분류된다","MSCI 지수는 달러로 계산하므로 국내 주가가 올라도 원화 약세 폭이 더 크면 MSCI 한국지수는 하락할 수 있다","MSCI 지수의 국가별 편입 비중은 각국 주가와 환율이 움직이면서 매일 달라진다"],"a":0,"c":"MSCI·FTSE 주가지수는 주식의, WGBI는 국채의 대표 벤치마크예요. 지수에 들어가면 그 지수를 따라가는 자금이 움직여요.","e":"한국 국채는 2026년 4월부터 11월까지 8개월에 걸쳐 WGBI에 단계적으로 편입되고 있어요. 그래서 이 지수를 따라가는 해외 자금이 들어올 수 있어요.","w":[null,"한국은 FTSE에서는 선진시장, MSCI에서는 아직 신흥시장이에요.","MSCI 지수는 달러로 계산하므로 원화 약세가 크면 원화 기준 주가 상승분이 상쇄될 수 있어요.","달러 기준 시가총액이 매일 바뀌므로 국가별 비중도 매일 달라져요."],"k":"MSCI는 '달러로 찍은 사진'이라, 주가가 웃어도 원화가 울면 사진 속 표정은 어두울 수 있어요.","m":"MSCI = 달러 기준·유동시가총액 · 한국: MSCI 신흥 / FTSE 선진 · WGBI 2026.4~11 단계 편입"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"국제채권 투자 시 고려사항","q":"국제채권 투자에 관한 설명으로 가장 적절하지 않은 것은?","o":["미국 국채는 최고 수준의 안전자산으로 취급되어 발행자 부도위험에 따른 가산금리를 따로 따지지 않는다","미국 외 국가의 채권에서 가산금리가 오르면 보유 채권 가격이 내리고 그 나라 신인도가 떨어졌다는 뜻이다","딤섬본드는 비거주자가 중국 본토 시장에서 발행하는 위안화 외국채이다","딤섬본드는 만기가 짧고 수익률이 낮은 편이어서 수익의 상당 부분이 위안화 환차익에 달려 있다"],"a":2,"c":"국제채권은 금리뿐 아니라 가산금리(신용), 환율, 그리고 발행지와 표시통화의 관계까지 함께 봐야 해요.","e":"딤섬본드는 중국 본토 밖(주로 홍콩)에서 발행되는 위안화 채권이라 유로채로 분류돼요. 비거주자가 중국 본토 시장에서 위안화 표시로 발행하는 외국채는 판다본드예요.","w":["미국 국채는 부도위험이 사실상 없다고 보므로, 연준 금리정책·수익률곡선·수급·달러 움직임 등을 주로 봐요.","가산금리 상승은 위험이 커졌다는 신호라 채권 가격 하락과 국가 신인도 하락을 뜻해요.",null,"딤섬본드는 우량 발행자가 많아 금리가 낮고 만기가 짧아서, 만기까지 보유하며 위안화 강세를 노리는 경우가 많아요."],"k":"딤섬은 홍콩 음식, 판다는 중국 본토 동물이라고 외우면 발행지가 안 헷갈려요.","m":"미국 국채 = 가산금리 X · 딤섬 = 홍콩·유로채 · 판다 = 본토·외국채"},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"DR 발행과 해외 상장의 실제","q":"국내 기업의 예탁증서(DR) 발행과 해외 상장에 관한 설명으로 가장 적절하지 않은 것은?","o":["원주 발행회사가 예탁기관과 계약하고 비용을 대면 스폰서 DR(Sponsored), 발행회사 관여 없이 예탁기관이 스스로 만들면 언스폰서 DR(Unsponsored)이라 한다","DR 보유자는 배당 수령과 의결권 행사를 예탁기관을 통해 간접적으로 한다","해외 증시에 추가로 상장하면 현지 공시 의무가 새로 생기고 상장유지 비용도 늘어난다","DR 발행은 외부 차입에 해당하므로 발행하면 부채비율이 높아진다"],"a":3,"c":"DR은 원주를 국내 보관기관에 맡기고 해외 예탁기관이 그 원주를 대신하는 증서를 발행하는 방식이에요. 기업 입장에서는 해외에서 주식으로 자금을 모으는 거예요.","e":"DR 발행은 빚이 아니라 자기자본 조달이에요. 그래서 오히려 재무구조가 좋아지고, 거래되는 시장이 늘어 유동성과 인지도도 높아져요. 대신 현지 공시 부담과 배당 요구 압력은 커져요.","w":["발행 비용과 절차를 누가 맡느냐에 따라 스폰서 DR과 언스폰서 DR로 나뉘어요.","원주는 국내 보관기관에 있으므로 DR 보유자는 예탁기관을 통해 배당을 받고 의결권을 행사해요.","해외 상장은 홍보효과와 신인도 상승 같은 장점이 있지만, 공시 의무와 상장유지 비용은 오히려 늘어요.",null],"k":"DR은 해외 투자자에게 '우리 회사 주식 교환권'을 파는 것이라, 빚이 아니라 새 주주를 들이는 거예요.","m":"DR = 자기자본 조달 · 의결권·배당은 예탁기관 경유 · 해외 상장 시 공시·유지비용↑"},{"s":2,"sec":"해외증권투자운용/투자전략","star":1,"lv":"중","t":"주식시장 규모와 회전율","q":"국제주식시장을 비교할 때 쓰는 지표와 국제화에 관한 〈보기〉에서 옳은 것만 묶은 것은?\nㄱ. 시가총액에 비해 거래가 많아 회전율이 높은 시장은 짧게 사고파는 투자자의 비중이 큰 편이다.\nㄴ. 한 나라 주식시장의 크기는 상장주식 시가총액 하나로 충분히 판단할 수 있다.\nㄷ. 국내 기업이 외국 거래소에도 함께 상장하는 것은 주식시장 국제화의 한 형태이다.\nㄹ. 기업이 은행 대출에 많이 기댈수록 GDP 대비 시가총액 비중은 높아지는 경향이 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"회전율은 주식이 얼마나 자주 손바뀜되는지 보여 주고, 시장 크기는 시가총액만이 아니라 투자자들이 어떻게 거래하고 누가 주식을 들고 있는지도 함께 봐야 해요.","e":"ㄱ, ㄷ이 옳아요. 시장 규모는 시가총액뿐 아니라 거래행태와 주식 보유 동기·분포도 함께 결정해요. 또 기업이 주식을 발행해 돈을 직접 모으는 비중이 클수록 경제 규모에 견준 시가총액이 커지는 편이에요. 참고로 해외 시장은 언어·회계기준·공시 제도가 달라 정보를 모으는 비용도 더 들어요.","w":["ㄴ은 틀렸어요. 시가총액 말고도 거래행태와 보유 분포를 함께 봐야 해요.",null,"ㄴ, ㄹ은 둘 다 틀린 설명이에요.","ㄹ은 틀렸어요. 은행 대출(간접금융)보다 주식 발행(직접금융) 비중이 클수록 시가총액 비중이 높아져요."],"k":"회전율은 \"손님이 얼마나 자주 바뀌는 가게인가\"예요. 단골이 오래 머무는 가게일수록 회전율이 낮아요.","m":"회전율↑ = 단기매매↑ · 시장 규모 = 시총 + 거래행태 + 보유 분포 · 직접금융↑ → 시총/GDP↑","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","t":"양키본드와 국제채 시장 관행","q":"국제채권에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 양키본드를 발행하려면 미국 감독당국의 공시 규정을 지키고 신용평가도 받아야 해서, 신용도가 낮은 발행자일수록 조달비용이 커진다.\nㄴ. 1984년 미국은 외국인이 받는 채권 이자에 매기던 원천징수세를 없앴다.\nㄷ. 김치본드는 비거주자만 발행할 수 있고 국내 거주자는 발행할 수 없다.\nㄹ. 유로채는 표시통화 국가 밖에서 발행되어 그 나라의 발행 규제를 상대적으로 덜 받는다.","o":["1개","2개","3개","4개"],"a":2,"c":"외국채는 발행국 규제를 그대로 받고, 유로채는 규제가 적은 대신 시장 관행이 촘촘해요. 김치본드는 외국채가 아니라 유로채 성격이에요.","e":"ㄱ, ㄴ, ㄹ이 옳아 3개예요. 김치본드는 한국 안에서 달러 같은 외화로 찍는 채권이라 국내 기업 같은 거주자도 발행할 수 있어요.","w":["옳은 것은 3개예요.","ㄱ·ㄴ·ㄹ 세 개가 옳아요.",null,"ㄷ은 틀렸어요. 김치본드는 거주자도 발행할 수 있어요."],"k":"양키본드는 \"미국 집에 들어가 미국 규칙을 지키는 손님\"이고, 김치본드는 \"한국 집에서 달러로 차려 낸 상\"이라 집주인(거주자)도 낼 수 있어요.","m":"양키본드: SEC 공시·신용평가, 1984 원천징수 폐지 · 김치본드: 거주자도 발행 · 유로채 시장조성자 = 매일 호가","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","t":"ADR·EDR·GDR과 상장비용","q":"국내 기업의 해외 상장 방식에 관한 설명으로 가장 적절하지 않은 것은?","o":["예탁증서 없이 원주 자체를 해외 거래소에 올리는 원주상장도 있지만, 한국 기업은 주로 예탁증서 방식을 쓴다","미국 시장에 올리면 ADR, 유럽 등 미국 밖 시장에 올리면 EDR, 미국과 그 밖의 시장에 동시에 올리면 GDR이라 부른다","예탁증서는 상장 시장의 통화로 표시되므로 현지 투자자가 익숙한 통화와 결제 방식으로 거래할 수 있다","상장비용만 놓고 보면 미국 증시가 미국 밖 시장보다 싸기 때문에 대부분의 기업이 미국 상장을 고른다"],"a":3,"c":"DR은 원주를 맡겨 두고 해외에서 대신 거래되는 증서예요. 어디에 상장하느냐에 따라 이름과 비용이 달라져요.","e":"상장비용만 보면 미국 밖 시장에 상장하는 EDR이 더 유리해요. 미국은 상장 기준이 까다롭고 공시 의무도 많아 돈이 더 들어요. 그래도 모을 수 있는 자금이 크고 이름을 알리기 좋아서 많은 기업이 미국을 선택해요.","w":["해외 상장 형태에는 DR 외에 원주상장과 복수상장도 있고, 한국 기업은 대개 DR을 써요.","상장 지역에 따른 ADR·EDR·GDR 구분이 맞아요.","현지 통화로 거래해 편하지만, DR 가격에 환율이 반영되므로 환위험이 완전히 사라지지는 않아요.",null],"k":"미국 상장은 \"비싼 대형 백화점 입점\"이에요. 입점비는 비싸도 손님이 많아서 다들 들어가려 해요.","m":"ADR(미국) · EDR(미국 밖, 상장비용 유리) · GDR(양쪽) · 원주상장은 예외적","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","t":"환위험 관리의 기본방침","q":"해외투자의 환위험 관리 체계에 관한 설명으로 가장 적절한 것은?","o":["환위험을 어떻게 다룰지에 대한 큰 원칙은 거래가 실제로 생기고 나서 건별로 정하면 된다","감수할 환위험의 크기(허용위험한도)는 회사 전체로 먼저 정하고, 이를 부서·운용역·포지션별로 쪼개 나눠 준 뒤 지키는지 확인한다","환위험 관리수단은 선물환 같은 파생상품뿐이며 통화 분산이나 보험 가입은 관리수단이 아니다","내재적 헤지는 어느 나라 통화든 그 통화가치와 현지 주가 사이에 뚜렷한 관계가 있어 누구나 쓰는 표준 수단이다"],"a":1,"c":"환위험은 미리 정한 방침에 따라 \"얼마까지 감수할지(한도)\"를 정해 나눠 주고, 여러 수단을 섞어 관리해요.","e":"허용위험한도는 기관 전체에서 정한 다음 부서와 운용역, 개별 포지션까지 나누어 배분하고 준수 여부를 점검해요. 기본방침은 거래 전에 미리 정해 둬요.","w":["큰 원칙은 거래 전에 먼저 세우고, 그 원칙에 맞춰 한도와 수단을 써요.",null,"파생상품 말고도 여러 통화로 나눠 들기, 보험, 내재적 헤지도 관리수단에 들어가요.","달러 외 통화에서는 통화가치와 주가 사이에 뚜렷한 관계를 찾기 어려워, 내재적 헤지는 주로 미국 투자자가 달러 강세기에 활용해요."],"k":"가족 여행 경비를 \"출발 전에\" 정해 두고, 사람마다 쓸 수 있는 용돈을 나눠 주는 것과 같아요.","m":"방침은 사전에 · 한도는 전체 → 부서 → 운용역 → 포지션 · 수단 = 파생 + 통화분산 + 보험 + 내재적 헤지","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"상","t":"원화 환산 수익률의 위험","q":"국내 투자자가 미국 주식형 펀드에 환헤지 없이 투자했다. 달러 기준 수익률의 표준편차는 15%, 원/달러 환율 변동률의 표준편차는 8%, 둘 사이의 상관계수는 −0.25이다. 원화 기준 수익률의 표준편차에 가장 가까운 것은? (단, 원화 수익률 ≈ 달러 수익률 + 환율 변동률로 본다)","o":["약 15.1%","약 16.1%","17.0%","23.0%"],"a":0,"c":"원화로 본 수익률은 \"현지 수익률 + 환율 변동률\"이라, 그 위험에는 두 변동성과 둘 사이의 공분산이 함께 들어가요.","e":"분산 = 0.15² + 0.08² + 2 × (−0.25) × 0.15 × 0.08 = 0.0225 + 0.0064 − 0.006 = 0.0229이고, 표준편차는 √0.0229 ≈ 15.1%예요. 상관이 음(−)이라 환율이 주가 손실을 일부 메워 줘서 두 분산의 합보다 위험이 작아졌어요. 환헤지를 하면 환위험만 줄고 현지 주가 위험은 남아요. 언헤지 펀드는 원/달러 환율이 오르면 원화 수익률이 커져요. 수출 경쟁력 논리로는 주가와 그 나라 통화가치가 음(−)의 관계지만, 요즘은 해외 자금 흐름의 영향이 커서 같은 방향(+)으로 움직이는 경우가 더 흔해요.","w":[null,"교차항의 2를 빠뜨렸어요(0.0225 + 0.0064 − 0.003).","공분산 항을 빼고 두 분산만 더했어요.","표준편차를 그냥 더했어요. 위험은 분산 단위로 합쳐야 해요."],"k":"두 사람이 시소를 타듯 반대로 움직이면(음의 상관), 둘을 합친 흔들림은 각자 흔들림을 더한 것보다 작아져요.","m":"σ²원화 = σ²주식 + σ²환율 + 2ρσσ · ρ < 0이면 위험↓","f":"σ = √(σA² + σe² + 2ρσAσe) = √(0.0225 + 0.0064 − 0.006) ≈ 15.1%","rev":0},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","t":"해외투자 세금과 펀드 환매","q":"국내 투자자의 해외 주식 투자에 관한 설명으로 가장 적절하지 않은 것은?","o":["해외 주식을 직접 팔아 생긴 양도차익에 현지에서도 세금을 냈다면, 국내에서 신고할 때 외국납부세액공제 등으로 이중과세를 조정할 수 있다","국내에서 만든 해외주식형 펀드를 환매해 얻은 이익은 배당소득으로 분류되어 15.4%(지방소득세 포함)를 떼고 지급된다","해외주식형 펀드는 현지 결제 주기와 운용 구조에 따라 환매 신청 후 돈이 들어오는 날짜가 제각각이어서 미리 확인해 둬야 한다","해외 주식 직접투자의 양도차익과 국내 설정 해외펀드의 환매이익에는 같은 세율이 적용된다"],"a":3,"c":"같은 해외 주식이라도 직접 사고팔면 양도소득세, 국내 펀드를 거치면 배당소득세로 과세 방식이 달라요.","e":"직접투자 양도차익은 연 250만원 기본공제 뒤 22%(지방소득세 포함)의 양도소득세를 내고 이듬해 5월에 직접 신고해요. 국내 설정 해외펀드의 환매이익은 배당소득으로 15.4%가 원천징수돼요. 그래서 두 세율은 달라요. 국내 주식에 투자하는 펀드는 해외 펀드보다 환매대금이 대체로 빨리 들어와요.","w":["국외자산 양도소득은 현지에서 낸 세금을 세액공제하거나 필요경비로 넣는 방법 중 하나를 골라 이중과세를 조정해요.","국내 설정 해외펀드 이익은 배당소득으로 15.4% 원천징수돼요.","현지 결제일과 운용 구조 때문에 환매기간이 펀드마다 달라요.",null],"k":"해외 주식을 \"직접 사면\" 내가 세무서에 신고하는 양도세, \"펀드 바구니에 담아 사면\" 은행이 떼어 가는 배당세예요.","m":"직접: 양도세 22%(250만 공제)·외국납부세액공제 · 국내 해외펀드: 배당소득 15.4% · 환매기간 펀드마다 다름","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"그랜빌의 이동평균선 매매신호","q":"그랜빌의 이동평균선 매매법칙에서 매수신호로 보기 어려운 것은?","o":["하락하던 이동평균선이 보합이나 상승으로 바뀌는 가운데 주가가 이동평균선을 아래에서 위로 뚫고 오른다","상승하는 이동평균선 위에 있던 주가가 잠시 이동평균선 아래로 내려갔다가 곧 다시 오른다","주가가 상승하는 이동평균선 근처까지 내려왔다가 닿지 않고 다시 오른다","상승하던 이동평균선이 보합이나 하락으로 바뀌는 가운데 주가가 이동평균선을 위에서 아래로 뚫고 내려간다"],"a":3,"c":"그랜빌은 주가와 이동평균선의 위치·방향 관계로 매수 4가지, 매도 4가지 신호를 정리했어요.","e":"이동평균선이 꺾이는 가운데 주가가 이를 아래로 뚫는 것은 대표적인 매도신호예요.","w":["이동평균선이 돌아서는 가운데 상향 돌파하는 것은 매수신호예요.","상승 추세 속 일시 이탈 후 회복은 매수신호예요.","상승 이동평균선에서 지지받는 것은 매수신호예요.",null],"k":"평균선이 꺾이며 주가가 밑으로 빠지면 \"추세가 끝났다\"는 신호예요.","m":"이평선 꺾임 + 하향 돌파 = 매도"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"간접법 현금흐름표의 가산 항목","q":"A사가 간접법으로 현금흐름표를 작성하려 한다. 당기순이익에서 출발할 때 더해 주는 조정 항목으로 볼 수 없는 것은?","o":["감가상각비","매출채권의 증가","매입채무의 증가","유형자산처분손실"],"a":1,"c":"간접법은 당기순이익에서 출발해 \"현금이 나가지 않은 비용\"은 더하고 \"현금이 들어오지 않은 수익·자산 증가\"는 빼요.","e":"매출채권이 늘었다는 것은 팔았지만 아직 돈을 못 받았다는 뜻이라 순이익에서 빼요.","w":["현금 지출이 없는 비용이라 더해요.",null,"아직 돈을 안 냈다는 뜻이라 더해요.","현금 유출 없는 손실이라 더해요."],"k":"외상으로 판 것(매출채권 증가)은 장부상 이익이지만 통장엔 돈이 없어요. 그래서 빼요.","m":"간접법: 비현금비용·부채 증가 = 가산 / 자산 증가·처분이익 = 차감"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"결합레버리지","q":"영업레버리지도(DOL)가 2, 재무레버리지도(DFL)가 1.5인 기업의 매출액이 10% 늘면 주당순이익(EPS)은 몇 % 늘어나는가?","o":["15%","20%","30%","35%"],"a":2,"c":"영업레버리지는 매출 변화가 영업이익에, 재무레버리지는 영업이익 변화가 순이익(EPS)에 미치는 효과예요. 둘을 곱한 것이 결합레버리지예요.","e":"결합레버리지도 = 2 × 1.5 = 3. 매출이 10% 늘면 EPS는 10% × 3 = 30% 늘어요.","w":["재무레버리지만 반영했어요.","영업레버리지만 반영했어요.",null,"두 레버리지도를 더했어요((2 + 1.5) × 10% = 35%). 두 값은 곱해야 해요."],"k":"지렛대 두 개를 연달아 쓰면 효과가 곱해져요. 2배 × 1.5배 = 3배!","m":"DCL = DOL × DFL · %ΔEPS = DCL × %Δ매출","f":"2 × 1.5 = 3 → 10% × 3 = 30%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"토빈의 Q","q":"토빈의 Q에 관한 설명으로 가장 적절하지 않은 것은?","o":["기업 자산의 시장가치를 대체원가로 나눈 값이다","Q가 1보다 크면 기업이 새로 설비투자를 할 유인이 생긴다","Q가 1보다 작으면 자산을 새로 만드는 것보다 기업을 사는 것이 싸다","Q가 1보다 크면 기업이 저평가되어 있어 적대적 인수 대상이 되기 쉽다"],"a":3,"c":"토빈의 Q는 시장이 매긴 기업 가치가 그 자산을 새로 만드는 비용보다 큰지 작은지를 보여 줘요.","e":"Q가 1보다 작을 때 시장가치가 대체원가보다 낮아 저평가 상태이고, 인수 대상이 되기 쉬워요. Q > 1은 오히려 고평가 쪽이에요.","w":["시장가치 ÷ 대체원가가 토빈의 Q예요.","Q > 1이면 새로 투자해 가치를 만들 유인이 있어요.","Q < 1이면 공장을 짓는 것보다 회사를 사는 게 싸요.",null],"k":"새 집 짓는 비용이 10억인데 그 집을 5억에 살 수 있으면(Q < 1) 사는 게 이득이죠.","m":"Q = 시장가치 ÷ 대체원가 · Q < 1 → 저평가·인수 대상"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"EV/EBITDA로 적정 주가 구하기","q":"〈보기〉의 자료로 EV/EBITDA 배수를 이용해 구한 A사의 1주당 적정 주가로 가장 적절한 것은?\n• A사 EBITDA: 100억원\n• 유사기업 평균 EV/EBITDA: 6배\n• A사 순차입금: 200억원\n• A사 발행주식 수: 100만주","o":["20,000원","40,000원","60,000원","80,000원"],"a":1,"c":"EV(기업가치)는 주주 몫과 채권자 몫을 합친 값이에요. 그래서 EV에서 순차입금을 빼야 주주 몫(주식가치)이 나와요.","e":"EV = 100억 × 6 = 600억원, 주식가치 = 600억 − 200억 = 400억원, 1주당 = 400억 ÷ 100만주 = 40,000원이에요.","w":["순차입금을 두 번 뺐어요.",null,"EV를 그대로 주식가치로 봤어요.","순차입금을 빼지 않고 더했어요."],"k":"가게 가치가 600인데 빚이 200이면, 주인 몫은 400이에요. 이걸 주식 수로 나누면 한 주 가격이에요.","m":"주식가치 = EBITDA × 배수 − 순차입금","f":"(100 × 6 − 200)억 ÷ 100만주 = 40,000원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"포터의 5가지 경쟁요인","q":"포터(Porter)의 산업 경쟁구조 분석에서 말하는 5가지 경쟁요인(Five Forces)에 해당하지 않는 것은?","o":["신규 진입자의 위협","대체재의 위협","구매자와 공급자의 교섭력","정부의 산업정책"],"a":3,"c":"포터의 5가지 경쟁요인은 기존 기업 간 경쟁, 신규 진입 위협, 대체재 위협, 구매자 교섭력, 공급자 교섭력이에요.","e":"정부의 역할은 5가지 경쟁요인이 아니라 국가 경쟁력을 설명하는 다이아몬드 모형의 보조 요인이에요.","w":["신규 진입 위협은 5요인 중 하나예요.","대체재 위협은 5요인 중 하나예요.","구매자·공급자 교섭력은 5요인에 포함돼요.",null],"k":"\"새로 들어올 경쟁자, 비슷한 대체품, 손님 힘, 납품업체 힘, 지금 경쟁자\" 다섯 가지가 산업의 경쟁 강도를 정해요.","m":"5 Forces: 기존경쟁·진입·대체재·구매자·공급자 (정부는 다이아몬드)"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"EVA의 의미","q":"EVA(경제적 부가가치)에 관한 설명으로 가장 적절하지 않은 것은?","o":["세후영업이익에서 투하자본에 대한 자본비용을 뺀 값이다","타인자본비용뿐 아니라 자기자본비용도 반영한다","EVA가 양(+)이면 주주가치를 창출한 것으로 본다","회계상 당기순이익이 양(+)이면 EVA도 반드시 양(+)이다"],"a":3,"c":"EVA는 \"자본을 쓴 대가까지 빼고도 남은 이익\"이에요. 회계 이익과는 달라요.","e":"당기순이익은 자기자본비용을 빼지 않은 숫자라서, 순이익이 양수여도 자기자본비용을 넘지 못하면 EVA는 음수일 수 있어요.","w":["EVA = NOPAT − WACC × 투하자본이에요.","가중평균자본비용에는 자기자본비용도 들어가요.","자본비용을 넘는 이익을 냈다는 뜻이에요.",null],"k":"장부로는 흑자여도, 주주가 기대한 수익만큼 못 벌었다면 EVA는 적자예요.","m":"EVA = NOPAT − WACC × IC = (ROIC − WACC) × IC"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"ROIC로 구하는 EVA","q":"투하자본 500억원, 투하자본이익률(ROIC) 12%, 가중평균자본비용(WACC) 9%인 기업의 EVA는?","o":["15억원","45억원","60억원","105억원"],"a":0,"c":"EVA는 (ROIC − WACC) × 투하자본으로도 구할 수 있어요.","e":"EVA = (12% − 9%) × 500억 = 15억원이에요.","w":[null,"자본비용(9% × 500억)이에요.","세후영업이익(12% × 500억)이에요.","두 금액을 더했어요."],"k":"투하자본 1원당 3%씩 자본비용보다 더 벌었으니 500억 × 3%예요.","m":"EVA = (ROIC − WACC) × IC","f":"(12% − 9%) × 500 = 15억원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"MVA","q":"미래 EVA를 가중평균자본비용으로 할인한 현재가치의 합으로, 시장가치가 투하자본을 초과하는 금액을 뜻하는 것은?","o":["MVA(시장부가가치)","NOPAT","잉여현금흐름","토빈의 Q"],"a":0,"c":"EVA가 한 해의 가치 창출이라면, 미래 EVA를 모두 모은 현재가치는 기업이 시장에서 인정받는 초과가치예요.","e":"MVA는 미래 EVA의 현재가치 합이며 \"시장가치 − 투하자본\"으로 볼 수 있어요.","w":[null,"세후영업이익이에요.","투자 후 남는 현금흐름이에요.","시장가치 ÷ 대체원가 비율이에요."],"k":"해마다 쌓일 EVA를 지금 가치로 한꺼번에 모은 게 MVA예요.","m":"MVA = Σ 미래 EVA의 현재가치 = 시장가치 − 투하자본"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"항상성장모형 주가","q":"〈보기〉 조건에서 항상성장 배당할인모형으로 구한 이론주가는?\n• 올해 지급한 주당배당금(D₀): 1,000원\n• 배당성장률: 연 4%\n• 요구수익률: 연 9%","o":["20,000원","20,800원","11,556원","25,000원"],"a":1,"c":"항상성장모형은 다음 해 배당(D₁)을 (요구수익률 − 성장률)로 나눠요. 올해 배당이 주어지면 한 번 키워야 해요.","e":"D₁ = 1,000 × 1.04 = 1,040원, P₀ = 1,040 ÷ (0.09 − 0.04) = 20,800원이에요.","w":["D₀를 그대로 썼어요.",null,"분모에서 성장률을 빼지 않았어요(1,040 ÷ 0.09 ≈ 11,556원). 분모는 k − g예요.","계산이 맞지 않아요."],"k":"내년 배당 1,040원을 \"요구수익률 − 성장률\" 5%로 나눠요.","m":"P₀ = D₁ ÷ (k − g), D₁ = D₀(1 + g)","f":"1,040 ÷ 0.05 = 20,800원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"항상성장모형의 가정","q":"항상성장 배당할인모형(고든 모형)의 가정으로 가장 적절하지 않은 것은?","o":["배당이 매년 일정한 비율로 성장한다","요구수익률이 성장률보다 크다","요구수익률과 성장률이 일정하다","성장에 필요한 자금을 모두 외부 차입으로 조달한다"],"a":3,"c":"고든 모형은 단순한 가정 위에서 주가를 구하는 모형이에요.","e":"항상성장모형은 성장에 필요한 투자자금을 내부유보로만 조달한다고 가정해요. 외부 차입 조달은 가정이 아니에요.","w":["배당이 g%씩 꾸준히 커진다고 봐요.","k > g여야 식이 성립해요.","k와 g가 변하지 않는다고 봐요.",null],"k":"\"번 돈 일부를 다시 투자해서\" 꾸준히 커진다는 모형이에요.","m":"고든 모형: g 일정 · k > g · 내부유보로 성장"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"지속가능성장률","q":"ROE가 15%이고 배당성향이 40%인 기업의 지속가능성장률(g)은?","o":["6%","9%","15%","25%"],"a":1,"c":"번 돈 중 회사에 남긴 비율(유보율)을 자기자본이익률로 굴리면 성장률이 나와요.","e":"유보율 = 1 − 0.4 = 0.6, g = ROE × 유보율 = 15% × 0.6 = 9%예요.","w":["배당성향을 곱했어요.",null,"ROE를 그대로 썼어요.","계산이 맞지 않아요."],"k":"이익의 60%를 남겨 15%로 굴리니 9%씩 커져요.","m":"g = ROE × b (b = 1 − 배당성향)","f":"15% × 0.6 = 9%"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"유보율과 PER","q":"항상성장모형이 성립할 때, 기업의 ROE가 요구수익률보다 높은 경우 유보율을 높이면 PER은?","o":["낮아진다","높아진다","변하지 않는다","0이 된다"],"a":1,"c":"PER = (1 − b) ÷ (k − ROE × b)예요. 재투자 수익률(ROE)이 요구수익률보다 높으면 재투자가 가치를 만들어요.","e":"ROE > k이면 유보해서 재투자할수록 성장 가치가 커져 PER이 높아져요. ROE < k이면 반대로 낮아지고, 같으면 변하지 않아요.","w":["ROE < k일 때예요.",null,"ROE = k일 때예요.","그런 경우는 없어요."],"k":"은행 이자(k)보다 잘 굴리는 회사(ROE)라면 돈을 남길수록 좋아요.","m":"ROE > k → 유보↑ PER↑ / ROE < k → 유보↑ PER↓"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"PBR의 분해","q":"PBR을 ROE와 PER로 나타낸 식으로 옳은 것은?","o":["PBR = ROE × PER","PBR = ROE ÷ PER","PBR = PER ÷ ROE","PBR = ROE + PER"],"a":0,"c":"PBR = 주가 ÷ BPS, PER = 주가 ÷ EPS, ROE = EPS ÷ BPS예요.","e":"(EPS ÷ BPS) × (주가 ÷ EPS) = 주가 ÷ BPS이므로 PBR = ROE × PER이에요.","w":[null,"식이 맞지 않아요.","식이 맞지 않아요.","비율은 더하지 않아요."],"k":"EPS가 위아래로 지워지면서 주가 ÷ BPS만 남아요.","m":"PBR = ROE × PER"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"PSR의 장점","q":"PER 대신 PSR(주가매출액비율)을 쓰는 이유로 가장 적절한 것은?","o":["이익이 적자인 기업에도 적용할 수 있다","기업의 수익성 차이를 완벽하게 반영한다","부채 수준을 직접 반영한다","배당 정책을 직접 반영한다"],"a":0,"c":"PER은 이익이 음수면 의미가 없어요. 매출액은 거의 항상 양수예요.","e":"PSR은 매출액을 기준으로 하므로 적자 기업이나 신생 기업에도 쓸 수 있고, 회계 처리에 따른 왜곡이 비교적 적어요.","w":[null,"매출 기준이라 수익성 차이는 잘 반영하지 못해요.","부채를 직접 반영하지 않아요.","배당과 관계없어요."],"k":"아직 돈을 못 버는 회사도 \"얼마나 팔았는지\"는 있어요.","m":"PSR = 주가 ÷ 주당매출액 · 적자기업에도 적용"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"유사기업 PER로 공모가 구하기","q":"공모 예정 기업의 주당순이익이 2,000원이고 유사기업 평균 PER이 12배이다. 30% 할인율을 적용한 공모 희망가격은?","o":["16,800원","24,000원","7,200원","31,200원"],"a":0,"c":"상대가치평가로 구한 주당 가치에 할인율을 적용해 공모가를 정해요.","e":"주당 평가가치 = 2,000 × 12 = 24,000원, 30% 할인 → 24,000 × 0.7 = 16,800원이에요.","w":[null,"할인 전 가치예요.","할인액이에요.","할증했어요."],"k":"이익 2,000원에 12배를 곱한 24,000원에서 30%를 깎아요.","m":"공모가 = EPS × 유사기업 PER × (1 − 할인율)","f":"24,000 × 0.7 = 16,800원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"잔여이익모형","q":"잔여이익모형(RIM)으로 주식가치를 구하는 식으로 가장 적절한 것은?","o":["현재 자기자본 장부가치 + 미래 잔여이익의 현재가치 합","미래 배당의 현재가치 합 − 자기자본","시가총액 + 순차입금","당기순이익 × 업종 평균 PER"],"a":0,"c":"잔여이익은 순이익에서 자기자본비용을 뺀 이익이에요.","e":"RIM의 주주가치 = 현재 자기자본 + Σ 잔여이익의 현재가치이고, 잔여이익 = 순이익 − 자기자본 × 자기자본비용이에요.","w":[null,"식이 맞지 않아요.","EV예요.","상대가치평가예요."],"k":"지금 장부에 있는 돈에, 앞으로 기대 이상으로 벌 돈을 더해요.","m":"RIM: V = B₀ + Σ RI/(1+k)ᵗ, RI = NI − k × B"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"FCFF 계산","q":"〈보기〉에서 기업잉여현금흐름(FCFF)은?\n• 영업이익(EBIT): 200억원, 법인세율 25%\n• 감가상각비: 40억원\n• 자본적 지출: 60억원\n• 순운전자본 증가: 20억원","o":["110억원","150억원","160억원","200억원"],"a":0,"c":"FCFF는 세후영업이익에 비현금비용을 더하고, 투자(설비·운전자본)를 빼서 구해요.","e":"FCFF = 200 × (1 − 0.25) + 40 − 60 − 20 = 150 + 40 − 80 = 110억원이에요.","w":[null,"세후영업이익만 구했어요.","법인세를 빼지 않았어요(200 + 40 − 60 − 20 = 160억원). EBIT에 (1 − 법인세율)을 곱해야 해요.","세금과 투자를 반영하지 않았어요."],"k":"세후 150억 + 감가상각 40억 − 설비 60억 − 운전자본 20억이에요.","m":"FCFF = EBIT(1 − t) + 감가상각비 − 자본적지출 − 순운전자본 증가","f":"150 + 40 − 60 − 20 = 110억원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"현금흐름 활동 구분","q":"현금흐름표에서 투자활동 현금흐름에 해당하는 것은?","o":["유상증자","상품 매출로 받은 현금","단기차입금의 차입","유형자산의 취득"],"a":3,"c":"현금흐름표는 영업, 투자, 재무 활동으로 나눠요. 투자활동은 장기 자산을 사고파는 거래예요.","e":"유형자산을 취득하거나 처분하는 것은 투자활동이에요. 차입과 증자는 재무활동, 매출 대금은 영업활동이에요.","w":["재무활동이에요.","영업활동이에요.","재무활동이에요.",null],"k":"공장·기계를 사는 건 \"투자\", 돈을 빌리는 건 \"재무\", 물건을 파는 건 \"영업\"이에요.","m":"영업 = 본업 · 투자 = 자산 취득·처분 · 재무 = 차입·증자·상환"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"간접법의 차감 항목","q":"순이익에서 출발해 영업현금흐름을 조정하는 방식에서 빼 주는 조정 항목은?","o":["감가상각비","유형자산처분이익","재고자산의 감소","미지급비용의 증가"],"a":1,"c":"간접법은 순이익에서 출발해, 현금 유출입이 없거나 영업활동이 아닌 손익을 걸러 내요.","e":"유형자산처분이익은 투자활동에서 생긴 이익이라 영업현금흐름을 구할 때 순이익에서 빼요. 처분 대금 전체는 투자활동 현금흐름에 들어가요.","w":["비현금비용이라 더해요.",null,"재고가 현금으로 바뀌었으니 더해요.","비용은 잡혔지만 현금이 안 나갔으니 더해요."],"k":"기계를 팔아 생긴 이익은 \"영업\"이 아니라 \"투자\" 쪽 이야기예요.","m":"차감: 처분이익·매출채권 증가·재고 증가 / 가산: 감가상각·처분손실·매입채무 증가"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"재고자산회전율","q":"매출액 600억원, 평균 재고자산 100억원인 기업의 재고자산회전율과 재고자산회전기간(1년 360일 기준)으로 옳은 것은?","o":["60회, 6일","6회, 30일","6회, 60일","0.17회, 60일"],"a":2,"c":"회전율은 1년 동안 재고가 몇 번 팔려 나갔는지, 회전기간은 한 번 팔리는 데 걸리는 날수예요.","e":"회전율 = 600 ÷ 100 = 6회, 회전기간 = 360 ÷ 6 = 60일이에요.","w":["계산이 맞지 않아요.","회전기간 계산이 틀렸어요.",null,"분자·분모를 바꿨어요."],"k":"재고가 1년에 6바퀴 돌면 한 바퀴에 60일이에요.","m":"재고자산회전율 = 매출액 ÷ 재고자산 · 회전기간 = 360 ÷ 회전율","f":"600 ÷ 100 = 6회 → 60일"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"영업레버리지도","q":"매출액이 10% 늘 때 영업이익이 30% 늘었다. 이 기업의 영업레버리지도(DOL)와, 매출액이 5% 감소할 때 예상되는 영업이익 변화율은?","o":["3, −15%","3, −5%","0.33, −1.7%","2, −10%"],"a":0,"c":"영업레버리지도는 매출 변화율에 대한 영업이익 변화율의 배수예요. 고정비가 클수록 커요.","e":"DOL = 30% ÷ 10% = 3이고, 매출 5% 감소 시 영업이익은 3 × (−5%) = −15% 변해요.","w":[null,"배수를 적용하지 않았어요.","역수를 썼어요.","계산이 맞지 않아요."],"k":"매출이 1% 움직이면 영업이익은 3% 움직이는 회사예요.","m":"DOL = 영업이익 변화율 ÷ 매출액 변화율","f":"30 ÷ 10 = 3 → 3 × (−5%) = −15%"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"재무레버리지도","q":"EBIT 100억원에 연 이자 20억원을 부담하는 회사라면 DFL은 얼마인가?","o":["0.8","1.25","5","1.2"],"a":1,"c":"재무레버리지도는 영업이익 변화에 대해 주당순이익이 몇 배로 변하는지 보여 줘요. 이자(고정 재무비용)가 클수록 커요.","e":"DFL = EBIT ÷ (EBIT − 이자) = 100 ÷ 80 = 1.25예요.","w":["역수예요.",null,"이자보상비율이에요.","이자를 더했어요."],"k":"이자 20억을 빼고 남은 80억이 기준이라, 100 ÷ 80 = 1.25배 출렁여요.","m":"DFL = EBIT ÷ (EBIT − I)","f":"100 ÷ 80 = 1.25"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"ROE 계산","q":"매출액순이익률 5%, 총자산회전율 1.2회, 부채비율 150%인 기업의 ROE는?","o":["6%","9%","15%","7.5%"],"a":2,"c":"ROE = 순이익률 × 총자산회전율 × (총자산 ÷ 자기자본)이에요. 부채비율 150%면 총자산 ÷ 자기자본 = 2.5예요.","e":"ROE = 5% × 1.2 × 2.5 = 15%예요.","w":["ROA예요.","부채비율 1.5를 그대로 곱했어요.",null,"계산이 맞지 않아요."],"k":"자본 1에 빚 1.5를 더하면 자산은 2.5예요. ROA 6%에 2.5배를 곱해요.","m":"ROE = 순이익률 × 총자산회전율 × (1 + 부채비율)","f":"5% × 1.2 × 2.5 = 15%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"배당성향과 배당수익률","q":"당기순이익 600억원, 발행주식수 1,000만주, 주당배당금 1,800원, 주가 60,000원일 때 배당성향과 배당수익률로 옳은 것은?","o":["배당성향 30%, 배당수익률 3%","배당성향 3%, 배당수익률 30%","배당성향 30%, 배당수익률 10%","배당성향 18%, 배당수익률 3%"],"a":0,"c":"EPS = 순이익 ÷ 주식수예요. 배당성향은 배당 ÷ EPS, 배당수익률은 배당 ÷ 주가예요.","e":"EPS = 600억 ÷ 1,000만주 = 6,000원, 배당성향 = 1,800 ÷ 6,000 = 30%, 배당수익률 = 1,800 ÷ 60,000 = 3%예요.","w":[null,"두 지표를 바꿨어요.","10%는 이익수익률(EPS ÷ 주가)이에요.","배당성향 계산이 틀렸어요."],"k":"번 돈 6,000원 중 1,800원을 나눠 줬고(30%), 주가 대비로는 3%예요.","m":"배당성향 = DPS ÷ EPS · 배당수익률 = DPS ÷ 주가","f":"EPS 6,000 → 30% · 3%"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"WACC 계산","q":"자기자본 600억원(자기자본비용 12%), 타인자본 400억원(세전 차입이자율 8%), 법인세율 25%인 기업의 가중평균자본비용(WACC)은?","o":["9.6%","10.4%","7.2%","10.0%"],"a":0,"c":"WACC는 자본 구성 비중으로 각 자본비용을 가중평균해요. 이자는 비용 처리되므로 세후로 바꿔요.","e":"WACC = 0.6 × 12% + 0.4 × 8% × (1 − 0.25) = 7.2% + 2.4% = 9.6%예요.","w":[null,"법인세 절감효과를 반영하지 않았어요.","자기자본 부분만 구했어요.","단순 평균이에요."],"k":"자기자본 몫 7.2%에 세금 깎인 이자 몫 2.4%를 더해요.","m":"WACC = (E/V)kₑ + (D/V)k_d(1 − t)","f":"7.2% + 2.4% = 9.6%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"제로성장 주식가치","q":"배당이 앞으로 늘지도 줄지도 않고 해마다 1,500원씩 나온다고 본다. 투자자가 10%를 원한다면 이 주식의 적정가는?","o":["1,500원","13,636원","15,000원","16,500원"],"a":2,"c":"배당이 늘지 않고 일정하면 영구연금처럼 배당 ÷ 요구수익률로 구해요.","e":"P = 1,500 ÷ 0.10 = 15,000원이에요.","w":["배당 그대로예요.","구한 적정가 15,000원을 한 번 더 할인했어요(15,000 ÷ 1.1 ≈ 13,636원). 제로성장 주식은 D ÷ k로 끝나요.",null,"성장을 가정했어요."],"k":"해마다 1,500원이 나오는 쿠폰을 10%로 굴리려면 15,000원이 필요해요.","m":"제로성장: P = D ÷ k","f":"1,500 ÷ 0.1 = 15,000원"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"HHI 계산과 해석","q":"어떤 산업에 시장점유율이 동일한 기업 5개만 있을 때의 허핀달-허쉬만 지수(HHI, 점유율 %의 제곱합)와, HHI를 소수로 바꾼 값의 역수가 뜻하는 것으로 가장 적절한 것은?","o":["100, 완전경쟁","10,000, 독점","2,000, 동등 규모 기업 수 5개","500, 동등 규모 기업 수 20개"],"a":2,"c":"HHI는 각 기업 점유율의 제곱을 모두 더한 값이에요. 점유율이 같으면 기업 수가 많을수록 작아져요.","e":"점유율 20%짜리 5개 → 20² × 5 = 2,000이에요. HHI를 비율로 바꾼 값(0.2)의 역수 5는 \"동등 규모 기업 수\"예요.","w":["계산이 맞지 않아요.","1개 기업이 100%일 때예요.",null,"계산이 맞지 않아요."],"k":"20 × 20을 5번 더하면 2,000이에요.","m":"HHI = Σ(점유율%)² · 독점 10,000 · 역수 = 동등규모 기업 수","f":"20² × 5 = 2,000"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"CRk(상위 k개 기업 집중률)","q":"상위 k개 기업 집중률(CRk)과 비교한 HHI의 특징으로 가장 적절한 것은?","o":["산업 내 모든 기업의 점유율과 규모 분포를 반영한다","상위 k개 기업의 점유율만 단순히 더한다","기업 수가 늘수록 값이 커진다","산업 집중도와 관계없는 지표이다"],"a":0,"c":"CRk는 상위 몇 개 기업 점유율의 합이라 나머지 기업 분포는 반영하지 못해요.","e":"HHI는 모든 기업의 점유율을 제곱해 더하므로 기업 간 규모 차이(불균등)까지 반영해요.","w":[null,"CRk의 설명이에요.","기업 수가 늘면 대체로 작아져요.","대표적인 집중도 지표예요."],"k":"CRk는 \"상위 3명 키 합계\", HHI는 \"반 전체 키 차이까지\" 보는 거예요.","m":"CRk = 상위 k개 점유율 합 · HHI = 전체 점유율 제곱합"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"성숙기 산업의 특징","q":"산업 수명주기 중 성숙기의 특징으로 가장 적절한 것은?","o":["매출이 급증하고 신규 진입이 활발하다","제품 인지도가 낮고 적자인 기업이 많다","수요가 급감해 기업들이 시장에서 철수한다","시장 수요가 포화되어 성장이 둔화되고 가격·원가 경쟁이 치열해진다"],"a":3,"c":"산업은 도입기 → 성장기 → 성숙기 → 쇠퇴기를 거쳐요.","e":"성숙기에는 수요가 포화되어 성장률이 둔화되고, 기업들이 원가 절감·가격 경쟁으로 점유율을 지키려 해요.","w":["성장기의 특징이에요.","도입기의 특징이에요.","쇠퇴기의 특징이에요.",null],"k":"살 사람은 다 산 시장이라, 이제는 \"누가 더 싸게 만드나\" 싸움이에요.","m":"도입 = 적자·낮은 인지도 · 성장 = 매출 급증 · 성숙 = 포화·원가경쟁 · 쇠퇴 = 철수"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"진입장벽의 요인","q":"포터의 경쟁요인 중 신규 진입의 위협을 낮추는(진입장벽을 높이는) 요인으로 가장 적절하지 않은 것은?","o":["규모의 경제","높은 초기 자본 소요","유통 경로 확보의 어려움","낮은 제품 차별화와 낮은 전환비용"],"a":3,"c":"진입장벽이 높을수록 새로운 기업이 들어오기 어려워 기존 기업의 수익성이 유지돼요.","e":"제품 차별화가 약하고 고객이 다른 제품으로 쉽게 바꿀 수 있으면(전환비용이 낮으면) 신규 진입이 쉬워져요.","w":["대량생산 원가 우위가 진입을 막아요.","큰 자본이 필요하면 들어오기 어려워요.","판매망을 뚫기 어려우면 진입이 어려워요.",null],"k":"아무 제품이나 비슷하고 쉽게 갈아탈 수 있으면 누구나 들어올 수 있어요.","m":"진입장벽: 규모의 경제·자본·유통·차별화·전환비용·정부규제"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"포터의 본원적 경쟁전략","q":"포터가 제시한 본원적 경쟁전략에 해당하지 않는 것은?","o":["원가우위 전략","차별화 전략","집중화 전략","다각화 전략"],"a":3,"c":"포터는 경쟁우위를 얻는 기본 전략을 세 가지로 제시했어요.","e":"본원적 경쟁전략은 원가우위, 차별화, 집중화예요. 다각화는 여기에 해당하지 않아요.","w":["가장 싸게 만드는 전략이에요.","남과 다른 가치를 주는 전략이에요.","특정 시장에 집중하는 전략이에요.",null],"k":"\"싸게, 다르게, 좁게\" 세 가지예요.","m":"본원적 전략 = 원가우위 · 차별화 · 집중화"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"구매자 교섭력","q":"포터의 산업구조 분석에서 구매자의 교섭력이 커지는 경우로 가장 적절한 것은?","o":["구매자가 소수이고 대량으로 구매한다","제품이 고도로 차별화되어 있다","구매자가 다른 공급자로 바꾸는 비용이 매우 크다","구매자가 제품 정보를 거의 갖지 못한다"],"a":0,"c":"구매자 교섭력이 크면 가격 인하 압력이 커져 산업 수익성이 낮아져요.","e":"구매자가 적고 한 번에 많이 사면 공급자에게 가격을 낮추라고 요구할 힘이 커요.","w":[null,"차별화되면 구매자 힘이 약해져요.","전환비용이 크면 구매자 힘이 약해져요.","정보가 없으면 구매자 힘이 약해져요."],"k":"큰손 고객 몇 명이 다 사 가면, 그 고객이 갑이에요.","m":"구매자 교섭력↑: 소수·대량구매·표준품·낮은 전환비용·정보 많음"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산포도 측정치","q":"자료가 흩어진 정도를 나타내는 산포도 측정치에 해당하지 않는 것은?","o":["범위","분산","사분위수 범위","중앙값"],"a":3,"c":"자료의 특성은 중심(대푯값)과 흩어진 정도(산포도)로 나타내요.","e":"중앙값은 자료를 크기순으로 놓았을 때 가운데 값인 대푯값이에요. 범위, 분산, 표준편차, 사분위수 범위가 산포도예요.","w":["최댓값 − 최솟값이에요.","평균에서 떨어진 거리 제곱의 평균이에요.","Q3 − Q1이에요.",null],"k":"중앙값은 \"가운데가 어디냐\", 산포도는 \"얼마나 퍼져 있냐\"예요.","m":"대푯값: 평균·중앙값·최빈값 / 산포도: 범위·분산·표준편차·사분위범위·변동계수"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"변동계수 비교","q":"〈보기〉 두 자산을 수익률 1단위당 위험(변동계수)으로 비교한 것으로 가장 적절한 것은?\n• A: 평균 수익률 8%, 표준편차 12%\n• B: 평균 수익률 15%, 표준편차 18%","o":["A의 변동계수가 더 작아 상대 위험이 작다","B의 변동계수가 더 작아 상대 위험이 작다","두 자산의 변동계수가 같다","표준편차가 큰 B가 항상 상대 위험도 크다"],"a":1,"c":"변동계수는 표준편차를 평균으로 나눈 값으로, 평균이 다른 자산끼리 상대 위험을 비교할 때 써요.","e":"A = 12 ÷ 8 = 1.5, B = 18 ÷ 15 = 1.2라서 B의 상대 위험이 더 작아요.","w":["A가 1.5로 더 커요.",null,"1.5와 1.2로 달라요.","평균 대비로 보면 B가 작아요."],"k":"B는 흔들림이 크지만 그만큼 더 벌어서, 1%당 흔들림은 오히려 작아요.","m":"CV = σ ÷ 평균","f":"A 1.5 · B 1.2"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"비대칭 분포의 대푯값","q":"오른쪽으로 꼬리가 긴(양의 왜도) 분포에서 대푯값의 크기 관계로 가장 적절한 것은?","o":["평균 > 중앙값 > 최빈값","최빈값 > 중앙값 > 평균","평균 = 중앙값 = 최빈값","중앙값 > 평균 > 최빈값"],"a":0,"c":"극단값은 평균을 자기 쪽으로 끌어당겨요. 최빈값은 봉우리, 중앙값은 그 사이에 있어요.","e":"오른쪽 꼬리가 길면 큰 값들이 평균을 끌어올려 평균 > 중앙값 > 최빈값이 돼요.","w":[null,"왼쪽 꼬리(음의 왜도)일 때예요.","대칭 분포일 때예요.","순서가 맞지 않아요."],"k":"소득 분포처럼 부자 몇 명이 평균을 끌어올리는 모양이에요.","m":"양의 왜도: 평균 > 중앙값 > 최빈값 / 음의 왜도: 반대"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"공분산과 상관계수","q":"공분산과 상관계수에 관한 설명으로 가장 적절하지 않은 것은?","o":["상관계수는 공분산을 두 변수 표준편차의 곱으로 나눈 값이다","상관계수는 −1과 +1 사이의 값을 가진다","공분산은 측정 단위에 따라 크기가 달라진다","상관계수가 0이면 두 변수 사이에 어떤 관계도 존재하지 않는다"],"a":3,"c":"상관계수는 공분산을 표준화해 단위와 무관하게 만든 값이에요.","e":"상관계수 0은 선형 관계가 없다는 뜻일 뿐이에요. 곡선 같은 비선형 관계는 있을 수 있어요.","w":["ρ = Cov ÷ (σ₁σ₂)예요.","−1 ≤ ρ ≤ 1이에요.","단위가 바뀌면 공분산도 바뀌어요.",null],"k":"직선으로 안 엮여도, 포물선처럼 엮여 있을 수 있어요.","m":"ρ = Cov(X,Y) ÷ (σₓσᵧ) · ρ = 0 → 선형관계 없음"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"결정계수","q":"단순회귀분석에서 결정계수(R²)에 관한 설명으로 가장 적절한 것은?","o":["종속변수의 총변동 중 회귀식으로 설명되는 변동의 비율이다","항상 음수 값을 가진다","1에 가까울수록 회귀식의 설명력이 낮다","독립변수의 기울기와 항상 같다"],"a":0,"c":"결정계수는 회귀식이 자료를 얼마나 잘 설명하는지 나타내요.","e":"R²는 총변동 중 회귀식으로 설명되는 변동의 비율로 0과 1 사이 값을 가지며, 1에 가까울수록 설명력이 높아요.","w":[null,"0 ~ 1 사이예요.","1에 가까울수록 설명력이 높아요.","기울기와 다른 개념이에요."],"k":"\"이 식이 움직임의 몇 %를 설명하나?\"예요.","m":"R² = 설명된 변동 ÷ 총변동 (0 ~ 1)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"하","rev":0,"t":"기술적 분석의 기본 가정","q":"기술적 분석의 기본 가정으로 가장 적절하지 않은 것은?","o":["주가는 수요와 공급에 의해 결정된다","주가는 추세를 이루며 움직이는 경향이 있다","과거의 주가 패턴은 되풀이되는 경향이 있다","주가는 기업의 내재가치로 빠르게 수렴한다"],"a":3,"c":"기술적 분석은 가격과 거래량의 움직임만으로 앞으로의 흐름을 예측하려는 방법이에요.","e":"내재가치를 구해 주가와 비교하는 것은 기본적 분석의 관점이에요. 기술적 분석은 수요·공급, 추세, 패턴 반복을 가정해요.","w":["기본 가정이에요.","기본 가정이에요.","기본 가정이에요.",null],"k":"기술적 분석은 \"회사가 얼마짜리냐\"보다 \"차트가 어떻게 움직이냐\"를 봐요.","m":"기술적 분석 가정: 수요·공급 · 추세 지속 · 패턴 반복"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"기술적 분석의 한계","q":"기술적 분석의 한계로 가장 적절하지 않은 것은?","o":["과거 패턴이 미래에도 반복된다는 보장이 없다","같은 차트라도 분석가마다 해석이 다를 수 있다","주가가 변한 근본 원인을 설명하지 못한다","주가 움직임에 대한 시각적 판단이 불가능하다"],"a":3,"c":"기술적 분석은 차트로 흐름을 직관적으로 볼 수 있다는 장점이 있지만, 한계도 분명해요.","e":"차트로 주가 흐름을 시각적으로 쉽게 파악할 수 있다는 건 오히려 장점이에요.","w":["대표적 한계예요.","해석이 주관적이에요.","원인 분석이 어려워요.",null],"k":"\"한눈에 보인다\"는 기술적 분석의 강점이에요.","m":"한계: 반복 불확실 · 주관적 해석 · 원인 설명 불가"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"약형 효율적 시장과 기술적 분석","q":"시장이 약형 효율적 시장이라면 다음 중 초과수익을 얻기 어려운 방법은?","o":["재무제표 등 공개된 정보를 이용한 기본적 분석","미공개 내부정보를 이용한 거래","공시되지 않은 기업 정보 분석","과거 주가와 거래량 패턴을 이용한 기술적 분석"],"a":3,"c":"약형 효율적 시장에서는 과거 가격·거래량 정보가 이미 주가에 반영돼 있어요.","e":"약형 효율적 시장에서는 과거 주가 정보로 초과수익을 얻을 수 없으므로 기술적 분석이 쓸모없어요.","w":["약형 시장은 과거 가격 정보만 반영돼 있다고 봐요. 그래서 공개된 재무정보를 분석하면 초과수익을 얻을 여지가 있어요.","약형에서는 내부정보로 초과수익이 가능할 수 있어요.","공개되지 않은 정보는 약형에 반영되지 않아요.",null],"k":"이미 모두가 본 차트로는 남보다 더 벌기 어려워요.","m":"약형 = 과거 가격 반영 → 기술적 분석 무용","f":null},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"다우이론의 기본 원칙","q":"다우이론의 기본 원칙으로 가장 적절하지 않은 것은?","o":["평균주가는 모든 정보를 반영한다","주가 움직임은 주추세, 중기추세, 단기추세로 나뉜다","추세는 두 가지 평균주가가 서로 확인해 줄 때 신뢰도가 높다","단기 일일 변동이 주추세를 판단하는 가장 중요한 근거이다"],"a":3,"c":"다우이론은 주가 흐름을 큰 추세 중심으로 보는 이론이에요.","e":"다우이론은 단기 변동을 잡음으로 보고, 수년간 이어지는 주추세를 가장 중요하게 봐요.","w":["모든 정보가 평균주가에 담겨 있다고 봐요.","세 가지 추세로 나눠요.","산업지수와 운송지수의 상호 확인을 중시해요.",null],"k":"바다의 조수(주추세)가 중요하지, 잔물결(단기 변동)은 중요하지 않아요.","m":"다우: 주추세 · 중기추세(2차) · 단기추세 / 두 지수 상호 확인 · 거래량 확인"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"피보나치 비율","q":"엘리어트 파동이론에서 조정 파동의 되돌림 비율로 흔히 쓰이는 피보나치 비율로 가장 적절하게 묶은 것은?","o":["0.382, 0.618","0.25, 0.75","0.1, 0.9","0.333, 0.667"],"a":0,"c":"엘리어트 이론은 피보나치 수열(1, 1, 2, 3, 5, 8, 13, …)에서 나온 비율을 써요.","e":"조정 파동은 직전 파동의 38.2%, 50%, 61.8% 정도를 되돌리는 경우가 많다고 보며, 0.382와 0.618이 대표적이에요.","w":[null,"피보나치 비율이 아니에요.","피보나치 비율이 아니에요.","피보나치 비율이 아니에요."],"k":"황금비 0.618과 그 짝 0.382를 기억하세요.","m":"피보나치 되돌림: 38.2% · 50% · 61.8%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"하","rev":0,"t":"골든크로스","q":"단기 이동평균선이 장기 이동평균선을 아래에서 위로 뚫고 올라가는 현상과 그 의미로 옳은 것은?","o":["골든크로스, 매수 신호","데드크로스, 매도 신호","골든크로스, 매도 신호","데드크로스, 매수 신호"],"a":0,"c":"단기선과 장기선이 교차하는 방향으로 추세 전환을 판단해요.","e":"단기선이 장기선을 상향 돌파하면 골든크로스로 상승 전환(매수) 신호, 하향 돌파하면 데드크로스로 매도 신호예요.","w":[null,"하향 돌파일 때예요.","의미가 반대예요.","이름과 의미 모두 반대예요."],"k":"최근 흐름(단기)이 긴 흐름(장기)을 위로 넘어서면 힘이 붙은 거예요.","m":"골든크로스 = 단기↑장기 (매수) · 데드크로스 = 단기↓장기 (매도)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"이격도 계산","q":"현재 주가가 10,500원이고 20일 이동평균이 10,000원일 때 20일 이격도는?","o":["95%","100%","105%","110%"],"a":2,"c":"이격도는 주가가 이동평균선에서 얼마나 떨어져 있는지 보는 지표예요.","e":"이격도 = 주가 ÷ 이동평균 × 100 = 10,500 ÷ 10,000 × 100 = 105%예요. 100%보다 크면 주가가 이동평균 위에 있다는 뜻이에요.","w":["역수에 가까운 값이에요.","주가와 이동평균이 같을 때예요.",null,"계산이 맞지 않아요."],"k":"평균보다 5% 높게 떠 있어요.","m":"이격도 = 주가 ÷ 이동평균 × 100","f":"10,500 ÷ 10,000 = 105%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"OBV의 원리","q":"OBV(On Balance Volume)에 관한 설명으로 가장 적절한 것은?","o":["주가가 오른 날의 거래량은 더하고 내린 날의 거래량은 빼서 누적한다","종가를 최고가와 최저가 사이의 위치로 나타낸다","단기 지수이동평균에서 장기 지수이동평균을 뺀다","상승일 수를 전체 일수로 나눈다"],"a":0,"c":"OBV는 거래량이 주가에 앞선다는 생각에서 나온 거래량 지표예요.","e":"OBV는 상승일 거래량은 더하고 하락일 거래량은 빼서 누적한 값이에요. 주가가 보합이어도 OBV가 오르면 매집으로 봐요.","w":[null,"스토캐스틱이에요.","MACD예요.","투자심리선이에요."],"k":"오른 날 거래량은 \"매수 쪽 힘\", 내린 날 거래량은 \"매도 쪽 힘\"으로 쌓아요.","m":"OBV = Σ(상승일 거래량) − Σ(하락일 거래량)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"MACD의 구성","q":"MACD 지표에 관한 설명으로 가장 적절한 것은?","o":["단기 지수이동평균에서 장기 지수이동평균을 뺀 값이며, 시그널선과의 교차로 매매 시점을 판단한다","최근 일정 기간 중 상승일 수의 비율이다","거래량을 누적한 값이다","최고가와 최저가의 평균을 이은 선이다"],"a":0,"c":"MACD는 두 이동평균선이 벌어졌다 모였다 하는 성질을 이용한 추세 지표예요.","e":"MACD = 단기 EMA − 장기 EMA이고, MACD의 이동평균인 시그널선을 상향 돌파하면 매수, 하향 돌파하면 매도 신호로 봐요.","w":[null,"투자심리선이에요.","OBV예요.","일목균형표 전환선·기준선의 개념이에요."],"k":"단기선과 장기선의 \"거리\"를 그래프로 그린 거예요.","m":"MACD = 단기EMA − 장기EMA · 시그널 = MACD의 EMA"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"RSI 계산","q":"최근 14일 동안 상승폭 합계가 42포인트, 하락폭 합계가 18포인트일 때 RSI와 그 해석으로 옳은 것은?","o":["233, 과열","57, 중립","30, 과매도 구간","70, 과매수 구간 진입 가능성"],"a":3,"c":"RSI는 상승폭이 전체 변동폭에서 차지하는 비율로 매수·매도 세력의 강도를 나타내요.","e":"RSI = 42 ÷ (42 + 18) × 100 = 70이에요. 보통 70 이상이면 과매수, 30 이하면 과매도로 봐요.","w":["상승폭 ÷ 하락폭이에요.","계산이 맞지 않아요.","하락폭 비율이에요.",null],"k":"움직인 60포인트 중 42포인트가 오른 쪽이었어요.","m":"RSI = 상승폭 ÷ (상승폭 + 하락폭) × 100 · 70↑ 과매수 · 30↓ 과매도","f":"42 ÷ 60 = 70"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"투자심리선","q":"최근 10일 중 8일 주가가 올랐을 때 투자심리선과 일반적 해석으로 옳은 것은?","o":["80%, 과열 국면으로 매도 고려","80%, 침체 국면으로 매수 고려","20%, 과열 국면","8%, 중립"],"a":0,"c":"투자심리선은 최근 일정 기간 중 주가가 오른 날의 비율이에요.","e":"8 ÷ 10 = 80%예요. 보통 75% 이상이면 과열, 25% 이하면 침체로 봐요.","w":[null,"해석이 반대예요.","하락일 비율이에요.","계산이 맞지 않아요."],"k":"열흘 중 여드레 올랐으면 분위기가 너무 뜨거워요.","m":"투자심리선 = 상승일 수 ÷ 기간 × 100 · 75%↑ 과열 · 25%↓ 침체","f":"8 ÷ 10 = 80%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"ADL(등락주선)","q":"ADL(등락주선)에 관한 설명으로 가장 적절한 것은?","o":["상승 종목 수에서 하락 종목 수를 뺀 값을 누적해 시장 내부의 힘을 본다","개별 종목 거래량을 누적한다","종가를 이동평균으로 나눈다","하루 중 최고가와 최저가의 차이이다"],"a":0,"c":"지수는 대형주 몇 개 때문에 오를 수도 있어요. 시장 전체가 함께 오르는지 보는 지표가 필요해요.","e":"ADL은 매일 상승 종목 수 − 하락 종목 수를 누적한 값이에요. 지수는 오르는데 ADL이 내리면 시장 내부가 약해진 것으로 봐요.","w":[null,"OBV에 가까운 설명이에요.","이격도예요.","일중 변동폭이에요."],"k":"대장주 몇 개만 오르는지, 시장 전체가 오르는지 가려내요.","m":"ADL = Σ(상승종목 수 − 하락종목 수)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"볼린저밴드","q":"볼린저밴드에 관한 설명으로 가장 적절한 것은?","o":["이동평균선을 중심으로 표준편차의 일정 배수만큼 위아래에 밴드를 그린다","밴드 폭은 변동성과 관계없이 일정하다","단기 이동평균과 장기 이동평균의 차이를 나타낸다","거래량만으로 계산한다"],"a":0,"c":"볼린저밴드는 가격 변동성을 반영해 폭이 넓어졌다 좁아졌다 해요.","e":"보통 20일 이동평균 ± 2 표준편차로 밴드를 그려요. 변동성이 커지면 밴드가 넓어지고, 작아지면 좁아져요.","w":[null,"변동성에 따라 폭이 변해요.","MACD 개념이에요.","가격으로 계산해요."],"k":"평균선 둘레에 \"흔들림 2배\" 울타리를 친 거예요.","m":"볼린저밴드 = 이동평균 ± k × σ (보통 20일 ± 2σ)"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"약세 다이버전스","q":"주가는 직전 고점을 넘어 신고가를 기록했는데 RSI는 직전 고점보다 낮은 고점을 만들었다. 이에 대한 해석으로 가장 적절한 것은?","o":["강한 상승 추세가 더 이어진다는 확인 신호이다","거래량이 급증한다는 신호이다","지표와 주가가 같은 방향이므로 의미가 없다","상승 탄력이 약해져 하락 반전 가능성을 경고하는 신호이다"],"a":3,"c":"주가와 지표가 반대 방향으로 움직이는 것을 다이버전스라고 해요.","e":"주가는 오르는데 지표 고점이 낮아지면 상승의 힘이 약해졌다는 뜻이라 하락 반전 가능성을 경고하는 약세 다이버전스예요.","w":["반대 해석이에요.","거래량과 직접 관련 없어요.","방향이 서로 달라요.",null],"k":"키는 커졌는데 체력은 떨어진 상태예요.","m":"약세 다이버전스 = 주가 고점↑ 지표 고점↓ → 하락 경고"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"정배열","q":"주가 위에서부터 단기 → 중기 → 장기 이동평균선 순서로 놓인 배열과 그 의미로 옳은 것은?","o":["정배열, 상승 추세","역배열, 하락 추세","정배열, 하락 추세","역배열, 상승 추세"],"a":0,"c":"이동평균선이 놓인 순서로 현재 추세를 판단할 수 있어요.","e":"주가 > 단기 > 중기 > 장기 이평선 순서는 정배열로 상승 추세를 뜻해요. 반대 순서는 역배열로 하락 추세예요.","w":[null,"반대 순서일 때예요.","의미가 반대예요.","이름과 의미 모두 반대예요."],"k":"최근 값일수록 위에 있으면 계속 올라가고 있는 거예요.","m":"정배열 = 주가 > 단기 > 중기 > 장기 (상승)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"일목균형표의 후행스팬","q":"일목균형표에서 당일 종가를 26일 뒤로(과거 쪽으로) 옮겨 그린 선은?","o":["전환선","기준선","선행스팬","후행스팬"],"a":3,"c":"일목균형표는 전환선, 기준선, 선행스팬 1·2, 후행스팬으로 이루어져요.","e":"당일 종가를 26일 과거 쪽으로 옮겨 그린 선이 후행스팬이에요. 전환선은 9일, 기준선은 26일의 (최고가 + 최저가) ÷ 2예요.","w":["9일 (최고 + 최저) ÷ 2예요.","26일 (최고 + 최저) ÷ 2예요.","미래 쪽으로 옮겨 그려 구름대를 만들어요.",null],"k":"\"뒤따라오는\" 선이라 후행스팬이에요.","m":"전환선 9일 · 기준선 26일 · 선행스팬 → 미래 26일 · 후행스팬 = 종가를 과거 26일"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"망치형과 교수형","q":"몸통이 작고 아래꼬리가 긴 같은 모양의 캔들이 하락 추세 바닥에서 나타나면 ( ㉠ ), 상승 추세 고점에서 나타나면 ( ㉡ )이라 한다. ㉠·㉡에 맞는 것은?","o":["㉠ 망치형(상승 반전), ㉡ 교수형(하락 반전)","㉠ 교수형(하락 반전), ㉡ 망치형(상승 반전)","㉠ 도지형, ㉡ 장악형","㉠ 샛별형, ㉡ 석별형"],"a":0,"c":"캔들은 같은 모양이라도 어디에서 나왔는지에 따라 의미가 달라져요.","e":"바닥에서 나오면 망치형으로 상승 반전 신호, 고점에서 나오면 교수형으로 하락 반전 신호예요.","w":[null,"위치가 반대예요.","모양이 다른 캔들이에요.","세 개의 캔들로 이루어진 패턴이에요."],"k":"바닥에서 망치로 땅을 \"탕\" 치고 올라가요.","m":"아래꼬리 긴 캔들: 바닥 = 망치형(↑) · 고점 = 교수형(↓)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"하","rev":0,"t":"도지형 캔들","q":"시가와 종가가 거의 같아 몸통이 거의 없는 십자 모양 캔들이 뜻하는 것으로 가장 적절한 것은?","o":["거래량이 0이었다","강한 상승 추세가 확정되었다","매수세와 매도세가 팽팽해 추세 전환 가능성을 시사한다","반드시 다음 날 갭 상승한다"],"a":2,"c":"몸통은 시가와 종가의 차이예요. 몸통이 없다면 하루 종일 싸웠지만 승부가 나지 않은 거예요.","e":"도지형은 매수·매도 세력이 균형을 이룬 상태로, 추세의 끝에서 나타나면 전환 가능성을 시사해요.","w":["거래량과 무관해요.","방향이 정해지지 않은 상태예요.",null,"확정된 예측이 아니에요."],"k":"줄다리기가 무승부로 끝난 하루예요.","m":"도지 = 시가 ≈ 종가 · 균형 · 전환 가능성"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"상승장악형","q":"하락 추세에서 전날의 작은 음봉 몸통을 다음 날의 큰 양봉 몸통이 완전히 감싸는 패턴은?","o":["상승장악형","하락장악형","흑운형","석별형"],"a":0,"c":"두 개의 캔들로 이루어진 반전 패턴은 뒤의 캔들이 앞의 캔들을 얼마나 압도하는지 봐요.","e":"하락 추세 끝에서 큰 양봉이 전날 음봉을 감싸면 상승장악형으로 상승 반전 신호예요.","w":[null,"상승 추세에서 큰 음봉이 양봉을 감쌀 때예요.","상승 추세에서 음봉이 전날 양봉 중간 아래로 파고들 때예요.","고점에서 나오는 세 캔들 하락 반전형이에요."],"k":"어제 판 사람보다 오늘 산 사람이 훨씬 세요.","m":"상승장악형 = 하락 끝 · 큰 양봉이 음봉을 감쌈"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"섬꼴반전","q":"상승 추세에서 갭 상승 후 며칠 거래되다가 다시 갭 하락하여, 그 구간이 섬처럼 고립되는 패턴의 의미는?","o":["강한 하락 반전 신호","상승 추세 지속 신호","거래량 감소 신호","아무 의미 없음"],"a":0,"c":"섬꼴반전은 소멸갭과 돌파갭이 연달아 나타나 가격 구간이 고립된 모양이에요.","e":"상승 추세 끝에서 섬꼴이 나오면 강한 하락 반전 신호로 봐요. 하락 추세 끝이면 상승 반전 신호예요.","w":[null,"반대예요.","거래량 지표가 아니에요.","중요한 반전 패턴이에요."],"k":"위로 뛰어올랐다가 다리가 끊겨 고립된 섬이에요.","m":"섬꼴반전 = 소멸갭 + 반대 방향 돌파갭 → 강한 반전"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"헤드앤숄더","q":"헤드앤숄더(머리어깨형) 패턴에 관한 설명으로 가장 적절하지 않은 것은?","o":["목선을 하향 돌파하면 매도 신호로 본다","가운데 고점(머리)이 양쪽 고점(어깨)보다 높다","대개 오른쪽 어깨에서 거래량이 가장 크게 늘어난다","상승 추세의 끝에서 나타나는 대표적 하락 반전형이다"],"a":2,"c":"헤드앤숄더는 고점이 세 번 만들어지고 가운데가 가장 높은 반전 패턴이에요.","e":"거래량은 대개 왼쪽 어깨나 머리에서 많고, 오른쪽 어깨에서는 줄어드는 경향이 있어요. 매수세가 약해졌다는 뜻이에요.","w":["목선 붕괴 = 매도 신호예요.","머리가 가장 높아요.",null,"대표 하락 반전형이에요."],"k":"세 번째 봉우리에서는 오를 힘(거래량)이 빠져 있어요.","m":"헤드앤숄더: 좌어깨·머리·우어깨 · 목선 하향 돌파 = 매도 · 우어깨 거래량↓"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"깃발형 패턴","q":"깃발형 패턴에 관한 설명으로 가장 적절한 것은?","o":["장기간에 걸쳐 둥근 바닥을 만드는 반전형이다","거래량이 조정 구간에서 크게 늘어난다","고점이 세 번 나타나는 반전형이다","급격한 가격 변동 뒤 짧은 기간 평행한 조정이 나타나고, 이후 기존 추세가 이어지는 경우가 많다"],"a":3,"c":"깃발형은 깃대(급등·급락)와 깃발(짧은 조정)로 이루어진 모양이에요.","e":"깃발형은 급한 움직임 뒤 짧게 쉬어 가는 지속형 패턴이에요. 조정 구간에서는 거래량이 줄고, 돌파 때 다시 늘어요.","w":["원형 바닥형이에요.","조정 구간에서는 줄어요.","헤드앤숄더 등이에요.",null],"k":"달리다 잠깐 숨 고르고 다시 같은 방향으로 뛰어요.","m":"깃발형 = 깃대(급변) + 깃발(짧은 조정) → 추세 지속"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"지지와 저항의 역할 전환","q":"지지선과 저항선에 관한 설명으로 가장 적절한 것은?","o":["강하게 뚫린 저항선은 이후 지지선 역할을 하는 경우가 많다","지지선은 한 번 정해지면 절대 뚫리지 않는다","저항선은 주가가 내려가지 못하게 막는 선이다","지지선과 저항선은 거래량과 관계가 없다"],"a":0,"c":"지지선은 하락을 멈추게 하는 가격대, 저항선은 상승을 막는 가격대예요.","e":"저항선을 강하게 뚫고 올라가면 그 가격대가 이후 지지선이 되는 경우가 많아요. 반대로 무너진 지지선은 저항선이 되기 쉬워요.","w":[null,"뚫릴 수 있어요.","지지선의 설명이에요.","거래량이 많았던 가격대일수록 강해요."],"k":"어제의 천장이 오늘의 바닥이 돼요.","m":"돌파된 저항 → 지지 · 붕괴된 지지 → 저항"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"추세선의 신뢰도","q":"추세선의 신뢰도를 높이는 조건으로 가장 적절하지 않은 것은?","o":["추세선에 닿은 저점(고점)의 수가 많다","추세선이 형성된 기간이 길다","추세선의 기울기가 완만하다","추세선의 기울기가 매우 가파르다"],"a":3,"c":"추세선은 저점끼리(상승 추세) 또는 고점끼리(하락 추세) 이은 선이에요.","e":"기울기가 너무 가파른 추세선은 오래 유지되기 어려워 신뢰도가 낮아요. 접점이 많고, 기간이 길고, 완만할수록 신뢰도가 높아요.","w":["접점이 많을수록 신뢰도가 높아요.","기간이 길수록 신뢰도가 높아요.","완만할수록 신뢰도가 높아요.",null],"k":"급경사 오르막은 금방 숨이 차요.","m":"추세선 신뢰도↑: 접점 多 · 기간 長 · 기울기 완만"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"거래량과 추세","q":"거래량과 주가의 관계에 관한 일반적 원칙으로 가장 적절한 것은?","o":["상승 추세에서는 오를 때 거래량이 늘고 조정 때 거래량이 줄어야 추세가 건강하다","주가 상승 중 거래량이 계속 줄면 상승 추세가 강해진다는 뜻이다","거래량은 주가와 전혀 관계없다","천장권에서는 항상 거래량이 감소한 뒤 주가가 오른다"],"a":0,"c":"거래량은 추세를 확인해 주는 역할을 해요.","e":"상승 추세가 건강하려면 오를 때 거래량이 늘고 쉬어 갈 때 줄어야 해요. 상승 중 거래량이 줄면 추세가 약해졌다는 신호예요.","w":[null,"상승 탄력 약화 신호예요.","거래량은 추세 확인에 중요해요.","맞지 않아요."],"k":"사람들이 몰려서 사야 진짜 오르는 거예요.","m":"추세 방향 거래량↑ · 조정 거래량↓ = 건강한 추세"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"시간 개념이 없는 차트","q":"가격이 일정 폭 이상 움직일 때만 기록하고 시간의 흐름은 고려하지 않는 차트는?","o":["봉차트","선차트","P&F(점수도표) 차트","바차트"],"a":2,"c":"대부분의 차트는 가로축이 시간이지만, 시간을 무시하고 가격 변화만 기록하는 차트도 있어요.","e":"P&F 차트는 정해진 가격 폭 이상 오르면 X, 내리면 O를 기록하며 시간은 고려하지 않아요. 삼선전환도도 시간을 무시하는 차트예요.","w":["날짜별로 시가·고가·저가·종가를 그려요.","날짜별 종가를 이어요.",null,"날짜별 고가·저가·종가를 그려요."],"k":"시계는 보지 않고 \"얼마나 움직였나\"만 적어요.","m":"시간 무시 차트: P&F · 삼선전환도"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"사께다 전법의 삼산","q":"사께다 전법에서 큰 산 세 개가 나란히 있는 모양으로, 천장권에서 나타나는 패턴은?","o":["삼산(삼존천정형)","삼천(삼존바닥형)","삼공","삼병"],"a":0,"c":"사께다 전법은 삼산, 삼천, 삼공, 삼병, 삼법으로 이루어진 일본식 캔들 분석법이에요.","e":"삼산은 고점이 세 번 나타나는 천장권 패턴으로, 서양의 헤드앤숄더와 비슷해요.","w":[null,"바닥권 패턴이에요.","갭이 세 번 나타나는 거예요.","같은 색 캔들 세 개가 연속되는 거예요."],"k":"봉우리 세 개 = 꼭대기, 골짜기 세 개 = 바닥이에요.","m":"삼산 = 천장 · 삼천 = 바닥 · 삼공 = 갭 3번 · 삼병 = 연속 3봉 · 삼법 = 쉬기"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"적삼병","q":"바닥권에서 양봉 세 개가 연속으로 나타나며 종가가 계속 높아지는 패턴의 의미로 가장 적절한 것은?","o":["상승 전환 신호","하락 전환 신호","추세 없음","거래 정지 신호"],"a":0,"c":"사께다 전법의 삼병은 같은 색 캔들 세 개가 연속되는 패턴이에요.","e":"바닥권에서 양봉 세 개가 연속되는 적삼병은 상승 전환 신호, 고점에서 음봉 세 개가 연속되는 흑삼병은 하락 전환 신호예요.","w":[null,"흑삼병의 의미예요.","분명한 신호예요.","관련 없어요."],"k":"빨간 기둥 세 개가 계단처럼 올라가요.","m":"적삼병(양봉 3) = 상승 · 흑삼병(음봉 3) = 하락"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"이중바닥형","q":"이중바닥형(W자형) 패턴에서 매수 신호로 보는 시점은?","o":["두 바닥 사이 고점(목선)을 상향 돌파할 때","첫 번째 바닥이 만들어질 때","두 번째 바닥에서 하락이 시작될 때","목선을 하향 돌파할 때"],"a":0,"c":"이중바닥은 저점을 두 번 확인한 뒤 상승으로 돌아서는 반전 패턴이에요.","e":"두 바닥 사이의 고점(목선)을 거래량과 함께 상향 돌파할 때 패턴이 완성된 것으로 보고 매수 신호로 봐요.","w":[null,"패턴이 완성되지 않았어요.","바닥 확인 전이에요.","이중천장의 매도 신호예요."],"k":"바닥을 두 번 다지고, 가운데 언덕을 넘어설 때가 출발 신호예요.","m":"이중바닥 = 목선 상향 돌파 시 매수 · 이중천장 = 목선 하향 돌파 시 매도"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"원형바닥형","q":"오랜 기간 서서히 하락하다가 바닥을 둥글게 다진 뒤 서서히 오르는 패턴에 관한 설명으로 가장 적절한 것은?","o":["원형바닥형으로, 상승 반전 패턴이다","깃발형으로, 하락 지속 패턴이다","섬꼴반전으로, 하락 반전 패턴이다","페넌트형으로, 하락 반전 패턴이다"],"a":0,"c":"반전 패턴 중에는 급하게 바뀌는 것도 있고, 오랜 시간 천천히 바뀌는 것도 있어요.","e":"원형바닥형은 장기간 둥글게 바닥을 만들며 상승으로 전환하는 반전형이에요. 거래량도 바닥 부근에서 줄었다가 상승하면서 늘어나요.","w":[null,"깃발형은 짧은 조정 후 지속형이에요.","섬꼴은 갭으로 고립된 모양이에요.","페넌트는 지속형이에요."],"k":"그릇(접시) 모양으로 천천히 돌아 올라가요.","m":"원형바닥 = 장기 · 상승 반전 · 거래량도 U자"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"EV/EBITDA의 장점","q":"기업 간 가치를 비교할 때 EV/EBITDA를 쓰는 이유로 가장 적절한 것은?","o":["적자 기업과 흑자 기업 모두 EBITDA가 항상 양수다","감가상각 방법과 자본구조(부채 수준) 차이의 영향을 덜 받아 기업 간 비교가 쉽다","주주 몫의 가치만 정확히 보여 준다","배당 정책을 직접 반영한다"],"a":1,"c":"EV는 주주와 채권자 몫을 합친 기업 전체 가치, EBITDA는 이자·세금·감가상각 전 이익이에요.","e":"EBITDA는 감가상각과 이자 비용을 빼기 전 이익이고 EV는 부채까지 포함하므로, 감가상각 방법이나 부채 비율이 다른 기업끼리도 비교하기 쉬워요.","w":["EBITDA도 음수가 될 수 있어요.",null,"EV는 채권자 몫까지 포함한 기업 전체 가치예요.","배당과 직접 관계없어요."],"k":"빚이 많든 적든, 감가상각을 어떻게 하든 \"본업으로 버는 힘\"을 비교해요.","m":"EV/EBITDA: 자본구조·감가상각·세제 차이 영향↓ · 기업 전체 가치 비교"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"PCR(주가현금흐름비율)","q":"PER 대신 PCR(주가 ÷ 주당현금흐름)을 함께 보는 이유로 가장 적절한 것은?","o":["배당을 지급하지 않는 기업은 평가할 수 없다","부채가 많은 기업만 평가할 수 있다","감가상각 방법 등 회계 처리 차이로 인한 이익 왜곡을 줄일 수 있다","주가와 무관하게 기업가치를 구할 수 있다"],"a":2,"c":"회계상 이익은 감가상각 방법 등에 따라 달라질 수 있지만, 현금흐름은 상대적으로 덜 영향을 받아요.","e":"PCR은 이익 대신 현금흐름을 쓰기 때문에 회계 처리 방식 차이에 따른 왜곡을 줄이고 기업 간 비교가 쉬워요.","w":["배당과 관계없어요.","부채와 관계없어요.",null,"주가를 분자로 써요."],"k":"장부 이익은 꾸밀 수 있어도, 들어온 현금은 꾸미기 어려워요.","m":"PCR = 주가 ÷ 주당 현금흐름 · 회계 왜곡 완화"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"투자안 현금흐름 추정 원칙","q":"신규 투자안의 증분현금흐름을 추정하는 원칙으로 가장 적절하지 않은 것은?","o":["투자 여부와 관계없이 이미 써 버린 시장조사 비용은 현금흐름에 넣지 않는다","감가상각비는 현금이 나가지 않는 비용이므로 법인세 계산을 포함해 현금흐름 추정에서 완전히 무시한다","회사가 놀리던 창고를 새 사업에 쓰면 그 창고를 팔거나 빌려줬을 때 얻을 수 있던 금액을 비용으로 반영한다","새 제품 때문에 기존 제품 판매가 줄어드는 효과도 현금흐름에 반영한다"],"a":1,"c":"투자안의 현금흐름은 '이 투자를 해서 새로 늘거나 줄어드는 현금'만 세후 기준으로 잡아요.","e":"감가상각비 자체는 현금 유출이 아니지만, 세금을 매기는 이익을 줄여서 법인세를 덜 내게 해 줘요. 이 절세효과(감가상각비 × 법인세율)는 현금흐름에 반영해야 해요.","w":["이미 써서 되돌릴 수 없는 매몰원가는 투자 결정과 무관하므로 빼요.",null,"자기 자산을 쓰더라도 포기한 대가(기회비용)는 비용으로 반영해요.","기존 제품 매출을 잠식하는 부수효과도 증분현금흐름에 들어가요."],"k":"이미 엎질러진 물(매몰원가)은 세지 않고, 포기한 기회는 세고, 감가상각은 '세금 깎아 주는 쿠폰'으로 세요.","m":"현금흐름 추정: 매몰원가 제외 · 기회비용·잠식효과 포함 · 감가상각 절세효과 반영 · 세후 기준"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"재무비율의 분류와 출처","q":"재무비율의 분류에 관한 설명으로 가장 적절한 것은?","o":["이자보상비율과 고정비용보상비율은 기업이 지금의 재무적 부담을 감당할 수 있는지 보는 보상비율에 속한다","당좌비율은 기업의 이익 창출력을 보는 수익성 비율이다","총자산회전율은 계산에 필요한 숫자를 손익계산서 한 곳에서 모두 얻는다","부채비율은 자산을 얼마나 효율적으로 쓰는지 보는 활동성 비율이다"],"a":0,"c":"재무비율은 유동성·안정성·수익성·활동성·보상비율 등으로 나눠요. 무엇을 재려는지에 따라 분류가 정해져요.","e":"이자보상비율(영업이익 ÷ 이자비용)과 고정비용보상비율은 지금 짊어진 이자·고정비 부담을 이익으로 감당할 수 있는지 보는 보상비율이에요. 이자보상비율은 두 숫자를 모두 손익계산서에서 가져와요.","w":[null,"당좌비율은 단기 지급능력을 보는 유동성 비율이에요.","총자산회전율은 매출액(손익계산서) ÷ 총자산(재무상태표)이라 두 재무제표를 함께 쓰는 비율이에요.","부채비율은 재무구조가 얼마나 튼튼한지 보는 안정성 비율이에요."],"k":"보상비율은 '번 돈으로 이자 청구서를 몇 번 낼 수 있나'를 세는 비율이에요.","m":"유동성: 유동·당좌·현금비율 · 안정성: 부채비율 · 활동성: 회전율 · 보상: 이자보상·고정비용보상"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"재무비율 해석의 함정","q":"재무비율의 해석으로 가장 적절하지 않은 것은?","o":["이자보상비율이 1 미만이면 영업에서 번 이익이 이자비용에도 못 미친다는 뜻이다","유동자산 가운데 재고자산 비중이 큰 기업은 유동비율만 보면 단기 상환능력을 실제보다 좋게 볼 수 있다","매출채권회전율이 짧은 기간에 갑자기 크게 오르면 회수 관리가 좋아진 우량 신호로만 본다","부채비율이 높아지면 재무위험이 커지므로 주주의 요구수익률도 올라간다"],"a":2,"c":"재무비율은 숫자 하나만 보지 말고, 왜 그렇게 바뀌었는지와 다른 비율을 함께 봐야 해요.","e":"회전율이 갑자기 치솟는 것은 재고를 헐값에 처분하거나 매출채권을 큰 할인을 받고 현금화한 결과일 수 있어요. 그래서 오히려 부실 징후로 의심해 봐야 해요.","w":["이자보상비율 1 미만은 번 돈(영업이익)이 이자비용보다 적다는 뜻이에요.","재고자산은 바로 현금이 되지 않아요. 그래서 재고를 뺀 당좌비율로 보완해요.",null,"빚이 많을수록 주주가 지는 위험이 커져 기대(요구)수익률도 올라가요."],"k":"외상값이 갑자기 빨리 돈으로 바뀌었다면 장사가 잘돼서일 수도 있지만, 급해서 헐값에 넘긴 것일 수도 있어요.","m":"회전율 급등 = 부실 의심 · 이자보상 < 1 = 이자도 못 냄 · 유동비율 과대평가 → 당좌비율로 보완"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"PEG 비율(PEGR)","q":"A주식은 PER 20배, 향후 연평균 EPS 성장률 25%이고, B주식은 PER 12배, 성장률 8%이다. PEGR을 이용한 판단으로 가장 적절한 것은?","o":["PER이 낮은 B가 성장성과 관계없이 항상 더 싸다","A의 PEGR은 0.8, B는 1.5로 성장성을 감안하면 A가 상대적으로 저평가되어 있다","A의 PEGR은 1.25, B는 약 0.67로 성장성을 감안하면 B가 상대적으로 저평가되어 있다","PEGR 값이 클수록 성장 대비 주가가 싸다는 뜻이므로 B가 유리하다"],"a":1,"c":"PEGR은 PER을 이익 성장률(%)로 나눠, 성장성에 비해 PER이 비싼지 싼지를 보는 지표예요.","e":"PEGR = PER ÷ 성장률이에요. A는 20 ÷ 25 = 0.8, B는 12 ÷ 8 = 1.5예요. 값이 작을수록 성장 대비 주가가 싸다고 보므로 A가 상대적으로 저평가예요.","w":["PER만 보면 성장성 차이를 놓쳐요. 빨리 성장하는 기업은 PER이 높아도 비싸지 않을 수 있어요.",null,"성장률을 PER로 나눴어요. PEGR은 PER을 성장률로 나눠요.","PEGR은 낮을수록 저평가로 해석해요."],"k":"비싸 보이는 빵(높은 PER)도 크기(성장률)가 훨씬 크면 오히려 싼 거예요.","m":"PEGR = PER ÷ EPS 성장률(%) → 낮을수록 저평가","f":"A: 20 ÷ 25 = 0.8 · B: 12 ÷ 8 = 1.5"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"PBR이 1이 아닌 이유","q":"실제 주식시장에서 PBR이 1과 다르게 나타나는 이유로 보기 어려운 것은?","o":["주가는 앞으로 벌 이익에 대한 기대를 담지만 주당순자산은 과거 취득원가를 바탕으로 하기 때문이다","주가는 기업 전체를 하나의 조직으로 평가하지만 순자산은 개별 자산 합계에서 부채를 뺀 값이기 때문이다","브랜드나 인적자원처럼 회계기준상 장부에 잡히지 않는 가치가 있기 때문이다","주가와 주당순자산이 똑같이 오늘의 시장가격으로 평가되기 때문이다"],"a":3,"c":"PBR은 주가 ÷ 주당순자산(BPS)이에요. 분자와 분모의 측정 시점·범위·기준이 달라서 1에서 벗어나요.","e":"두 값이 똑같이 오늘의 시장가격으로 평가된다면 PBR은 오히려 1에 가까워야 해요. 실제로는 주가는 미래 기대, 순자산은 과거 원가라서 시점부터 달라요. 이 시점 차이를 보완하려고 분모에 대체원가를 쓰는 지표가 토빈의 Q예요.","w":["측정 시점의 차이(미래 기대 vs 과거 원가)예요.","측정 범위의 차이(하나의 조직 vs 개별 자산의 합)예요.","측정 기준의 차이로, 장부가액은 회계 관습과 인식 기준의 제약을 받아요.",null],"k":"중고차 시세(주가)와 처음 산 영수증 금액(장부가)이 같을 리 없는 것과 같아요.","m":"PBR ≠ 1 이유: 시점(미래 vs 과거) · 범위(전체 vs 개별 합) · 기준(회계 관습)"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"PER의 해석","q":"PER을 설명한 〈보기〉에서 옳은 것의 개수는?\nㄱ. 지금의 이익 수준으로 투자원금을 회수하는 데 걸리는 기간으로 볼 수 있다.\nㄴ. PER의 역수(EPS ÷ 주가)는 그 주식의 기대수익률로 해석할 수 있다.\nㄷ. 경기 전망이 나빠지면 PER은 오히려 높아지는 것이 일반적이다.\nㄹ. 다른 조건이 같다면 요구수익률이 오르면 PER은 낮아지고, 기대 성장률이 오르면 PER은 높아진다.\nㅁ. 이익 변동이 큰 경기민감 업종이나 적자 기업에는 PER을 적용하기 어렵다.","o":["2개","3개","4개","5개"],"a":2,"c":"PER은 주가 ÷ EPS로, 이익 1원에 시장이 몇 원을 쳐 주는지를 보여 줘요.","e":"ㄱ, ㄴ, ㄹ, ㅁ이 옳아 4개예요. 전망이 나빠지면 그 기대가 주가에 먼저 반영되므로 PER은 오히려 낮아지는 것이 일반적이에요.","w":["옳은 것은 4개예요.","옳은 것은 ㄱ·ㄴ·ㄹ·ㅁ 4개예요. 틀린 것은 ㄷ 하나뿐이에요.",null,"ㄷ은 틀렸어요. 비관적일수록 PER은 낮아져요."],"k":"PER 10배는 '지금 이익이 그대로면 10년 만에 본전'이라는 뜻이에요.","m":"PER: 회수기간 · 역수 = 기대수익률 · k↑ → PER↓ · g↑ → PER↑ · 경기민감·적자 기업엔 부적합"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"2단계 배당할인모형","q":"A사의 주당배당금은 1년 뒤 2,000원, 2년 뒤 2,200원으로 예상되고, 3년째부터는 해마다 5%씩 영구히 늘어난다. 투자자의 요구수익률이 15%라면 A사 주식의 적정 가치에 가장 가까운 것은?","o":["20,000원","23,739원","25,300원","20,870원"],"a":3,"c":"배당 성장 방식이 중간에 바뀌면, 일정 성장이 시작되는 시점의 주가부터 계산한 다음 앞의 배당과 함께 현재로 할인해요.","e":"2년 말 주가 P₂ = 2,200 × 1.05 ÷ (0.15 − 0.05) = 23,100원이에요. P₀ = 2,000 ÷ 1.15 + (2,200 + 23,100) ÷ 1.15² ≈ 1,739 + 19,130 ≈ 20,870원이에요.","w":["처음부터 5%로 성장한다고 보고 2,000 ÷ 0.10으로 계산했어요.","2년 말 금액(2,200원 + 23,100원)을 1년만 할인했어요.","2년 말 금액(2,200원 + 23,100원)을 할인하지 않고 그대로 썼고, 1년 뒤 배당 2,000원의 현재가치도 빠뜨렸어요.",null],"k":"앞 2년은 계단을 한 칸씩 세고, 그 뒤는 엘리베이터(항상성장 공식)로 한 번에 올라간 다음, 모두 현재로 끌어와요.","m":"2단계 DDM: P₂ = D₃ ÷ (k − g) → P₀ = D₁/(1+k) + (D₂ + P₂)/(1+k)²","f":"P₂ = 2,310 ÷ 0.10 = 23,100 → P₀ = 2,000/1.15 + 25,300/1.15² ≈ 20,870원"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산업경쟁력 분석모형의 세 축","q":"경쟁자산·시장구조·산업성과의 세 축으로 산업경쟁력을 진단하는 모형에서, 〈보기〉 가운데 '산업성과' 축에 속하는 항목만 묶은 것은?\nㄱ. 산업 성장률\nㄴ. 기업 간 경쟁 정도\nㄷ. 노동생산성\nㄹ. 기술력과 인적자본\nㅁ. 수출실적","o":["ㄱ, ㄷ, ㅁ","ㄴ, ㄹ","ㄱ, ㄴ, ㅁ","ㄷ, ㄹ, ㅁ"],"a":0,"c":"이 모형은 산업이 가진 밑천(경쟁자산), 경쟁 환경(시장구조), 그 결과(산업성과)로 경쟁력을 나눠 봐요.","e":"산업성과 축에는 산업 성장률, 생산성, 외부효과, 수출실적이 들어가요. 그래서 ㄱ, ㄷ, ㅁ이 해당해요.","w":[null,"ㄴ의 경쟁 정도는 시장구조, ㄹ의 기술력·인적자본은 경쟁자산에 속해요.","ㄴ의 경쟁 정도는 정부규제·연관산업과 함께 시장구조에 속해요.","ㄹ의 기술력·인적자본은 물적자본·인프라·수요조건 등과 함께 경쟁자산에 속해요."],"k":"경쟁자산은 '선수의 체력', 시장구조는 '경기장 환경', 산업성과는 '경기 성적표'예요.","m":"경쟁자산(기술·인적·물적자본 등) · 시장구조(경쟁·규제·연관산업) · 산업성과(성장률·생산성·수출실적·외부효과)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산업구조 변화 이론의 비교","q":"산업구조 변화를 설명하는 이론에 관한 설명으로 가장 적절하지 않은 것은?","o":["내생적 성장이론은 교육·연구개발을 통한 요소 창출보다 원래 주어진 요소 부존을 더 중시한다","리카도의 비교우위론은 나라 간 노동 투입량(생산비) 차이로 산업의 상대적 우위를 설명한다","헥셔-올린 모형은 나라마다 상대적으로 풍부한 생산요소를 많이 쓰는 산업이 발달한다고 본다","제품수명주기 이론은 기술 혁신 역량과 새 제품을 만드는 능력 같은 공급 측 힘을 산업구조 변화의 동력으로 본다"],"a":0,"c":"산업구조 이론은 '원래 가진 조건'을 중시하는 전통 이론과 '스스로 만들어 내는 능력'을 중시하는 동태적 이론으로 나눠 볼 수 있어요.","e":"내생적 성장이론은 교육·R&D로 지식과 기술, 인적자본을 새로 키워 내는 요소 창출을 성장 동력으로 봐요. 요소 부존을 중시하는 것은 헥셔-올린 모형이에요.","w":[null,"비교우위론은 노동 투입량 차이에 따른 상대적 우위로 설명하는 정태적 전통 이론이에요.","헥셔-올린 모형은 요소 부존 차이를 중시하는 정태적 전통 이론이에요.","제품수명주기 이론은 기술혁신 같은 공급 능력을 중시하는 동태적 이론이에요."],"k":"타고난 재산(요소 부존)으로 사는 게 전통 이론, 공부해서 실력(요소 창출)을 키우는 게 내생적 성장이론이에요.","m":"정태적: 비교우위·헥셔-올린(요소 부존) · 동태적: 내생적 성장(요소 창출)·제품수명주기"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산업구조 변화의 법칙","q":"산업구조 변화에 관한 법칙과 그 내용의 연결로 가장 적절하지 않은 것은?","o":["페티-클라크의 법칙 – 소득이 늘수록 노동력의 중심이 1차 산업에서 2차·3차 산업으로 옮겨 간다","쿠즈네츠 – 이런 구조 변화가 노동력 말고도 생산액과 자본 구성에서도 나타남을 통계로 확인했다","호프만의 법칙 – 공업화가 진행될수록 제조업 안에서 생산재보다 소비재의 비중이 커진다","뵘바베르크의 우회생산론 – 경제가 발전할수록 총생산에서 중간재가 차지하는 비중이 커진다"],"a":2,"c":"경제가 발전하면서 산업의 무게중심이 어떻게 옮겨 가는지를 설명한 법칙들이에요.","e":"호프만의 법칙은 공업화가 진행될수록 제조업 안에서 소비재보다 생산재(자본재) 비중이 커진다는 내용이에요. 두 부문이 뒤바뀌었어요.","w":["페티-클라크의 법칙은 1차 → 2차 → 3차 산업으로 비중이 옮겨 간다는 내용이에요.","쿠즈네츠는 노동력 외에 생산·자본에서도 같은 흐름을 실증했어요.",null,"우회생산론은 생산 과정이 길어지면서 중간재 수요가 커진다는 내용이에요."],"k":"경제가 발전할수록 공장은 '물건 만드는 기계'를 더 많이 만들게 돼요. 그게 호프만의 법칙이에요.","m":"페티-클라크: 1차→2·3차 · 호프만: 생산재 비중↑ · 우회생산: 중간재 비중↑"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산업연관표 읽는 법","q":"산업연관표와 산업연관분석에 관한 설명으로 가장 적절한 것은?","o":["다른 산업들의 최종수요가 늘면서 어느 산업의 생산이 함께 느는 효과를 후방연쇄효과라 한다","국민소득통계처럼 중간재 거래는 빼고 최종생산물만 기록한다","표를 세로로 읽으면 각 산업의 투입구조를, 가로로 읽으면 산출물의 배분구조를 알 수 있다","한 산업의 투입 합계와 산출 합계는 일반적으로 일치하지 않는다"],"a":2,"c":"산업연관표는 산업끼리 무엇을 사고팔았는지를 한 표에 담아, 한 산업의 변화가 경제 전체에 어떻게 퍼지는지 보여 줘요.","e":"세로(열)는 그 산업이 생산에 무엇을 얼마나 썼는지(투입구조), 가로(행)는 만든 것을 어디에 팔았는지(배분구조)를 보여 줘요. 최종수요 1단위가 늘 때 모든 산업에서 직·간접으로 생기는 생산은 생산유발계수(레온티에프 역행렬계수)로 읽어요.","w":["그것은 전방연쇄효과예요. 후방연쇄효과는 어느 산업의 수요 증가가 원료를 대는 다른 산업의 생산을 끌어올리는 효과예요.","산업연관표는 국민소득통계에는 잡히지 않는 산업 간 중간재 거래까지 모두 담는 것이 특징이에요.",null,"세로로 더한 총투입액과 가로로 더한 총산출액은 항상 같아요."],"k":"세로는 '장보기 영수증', 가로는 '판매 장부'라고 생각하면 쉬워요.","m":"세로 = 투입구조 · 가로 = 배분구조 · 총투입 = 총산출 · 생산유발계수 = 레온티에프 역행렬"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"산업정책의 성격과 종류","q":"산업정책에 관한 설명으로 가장 적절하지 않은 것은?","o":["독과점·담합을 규제해 산업 안의 경쟁 질서를 바로잡는 것은 산업조직정책에 속한다","산업정책은 총수요보다 총공급 쪽을 관리해 경제성장을 직접 겨냥하는 공급 지향적 정책이다","산업정책은 경제가 성숙한 선진국일수록 더 강조되어 왔다","유망 산업을 집중 육성하거나 사양산업의 자원을 신산업으로 옮기는 것은 산업구조정책에 속한다"],"a":2,"c":"산업정책은 정부가 생산요소의 공급과 배분에 끼어들어 성장을 이끄는 정책이에요. 산업 안의 경쟁을 다루면 산업조직정책, 산업 사이의 비중을 다루면 산업구조정책이에요.","e":"산업정책은 역사적으로 발전이 늦게 시작된 후발국에서 더 강조되어 왔어요. 같은 나라라도 발전 단계가 바뀌면 알맞은 정책 수단도 달라져요.","w":["산업 내부의 경쟁 형태를 조정하는 것이 산업조직정책이에요. 허핀달지수 같은 집중도 지표도 여기서 쓰여요.","재정·금융으로 총수요를 관리하는 거시정책과 달리, 산업정책은 공급 측면을 관리해요.",null,"산업 간 자원 배분을 바꿔 바람직한 산업구조로 옮겨 가려는 것이 산업구조정책이에요."],"k":"따라잡아야 할 후발 주자일수록 코치(정부)가 훈련 계획을 더 꼼꼼히 짜 줘요.","m":"산업정책 = 공급 지향·후발국 강조 · 산업조직정책 = 산업 내 경쟁 · 산업구조정책 = 산업 간 배분"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"기술적 지표의 유형 구분","q":"〈보기〉의 기술적 지표 가운데 과열·침체 정도를 재어 추세가 꺾이는 시점을 찾는 추세반전형 지표를 모두 고른 것은?\nㄱ. MACD\nㄴ. RSI\nㄷ. OBV\nㄹ. 스토캐스틱\nㅁ. MAO\nㅂ. ROC","o":["ㄴ, ㄹ","ㄱ, ㄴ, ㄹ, ㅁ","ㄴ, ㄷ, ㄹ, ㅂ","ㄴ, ㄹ, ㅂ"],"a":3,"c":"기술적 지표는 추세를 따라가는 추세추종형, 과열·침체를 보는 추세반전형, 거래량으로 보는 거래량 지표로 나눠요.","e":"RSI, 스토캐스틱, ROC(그리고 CCI)는 과열·침체 정도를 재어 반전 시점을 찾는 추세반전형이에요. MACD·MAO·소나(Sonar)는 추세추종형, OBV·VR·역시계곡선은 거래량 지표예요.","w":["ROC도 추세반전형이에요.","MACD와 MAO는 이미 생긴 추세를 따라가는 추세추종형이에요.","OBV는 거래량 지표예요.",null],"k":"추세추종형은 '흐름 타기', 추세반전형은 '과속 단속', 거래량 지표는 '사람 수 세기'예요.","m":"추세추종: MACD·MAO·소나 · 추세반전: RSI·스토캐스틱·ROC·CCI · 거래량: OBV·VR·역시계곡선"},{"s":2,"sec":"투자분석기법","star":3,"lv":"상","rev":0,"t":"VR 계산과 해석","q":"어느 종목의 최근 20일 동안 주가 상승일 거래량 합계는 900만주, 하락일 거래량 합계는 300만주, 보합일 거래량 합계는 200만주였다. 이 종목의 VR과 그 해석으로 가장 적절한 것은?","o":["300%, 보합일 거래량은 계산에서 빼므로 과열 경계 신호이다","250%, 보통 수준으로 보는 150%는 넘지만 경계 신호로 보는 450%에는 못 미친다","250%, 70% 아래로 떨어졌으므로 단기 매수 신호이다","180%, 100%를 넘었으므로 곧바로 과열로 판단한다"],"a":1,"c":"VR은 상승일 거래량을 하락일 거래량과 비교한 지표예요. 보합일 거래량은 양쪽에 절반씩 나눠 넣어요.","e":"VR = (900 + 200 × ½) ÷ (300 + 200 × ½) × 100 = 1,000 ÷ 400 × 100 = 250%예요. 상승일 거래량이 보통 더 많아 150%를 보통 수준으로 보고, 450%를 넘으면 경계, 70% 이하면 단기 매수 시점으로 봐요. VR은 천장권보다 바닥권 판단에서 신뢰도가 높아요.","w":["보합일 거래량을 빼고 900 ÷ 300으로 계산했어요. 보합일 거래량은 절반씩 넣어요.",null,"250%는 70% 이하가 아니에요.","보합일 거래량을 하락 쪽에만 모두 넣었고, 보통 수준은 150%로 봐요."],"k":"VR은 '사는 날 손님 수 ÷ 파는 날 손님 수'예요. 애매한 날(보합)의 손님은 반반 나눠요.","m":"VR = (상승 + 보합/2) ÷ (하락 + 보합/2) · 보통 150% · 450%↑ 경계 · 70%↓ 매수","f":"(900 + 100) ÷ (300 + 100) × 100 = 250%"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"캔들 개수에 따른 반전 신호","q":"캔들차트의 반전 신호 가운데 캔들 두 개가 결합해 만들어지는 패턴끼리 묶은 것은?","o":["망치형, 교수형","샛별형, 석별형","장악형, 관통형","유성형, 까마귀형"],"a":2,"c":"캔들 반전 신호는 캔들 1개(망치형·교수형·유성형 등), 2개(장악형·관통형·잉태형·먹구름형), 3개(샛별형·석별형·까마귀형 등)로 나눠 외워요.","e":"장악형은 뒤의 큰 몸통이 앞 캔들 몸통을 감싸는 모양이고, 관통형은 음봉 다음 날 양봉이 앞 음봉 몸통의 절반 위까지 올라오는 상승 반전 신호예요. 둘 다 캔들 2개로 이루어져요. 관통형과 반대로 양봉 뒤의 음봉이 중심선 아래로 파고들면 먹구름형이에요.","w":["망치형과 교수형은 캔들 1개짜리 신호예요.","샛별형(하락 추세 바닥에서 긴 음봉 → 작은 몸통 → 긴 양봉)과 석별형(고점에서 반대 모양)은 캔들 3개짜리 신호예요.",null,"유성형은 1개, 까마귀형은 3개짜리 신호예요."],"k":"캔들 패턴은 '혼자(1개), 짝꿍(2개), 삼총사(3개)'로 나눠 외우면 쉬워요.","m":"1개: 망치·교수·유성 · 2개: 장악·관통·먹구름·잉태 · 3개: 샛별·석별·까마귀"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"갭의 종류와 위치","q":"갭(gap)에 관한 설명으로 가장 적절한 것은?","o":["돌파갭은 거래량이 적을 때 생기고 대개 금방 메워져 추세를 읽는 데 쓸모가 적다","소멸갭은 새 추세가 시작되는 출발점에서 나타나는 갭이다","급진갭(측정갭)은 추세가 빠르게 진행되는 중간에 나타나며 엘리어트 3번 파동에서 자주 보인다","보통갭은 강한 추세 도중에 나타나 목표 가격의 중간 지점을 알려 준다"],"a":2,"c":"갭은 나타나는 위치에 따라 보통갭(횡보 중), 돌파갭(추세 출발), 급진갭(추세 중간), 소멸갭(추세 막바지)으로 나눠요.","e":"급진갭은 이미 생긴 추세가 가속되는 중간에 나타나 목표 가격의 중간 지점을 가늠하게 해 줘서 측정갭이라고도 해요. 다우이론의 추세추종 국면, 엘리어트 3번 파동에서 자주 나타나요.","w":["그것은 보통갭의 특징이에요. 돌파갭은 많은 거래량과 함께 나타나고 잘 메워지지 않아 새 추세의 출발 신호로 봐요.","소멸갭은 추세의 막바지에 나타나 곧 메워지며 추세가 끝나 감을 알려 줘요.",null,"보통갭은 횡보 국면에서 생기며 별 의미 없이 금방 메워질 때가 많아요."],"k":"갭은 마라톤의 구간 표시예요. 출발(돌파), 반환점(급진), 결승 직전 마지막 스퍼트(소멸)예요.","m":"보통갭: 횡보 · 돌파갭: 출발·대량 거래 · 급진갭: 중간·측정갭·3번 파동 · 소멸갭: 막바지"},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"t":"다우이론 국면별 특징","q":"다우이론의 장기추세 국면에 관한 설명으로 가장 적절하지 않은 것은?","o":["매집 국면 – 경기 전망이 어두워 일반투자자는 실망해 팔지만, 전문투자자는 조금씩 사 모은다","과열 국면 – 경제 뉴스가 온통 낙관적이고, 확신을 가진 일반투자자가 몰려들어 거래가 크게 늘어난다","분산 국면 – 전문투자자가 보유 주식을 넘기며, 주가가 조금만 밀려도 거래량이 늘어난다","침체 국면 – 사려는 사람이 거의 없어 주가가 폭포처럼 급락하고 거래도 확 줄어드는, 하락 속도가 가장 빠른 단계이다"],"a":3,"c":"다우이론은 강세장을 매집 → 상승(마크업) → 과열, 약세장을 분산 → 공포 → 침체의 세 국면씩으로 나눠요.","e":"주가가 폭포처럼 급락하고 사려는 사람이 거의 없는 모습은 약세 두 번째 단계인 공포 국면이에요. 침체 국면(약세 3국면)은 투매가 이어지지만 시간이 갈수록 하락 폭과 거래량이 줄며 바닥을 다지는 단계예요. 참고로 기술적 분석가가 가장 큰 수익을 내는 구간은 강세 2국면인 상승(마크업) 국면이에요.","w":["매집 국면은 강세 1국면으로, 전문투자자가 싼값에 주식을 모아요.","과열 국면은 강세 3국면으로, 일반투자자가 확신을 갖고 몰려드는 때예요. 전문투자자가 보유 주식을 넘기며 빠져나가는 것은 다음 단계인 분산 국면이에요.","분산 국면은 약세 1국면으로, 전문투자자가 이익을 챙겨 빠져나가요.",null],"k":"강세장은 '몰래 사기 → 다 같이 오르기 → 들뜨기', 약세장은 '몰래 팔기 → 겁먹고 던지기 → 지쳐서 바닥 다지기'예요.","m":"강세: 매집→마크업→과열 · 약세: 분산→공포(급락)→침체(바닥 다지기)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"t":"엘리어트 하락 파동","q":"엘리어트 파동이론의 하락 a-b-c 파동에 관한 설명으로 가장 적절하지 않은 것은?","o":["a파는 상승 추세가 끝나고 하락이 시작되는 파동으로, 다섯 개의 작은 파동으로 이루어진다","b파는 하락 중 나타나는 반등이라 상승 전환으로 착각하기 쉬우며, 보유 주식을 정리할 마지막 기회로 본다","하락 국면에서 추세와 같은 쪽으로 가는 충격파동은 b파이고, a파와 c파는 조정파동이다","c파는 거래가 많고 갭이 생기는 등 하락 폭이 큰 경우가 많다"],"a":2,"c":"엘리어트 파동의 한 사이클은 상승 5파(1~5번)와 하락 3파(a·b·c), 모두 8개 파동이에요. 추세 방향으로 움직이면 충격파동, 반대로 움직이면 조정파동이에요.","e":"하락 국면에서 하락 쪽으로 움직이는 a파와 c파가 충격파동이고, 반대로 튀어 오르는 b파가 조정파동이에요. 상승 국면의 1·3·5번이 충격파동, 2·4번이 조정파동이라는 원리를 하락 국면에 그대로 적용한 거예요.","w":["a파는 추세가 꺾이는 곳에서 시작하며 작은 파동 5개로 구성돼요.","b파는 매수 함정이 되기 쉬워, 남은 주식을 팔 마지막 기회로 봐요.",null,"c파는 상승 국면의 3번 파동처럼 힘이 세서 하락 폭이 크고 거래도 활발해요."],"k":"내려가는 길에서 b파는 '잠깐 오르막'일 뿐이에요. 속지 말고 짐을 정리할 때예요.","m":"한 사이클 8파 = 상승 5 + 하락 3 · 하락 충격파 = a·c · 조정파 = b(매도 기회)"},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","t":"현금비율과 부채의존도 계산","q":"A사의 재무상태표 일부가 〈보기〉와 같을 때, 비율을 바르게 계산한 것은?\n• 현금및현금성자산 30억원, 단기매매증권 15억원, 매출채권 45억원, 재고자산 50억원, 선급금 10억원(유동자산은 이것뿐이다)\n• 유동부채 90억원\n• 총자산 400억원, 총부채 250억원\n(단, 당좌자산 = 유동자산 − 재고자산 − 선급금, 현금비율의 분자 = 현금및현금성자산 + 단기매매증권)","o":["부채의존도는 37.5%이다","부채비율은 62.5%이다","현금비율은 50%이다","당좌비율은 약 111.1%이다"],"a":2,"c":"유동성 비율은 분자에 무엇을 넣느냐로, 부채 비율은 분모가 자기자본이냐 총자산이냐로 갈려요.","e":"현금비율 = (30 + 15) ÷ 90 = 50%예요. 당좌비율 = (150 − 50 − 10) ÷ 90 = 100%, 부채비율 = 250 ÷ 150(자기자본) ≈ 166.7%, 부채의존도 = 250 ÷ 400 = 62.5%예요. 유동비율은 150 ÷ 90 ≈ 166.7%예요.","w":["37.5%는 자기자본 ÷ 총자산(자기자본비율)이에요. 부채의존도는 62.5%예요.","62.5%는 총부채를 총자산으로 나눈 부채의존도예요. 부채비율은 자기자본으로 나눠 약 166.7%예요.",null,"선급금 10억원을 빼지 않았어요(100 ÷ 90). 당좌비율은 100%예요."],"k":"부채비율은 \"내 돈 대비 빌린 돈\", 부채의존도는 \"전체 살림 중 빌린 돈의 몫\"이에요.","m":"당좌 = (유동 − 재고) ÷ 유동부채(문제가 선급금도 빼라고 하면 그대로) · 현금비율 = (현금 + 단기유가증권) ÷ 유동부채 · 부채비율 = 부채 ÷ 자기자본 · 부채의존도 = 부채 ÷ 총자산","f":"현금비율 = 45 ÷ 90 = 50%, 당좌비율 = 90 ÷ 90 = 100%, 부채비율 = 250 ÷ 150 ≈ 166.7%, 부채의존도 = 250 ÷ 400 = 62.5%","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","t":"산업연관표 총투입액 계산","q":"B국 산업연관표의 합계가 중간수요 340조원, 최종수요 260조원, 수입 90조원이다. 이 나라의 총투입액은?","o":["260조원","510조원","600조원","690조원"],"a":1,"c":"산업연관표에서는 \"총투입 = 총산출\"이 항상 성립하고, 총산출은 총수요에서 수입을 뺀 값이에요.","e":"총수요 = 340 + 260 = 600조원, 총산출 = 600 − 90 = 510조원이고 이것이 총투입액과 같아요. 참고로 투입계수는 중간투입과 부가가치를 총투입으로 나눈 값으로 생산기술 구조를 보여 주고, 최종수요가 1단위 늘 때 직·간접으로 늘어나는 수입은 수입유발계수로 읽어요.","w":["최종수요만 봤어요. 산업연관표는 국민소득통계와 달리 중간재 거래도 담아요.",null,"총수요에서 수입을 빼지 않았어요.","수입을 빼야 하는데 더했어요."],"k":"가게 매출(총수요) 중 다른 가게에서 떼어 온 물건(수입)을 빼야 우리 가게가 직접 만든 양(총산출)이 나와요.","m":"총투입 = 총산출 = 중간수요 + 최종수요 − 수입","f":"총투입 = 340 + 260 − 90 = 510조원","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","t":"추세선의 종류와 이동평균선 밀집","q":"추세선과 이동평균선에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 상승 중에 주가를 받쳐 주던 지지선이 한번 뚫리고 나면, 그 뒤에는 주가를 누르는 저항선 역할을 하는 경우가 많다.\nㄴ. 상승추세선은 상승 국면의 고점끼리 이어서 긋는다.\nㄷ. 부채꼴처럼 펼쳐지는 추세선이 차례로 몇 개 생기면서 점점 눕는다면 지금의 추세가 힘을 잃어 간다는 뜻이다.\nㄹ. 단기·중기·장기 이동평균선이 한데 뭉치는 모습은 변동성이 줄어들며 힘이 모이는 국면이다.\nㅁ. 이동평균 기간이 길수록 선이 가팔라지고 매매신호가 더 자주 나온다.","o":["2개","3개","4개","5개"],"a":1,"c":"추세선은 어디를 잇느냐, 몇 개가 어떻게 생기느냐로 추세의 힘을 읽어요. 지지선이 뚫리면 저항선으로, 저항선이 뚫리면 지지선으로 역할이 바뀌는 경우가 많아요. 이동평균선은 기간이 길수록 느리고 묵직해요.","e":"ㄱ, ㄷ, ㄹ이 옳아 3개예요. 오르는 추세선은 바닥들을, 내리는 추세선은 꼭대기들을 이어서 그어요. 이동평균선이 밀집하면 그 자체가 매도신호는 아니고, 이후 방향이 정해지며 변동성이 커질 때 그 추세를 따라가요. 이동평균 기간이 길수록 선은 완만해지고 신호는 늦게 나오지만 지지·저항선 역할이 커져요.","w":["옳은 것은 ㄱ, ㄷ, ㄹ 3개예요.",null,"ㄴ과 ㅁ은 틀렸어요.","ㄴ은 고점이 아니라 저점을 이어요. ㅁ은 방향이 반대예요."],"k":"용수철을 꾹 누르면(이평선 밀집) 조용해 보이지만, 손을 놓는 순간 한쪽으로 크게 튀어요.","m":"뚫린 지지선 → 저항선(역할 전환) · 상승추세선 = 저점 연결 · 부채형 여러 개 = 추세 둔화 · 이평 밀집 = 변동성 축소","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","t":"반전형·지속형 패턴 구분","q":"차트 패턴에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 꼭대기는 갈수록 올라가고 바닥은 갈수록 내려가 출렁임이 커지는 확대형은 반전형으로 본다.\nㄴ. 앞쪽은 확대형, 뒤쪽은 대칭삼각형 모양이 이어 붙은 것이 다이아몬드형이다.\nㄷ. 상승하던 주가가 둥근 지붕처럼 천천히 꺾여 내려오는 모양을 원형바닥형이라 한다.\nㄹ. W자 모양 이중바닥형은 뒤에 생기는 바닥이 앞 바닥보다 덜 뾰족하고 약간 높게 형성되는 경우가 많다.\nㅁ. 삼각형 패턴은 폭이 좁아질수록 거래량이 늘고, 돌파할 때는 거래량이 줄어야 신뢰도가 높다.","o":["2개","3개","4개","5개"],"a":1,"c":"패턴은 추세가 꺾이는 반전형과 잠시 쉬었다 이어지는 지속형으로 나뉘고, 거래량이 그 신뢰도를 확인해 줘요.","e":"ㄱ, ㄴ, ㄹ이 옳아 3개예요. 오르다가 둥글게 꺾여 내려오는 것은 원형천장형이고, 원형바닥형은 그 반대 모양이에요. 삼각형이 좁아지는 동안에는 관망세로 거래량이 줄고, 한쪽으로 돌파할 때 거래량이 늘어야 믿을 만해요. 교재 분류로 보면 지속형에는 삼각형, 깃발형, 페넌트형, 쐐기형, 직사각형, 다이아몬드형이 있고, 반전형에는 헤드앤숄더, 이중천장(바닥)형, 원형, 확대형이 있어요.","w":["옳은 것은 ㄱ, ㄴ, ㄹ 3개예요.",null,"ㄷ과 ㅁ은 틀렸어요.","ㄷ은 원형천장형의 설명이고, ㅁ은 거래량 방향이 반대예요."],"k":"삼각형 패턴은 \"숨을 고르며 조용해지다가(거래량↓) 문을 박차고 나갈 때 함성(거래량↑)\"이 나야 진짜예요.","m":"확대형 = 반전형 · 다이아몬드 = 확대형 + 대칭삼각형 · 오르다 둥글게 꺾임 = 원형천장 · 삼각형: 수렴 중 거래량↓, 돌파 때↑","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"상","t":"스토캐스틱 %D와 교차 신호","q":"최근 9일 동안 최고가 25,000원, 최저가 20,000원이고 오늘 종가는 24,400원이다. 전전일 %K는 95%, 전일 %K는 92%였고 전일에는 %K가 %D(90%)보다 위에 있었다. %D를 최근 3일 %K의 평균으로 구할 때, 오늘의 지표와 해석으로 가장 적절한 것은?","o":["%K 88%, %D 약 91.7%이며, 과열권에 들어섰으므로 매수 신호로 본다","%K 12%, 침체권이므로 매수 신호로 본다","%K 88%, %D 약 91.7%이며, 과열권에서 %K가 %D를 위에서 아래로 뚫어 매도 신호로 본다","%K 약 97.6%, 아직 %D보다 위에 있으므로 신호가 없다"],"a":2,"c":"스토캐스틱은 종가가 최근 가격 범위의 어디쯤 있는지(%K)와 그 평균(%D)의 교차로 과열·침체 속 전환을 잡아요.","e":"%K = (24,400 − 20,000) ÷ (25,000 − 20,000) × 100 = 88%, %D = (95 + 92 + 88) ÷ 3 ≈ 91.7%예요. 어제는 %K가 위였는데 오늘은 아래로 내려와, 과열권에서 하향 교차가 일어났으니 매도 신호예요. 침체권에서 %K가 %D를 위로 뚫으면 매수 신호예요. 참고로 RSI 같은 추세반전형 지표는 산출기간이 짧을수록 민감해져 신호가 잦아지고, 신호가 너무 자주 나온다는 점이 단점이에요.","w":["과열권에서의 하향 교차는 매도 신호예요.","(최고가 − 종가)로 계산했어요. 분자는 종가 − 최저가예요.",null,"종가 ÷ 최고가로 계산했어요."],"k":"%K는 빠른 토끼, %D는 뒤따라오는 거북이예요. 높은 언덕(과열권)에서 토끼가 거북이 아래로 내려가면 내리막이 시작된다는 뜻이에요.","m":"%K = (종가 − 최저) ÷ (최고 − 최저) · %D = %K의 이동평균 · 과열권 하향교차 = 매도, 침체권 상향교차 = 매수","f":"%K = 4,400 ÷ 5,000 = 88%, %D = (95 + 92 + 88) ÷ 3 ≈ 91.7%","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","t":"산업 분류와 생산요소","q":"산업분석에 관한 〈보기〉에서 옳은 것만 묶은 것은?\nㄱ. 자연자원이나 숙련되지 않은 노동력은 단순요소이고, 기술·인적자본·지식재산권은 고급요소이다.\nㄴ. 비영리 단체의 활동은 산업활동에서 빠지고, 가정 안의 가사활동은 산업활동에 들어간다.\nㄷ. 설비투자와 함께 움직이는 기계·건설 같은 산업은 전체 경기보다 먼저 방향을 바꾸는 경기선행산업인 경우가 많다.\nㄹ. 음식료·전력처럼 호황에도 매출과 이익이 크게 늘지 않는 산업은 경기민감산업이다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"산업은 경기에 얼마나, 언제 반응하는지로 나누고, 경쟁력의 바탕인 생산요소는 단순요소와 고급요소로 나눠요.","e":"ㄱ, ㄷ이 옳아요. 돈을 벌려는 활동이든 아니든 산업활동에 들어가고, 집안에서 하는 가사활동만 빠져요. 음식료·전력·의약품처럼 경기 영향이 작은 산업은 경기방어산업이고, 자동차·철강처럼 호황에 크게 느는 산업이 경기민감산업이에요. 발전 단계로 보면 성장기에는 단순요소와 고급요소 경쟁력이 함께 오르고, 구조조정기에는 임금이 빠르게 올라 단순요소 경쟁력이 빨리 떨어져요.","w":["ㄴ은 포함과 제외를 반대로 말했어요.",null,"ㄴ, ㄹ은 둘 다 틀렸어요.","ㄹ은 경기방어산업의 설명이에요."],"k":"경기선행산업은 \"날씨가 바뀌기 전에 먼저 우산을 파는 가게\"예요. 기업들이 설비를 늘릴 때 먼저 바빠져요.","m":"단순요소 = 자연자원·미숙련 노동 / 고급요소 = 기술·인적자본 · 산업활동: 비영리 포함, 가사 제외 · 설비투자 연관 = 경기선행","rev":0},{"s":2,"sec":"투자분석기법","star":2,"lv":"상","t":"주가로 역산한 요구수익률","q":"C사의 당기 주당순이익은 4,000원이고 배당성향 30%를 유지하며 당기 배당은 이미 지급했다. ROE는 15%로 일정하고 현재 주가는 26,520원이다. 항상성장모형이 성립할 때 판단으로 가장 적절한 것은?","o":["이미 지급한 당기 배당 1,200원을 그대로 분자에 넣어도 요구수익률은 정확히 같게 나온다","C사가 신규 투자를 줄여 잉여현금흐름이 커지면 그만큼 성장성도 높아졌다고 볼 수 있다","지속가능성장률은 4.5%이다","현재 주가에 담긴 투자자의 요구수익률은 약 15.5%이다"],"a":3,"c":"주가와 배당, 성장률을 알면 항상성장모형을 거꾸로 풀어 시장이 요구하는 수익률을 구할 수 있어요.","e":"g = 유보율 × ROE = 0.7 × 15% = 10.5%, D₁ = 1,200 × 1.105 = 1,326원이에요. k = D₁ ÷ P + g = 1,326 ÷ 26,520 + 10.5% = 5% + 10.5% = 15.5%예요.","w":["당기 배당 1,200원을 쓰면 약 15.0%가 나와요. 분자에는 다음 기 배당 D₁을 넣어야 해요.","잉여현금흐름은 투자를 줄이면 커지므로, 값이 크다고 성장성이 높다고 볼 수 없어요.","배당성향 30%를 곱했어요. 성장률은 유보율 70%를 곱해 10.5%예요.",null],"k":"가게 가격(주가)과 내년 용돈(배당), 용돈 오르는 속도(성장률)를 알면, 손님이 기대하는 수익률을 거꾸로 계산할 수 있어요.","m":"k = D₁ ÷ P₀ + g · g = 유보율 × ROE · 분자는 D₀ 아닌 D₁","f":"g = 0.7 × 15% = 10.5%, D₁ = 1,326원, k = 1,326 ÷ 26,520 + 0.105 = 15.5%","rev":0},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","t":"엘리어트 법칙과 해석의 한계","q":"엘리어트 파동이론에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 한 번의 큰 사이클은 상승 5개, 하락 3개를 합쳐 모두 8개의 파동으로 이루어진다.\nㄴ. 2번 파동이 1번 파동의 출발점보다 더 아래로 내려갔다면 파동을 잘못 센 것이다.\nㄷ. 4번 파동이 내려와 1번 파동 꼭대기보다 더 아래까지 떨어져도 규칙 위반이 아니다.\nㄹ. 1·3·5번 파동 가운데 3번 파동이 가장 짧은 경우가 많다.\nㅁ. 꼭 지켜야 할 규칙은 몇 개뿐이고 나머지 해석의 여지가 커서, 같은 차트라도 분석가마다 파동을 다르게 셀 수 있다.","o":["2개","3개","4개","5개"],"a":1,"c":"엘리어트 이론에는 절대 깨지면 안 되는 규칙 세 가지가 있고, 그 밖의 해석은 자유로운 편이라 사람마다 결론이 달라질 수 있어요.","e":"ㄱ, ㄴ, ㅁ이 옳아 3개예요. 절대 규칙은 ① 2번 파동은 1번 파동 출발점 아래로 가지 않는다, ② 3번 파동은 1·3·5번 중 가장 짧을 수 없다, ③ 4번 파동 저점은 1번 파동 고점과 겹치지 않는다는 세 가지예요. 3번 파동은 보통 가장 길고 강해요.","w":["옳은 것은 ㄱ, ㄴ, ㅁ 3개예요.",null,"ㄷ과 ㄹ은 틀렸어요.","ㄷ은 절대 규칙 위반이고, ㄹ은 3번 파동이 보통 가장 길어요."],"k":"규칙은 세 개뿐인 보드게임이라, 나머지는 사람마다 \"우리 집 규칙\"으로 다르게 놀 수 있어요.","m":"상승 5 + 하락 3 = 8파 · 절대 규칙 3개(2번 < 1번 시작점 X, 3번 최단 X, 4번–1번 겹침 X) · 해석 융통성 = 한계","rev":0},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"채권 포지션의 VaR","q":"〈보기〉의 채권 포지션에 대한 1일 VaR(95% 신뢰수준)에 가장 가까운 것은?\n• 채권 포지션: 1,000억원\n• 수정듀레이션: 4\n• 만기수익률 일일 변화의 표준편차: 0.5%p\n• 95% 신뢰수준 z값: 1.65","o":["20억원","33억원","8.25억원","330억원"],"a":1,"c":"채권 VaR는 \"금리가 얼마나 흔들리는지 × 금리 1%p당 가격이 얼마나 변하는지(수정듀레이션)\"로 구해요.","e":"VaR = 1,000억 × 4 × 0.005 × 1.65 = 33억원이에요.","w":["신뢰수준 z값(1.65)을 곱하지 않았어요.",null,"수정듀레이션을 곱하지 않았어요.","0.5%p(= 0.005)를 0.05로 잘못 넣어 10배 크게 계산했어요."],"k":"금리가 0.5%p 흔들리면 가격은 4배인 2% 흔들려요. 여기에 95% 기준 1.65를 곱하면 3.3%, 1,000억의 3.3%가 33억이에요.","m":"채권 VaR = 포지션 × 수정듀레이션 × σ(Δy) × z","f":"1,000 × 4 × 0.005 × 1.65 = 33억원"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"역사적 시뮬레이션 VaR","q":"역사적 시뮬레이션 방법으로 VaR를 측정할 때의 특징으로 가장 적절하지 않은 것은?","o":["수익률 분포에 대한 특정한 가정 없이 과거 자료를 그대로 쓴다","옵션처럼 가격이 비선형으로 움직이는 포지션도 반영할 수 있다","자산 수익률이 반드시 정규분포를 따른다고 가정해야 한다","과거 표본 기간에 없었던 위기 상황은 반영하기 어렵다"],"a":2,"c":"VaR 측정 방법은 델타-노말(분석적), 역사적 시뮬레이션, 몬테카를로 시뮬레이션으로 나뉘어요. 역사적 시뮬레이션은 과거에 실제로 일어난 변화를 그대로 다시 적용해요.","e":"역사적 시뮬레이션은 분포 가정이 필요 없는 것이 장점이에요. 정규분포 가정이 필요한 것은 델타-노말 방법이에요.","w":["분포 가정이 없는 것이 특징이에요.","실제 가격으로 재평가하므로 비선형 포지션도 반영돼요.",null,"과거에 없던 상황은 반영 못 하는 것이 한계예요."],"k":"\"지난 1년 동안 실제로 일어났던 일이 오늘 다시 일어나면?\"을 그대로 돌려 보는 방법이에요.","m":"역사적 시뮬 = 분포 가정 X · 과거 의존 / 델타-노말 = 정규분포 가정"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"몬테카를로 시뮬레이션 VaR","q":"몬테카를로 시뮬레이션으로 VaR를 측정하는 방법에 관한 설명으로 가장 적절한 것은?","o":["다양한 확률분포와 비선형 포지션을 반영할 수 있어 가장 정교한 방법으로 평가된다","계산이 매우 간단해 실무에서 가장 빠르게 구할 수 있다","과거 실제 가격 변화만 그대로 사용하므로 모형 설정이 필요 없다","정규분포를 가정한 델타로만 포지션 가치 변화를 근사한다"],"a":0,"c":"몬테카를로 시뮬레이션은 가격 변화를 확률 모형으로 수없이 만들어 내고, 포지션을 매번 다시 평가해 VaR를 구해요.","e":"분포와 비선형성을 자유롭게 반영할 수 있어 가장 정교하지만, 계산량이 많고 모형이 틀리면 결과도 틀리는(모형위험) 단점이 있어요.","w":[null,"계산량이 가장 많은 방법이에요.","과거 자료를 그대로 쓰는 것은 역사적 시뮬레이션이에요.","델타로 근사하는 것은 델타-노말 방법이에요."],"k":"주사위를 수만 번 굴려 미래 시나리오를 만들어 보는 방법이에요. 정확하지만 시간이 오래 걸려요.","m":"몬테카를로 = 가장 정교 · 계산 부담 · 모형위험"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"KMV 모형의 부도거리","q":"KMV 모형에 따를 때 부도확률이 가장 낮은 기업은? (기업가치는 정규분포를 따른다)\n• 갑: 1년 후 기업가치 기대값 120, 부채 80, 기업가치 표준편차 20\n• 을: 1년 후 기업가치 기대값 150, 부채 100, 기업가치 표준편차 25\n• 병: 1년 후 기업가치 기대값 200, 부채 150, 기업가치 표준편차 10\n• 정: 1년 후 기업가치 기대값 100, 부채 40, 기업가치 표준편차 40","o":["병","을","정","갑"],"a":0,"c":"KMV 모형은 기업가치가 부채보다 작아지면 부도로 봐요. 기업가치 기대값이 부채에서 표준편차 몇 개만큼 떨어져 있는지(부도거리)가 클수록 안전해요.","e":"부도거리 = (기업가치 기대값 − 부채) ÷ 표준편차. 갑 2, 을 2, 병 5, 정 1.5로 병의 부도거리가 가장 커서 부도확률이 가장 낮아요.","w":[null,"을의 부도거리는 2예요.","정은 여유분(60)이 크지만 변동성(40)도 커서 부도거리가 1.5예요.","갑의 부도거리는 2예요."],"k":"절벽(부채)에서 얼마나 떨어져 있는지를 \"걸음 수(표준편차)\"로 재는 거예요. 걸음 수가 많을수록 안전해요.","m":"부도거리(DD) = (E[V] − D) ÷ σV → 클수록 안전","f":"갑 40/20 = 2 · 을 50/25 = 2 · 병 50/10 = 5 · 정 60/40 = 1.5"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"VaR의 해석","q":"〈보기〉의 ( ) 안에 들어갈 말을 순서대로 바르게 나열한 것은?\n〈보기〉 어느 포트폴리오의 1일 VaR가 신뢰수준 99%에서 10억원이라는 것은, 하루 동안 ( ㄱ ) 이상 손실을 볼 확률이 ( ㄴ )라는 뜻이다.","o":["ㄱ 10억원 – ㄴ 1%","ㄱ 10억원 – ㄴ 99%","ㄱ 1억원 – ㄴ 1%","ㄱ 99억원 – ㄴ 10%"],"a":0,"c":"VaR는 정상적인 시장에서 주어진 기간과 신뢰수준 아래 발생할 수 있는 최대 손실이에요.","e":"99% 신뢰수준 1일 VaR 10억원은 하루 손실이 10억원을 넘을 확률이 1%라는 뜻이에요. 99%의 확률로 손실이 10억원 이하예요.","w":[null,"99%는 손실이 VaR 이하일 확률이에요.","금액이 맞지 않아요.","금액과 확률이 모두 맞지 않아요."],"k":"100일 중 99일은 손실이 10억원 이하, 나머지 1일 정도는 그보다 클 수 있다는 뜻이에요.","m":"VaR(99%) = 손실이 그 값을 넘을 확률 1%"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"한계 VaR와 자산 편입","q":"현재 포트폴리오 VaR가 100억원이다. 후보 자산을 각각 편입했을 때의 포트폴리오 VaR가 〈보기〉와 같다면, 위험 감소 효과가 가장 큰 자산은?\n• A 편입 시 108억원\n• B 편입 시 95억원\n• C 편입 시 112억원\n• D 편입 시 101억원","o":["A","B","C","D"],"a":1,"c":"한계 VaR는 새 자산을 넣었을 때 포트폴리오 VaR가 얼마나 변하는지를 보여 줘요.","e":"한계 VaR는 A +8, B −5, C +12, D +1억원이에요. B는 편입 후 VaR가 오히려 줄어 위험 감소 효과가 가장 커요(헤지 성격).","w":["VaR가 8억원 늘어요.",null,"VaR가 가장 많이 늘어요.","VaR가 1억원 늘어요."],"k":"넣었더니 전체 흔들림이 줄어드는 자산이 \"위험을 깎아 주는\" 자산이에요.","m":"한계 VaR = 편입 후 VaR − 기존 VaR (음수면 위험 감소)","f":"A +8 · B −5 · C +12 · D +1"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"옵션 포지션의 델타 VaR","q":"기초자산 가격 100원, 기초자산 일일 수익률 표준편차 2%, 델타 0.5인 콜옵션 100계약을 보유하고 있다(1계약 = 기초자산 1단위). 95% 신뢰수준(z = 1.65)의 델타-노말 1일 VaR는?","o":["165원","330원","100원","1,650원"],"a":0,"c":"델타-노말 방법은 옵션 VaR를 \"델타 × 기초자산 VaR\"로 선형 근사해요.","e":"기초자산 포지션 = 100원 × 100 = 10,000원, VaR = 0.5 × 10,000 × 0.02 × 1.65 = 165원이에요.","w":[null,"델타를 반영하지 않았어요.","z값을 반영하지 않았어요.","자릿수를 잘못 계산했어요."],"k":"옵션은 기초자산의 절반(델타 0.5)만큼 움직이니 VaR도 절반이에요.","m":"옵션 VaR ≈ Δ × 기초자산 포지션 × σ × z","f":"0.5 × 10,000 × 0.02 × 1.65 = 165원"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"델타-노말 방법의 특징","q":"델타-노말(분석적) VaR 측정 방법에 관한 설명으로 가장 적절하지 않은 것은?","o":["수익률이 정규분포를 따른다고 가정한다","포지션 가치 변화를 선형으로 근사해 계산이 빠르다","옵션처럼 비선형 포지션의 위험은 정확히 측정하기 어렵다","분포 가정이 필요 없어 두꺼운 꼬리를 정확히 반영한다"],"a":3,"c":"델타-노말 방법은 분산·공분산과 델타를 이용해 VaR를 빠르게 계산하는 방법이에요.","e":"델타-노말은 정규분포를 가정하므로 실제 수익률의 두꺼운 꼬리(fat tail)를 반영하지 못해 VaR를 과소평가할 수 있어요.","w":["정규분포 가정이 핵심이에요.","선형 근사라 계산이 빨라요.","비선형 위험 측정이 한계예요.",null],"k":"\"모든 흔들림은 종 모양\"이라고 가정해서 빠르지만, 극단적인 날을 놓칠 수 있어요.","m":"델타-노말: 정규분포 · 선형 · 빠름 · 비선형·두꺼운 꼬리 한계"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"스트레스 테스트","q":"스트레스 테스트에 관한 설명으로 가장 적절하지 않은 것은?","o":["금융위기 같은 극단적인 시나리오에서 손실을 추정한다","VaR가 잡지 못하는 꼬리 위험을 보완한다","과거 위기 사례나 가상 시나리오를 이용한다","정상적인 시장 상황에서 평균적으로 예상되는 손실을 측정한다"],"a":3,"c":"VaR는 정상 시장에서의 최대 손실을 보여 주지만, 위기 때의 큰 손실은 잘 보여 주지 못해요.","e":"스트레스 테스트는 정상 상황이 아니라 극단적인 위기 상황에서의 손실을 측정해 VaR를 보완해요.","w":["극단적 시나리오가 핵심이에요.","꼬리 위험을 보완해요.","과거 위기·가상 시나리오를 써요.",null],"k":"\"최악의 폭풍이 오면 우리 배가 버틸까?\"를 시험해 보는 거예요.","m":"스트레스 테스트 = 극단 시나리오 · VaR 보완"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"백테스팅","q":"VaR 모형의 정확성을 검증하기 위해 실제 손실이 VaR를 넘은 횟수를 예상 횟수와 비교하는 방법은?","o":["백테스팅","스트레스 테스트","몬테카를로 시뮬레이션","듀레이션 분석"],"a":0,"c":"VaR 모형이 맞다면 99% VaR를 넘는 손실은 100일 중 1일 정도만 나와야 해요.","e":"실제 손실이 VaR를 초과한 횟수를 이론상 기대 횟수와 비교해 모형을 검증하는 것이 백테스팅이에요.","w":[null,"극단 시나리오 분석이에요.","VaR 계산 방법이에요.","채권 금리 위험 분석이에요."],"k":"일기예보가 \"비 올 확률 10%\"였던 날 실제로 비가 얼마나 왔는지 맞춰 보는 거예요.","m":"백테스팅 = VaR 초과 횟수로 모형 검증"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"VaR의 한계와 기대손실(ES)","q":"VaR의 한계를 보완하기 위해 VaR를 넘는 손실이 발생했을 때의 평균 손실을 측정하는 지표는?","o":["기대손실(Expected Shortfall, CVaR)","베타","샤프비율","듀레이션"],"a":0,"c":"VaR는 \"손실이 이 값을 넘을 확률\"만 알려 줄 뿐, 넘었을 때 얼마나 크게 잃을지는 알려 주지 않아요.","e":"VaR를 넘는 꼬리 구간 손실의 평균을 보는 지표가 기대손실(ES, CVaR)이에요.","w":[null,"시장 민감도예요.","위험조정 성과 지표예요.","채권 금리 민감도예요."],"k":"VaR가 \"문턱\"이라면 ES는 \"문턱을 넘었을 때 평균 피해\"예요.","m":"ES(CVaR) = VaR 초과 손실의 평균 · 꼬리위험 보완"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"신용 기대손실 계산","q":"익스포저(EAD) 100억원, 부도율(PD) 2%, 부도 시 손실률(LGD) 45%인 대출의 기대손실(EL)은?","o":["0.9억원","2.0억원","45억원","55억원"],"a":0,"c":"신용 기대손실은 부도 시 노출금액에 부도 확률과 손실률을 곱해 구해요.","e":"EL = 100억 × 2% × 45% = 0.9억원이에요.","w":[null,"손실률을 반영하지 않았어요.","부도율을 반영하지 않았어요.","부도율을 빼고, 회수율(55%)을 손실률로 착각했어요."],"k":"100억 빌려줬는데 2% 확률로 망하고, 망하면 45%를 잃으니 평균 0.9억 손실이에요.","m":"EL = EAD × PD × LGD","f":"100 × 0.02 × 0.45 = 0.9억원"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"비기대손실과 자본","q":"신용위험 관리에서 비기대손실(UL)에 관한 설명으로 가장 적절한 것은?","o":["평균적으로 예상되는 손실이라 대손충당금으로 대비한다","예상보다 크게 생길 수 있는 손실의 변동성으로, 자기자본으로 대비한다","항상 0이다","기대손실과 같은 개념이다"],"a":1,"c":"신용손실은 평균적으로 예상되는 기대손실(EL)과 그보다 크게 벗어날 수 있는 비기대손실(UL)로 나눠요.","e":"UL은 기대손실을 넘어 생길 수 있는 손실의 변동성으로, 자기자본(경제적 자본)으로 대비해요. 기대손실은 충당금으로 대비해요.","w":["기대손실(EL)의 설명이에요.",null,"변동성이 있으면 0이 아니에요.","다른 개념이에요."],"k":"평균 손실은 미리 떼어 두고(충당금), 예상 밖의 큰 손실은 자본으로 버텨요.","m":"EL → 충당금 · UL → 자기자본"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"신용위험 경감 수단","q":"신용위험을 줄이는 수단으로 가장 거리가 먼 것은?","o":["담보 확보","보증 확보","거래상대방과의 네팅(상계) 계약","특정 기업에 대한 익스포저 집중 확대"],"a":3,"c":"신용위험은 담보·보증·네팅·신용파생상품 등으로 줄일 수 있어요.","e":"특정 기업에 익스포저를 몰아주면 그 기업이 부도날 때 손실이 커져 오히려 신용위험이 커져요.","w":["담보는 대표적인 경감 수단이에요.","보증도 경감 수단이에요.","네팅은 순노출을 줄여요.",null],"k":"한 사람에게 몰아서 빌려주면 그 사람이 넘어질 때 같이 넘어져요.","m":"신용위험 경감: 담보 · 보증 · 네팅 · 신용파생 · 분산"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"CreditMetrics","q":"신용등급이 오르내리는 확률(등급 전이행렬)을 이용해 부도뿐 아니라 등급 변화에 따른 가치 변동까지 반영하는 신용위험 모형은?","o":["CreditMetrics","KMV","델타-노말 모형","CAPM"],"a":0,"c":"신용위험 모형은 부도 여부만 보는 모형과 신용등급 변화까지 보는 모형으로 나뉘어요.","e":"CreditMetrics는 등급 전이행렬로 신용등급 하락·상승에 따른 채권 가치 변화까지 반영해 신용 VaR를 구해요.","w":[null,"주가로 부도확률을 추정하는 모형이에요.","시장위험 VaR 계산 방법이에요.","기대수익률 모형이에요."],"k":"\"부도 났나 안 났나\"뿐 아니라 \"등급이 떨어졌나\"까지 따지는 모형이에요.","m":"CreditMetrics = 등급 전이행렬 · 등급 변화 반영"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"RAROC 계산","q":"어느 사업부의 수익이 20억원, 영업비용이 8억원, 기대손실이 2억원이고 배분된 경제적 자본이 50억원이다. RAROC는?","o":["10%","20%","24%","40%"],"a":1,"c":"RAROC는 위험을 반영한 이익을 그 위험에 필요한 자본으로 나눠 사업 성과를 비교하는 지표예요.","e":"위험조정이익 = 20 − 8 − 2 = 10억원, RAROC = 10 ÷ 50 = 20%예요.","w":["계산이 맞지 않아요.",null,"기대손실을 빼지 않았어요.","비용과 기대손실을 모두 빼지 않았어요(20 ÷ 50)."],"k":"위험까지 빼고 남은 10억을 위험 대비 자본 50억으로 나누면 20%예요.","m":"RAROC = (수익 − 비용 − 기대손실) ÷ 경제적 자본","f":"(20 − 8 − 2) ÷ 50 = 20%"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"레버리지와 위험","q":"레버리지(차입)에 관한 설명으로 가장 적절하지 않은 것은?","o":["차입을 늘리면 자기자본수익률의 변동성이 커진다","투자수익률이 차입이자율보다 높으면 자기자본수익률이 올라간다","레버리지가 커지면 손실이 날 때 자기자본 손실 폭도 커진다","레버리지를 늘리면 위험은 줄고 수익만 늘어난다"],"a":3,"c":"레버리지는 빌린 돈으로 투자 규모를 키우는 거예요. 이익도 손실도 함께 커져요.","e":"레버리지는 수익과 위험을 모두 키워요. 위험이 줄어드는 것은 아니에요.","w":["변동성이 커져요.","정(+)의 레버리지 효과예요.","손실도 커져요.",null],"k":"지렛대는 들어 올릴 때도, 넘어질 때도 힘을 키워요.","m":"레버리지 = 수익·위험 모두 확대"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"두꺼운 꼬리와 VaR","q":"수익률 분포의 첨도가 정규분포(첨도 3)보다 큰 두꺼운 꼬리(fat tail)를 가질 때, 정규분포를 가정한 VaR에 관한 설명으로 가장 적절한 것은?","o":["실제 위험을 과대평가한다","실제 위험을 과소평가할 수 있다","첨도와 VaR는 관계가 없다","정확히 측정한다"],"a":1,"c":"두꺼운 꼬리는 극단적인 손실이 정규분포 예상보다 더 자주 일어난다는 뜻이에요.","e":"정규분포를 가정하면 극단적 손실이 일어날 확률을 실제보다 낮게 보므로 VaR가 실제 위험을 과소평가할 수 있어요.","w":["극단적 손실을 덜 반영해 과소평가해요.",null,"첨도는 꼬리 위험과 직결돼요.","정규 가정과 실제 분포가 달라요."],"k":"\"이런 폭락은 100년에 한 번\"이라고 했는데 실제로는 10년에 한 번 오는 상황이에요.","m":"첨도 > 3(두꺼운 꼬리) → 정규 VaR 과소평가"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"기간·신뢰수준 동시 변환","q":"1일 95% VaR(z = 1.65)가 10억원인 포트폴리오의 10일 99% VaR(z = 2.33)에 가장 가까운 것은?","o":["14.1억원","31.6억원","44.7억원","141.2억원"],"a":2,"c":"VaR는 √T 법칙으로 기간을, z값 비율로 신뢰수준을 바꿀 수 있어요.","e":"10억 × √10 × (2.33 ÷ 1.65) ≈ 10 × 3.162 × 1.412 ≈ 44.7억원이에요.","w":["신뢰수준만 바꿨어요.","기간만 바꿨어요.",null,"√10 대신 10을 곱했어요."],"k":"기간이 10배면 √10(약 3.16배), 신뢰수준 95→99%면 약 1.41배, 둘을 곱해요.","m":"VaR₂ = VaR₁ × √(T₂/T₁) × z₂ ÷ z₁","f":"10 × 3.162 × 1.412 ≈ 44.7억원"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"신용손실 분포의 특징","q":"신용손실 분포에 관한 설명으로 가장 적절한 것은?","o":["좌우 대칭인 정규분포를 따른다","대부분 작은 손실이 나다가 드물게 큰 손실이 나는, 꼬리가 긴 비대칭 분포이다","항상 손실이 0이다","시장위험 분포와 모양이 같다"],"a":1,"c":"대출은 대부분 정상적으로 상환되지만, 부도가 나면 손실이 크게 생겨요.","e":"신용손실은 작은 손실이 대부분이고 드물게 큰 손실이 생기는 오른쪽 꼬리가 긴 비대칭 분포예요. 그래서 정규분포 가정이 잘 맞지 않아요.","w":["비대칭 분포예요.",null,"부도가 나면 손실이 생겨요.","시장위험 분포보다 더 비대칭이에요."],"k":"평소에는 조용하다가 가끔 \"큰 사고\"가 나는 모양이에요.","m":"신용손실 분포 = 비대칭 · 긴 꼬리"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"거래상대방 신용위험 노출","q":"장외파생상품의 거래상대방 신용위험 노출(익스포저)에 관한 설명으로 가장 적절한 것은?","o":["현재 계약 가치가 마이너스여도 현재 노출은 그 금액만큼 크다","현재 노출(대체비용)과 앞으로 생길 수 있는 잠재적 노출을 함께 고려한다","장외파생상품에는 거래상대방 위험이 없다","명목원금 전체가 항상 손실 노출이다"],"a":1,"c":"장외파생은 상대방이 부도나면 계약 가치를 잃을 수 있어요. 지금 가치와 앞으로 변할 가치를 함께 봐야 해요.","e":"거래상대방 노출은 현재 노출(계약 가치가 양수일 때의 대체비용)과 잠재적 미래 노출을 더해 측정해요.","w":["가치가 마이너스면 현재 노출은 0이에요.",null,"장외파생은 상대방 위험이 커요.","명목원금이 전부 노출되는 것은 아니에요."],"k":"지금 받을 돈(현재 노출)뿐 아니라 앞으로 받을 수도 있는 돈(잠재 노출)까지 생각해요.","m":"상대방 노출 = 현재노출(대체비용) + 잠재노출"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"상관계수 0.5인 포트폴리오 VaR","q":"주식 부문 VaR가 50억원, 채권 부문 VaR가 120억원이고 두 부문 손익의 상관계수가 0.5이다. 회사 전체 VaR에 가장 가까운 것은?","o":["130.0억원","151.3억원","170.0억원","85.0억원"],"a":1,"c":"포트폴리오 VaR는 개별 VaR와 상관계수로 구해요. 상관계수가 클수록 분산효과가 줄어 VaR가 커져요.","e":"VaRp = √(50² + 120² + 2 × 0.5 × 50 × 120) = √(2,500 + 14,400 + 6,000) = √22,900 ≈ 151.3억원이에요.","w":["상관계수 0일 때의 값이에요.",null,"상관계수 1일 때의 값이에요.","단순 평균이에요."],"k":"두 위험이 절반쯤 같이 움직여서, 0일 때(130)와 1일 때(170) 사이인 약 151이 나와요.","m":"VaRp = √(A² + B² + 2ρAB)","f":"√22,900 ≈ 151.3억원"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"상관계수와 포트폴리오 VaR","q":"두 자산 포트폴리오에서 다른 조건이 같을 때 두 자산 수익률의 상관계수가 커지면 포트폴리오 VaR는?","o":["작아진다","커진다","변하지 않는다","항상 0이 된다"],"a":1,"c":"상관계수가 클수록 두 자산이 함께 움직여 서로 위험을 상쇄하는 효과가 줄어요.","e":"상관계수가 커지면 분산효과가 줄어 포트폴리오 VaR가 커져요. 상관계수 1이면 개별 VaR의 합과 같아요.","w":["반대 방향이에요.",null,"상관계수가 VaR에 영향을 줘요.","상관계수가 −1이고 비중이 맞을 때만 0이 될 수 있어요."],"k":"같이 움직이는 친구끼리 묶으면 같이 넘어져요.","m":"상관계수↑ → 분산효과↓ → 포트 VaR↑"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"EWMA 변동성 추정","q":"VaR 계산에 쓰는 변동성을 지수가중이동평균(EWMA) 방식으로 추정할 때의 특징으로 가장 적절한 것은?","o":["최근 관측치에 더 큰 가중치를 주어 변동성 변화에 빠르게 반응한다","모든 과거 관측치에 같은 가중치를 준다","감쇠계수(λ)가 클수록 최근 정보에 더 민감하게 반응한다","과거 자료가 전혀 필요 없다"],"a":0,"c":"EWMA는 오래된 자료일수록 가중치를 지수적으로 줄여 가며 변동성을 구해요.","e":"EWMA는 최근 수익률에 더 큰 가중치를 주어 변동성 변화를 빨리 반영해요. 감쇠계수 λ가 클수록 과거 정보의 영향이 오래 남아 변화에 덜 민감해요.","w":[null,"단순 이동평균 방식의 설명이에요.","λ가 클수록 과거 영향이 오래 남아 반응이 느려요.","과거 자료로 계산해요."],"k":"어제 일이 지난달 일보다 더 중요하게 반영돼요.","m":"EWMA: σ²ₜ = λσ²ₜ₋₁ + (1 − λ)r²ₜ₋₁ · 최근 가중↑ · λ↑ → 반응 느림"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"외환 포지션 VaR","q":"1,000만달러 외화자산을 보유하고 있다. 원/달러 환율이 1,300원, 환율 일일 변동성이 0.8%일 때 95% 신뢰수준(z = 1.65)의 1일 VaR에 가장 가까운 것은?","o":["1.04억원","1.72억원","2.42억원","13.0억원"],"a":1,"c":"외환 포지션 VaR는 원화로 환산한 포지션에 환율 변동성과 z값을 곱해 구해요.","e":"원화 포지션 = 1,000만 × 1,300 = 130억원, VaR = 130억 × 0.008 × 1.65 ≈ 1.72억원이에요.","w":["z값을 곱하지 않았어요.",null,"99% z값을 썼어요.","계산이 맞지 않아요. 130억 × 0.008 × 1.65로 구해야 해요."],"k":"130억원어치 달러가 하루에 0.8%씩 흔들리니, 95% 기준 최대 손실은 약 1.7억원이에요.","m":"VaR = 원화 포지션 × σ × z","f":"130억 × 0.008 × 1.65 ≈ 1.72억원"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"VaR의 유용성과 한계","q":"VaR에 관한 설명으로 가장 적절하지 않은 것은?","o":["서로 다른 자산의 위험을 하나의 금액으로 비교할 수 있다","위험 한도 설정과 자본 배분에 쓰인다","위험조정 성과 평가(RAROC 등)에 쓰인다","발생할 수 있는 최악의 손실 금액을 정확히 알려 준다"],"a":3,"c":"VaR는 위험을 금액 하나로 보여 줘서 관리에 편리하지만, 한계도 분명해요.","e":"VaR는 주어진 신뢰수준에서의 최대 손실일 뿐 최악의 손실이 아니에요. VaR를 넘는 손실이 얼마나 클지는 알려 주지 않아요.","w":["위험을 금액으로 통일해 비교해요.","한도·자본 배분에 써요.","성과평가에 써요.",null],"k":"VaR는 \"99일은 이 정도까지\"이지, \"최악의 하루\"가 아니에요.","m":"VaR 유용성: 비교·한도·자본배분·성과평가 / 한계: 꼬리 손실 크기 X"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"규제 목적 VaR 기준","q":"바젤Ⅱ(바젤 2.5) 기준에 따라 은행이 내부모형으로 시장위험 자본을 산출할 때 쓰는 VaR의 보유기간과 신뢰수준으로 가장 적절한 것은?","o":["1일, 95%","10일, 99%","1년, 90%","30일, 95%"],"a":1,"c":"감독당국은 금융회사 내부모형의 VaR를 자본 산출에 쓰도록 하면서 기준을 정해 두었어요.","e":"바젤Ⅱ 내부모형 방식에서는 보유기간 10일, 신뢰수준 99%의 VaR를 기준으로 써요. 참고로 바젤Ⅲ 최종안(FRTB)에서는 VaR 대신 97.5% 기대손실(ES)을 써요.","w":["내부 관리용으로 흔히 쓰는 기준이에요.",null,"규제 기준이 아니에요.","규제 기준이 아니에요."],"k":"규제는 \"열흘 동안, 99% 확실하게\" 버틸 자본을 요구해요.","m":"규제 VaR = 10일 · 99%","f":null},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"환노출의 종류","q":"해외 자회사의 외화 재무제표를 원화로 바꿔 연결재무제표를 작성할 때 환율 변동으로 장부상 가치가 변하는 노출은?","o":["거래적 노출","환산 노출(회계적 노출)","경제적 노출","신용 노출"],"a":1,"c":"환노출은 거래적, 환산(회계적), 경제적 노출로 나눠요.","e":"외화 재무제표를 원화로 환산하면서 장부상 가치가 변하는 것은 환산 노출이에요.","w":["이미 맺은 외화 거래의 결제 금액이 변하는 노출이에요.",null,"장기적인 경쟁력·현금흐름이 변하는 노출이에요.","환노출 종류가 아니에요."],"k":"실제 돈이 오가지 않아도 \"장부상 숫자\"가 바뀌는 게 환산 노출이에요.","m":"거래적 = 결제 금액 · 환산 = 장부 · 경제적 = 미래 현금흐름"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"스프레드로 추정한 부도율","q":"위험채권 수익률이 연 6%, 같은 만기 무위험채권 수익률이 연 4%, 부도 시 회수율이 50%이다. 신용스프레드로 추정한 연간 부도율에 가장 가까운 것은?","o":["1%","2%","4%","6%"],"a":2,"c":"신용스프레드는 기대손실(부도율 × 손실률)에 대한 보상으로 볼 수 있어요.","e":"스프레드 2% ≈ 부도율 × (1 − 회수율) → 부도율 ≈ 2% ÷ 0.5 = 4%예요.","w":["계산이 맞지 않아요.","회수율을 반영하지 않았어요.",null,"위험채권 수익률을 그대로 썼어요."],"k":"스프레드 2%는 \"부도율 × 잃는 비율 50%\"라서 부도율은 4%예요.","m":"스프레드 ≈ PD × LGD → PD ≈ 스프레드 ÷ (1 − 회수율)","f":"2% ÷ 0.5 = 4%"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"부도 상관관계","q":"대출 포트폴리오에서 차주들 사이의 부도 상관관계가 높아질 때 나타나는 현상으로 가장 적절한 것은?","o":["기대손실이 크게 줄어든다","여러 차주가 동시에 부도날 가능성이 커져 꼬리 손실(비기대손실)이 커진다","신용위험이 완전히 분산된다","부도 상관관계는 포트폴리오 위험과 관계없다"],"a":1,"c":"경기가 나빠지면 여러 기업이 함께 어려워져요. 부도가 함께 일어나는 정도가 부도 상관관계예요.","e":"부도 상관관계가 높으면 동시 부도 가능성이 커져 큰 손실이 날 확률(꼬리 위험)이 커져요. 기대손실 자체는 크게 변하지 않아요.","w":["기대손실은 개별 기대손실의 합이라 크게 변하지 않아요.",null,"분산효과가 줄어요.","포트폴리오 위험에 큰 영향을 줘요."],"k":"도미노처럼 한 회사가 넘어질 때 다른 회사도 같이 넘어지면 큰 사고가 나요.","m":"부도 상관↑ → 동시부도↑ → 비기대손실↑"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"신용손실 표준편차 계산","q":"익스포저 200억원, 부도율 1%, 부도 시 손실률 50%인 대출의 신용손실 표준편차에 가장 가까운 것은? (부도는 베르누이 분포)","o":["1.0억원","9.95억원","19.9억원","100억원"],"a":1,"c":"신용손실 표준편차는 노출금액 × 손실률 × √(부도율 × (1 − 부도율))로 구해요.","e":"σ = 200억 × 0.5 × √(0.01 × 0.99) ≈ 100억 × 0.0995 ≈ 9.95억원이에요.","w":["기대손실(200 × 1% × 50%)이에요.",null,"손실률을 반영하지 않았어요.","부도 시 손실 금액이에요."],"k":"평균 손실은 1억이지만, 실제로는 0 아니면 100억이라 흔들림이 약 10억이에요.","m":"σ = EAD × LGD × √(PD(1 − PD))","f":"100 × √0.0099 ≈ 9.95억원"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"기대손실의 가법성","q":"여러 대출로 이루어진 포트폴리오의 신용위험에 관한 설명으로 가장 적절한 것은?","o":["포트폴리오 기대손실은 개별 대출 기대손실의 합과 같다","포트폴리오 비기대손실은 항상 개별 비기대손실의 합과 같다","대출 수가 늘면 기대손실이 반드시 줄어든다","기대손실은 상관관계에 따라 크게 달라진다"],"a":0,"c":"기대값은 더할 수 있지만, 변동성(표준편차)은 상관관계 때문에 단순히 더할 수 없어요.","e":"기대손실은 상관관계와 관계없이 개별 기대손실의 합이에요. 비기대손실은 상관관계에 따라 합보다 작아질 수 있어요.","w":[null,"상관관계 때문에 합보다 작을 수 있어요.","기대손실은 대출 규모에 따라 늘어요.","기대손실은 상관관계와 무관해요."],"k":"평균은 그냥 더하면 되지만, 흔들림은 서로 상쇄되기도 해요.","m":"EL = 개별 EL의 합 · UL ≤ 개별 UL의 합"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"RAROC와 자본비용","q":"어느 사업의 RAROC가 15%이고 회사의 자기자본비용이 10%일 때의 판단으로 가장 적절한 것은?","o":["위험 대비 자본비용보다 높은 수익을 내므로 주주가치를 늘린다","자본비용보다 낮아 사업을 줄여야 한다","RAROC와 자본비용은 비교할 수 없다","RAROC는 높을수록 위험이 크다는 뜻이다"],"a":0,"c":"RAROC가 자본비용(허들레이트)보다 높으면 그 사업은 위험을 감안해도 가치를 만들어 내요.","e":"RAROC 15%가 자본비용 10%보다 높으므로 위험 대비 충분한 수익을 내 주주가치를 늘리는 사업이에요.","w":[null,"RAROC가 더 높아요.","자본비용과 비교해 판단해요.","RAROC는 위험 대비 수익성이에요."],"k":"주주가 기대하는 수익률(10%)보다 더 버는(15%) 사업은 남는 장사예요.","m":"RAROC > 자본비용 → 가치 창출","f":null},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"경제적 자본","q":"경제적 자본에 관한 설명으로 가장 적절한 것은?","o":["감독당국이 정한 최소 규제자본과 항상 같다","회사가 자체 위험 측정으로 산출한, 비기대손실에 대비하는 데 필요한 자본이다","기대손실에 대비하는 충당금이다","회계상 자본총계와 같다"],"a":1,"c":"경제적 자본은 회사가 스스로 측정한 위험에 맞춰 필요한 자본이에요. 규제자본과는 기준이 달라요.","e":"경제적 자본은 비기대손실(예상 밖 손실)을 견디기 위해 필요한 자본으로, 회사 내부 위험 측정으로 산출해요.","w":["규제자본과 다를 수 있어요.",null,"기대손실은 충당금으로 대비해요.","회계상 자본과 다른 개념이에요."],"k":"\"우리 회사 위험을 버티려면 진짜로 얼마가 필요할까?\"를 계산한 자본이에요.","m":"경제적 자본 = 내부 측정 · 비기대손실 대비"},{"s":2,"sec":"리스크관리","star":2,"lv":"하","rev":0,"t":"위험관리 조직의 독립성","q":"금융회사 위험관리 조직에 관한 설명으로 가장 적절한 것은?","o":["위험관리 부서는 영업 부서 아래에 두어 실적 목표를 함께 진다","위험관리 부서는 영업(프런트) 부서로부터 독립되어야 한다","위험 측정은 거래를 담당한 트레이더가 직접 한다","위험 한도는 영업 부서가 스스로 정한다"],"a":1,"c":"위험을 지는 부서(프런트)와 위험을 측정·감시하는 부서(미들)가 분리되어야 견제가 가능해요.","e":"위험관리 부서는 영업 부서로부터 독립되어 객관적으로 위험을 측정하고 한도를 관리해야 해요.","w":["독립성이 훼손돼요.",null,"스스로 측정하면 견제가 안 돼요.","한도는 이사회 등이 정해요."],"k":"선수가 스스로 심판을 보면 안 되는 것처럼, 위험을 지는 사람과 재는 사람은 달라야 해요.","m":"프런트(거래) · 미들(위험관리) · 백(결제) 분리"},{"s":2,"sec":"리스크관리","star":2,"lv":"하","rev":0,"t":"위험관리 절차","q":"위험관리 절차를 순서대로 바르게 나열한 것은?","o":["위험 인식 → 위험 측정 → 위험 통제 → 모니터링","위험 측정 → 위험 인식 → 모니터링 → 위험 통제","위험 통제 → 위험 인식 → 위험 측정 → 모니터링","모니터링 → 위험 통제 → 위험 측정 → 위험 인식"],"a":0,"c":"위험을 관리하려면 먼저 어떤 위험이 있는지 알아야 하고, 크기를 재야 줄이거나 막을 수 있어요.","e":"위험 인식 → 측정 → 통제 → 모니터링(사후 점검) 순서로 이루어져요.","w":[null,"인식이 먼저예요.","통제 전에 인식·측정이 필요해요.","순서가 거꾸로예요."],"k":"\"뭐가 위험하지? → 얼마나? → 어떻게 막지? → 잘 막고 있나?\" 순서예요.","m":"인식 → 측정 → 통제 → 모니터링"},{"s":2,"sec":"리스크관리","star":2,"lv":"하","rev":0,"t":"위험 대응 방법","q":"보험에 가입해 화재 손실을 보험회사에 넘기는 것은 어떤 위험 대응 방법인가?","o":["위험 회피","위험 전가","위험 보유","위험 감소"],"a":1,"c":"위험 대응 방법은 회피(아예 하지 않기), 전가(남에게 넘기기), 보유(스스로 감당), 감소(줄이기)로 나눠요.","e":"보험이나 헤지처럼 손실 위험을 다른 사람에게 넘기는 것은 위험 전가예요.","w":["위험한 활동을 아예 하지 않는 거예요.",null,"스스로 손실을 감당하는 거예요.","발생 가능성이나 크기를 줄이는 거예요."],"k":"내 위험을 보험회사에 \"넘겨주는\" 거예요.","m":"회피 · 전가(보험·헤지) · 보유 · 감소"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"√T 법칙의 가정","q":"VaR를 1일에서 여러 날로 늘릴 때 √T를 곱하는 방법이 정확하려면 필요한 가정은?","o":["일별 수익률이 서로 독립적이다(자기상관이 없다)","일별 수익률이 서로 강하게 양의 상관을 가진다","수익률이 항상 양수이다","포지션 규모가 매일 두 배로 늘어난다"],"a":0,"c":"분산은 독립인 기간끼리 더할 수 있어서, 기간이 T배면 분산도 T배, 표준편차는 √T배가 돼요.","e":"√T 법칙은 일별 수익률이 서로 독립적이고(자기상관 0) 분포가 같다는 가정 아래 성립해요.","w":[null,"양의 자기상관이 있으면 √T보다 더 커져요.","수익률 부호와 관계없어요.","포지션은 일정하다고 가정해요."],"k":"날마다 흔들림이 \"서로 상관없이\" 일어나야 √T로 늘릴 수 있어요.","m":"√T 법칙 = 일별 수익률 독립·동일분포 가정"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"구성요소 VaR","q":"포트폴리오 VaR를 각 자산이 기여한 몫으로 나눈 구성요소 VaR(component VaR)에 관한 설명으로 가장 적절한 것은?","o":["구성요소 VaR를 모두 더하면 포트폴리오 VaR와 같다","구성요소 VaR의 합은 항상 개별 VaR의 합과 같다","구성요소 VaR는 음수가 될 수 없다","구성요소 VaR는 자산 비중과 관계없다"],"a":0,"c":"구성요소 VaR는 포트폴리오 전체 위험을 자산별로 나눠 \"누가 위험을 얼마나 키우는지\" 보여 줘요.","e":"구성요소 VaR를 모두 더하면 포트폴리오 VaR가 돼요. 헤지 역할을 하는 자산은 음수가 될 수도 있어요.","w":[null,"분산효과 때문에 개별 VaR 합과 달라요.","헤지 자산은 음수가 될 수 있어요.","비중이 클수록 기여도가 커요."],"k":"반 전체 소음을 학생별로 나눠 보면, 조용히 시키는 학생은 마이너스 기여예요.","m":"Σ 구성요소 VaR = 포트폴리오 VaR"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"민감도 분석","q":"금리나 환율 같은 위험요인 하나만 일정 폭 변한다고 가정하고 포트폴리오 가치 변화를 측정하는 방법은?","o":["역사적 시뮬레이션","백테스팅","몬테카를로 시뮬레이션","민감도 분석"],"a":3,"c":"위험 측정 방법에는 한 가지 변수만 움직여 보는 단순한 방법부터 여러 변수를 동시에 움직이는 방법까지 있어요.","e":"위험요인 하나의 변화가 가치에 주는 영향을 보는 것은 민감도 분석이에요. 듀레이션, 델타가 대표적인 민감도 지표예요.","w":["과거 변화를 그대로 적용해요.","VaR 모형 검증 방법이에요.","여러 변수를 무작위로 움직여 봐요.",null],"k":"\"금리만 1% 오르면?\"처럼 하나만 바꿔 보는 거예요.","m":"민감도 분석 = 단일 위험요인 변화 영향"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"유동성 조정 VaR","q":"팔기 어려운 자산으로 구성된 포지션의 위험을 평가할 때 고려할 사항으로 가장 적절한 것은?","o":["청산에 걸리는 기간이 길수록 VaR를 더 크게 잡아야 한다","유동성이 낮으면 VaR를 줄여야 한다","유동성은 VaR와 관계없다","팔기 어려운 자산은 위험이 없다"],"a":0,"c":"일반 VaR는 포지션을 보유 기간 안에 정상 가격으로 정리할 수 있다고 가정해요. 팔기 어려운 자산은 그 가정이 맞지 않아요.","e":"청산 기간이 길거나 매도 시 가격이 크게 밀리면 손실이 더 커질 수 있으므로 유동성을 반영해 VaR를 더 크게 잡아요.","w":[null,"유동성이 낮으면 위험이 커져요.","유동성은 손실 크기에 영향을 줘요.","팔기 어려울수록 위험이 커요."],"k":"빨리 못 파는 물건은 파는 동안 값이 더 떨어질 수 있어요.","m":"유동성 낮음 → 청산기간·가격충격 → VaR 상향"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"음의 왜도","q":"수익률 분포의 왜도가 음(−)일 때의 의미로 가장 적절한 것은?","o":["오른쪽 꼬리가 길어 큰 이익이 날 가능성이 있다","왼쪽 꼬리가 길어 큰 손실이 날 가능성이 상대적으로 크다","분포가 완전히 대칭이다","첨도가 0이다"],"a":1,"c":"왜도는 분포가 한쪽으로 기울어진 정도를 나타내요. 꼬리가 긴 쪽이 극단값이 나오는 쪽이에요.","e":"왜도가 음수면 왼쪽(손실 쪽) 꼬리가 길어 드물지만 큰 손실이 날 가능성이 상대적으로 커요.","w":["양(+)의 왜도의 설명이에요.",null,"왜도 0일 때예요.","첨도와는 다른 개념이에요."],"k":"평소엔 조금씩 벌다가 가끔 크게 잃는 모양이에요.","m":"왜도 < 0 → 왼쪽(손실) 꼬리 · 왜도 > 0 → 오른쪽 꼬리"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"금리위험의 두 얼굴","q":"채권 보유자가 지는 금리위험에 관한 설명으로 가장 적절한 것은?","o":["금리가 오르면 채권 가격이 올라 이익을 본다","금리가 오르면 가격위험(손실), 금리가 내리면 재투자위험이 생긴다","금리 변동은 채권 투자에 영향이 없다","금리가 내리면 재투자수익이 늘어난다"],"a":1,"c":"금리 변동은 채권 가격과 이자 재투자 수익에 반대 방향으로 영향을 줘요.","e":"금리가 오르면 채권 가격이 떨어지는 가격위험, 금리가 내리면 받은 이자를 낮은 금리로 굴려야 하는 재투자위험이 생겨요.","w":["금리가 오르면 가격이 내려요.",null,"금리는 채권에 큰 영향을 줘요.","금리가 내리면 재투자수익이 줄어요."],"k":"금리가 오르면 \"값\"이, 내리면 \"이자 굴리기\"가 문제예요.","m":"금리↑ → 가격위험 · 금리↓ → 재투자위험 (면역전략으로 상쇄)"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"결제위험","q":"서로 다른 시간대에서 외환을 결제할 때 한쪽은 이미 돈을 보냈는데 상대방이 대금을 보내기 전에 파산해 손실을 보는 위험은?","o":["결제위험(헤르슈타트 위험)","시장위험","모형위험","유동성 프리미엄"],"a":0,"c":"외환 거래는 나라마다 시간대가 달라 두 통화가 동시에 결제되지 않을 수 있어요.","e":"내가 먼저 지급했는데 상대방이 지급 전에 파산해 생기는 위험을 결제위험(헤르슈타트 위험)이라고 해요.","w":[null,"가격 변동 위험이에요.","모형이 틀려서 생기는 위험이에요.","위험의 종류가 아니라 보상 개념이에요."],"k":"물건값을 먼저 보냈는데 상대가 물건을 보내기 전에 문을 닫아 버린 상황이에요.","m":"결제위험 = 시차 결제 중 상대방 파산"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"모형위험","q":"위험 측정 모형의 잘못된 가정이나 오류 때문에 위험을 잘못 측정해 손실이 생길 위험은?","o":["모형위험","신용위험","결제위험","국가위험"],"a":0,"c":"VaR나 가격 모형은 여러 가정 위에 서 있어서, 가정이 틀리면 위험 측정도 틀려요.","e":"모형의 가정이나 계산 오류로 위험을 잘못 측정하거나 가격을 잘못 매겨 손실이 생기는 것은 모형위험이에요.","w":[null,"상대방 채무불이행 위험이에요.","결제 시차 위험이에요.","특정 국가의 정치·경제 위험이에요."],"k":"지도가 틀리면 아무리 잘 운전해도 길을 잃어요.","m":"모형위험 = 모형 가정·오류로 인한 오측정"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"VaR의 하위가법성","q":"VaR와 기대손실(ES)을 비교한 설명으로 가장 적절한 것은?","o":["VaR는 포트폴리오 VaR가 개별 VaR 합보다 커지는 경우가 있어 하위가법성을 항상 만족하지는 않지만, ES는 하위가법성을 만족한다","VaR는 언제나 하위가법성을 만족한다","ES는 VaR보다 항상 작다","ES는 꼬리 손실 크기를 반영하지 못한다"],"a":0,"c":"좋은 위험 측정치는 합쳐서 분산하면 위험이 줄거나 같아야 해요(하위가법성).","e":"VaR는 분포 모양에 따라 합친 포트폴리오의 VaR가 개별 VaR 합보다 커질 수 있어 일관된 위험측정치가 아니에요. ES는 하위가법성을 만족해요.","w":[null,"만족하지 않는 경우가 있어요.","ES ≥ VaR예요.","ES는 꼬리 손실의 평균이에요."],"k":"VaR는 가끔 \"합치면 더 위험하다\"는 이상한 답을 내요.","m":"하위가법성: VaR X(항상은 아님) · ES O · ES ≥ VaR"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"재무위험의 종류","q":"금융회사가 지는 재무위험의 종류에 대한 설명으로 가장 적절하지 않은 것은?","o":["운영위험은 내부 절차·인력·시스템의 실패나 외부 사건에서 생긴다","시장위험은 주가·금리·환율·상품가격 같은 시장가격의 변동에서 생긴다","유동성위험은 시장위험 안에 포함되는 하위 위험이다","법적위험은 맺은 계약을 법적으로 집행할 수 없어 손실을 볼 위험이다"],"a":2,"c":"재무위험은 시장위험·신용위험·유동성위험·운영위험·법적위험으로 나눠 봐요.","e":"유동성위험은 시장위험에 속한 위험이 아니라, 시장위험·신용위험과 같은 층위의 독립된 위험이에요. 포지션을 제때 제값에 팔지 못해 손실을 보는 위험이에요. 참고로 거래상대방이 돈을 갚지 못하는 위험은 신용위험이에요.","w":["운영위험은 시스템 결함, 내부통제 실패, 사기, 직원 실수, 재해 같은 사건에서 생겨요.","시장위험은 위험요인에 따라 주가·금리·환율·상품가격 위험으로 나뉘어요.",null,"법적위험은 계약 내용을 법적으로 실행할 수 없을 때 생기는 위험이에요."],"k":"유동성위험은 시장위험의 '부하'가 아니라 같은 줄에 선 '동료'예요.","m":"재무위험 = 시장 · 신용 · 유동성 · 운영 · 법적위험 (유동성 ≠ 시장위험의 하위)"},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"t":"부분가치평가와 완전가치평가","q":"〈보기〉의 VaR 측정 방법 가운데 완전가치평가법으로 분류되는 것만 묶은 것은?\nㄱ. 델타-노말 방법\nㄴ. 델타-감마 방법\nㄷ. 역사적 시뮬레이션\nㄹ. 몬테카를로 시뮬레이션\nㅁ. 스트레스 검증","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄷ, ㄹ, ㅁ","ㄴ, ㄹ, ㅁ"],"a":2,"c":"부분가치평가법은 델타·감마 같은 민감도로 가치 변화를 '근사'하고, 완전가치평가법은 시나리오별로 가격모형을 돌려 포지션 가치를 '새로 계산'해요.","e":"역사적 시뮬레이션, 몬테카를로 시뮬레이션, 스트레스 검증은 시나리오마다 포지션을 다시 평가하므로 완전가치평가법이에요. 몬테카를로에서 주가 같은 위험요인은 주로 기하 브라운 운동(GBM) 모형으로 만들어 내요.","w":["델타-노말과 델타-감마는 민감도로 근사하는 부분가치평가법이에요.","스트레스 검증도 시나리오마다 포지션을 다시 평가하므로 완전가치평가법이에요.",null,"델타-감마는 2차 항까지 쓰지만 가치를 새로 계산하지는 않아 부분가치평가법이에요."],"k":"부분가치평가는 '눈대중 견적', 완전가치평가는 '하나하나 다시 재 보는 실측'이에요.","m":"부분가치: 델타-노말·델타-감마 · 완전가치: 역사적·몬테카를로·스트레스 검증"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"옵션 포지션 VaR의 함정","q":"옵션이 포함된 포지션의 VaR 측정에 관한 설명으로 가장 적절하지 않은 것은?","o":["델타-노말 방식의 옵션 VaR 계산에는 기초자산 가격, 변동성, 신뢰상수, 델타가 쓰이고 행사가격은 식에 직접 들어가지 않는다","델타 중립으로 짠 포지션은 델타 기준 VaR가 0에 가깝게 나와 실제 위험이 과소평가될 수 있다","양(+)의 감마를 가진 옵션 매수 포지션에 감마를 반영하면 VaR는 델타만 쓸 때보다 커진다","델타-감마 방법도 가격모형으로 가치를 새로 계산하지 않고 민감도로 어림하므로 부분가치평가법이다"],"a":2,"c":"옵션 가치는 기초자산 가격에 대해 곡선으로 움직여요. 델타는 그 곡선의 기울기(직선 근사)이고, 감마는 휘어진 정도예요.","e":"감마가 양(+)인 매수 포지션은 가격이 불리하게 움직여도 실제 손실이 직선(델타) 예측보다 작아요. 그래서 감마를 반영하면 VaR가 오히려 작아져요. 음(−)의 감마를 가진 매도 포지션은 반대로 커져요.","w":["델타-노말 옵션 VaR = 기초자산 가격 × 변동성 × 신뢰상수 × 델타예요. 행사가격·프리미엄은 직접 쓰지 않아요.","델타가 0이면 델타로 잰 위험도 0이 되지만, 감마 같은 곡률 위험은 그대로 남아 있어요.",null,"델타-감마 방법은 2차 항까지 쓰지만 가치를 새로 계산하지는 않아 부분가치평가법이에요."],"k":"옵션 매수자는 휘어진 길(양의 감마) 덕분에 내리막에서 직선으로 계산한 것보다 덜 미끄러져요.","m":"감마(+) 매수 → 델타-감마 VaR < 델타 VaR · 감마(−) 매도 → 더 큼 · 델타 중립 = VaR 과소평가"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"KMV 모형의 구조","q":"KMV 모형에 관한 설명으로 가장 적절하지 않은 것은?","o":["부도거리는 자산가치의 변동성이 커질수록 길어져 부도 위험이 줄어든다","주주 지분을 기업 자산가치를 기초자산으로, 부채를 행사가격으로 하는 콜옵션으로 본다","부도점은 보통 '단기부채 + 장기부채 × 50%'로 정한다","정규분포를 가정한 이론적 부도확률과 실제 부도 자료로 추정한 실증적 부도확률은 서로 다를 수 있다"],"a":0,"c":"KMV 모형은 '기업 자산가치가 부도점 아래로 떨어지면 부도'라고 보고, 주가 같은 시장 정보로 기업 자산의 가치와 변동성을 거꾸로 추정해요.","e":"부도거리 = (기대 자산가치 − 부도점) ÷ 자산가치 표준편차예요. 변동성(분모)이 커지면 부도거리는 짧아지고 부도 위험은 커져요.","w":[null,"빚을 다 갚은 뒤의 나머지만 주주 몫이므로, 주식은 자산가치에 대한 콜옵션과 같아요.","장기부채는 당장 상환 압력이 덜하므로 절반만 반영해 부도점을 잡아요.","정규분포로 계산한 이론 EDF와 실제 부도 통계로 구한 실증 EDF는 일치하지 않을 수 있어요."],"k":"부도거리는 '절벽(부도점)까지 남은 걸음 수'예요. 걸음이 크게 흔들릴수록(변동성↑) 남은 걸음 수는 줄어요.","m":"DD = (기대 자산가치 − 부도점) ÷ σ · 부도점 = 단기부채 + 장기부채 × ½ · 주식 = 자산 콜옵션"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"부도모형과 MTM 모형","q":"신용리스크 측정 모형에 관한 설명으로 가장 적절한 것은?","o":["부도모형(DM)은 부도가 나지 않더라도 신용등급이 떨어지면 그 가치 하락을 신용손실로 인식한다","MTM 모형은 신용등급 전이확률을 이용해 등급 변화에 따른 가치 변동까지 신용손실로 반영한다","신용리스크는 신용손실 분포의 기대손실(EL)로 정의하며 자기자본으로 대비한다","신용손실 분포는 좌우 대칭이므로 평균과 표준편차만으로 꼬리 위험을 충분히 잴 수 있다"],"a":1,"c":"부도모형은 '부도가 나야' 손실로 보고, MTM 모형은 '등급이 떨어져도' 손실로 봐요.","e":"MTM 모형은 등급 전이행렬로 등급이 오르내릴 때의 가치 변화 분포를 구해 신용 VaR를 계산해요. JP모건의 CreditMetrics가 대표적이에요. 부도모형은 익스포저·부도율·손실률만으로 계산해요.","w":["그것은 MTM 모형의 특징이에요. 부도모형은 부도가 실제로 났을 때만 손실을 인식해요.",null,"신용리스크는 예상외손실(UL)로 정의해요. 기대손실은 비용으로 보고 충당금으로 대비하고, 예상외손실을 자기자본으로 대비해요.","신용손실 분포는 꼬리가 길고 두꺼운 비대칭 분포라, 퍼센타일 같은 방법으로 재는 것이 바람직해요."],"k":"부도모형은 '시험 낙제'만 벌점, MTM 모형은 '성적 하락'에도 벌점을 줘요.","m":"부도모형: EAD·PD·LGD, 부도만 손실 · MTM: 등급 전이까지 손실(CreditMetrics) · 신용리스크 = UL"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"리스크관리 실패 사례","q":"리스크관리 실패 사례와 그 원인·교훈의 연결로 가장 적절하지 않은 것은?","o":["베어링은행 – 한 딜러가 거래와 결제 업무를 함께 맡아 손실을 숨겨, 직무 분리와 내부통제의 중요성을 남겼다","오렌지카운티 – 단기로 빌린 돈으로 장기채에 투자했다가 금리가 오르며 큰 손실을 내, 정기적 시가평가와 VaR 측정의 필요성을 남겼다","LTCM – 차익거래 모형을 지나치게 믿고 레버리지를 크게 키웠다가 시장 급변으로 무너졌다","메탈게젤샤프트 – 딜러 개인의 가공계좌 불법거래가 원인이었으며, 명목거래한도 설정이 핵심 교훈이다"],"a":3,"c":"대표적인 실패 사례는 '무엇 때문에 무너졌는지' 한 가지 표지로 구분해 두면 쉬워요.","e":"메탈게젤샤프트는 장기 고정가격 석유 공급계약을 만기가 짧은 근월물 선물로 이어 가며 헤지하다가, 유가 하락으로 증거금 부담이 커져 무너진 사례예요. 허위 계좌를 통한 불법거래는 베어링은행의 특징이에요.","w":["베어링은행은 매매 담당과 결제·확인 담당이 나뉘지 않아 불법거래가 오래 숨겨진 사례예요.","오렌지카운티는 금리 예측 실패로 지방재정이 파산한 사례예요.","LTCM은 모형을 너무 믿고 빚을 지나치게 늘린 것이 원인이었어요.",null],"k":"베어링 = 혼자 다 한 딜러, 오렌지카운티 = 금리 베팅, LTCM = 천재들의 레버리지, 메탈게젤샤프트 = 짧은 선물로 긴 계약 막기예요.","m":"베어링: 직무 미분리 · 오렌지카운티: 금리↑·시가평가 · LTCM: 모형 과신·레버리지 · MG: 만기 불일치 롤링헤지"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"만기 불일치 헤지의 위험","q":"B사는 고객에게 앞으로 8년간 경유를 정해진 가격에 공급하기로 하고, 이 위험을 만기 1~2개월짜리 근월물 선물을 계속 갈아타는 방식과 일부 장외 스왑으로 헤지했다. 이 헤지 구조에 관한 설명으로 가장 적절하지 않은 것은?","o":["근월물을 만기마다 새로 사야 하므로 선물 가격 구조에 따라 롤오버 손익이 생긴다","유가가 떨어지면 선물 손실은 생기지만 공급계약 이익이 곧바로 현금으로 들어오므로 자금 압박은 생기지 않는다","헤지 계약의 만기와 공급계약의 만기가 크게 어긋나 베이시스 위험이 남는다","장외 스왑은 결제를 보증해 주는 거래소가 없어 상대방이 돈을 치르지 못할 신용위험이 생긴다"],"a":1,"c":"장기 고정가격 계약을 짧은 선물로 이어 막으면 만기 불일치, 롤오버, 자금조달, 거래상대방 위험이 함께 따라와요.","e":"선물 손실은 매일 정산되어 곧바로 증거금을 내야 하지만, 공급계약의 이익은 앞으로 몇 년에 걸쳐 조금씩 들어와요. 이 시차 때문에 자금조달 위험이 생기고, 메탈게젤샤프트도 이 문제로 무너졌어요.","w":["근월물을 갈아탈 때마다 선물 가격 구조에 따라 손익이 생기는 롤오버 위험이 있어요.",null,"만기가 다르면 헤지 수단과 헤지 대상의 가격이 똑같이 움직이지 않아 베이시스 위험이 남아요.","장외 거래는 결제 보장 기관이 없어 상대방 신용위험이 있어요."],"k":"손실은 오늘 현금으로 내야 하는데 이익은 8년 할부로 들어온다면, 장부상 괜찮아도 지갑이 먼저 바닥나요.","m":"만기 불일치 롤링헤지 위험 = 롤오버 · 베이시스 · 자금조달(증거금) · 거래상대방 신용"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"VaR 기준 한도의 특징","q":"포지션 명목금액에 상한을 두는 한도 방식과 비교해 VaR 기준 위험한도의 특징으로 가장 적절한 것은?","o":["상품 간 상관관계가 반영되어 분산효과를 한도 관리에 담을 수 있다","변동성과 상관계수를 추정할 필요가 없어 가장 간편하다","과거에 없던 극단적 상황의 손실까지 한도에 자동으로 포함된다","명목금액이 같으면 위험이 다른 상품에도 똑같은 한도가 적용된다"],"a":0,"c":"명목금액 한도는 '얼마나 샀나'만 보고, VaR 한도는 '얼마나 위험한가'를 봐요.","e":"VaR 한도는 상품마다 다른 위험 크기와 상품끼리의 상관관계를 담으므로 분산효과가 한도에 들어가요. 그래서 부서별 VaR 한도를 더한 값이 회사 전체 한도보다 커도 돼요.","w":[null,"변동성과 상관계수를 추정해야 하는 쪽이 VaR 방식이에요.","VaR는 과거에 없던 극단 상황을 잘 잡지 못해 스트레스 검증으로 보완해요.","그것은 명목금액 한도의 특징이자 단점이에요."],"k":"명목금액 한도는 '장바구니 무게' 제한, VaR 한도는 '깨질 위험' 제한이에요.","m":"VaR 한도: 위험 크기·상관관계 반영 → 분산효과 인정 · 명목한도: 위험 차이 무시"},{"s":2,"sec":"리스크관리","star":3,"lv":"상","rev":0,"t":"베타를 이용한 주식 VaR","q":"500억원 규모 주식 포트폴리오의 시장 대비 베타는 0.8이고, 시장수익률의 일간 표준편차는 1.25%이다. 이때 신뢰수준 99%(z = 2.33), 보유기간 9일 기준 VaR는?","o":["11.65억원","약 43.69억원","104.85억원","34.95억원"],"a":3,"c":"주식 포트폴리오의 변동성을 직접 모르면, 시장 변동성에 베타를 곱해 포트폴리오 변동성으로 바꿔 써요.","e":"VaR = 500억 × 1.25% × 0.8 × 2.33 × √9 = 5억 × 2.33 × 3 = 34.95억원이에요. 델타-노말 방법에서 주식은 베타, 채권은 수정듀레이션, 옵션은 델타를 민감도로 곱해요.","w":["보유기간 √9 = 3을 곱하지 않은 1일 VaR예요.","베타 0.8을 곱하지 않았어요.","√9 = 3이 아니라 9를 곱했어요.",null],"k":"시장이 1% 흔들릴 때 내 주식은 0.8%만 흔들려요. 그 흔들림에 99% 기준 2.33과 기간 √9를 곱해요.","m":"주식 VaR = 금액 × σ시장 × β × z × √T","f":"500 × 0.0125 × 0.8 × 2.33 × 3 = 34.95억원"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"듀레이션 환산 채권 VaR","q":"시가 400억원인 채권의 맥컬리 듀레이션은 4.2년, 만기수익률은 5%이다. 만기수익률 변화의 일간 표준편차가 0.05%p라면 신뢰수준 95%(z = 1.65) 기준 1일 VaR는?","o":["1.32억원","1.386억원","0.80억원","13.2억원"],"a":0,"c":"채권 VaR에는 금리 1%p 변화에 가격이 몇 % 변하는지를 나타내는 수정듀레이션을 써요. 맥컬리 듀레이션이 주어지면 먼저 바꿔야 해요.","e":"수정듀레이션 = 4.2 ÷ 1.05 = 4.0이에요. VaR = 400억 × 4.0 × 0.0005 × 1.65 = 1.32억원이에요.","w":[null,"맥컬리 듀레이션 4.2를 그대로 넣었어요. 수정듀레이션(4.0)으로 바꿔야 해요.","신뢰상수 1.65를 곱하지 않았어요.","표준편차 0.05%p를 0.0005가 아니라 0.005로 넣어 10배 크게 계산했어요."],"k":"맥컬리 듀레이션은 '원재료', 수정듀레이션은 '손질한 재료'예요. VaR 요리에는 손질한 재료를 써요.","m":"수정듀레이션 = D ÷ (1 + y) · 채권 VaR = 금액 × MD × σ(Δy) × z","f":"MD = 4.2 ÷ 1.05 = 4 → 400 × 4 × 0.0005 × 1.65 = 1.32억원"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"회수율과 손실률의 결정","q":"신용위험 측정 요소에 관한 설명으로 가장 적절하지 않은 것은?","o":["기대손실은 부도 시 노출금액(EAD), 부도율(PD), 부도 시 손실률(LGD)을 곱해 구한다","부도 시 손실률은 '1 − 회수율'로 구한다","담보 등 채권 보전장치가 있는 은행대출은 일반적으로 회사채보다 회수율이 낮다","한 차주에게 받을 돈이라도 변제순위가 앞설수록 회수율이 높다"],"a":2,"c":"부도율은 '부도가 날 확률', 손실률은 '부도가 나면 얼마나 잃는가'예요. 둘은 서로 다른 변수예요.","e":"은행대출은 담보와 채권 보전장치 덕분에 회사채보다 회수율이 높게 나타나는 것이 일반적이에요. 회수율은 부도 뒤 돌려받은 금액을 익스포저로 나눠 구해요.","w":["EL = EAD × PD × LGD로, 세 요소가 신용위험 측정의 핵심이에요.","LGD = 1 − 회수율이라, 회수율이 40%면 손실률은 60%예요.",null,"변제순위가 높은 선순위 채권일수록 먼저 돌려받아 회수율이 높아요."],"k":"돈을 빌려줄 때 담보를 잡고 앞줄에 선 사람일수록 떼일 돈이 적어요.","m":"EL = EAD × PD × LGD · LGD = 1 − 회수율 · 선순위·은행대출일수록 회수율↑"},{"s":2,"sec":"리스크관리","star":2,"lv":"중","rev":0,"t":"VaR 설정과 측정법의 한계","q":"VaR 측정 조건과 방법에 관한 설명으로 가장 적절하지 않은 것은?","o":["신뢰수준을 너무 높게 잡으면 그 꼬리 구간에 해당하는 관측치가 적어 추정치를 믿기 어려워진다","다른 조건이 같으면 신뢰수준을 높이거나 보유기간을 늘릴수록 VaR는 커진다","빠르게 정리할 수 있는 유동성 높은 트레이딩 포지션에는 1일처럼 짧은 보유기간을 쓸 수 있다","역사적 시뮬레이션은 어떤 표본기간을 쓰든 결과가 거의 같아 표본기간 선택에 신경 쓸 필요가 없다"],"a":3,"c":"VaR는 보유기간과 신뢰수준을 어떻게 잡느냐, 어떤 방법으로 재느냐에 따라 값이 달라져요.","e":"역사적 시뮬레이션의 대표 약점은 표본기간을 어떻게 잡느냐에 따라 결과가 달라진다는 점이에요. 짧으면 최근 움직임에 지나치게 휘둘리고, 길면 그동안 바뀐 시장 구조를 반영하지 못해요. 또 표본기간에 없던 위기는 반영하지 못해 스트레스 검증으로 보완해요.","w":["꼬리 끝으로 갈수록 자료가 드물어 추정이 불안정해져요.","신뢰수준이 높을수록 z값이, 보유기간이 길수록 √T가 커져 VaR가 커져요.","유동성이 높을수록 빨리 정리할 수 있으므로 보유기간을 짧게 잡아요.",null],"k":"역사적 시뮬레이션은 '어떤 앨범을 펼치느냐'에 따라 같은 사람도 다르게 보여요.","m":"보유기간 = 유동성 따라 · 신뢰수준 과도 → 불안정 · 역사적 시뮬레이션 = 표본기간 의존"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","rev":0,"t":"포트폴리오 VaR로 상관계수 구하기","q":"주식 포지션의 VaR는 40억원, 채권 포지션의 VaR는 60억원이고, 둘을 합친 포트폴리오의 VaR는 80억원이다. 두 포지션 간 수익률 상관계수는?","o":["0","0.5","0.25","0.8"],"a":2,"c":"포트폴리오 VaR를 제곱하면 각 VaR의 제곱을 더한 값에 상관계수가 들어간 교차항이 붙어요. 이 식을 거꾸로 풀면 상관계수를 구할 수 있어요.","e":"80² = 40² + 60² + 2 × ρ × 40 × 60이므로 6,400 = 5,200 + 4,800ρ, ρ = 1,200 ÷ 4,800 = 0.25예요. 이때 분산효과는 (40 + 60) − 80 = 20억원이에요.","w":["상관계수가 0이면 포트폴리오 VaR는 √5,200 ≈ 72.1억원이어야 해요.","교차항의 2를 빠뜨리고 1,200 ÷ 2,400으로 계산했어요.",null,"상관계수가 0.8이면 포트폴리오 VaR는 약 95.1억원으로 더 커져요."],"k":"따로 잰 위험(40, 60)을 더하면 100인데 합쳐 보니 80이에요. 그 줄어든 정도로 두 자산이 얼마나 따로 노는지 거꾸로 알아내요.","m":"VaRp² = VaR₁² + VaR₂² + 2ρ·VaR₁·VaR₂ → ρ = (VaRp² − VaR₁² − VaR₂²) ÷ (2·VaR₁·VaR₂)","f":"(6,400 − 1,600 − 3,600) ÷ (2 × 40 × 60) = 1,200 ÷ 4,800 = 0.25"},{"s":2,"sec":"리스크관리","star":2,"lv":"상","t":"VaR 한도로 투자 한도 역산","q":"트레이딩팀에 주어진 하루 VaR 한도가 9.32억원이다. 새로 담으려는 종목의 일간 변동성(표준편차)이 2%라면, 99% 신뢰수준(z = 2.33)에서 이 종목에 넣을 수 있는 돈은 최대 얼마인가?","o":["200억원","약 282억원","466억원","약 1,086억원"],"a":0,"c":"VaR 식(투자금액 × 변동성 × z)을 투자금액에 대해 거꾸로 풀면 한도 안에서 투자할 수 있는 최대 금액이 나와요.","e":"투자금액 × 0.02 × 2.33 = 9.32억원 → 투자금액 = 9.32 ÷ 0.0466 = 200억원이에요. 위험 한도에는 VaR 한도, 손실(손절매) 한도, 포지션 한도 등이 있고, 한도를 넘으면 수익이 났더라도 보고하고 조치해야 해요.","w":[null,"99% 대신 95% z값 1.65를 썼어요.","z값을 반영하지 않고 표준편차로만 나눴어요.","z값으로 나눠야 하는데 곱했어요."],"k":"한 달 용돈 한도를 알면, 하루에 쓸 수 있는 돈을 거꾸로 계산하는 것과 같아요.","m":"최대 투자금액 = VaR 한도 ÷ (σ × z)","f":"9.32 ÷ (0.02 × 2.33) = 9.32 ÷ 0.0466 = 200억원","rev":0},{"s":2,"sec":"리스크관리","star":2,"lv":"상","t":"위험 지표의 역산 응용","q":"〈보기〉의 계산 중 옳은 것은 모두 몇 개인가?\nㄱ. 순수익 18억원이 예상되는 사업부가 RAROC(순수익 ÷ VaR)를 0.75 이상으로 유지하려면 VaR는 24억원 이하여야 한다.\nㄴ. 익스포저 250억원, 회수율 40%인 대출의 기대손실이 3억원이라면 부도율은 2%이다.\nㄷ. 익스포저와 손실률이 일정하고 부도율이 4%라면, 부도모형의 예상외손실(UL)은 기대손실(EL)의 약 4.9배이다.\nㄹ. 1일 VaR가 5억원이면 1년(260영업일) VaR는 5억원 × 260 = 1,300억원이다.","o":["1개","2개","3개","4개"],"a":2,"c":"VaR·RAROC·기대손실 공식은 앞으로도 뒤로도 풀 수 있어요. 기간 환산만큼은 기간이 아니라 기간의 제곱근을 곱해요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. ㄱ: VaR ≤ 18 ÷ 0.75 = 24억원. ㄴ: PD = 3 ÷ (250 × 0.6) = 2%. ㄷ: UL ÷ EL = √(p(1 − p)) ÷ p = √(0.96 ÷ 0.04) ≈ 4.9배예요. 부도율이 낮을수록 이 배수는 커져요. ㄹ: 5 × √260 ≈ 80.6억원이에요. 이 문제에서는 1년을 260영업일로 가정했어요.","w":["옳은 것은 3개예요.","ㄷ도 옳아요.",null,"ㄹ은 틀렸어요. √260을 곱해야 해요."],"k":"공식은 왕복 티켓이에요. 앞으로 가면 VaR를 구하고, 거꾸로 가면 한도나 부도율을 구해요.","m":"허용 VaR = 순수익 ÷ 목표 RAROC · PD = EL ÷ (EAD × LGD) · UL/EL = √((1 − p) ÷ p) · VaR_T = VaR₁ × √T","f":"ㄱ 18 ÷ 0.75 = 24 · ㄴ 3 ÷ (250 × 0.6) = 2% · ㄷ √(0.96 ÷ 0.04) ≈ 4.9 · ㄹ 5 × √260 ≈ 80.6억원","rev":0},{"s":2,"sec":"리스크관리","star":2,"lv":"중","t":"VaR 측정법별 강점과 약점","q":"VaR 측정 방법에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 어떤 모형으로 재느냐에 따라 VaR가 달라지는 폭은 옵션처럼 손익이 곡선인 상품에서 특히 크다.\nㄴ. 스트레스 검증은 확률분포에 근거해 VaR를 내므로 다른 VaR 측정 방법을 대신할 수 있다.\nㄷ. 스트레스 검증은 과거 관측 자료가 쌓이지 않은 상품에도 적용할 수 있다.\nㄹ. 역사적 시뮬레이션은 과거 실제 움직임을 그대로 쓰므로, 위험요인끼리의 연관성이 따로 계산하지 않아도 결과에 녹아든다.\nㅁ. 델타-노말 방법은 포지션마다 가치평가모형이 반드시 있어야 계산할 수 있다.","o":["2개","3개","4개","5개"],"a":1,"c":"VaR 측정법마다 무엇을 가정하고 무엇이 필요한지가 달라서, 잘하는 것과 못하는 것도 달라요.","e":"ㄱ, ㄷ, ㄹ이 옳아 3개예요. 스트레스 검증은 분석자가 정한 시나리오에 기대므로 확률을 말해 주지 못하고 상관관계도 제대로 담지 못해, VaR를 대신하는 게 아니라 보완해요. 델타-노말은 변동성과 상관계수만 있으면 계산되고, 상품 가격을 다시 매기는 모형은 쓰지 않아요. 대신 정규분포를 가정해요. 역사적 시뮬레이션은 분산이나 공분산을 따로 구하지 않아도 되지만, 보유 상품의 과거 가격 정보가 부족하면 쓰기 어려워요.","w":["옳은 것은 ㄱ, ㄷ, ㄹ 3개예요.",null,"ㄴ과 ㅁ은 틀렸어요.","ㄴ은 대체가 아니라 보완이고, ㅁ은 가치평가모형이 필요 없어요."],"k":"스트레스 검증은 \"지진 대피 훈련\"이에요. 지진이 날 확률은 알려 주지 않지만, 나면 얼마나 위험한지 보여 줘요.","m":"비선형일수록 모형 간 VaR 차이↑ · 스트레스 검증 = 보완(확률·상관 X, 자료 없어도 가능) · HS = 상관구조 자동 반영 · 델타-노말 = 가치평가모형 불필요","rev":0},{"s":2,"sec":"리스크관리","star":2,"lv":"중","t":"신용리스크 측정 자료와 집중리스크","q":"은행의 신용리스크 측정과 관리에 관한 〈보기〉에서 옳은 것만 묶은 것은?\nㄱ. 부도 시 익스포저에는 현재 대출잔액뿐 아니라 아직 쓰지 않은 한도 중 부도 전에 인출될 것으로 예상되는 금액도 포함한다.\nㄴ. 신용등급 전이확률은 부도모형으로 신용손실을 산출할 때 반드시 필요한 자료이다.\nㄷ. 대출이 한 업종에 쏠려 있으면 업황이 꺾일 때 여러 차주가 한꺼번에 나빠질 수 있으므로, 업종마다 대출 상한을 두고 차주끼리의 연관성을 넣은 신용 VaR로 쏠림 정도를 잰다.\nㄹ. 장외파생상품의 익스포저는 계약할 때 확정되므로 이후 시장가격이 움직여도 변하지 않는다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":1,"c":"신용리스크는 \"얼마를 빌려줬나(EAD)·떼일 확률(PD)·떼이면 얼마 잃나(LGD)\"로 재고, 한곳에 몰리면 위험이 더 커져요.","e":"ㄱ, ㄷ이 옳아요. 부도모형은 익스포저·부도율·손실률만으로 계산하고, 등급 전이확률은 등급 하락에 따른 가치 감소까지 잡는 MTM 모형의 자료예요. 장외파생상품의 익스포저는 시장가격에 따라 계속 바뀌므로 미리 확정되지 않아요. 비슷한 차주들에게 돈이 몰려서 생기는 이런 추가 위험을 신용집중리스크라고 해요.","w":["ㄴ은 MTM 모형에서 쓰는 자료예요.",null,"ㄴ, ㄹ은 둘 다 틀렸어요.","ㄹ은 틀렸어요. 장외파생 익스포저는 시장가격에 따라 변해요."],"k":"같은 동네 가게들에만 돈을 빌려주면, 그 동네 상권이 무너질 때 한꺼번에 못 받게 돼요.","m":"EAD = 잔액 + 미사용 한도 예상 인출분 · 전이확률 = MTM 모형 · 집중리스크 = 업종 한도 + 상관 반영 신용 VaR","rev":0},{"s":2,"sec":"리스크관리","star":2,"lv":"상","t":"KMV 부도점과 부도거리 계산","q":"D기업의 1년 후 기대 자산가치는 250억원, 자산가치 표준편차는 25억원이다. 단기부채는 120억원, 장기부채는 60억원이다. KMV 모형의 일반적인 부도점 설정 방식을 따를 때 부도거리와 그 의미로 가장 적절한 것은? (단, 자산가치는 정규분포를 따른다)","o":["부도거리 4, 자산가치가 기대값에서 4표준편차 이내에 머물 확률이 부도율이다","부도거리 2.8, 부채 전액을 부도점으로 잡은 값이다","부도거리 4, 자산가치가 기대값보다 4표준편차 이상 떨어질 확률이 부도율이다","부도거리 10, 기대 자산가치를 표준편차로 나눈 값이다"],"a":2,"c":"KMV는 단기부채 전액과 장기부채 절반을 더해 부도점을 잡고, 자산가치가 그 아래로 떨어질 확률을 부도율로 봐요.","e":"부도점 = 120 + 60 × 50% = 150억원, 부도거리 = (250 − 150) ÷ 25 = 4예요. 부도율은 자산가치가 기대값에서 4표준편차 이상 떨어지는 한쪽 꼬리 확률(약 0.003%)이에요.","w":["그것은 부도가 나지 않을 확률에 가까워요. 부도율은 아래쪽 꼬리 확률이에요.","장기부채의 절반만 반영해야 하는데 전액(180억원)을 썼어요.",null,"부도점을 빼지 않았어요."],"k":"자산가치가 출발점이고 부도점이 낭떠러지예요. 부도거리는 낭떠러지까지 \"흔들림 몇 걸음\"이 남았는지 세는 거예요.","m":"부도점 = 단기부채 + 장기부채 × 50% · DD = (기대 자산가치 − 부도점) ÷ σ · 부도율 = DD 이상 하락할 확률","f":"부도점 = 120 + 30 = 150, DD = (250 − 150) ÷ 25 = 4","rev":0},{"s":3,"sec":"직무윤리","lv":"하","t":"과당매매 판단 기준","q":"증권회사 직원 갑이 일반투자자 을의 계좌에서 짧은 기간 동안 매매를 반복하도록 권유하였다. 갑의 권유가 과당매매에 해당하는지 판단할 때 살펴보는 요소로 가장 거리가 먼 것은?","o":["담당 직원의 월별 영업실적 목표 달성률","개별 매매거래 시 권유 내용이 타당한지 여부","일반투자자가 부담하는 수수료의 총액","일반투자자의 재산상태와 투자목적에 적합한지 여부"],"a":0,"k":"과당매매는 '수수료를 벌려고 고객 계좌로 너무 자주 사고팔게 하는 것'이에요. 그래서 고객 입장에서 괜찮은 거래였는지를 봐요. 직원 실적은 고객과 상관없어요.","m":"\"과당매매는 고객 눈으로: 수수료·재산·이해도·권유 타당성\"","c":"과당매매는 투자자 이익과 관계없이 회사·직원 수익을 위해 매매를 과도하게 권유하는 행위예요. 판단은 투자자 기준으로 해요.","e":"과당매매는 수수료 총액, 재산상태·투자목적 적합성, 투자자가 위험을 이해하는지, 개별 권유의 타당성으로 판단해요. 직원의 실적 목표는 판단 기준이 아니에요.","w":[null,"판단 기준이에요. 권유마다 이유가 있어야 해요.","판단 기준이에요. 수수료가 과하면 과당매매를 의심해요.","판단 기준이에요. 고객 형편에 맞지 않는 매매는 문제예요."],"star":3,"rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"임직원의 대외활동","q":"금융투자회사 임직원이 방송 출연, 강연, 기고, SNS 활동 등 대외활동을 할 때 지켜야 할 기준으로 가장 적절하지 않은 것은?","o":["대외활동을 하려면 원칙적으로 회사의 사전 승인을 받아야 한다","회사의 공식 의견이 아닌 경우에는 개인 의견임을 분명히 밝혀야 한다","개인 SNS에 올리는 글은 사적인 활동이므로 확정되지 않은 사항을 단정적으로 말해도 된다","대외활동으로 대가를 받았다면 그 사실을 회사에 신고해야 한다"],"a":2,"c":"임직원의 대외활동은 회사와 시장에 영향을 줄 수 있어서, 사전 승인·개인 의견 표시·대가 신고 같은 절차를 지켜야 해요.","e":"SNS도 대외활동에 포함돼요. 불확실한 사항을 단정적으로 표현하거나 시장에 영향을 줄 수 있는 내용을 올리면 안 돼요.","w":["회사의 사전 승인을 받는 것이 원칙이에요.","공식 의견이 아니면 사견임을 밝혀야 해요.",null,"대가를 받으면 회사에 신고해야 해요."],"k":"회사 이름을 달고 나가는 순간 내 말이 회사 말처럼 들려요. 그래서 SNS도 \"회사 밖 개인 공간\"이 아니에요.","m":"대외활동: 사전승인 · 사견 표시 · 대가 신고 · SNS도 포함","rev":0},{"s":3,"sec":"직무윤리","lv":"중","t":"금융소비자보호법 6대 판매원칙","q":"금융소비자보호법상 금융상품 판매업자등이 지켜야 할 6대 판매원칙에 해당하는 것은 모두 몇 개인가?\n\n〈보기〉\nㄱ. 적합성 원칙\nㄴ. 적정성 원칙\nㄷ. 설명의무\nㄹ. 불공정영업행위 금지\nㅁ. 최소 수익률 보장 원칙\nㅂ. 허위·과장광고 금지","o":["3개","4개","5개","6개"],"a":2,"k":"금융상품을 팔 때 지켜야 할 약속 6가지예요. 그런데 '수익을 보장해 준다'는 약속은 오히려 하면 안 되는 말이에요.","m":"\"적합·적정·설명·불공정·부당권유·광고\" — 수익 보장은 금지 행위","c":"6대 판매원칙은 적합성 원칙, 적정성 원칙, 설명의무, 불공정영업행위 금지, 부당권유행위 금지, 허위·과장광고 금지예요.","e":"〈보기〉 중 ㄱ·ㄴ·ㄷ·ㄹ·ㅂ 다섯 개가 6대 판매원칙이에요. ㅁ의 수익률 보장은 원칙이 아니라 오히려 부당권유에 해당할 수 있는 행위예요.","w":["ㄱ·ㄴ·ㄷ·ㄹ·ㅂ 다섯 개를 다 세지 않은 값이에요.","ㄹ이나 ㅂ을 빠뜨린 값이에요.",null,"ㅁ까지 포함한 값이에요. 수익 보장은 원칙이 아니에요."],"star":3,"rev":0},{"s":3,"sec":"직무윤리","lv":"중","t":"청약철회권 행사 기간","q":"금융소비자보호법상 청약철회권의 행사 기간을 상품 유형별로 바르게 연결한 것은? (원칙적인 기준이며, 투자성 상품은 철회 대상 상품에 한한다)","o":["투자성 상품 — 계약서류를 받은 날부터 30일 이내","보장성 상품 — 보험증권을 받은 날부터 7일 이내","대출성 상품 — 계약서류를 받은 날 또는 계약체결일부터 7일 이내","투자성 상품 — 계약서류를 받은 날 또는 계약체결일부터 7일 이내"],"a":3,"k":"산 물건을 '없던 일로' 할 수 있는 숙려 기간이에요. 투자상품은 짧게 7일, 대출은 14일, 보험은 15일이에요.","m":"\"투자 7 · 대출 14 · 보험 15\"","c":"청약철회권은 계약 후 일정 기간 안에 소비자가 이유 없이 계약을 물릴 수 있는 권리예요. 기간은 상품 유형마다 달라요.","e":"투자성 상품은 계약서류를 받은 날 또는 계약체결일부터 7일 이내에 철회할 수 있어요.","w":["투자성 상품은 30일이 아니라 7일이에요.","보장성 상품은 보험증권을 받은 날부터 15일이에요(청약일부터 30일 한도).","대출성 상품은 7일이 아니라 14일이에요.",null],"star":3,"rev":0},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"이해상충의 관리","q":"금융투자업자의 이해상충 관리에 관한 설명으로 가장 적절하지 않은 것은?","o":["이해상충 발생 가능성을 파악·평가하고 내부통제기준에 따라 관리해야 한다","투자자에게 이해상충 사실을 알리기만 하면 그 수준을 낮추지 않아도 거래할 수 있다","이해상충 가능성이 있으면 투자자에게 알리고 투자자 보호에 문제가 없는 수준으로 낮춘 뒤 거래해야 한다","이해상충 가능성을 낮추기 어려우면 그 거래를 하지 않아야 한다"],"a":1,"c":"이해상충 관리는 \"파악 → 공시(알림) → 낮춤 → 안 되면 거래 금지\"의 순서로 이루어져요.","e":"알리는 것만으로는 부족해요. 투자자 보호에 문제가 없는 수준까지 낮춰야 거래할 수 있고, 낮출 수 없으면 거래를 포기해야 해요.","w":["파악·평가·관리가 출발점이에요.",null,"알리고 낮춘 뒤 거래하는 것이 원칙이에요.","낮추기 어려우면 거래하지 않아야 해요."],"k":"\"제가 이 거래로 이득을 볼 수도 있어요\"라고 말만 하고 끝내면 안 돼요. 문제가 안 될 만큼 줄이고, 못 줄이면 하지 말아야 해요.","m":"이해상충: 파악 → 알림 → 낮춤 → 불가하면 거래 X"},{"s":3,"sec":"직무윤리","star":2,"lv":"하","rev":0,"t":"직무윤리 위반 시 제재","q":"금융투자업 종사자가 직무윤리를 위반했을 때의 제재에 관한 설명으로 가장 적절하지 않은 것은?","o":["금융위원회 등은 법령에 근거해 행정제재를 할 수 있다","법을 위반한 계약은 무효·취소·해지 등 민사상 책임으로 이어질 수 있다","직무윤리는 법이 아니므로 위반하더라도 어떠한 제재나 불이익도 받지 않는다","금융투자협회는 회원사와 그 임직원에게 자율규제에 따른 제재를 할 수 있다"],"a":2,"c":"직무윤리 중 상당 부분은 법규로 정해져 있어요. 그래서 위반하면 자율규제·행정제재·민사책임·형사처벌로 이어질 수 있어요.","e":"직무윤리 위반은 법 위반이 되는 경우가 많고, 그렇지 않더라도 고객과 시장의 신뢰를 잃는 시장 통제를 받아요.","w":["금융위 등의 행정제재가 있어요.","민사상 책임이 따를 수 있어요.",null,"협회의 자율규제 제재가 있어요."],"k":"\"윤리는 마음가짐일 뿐\"이 아니에요. 금융권에서는 윤리를 어기면 협회·당국·법원 모두에게 혼날 수 있어요.","m":"윤리 위반 제재: 자율규제 · 행정 · 민사 · 형사 · 시장 통제"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"금융투자업 직무윤리가 중요한 이유","q":"증권·자산운용 업계 종사자에게 유독 높은 윤리 수준을 요구하는 배경으로 맞지 않는 것은?","o":["금융투자상품은 원본손실 가능성이 있다","고객의 재산을 맡아 관리하는 경우가 많다","회사와 고객 사이에 정보 비대칭이 크다","투자자는 늘 냉정하게 판단하니 숫자만 정확히 알려 주면 된다"],"a":3,"c":"금융투자업은 고객 돈을 다루고, 상품이 복잡하며, 고객보다 회사가 훨씬 많이 알아요. 그래서 신뢰가 가장 중요한 자산이에요.","e":"소비자를 늘 합리적인 존재로 보고 정보만 주면 된다는 생각은 전통적 관점이에요. 지금은 소비자가 충분히 보호받아야 할 존재로 봐요.","w":["원본손실 가능성 때문에 더 엄격해요.","고객 재산 수탁이 이유예요.","정보 비대칭이 이유예요.",null],"k":"아는 게 훨씬 많은 쪽이 정직해야 거래가 공정해져요.","m":"윤리 중요성: 원본손실 · 고객자산 수탁 · 정보비대칭 · 신뢰"},{"s":3,"sec":"직무윤리","star":3,"lv":"하","rev":0,"t":"전문가로서의 주의의무","q":"금융투자업 종사자가 업무를 수행할 때 일반인보다 높은 전문가 수준의 주의를 기울여야 한다는 의무는?","o":["주의의무(선량한 관리자의 주의의무)","보고의무","비밀유지의무","자기거래 금지의무"],"a":0,"c":"금융투자업 종사자의 기본 의무는 신의성실, 고객 우선(충실의무), 전문가로서의 주의의무예요.","e":"전문가에게 요구되는 수준의 주의를 기울이는 것은 주의의무(선관주의의무)예요.","w":[null,"보고의무는 업무 처리 결과를 고객에게 알리는 의무예요.","비밀유지의무는 고객 정보를 지키는 의무예요.","자기거래 금지는 이해상충 방지 의무예요."],"k":"의사가 일반인보다 조심해서 진료해야 하듯, 금융 전문가도 더 꼼꼼해야 해요.","m":"기본의무: 신의성실 · 충실의무(고객우선) · 주의의무(전문가)"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"이해상충의 발생 원인","q":"금융투자업에서 이해상충이 생기는 원인에 관한 설명으로 가장 적절하지 않은 것은?","o":["기업금융 같은 사적 업무에서 얻은 미공개 정보가 자산운용·투자권유 같은 공적 업무에 쓰일 때 생긴다","한 회사가 여러 금융투자업을 함께 영위하면 이해상충 가능성이 커진다","회사와 고객 사이의 정보 비대칭이 원인이 된다","자산운용 등 공적 업무의 정보가 기업금융 업무로 흘러갈 때만 이해상충이 생긴다"],"a":3,"c":"이해상충은 회사나 직원의 이익과 고객의 이익이 부딪칠 때 생겨요.","e":"미공개 정보는 주로 기업금융 같은 사적 업무 영역에서 생겨 공적 업무 영역으로 흘러갈 때 문제가 돼요. 흐름 방향을 반대로 적었어요.","w":["정보가 사적 → 공적 영역으로 흐를 때예요.","겸영이 늘면 이해상충 가능성이 커요.","정보 비대칭이 원인이에요.",null],"k":"기업 비밀을 아는 부서의 정보가 고객 상대 부서로 새면 문제예요.","m":"이해상충: 사적업무 정보 → 공적업무 이용 · 겸영 · 정보비대칭"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"정보교류 차단","q":"금융투자회사가 이해상충을 막기 위해 부서 사이에 미공개 정보가 오가지 않도록 칸막이를 두는 장치는?","o":["정보교류 차단장치(차이니즈 월)","내부제보 제도","분쟁조정 제도","청약철회 제도"],"a":0,"c":"같은 회사 안에서도 기업금융 부서와 운용·영업 부서는 이해가 다를 수 있어요.","e":"부서 간 정보 이동을 막는 칸막이가 정보교류 차단장치(차이니즈 월)예요.","w":[null,"위법행위를 알리는 제도예요.","분쟁을 해결하는 제도예요.","소비자가 계약을 철회하는 제도예요."],"k":"부서 사이에 \"만리장성\"을 쌓아 비밀이 넘어가지 않게 해요.","m":"정보교류 차단 = 차이니즈 월"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"적합성 원칙의 절차","q":"금융소비자보호법상 투자성 상품을 권유할 때 판매업자가 밟는 절차를 순서대로 바르게 나열한 것은?\nㄱ. 맞는 상품을 골라 권하고 핵심 내용을 알려 준다\nㄴ. 상품 추천을 받고 싶은지 물어본다\nㄷ. 일반금융소비자인지 확인한다\nㄹ. 상담으로 투자 목적·재산 상황 등을 듣고 서명 등으로 확인받는다","o":["ㄴ → ㄷ → ㄹ → ㄱ","ㄷ → ㄴ → ㄹ → ㄱ","ㄹ → ㄴ → ㄷ → ㄱ","ㄴ → ㄹ → ㄷ → ㄱ"],"a":0,"c":"적합성 원칙은 소비자에게 맞는 상품만 권유하도록 하는 원칙이에요. 순서대로 확인하는 것이 중요해요.","e":"권유 희망 확인 → 일반금융소비자 여부 확인 → 정보 파악·확인 → 적합한 상품 권유·설명 순이에요.","w":[null,"권유를 원하는지부터 확인해요.","정보 파악 전에 권유 희망과 소비자 유형을 확인해요.","정보 파악 전에 소비자 유형을 확인해요."],"k":"\"추천 원하세요? → 일반 고객이세요? → 상황 알려 주세요 → 이 상품이 맞아요\" 순서예요.","m":"권유 희망 → 일반소비자 확인 → 정보 파악 → 권유·설명"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"적정성 원칙","q":"일반 고객이 추천 없이 스스로 고른 파생상품에 가입하려 한다. 판매사가 고객 정보를 파악해 부적정하면 알려야 하는 원칙은?","o":["부당권유 금지","적합성 원칙","적정성 원칙","설명 의무"],"a":2,"c":"권유를 하면 적합성 원칙, 권유 없이 소비자가 스스로 사려 할 때는 적정성 원칙이 적용돼요.","e":"권유 없이 판매하려 할 때 소비자 정보를 파악하고, 그 상품이 적정하지 않으면 그 사실을 알리고 확인받는 것이 적정성 원칙이에요.","w":["불확실한 사항에 단정적 판단을 주는 등 잘못된 권유를 막는 원칙이에요.","권유할 때 적용되는 원칙이에요.",null,"설명의무는 중요사항을 설명할 의무예요."],"k":"손님이 직접 \"이거 살래요\" 해도 \"이건 위험해서 손님께 맞지 않아요\"라고 알려 줘야 해요.","m":"권유 O → 적합성 / 권유 X → 적정성"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"투자광고의 운용실적 표시","q":"투자일임상품 광고에서 금융소비자보호법상 허용되지 않는 것은?","o":["과거 실적이 앞으로의 수익을 뜻하지 않는다는 점을 함께 알린다","5년 성과 가운데 수익률이 좋았던 1년의 실적만 골라 싣는다","운용 수수료를 함께 표시한다","상품의 주요 위험을 함께 표시한다"],"a":1,"c":"투자광고는 소비자를 오인시키지 않도록 운용실적 표시 방법을 엄격하게 정해요.","e":"유리한 기간의 실적만 골라 싣는 것은 소비자를 오인시키므로 금지돼요.","w":["미래 수익 비보장 문구는 필요해요.",null,"수수료 표시는 필요해요.","주요 위험 표시는 필요해요."],"k":"잘 나온 사진만 골라 올리는 것처럼 좋은 해만 보여 주면 안 돼요.","m":"운용실적 광고: 유리한 기간만 선택 표시 X"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"금융소비자보호 총괄책임자","q":"금융소비자보호 총괄책임자(CCO)에 관한 설명으로 가장 적절한 것은?","o":["영업 부서장이 겸직하는 것이 원칙이다","대표이사 직속의 독립적 지위에서 금융소비자보호 업무를 총괄한다","준법감시인의 지휘를 받는다","판매 실적 목표를 정하는 것이 주된 업무이다"],"a":1,"c":"CCO는 금융소비자보호 업무를 총괄하는 책임자로, 영업 압박에서 독립적이어야 해요.","e":"CCO는 대표이사 직속으로 독립적인 지위에서 소비자보호 절차 마련, 민원 관리 등 업무를 총괄해요.","w":["영업과 분리된 독립성이 중요해요.",null,"대표이사 직속이에요.","소비자보호가 주된 업무예요."],"k":"소비자 편에 서야 하니 영업 부서 밑이 아니라 대표 바로 아래에 둬요.","m":"CCO = 대표이사 직속 · 독립적 소비자보호 총괄"},{"s":3,"sec":"직무윤리","star":3,"lv":"하","rev":0,"t":"내부통제기준의 제정","q":"증권사가 임직원이 지킬 업무 기준(내부통제기준)을 새로 만들거나 고치려 한다. 맞는 설명은?","o":["대표이사 혼자 결재로 고칠 수 있다","법에서 요구하는 것이 아니라 권고 사항이다","기준을 둘지 말지는 회사 마음이다","만들거나 고칠 때 이사회 의결이 필요하다"],"a":3,"c":"내부통제기준은 임직원이 법령을 지키며 일하도록 회사가 정한 기준과 절차예요.","e":"내부통제기준 마련은 법령상 의무이고, 제정과 변경은 모두 이사회 결의를 거쳐야 해요.","w":["이사회 결의가 필요해요.","법령상 의무예요.","마련은 법령상 의무예요.",null],"k":"회사의 \"교통법규\"라서 이사회가 정하고 이사회가 바꿔요.","m":"내부통제기준: 법적 의무 · 제정·변경 = 이사회 결의"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"준법감시인의 보수와 독립성","q":"준법감시인에 관한 설명으로 가장 적절하지 않은 것은?","o":["임면은 이사회 의결을 거친다","임기는 2년 이상으로 한다","보수와 평가는 회사의 재무적 경영성과와 연동하지 않는 별도 기준으로 정한다","보수는 회사 이익이 많이 날수록 크게 늘도록 이익과 직접 연동해야 한다"],"a":3,"c":"준법감시인은 회사 안의 \"심판\"이라 회사 실적에 흔들리지 않게 독립성을 보장해요.","e":"준법감시인의 보수와 평가는 재무적 경영성과와 연동하지 않는 별도 기준으로 운영해야 해요.","w":["이사회 의결로 임면해요.","임기는 2년 이상이에요.","성과 비연동이 원칙이에요.",null],"k":"심판의 월급이 한 팀 점수에 따라 달라지면 공정할 수 없어요.","m":"준법감시인: 이사회 임면 · 임기 2년↑ · 보수는 성과 비연동"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"준법감시인의 겸직 제한","q":"준법감시인의 겸직에 관한 설명으로 가장 적절한 것은?","o":["자산운용 업무를 함께 맡을 수 있다","영업 부서장을 겸할 수 있다","직원 중에서 준법감시인을 선임할 수 있는 소규모 금융회사는 위험관리책임자 업무를 겸할 수 있다","어떤 경우에도 다른 업무를 겸할 수 없다"],"a":2,"c":"준법감시인이 점검 대상 업무를 직접 하면 스스로를 감시하게 되므로 겸직을 제한해요.","e":"자산운용 등과의 겸직은 금지되지만, 소규모 금융회사에서는 위험관리책임자 업무를 겸할 수 있어요.","w":["자산운용 업무 겸직은 금지돼요.","영업 업무 겸직은 금지돼요.",null,"소규모 회사의 위험관리책임자 겸직 예외가 있어요."],"k":"감시하는 사람이 감시받는 일을 같이 하면 안 되지만, 작은 회사는 비슷한 점검 업무를 함께 할 수 있어요.","m":"준법감시인 겸직: 자산운용 등 X · 소규모는 위험관리책임자 겸직 가능"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"설명의무 위반 손해배상","q":"금융소비자보호법상 설명의무를 위반한 판매업자의 손해배상 책임에 관한 설명으로 가장 적절한 것은?","o":["소비자가 판매업자의 고의·과실을 입증해야 한다","판매업자가 자신에게 고의나 과실이 없음을 입증하지 못하면 배상 책임을 진다","설명의무 위반에는 손해배상 책임이 없다","대리인을 통한 계약에서는 설명의무 이행 여부를 본인 기준으로 판단한다"],"a":1,"c":"금융상품은 복잡해서 소비자가 판매업자의 잘못을 증명하기 어려워요. 그래서 입증 책임을 판매업자에게 넘겼어요.","e":"설명의무 위반으로 손해가 생기면 판매업자가 고의·과실이 없음을 입증하지 못하는 한 배상 책임을 져요.","w":["입증 책임이 판매업자에게 전환돼요.",null,"손해배상 책임이 있어요.","설명의무 이행 여부는 대리인 기준으로 판단해요."],"k":"\"잘못 없었어요\"를 회사가 증명해야 해요. 소비자가 증명할 필요가 없어요.","m":"설명의무 위반 → 판매업자가 무과실 입증 책임"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"t":"부당권유행위","q":"금융소비자보호법상 부당권유행위에 해당하는 것은?","o":["소비자의 요청을 받고 상품 위험을 설명했다","불확실한 사항에 대해 \"이 주식은 반드시 오릅니다\"라고 단정적으로 말했다","상품의 장단점을 함께 설명했다","소비자가 원해서 추가 자료를 제공했다"],"a":1,"c":"부당권유는 소비자를 오인시키거나 판단을 흐리게 하는 권유예요. 단정적 판단 제공, 허위 사실, 불초청 권유 등이 있어요.","e":"불확실한 사항에 대해 단정적 판단을 주거나 확실하다고 오인하게 하는 것은 부당권유예요.","w":["정상적인 설명이에요.",null,"균형 잡힌 설명이에요.","소비자 요청에 따른 정보 제공이에요."],"k":"\"무조건 오른다\"는 말은 금융에서 절대 해선 안 되는 말이에요.","m":"부당권유: 단정적 판단 · 허위사실 · 불초청 권유 등"},{"s":3,"sec":"직무윤리","star":2,"lv":"상","rev":0,"t":"재산상 이익 제공 공시","q":"금융투자회사가 특정 거래상대방에게 최근 5개 사업연도를 합산해 일정 금액을 넘는 재산상 이익을 제공한 경우 인터넷 홈페이지에 공시해야 한다. 그 기준 금액은?","o":["1억원","5억원","10억원","50억원"],"a":2,"c":"재산상 이익 제공은 한도 규제 대신 내부통제와 공시로 관리해요.","e":"최근 5개 사업연도 합산 10억원을 넘으면 인터넷 홈페이지에 공시해야 해요.","w":["기준보다 낮아요.","기준보다 낮아요.",null,"기준보다 높아요."],"k":"한 상대에게 5년간 10억 넘게 줬다면 모두가 볼 수 있게 공개해야 해요.","m":"재산상 이익 공시: 5개 사업연도 합산 10억 초과"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"1억원 이하 과태료 사유","q":"금융회사의 지배구조에 관한 법률상 1억원 이하의 과태료 부과 대상으로 가장 적절한 것은?","o":["내부통제기준을 마련하지 않은 경우","임직원이 회사 행사에 불참한 경우","준법감시인이 연차 휴가를 사용한 경우","이사회를 정기적으로 연 경우"],"a":0,"c":"지배구조법은 내부통제 체계를 갖추지 않은 회사에 과태료를 부과해요.","e":"내부통제기준을 마련하지 않거나 준법감시인을 두지 않은 경우 등은 1억원 이하의 과태료 대상이에요.","w":[null,"과태료 대상이 아니에요.","과태료 대상이 아니에요.","정상적인 운영이에요."],"k":"회사의 \"교통법규(내부통제기준)\"를 아예 안 만들면 큰 과태료를 내요.","m":"1억 이하 과태료: 내부통제기준 미마련 · 준법감시인 미선임 등"},{"s":3,"sec":"직무윤리","star":3,"lv":"상","rev":0,"t":"위법계약해지 기한","q":"2024년 3월 1일에 투자성 상품 계약을 맺은 소비자가 2026년 6월 1일에 판매 과정의 위법 사실을 알았다. 금융소비자보호법상 위법계약해지를 요구할 수 있는 마지막 날로 가장 적절한 것은?","o":["2026년 6월 11일","2027년 6월 1일","2029년 3월 1일","기한 제한이 없다"],"a":1,"c":"위법계약해지권은 계약체결일부터 5년 이내의 범위에서, 위법 사실을 안 날부터 1년 이내에 행사할 수 있어요.","e":"안 날(2026.6.1)부터 1년인 2027년 6월 1일이 계약일부터 5년(2029.3.1)보다 먼저 오므로 2027년 6월 1일까지예요.","w":["10일은 판매업자가 해지 요구를 받고 수락 여부를 알려야 하는 기간이에요. 소비자의 요구 기한이 아니에요.",null,"5년 한도만 보고 1년 기한을 빠뜨렸어요.","기한이 있어요."],"k":"\"안 날부터 1년\"과 \"계약일부터 5년\" 중 먼저 오는 날까지예요.","m":"위법계약해지: 계약일 5년 이내 + 안 날부터 1년 이내 · 회사는 10일 내 수락 여부 통지"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"전문금융소비자의 대우","q":"금융소비자 유형에 관한 설명으로 가장 적절한 것은?","o":["전문금융소비자는 어떤 경우에도 일반금융소비자로 대우받을 수 없다","일부 전문금융소비자는 일반금융소비자와 같은 대우를 받겠다고 판매업자에게 알릴 수 있다","적합성 원칙은 전문금융소비자에게만 적용된다","전문금융소비자와 일반금융소비자의 보호 수준은 같다"],"a":1,"c":"금융소비자는 전문성과 위험감수능력에 따라 전문금융소비자와 일반금융소비자로 나뉘고, 보호 수준이 달라요.","e":"일정한 전문금융소비자는 일반금융소비자로 대우받겠다는 의사를 알리면 일반금융소비자와 같은 보호를 받을 수 있어요.","w":["일정한 경우 일반금융소비자 대우를 받을 수 있어요.",null,"적합성 원칙은 일반금융소비자에게 적용돼요.","일반금융소비자가 더 두텁게 보호돼요."],"k":"\"저는 전문가지만 일반 고객처럼 꼼꼼히 설명받고 싶어요\"라고 요청할 수 있어요.","m":"전문 → 일반 대우 전환 가능 · 적합성·적정성 = 일반소비자"},{"s":3,"sec":"직무윤리","star":2,"lv":"하","rev":0,"t":"법과 윤리의 관계","q":"법과 윤리의 관계에 관한 설명으로 가장 적절한 것은?","o":["법은 윤리보다 넓은 개념이다","\"법은 최소한의 윤리\"라고 할 수 있다","윤리를 지키면 법은 지키지 않아도 된다","윤리는 법과 아무 관계가 없다"],"a":1,"c":"법은 사회가 반드시 지켜야 할 최소한의 규범을 강제로 정한 것이고, 윤리는 그보다 넓은 바람직한 행동 기준이에요.","e":"법은 윤리 가운데 강제할 필요가 있는 최소한을 정한 것이라 \"법은 최소한의 윤리\"라고 해요.","w":["윤리가 더 넓은 개념이에요.",null,"법은 반드시 지켜야 해요.","법은 윤리에 바탕을 둬요."],"k":"법은 \"이 선은 넘지 마\", 윤리는 \"이렇게 하면 더 좋아\"예요.","m":"법 = 최소한의 윤리 · 윤리 ⊃ 법"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"신의성실의 원칙","q":"금융투자업 종사자의 신의성실 의무에 관한 설명으로 가장 적절하지 않은 것은?","o":["윤리적 의무이면서 법적 의무이기도 하다","권리 행사와 의무 이행의 기준이 된다","법률관계를 해석하는 기준이 된다","단순한 도덕적 권고일 뿐 위반해도 법적 책임은 없다"],"a":3,"c":"신의성실은 상대의 신뢰를 저버리지 않도록 성실하게 행동하라는 원칙으로, 자본시장법에도 명시되어 있어요.","e":"신의성실은 법적 의무이기도 하므로 위반하면 손해배상 등 법적 책임으로 이어질 수 있어요.","w":["윤리이자 법적 의무예요.","권리·의무의 기준이에요.","해석 기준이 돼요.",null],"k":"\"믿음을 저버리지 마라\"는 착한 마음가짐을 넘어 법으로 요구되는 의무예요.","m":"신의성실 = 윤리 + 법적 의무"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"설명 후 확인 방법","q":"판매업자가 일반금융소비자에게 중요사항을 설명한 뒤 이해했음을 확인받는 방법으로 가장 거리가 먼 것은?","o":["서명","기명날인","녹취","직원의 구두 진술만으로 확인한 것으로 처리"],"a":3,"c":"설명의무를 이행했다는 사실은 나중에 분쟁이 생겼을 때 증명할 수 있어야 해요.","e":"설명 후 소비자의 이해를 서명, 기명날인, 녹취 등으로 확인받아야 해요. 직원의 진술만으로는 확인이 되지 않아요.","w":["서명은 확인 방법이에요.","기명날인은 확인 방법이에요.","녹취는 확인 방법이에요.",null],"k":"\"설명 들었어요\"를 증거로 남겨야 해요. 직원 말만으로는 부족해요.","m":"설명 확인: 서명 · 기명날인 · 녹취 등"},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"t":"내부제보 제도","q":"금융투자회사의 내부제보 제도에 관한 설명으로 가장 적절하지 않은 것은?","o":["제보자의 신분은 비밀로 보장해야 한다","제보를 이유로 제보자에게 인사상 불이익을 주어서는 안 된다","회사에 중대한 영향을 주는 위법행위를 알고도 제보하지 않은 임직원에게 불이익을 줄 수 있다","제보는 반드시 실명으로만 해야 하며 익명 제보는 받을 수 없다"],"a":3,"c":"내부제보 제도는 회사 안의 위법·부당행위를 조기에 발견하기 위한 장치예요.","e":"제보 방법은 회사 기준에 따르며, 제보자 보호를 위해 비밀 보장이 핵심이에요. 실명만 허용한다는 것은 제도 취지에 맞지 않아요.","w":["신분 비밀이 보장돼요.","불이익 금지가 원칙이에요.","미제보자 불이익 규정을 둘 수 있어요.",null],"k":"\"용기 내 알린 사람\"을 보호해야 제도가 살아요.","m":"내부제보: 비밀 보장 · 불이익 금지 · 미제보자 불이익 가능"},{"s":3,"sec":"직무윤리","star":2,"lv":"하","rev":0,"t":"보고의무","q":"금융투자업 종사자가 고객에게 업무 처리 결과를 지체 없이 알려야 하는 의무는?","o":["보고의무","공정한 처리 의무","이해상충 방지 의무","설명의무"],"a":0,"c":"고객은 자기 재산이 어떻게 처리되었는지 알 권리가 있어요.","e":"위임받은 업무를 처리한 뒤 그 결과를 고객에게 알리는 것이 보고의무예요. 고객이 요구하지 않아도 지체 없이 해야 해요.","w":[null,"공정한 처리 의무는 여러 고객을 차별 없이 공정하게 대하는 의무예요. 결과를 알리는 의무와는 달라요.","고객과 이해가 충돌하는 거래를 막는 의무예요.","설명의무는 상품을 권유하거나 팔 때 중요한 내용을 설명하는 의무예요. 처리 결과를 알리는 의무와는 달라요."],"k":"심부름을 했으면 \"다 했어요\"라고 결과를 알려 줘야 해요.","m":"보고의무 = 처리 결과 지체 없이 통지","f":null},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"영업관리자의 자격과 운영","q":"P증권은 부산지점에 영업점별 영업관리자를 두려 한다. 표준내부통제기준상 옳지 않은 설명은?","o":["영업점장이 아닌 책임자급 직원 가운데에서 지정한다","그 영업점 근무 경력이 1년 이상이거나, 준법감시·감사 업무 경력이 1년 이상이어야 한다","임기를 1년 이상으로 정하고, 그 영업점에서 상근하게 한다","준법감시인은 영업관리자에게 법규·윤리 교육을 2년에 1회 이상 실시하면 된다"],"a":3,"c":"영업관리자는 영업점 안에서 준법감시 업무를 대신 맡는 사람이에요. 그래서 경력·상근·임기 요건을 두고, 교육과 보상으로 역할을 뒷받침해요.","e":"준법감시인은 해마다 한 번 이상 영업관리자에게 법규·윤리 교육을 해야 해요. 2년에 한 번으로는 부족해요. 회사는 업무 수행 결과에 따라 영업관리자에게 보상을 줄 수 있고, 준법감시 업무를 했다는 이유로 불이익을 주면 안 돼요.","w":["맞는 설명이에요. 영업점장이 아닌 책임자급에서 지정하는 것이 원칙이에요.","맞는 설명이에요. 영업점 근무 1년 이상 또는 준법감시·감사업무 1년 이상 경력이 요건이에요.","맞는 설명이에요. 임기는 1년 이상이고 해당 영업점에 상근해야 해요.",null],"k":"영업관리자는 지점에 파견된 '작은 준법감시인'이에요. 현장을 잘 알아야 하니 경력과 상근이 필요하고, 해마다 교육으로 감각을 새로 다듬어요.","m":"\"영업관리자: 책임자급 · 경력 1년↑ · 상근 · 임기 1년↑ · 교육 연 1회↑\"","rev":0},{"s":3,"sec":"직무윤리","star":3,"lv":"중","t":"준법감시인의 선임 대상과 보고","q":"Q증권이 새 준법감시인을 뽑으려 한다. 금융회사 지배구조법령상 가장 적절하지 않은 것은? (Q증권은 직원 중에서 준법감시인을 뽑을 수 있는 예외 회사가 아니다)","o":["사내이사나 업무집행책임자 가운데에서 선임해야 한다","선임했다면 7영업일 안에 금융위원회에 그 사실을 보고한다","해임할 때는 이사 총수의 3분의 2 이상이 찬성해야 한다","주주총회 보통결의로 선임하고, 임기는 1년 이상이면 된다"],"a":3,"c":"준법감시인은 회사 안에서 법규 준수를 감시하는 사람이에요. 지위가 흔들리지 않도록 뽑는 대상, 임면 절차, 임기, 보고를 법으로 정해 두었어요.","e":"준법감시인은 이사회 의결로 임면하고, 임기는 2년 이상이어야 해요. 주주총회 결의도, 1년 임기도 틀렸어요. 직원 중에서 뽑을 수 있는 예외 회사라도 기간제·단시간 근로자는 준법감시인이 될 수 없어요.","w":["맞는 설명이에요. 원칙적으로 사내이사나 업무집행책임자 가운데에서 뽑아요.","맞는 설명이에요. 임면한 날부터 7영업일 안에 금융위원회에 알려야 해요.","맞는 설명이에요. 해임은 일반 의결보다 요건이 무거워요.",null],"k":"준법감시인은 경기장의 주심이에요. 높은 자리에서 뽑고, 바꿀 때는 이사회가 무겁게 결정하고, 바꾼 사실은 감독기관에 바로 알려요.","m":"\"준법감시인: 사내이사·업무집행책임자 중 · 이사회 의결 · 해임 3분의 2 · 임기 2년↑ · 보고 7영업일\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"분쟁조정과 소송의 관계","q":"일반금융소비자 박씨가 펀드 손실 1,500만원에 대해 금융감독원에 분쟁조정을 신청했다. 이에 대한 금융소비자보호법상 설명 중 틀린 것은?","o":["판매회사는 조정안이 제시되기 전까지 이 사건으로 소송을 제기할 수 없다","같은 사건이 소송으로 가면 법원은 조정이 끝날 때까지 재판을 멈출 수 있다","법원이 소송절차를 중지하지 않더라도 조정위원회는 조정을 끝까지 진행해야 한다","두 당사자가 조정안을 받아들여 조정이 성립하면 재판상 화해와 같은 효력이 있다"],"a":2,"c":"분쟁조정은 소송보다 빠르고 싸게 다툼을 푸는 제도예요. 소송과 겹치면 한쪽을 멈추고, 소액 사건은 금융회사가 소송으로 빠져나가지 못하게 막아요.","e":"소송이 걸렸는데 법원이 소송을 멈추지 않으면, 이번에는 조정위원회 쪽이 조정절차를 멈춰야 해요. 두 절차의 결론이 엇갈리는 것을 막기 위해서예요.","w":["맞는 설명이에요. 일반금융소비자가 낸 2천만원 이내의 소액분쟁은 조정안이 나오기 전까지 금융회사가 소송을 걸 수 없어요.","맞는 설명이에요. 법원은 조정이 끝날 때까지 소송절차를 중지할 수 있어요.",null,"맞는 설명이에요. 조정이 성립하면 재판상 화해와 같은 효력이 있어요."],"k":"같은 다툼을 두 심판이 동시에 보면 판정이 엇갈릴 수 있어요. 그래서 법원이 안 멈추면 조정 쪽이 멈추는 거예요.","m":"\"법원 중지 가능 · 안 멈추면 조정 중지 · 2천만원 이내 소액은 금융회사 소 제기 금지\"","rev":0},{"s":3,"sec":"직무윤리","star":3,"lv":"상","t":"판매 이후 소비자 권리의 기한","q":"금융소비자보호법상 투자성 상품 판매 이후 단계의 제도에 관한 〈보기〉의 설명 중 옳은 것만 모두 고른 것은?\n\n〈보기〉\nㄱ. 청약이 철회되면 판매업자는 접수일부터 3영업일 안에 받은 돈을 돌려줘야 한다.\nㄴ. 판매업자는 청약 철회를 이유로 소비자에게 위약금을 물릴 수 있다.\nㄷ. 자료 열람 요구를 받은 판매업자는 6영업일 안에 열람할 수 있게 해야 한다.\nㄹ. 위법계약 해지를 요구받은 판매업자는 30일 이내에 수락 여부를 알리면 된다.\nㅁ. 청약 철회는 철회 의사를 적은 서면 등을 보낸 때에 효력이 생긴다.","o":["ㄱ, ㄷ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㅁ","ㄱ, ㄷ, ㄹ, ㅁ"],"a":1,"c":"금융상품을 산 뒤에도 소비자는 철회, 자료 열람, 위법계약 해지 같은 권리를 가져요. 판매업자가 미루지 못하게 절차마다 기한을 정해 뒀어요.","e":"ㄱ·ㄷ·ㅁ이 옳아요. 철회를 이유로 위약금이나 손해배상을 청구할 수 없고(ㄴ), 위법계약 해지 요구에는 10일 이내에 수락 여부를 알려야 해요(ㄹ).","w":["ㅁ도 옳아요. 투자성 상품의 철회는 서면 등을 발송한 때 효력이 생겨요.",null,"ㄴ은 틀렸어요. 철회를 이유로 위약금을 받을 수 없어요.","ㄹ은 틀렸어요. 수락 여부 통지 기한은 30일이 아니라 10일이에요."],"k":"물건을 산 뒤 '반품·영수증 확인·환불 요구' 창구가 따로 있고, 창구마다 처리 마감 시간이 붙어 있는 셈이에요.","m":"\"철회 금전 반환 3영업일 · 자료 열람 6영업일 · 위법계약 해지 통지 10일\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"상","t":"거부 후 재권유와 불초청 권유 예외","q":"S증권 직원이 투자성 상품을 권유하는 상황이다. 금융소비자보호법령상 허용되지 않는 것은?","o":["고객이 권유를 거절한 지 1개월이 지난 뒤 같은 상품을 다시 권유했다","고객이 투자성 상품 권유를 거절하자 같은 날 보장성 상품을 권유했다","요청이 없던 일반금융소비자에게 미리 안내하고 동의를 받은 뒤 전화로 장외파생상품을 권유했다","요청은 없었지만 미리 안내하고 권유를 받겠다는 답을 들은 전문금융소비자에게 전화로 주가지수선물을 권유했다"],"a":2,"c":"소비자가 싫다고 했는데 계속 권유하거나, 부르지도 않았는데 위험한 상품을 권유하면 소비자 판단이 흐려져요. 그래서 재권유와 불초청 권유를 제한하되 예외를 정해 뒀어요.","e":"일반금융소비자에게는 사전 안내와 동의를 거쳐도 장외파생상품, 장내파생상품, 사모펀드, 고난도상품 같은 고위험 상품을 불초청 방식으로 권유할 수 없어요.","w":["허용돼요. 거부 의사를 밝힌 뒤 1개월이 지나면 같은 상품을 다시 권유할 수 있어요.","허용돼요. 거절한 것과 다른 유형의 상품을 권유하는 것은 재권유 금지에 걸리지 않아요.",null,"허용돼요. 전문금융소비자는 장외파생상품만 불초청 권유 예외에서 빠져요."],"k":"'괜찮아요'라고 한 손님에게 한 달은 같은 물건을 들이밀지 말고, 위험한 물건은 부르지 않은 손님에게 먼저 팔러 가지 말라는 거예요.","m":"\"거부 후 1개월 지나면 재권유 OK · 다른 유형 상품 OK · 일반소비자 고위험 불초청 X\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"비밀정보의 제공과 범위","q":"R증권 임직원이 비밀정보를 다루는 방법으로 가장 적절한 것은?","o":["고객의 매매거래내역이 전산에만 저장되어 있고 문서로 출력되지 않았다면 비밀정보가 아니다","비밀정보는 먼저 동료에게 건넨 뒤 나중에 준법감시인 승인을 받으면 된다","비밀정보는 업무상 꼭 알아야 할 사람에게만 준법감시인의 사전승인을 받아 제공한다","회사가 맡긴 업무를 위해서라도 비밀정보를 이용하는 것은 일절 금지된다"],"a":2,"c":"비밀정보는 한번 새면 되돌릴 수 없어요. 그래서 범위는 넓게 잡고, 주고받는 길은 좁게 열어 두어요.","e":"비밀정보는 업무상 필요성이 인정되는 사람에게만(Need to Know Rule) 준법감시인의 사전승인을 받아 제공해요. 비밀정보인지 애매한 정보도 준법감시인이 확인하기 전까지는 비밀정보로 다뤄요.","w":["기록 형태나 기록 여부와 관계없이 고객의 신상정보와 매매거래내역은 비밀정보예요.","승인은 제공하기 전에 받아야 해요. 사후승인으로는 안 돼요.",null,"금지되는 것은 회사 업무 목적 밖의 이용이에요. 업무 수행에 필요한 이용은 가능해요."],"k":"금고 열쇠는 꼭 필요한 사람만, 경비실(준법감시인) 허락을 먼저 받고 빌려 가는 것과 같아요.","m":"\"비밀정보: 기록 형태 무관 · 애매하면 비밀정보 · Need to Know · 준법감시인 '사전'승인\"","rev":0},{"s":3,"sec":"직무윤리","star":1,"lv":"중","t":"전자통신과 공중포럼 활동","q":"금융투자회사 직원 T의 전자통신·대외활동에 대한 설명 중 옳지 않은 것은?","o":["T가 집에서 개인 노트북으로 고객에게 보낸 업무 이메일도 내부통제기준의 적용을 받는다","T가 방송 출연 같은 대외활동을 하려면 원칙적으로 회사의 사전승인을 받아야 한다","T가 회사 공식 입장이 아닌 시장 전망을 밝힐 때는 개인 의견임을 분명히 해야 한다","사외 대화방은 사적 공간이므로 T가 특정 종목 전망을 올려도 회사 기준이 적용되지 않는다"],"a":3,"c":"인터넷과 메신저도 회사 밖 사람들을 만나는 통로예요. 그래서 이메일, 대화방, SNS에도 대외활동 기준이 그대로 적용돼요.","e":"회사 밖 대화방에 참여하는 것은 공중포럼 활동으로 봐서, 언론 인터뷰와 비슷한 수준의 윤리기준을 지켜야 해요. 사적인 공간이라고 기준이 사라지지 않아요.","w":["맞는 설명이에요. 고객과 주고받는 이메일은 사용 장소와 관계없이 내부통제기준과 관계법령을 따라야 해요.","맞는 설명이에요. 대외활동은 성격에 따라 소속 부점장·준법감시인·대표이사의 사전승인을 받아요.","맞는 설명이에요. 공식 견해가 아니면 사견임을 밝히고 표현할 수 있어요.",null],"k":"회사 배지를 떼고 들어간 단체 대화방이라도, 듣는 사람은 'OO증권 직원' 말로 받아들여요. 그래서 기자 앞에서 말하듯 조심해야 해요.","m":"\"이메일은 장소 불문 · 사외 대화방 = 공중포럼 = 언론 접촉 기준\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"상","t":"자기계약 금지의 예외","q":"투자매매업자 U증권이 투자자와의 거래에서 스스로 상대방이 되는 경우 중 자본시장법령상 자기계약 금지의 예외로 볼 수 없는 것은?","o":["증권시장의 경쟁매매에서 U증권의 자기 주문과 고객 주문이 우연히 체결된 경우","다자간매매체결회사(ATS)에서 체결된 매매","U증권이 판매한 집합투자증권을 투자자로부터 U증권이 사들이는 경우","장외에서 고객 주문을 중개하면서 그 상대방을 U증권 자신으로 정해 체결한 경우"],"a":3,"c":"자기계약은 중개인이 몰래 손님의 거래 상대가 되는 거예요. 손님에게 불리한 가격을 붙일 유인이 생기므로 원칙적으로 막고, 그럴 우려가 없는 경우만 풀어 줘요.","e":"같은 매매에서 고객 주문을 중개하면서 스스로 상대방이 되는 것이 바로 금지되는 자기계약이에요. 거래 상대방이 우연히 정해지는 장내시장 등만 예외예요.","w":["예외예요. 증권시장·파생상품시장을 통한 매매는 상대방이 우연히 정해져요.","예외예요. 다자간매매체결회사를 통한 매매도 시행령상 예외예요.","예외예요. 자기가 판 집합투자증권을 다시 사들이는 것은 시행령이 정한 예외예요.",null],"k":"중고거래를 대신 해 주겠다던 친구가 사실은 자기가 사 가는 셈이에요. 다만 공개 경매장에서 우연히 낙찰된 거라면 문제가 없어요.","m":"\"자기계약 예외: 장내시장 · 다자간매매체결회사 · 자기가 판 펀드 매수\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"금융위원회 조치의 불복 절차","q":"금융위원회가 금융투자업자에 하는 조치와 그 불복 절차에 관한 자본시장법상 설명으로 가장 적절한 것은?","o":["임원 해임요구는 청문을 거치지 않아도 되는 처분이다","금융투자업 인가 취소 처분에 불복하는 금융투자업자는 고지를 받은 날부터 30일 안에 금융위원회에 이의신청을 할 수 있다","금융위원회는 이의신청을 받은 날부터 90일 안에 결과를 통지해야 한다","이의신청 결과 통지 기간은 어떤 경우에도 늘릴 수 없다"],"a":1,"c":"무거운 처분은 하기 전에 청문으로 당사자 말을 듣고, 처분 뒤에는 이의신청으로 다시 다툴 길을 열어 둬요.","e":"인가 취소 같은 처분에 불복하면 고지를 받은 날부터 30일 안에 금융위원회에 이의신청을 할 수 있어요. 금융위원회는 신청을 받은 날부터 60일 안에 결과를 알려야 하고, 부득이한 사정이 있으면 30일 범위에서 한 차례 늘릴 수 있어요.","w":["임원 해임요구는 직원 면직요구, 인가·등록 취소와 함께 청문 대상이에요.",null,"결과 통지 기한은 90일이 아니라 60일이에요.","부득이한 사정이 있으면 30일 범위에서 한 차례 늘릴 수 있어요."],"k":"판정 전에 선수 해명을 듣고(청문), 판정 뒤에도 30일 안에 이의를 걸 수 있는 비디오 판독 제도예요.","m":"\"청문: 인가·등록 취소 · 임원 해임요구 · 직원 면직요구 / 이의신청 30일 · 통지 60일(+30일 1회)\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"표준윤리준칙 항목의 분류","q":"금융투자회사 표준윤리준칙의 항목을 본인·회사·사회에 대한 윤리로 나눌 때 바르게 짝지은 것은?","o":["상호존중 – 사회에 대한 윤리","품위유지 – 회사에 대한 윤리","시장질서 존중 – 사회에 대한 윤리","주주가치 극대화 – 본인에 대한 윤리"],"a":2,"c":"표준윤리준칙은 고객우선, 신의성실 외에 윤리를 세 갈래로 나눠요. 본인(법규준수, 자기혁신, 품위유지, 사적 이익 추구 금지), 회사(정보보호, 상호존중, 공용재산의 사적 사용 금지, 경영진의 책임, 위반행위 보고, 대외활동, 고용계약이 끝난 뒤의 의무), 사회(시장질서 존중, 주주가치 극대화, 사회적 책임)예요.","e":"시장질서 존중은 주주가치 극대화, 사회적 책임과 함께 사회에 대한 윤리예요.","w":["상호존중은 회사에 대한 윤리예요.","품위유지는 법규준수·자기혁신·사적 이익 추구 금지와 함께 본인에 대한 윤리예요.",null,"주주가치 극대화는 사회에 대한 윤리예요."],"k":"'나를 다스리기 – 회사 지키기 – 세상에 보답하기' 세 칸 서랍에 항목을 넣는다고 생각하면 쉬워요.","m":"\"사회 = 시장질서·주주가치·사회적 책임 / 회사 = 정보보호·상호존중·경영진 책임\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"경영진 지도책임과 사용자책임의 범위","q":"V증권 준법감시부서가 신임 관리자 교육 자료에 넣을 문장을 검토하고 있다. 〈보기〉 중 옳은 것만 모두 고른 것은?\n\n〈보기〉\nㄱ. 지점장 같은 중간 관리자도 자기 지위와 보고 라인을 통해 부하 직원을 지도·지원할 책임이 있다.\nㄴ. 직원의 위법행위로 회사가 고객에게 배상했다면, 회사는 그 직원에게 배상액을 다시 청구할 수 없다.\nㄷ. 회사 전체의 위험관리 체계가 잘 돌아가는지 관리·감독하는 일은 소비자보호 총괄 임원(CCO)이 맡는 고유 업무다.\nㄹ. V증권의 위탁을 받아 일하는 투자권유대행인이 상품을 권하다가 고객에게 손해를 끼쳤다면 V증권도 배상 책임을 질 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ"],"a":1,"c":"직원 잘못에 대해 회사는 사용자책임을 지고, 관리자는 자리에 맞는 지도·지원 책임을 져요. 내부통제 책임자마다 맡는 영역도 따로 정해져 있어요.","e":"ㄱ·ㄹ이 옳아요. 지도·지원 책임은 최고경영진뿐 아니라 중간책임자에게도 있어요. 투자권유대행인은 직원이 아닌 개인사업자지만 금융소비자보호법은 그를 판매대리·중개업자로 보아, 일을 맡긴 직접판매업자도 배상 책임을 질 수 있게 해요. 사용자책임은 직원의 행위가 업무 집행과 관련될 때 성립하고, 배상한 회사는 그 직원에게 구상권을 행사할 수 있어요.","w":["ㄴ은 틀렸어요. 회사는 피해자에게 배상한 뒤 잘못한 직원에게 구상권을 행사할 수 있어요.",null,"둘 다 틀렸어요. 구상권은 행사할 수 있고, 회사 전체 위험관리 감독은 위험관리책임자의 일이에요.","ㄷ은 틀렸어요. CCO는 소비자보호 절차·기준 마련, 상품 개발·판매·사후관리 단계의 소비자보호, 민원 처리 감독, 민원발생부서 평가를 맡아요. 회사 전체 위험관리는 위험관리책임자 몫이에요."],"k":"축구 선수가 반칙해서 구단이 벌금을 냈다면 구단은 그 선수에게 물어내라고 할 수 있어요. 주장도 감독과 함께 후배를 이끌 책임이 있고요.","m":"\"지도책임은 중간관리자도 · 사용자 배상 후 구상권 O · 회사 전체 위험관리 = 위험관리책임자\"","rev":0},{"s":3,"sec":"직무윤리","star":2,"lv":"중","t":"철회 제외 사유와 통지·열람의 세부 기준","q":"일반금융소비자 한씨는 W증권과 거래하고 있다. 금융소비자보호법령과 자본시장법령에 따져 볼 때 틀린 것은?","o":["한씨가 분쟁조정을 준비하며 자료 사본을 우편으로 받겠다고 하면, W증권은 열람 수수료와 우송료를 한씨에게 청구할 수 있다","한씨의 자료 열람 요구가 W증권의 영업상 비밀을 크게 해칠 염려가 있으면 W증권은 열람을 제한할 수 있다","한씨가 매매명세 통지를 원하지 않는다고 밝히면, W증권은 지점에 비치하거나 홈페이지에서 수시로 조회할 수 있게 하는 방법으로 통지를 대신할 수 있다","철회 대상인 투자성 상품이라면, 한씨가 철회기간 안에 맡긴 돈을 곧바로 운용하는 데 동의했더라도 청약을 철회할 수 있다"],"a":3,"c":"판매 이후 소비자 권리에도 세부 조건이 있어요. 철회권은 돈을 바로 굴리는 데 동의하면 사라지고, 자료 열람은 비용을 청구하거나 정해진 사유로 제한할 수 있어요.","e":"철회 대상인 고난도 상품 등이라도, 일반금융소비자가 맡긴 돈을 바로 굴리는 데 동의했다면 철회 대상에서 빠져요. 운용이 이미 시작돼 되돌리기 어렵기 때문이에요. 참고로 철회기간은 원칙적으로 7일이지만, 더 긴 기간을 약정했다면 그 기간을 따라요.","w":["맞아요. 판매업자는 열람 수수료와, 사본을 우편으로 받는 경우의 우송료를 소비자에게 청구할 수 있어요.","맞아요. 영업비밀의 현저한 침해 우려, 다른 사람 이익의 부당한 침해 우려 등은 열람 제한 사유예요. 열람 목적은 분쟁조정·소송 같은 권리구제예요.","맞아요. 투자자가 통지를 원하지 않으면 영업점 비치나 인터넷 조회로 매매명세 통지를 갈음할 수 있어요.",null],"k":"주문한 음식을 '바로 만들어 주세요'라고 했다면 조리가 시작된 뒤에는 취소가 어려운 것과 같아요.","m":"\"즉시 운용 동의 → 철회 X · 열람 수수료·우송료 청구 O · 통지 원치 않으면 비치·인터넷\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","lv":"하","t":"투자자예탁금 별도예치","q":"자본시장법상 투자매매업자·투자중개업자의 투자자예탁금에 관한 설명으로 가장 적절하지 않은 것은?","o":["회사가 파산하면 예치기관은 예치금을 투자자에게 우선 지급해야 한다","회사는 투자자예탁금을 고유재산과 합쳐 운용하여 수익을 낼 수 있다","예치된 투자자예탁금은 원칙적으로 누구도 상계하거나 압류할 수 없다","투자자예탁금은 고유재산과 구분하여 증권금융회사에 예치하거나 신탁업자에 신탁해야 한다"],"a":1,"k":"고객이 주식 사려고 맡긴 돈을 회사 돈과 한 통장에 섞으면, 회사가 망할 때 같이 날아가요. 그래서 따로 떼어 안전한 곳에 맡겨 둬요.","m":"\"고객 돈은 따로(증권금융), 압류 ✕, 파산 땐 고객 먼저\"","c":"투자자예탁금은 고객이 매매를 위해 맡긴 돈이에요. 회사가 망해도 고객 돈을 지키기 위해 별도로 예치하게 해요.","e":"투자자예탁금은 고유재산과 구분해서 예치해야 해요. 회사가 자기 돈처럼 섞어서 운용하는 것은 허용되지 않아요.","w":["맞는 설명이에요. 파산 시 고객이 먼저 돌려받아요.",null,"맞는 설명이에요. 고객 돈을 지키기 위한 장치예요.","맞는 설명이에요. 별도예치가 핵심이에요."],"star":3,"rev":0},{"s":3,"sec":"자본시장 관련 법규","lv":"상","t":"공모 집합투자기구의 운용 제한","q":"자본시장법상 공모 집합투자기구의 집합투자재산 운용에 관한 설명으로 옳은 것은 모두 몇 개인가? (예외는 고려하지 않는다)\n\n〈보기〉\nㄱ. 동일종목 증권에는 각 집합투자기구 자산총액의 10%를 초과하여 투자할 수 없다.\nㄴ. 국채에는 각 집합투자기구 자산총액의 100%까지 투자할 수 있다.\nㄷ. 각 집합투자기구는 동일법인이 발행한 지분증권 총수의 10%를 초과하여 투자할 수 없다.\nㄹ. 집합투자재산으로 금전을 차입하는 것은 원칙적으로 허용된다.\nㅁ. 집합투자재산 중 금전을 타인에게 대여하는 것은 원칙적으로 금지된다.","o":["2개","3개","4개","5개"],"a":2,"k":"펀드가 한 종목에 몰빵하거나 빚을 내서 투자하면 위험하죠. 그래서 '한 종목은 10%까지, 빚내기와 돈 빌려주기는 원칙적으로 금지'라는 울타리를 쳐 둬요.","m":"\"한 종목 10% · 국채 100% · 지분 10% · 차입 ✕ · 대여 ✕\"","c":"공모펀드는 일반투자자 돈을 모은 것이라 분산투자와 안정성을 위해 투자 한도와 차입·대여 제한을 둬요.","e":"ㄱ·ㄴ·ㄷ·ㅁ이 옳아요. 집합투자재산으로 금전을 차입하는 것은 원칙적으로 금지되고, 대량 환매 같은 예외적인 경우에만 일정 한도 안에서 허용돼요.","w":["옳은 것을 너무 적게 센 값이에요.","ㄴ(국채 100%)이나 ㅁ을 빠뜨린 값이에요.",null,"ㄹ까지 포함한 값이에요. 차입은 원칙 금지예요."],"star":3,"rev":0},{"s":3,"sec":"자본시장 관련 법규","lv":"중","t":"순자본비율과 적기시정조치","q":"금융투자업자 B사의 재무 현황이 다음과 같을 때, 순자본비율과 이에 따른 적기시정조치로 가장 적절한 것은?\n\n〈자료〉\n• 영업용순자본: 1,200억원\n• 총위험액: 900억원\n• 필요유지자기자본: 500억원","o":["60% — 경영개선권고","60% — 경영개선요구","75% — 경영개선권고","240% — 조치 대상 아님"],"a":0,"k":"회사 체력(순자본비율)을 재서 100% 아래면 '주의', 50% 아래면 '치료하세요', 0% 아래면 '강제 치료'예요.","m":"\"(영업용순자본 − 총위험액) ÷ 필요유지자기자본, 100·50·0\"","c":"순자본비율은 위험을 빼고 남은 자본이 꼭 있어야 할 자본의 몇 %인지 보여 줘요. 100% 미만이면 권고, 50% 미만이면 요구, 0% 미만이면 명령이에요.","e":"(1,200 − 900) ÷ 500 × 100 = 60%예요. 50% 이상 100% 미만 구간이라 경영개선권고 대상이에요.","w":[null,"60%는 50% 이상이라 요구가 아니라 권고 구간이에요.","총위험액을 영업용순자본으로 나눈 값(900 ÷ 1,200 = 75%)이에요. 공식은 (영업용순자본 − 총위험액) ÷ 필요유지자기자본이에요.","총위험액을 빼지 않고 영업용순자본만 나눈 값이에요."],"f":"순자본비율 = (1,200 − 900) ÷ 500 × 100 = 60%","star":3,"rev":0},{"s":3,"sec":"자본시장 관련 법규","lv":"중","t":"미공개중요정보 이용 규제 대상","q":"자본시장법상 미공개중요정보 이용행위 금지 규정에서 내부자 또는 준내부자로 보기 어려운 자는?","o":["해당 법인의 현직 임원","해당 법인과 인수합병 계약을 교섭 중인 회사의 직원","해당 법인의 임원에서 물러난 지 2년이 지난 자","해당 법인에 대한 인허가 권한을 가진 공무원"],"a":2,"k":"회사 비밀을 알 수 있는 위치에 있는 사람은 그 정보로 주식을 사고팔면 안 돼요. 회사를 떠난 사람도 1년 동안은 똑같이 막아요. 2년이 지났다면 이 범위에서 벗어나요.","m":"\"내부자·준내부자·정보수령자, 퇴직 후 1년까지\"","c":"미공개중요정보 이용 규제 대상은 내부자(회사·임직원·주요주주), 준내부자(인허가권자·계약 체결 또는 교섭 중인 자 등), 정보수령자예요. 지위를 잃은 뒤 1년이 지나지 않은 자도 포함해요.","e":"내부자·준내부자 지위는 그 지위를 벗어난 뒤 1년까지 유지돼요. 물러난 지 2년이 지난 전직 임원은 내부자로 보기 어려워요.","w":["현직 임원은 대표적인 내부자예요.","계약 체결이나 교섭 중인 자는 준내부자예요.",null,"인허가권자는 준내부자예요."],"star":3,"rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"자본시장법상 증권의 분류","q":"자본시장법상 증권의 종류와 그 예를 연결한 것으로 가장 적절하지 않은 것은?","o":["「상법」상 합자회사의 출자지분 — 지분증권","공동사업에 투자하고 주로 타인이 수행한 사업의 손익을 받는 계약상 권리 — 지분증권","신탁의 수익권이 표시된 것 — 수익증권","주가연계증권(ELS) — 파생결합증권"],"a":1,"c":"자본시장법은 증권을 채무증권, 지분증권, 수익증권, 투자계약증권, 파생결합증권, 증권예탁증권 6가지로 나눠요.","e":"남이 하는 공동사업에 돈을 넣고 그 손익을 받는 권리는 투자계약증권이에요. 지분증권이 아니에요.","w":["합자회사·유한책임회사·유한회사·합자조합·익명조합의 출자지분은 지분증권에 들어가요. (합명회사 지분은 빠져요)",null,"신탁 수익권이 표시된 것은 수익증권이 맞아요.","ELS는 기초자산에 연계돼도 원금 이상 손실이 없는 구조라 파생상품이 아니라 파생결합증권(증권)이에요."],"k":"친구 가게에 돈만 대고 장사는 친구가 하면서 이익을 나눠 받는 권리, 이게 투자계약증권이에요. 내가 회사 주인이 되는 지분과는 달라요.","m":"남의 사업 손익 받기 = 투자계약증권 · 신탁 = 수익증권","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","t":"MMF 운용 제한","q":"집합투자재산이 6,000억원이고 보유 증권 총액이 5,000억원인 단기금융집합투자기구(MMF)가 있다. 이 MMF가 (ㄱ) 남은 만기 1년 이상인 국채증권에 운용할 수 있는 최대 금액과 (ㄴ) 환매조건부매도로 조달할 수 있는 최대 금액을 순서대로 짝지은 것은?","o":["300억원 — 2,500억원","300억원 — 250억원","600억원 — 250억원","600억원 — 2,500억원"],"a":1,"c":"MMF는 언제든 돈을 돌려줄 수 있어야 해서, 만기가 긴 자산과 빚(환매조건부매도)을 아주 적게만 허용해요. 두 한도 모두 5%예요.","e":"(ㄱ) 남은 만기 1년 이상 국채는 집합투자재산의 5% 이내: 6,000억 × 5% = 300억원. (ㄴ) 환매조건부매도는 보유 증권 총액의 5% 이내: 5,000억 × 5% = 250억원.","f":"국채(만기 1년↑) 한도 = 집합투자재산 × 5% · 환매조건부매도 한도 = 보유 증권 총액 × 5%","w":["(ㄴ)에 일반 펀드 기준 50%를 적용했어요.",null,"(ㄱ)을 10%로 계산했어요.","두 값 모두 한도를 크게 잡았어요. 50%는 일반 펀드의 환매조건부매도 한도예요."],"k":"MMF는 \"통장처럼 바로 꺼내 쓰는 펀드\"라서, 오래 묶이는 자산이나 빌린 돈은 5%만 허용해요.","m":"MMF는 둘 다 5% (일반펀드 레포는 50%)","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"공모펀드의 금전 차입·대여","q":"자본시장법상 일반 공모 집합투자기구(부동산 집합투자기구 제외)의 금전 차입과 대여에 관한 설명으로 가장 적절하지 않은 것은?","o":["집합투자기구의 계산으로 금전을 빌리는 것은 원칙적으로 금지된다","대량 환매 청구 등 예외적인 경우에는 차입 당시 순자산총액의 10% 이내에서 빌릴 수 있다","빌린 돈을 모두 갚기 전에는 투자대상자산을 새로 취득할 수 없다","집합투자재산 중 금전은 상대방 제한 없이 자유롭게 대여할 수 있다"],"a":3,"c":"펀드는 투자자 돈으로 운용하는 것이라 빌리거나 빌려주는 것을 원칙적으로 막아요. 예외도 아주 좁게만 허용해요.","e":"금전 대여도 원칙적으로 금지돼요. 금융기관 등에 대한 30일 이내 단기대출처럼 정해진 예외만 허용돼요.","w":["차입은 원칙적으로 금지예요.","대량 환매 등 예외에는 순자산총액 10% 이내 차입이 가능해요.","차입금을 갚기 전에는 신규 취득이 제한돼요.",null],"k":"남의 돈(투자자 돈)을 맡은 사람이 마음대로 빌리고 빌려주면 위험하겠죠? 급할 때 조금(10%)만 빌릴 수 있어요.","m":"펀드 차입: 원칙 금지 · 예외 순자산 10% · 대여도 원칙 금지","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","rev":0,"t":"투자신탁의 수익자총회","q":"공모 투자신탁의 수익자총회 제도에 대한 자본시장법상 설명 중 가장 적절한 것은?","o":["법에서 정한 결의사항은 출석 수익자 의결권의 과반수와 발행 총좌수의 3분의 1 이상으로 결의한다","수익자총회는 수익자만 소집할 수 있다","발행된 수익증권 총좌수의 5% 이상을 가진 수익자는 수익자총회 소집을 요구할 수 있다","연기된 수익자총회도 원래 수익자총회와 결의 요건이 같다"],"a":2,"c":"수익자총회는 투자신탁의 중요한 사항을 수익자들이 정하는 자리예요. 원칙적으로 집합투자업자가 소집하고, 신탁업자나 일정 지분 이상의 수익자가 소집을 요구할 수 있어요.","e":"발행 총좌수의 5% 이상을 보유한 수익자는 집합투자업자에게 수익자총회 소집을 요구할 수 있어요.","w":["법정 결의사항은 출석 과반수와 총좌수 4분의 1 이상이에요.","소집권자는 집합투자업자이고, 신탁업자와 5% 이상 수익자는 소집을 요구할 수 있어요.",null,"연기 수익자총회는 요건이 완화돼요(법정 사항은 총좌수 8분의 1 이상)."],"k":"아파트 입주자 회의처럼 \"5% 이상 모이면 회의 열자고 요구\"할 수 있어요. 사람이 안 모이면 다음 회의는 문턱을 낮춰 줘요.","m":"수익자총회: 소집요구 5% · 결의 과반수+1/4 · 연기총회 1/8"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"하","rev":0,"t":"집합투자기구의 이익금 분배","q":"자본시장법상 집합투자기구의 이익금 분배에 관한 설명으로 가장 거리가 먼 것은?","o":["현금 대신 새로 발행한 집합투자증권을 나눠 줄 수도 있다","집합투자규약에서 정하면 이익금을 초과하여 분배할 수 있다","분배 방법은 집합투자업자가 결산 때마다 정하면 되고 집합투자규약에 정할 필요는 없다","집합투자규약에서 정하면 이익금 분배를 유보할 수 있으나 MMF는 유보할 수 없다"],"a":2,"c":"이익금 분배는 투자자의 이해에 직결돼서, 분배 방식·유보·초과분배를 모두 집합투자규약에 미리 정해 두어야 해요.","e":"분배 방법과 시기는 집합투자규약에서 정해야 해요. 집합투자업자가 결산 때마다 임의로 정할 수 없어요.","w":["금전이나 새로 발행하는 집합투자증권으로 분배할 수 있어요.","규약에 정하면 초과 분배도 가능해요.",null,"규약에 정하면 유보 가능하고, MMF는 유보할 수 없어요."],"k":"이익을 어떻게 나눌지는 \"게임 규칙(규약)\"에 미리 적어 둬야 해요. 그때그때 운용사 마음대로 바꾸면 안 돼요.","m":"이익금: 금전 또는 새 증권 · 유보·초과분배는 규약에 · MMF 유보 X"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"매매명세의 통지","q":"자본시장법상 투자매매업자·투자중개업자의 매매명세 통지에 관한 설명으로 가장 적절하지 않은 것은?","o":["반기 동안 매매가 없으면 반기 말 잔액 등을 반기 종료 후 20일까지 통지해야 한다","통지는 우편 서면으로만 해야 하고 전자우편이나 문자메시지는 허용되지 않는다","월간 매매내역·손익내역·잔액현황 등은 다음 달 20일까지 통지해야 한다","주문이 체결되면 곧바로 거래 종류·종목·수량·체결가·수수료 등을 알려야 한다"],"a":1,"c":"매매명세 통지는 투자자가 자기 계좌에서 무슨 일이 있었는지 확인할 수 있게 하는 제도예요. 체결 즉시, 매월, 반기 단위로 알려 줘요.","e":"통지는 투자자와 미리 합의한 방법으로 하면 돼요. 서면 외에 전자우편, 문자메시지 등도 쓸 수 있어요.","w":["매매가 없으면 반기 말 기준으로 20일까지 알려요.",null,"월간 내역은 다음 달 20일까지예요.","체결 즉시 지체 없이 통지해요."],"k":"은행 문자 알림처럼 \"언제, 무엇을, 얼마에\" 거래됐는지 바로 알려 주는 거예요. 꼭 종이 편지일 필요는 없어요.","m":"매매명세: 체결 즉시 · 월간은 다음 달 20일 · 반기 무거래도 20일"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"공공적 법인의 주식 소유 제한","q":"자본시장법상 공공적 법인의 주식 소유 제한에 관한 설명으로 가장 적절하지 않은 것은?","o":["공공적 법인이 상장될 당시 발행주식 총수의 10% 이상을 가진 주주는 그 비율까지 소유할 수 있다","그 밖의 자는 발행주식 총수의 3%를 넘게 소유할 수 없다","금융위원회의 승인을 받으면 기준을 넘어 소유할 수 있다","기준을 넘어 취득한 주식이라도 의결권은 정상적으로 행사할 수 있다"],"a":3,"c":"공공적 법인은 국민 경제에 중요한 회사라서 특정인이 지배하지 못하도록 주식 소유를 제한해요.","e":"기준을 넘은 주식은 의결권을 행사할 수 없고, 금융위원회는 6개월 이내의 기간을 정해 소유 기준을 충족하도록 시정을 명할 수 있어요.","w":["상장 당시 10% 이상 주주는 그 비율까지 소유할 수 있어요.","그 밖의 자는 3%가 한도예요.","금융위 승인을 받으면 초과 소유가 가능해요.",null],"k":"전기·통신처럼 모두가 쓰는 회사를 한 사람이 쥐락펴락하지 못하게 \"3%까지만\"으로 막아 둔 거예요.","m":"공공적 법인: 상장 당시 10%↑ 주주는 그 비율 · 그 외 3% · 초과분 의결권 X"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"하","rev":0,"t":"금융투자상품의 범위","q":"자본시장법상 금융투자상품에서 제외되는 것으로 가장 거리가 먼 것은?","o":["주식매수선택권","파생결합증권","원화로 표시된 양도성예금증서","관리형신탁의 수익권"],"a":1,"c":"금융투자상품은 원본 손실 가능성(투자성)이 있는 상품이에요. 다만 투자성이 있어도 정책적으로 제외하는 몇 가지가 있어요.","e":"파생결합증권은 증권의 한 종류로 금융투자상품에 포함돼요. 원화 CD, 관리형신탁의 수익권, 주식매수선택권은 금융투자상품에서 명시적으로 제외돼요.","w":["주식매수선택권은 임직원 보상 수단이라 제외돼요.",null,"원화 표시 CD는 만기가 짧고 유통이 예금처럼 이뤄져 제외돼요.","관리형신탁 수익권은 제외돼요."],"k":"\"손해 볼 수 있는 투자 상품\"이 기본이지만, 예금 같은 CD나 회사가 직원에게 주는 스톡옵션은 빼 주는 거예요.","m":"금투상품 제외 3총사: 원화 CD · 관리형신탁 수익권 · 주식매수선택권"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"집합투자재산의 평가","q":"집합투자업자가 펀드 기준가격을 정하기 위해 집합투자재산을 평가하는 방법에 대한 설명 중 가장 적절하지 않은 것은?","o":["집합투자재산은 원칙적으로 시가로 평가한다","신뢰할 만한 시가가 없으면 공정가액으로 평가한다","MMF는 장부가격으로 평가할 수 있다","집합투자업자는 평가의 일관성을 위해 집합투자재산평가위원회를 둘 필요가 없다"],"a":3,"c":"펀드 기준가격은 집합투자재산 평가에서 나와요. 그래서 평가 원칙(시가 → 공정가액)과 이를 관리하는 조직을 법으로 정해요.","e":"집합투자업자는 집합투자재산평가위원회를 구성·운영해 공정하고 일관되게 평가해야 해요.","w":["시가 평가가 원칙이에요.","시가가 없으면 공정가액으로 평가해요.","MMF는 장부가 평가가 허용돼요.",null],"k":"펀드 가격표를 매기는 일이라, 시장 가격이 있으면 그걸 쓰고 없으면 위원회가 공정하게 정해요.","m":"평가: 시가 → 없으면 공정가액 · MMF 장부가 · 평가위원회 필수"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"하","rev":0,"t":"증권과 파생상품의 구분 기준","q":"자본시장법상 금융투자상품의 구분에 관한 설명으로 가장 적절하지 않은 것은?","o":["원본손실가능성(투자성)이 있으면 금융투자상품이다","원본을 초과하는 손실 가능성이 있으면 파생상품, 없으면 증권으로 나눈다","은행 예금은 원본손실가능성이 없어 금융투자상품이 아니다","원본을 초과하는 손실 가능성이 있어야 비로소 금융투자상품이 된다"],"a":3,"c":"자본시장법은 두 단계로 나눠요. 1단계: 원본손실가능성이 있으면 금융투자상품. 2단계: 원본을 넘는 손실이 가능하면 파생상품, 아니면 증권.","e":"금융투자상품인지 가르는 기준은 원본손실가능성(투자성)이에요. 원본초과손실 가능성은 그다음 단계에서 증권과 파생상품을 나누는 기준이에요.","w":["투자성이 금융투자상품의 기준이에요.","원본초과손실 여부로 증권과 파생상품을 나눠요.","예금은 투자성이 없어 제외돼요.",null],"k":"1층 문(투자성)을 통과하면 금융투자상품, 2층 문(원금 넘게 잃을 수 있나)에서 증권과 파생으로 갈라져요.","m":"투자성 → 금투상품 / 원본초과손실 → 파생, 아니면 증권"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"집합투자의 요건","q":"자본시장법상 집합투자에 해당하기 위한 요건으로 가장 거리가 먼 것은?","o":["2인 이상의 투자자로부터 모은 금전등일 것","투자자로부터 일상적인 운용지시를 받지 않을 것","운용 결과를 투자자에게 배분하여 귀속시킬 것","투자자가 50인 이상일 것"],"a":3,"c":"집합투자는 여러 사람 돈을 모아(2인 이상), 전문가가 알아서 굴리고(일상적 운용지시 없음), 결과를 나눠 주는(배분·귀속) 구조예요.","e":"인원 요건은 2인 이상이에요. 50인은 공모와 사모를 가르는 기준이지 집합투자의 요건이 아니에요.","w":["2인 이상이면 충족돼요.","일상적 운용지시가 없어야 해요.","결과를 배분·귀속시켜야 해요.",null],"k":"\"둘 이상 모아서, 맡겨서, 나눠 받기\"가 집합투자예요. 50명은 공모 여부를 따질 때 쓰는 숫자예요.","m":"집합투자: 2인 이상 · 운용지시 X · 배분 귀속"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"집합투자기구 형태와 발행 증권","q":"투자자가 펀드에 가입하면 받는 증권의 종류는 펀드의 법적 형태에 따라 달라진다. 형태와 증권을 짝지은 것 중 맞는 것은?","o":["신탁형 펀드 – 수익증권","회사형(주식회사) 펀드 – 출자지분","합자조합형 펀드 – 수익증권","유한회사형 펀드 – 주식"],"a":0,"c":"집합투자기구는 신탁형, 회사형, 조합형으로 나뉘고, 형태마다 발행하는 증권이 달라요.","e":"수익증권을 발행하는 것은 신탁형인 투자신탁뿐이에요. 투자회사는 주식, 투자유한회사·투자합자회사·조합형은 출자지분을 발행해요.","w":[null,"투자회사는 주식을 발행해요.","조합형은 출자지분을 발행해요.","투자유한회사는 출자지분을 발행해요."],"k":"신탁은 \"수익권\", 주식회사는 \"주식\", 나머지 회사·조합은 \"지분\"이라고 연결하면 쉬워요.","m":"신탁 = 수익증권 · 투자회사 = 주식 · 그 외 = 출자지분"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"집합투자기구 관계회사","q":"펀드 운용을 돕는 외부 회사들을 자본시장법은 \"집합투자기구 관계회사\"로 묶어 규율한다. 여기에 들지 않는 곳은?","o":["일반사무관리회사","집합투자기구평가회사","채권평가회사","신탁업자"],"a":3,"c":"집합투자기구 관계회사는 펀드 운영을 돕는 회사로, 일반사무관리회사·집합투자기구평가회사·채권평가회사 3종이에요.","e":"신탁업자는 집합투자재산을 보관·관리하는 필수 참여자이지만 관계회사 3종에는 들어가지 않아요.","w":["투자회사 운영업무를 맡는 관계회사예요.","펀드를 평가·공시하는 관계회사예요.","채권 등 가격을 평가하는 관계회사예요.",null],"k":"관계회사 3총사는 \"사무 보는 곳, 펀드 평가하는 곳, 채권 값 매기는 곳\"이에요. 돈을 보관하는 신탁업자는 따로예요.","m":"관계회사: 일반사무관리 · 펀드평가 · 채권평가"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"금융소비자보호법의 금융상품 유형","q":"금소법은 모든 금융상품을 몇 가지 성격으로 나눠 판매 규제를 적용한다. 그 구분에 없는 것은?","o":["예금처럼 원금을 맡기는 상품(예금성)","돈을 빌리는 상품(대출성)","사고에 대비하는 상품(보장성)","현금화가 쉬운 상품(유동성)"],"a":3,"c":"금융소비자보호법은 기능별 규제를 위해 금융상품을 예금성·대출성·투자성·보장성 4가지로 나눠요.","e":"유동성 상품이라는 유형은 없어요. 4유형은 예금성, 대출성, 투자성, 보장성이에요.","w":["예금성은 4유형 중 하나예요.","대출성은 4유형 중 하나예요.","보장성은 4유형 중 하나예요.",null],"k":"\"맡기고(예금), 빌리고(대출), 굴리고(투자), 대비하는(보장)\" 4가지예요.","m":"금소법 4유형: 예금 · 대출 · 투자 · 보장"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"하","rev":0,"t":"등록 대상 금융투자업","q":"자본시장법상 금융위원회의 인가가 아닌 등록만으로 영위할 수 있는 업무로 가장 적절한 것은?","o":["신탁업","투자일임업","집합투자업","투자매매업"],"a":1,"c":"고객 재산을 직접 맡거나 이해상충이 큰 업무는 인가, 상대적으로 위험이 낮은 업무는 등록으로 진입해요.","e":"투자일임업은 운용권한을 위임받지만 고객 자산을 보관하지 않아 등록 대상이에요. 등록 대상은 투자자문업·투자일임업·온라인소액투자중개업·일반사모집합투자업이에요.","w":["신탁업은 인가 대상이에요.",null,"집합투자업은 인가 대상이에요.","투자매매업은 인가 대상이에요."],"k":"돈을 직접 맡아 두지 않는 \"조언·대신 운용\" 업무는 등록만 하면 돼요.","m":"등록: 자문 · 일임 · 온라인소액중개 · 일반사모집합"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"금융기관 검사와 제재 절차","q":"금융감독원이 G증권을 검사한 뒤 제재를 하려 한다. 관련 규정에 비추어 가장 적절한 것은?","o":["검사는 그 종류에 따라 현장검사와 서면검사로 구분된다","제재 전에 G증권에 의견을 진술할 기회를 주어야 한다","G증권은 이의신청 결과가 마음에 들지 않으면 같은 제재에 다시 이의신청할 수 있다","G증권의 임직원 개인은 이의신청을 할 수 없다"],"a":1,"c":"검사는 종류(정기·수시)와 방법(현장·서면)을 구분해요. 제재는 불이익 처분이라 사전에 의견을 들을 기회를 줘야 해요.","e":"제재 전에는 상당한 기간을 정해 구술 또는 서면으로 의견을 진술할 기회를 줘야 해요.","w":["검사의 종류는 정기·수시이고, 현장·서면은 검사 방법이에요.",null,"이의신청은 같은 제재에 한 번만 할 수 있어요.","제재를 받은 임직원도 이의신청할 수 있어요."],"k":"벌을 주기 전에 \"할 말 있나요?\"라고 꼭 물어봐야 해요. 이의신청은 한 번뿐이에요.","m":"검사 종류 = 정기·수시 / 방법 = 현장·서면 · 이의신청 1회"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"증권분석기관","q":"기업공개 시 공모가격 산정을 위한 평가를 맡는 증권분석기관이 될 수 없는 자는?","o":["인수업무를 하는 투자매매업자","신용평가업자","회계법인","일반사무관리회사"],"a":3,"c":"증권분석기관은 공모가격 등을 평가하는 곳이라 전문성과 독립성이 필요해요.","e":"증권분석기관은 인수·주선 업무를 하는 투자매매·중개업자, 신용평가업자, 회계법인, 채권평가회사로 한정돼요. 일반사무관리회사는 펀드 운영업무를 하는 곳이에요.","w":["인수업무를 하는 투자매매업자는 될 수 있어요.","신용평가업자는 될 수 있어요.","회계법인은 될 수 있어요.",null],"k":"값을 매기는 일은 증권사·신평사·회계법인·채권평가사만 할 수 있어요.","m":"증권분석기관: 인수증권사 · 신평사 · 회계법인 · 채권평가사"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"임의매매의 처벌","q":"H증권 직원이 고객의 주문 없이 고객 계좌의 예탁금으로 주식을 사고팔았다. 이 행위의 명칭과 자본시장법상 처벌 수준을 짝지은 것으로 가장 적절한 것은?","o":["임의매매 – 징역 5년 이하 또는 벌금 2억원 이하","임의매매 – 징역 1년 이하 또는 벌금 3천만원 이하","일임매매 – 징역 5년 이하 또는 벌금 2억원 이하","일임매매 – 형사처벌 없음"],"a":0,"c":"투자자 주문 없이 그 재산으로 매매하는 것은 임의매매예요. 투자자가 미리 권한을 맡긴 일임매매와 구분해야 해요.","e":"주문 없이 매매한 것은 임의매매이고, 5년 이하의 징역 또는 2억원 이하의 벌금에 처해요.","w":[null,"법정형을 한 단계 낮게 붙였어요.","투자자가 권한을 위임하지 않았으므로 일임매매가 아니에요.","일임매매가 아니라 임의매매이고, 형사처벌 대상이에요."],"k":"내 허락 없이 내 돈으로 주식을 사고판 거예요. 무겁게 처벌해요.","m":"임의매매 = 주문 없이 매매 → 5년 / 2억"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"하","rev":0,"t":"투자신탁 수익증권의 발행","q":"T운용이 새 투자신탁을 만들고 투자자에게 수익증권을 발행하려 한다. 발행 방식에 대한 설명으로 맞는 것은?","o":["수익증권에는 1좌당 금액이 표시된다","수익증권은 무액면·기명식으로 발행된다","수익자는 보유 좌수와 관계없이 같은 몫을 받는다","수익증권은 반드시 실물로 발행해 교부해야 한다"],"a":1,"c":"수익증권은 투자신탁의 수익권을 나타내는 증권이에요. 좌수에 따라 권리가 균등하게 나뉘어요.","e":"수익증권은 무액면·기명식으로 발행되고, 실물이 아니라 전자등록 방식으로 발행돼요.","w":["무액면이라 1좌당 금액이 표시되지 않아요.",null,"보유 좌수에 비례해 권리를 가져요.","전자등록 방식으로 발행해요."],"k":"수익증권은 \"이름 적힌(기명), 금액 없는(무액면) 지분 기록\"이에요.","m":"수익증권: 무액면 · 기명식 · 전자등록 · 좌수 비례"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"조사결과에 따른 조치","q":"증권선물위원회 조사로 상장법인 T사의 위법행위가 확인되었다. 이때 T사에 대해 할 수 있는 조치가 아닌 것은?","o":["1년의 범위에서 증권 발행 제한","임원에 대한 해임권고","위법행위에 가담한 직원의 업무 정지","경고 또는 주의"],"a":2,"c":"조사 결과 위법행위가 확인되면 상장법인에 대해 정해진 조치를 할 수 있어요. 조치 목록에 없는 것은 할 수 없어요.","e":"상장법인에 대한 조치에는 증권 발행 제한(1년 이내), 임원 해임권고, 경고·주의 등이 있어요. 직원의 업무 정지는 열거돼 있지 않아요.","w":["1년 범위의 증권 발행 제한은 조치 대상이에요.","임원 해임권고는 할 수 있어요.",null,"경고·주의도 할 수 있어요."],"k":"회사에는 \"발행 제한, 임원 해임권고, 경고\"까지 할 수 있지만 직원 개인 업무정지는 목록에 없어요.","m":"상장법인 조치: 발행제한 1년 · 임원 해임권고 · 경고·주의"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"순자본비율 수시보고","q":"금융투자업규정상 1종 금융투자업자의 순자본비율 보고에 관한 설명으로 가장 적절하지 않은 것은?","o":["순자본비율은 최소한 일별로 산정해야 한다","순자본비율이 100%에 미달하면 지체 없이 보고해야 한다","산정 기초가 되는 금액은 연결 대상 종속회사가 있으면 연결재무제표 장부가액을 쓴다","이미 100%에 미달한 상태라면 그 뒤 영업용순자본이 10% 이상 줄어도 다음 정기보고 때까지 보고하지 않아도 된다"],"a":3,"c":"순자본비율은 정기적으로 보고하고, 비율이 나빠지는 상황에서는 즉시 알려 감독당국이 대응할 수 있게 해요.","e":"100%에 미달한 뒤에도 영업용순자본이 10% 이상 줄거나 총위험액이 10% 이상 늘면 지체 없이 보고해야 해요.","w":["맞는 설명이에요. 순자본비율은 최소한 매일 산정해요.","100% 미달 시 지체 없이 보고해요.","연결 대상 회사가 있으면 연결재무제표가 기초예요.",null],"k":"이미 아픈 환자가 더 나빠지면 다음 정기검진까지 기다리지 말고 바로 알려야 해요.","m":"100% 미달 후 순자본 10%↓·위험 10%↑ → 즉시 보고","f":null},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"긴급조치의 요건","q":"금융위원회가 금융투자업자에 대하여 투자자예탁금 지급정지 등 긴급조치를 할 수 있는 사유로 가장 거리가 먼 것은?","o":["발행한 어음이 부도나거나 당좌거래가 정지된 경우","유동성이 급격히 악화되어 투자자예탁금을 지급할 수 없는 경우","휴업이나 영업정지로 돌발적인 사태가 생긴 경우","순자본비율이 0% 미만으로 떨어진 경우"],"a":3,"c":"긴급조치는 지급결제가 실제로 막히는 돌발 상황에 대응하는 수단이에요. 재무비율 악화는 적기시정조치로 다뤄요.","e":"순자본비율 0% 미만은 적기시정조치(경영개선명령) 사유예요. 긴급조치 사유가 아니에요.","w":["어음 부도는 긴급조치 사유예요.","예탁금 지급불능은 긴급조치 사유예요.","휴업·영업정지 같은 돌발 사태도 사유예요.",null],"k":"\"지금 당장 돈이 안 나간다!\"가 긴급조치, \"체력(비율)이 나쁘다\"는 적기시정조치예요.","m":"긴급조치 = 부도·지급불능·돌발사태 / 비율 악화 = 적기시정"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"위험관리 체계","q":"금융투자업규정상 금융투자업자의 위험관리에 관한 설명으로 가장 적절하지 않은 것은?","o":["위험관리지침을 문서로 정해 두어야 한다","감내할 수 있는 위험 한도와 위험관리 기본방침은 주주총회에서 정한다","자회사를 포함해 위험을 종합적으로 관리해야 한다","위험관리를 위한 별도 조직을 두어야 한다"],"a":1,"c":"위험관리는 경영 판단의 핵심이라 이사회가 방침과 한도를 정하고, 별도 조직이 점검해요.","e":"위험 한도와 위험관리 기본방침은 이사회 의결사항이에요. 주주총회는 정관 변경, 이사 선임 등 회사법상 기본사항을 다뤄요.","w":["위험관리지침은 문서로 정해야 해요.",null,"자회사 위험도 함께 관리해요.","위험관리 전담 조직이 필요해요."],"k":"얼마나 위험을 감수할지는 회사 운전석에 있는 이사회가 정해요.","m":"위험 한도·기본방침 = 이사회 의결"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"금융위원회와 금융감독원","q":"금융위원회와 금융감독원에 관한 설명으로 가장 적절한 것은?","o":["금융위원회는 기획재정부 소속의 독임제 기관이다","금융감독원장의 임기는 5년이다","금융감독원은 금융기관의 업무와 재산 상황을 검사한다","증권선물위원회는 금융감독원 안에 설치된 내부 조직이다"],"a":2,"c":"금융위원회는 정책과 의결을, 금융감독원은 검사와 감독 실무를 맡아요. 증권선물위원회는 금융위원회 안에 있어요.","e":"금융감독원은 금융기관의 업무와 재산 상황을 모두 검사해요.","w":["금융위원회는 국무총리 소속 합의제 행정기관이에요.","금융감독원장 등의 임기는 3년이고 한 차례 연임할 수 있어요.",null,"증권선물위원회는 금융위원회에 설치돼요."],"k":"금융위 = 정책 결정(국무총리 소속 위원회), 금감원 = 현장 검사관이에요.","m":"금융위 = 국무총리 소속 합의제 · 금감원 = 검사 · 증선위 = 금융위 안"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"매출의 정의와 증권신고서","q":"자본시장법상 증권신고서에 관한 설명으로 가장 적절한 것은?","o":["모집과 매출은 모두 10인 이상을 상대로 할 때 성립한다","모집은 이미 발행된 증권을 대상으로 한다","증권신고서는 매출의 경우 매출인이 제출한다","매출은 이미 발행된 증권을 50인 이상에게 매도의 청약을 하거나 매수의 청약을 권유하는 것이다"],"a":3,"c":"모집은 새로 발행하는 증권, 매출은 이미 발행된 증권을 50인 이상에게 파는 것이에요.","e":"이미 발행된 증권을 50인 이상에게 매도 청약·매수 청약 권유하는 것이 매출이에요. 증권신고서는 모집이든 매출이든 발행인이 제출해요.","w":["모집·매출 모두 50인 이상이 기준이에요. 10인은 기준이 아니에요.","새로 발행하는 증권이 모집 대상이에요.","증권신고서 제출의무자는 언제나 발행인이에요.",null],"k":"새 상품을 처음 파는 게 모집, 이미 있는 걸 많은 사람에게 되파는 게 매출이에요.","m":"모집 = 신규 발행 · 매출 = 기발행 · 신고서 제출 = 발행인","f":null},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"투자설명서 교부 면제","q":"K자산운용 펀드를 사려는 다음 사람들 가운데 판매회사가 투자설명서를 주지 않아도 되는 사람을 모두 고른 것은?\nㄱ. 연기금 등 전문투자자\nㄴ. \"설명서는 필요 없다\"고 이메일로 밝힌 투자자\nㄷ. 지난달 받은 설명서와 내용이 같은 같은 펀드를 더 사는 투자자\nㄹ. 이 펀드에 처음 가입하는 일반투자자","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":2,"c":"투자설명서 교부는 원칙이지만, 이미 정보가 있거나 스스로 거부한 사람에게는 면제해요.","e":"전문투자자 등, 수령 거부 의사를 밝힌 자(서면·전화·전자우편 등), 같은 내용의 집합투자증권을 추가 취득하는 자가 면제 대상이에요. 처음 투자하는 일반투자자는 교부 대상이에요.","w":["ㄷ도 면제 대상이에요.","ㄴ도 면제 대상이에요.",null,"처음 투자하는 일반투자자에게는 반드시 교부해요."],"k":"\"이미 아는 사람, 필요 없다는 사람, 똑같은 걸 또 사는 사람\"은 안 줘도 돼요.","m":"교부 면제: 전문투자자 · 수령거부 · 동일 증권 추가 취득"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자설명서 갱신 주기","q":"투자설명서의 종류와 사용 시기에 관한 설명으로 가장 적절하지 않은 것은?","o":["예비투자설명서는 증권신고서 수리 후 효력 발생 전에 쓴다","간이투자설명서는 효력 발생 전과 후 모두 쓸 수 있다","개방형 집합투자증권은 투자설명서를 2년마다 1회 이상 고쳐 제출하면 된다","투자설명서는 증권신고서 효력 발생 후에 쓴다"],"a":2,"c":"계속 발행되는 개방형 집합투자증권은 정보가 최신이어야 해서 투자설명서를 정기적으로 고쳐야 해요.","e":"개방형 집합투자증권은 최초 발행 후 1년마다 1회 이상 투자설명서를 고쳐 제출해야 해요.","w":["예비투자설명서의 사용 시기가 맞아요.","간이투자설명서는 효력 전후 모두 써요.",null,"투자설명서는 효력 발생 후에 써요."],"k":"계속 파는 펀드 설명서는 \"매년\" 새로 고쳐요.","m":"개방형 투자설명서 갱신 = 1년마다 1회 이상"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"하","rev":0,"t":"전매제한 인출 불허 사유","q":"전매제한조치로 예탁된 증권의 인출 사유로 가장 거리가 먼 것은?","o":["합병으로 존속회사 주식과 교환하기 위한 인출","액면분할에 따라 새 증권으로 바꾸기 위한 인출","공개매수에 응모하기 위한 인출","전환권을 행사하기 위한 인출"],"a":2,"c":"전매제한 예탁증권은 보유자가 그대로 유지되는 형식적 변경일 때만 꺼낼 수 있어요.","e":"공개매수 응모는 그 자체가 매도라 소유권이 넘어가요. 전매제한 취지를 정면으로 무너뜨리므로 인출 사유가 아니에요.","w":["합병에 따른 교환은 허용돼요.","액면분할에 따른 교환은 허용돼요.",null,"권리 행사는 허용돼요."],"k":"공개매수 응모는 결국 \"파는 것\"이라 안 돼요.","m":"전매제한 인출: 형식적 변경 O · 매도(공개매수 응모) X"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"투자자예탁금의 보호","q":"자본시장법상 투자자예탁금에 관한 설명으로 가장 적절하지 않은 것은?","o":["고유재산과 구분해 증권금융회사에 예치하거나 신탁해야 한다","예치·신탁된 투자자예탁금은 누구도 상계하거나 압류할 수 없다","예치한 금융투자업자는 투자자예탁금을 자기 차입금의 담보로 제공할 수 있다","예치할 때는 투자자의 재산이라는 뜻을 밝혀야 한다"],"a":2,"c":"투자자예탁금은 투자자의 돈이라 금융투자업자의 재산과 완전히 분리해 보호해요.","e":"예치 금융투자업자도 투자자예탁금을 양도하거나 담보로 제공할 수 없어요.","w":["별도 예치·신탁이 원칙이에요.","상계·압류가 금지돼요.",null,"투자자 재산임을 밝혀야 해요."],"k":"고객이 맡긴 돈을 회사 대출 담보로 잡으면 회사가 망할 때 고객 돈이 사라져요.","m":"예탁금: 별도예치 · 상계·압류 X · 양도·담보 X"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"예치기관의 예탁금 운용","q":"증권금융회사가 증권사로부터 예치받은 투자자예탁금을 굴리려 한다. 허용되지 않는 방법은?","o":["국채증권이나 지방채증권을 산다","정부·지방자치단체가 원리금 지급을 보증한 채무증권을 산다","달러 표시 양도성예금증서를 담보로 잡고 대출한다","상장증권을 담보로 잡고 대출한다"],"a":2,"c":"투자자예탁금은 언제든 돌려줘야 하는 돈이라 안전하고 유동성 높은 방법으로만 운용해요.","e":"담보대출은 증권이나 원화로 표시된 양도성예금증서를 담보로 할 때만 허용돼요. 외화 CD는 환율 위험이 있어 안 돼요.","w":["국채·지방채 매수는 허용돼요.","정부 등이 보증한 채무증권 매수는 허용돼요.",null,"증권 담보 대출은 허용돼요."],"k":"고객 돈은 \"환율로 흔들릴 수 있는 담보\"를 잡고 빌려주면 안 돼요.","m":"예탁금 운용: 국공채 · 보증채 · 증권·원화CD 담보대출"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자자문업자의 금지행위","q":"〈보기〉는 자문·일임 회사 V사가 한 일이다. 법상 하면 안 되는 행위는 몇 개인가?\nㄱ. 계약서상 보수와 별도로 수익이 나자 사례금을 따로 받았다.\nㄴ. 돈이 부족한 고객에게 다른 회사 대출을 알선해 주었다.\nㄷ. 자격 요건을 갖춘 운용역에게 일임재산을 맡겼다.","o":["0개","1개","2개","3개"],"a":2,"c":"투자자문·일임업자는 계약으로 정한 보수만 받고, 투자자에게 돈을 빌려주거나 대출을 연결해 주면 안 돼요.","e":"금지되는 행위는 ㄱ과 ㄴ, 2개예요. 자격 있는 투자운용인력에게 운용을 맡기는 ㄷ은 적법해요.","w":["ㄱ, ㄴ은 금지 행위예요.","ㄴ(대출 중개)도 금지예요.",null,"ㄷ은 적법한 행위예요."],"k":"정해진 수수료 외 \"보너스\"를 받거나, 고객에게 \"빚내서 투자\"를 연결해 주면 안 돼요.","m":"자문·일임: 계약 외 대가 X · 금전 대여·중개 X"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자일임보고서 교부 주기","q":"투자일임업자의 투자일임보고서에 관한 설명으로 가장 적절하지 않은 것은?","o":["일반투자자에게 3개월에 1회 이상 교부해야 한다","역외투자일임업자는 국내 투자자에게 분기마다 1회만 제공하면 된다","작성 대상 기간이 지난 후 2개월 이내에 교부해야 한다","투자일임재산의 운용 현황을 담아야 한다"],"a":1,"c":"투자일임보고서는 투자자가 맡긴 재산이 어떻게 운용되는지 정기적으로 알려 주는 문서예요.","e":"역외투자일임업자는 국내 투자자 보호를 위해 월 1회 이상 제공해야 해요. 분기 1회는 국내 투자일임업자의 주기예요.","w":["3개월에 1회 이상이 맞아요.",null,"작성 기간 경과 후 2개월 이내예요.","운용 현황을 담아야 해요."],"k":"해외에 있는 일임업자는 더 자주(매달) 알려 줘야 해요.","m":"일임보고서: 국내 3개월 1회 · 역외 월 1회"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","rev":0,"t":"동일법인 지분증권 투자한도","q":"공모펀드가 한 회사의 주식을 사들일 때 걸리는 지분 한도(지분증권 총수 기준)에 대한 설명으로 맞는 것은?","o":["한도는 각 집합투자기구 자산총액의 10%로 계산한다","한 운용사의 모든 펀드를 합치면 한도가 50%까지 늘어난다","부동산집합투자기구도 예외 없이 지분증권 총수의 10%를 넘을 수 없다","한도는 그 법인이 발행한 지분증권 총수의 10%로 계산한다"],"a":3,"c":"동일종목 투자한도(자산총액 기준)와 동일법인 지분증권 한도(발행총수 기준)는 분모가 달라요.","e":"각 집합투자기구는 동일법인이 발행한 지분증권 총수의 10%를 넘어 투자할 수 없어요. 부동산집합투자기구는 부동산개발회사 등 지분을 100%까지 취득할 수 있는 예외가 있어요.","w":["자산총액 기준 10%는 동일종목 투자한도예요.","집합투자업자 전체 합산 한도는 20%예요.","부동산집합투자기구는 예외가 있어요.",null],"k":"\"내 펀드 돈의 10%\"가 아니라 \"그 회사 주식 전체의 10%\"까지라는 뜻이에요.","m":"동일법인 지분: 발행총수의 10%(펀드별) · 운용사 전체 20%"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","rev":0,"t":"동일종목 30% 투자 가능 증권","q":"공모 집합투자기구가 자산총액의 30%까지 동일종목에 투자할 수 있는 증권을 〈보기〉에서 모두 고르면 몇 개인가?\nㄱ. 지방채증권\nㄴ. 특수채증권\nㄷ. 파생결합증권\nㄹ. OECD 회원국 정부가 발행한 채권\nㅁ. 일반 상장회사가 발행한 주식","o":["2개","3개","4개","5개"],"a":2,"c":"동일종목 투자한도는 원칙 10%이고, 신용도가 높거나 분산이 어려운 일부 증권은 30% 또는 100%까지 허용해요.","e":"지방채, 특수채, 파생결합증권, OECD 회원국(및 중국) 정부 발행 채권은 30%까지 가능해요. 일반 회사 주식은 10% 한도예요. 4개예요.","w":["ㄱ~ㄹ 네 개가 30% 대상이에요.","파생결합증권도 30% 대상이에요.",null,"일반 주식은 10% 한도예요."],"k":"나라 빚(국채)은 100%, 지방·특수채·파생결합·OECD 국채는 30%, 나머지는 10%예요.","m":"동일종목: 국채 100% · 지방채·특수채·파생결합·OECD국채 30% · 일반 10%"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"집합투자업자의 불건전 영업행위","q":"W자산운용이 펀드를 굴리면서 한 다음 행위 가운데 법이 막는 불건전 영업행위는?","o":["계열 증권사가 인수한 채권을 인수 후 3개월이 지나 매입했다","다른 운용사와 짜고 서로의 펀드로 상대 회사 상품을 사 주었다","규약에 적힌 투자 범위 안에서 운용했다","거래소 시장에서 계열사 상장주식을 정상 가격으로 샀다"],"a":1,"c":"집합투자업자는 투자자 이익을 해치거나 시장을 왜곡할 수 있는 거래를 해서는 안 돼요.","e":"제3자와 짜고 서로의 펀드로 특정 자산에 교차투자하는 것은 이해상충과 시세 왜곡을 낳아 금지돼요.","w":["인수일부터 3개월이 지나면 예외로 허용돼요.",null,"규약 범위 내 운용은 정상 업무예요.","공개시장 거래는 이해관계인 거래 제한의 예외예요."],"k":"\"네 펀드로 내 종목 사 주면, 내 펀드로 네 종목 사 줄게\"는 금지예요.","m":"교차투자(짜고 서로 사 주기) = 금지"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"수시공시 사유","q":"N자산운용의 펀드에 아래 일이 생겼다. 투자자에게 바로 알려야 하는 수시공시 사유만 모두 고른 것은?\nㄱ. 담당 펀드매니저가 바뀌었다\nㄴ. 환매를 연기하기로 결정했다\nㄷ. 규약을 바꾸면서 투자설명서도 함께 바뀌었다\nㄹ. 편입 채권에서 부실이 발생했다","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":1,"c":"수시공시는 투자자에게 중요한 변화가 생겼을 때 바로 알리는 제도예요.","e":"운용인력 변경, 환매연기·재개, 부실자산 발생은 수시공시 사유예요. 규약 변경에 따른 투자설명서 변경은 규약 변경 자체의 절차를 거치므로 제외돼요.","w":["부실자산 발생(ㄹ)도 수시공시 사유예요.",null,"ㄱ(운용인력 변경)이 빠졌고, ㄷ은 제외 사유예요.","ㄷ은 수시공시 사유에서 제외돼요."],"k":"\"담당 매니저가 바뀌었어요, 환매가 멈췄어요, 부실이 생겼어요\"는 바로 알려야 해요.","m":"수시공시: 운용인력 변경 · 환매연기·재개 · 부실자산"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"영업보고서 제출","q":"집합투자업자의 집합투자재산 관련 보고·제출 의무에 관한 설명으로 가장 적절한 것은?","o":["분기 영업보고서는 분기 종료 후 2개월 안에 금융위원회와 금융투자협회에 낸다","분기 영업보고서는 금융위원회에만 내면 된다","결산서류는 사유가 생긴 날부터 6개월 안에 내면 된다","영업보고서는 1년에 한 번만 내면 된다"],"a":0,"c":"집합투자업자는 펀드 운용 현황을 정기적으로 감독당국과 협회에 보고해요.","e":"매 분기 영업보고서는 분기 종료 후 2개월 이내에 금융위원회와 협회 두 곳에 제출해요. 결산서류도 사유 발생일부터 2개월 이내예요.","w":[null,"협회에도 제출해야 해요.","결산서류도 2개월 이내예요.","분기마다 제출해요."],"k":"분기마다, 2개월 안에, 금융위와 협회 두 곳에!","m":"영업보고서: 분기 · 2개월 이내 · 금융위 + 협회"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"사모집합투자기구의 명칭","q":"집합투자기구의 명칭에 관한 설명으로 가장 적절한 것은?","o":["사모집합투자기구는 명칭에 \"사모\"라는 표시를 해야 한다","명칭 앞부분에 판매회사의 이름을 넣어야 한다","운용전문인력의 이름을 명칭에 넣을 수 있다","집합투자기구의 종류는 명칭에 표시하지 않아도 된다"],"a":0,"c":"펀드 이름은 투자자가 상품 성격을 오해하지 않도록 일정한 규칙을 따라야 해요.","e":"사모집합투자기구는 명칭에 \"사모\"를 표시해야 해요. 명칭 앞에는 판매회사가 아니라 운용하는 회사 이름을 넣을 수 있어요.","w":[null,"판매회사가 아니라 운용회사 이름이에요.","운용전문인력 이름은 쓸 수 없어요.","종류를 알 수 있게 표시해야 해요."],"k":"이름만 봐도 \"사모펀드구나\"를 알 수 있어야 해요.","m":"사모펀드 명칭 = \"사모\" 표시 · 앞에는 운용사 이름"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"내부자와 준내부자","q":"P사의 미공개 신제품 정보를 알게 된 다음 사람 가운데 자본시장법상 \"준내부자\"로 분류되는 사람은?","o":["해당 법인 계열회사의 임원","해당 법인과 공급계약 체결을 교섭하고 있는 회사","해당 법인의 주요주주","해당 법인의 직원"],"a":1,"c":"내부자는 회사 안에 있는 사람(임직원·대리인·주요주주), 준내부자는 회사 밖에서 업무상 정보를 얻는 사람이에요.","e":"해당 법인과 계약을 체결하고 있거나 교섭 중인 자, 법령상 인허가·감독 권한을 가진 자가 준내부자예요.","w":["계열회사 임직원은 내부자예요.",null,"주요주주는 내부자예요.","직원은 내부자예요."],"k":"회사 밖이지만 거래하면서 비밀을 알게 된 사람이 준내부자예요.","m":"내부자 = 임직원·주요주주 / 준내부자 = 감독권한자·계약 상대방"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"대량보유 보고(5% 룰)","q":"상장사 지분을 사 모으는 투자자에게 적용되는 \"5% 보고\" 제도에 대한 설명으로 틀린 것은?","o":["본인과 특별관계자를 합쳐 5% 이상 보유하게 되면 5일 이내에 보고한다","보유 비율이 1% 이상 변동하면 변동 보고를 한다","보유 목적을 단순투자에서 경영참가로 바꾸면 변경 보고를 한다","지분율 변화가 없다면 보유 목적을 경영참가에서 단순투자로 바꾸어도 보고할 필요가 없다"],"a":3,"c":"5% 룰은 경영권에 영향을 줄 수 있는 지분 변화를 시장에 알리는 제도예요.","e":"보유 목적 변경은 방향과 관계없이 모두 변경 보고 사유예요. 지분율 변화가 없어도 보고해야 해요.","w":["5% 이상 보유 시 5일 이내 보고해요.","1% 이상 변동 시 보고해요.","경영참가로의 변경은 보고 사유예요.",null],"k":"\"경영에 참여할 거야 → 그냥 투자만 할래\"로 바뀌는 것도 시장엔 중요한 정보예요.","m":"5% 룰: 5% · 5일 · 1% 변동 · 목적 변경도 보고"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"업무위탁 보고 시기","q":"금융투자업자의 업무위탁에 관한 설명으로 가장 적절한 것은?","o":["본질적 업무를 위탁하면 위탁받은 자가 업무를 수행하기 7일 전까지 보고해야 한다","본질적 업무는 어떤 경우에도 위탁할 수 없다","업무위탁은 금융위원회의 사전 승인을 받아야만 할 수 있다","위탁한 업무에 문제가 생겨도 위탁한 금융투자업자는 책임지지 않는다"],"a":0,"c":"금융투자업자는 일부 업무를 다른 회사에 맡길 수 있지만, 핵심 업무는 사전 보고 등 더 엄격한 절차를 거쳐요.","e":"본질적 업무를 위탁하면 위탁받은 자가 그 업무를 실제로 수행하려는 날의 7일 전까지 보고해야 해요.","w":[null,"일정 요건을 갖추면 본질적 업무도 위탁할 수 있어요.","사전 승인이 아니라 보고 방식이에요.","위탁해도 투자자에 대한 책임은 남아요."],"k":"핵심 업무를 남에게 맡길 땐 일주일 전에 미리 알려야 해요.","m":"본질적 업무 위탁 = 수행 7일 전 보고"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"장외파생상품 매매 승인","q":"투자매매업자의 장외파생상품 업무에 관한 설명으로 가장 적절하지 않은 것은?","o":["장외파생상품 매매 때마다 파생상품업무책임자의 승인을 받는다","일반투자자와의 장외파생상품 매매는 위험회피 목적에 한한다","파생상품업무책임자는 상근임원이어야 한다","준법감시인의 사전 승인만 받으면 파생상품업무책임자의 승인을 생략할 수 있다"],"a":3,"c":"장외파생상품은 위험이 커서 거래마다 책임 있는 임원의 승인을 받도록 해요.","e":"장외파생상품 매매는 상근임원인 파생상품업무책임자의 승인을 받아야 해요. 준법감시인은 내부통제 점검 담당이라 개별 거래 승인 주체가 아니에요.","w":["거래마다 승인을 받아요.","일반투자자와는 위험회피 목적만 허용돼요.","상근임원이어야 해요.",null],"k":"위험한 거래의 \"결재권자\"는 파생상품 책임 임원이에요. 준법감시인이 대신할 수 없어요.","m":"장외파생: 파생상품업무책임자(상근임원) 승인 · 일반투자자는 헤지만"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"자산건전성 충당금 적립률","q":"금융투자업규정상 자산건전성 분류별 최저 대손충당금 적립률로 가장 적절하지 않은 것은?","o":["정상 – 0.5%","요주의 – 2%","고정 – 20%","회수의문 – 50%"],"a":3,"c":"자산건전성이 나쁠수록 돌려받지 못할 가능성이 커서 충당금을 더 많이 쌓아요.","e":"최저 적립률은 정상 0.5%, 요주의 2%, 고정 20%, 회수의문 75%, 추정손실 100%예요.","w":["정상은 0.5%예요.","요주의는 2%예요.","고정은 20%예요.",null],"k":"나쁠수록 더 많이 떼어 둬요. 회수의문은 75%, 추정손실은 전부예요.","m":"충당금: 정상 0.5 · 요주의 2 · 고정 20 · 회수의문 75 · 추정손실 100"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"신용공여 담보비율","q":"투자중개업자가 투자자에게 상장주권을 담보로 1억원을 신용공여하려 한다. 금융투자업규정상 신용공여를 할 때 확보(징구)해야 하는 최소 담보 평가액으로 가장 적절한 것은?","o":["1억원","1억 2천만원","1억 4천만원","2억원"],"a":2,"c":"증권을 담보로 돈을 빌려줄 때는 주가 하락에 대비해 빌려준 돈보다 넉넉한 담보를 잡아요.","e":"신용공여를 할 때는 신용공여금액의 140% 이상에 해당하는 담보를 확보(징구)해야 해요. 1억원 × 140% = 1억 4천만원이에요. 그 뒤 계속 지켜야 하는 담보비율(담보유지비율)은 회사가 내규로 정해요.","w":["담보비율 100%는 너무 낮아요.","120%가 아니라 140%예요.",null,"200%는 법정 최소 기준이 아니에요."],"k":"1억을 빌려주면 주식을 1억 4천만원어치는 잡아 둬야 해요.","m":"신용공여 담보 징구 ≥ 140% · 유지비율은 회사 내규","f":"1억원 × 1.4 = 1억 4천만원"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"반대수익자의 매수청구권","q":"투자신탁의 합병 등 수익자총회 결의에 반대한 수익자가 수익증권 매수를 청구하려면 언제까지 해야 하는가? (총회 전에 반대 의사를 서면으로 알린 경우)","o":["결의일부터 7일 이내","결의일부터 20일 이내","결의일부터 1개월 이내","결의일부터 3개월 이내"],"a":1,"c":"중요한 결정에 반대한 수익자가 펀드에서 빠져나올 수 있도록 매수청구권을 줘요.","e":"총회 전에 반대 의사를 서면으로 알린 수익자는 결의일부터 20일 이내에 서면으로 매수를 청구해야 해요.","w":["기간이 짧아요.",null,"1개월이 아니라 20일이에요.","기간이 너무 길어요."],"k":"\"반대했으니 내 몫을 사 가세요\"를 20일 안에 말해야 해요.","m":"반대수익자 매수청구 = 결의일부터 20일 이내"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"환매금지형의 추가 발행","q":"환매금지형 집합투자기구가 집합투자증권을 추가로 발행할 수 있는 경우로 가장 거리가 먼 것은?","o":["이익분배금 범위에서 추가로 발행하는 경우","기존 투자자의 이익을 해칠 우려가 없다고 신탁업자의 확인을 받은 경우","기존 투자자 전원이 동의한 경우","집합투자업자가 운용상 필요하다고 판단한 경우라면 언제든"],"a":3,"c":"환매금지형은 투자자가 돈을 뺄 수 없어서, 추가 발행이 기존 투자자의 지분을 희석시킬 수 있어요.","e":"추가 발행은 이익분배금 범위 내, 신탁업자 확인, 기존 투자자 전원 동의, 기존 투자자에게 우선 매수 기회를 주는 경우 등으로 제한돼요. 운용사 판단만으로는 안 돼요.","w":["이익분배금 범위는 허용돼요.","신탁업자 확인 시 허용돼요.","전원 동의 시 허용돼요.",null],"k":"못 빠져나가는 사람들 몫이 줄지 않도록 추가 발행을 엄격히 막아요.","m":"환매금지형 추가발행: 이익분배금 · 신탁업자 확인 · 전원 동의 · 우선매수"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","rev":0,"t":"부동산 관련 차입 한도","q":"부동산 전문 펀드 A(순자산 750억원)와, 부동산 전문 펀드는 아니지만 건물 300억원어치를 담은 혼합형 B펀드가 각각 부동산 취득 자금을 빌리려 한다. 법상 빌릴 수 있는 최대 금액의 짝은?","o":["A 1,500억원, B 210억원","A 750억원, B 300억원","A 1,500억원, B 300억원","A 525억원, B 210억원"],"a":0,"c":"부동산 투자는 차입이 흔해서 펀드도 일정 한도 안에서 빌릴 수 있게 해요. 펀드 종류에 따라 기준이 달라요.","e":"부동산집합투자기구는 순자산총액의 200%까지(750 × 2 = 1,500억원), 그 밖의 펀드는 보유 부동산가액의 70%까지(300 × 0.7 = 210억원) 빌릴 수 있어요.","w":[null,"한도 비율을 반영하지 않았어요.","B에 70%를 적용하지 않았어요.","A에 70%를 적용했어요."],"k":"부동산 전문 펀드는 내 돈의 2배까지, 일반 펀드는 부동산 값의 70%까지 빌릴 수 있어요.","m":"부동산펀드 차입 = 순자산 200% · 일반펀드 = 부동산가액 70%","f":"A 750 × 2 = 1,500억 · B 300 × 0.7 = 210억"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"미공개정보 규제 대상 증권","q":"상장사 임원이 회사 내부 호재를 미리 알고 거래했다. 내부자거래 규제가 미치는 \"특정증권등\"에 들어가지 않는 것은?","o":["해당 상장법인이 발행한 주권","해당 상장법인이 발행한 전환사채","해당 법인 주식을 기초자산으로 하는 주식선물","전환·교환 조건이 없는 일반 사채"],"a":3,"c":"미공개정보 규제는 주가와 연결된 증권을 대상으로 해요. 정보가 주가에 영향을 주기 때문이에요.","e":"전환·교환 조건이 없는 일반 사채는 주가와 직접 연계되지 않아 규제 대상에서 빠져요. 주권, 전환사채·신주인수권부사채, 그 증권을 기초로 한 파생상품 등이 대상이에요.","w":["주권은 대상이에요.","전환사채는 주식과 연계돼 대상이에요.","해당 주식을 기초로 한 파생상품은 대상이에요.",null],"k":"주가와 연결돼 있어야 내부 정보로 부당 이득을 볼 수 있어요.","m":"특정증권등: 주권 · CB·BW 등 · 관련 파생상품 (일반 사채 제외)"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"단기매매차익 반환","q":"상장법인의 임원이 자기 회사 주식을 산 뒤 일정 기간 안에 팔아 이익을 얻었다면 그 이익을 회사에 반환해야 한다. 그 기간은?","o":["1개월","3개월","6개월","1년"],"a":2,"c":"임원이나 주요주주는 내부 정보에 접근하기 쉬워서, 짧은 기간 사고판 이익은 정보 이용 여부와 관계없이 반환하게 해요.","e":"매수 후 6개월 이내 매도(또는 매도 후 6개월 이내 매수)로 얻은 이익은 회사에 반환해야 해요.","w":["기간이 짧아요.","기간이 짧아요.",null,"기간이 길어요."],"k":"회사 사람이 6개월 안에 사고팔아 번 돈은 \"혹시 몰라\" 회사에 돌려줘야 해요.","m":"단기매매차익 반환 = 6개월 이내 · 임원·주요주주"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"시세조종의 유형","q":"매수인과 매도인이 미리 짜고 같은 시기에 같은 가격으로 매매해 거래가 활발한 것처럼 보이게 하는 행위는?","o":["통정매매","가장매매","시세고정","공매도"],"a":0,"c":"시세조종은 인위적으로 가격이나 거래량을 조작해 다른 투자자를 속이는 행위예요.","e":"서로 짜고 같은 시기·가격에 사고파는 것은 통정매매예요. 권리 이전 없이 혼자 사고파는 척하는 것은 가장매매예요.","w":[null,"가장매매는 권리 이전 목적 없이 외형만 꾸미는 매매예요.","시세고정은 가격을 일정하게 묶어 두는 행위예요.","공매도는 시세조종 유형이 아니에요."],"k":"친구끼리 짜고 물건을 사고팔아 \"인기 상품\"처럼 보이게 하는 수법이에요.","m":"통정매매 = 짜고 매매 · 가장매매 = 권리이전 없는 매매"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"t":"공개매수 의무","q":"자본시장법상 공개매수를 해야 하는 경우로 가장 적절한 것은?","o":["증권시장에서 경쟁매매로 주식을 사서 5% 이상이 된 경우","6개월 동안 증권시장 밖에서 10인 이상으로부터 주식을 사 본인과 특별관계자 지분이 5% 이상이 되는 경우","1인으로부터 1% 미만을 산 경우","자기주식을 소각할 목적으로 산 경우"],"a":1,"c":"공개매수는 시장 밖에서 많은 주주에게 지분을 사들여 경영권을 바꿀 때 모든 주주에게 공평한 기회를 주는 제도예요.","e":"6개월 동안 증권시장 밖에서 10인 이상으로부터 사서 지분이 5% 이상이 되면 공개매수를 해야 해요.","w":["장내 경쟁매매는 공개매수 의무가 없어요.",null,"요건에 해당하지 않아요.","소각 목적 매수는 공개매수가 필요 없어요."],"k":"시장 밖에서 여러 사람에게 몰래 사 모으지 말고, 모두에게 공개적으로 제안하라는 거예요.","m":"공개매수: 6개월 · 장외 · 10인 이상 · 5% 이상"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"공개매수의 철회","q":"공개매수 철회에 관한 설명으로 가장 적절한 것은?","o":["공개매수자는 언제든 자유롭게 철회할 수 있다","원칙적으로 철회할 수 없고, 대항공개매수가 있는 경우 등 정해진 사유가 있을 때만 철회할 수 있다","응모 주주는 응모를 취소할 수 없다","철회는 금융위원회 허가만 받으면 된다"],"a":1,"c":"공개매수를 쉽게 철회할 수 있으면 시장이 교란되므로 철회를 엄격하게 제한해요.","e":"공개매수는 원칙적으로 철회할 수 없어요. 대항공개매수, 공개매수자의 사망·파산 등 정해진 사유가 있을 때만 철회할 수 있어요.","w":["철회는 제한돼요.",null,"응모 주주는 공개매수 기간 중 응모를 취소할 수 있어요.","정해진 사유가 있어야 해요."],"k":"\"살게요\"라고 공개 선언했으면 마음대로 취소할 수 없어요.","m":"공개매수 철회: 원칙 금지 · 대항공개매수 등 예외"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"사업보고서 제출 기한","q":"자본시장법상 사업보고서와 분기·반기보고서의 제출 기한을 바르게 짝지은 것은?","o":["사업보고서 – 사업연도 경과 후 90일 이내, 분기·반기보고서 – 기간 경과 후 45일 이내","사업보고서 – 30일 이내, 분기·반기보고서 – 15일 이내","사업보고서 – 1년 이내, 분기·반기보고서 – 90일 이내","사업보고서 – 45일 이내, 분기·반기보고서 – 90일 이내"],"a":0,"c":"상장법인 등은 정기적으로 회사 상황을 공시해 투자자가 판단할 수 있게 해요.","e":"사업보고서는 사업연도 경과 후 90일 이내, 반기·분기보고서는 그 기간 경과 후 45일 이내에 제출해요.","w":[null,"기한이 짧아요.","기한이 길어요.","두 기한이 바뀌었어요."],"k":"1년 성적표는 90일 안에, 분기·반기 성적표는 45일 안에 내요.","m":"사업보고서 90일 · 반기·분기보고서 45일"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"주요사항보고서","q":"상장법인에 부도, 영업정지, 회생절차 개시 신청 같은 중요한 사건이 생겼을 때 제출하는 공시는?","o":["증권신고서","사업보고서","주요사항보고서","투자설명서"],"a":2,"c":"정기공시만으로는 갑자기 생긴 중대한 사건을 제때 알릴 수 없어요.","e":"부도, 영업정지, 회생절차 개시 등 중요한 사실이 생기면 주요사항보고서로 공시해요.","w":["증권을 공모할 때 내는 서류예요.","정기적으로 내는 연간 보고서예요.",null,"청약 권유에 쓰는 문서예요."],"k":"회사에 큰일이 생기면 정기 성적표를 기다리지 말고 바로 알려야 해요.","m":"주요사항보고서 = 부도·영업정지·회생 등 중대 사건"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자권유대행인의 금지행위","q":"투자권유대행인에게 금지되는 행위로 가장 적절한 것은?","o":["위탁 계약을 맺은 금융투자업자를 위해 투자권유를 한다","투자자로부터 금전이나 증권을 직접 받는다","투자권유 전에 자신이 투자권유대행인임을 알린다","금융투자업자의 투자권유준칙을 따른다"],"a":1,"c":"투자권유대행인은 권유만 대신하는 사람이라 투자자의 재산을 직접 다루면 안 돼요.","e":"투자자로부터 금전·증권 등 재산을 받는 행위는 금지돼요. 투자권유를 다른 사람에게 재위탁하는 것도 금지예요.","w":["정상적인 업무예요.",null,"알려야 하는 의무예요.","따라야 하는 의무예요."],"k":"권유만 하고 돈은 절대 직접 받으면 안 돼요.","m":"투자권유대행인: 재산 수취 X · 재위탁 X"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"자산운용보고서","q":"집합투자업자의 자산운용보고서에 관한 설명으로 가장 적절한 것은?","o":["자산운용보고서는 금융위원회에만 제출한다","1년에 한 번만 투자자에게 주면 된다","3개월마다 1회 이상 투자자에게 교부해야 한다","투자자가 요청할 때만 교부한다"],"a":2,"c":"자산운용보고서는 펀드 투자자에게 운용 현황을 정기적으로 알리는 문서예요.","e":"집합투자업자는 자산운용보고서를 3개월마다 1회 이상 투자자에게 교부해야 해요.","w":["투자자에게 교부하는 보고서예요.","주기가 길어요.",null,"정기적으로 교부해야 해요."],"k":"석 달마다 \"이렇게 운용했어요\" 보고서를 보내 줘요.","m":"자산운용보고서 = 3개월마다 1회 이상 교부"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자회사의 구조","q":"투자회사(회사형 집합투자기구)에 관한 설명으로 가장 적절하지 않은 것은?","o":["상근 임직원이 없는 서류상 회사이다","집합투자업자가 법인이사가 된다","감독이사를 두어 업무를 감독한다","직원을 두고 운영 업무를 직접 처리한다"],"a":3,"c":"투자회사는 투자자들의 돈을 주식회사 형태로 모은 펀드예요. 실제 운영은 외부 회사들이 맡아요.","e":"투자회사는 상근 임직원이 없는 서류상 회사라 운영 업무는 일반사무관리회사에, 운용은 집합투자업자(법인이사)에, 보관은 신탁업자에 맡겨요.","w":["서류상 회사예요.","집합투자업자가 법인이사예요.","감독이사가 있어요.",null],"k":"\"이름만 있는 회사\"라 일은 모두 외부 전문 회사들이 나눠서 해요.","m":"투자회사: 서류상 회사 · 법인이사(운용사) · 감독이사 · 사무는 위탁"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"일반 사모집합투자기구의 투자자","q":"일반 사모집합투자기구에 관한 설명으로 가장 적절한 것은?","o":["투자자 수 제한 없이 공모 방식으로 판매한다","투자자 총수는 100인 이하이고, 그중 일반투자자는 49인 이하이다","누구나 금액 제한 없이 투자할 수 있다","명칭에 \"사모\"를 표시하지 않아도 된다"],"a":1,"c":"사모펀드는 소수의 투자자만 대상으로 해서 공모펀드보다 규제가 느슨한 대신 투자자 자격을 제한해요.","e":"사모집합투자기구의 투자자 총수는 100인 이하이고, 그중 일반투자자는 49인 이하여야 해요. 또 적격투자자 등 일정 요건을 갖춘 투자자만 투자할 수 있어요.","w":["사모 방식이에요.",null,"적격투자자 요건이 있어요.","명칭에 \"사모\"를 표시해야 해요."],"k":"\"최대 100명, 그중 일반 개인은 49명까지\"만 모이는 펀드예요.","m":"일반 사모: 총 100인 이하(일반투자자 49인 이하) · 적격투자자 · 명칭에 \"사모\"","f":null},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","rev":0,"t":"일반 사모펀드 최소 투자금액","q":"개인이 레버리지 200% 이하인 일반 사모집합투자기구에 적격투자자로 투자할 때의 최소 투자금액은?","o":["1억원","3억원","5억원","10억원"],"a":1,"c":"사모펀드는 위험이 크고 공시가 적어서, 충분한 자금력을 가진 사람만 투자하게 최소 금액을 정해요.","e":"레버리지 200% 이하 일반 사모펀드는 3억원 이상, 200%를 넘으면 5억원 이상 투자해야 해요.","w":["기준보다 낮아요.",null,"레버리지 200% 초과 펀드의 기준이에요.","기준보다 높아요."],"k":"사모펀드는 최소 3억(레버리지 큰 펀드는 5억)부터 들어갈 수 있어요.","m":"일반 사모 최소투자: 3억(레버리지 200%↓) · 5억(200%↑)"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"대주주와의 거래 제한","q":"금융투자업자의 대주주와의 거래 제한에 관한 설명으로 가장 적절한 것은?","o":["대주주에게 자유롭게 신용공여를 할 수 있다","대주주에 대한 신용공여는 원칙적으로 금지된다","대주주가 발행한 증권은 무제한으로 소유할 수 있다","대주주와의 거래는 공시할 필요가 없다"],"a":1,"c":"대주주가 금융투자회사를 \"개인 금고\"처럼 쓰지 못하게 거래를 제한해요.","e":"금융투자업자는 대주주에게 원칙적으로 신용공여를 할 수 없고, 대주주가 발행한 증권 소유도 제한돼요.","w":["원칙적으로 금지돼요.",null,"소유 한도가 있어요.","거래 내용 보고·공시 의무가 있어요."],"k":"회사 주인(대주주)이 회사 돈을 빌려 가면 고객 돈이 위험해져요.","m":"대주주 신용공여 원칙 금지 · 대주주 발행 증권 소유 제한"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"부정거래행위","q":"자본시장법상 부정거래행위에 해당하는 것으로 가장 적절한 것은?","o":["정확한 공시 정보를 바탕으로 매매하는 행위","정상적인 차익거래","매매를 유인할 목적으로 근거 없는 풍문을 퍼뜨리는 행위","공개된 리포트를 읽고 투자하는 행위"],"a":2,"c":"부정거래행위는 부정한 수단이나 거짓 정보로 다른 투자자를 속여 이익을 얻는 행위를 넓게 금지해요.","e":"매매를 유인하거나 시세를 움직이려고 풍문을 유포하는 것은 부정거래행위예요.","w":["정상적인 매매예요.","정상적인 거래예요.",null,"정상적인 투자예요."],"k":"\"이 회사 곧 인수된대\"라는 근거 없는 소문을 퍼뜨려 주가를 올리면 범죄예요.","m":"부정거래: 부정한 수단 · 풍문 유포 · 위계 사용"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"투자권유준칙","q":"금융투자업자의 투자권유준칙에 관한 설명으로 가장 적절한 것은?","o":["투자자가 직접 작성한다","회사 영업 목표를 정하는 문서이다","임직원이 투자권유를 할 때 따라야 할 구체적 기준과 절차를 정한 것이다","내부 문서이므로 공시할 필요가 없다"],"a":2,"c":"투자권유준칙은 적합성 원칙 등을 현장에서 지킬 수 있도록 회사가 만든 실무 기준이에요.","e":"임직원이 투자권유 시 따라야 할 기준과 절차를 정하고, 인터넷 홈페이지 등에 공시해야 해요.","w":["회사가 정해요.","권유 기준을 정하는 문서예요.",null,"공시해야 해요."],"k":"직원들이 고객에게 상품을 권할 때 따르는 \"매뉴얼\"이에요.","m":"투자권유준칙 = 권유 기준·절차 · 공시 의무"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"신탁재산의 독립성","q":"자본시장법상 신탁업자의 신탁재산 관리에 관한 설명으로 가장 적절하지 않은 것은?","o":["신탁재산은 신탁업자의 고유재산과 구분해 관리한다","신탁업자가 파산해도 신탁재산은 파산재단에 속하지 않는다","신탁재산에 대해서는 원칙적으로 강제집행할 수 없다","신탁업자는 신탁재산을 자기 고유재산의 채무 담보로 제공할 수 있다"],"a":3,"c":"신탁재산은 맡긴 사람(위탁자)과 수익자의 재산이라 신탁업자의 재산과 완전히 분리돼요.","e":"신탁재산을 신탁업자 자신의 채무 담보로 제공하는 것은 금지돼요.","w":["구분 관리가 원칙이에요.","파산재단에 속하지 않아요.","강제집행이 제한돼요.",null],"k":"맡긴 재산을 맡은 회사의 빚 담보로 쓰면 안 돼요.","m":"신탁재산: 구분관리 · 파산 격리 · 강제집행 제한 · 담보 제공 X"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"금융투자업자의 겸영업무 보고","q":"금융투자업자의 겸영업무와 부수업무에 관한 설명으로 가장 적절한 것은?","o":["부수업무는 어떤 경우에도 할 수 없다","겸영업무를 하면 금융투자업 인가가 취소된다","겸영업무는 업무를 시작한 날부터 2주 이내에 금융위원회에 보고하는 방식으로 영위할 수 있다","겸영업무는 금융위원회의 인가를 별도로 받아야만 한다"],"a":2,"c":"금융투자업자는 본업 외에 일정한 다른 금융업무(겸영)나 부수적인 업무를 할 수 있어요.","e":"겸영업무와 부수업무는 별도 인가 없이, 업무를 시작한 날부터 2주 이내에 금융위원회에 보고(사후보고)하는 방식으로 영위할 수 있어요.","w":["부수업무도 시작 후 2주 이내에 보고하면 할 수 있어요.","취소 사유가 아니에요.",null,"별도 인가가 아니라 사후보고 방식이에요."],"k":"본업 외의 일을 시작했다면 2주 안에 \"이 일도 하고 있어요\"라고 알리면 돼요.","m":"겸영·부수업무 = 시작 후 2주 이내 금융위 보고(사후보고)","f":null},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","rev":0,"t":"공매도 규제","q":"자본시장법상 상장증권 공매도에 관한 설명으로 가장 적절한 것은?","o":["소유하지 않은 증권을 빌리지도 않고 매도하는 무차입 공매도는 금지된다","차입 공매도와 무차입 공매도가 모두 자유롭게 허용된다","공매도 주문 시 공매도 여부를 표시할 필요가 없다","공매도 규제는 증권 외 파생상품 거래에도 동일하게 적용된다"],"a":0,"c":"공매도는 가지고 있지 않은 증권을 파는 거래예요. 빌려서 파는지 여부가 핵심이에요.","e":"자본시장법은 빌리지 않고 파는 무차입 공매도를 금지하고, 차입 공매도만 정해진 방법과 가격 규제 아래 허용해요. 공매도 주문은 그 사실을 표시해야 해요.","w":[null,"무차입 공매도는 금지예요.","공매도 표시 의무가 있어요.","상장증권 매도에 대한 규제예요."],"k":"빌린 주식만 팔 수 있어요.","m":"무차입 공매도 금지 · 차입 공매도 허용(호가·표시 규제)"},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","t":"금융투자업의 판단 기준과 적용배제","q":"다음 영업에 대한 자본시장법상 판단으로 가장 적절한 것은?","o":["X사가 고객 주문을 자기 명의로 내고 손익은 고객에게 돌렸다면 투자매매업에 해당한다","증권사와 위탁계약을 맺은 투자권유대행인이 투자를 권유하면 투자중개업을 영위하는 것이다","누구나 사 볼 수 있는 경제신문에 종목 분석 기사를 싣는 것은 투자자문업에 해당하지 않는다","종합금융회사가 어음관리계좌(CMA)를 운용하려면 집합투자업 인가가 필요하다"],"a":2,"c":"자본시장법은 금융투자업을 손익이 누구에게 귀속되는지(계산)로 나누고, 겉모습은 비슷해도 투자자 보호 필요가 적은 업무는 적용에서 빼 줘요.","e":"불특정 다수를 상대로 발행되는 간행물·방송 등으로 하는 투자 조언은 투자자문업에서 빠져요.","w":["금융투자업은 명의가 아니라 누구의 계산인지로 나눠요. 남의 계산이면 투자중개업이에요.","투자권유대행인의 권유 행위는 투자중개업에서 빠지는 적용배제 사유예요.",null,"종합금융회사의 CMA 업무는 집합투자업에서 빠지는 적용배제 사유예요."],"k":"가게 간판(명의)이 아니라 돈주머니(계산)가 누구 것인지 보는 거예요. 그리고 신문 칼럼까지 자문업으로 묶으면 지나치니 빼 줘요.","m":"\"자기 계산 = 매매업, 남의 계산 = 중개업 · 간행물·대행인·종금 CMA는 적용배제\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"증권신고서 제출 기준 금액","q":"비상장법인 Y사는 8개월 전에 증권신고서 없이 18억원어치 주식을 공모했고, 이번에 14억원어치를 추가로 공모하려 한다. 2026년 11월 현재 자본시장법령상 이번 공모에 관한 설명으로 가장 적절한 것은? (금액과 관계없이 신고해야 하는 증권은 아니다)","o":["이번 공모액이 30억원에 못 미치므로 증권신고서를 내지 않아도 된다","과거 1년간 신고서 없이 공모한 금액과 합치면 30억원 이상이므로 증권신고서를 내야 한다","증권신고서는 Y사가 아니라 공모를 주선하는 증권사가 제출한다","금융위원회가 신고서를 수리하면 그 주식의 가치를 정부가 인정한 것이 된다"],"a":1,"c":"증권신고서는 공모 증권의 정보를 투자자에게 알리는 서류예요. 소액이면 면제하지만, 쪼개서 공모하는 편법을 막으려고 과거 1년치를 합산해요. 기준 금액은 2026년 7월 시행령 개정으로 10억원에서 30억원으로 올랐어요.","e":"이번 모집가액에 과거 1년 동안 신고서 없이 한 모집가액을 더해 30억원 이상이면 신고서를 내야 해요. 14억원 + 18억원 = 32억원이라 제출 대상이에요.","w":["이번 금액만 보면 안 돼요. 과거 1년간 신고서 없이 한 공모액을 합쳐서 판단해요.",null,"증권신고서 제출의무자는 언제나 발행인이에요.","신고서를 수리하거나 효력이 생겨도 정부가 그 증권의 가치를 보증하는 것은 아니에요."],"k":"선물 한도 규칙을 피하려고 여러 번 나눠 줘도 1년치를 합쳐서 세는 것과 같아요.","m":"\"신고서: (이번 + 과거 1년 미신고분) 30억원↑이면 제출 · 제출자는 발행인\"","f":"14억원 + 18억원 = 32억원 ≥ 30억원 → 증권신고서 제출","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"상","t":"간주모집과 전매제한조치","q":"Z사가 49인 이하에게 사모로 증권을 발행하려 한다. 다음 중 전매가능성이 있어 모집으로 간주되는 경우는?","o":["사채권을 40매로 발행하면서 권면에 발행 후 1년 이내 분할금지 특약을 적은 경우","발행한 증권을 예탁결제원에 맡기고 1년간 인출·매각하지 않기로 계약한 경우","만기가 1년 6개월인 기업어음증권을 발행하는 경우","전환사채를 발행하면서 발행 후 1년 이상 전환권을 행사하지 못하게 한 경우"],"a":2,"c":"50인 미만에게 팔아도 곧 여러 사람에게 퍼질 수 있으면 사실상 공모예요. 그래서 전매가능성이 있으면 모집으로 보고, 퍼지지 않게 묶어 두면(전매제한조치) 사모로 인정해요.","e":"만기 365일 이상 CP는 되팔릴 가능성이 있다고 보아, 사모로 발행해도 모집으로 간주해요.","w":["50매 미만 발행에 1년 이내 분할금지 특약을 붙이면 전매제한조치로 인정돼요.","증권을 예탁결제원에 1년 동안 맡기고 꺼내거나 팔지 않기로 하면 전매제한조치예요.",null,"전환권을 발행 후 1년 이상 행사하지 못하게 하면 전매제한조치예요."],"k":"작은 모임에 나눠 준 쿠폰이라도 바로 되팔 수 있으면 사실상 전단지 뿌리기와 같아요. 그래서 1년간 묶어 둬야 '모임 안 쿠폰'으로 봐줘요.","m":"\"간주모집: 50매↑ · CP 만기 365일↑ · 상장 동종 지분증권 / 제한조치: 1년 예탁 · 1년 분할금지 · 전환권 1년 금지\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"환매가격·환매수수료·환매연기","q":"개방형 공모펀드의 환매에 관한 자본시장법상 설명으로 가장 적절한 것은?","o":["환매가격은 투자자가 환매를 청구한 날 직전에 공고된 기준가격으로 정한다","환매수수료는 환매하는 투자자가 내며, 그 돈은 펀드 재산에 들어간다","환매를 연기한 집합투자업자는 연기 결정일부터 3개월 이내에 총회를 열면 된다","환매대금은 청구일부터 30일 이내에 지급하면 된다"],"a":1,"c":"환매는 펀드에서 돈을 빼는 절차예요. 먼저 나간 사람이 남은 사람에게 손해를 주지 않도록 미래가격, 수수료 귀속, 연기 절차를 정해 뒀어요. 환매 청구는 그 펀드를 판 판매회사에 해요.","e":"환매수수료는 돈을 빼는 투자자가 내고, 판매회사가 아니라 펀드 재산으로 들어가요. 남아 있는 투자자를 보호하기 위해서예요.","w":["환매가격은 청구한 날 뒤에 계산되는 기준가격(미래가격)으로 정해요. 과거 가격을 쓰면 차익거래가 생겨요.",null,"환매연기를 결정하면 그날부터 6주 이내에 집합투자자총회에서 환매에 관한 사항을 결의해야 해요.","환매대금은 청구일부터 15일 이내 집합투자규약에서 정한 날에 지급해요."],"k":"단체 여행 경비에서 중간에 빠지는 사람이 위약금을 내면, 그 돈은 여행사가 아니라 남은 일행 경비에 보태지는 거예요.","m":"\"환매: 미래가격 · 수수료는 펀드 재산 귀속 · 15일 이내 지급 · 연기 시 6주 내 총회\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"투자신탁의 법정해지와 임의해지","q":"공모 투자신탁의 해지 사유 중 집합투자업자가 스스로 해지 여부를 선택할 수 있는 임의해지 사유로 가장 적절한 것은?","o":["수익자총회에서 투자신탁 해지를 결의한 경우","투자신탁이 다른 투자신탁에 흡수합병되어 소멸하는 경우","설정 후 1년이 지난 뒤 1개월 동안 계속 원본액이 50억원에 못 미친 경우","수익자 총수가 1인이 된 경우"],"a":2,"c":"투자신탁 해지는 반드시 해지해야 하는 법정해지와, 집합투자업자가 선택할 수 있는 임의해지로 나뉘어요. 신탁계약기간 종료, 수익자총회 해지 결의, 흡수합병으로 인한 소멸, 수익자 1인, 등록 취소는 법정해지예요.","e":"설정 후 1년이 지난 공모 투자신탁의 원본액이 1개월 동안 계속 50억원에 못 미치면 집합투자업자가 해지 여부를 선택할 수 있는 임의해지 사유예요.","w":["수익자총회의 해지 결의는 법정해지 사유예요.","피흡수합병은 법정해지 사유예요.",null,"수익자 총수가 1인이 되면 원칙적으로 법정해지 사유예요."],"k":"법정해지는 '계약 만료로 문을 닫아야 하는 가게', 임의해지는 '손님이 너무 적어 사장이 문 닫을지 고르는 가게'예요.","m":"\"임의해지: 수익자 전원 동의 · 전부 환매청구 · 1년 뒤 1개월 연속 50억 미만 / 나머지는 법정해지\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","t":"조사분석자료와 영업행위규칙","q":"증권사의 영업행위규칙에 대한 자본시장법령상 설명 중 틀린 것은?","o":["최선집행기준은 3개월마다 그 내용이 적정한지 점검해야 한다","고객 주문을 받기 전에 자기 거래인지 중개인지(투자매매업자·투자중개업자 여부)를 고객에게 밝혀야 한다","공모 인수 계약을 맺은 회사의 주식은 상장 첫날부터 40일이 지나기 전까지 리포트를 내놓을 수 없다","기업금융업무 실적에 연동된 성과보수를 조사분석 담당자에게 줄 때는 그 사실을 공시하면 된다"],"a":3,"c":"증권사는 고객 주문 처리, 리서치, 인수 업무가 한 지붕 아래 있어요. 그래서 이해상충이 생기기 쉬운 자리마다 영업행위규칙을 둬요.","e":"리서치 담당자의 보수를 인수·합병 자문 같은 기업금융 실적에 연동하는 것은 공시를 해도 금지돼요.","w":["맞는 설명이에요. 최선집행기준은 석 달에 한 번 점검하고, 바꾸면 그 사실을 공표해요.","맞는 설명이에요. 매매형태는 주문 접수 전에 밝히고, 밝히는 방법에는 제한이 없어요.","맞는 설명이에요. 인수한 증권의 주가를 띄우는 리포트를 막기 위해서예요.",null],"k":"같은 회사 안에서 '물건 파는 팀'이 '평가하는 팀' 월급을 좌우하면 평가표가 기울겠죠? 그래서 아예 연결고리를 끊어요.","m":"\"최선집행 3개월 점검 · 인수 증권 상장 후 40일 리포트 금지 · IB 연동 보수 금지\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"적기시정조치 단계별 조치 내용","q":"금융위원회가 1종 금융투자업자에게 적기시정조치를 하면서 단계와 조치를 짝지었다. 가장 적절한 것은?","o":["경영개선권고 – 영업의 일부 정지","경영개선요구 – 주식의 전부 소각","경영개선권고 – 새로운 업무 진출의 제한","경영개선요구 – 관리인 선임과 임원 직무 정지"],"a":2,"c":"적기시정조치는 재무 상태가 나빠질수록 조치가 세져요. 권고는 체질 개선, 요구는 몸집 줄이기, 명령은 경영권 자체에 손대는 단계예요.","e":"신규업무 진출 제한은 경영개선권고 단계의 조치예요. 권고는 순자본비율 100% 미만일 때, 요구는 50% 미만일 때, 명령은 0% 미만일 때 발동해요.","w":["영업 일부 정지는 경영개선요구 단계의 조치예요.","주식 소각은 경영개선명령 단계의 조치예요.",null,"관리인 선임과 임원 직무집행 정지는 경영개선명령 단계의 조치예요."],"k":"건강검진으로 치면 권고는 '식단 조절', 요구는 '입원 치료', 명령은 '보호자에게 결정권 넘기기'예요.","m":"\"권고: 경비절감·증자·신규업무 제한 / 요구: 점포폐쇄·임원교체·영업 일부정지 / 명령: 주식소각·관리인·합병\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","t":"계열회사 주식의 의결권 행사 방식","q":"M자산운용이 운용하는 펀드가 M자산운용의 계열회사 주식을 담고 있다. 펀드 재산 주식의 의결권 행사에 관한 자본시장법상 설명으로 가장 적절한 것은?","o":["계열회사 주식이 아니라면 투자한도를 넘겨 취득한 주식도 제한 없이 행사할 수 있다","다른 운용사와 계약해 서로의 의결권을 대신 행사하면 제한을 피할 수 있다","투자신탁재산의 의결권은 신탁업자가 투자자 이익을 위해 행사한다","계열회사 주식은 원칙적으로 다른 주주들의 결의 내용에 영향을 주지 않는 중립투표 방식으로 행사한다"],"a":3,"c":"펀드가 가진 주식의 의결권은 투자자를 위해 써야 해요. 그런데 운용사의 계열회사라면 운용사 이익 쪽으로 기울 수 있어 행사 방식을 제한해요.","e":"집합투자업자의 계열회사가 발행한 주식은 원칙적으로 중립투표(섀도보팅) 방식으로 행사해요. 참석한 다른 주주들의 찬반 결과에 영향을 주지 않게 하는 거예요.","w":["동일종목·동일법인 투자한도를 넘겨 취득한 주식은 의결권 행사가 제한돼요.","의결권 제한을 피하려고 제3자와 짜고 교차행사하는 것은 금지돼요.","투자신탁재산의 의결권은 집합투자업자가 행사해요.",null],"k":"가족 회사 투표에서 내 표를 '다른 사람들 표 비율대로' 나눠 넣으면 결과를 내 쪽으로 기울일 수 없죠? 그게 중립투표예요.","m":"\"계열사 주식 = 중립투표 · 한도 초과분 의결권 제한 · 교차행사 금지 · 행사 주체는 집합투자업자\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"이해관계인과의 거래 예외","q":"집합투자업자 V가 펀드 재산으로 한 다음 거래 가운데 자본시장법령상 허용되지 않는 것은?","o":["이해관계인이 되기 6개월 이전에 맺은 계약에 따라 이행한 거래","거래소 시장의 경쟁매매에서 이해관계인의 매도 주문과 체결된 주식 매수","펀드 자금으로 V 자신이 발행한 주식을 산 거래","일반적인 거래조건에 비추어 집합투자기구에 유리한 이해관계인과의 거래"],"a":2,"c":"이해관계인과 거래하면 펀드 재산이 운용사 쪽 사람들 이익에 쓰일 위험이 있어요. 그래서 원칙적으로 막고, 그런 위험이 적은 거래만 예외로 허용해요. 이해관계인에는 집합투자업자의 임직원·대주주·계열회사·계열회사 임직원과 이들의 배우자까지 들어가요.","e":"펀드 계산으로 그 집합투자업자 자신이 발행한 증권을 사는 것은 금지돼요. 이해관계인 거래 예외에도 해당하지 않아요.","w":["허용돼요. 이해관계인이 되기 6개월 이전에 맺은 계약에 따른 거래는 예외예요.","허용돼요. 공개시장 거래는 가격이 투명해 예외예요.",null,"허용돼요. 펀드에 유리한 거래는 예외예요."],"k":"가족에게 가게 물건을 팔 때, 공개 경매였거나 가족이 되기 훨씬 전에 맺은 계약이거나 가게에 더 이득이면 봐주는 거예요.","m":"\"이해관계인 거래 예외: 공개시장 · 6개월 이전 계약 · 펀드에 유리 / 자기 발행 증권 취득 금지\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"하","t":"금융위원회와 증권선물위원회의 구성","q":"금융감독기구의 구성에 관한 설명으로 가장 적절한 것은?","o":["금융위원회는 위원장을 포함한 5명의 위원으로 구성된다","증권선물위원회는 위원장을 포함해 5명으로 구성된다","증권선물위원회 위원장은 금융감독원장이 겸임한다","금융감독원장의 임기는 2년이고 연임이 불가능하다"],"a":1,"c":"금융위원회는 국무총리 소속 합의제 기관(9명)이고, 그 안에 자본시장 불공정거래 조사 등을 맡는 증권선물위원회(5명)가 있어요. 금융감독원은 이들의 지도·감독을 받아 검사 실무를 해요.","e":"증권선물위원회는 위원장을 포함해 5명이고, 위원장은 금융위원회 부위원장이 겸해요.","w":["금융위원회는 위원장·부위원장을 포함해 9명이에요.",null,"증권선물위원회 위원장은 금융위원회 부위원장이 겸임해요.","금융감독원장의 임기는 3년이고 한 차례 연임할 수 있어요."],"k":"금융위원회가 9명이 모이는 큰 회의라면, 증권선물위원회는 그 안에서 자본시장을 맡는 5명짜리 작은 회의예요.","m":"\"금융위 9명 · 증선위 5명(위원장 = 금융위 부위원장) · 금감원장 임기 3년\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":1,"lv":"상","t":"투자매매업자의 자기주식 예외 취득","q":"투자매매업자 K증권은 상장회사이다. K증권이 발행한 주식과 관련한 자본시장법령상 설명 중 틀린 것은?","o":["K증권 주식으로서 증권시장 매매수량단위에 못 미치는 주식은 매도 청약을 받아 장외에서 취득할 수 있다","이렇게 사들인 자기 주식은 3개월 안에 팔아야 한다","K증권 직원이 고객에게 K증권 주식을 사라고 권하는 것은 다른 상장주식 권유와 똑같이 자유롭다","같은 매매에서 K증권이 본인이면서 상대방의 중개인이 되는 것은 원칙적으로 금지된다"],"a":2,"c":"증권사가 자기 회사 주식을 고객에게 권하면 회사 이익과 고객 이익이 정면으로 부딪쳐요. 그래서 권유는 막고, 자투리 주식 정리처럼 꼭 필요한 취득만 짧게 허용해요.","e":"증권사가 고객에게 자기 회사가 발행한 주식을 사고팔라고 권하는 것은 불건전 영업행위로 금지돼요.","w":["맞는 설명이에요. 매매수량단위 미만 주식은 예외적으로 장외 취득이 허용돼요.","맞는 설명이에요. 예외로 취득한 자기주식은 3개월 안에 처분해야 해요.",null,"맞는 설명이에요. 자기계약 금지 규정이에요."],"k":"빵집 직원이 '우리 가게 주식 사세요'라고 권하는 건 손님보다 가게를 위한 말일 수 있어요.","m":"\"자기주식 매매 권유 금지 · 단주 장외취득 OK → 3개월 내 처분\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","t":"시장질서 교란행위의 규제 범위","q":"시장질서 교란행위에 대한 설명 중 틀린 것은?","o":["미공개정보를 여러 단계를 거쳐 전해 들은 다차 정보수령자도 규제 대상이 될 수 있다","알고리즘 거래 프로그램이 고장 나 허수 주문을 쏟아내 시세가 비틀렸다면 시세를 흔들 목적이 없었어도 규제 대상이 될 수 있다","위반으로 얻은 이익이 아무리 커도 과징금은 5억원을 넘을 수 없다","형사처벌이 아니라 과징금으로 제재한다"],"a":2,"c":"시장질서 교란행위는 기존 불공정거래 규제로 잡기 어려운 빈틈을 메우는 제도예요. 대상자를 넓히고 목적 요건을 빼는 대신, 형사처벌이 아닌 과징금으로 제재해요.","e":"과징금 상한은 원칙적으로 5억원이지만, 얻은 이익이나 피한 손실의 1.5배가 그보다 크면 그 금액까지 매길 수 있어요.","w":["맞는 설명이에요. 2차 이상 다차 정보수령자도 대상이에요.","맞는 설명이에요. 시장질서 교란행위는 목적 요건이 없어요.",null,"맞는 설명이에요. 형사처벌 대신 행정제재인 과징금을 부과해요."],"k":"고의 반칙만 잡던 심판이, 실수라도 경기를 망치면 벌금을 매기도록 규칙을 넓힌 거예요.","m":"\"교란행위: 다차 수령자 · 목적 불요 · 과징금 5억 또는 이익 1.5배\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":1,"lv":"상","t":"순자본비율 산정 원칙","q":"금융투자업규정이 정한 순자본비율 산정 원칙에 대한 설명 중 틀린 것은?","o":["영업용순자본에서 이미 차감한 항목에 대해서는 위험액을 산정하지 않는다","한 자산에 시장위험과 신용위험이 겹쳐 있으면 두 위험액을 각각 반영한다","아직 결제되지 않아 재무상태표에 잡히지 않은 거래는 위험액 산정 대상에서 빠진다","연결 대상 종속회사가 없으면 개별재무제표의 장부가액을 기초로 산정한다"],"a":2,"c":"순자본비율은 위험을 빠짐없이, 그러나 두 번 세지 않게 계산해야 정확해요. 그래서 산정 원칙을 따로 정해 둬요.","e":"부외자산과 부외부채도 위험이 있으므로 위험액을 산정해야 해요.","w":["맞는 설명이에요. 이미 뺀 항목에 또 위험액을 매기면 이중 차감이 돼요.","맞는 설명이에요. 위험이 겹치면 각각 산정해 모두 반영해요.",null,"맞는 설명이에요. 연결 대상 회사가 있을 때만 연결재무제표를 써요."],"k":"가계부에 아직 카드값이 안 빠져나갔어도 쓴 돈은 쓴 돈이에요. 반대로 이미 뺀 돈을 또 빼면 안 되고요.","m":"\"순자본비율: 부외항목도 위험액 산정 · 차감항목엔 위험액 X · 위험 겹치면 모두 반영\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"재간접 투자 한도와 사모펀드 편입","q":"공모 주식형 펀드를 운용하는 M자산운용이 다른 펀드의 집합투자증권을 편입하려 한다. 자본시장법령상 운용 제한에 관한 설명으로 틀린 것은? (상장지수집합투자기구 특례 등 예외는 고려하지 않는다)","o":["M자산운용이 운용하는 여러 펀드의 집합투자증권을 합쳐 자산총액의 50%를 넘게 담을 수 없다","한 펀드의 집합투자증권은 자산총액의 20%를 넘게 담을 수 없다","자산총액의 40%를 넘게 다른 펀드에 투자할 수 있는 펀드의 집합투자증권은 편입할 수 없다","사모펀드의 집합투자증권은 금액과 관계없이 한 좌도 편입할 수 없다"],"a":3,"c":"펀드가 다른 펀드에 투자하는 재간접 투자는 보수가 겹치고 위험이 쏠릴 수 있어서 운용사별·펀드별 한도를 둬요. 사모펀드는 완전 금지가 아니라 작은 비중까지만 허용해요.","e":"사모펀드의 집합투자증권은 자산총액의 5%까지는 담을 수 있고, 5%를 넘게 투자하는 것만 금지돼요. 그래서 '한 좌도 편입할 수 없다'는 틀렸어요.","w":["맞아요. 같은 집합투자업자가 운용하는 펀드들의 집합투자증권은 합쳐서 자산총액의 50%가 한도예요.","맞아요. 같은 펀드의 집합투자증권은 자산총액의 20%까지예요. 그 펀드가 발행한 집합투자증권 총수의 20%를 넘게 사들일 수도 없어요.","맞아요. 재간접펀드의 증권을 또 담으면 재간접의 재간접이 되어 보수가 겹겹이 쌓이고 실제 자산을 알기 어려워요.",null],"k":"도시락 가게가 다른 가게 도시락을 떼다 팔 수는 있지만, 한 가게 물건만 너무 많이 팔거나 남의 것을 또 떼어 온 도시락까지 팔면 안 돼요. 비공개 메뉴(사모)는 아주 조금만 섞을 수 있어요.","m":"\"재간접: 같은 운용사 50% · 같은 펀드 20% · 재간접펀드 X · 사모 5%까지\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"중","t":"투자광고에서 금지되는 표시 방법","q":"R증권 마케팅팀이 신문과 홈페이지에 실을 투자광고 시안을 만들었다. 금융소비자보호법·자본시장법 등 투자광고 관련 법령상 허용되는 것은?","o":["감독당국 경영실태평가에서 경쟁사 S증권보다 한 등급 높게 나왔다는 비교표를 싣는다","적격투자자만 가입할 수 있는 사모펀드의 투자 전략과 목표를 신문 전면 광고에 소개한다","작년 운용실적 수익률을 크게 적되, 세금을 빼기 전 숫자인지 뺀 뒤 숫자인지는 따로 적지 않는다","과거 운용실적을 표시하면서 그 실적이 앞으로의 수익을 보장하지 않는다는 문구를 함께 넣는다"],"a":3,"c":"투자광고는 많은 사람이 동시에 보니까 오해를 부르는 비교나 표시, 사모 상품 노출을 막아요.","e":"과거 운용실적을 표시할 때 미래 수익을 보장하지 않는다는 점을 함께 알리는 것은 오히려 지켜야 할 방법이에요. 나머지 셋은 금지되는 표시예요.","w":["금지돼요. 경영실태·위험 평가 결과를 다른 금융투자회사와 비교해 표시하면 감독 결과가 영업 경쟁 수단이 돼요.","금지돼요. 사모로 발행하는 상품의 내용을 불특정 다수가 보는 매체에 광고하면 사실상 공모와 같아져요.","금지돼요. 운용실적을 표시할 때 세전인지 세후인지를 빠뜨리면 투자자가 실제 수익을 잘못 알 수 있어요.",null],"k":"중고차 광고에 연비 숫자만 크게 쓰고 측정 기준을 빼면 오해를 부르죠. 투자광고도 숫자의 기준을 밝혀야 해요.","m":"\"투자광고 금지: 경영실태평가 비교 · 사모상품 노출 · 세전·세후 미표시 · 손실보전 오인\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"운용 담당 요건과 관계인수인 증권 매수","q":"다음은 집합투자업과 투자일임업을 함께 하는 N자산운용의 업무 처리이다. 자본시장법령상 허용되는 것만 모두 고른 것은?\n\n〈보기〉\nㄱ. 부동산운용전문인력 자격이 없는 증권운용 담당자에게 부동산펀드의 건물 매입 결정을 맡겼다.\nㄴ. 주식형 펀드 운용역이 펀드로 대량 매수할 종목을 자기 계좌로 먼저 사 두었다.\nㄷ. 계열 증권사(관계인수인)가 인수한 상장주권을, 인수 후 한 달이 지난 시점에 증권시장에서 투자일임재산으로 매수했다.\nㄹ. 계열 증권사(관계인수인)가 인수한 국채를 인수 직후 투자일임재산으로 매수했다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":2,"c":"운용은 자산 종류에 맞는 전문인력이 하고, 운용 결정과 매매 실행은 나눠요. 계열 인수인이 인수한 증권을 고객 재산으로 사 주는 것은 인수일부터 3개월 동안 원칙적으로 막지만, 떠넘길 위험이 낮은 경우는 예외예요.","e":"ㄷ·ㄹ이 허용돼요. 관계인수인이 인수한 증권이라도 상장주권을 증권시장에서 사거나, 국채·지방채·특수채처럼 떠넘길 위험이 낮은 증권을 사는 것은 예외로 허용돼요. 인수일부터 3개월이 지난 뒤의 매수, 투자일임재산에 유리한 거래도 예외예요. 반면 비상장 주식이나 비상장 회사 전환사채는 3개월 안에 사면 안 돼요.","w":["둘 다 허용되지 않아요. 부동산 운용은 부동산운용전문인력이 맡아야 하고, 펀드 주문을 알고 먼저 사는 것은 선행매매로 금지돼요.","ㄴ은 허용되지 않아요. 펀드 매매 정보를 이용해 자기 계좌로 먼저 사는 선행매매는 금지돼요.",null,"ㄱ은 허용되지 않아요. 운용 전문인력 요건은 자산 종류별로 정해진 법정 요건이라 다른 자격이나 내부 승인으로 대신할 수 없어요."],"k":"건물 사는 결정은 부동산 전문가에게, 주문 버튼은 다른 사람에게 맡겨요. 계열사가 못 판 물건을 고객 바구니에 넣는 것은 막되, 시장에서 산 상장주식이나 국채는 괜찮아요.","m":"\"운용인력은 자산별 자격 · 결정≠실행 · 관계인수인 증권 3개월 금지(예외: 장내 상장주권·국채 등)\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"투자신탁 합병 절차와 투자회사 이익분배","q":"투자신탁의 합병과 투자회사의 이익분배에 관한 자본시장법상 설명으로 〈보기〉에서 옳은 것만 모두 고른 것은?\n\n〈보기〉\nㄱ. 집합투자업자는 운용 중인 투자신탁 두 개를 없애고 새 투자신탁을 세우는 신설합병을 할 수 있다.\nㄴ. 합병을 결의할 수익자총회가 정족수 미달로 결의하지 못하면 그날부터 2주 이내에 연기수익자총회를 소집해야 한다.\nㄷ. 투자신탁을 합병한 집합투자업자는 합병 뒤 지체 없이 그 내용을 금융위원회에 보고해야 한다.\nㄹ. 투자회사가 이익금 전부를 새로 발행하는 주식으로 나눠 주려면 주주총회 특별결의를 거쳐야 한다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1,"c":"투자신탁 합병은 흡수합병만 되고 수익자총회 결의를 거쳐요. 투자회사는 회사 형태라 이익분배에도 회사식 제한이 붙어요.","e":"ㄴ·ㄷ이 옳아요. 합병을 마치면 바로 금융위원회에 그 사실을 알리고, 수익증권이 상장되어 있으면 거래소에도 보고해요. 연기수익자총회는 결의 요건이 완화돼요. 또 투자회사는 이익금을 나눌 때 '순자산액 − 최저순자산액'을 넘겨 나눠 줄 수 없어요.","w":["ㄱ은 틀렸어요. 투자신탁끼리 합칠 때는 한쪽이 다른 쪽을 흡수하는 방식만 허용돼요.",null,"ㄹ은 틀렸어요. 이익금을 새 주식으로 나눠 주는 것은 주식 발행 문제라 이사회 결의로 정해요.","ㄹ이 틀렸어요. 주주총회가 아니라 이사회 결의 사항이에요."],"k":"투자신탁 합병은 두 가게를 닫고 새 간판을 다는 방식은 안 되고, 한 가게가 옆 가게를 흡수하는 방식만 돼요.","m":"\"투자신탁 합병 = 흡수만 · 지체 없이 보고 · 연기총회 2주 / 투자회사 신주 분배 = 이사회\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","t":"업종별 재무건전성 지표와 레버리지비율","q":"금융투자업규정상 금융투자업자의 재무건전성 지표를 설명한 것 중 틀린 것은?","o":["투자매매업자·투자중개업자(1종 금융투자업자)는 순자본비율을 100% 이상 유지해야 한다","신탁업만 하는 3종 금융투자업자는 영업용순자본비율 150% 이상을 지켜야 한다","집합투자업자(2종 금융투자업자)는 최소영업자본액 이상의 자기자본을 갖추고 있어야 한다","레버리지비율은 위험가중치를 반영한 총위험액을 자기자본으로 나눈 지표다"],"a":3,"c":"업종마다 위험 구조가 달라서 재무건전성 지표도 달라요. 1종은 순자본비율, 2종은 최소영업자본액, 3종은 영업용순자본비율을 쓰고, 레버리지비율로 몸집 불리기를 따로 막아요.","e":"레버리지비율은 위험을 따로 가중하지 않고 총자산을 자기자본으로 나눠 '자기 돈의 몇 배로 몸집을 키웠는지' 보는 지표예요. 위험 기준 지표만으로는 잡히지 않는 덩치 불리기를 막으려고 함께 봐요.","w":["맞아요. 1종은 (영업용순자본 − 총위험액) ÷ 필요유지자기자본으로 구한 순자본비율을 100% 이상 지켜요.","맞아요. 신탁업만 하는 회사는 이름이 비슷한 영업용순자본비율(영업용순자본 ÷ 총위험액)로 150% 선을 지켜요.","맞아요. 집합투자업자는 비율이 아니라 최소영업자본액이라는 금액 기준으로 관리해요.",null],"k":"순자본비율이 '체력 검사'라면 레버리지비율은 '자기 돈 대비 몸집'이에요. 체력이 좋아도 빚으로 몸집만 키우면 위험하니까 따로 재요.","m":"\"1종 순자본비율 100% · 2종 최소영업자본액 · 3종 영업용순자본비율 150% · 레버리지 = 총자산 ÷ 자기자본\"","rev":0},{"s":3,"sec":"자본시장 관련 법규","star":2,"lv":"상","t":"정정신고서의 효력발생 시기","q":"2026년 11월 현재 「증권의 발행 및 공시 등에 관한 규정」상 정정신고서의 효력발생에 관한 설명으로 틀린 것은?","o":["일괄신고서를 정정하는 신고서는 원칙적으로 수리된 날부터 3일이 지난 날에 효력이 생긴다","시장금리 변동에 맞춰 사채의 발행가액이나 이자율만 바꾸는 정정신고서는 원칙적으로 수리된 다음 날 효력이 생긴다","상장을 위해 주식을 공모하는 회사가 공모 주식 수를 당초 신고한 수의 115%로 늘리는 정정을 해도 당초의 효력발생일은 그대로다","상장을 위해 주식을 공모하는 회사가 공모 주식 수를 당초 신고한 수의 70%로 줄이는 정정을 해도 당초의 효력발생일은 그대로다"],"a":3,"c":"증권신고서를 고치면 원칙적으로 정정신고서가 수리된 날부터 효력발생 기간을 다시 세요. 다만 투자 판단에 큰 영향이 없는 정정은 기간을 짧게 하거나 당초 날짜를 유지해 줘요.","e":"공모 주식 수를 당초의 80% 이상 120% 이하로 바꾸는 경우에만 당초 효력발생일에 영향이 없어요. 70%로 줄이면 이 범위를 벗어나므로 특례를 받을 수 없어요. 참고로 신고서의 효력이 생겼다고 해서 정부가 기재 내용의 진실성이나 증권의 가치를 보증하는 것은 아니에요.","w":["맞아요. 일괄신고서의 정정신고서는 원칙적으로 수리일부터 3일이 지나면 효력이 생겨요.","맞아요. 발행조건을 조금 조정하는 정도라 수리된 다음 날 효력이 생겨요.","맞아요. 지분증권 수를 당초의 80% 이상 120% 이하 범위에서 바꾸면 당초 효력발생일에 영향이 없어요. 115%는 이 범위 안이에요.",null],"k":"시험 답안의 글자 몇 개를 고친 정도면 마감 시간을 그대로 두지만, 답을 크게 바꾸면 다시 검토할 시간이 필요한 것과 같아요.","m":"\"정정 효력: 일괄신고 정정 3일 경과 · 금리 따른 발행조건 변경 다음 날 · 지분 수량 80~120% 당초일 유지\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"하","t":"집합투자증권 판매회사 변경","q":"투자자 김씨는 A증권에서 가입한 공모펀드를 B은행으로 옮기려고 판매회사 변경을 신청하였다. 협회 규정상 이 처리에 관한 설명으로 가장 적절한 것은?","o":["변경의 효력이 생기는 날이 환매수수료 부과기간 안이면 A증권은 환매수수료를 받을 수 있다","옮긴 뒤 환매수수료 면제 기간은 김씨가 그 펀드에 처음 가입한 날부터 계산한다","전산 관리가 곤란하거나 세제상 문제가 있는 펀드라도 판매회사는 반드시 변경해 주어야 한다","B은행은 변경 업무를 처리해 준 대가로 김씨에게 별도 수수료를 받을 수 있다"],"a":1,"c":"판매회사 변경제도는 투자자가 펀드를 해지하지 않고 판매회사만 옮길 수 있게 한 제도예요. 옮기는 것 때문에 투자자가 손해를 보지 않게 하는 것이 핵심이에요.","e":"판매회사를 옮겨도 펀드 가입 자체는 그대로 이어지므로, 환매수수료 면제 기간도 처음 가입한 날부터 계산해요. 변경일부터 새로 세지 않아요.","w":["환매수수료 부과기간 안이라도 판매회사 변경을 이유로 환매수수료를 받을 수 없어요.",null,"원칙은 모든 펀드에 적용하지만, 전산상 관리가 곤란하거나 세제상 문제가 있으면 예외로 변경할 수 없어요.","변경 절차의 대가로 환매수수료는 물론 별도 비용도 청구할 수 없어요."],"k":"통신사 번호이동처럼 펀드는 그대로 두고 가게만 바꾸는 거예요. 그래서 옮긴다고 위약금(환매수수료)이나 수수료를 물리지 않아요.","m":"판매사 변경: 수수료 0원 · 기산일은 첫 가입일","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","t":"인수 주관업무 제한(보유 지분)","q":"C증권이 이해관계인과 합하여 보유한 발행회사별 주식등의 비율이 다음과 같다. 협회 「증권 인수업무 등에 관한 규정」상 각 회사의 기업공개 주관업무 처리로 옳은 것은? (단, C증권 단독 보유분은 모두 5% 미만이고, 혁신기업 특례는 없다)\n• 갑사: 3%   • 을사: 7%   • 병사: 12%","o":["갑사 단독 주관 · 을사 단독 주관 · 병사 공동 주관","갑사 단독 주관 · 을사 공동 주관 · 병사 주관 불가","갑사 공동 주관 · 을사 공동 주관 · 병사 주관 불가","갑사 단독 주관 · 을사 주관 불가 · 병사 주관 불가"],"a":1,"c":"금융투자회사가 발행회사 주식을 많이 갖고 있으면 공모가격을 공정하게 정하기 어려워요. 그래서 보유 비율에 따라 주관업무를 제한해요.","e":"이해관계인과 합해 5% 미만이면 단독 주관이 가능하고, 5% 이상 10% 미만이면 다른 금융투자회사와 공동으로 주관해야 하며, 10% 이상이면 주관할 수 없어요(혁신기업은 기준이 10%·15%로 완화돼요). 그래서 갑사(3%) 단독, 을사(7%) 공동, 병사(12%) 불가예요.","w":["을사(7%)는 5% 이상이라 단독 주관이 안 되고, 병사(12%)는 10% 이상이라 아예 주관할 수 없어요.",null,"갑사(3%)는 5% 미만이라 공동 주관 의무가 없어요.","을사(7%)는 10% 미만이라 주관 금지가 아니라 공동 주관 대상이에요."],"k":"내 회사 주식을 많이 가진 증권사가 혼자 가격을 정하면 팔이 안으로 굽겠죠? 조금(5~10%) 가졌으면 다른 증권사와 같이, 많이(10%↑) 가졌으면 아예 빠지라는 규칙이에요.","m":"주관업무: 5% 미만 단독 · 5~10% 공동 · 10%↑ 불가","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"재산상 이익의 가액 산정","q":"금융투자협회 규정상 금융투자회사가 거래상대방에게 제공하는 재산상 이익에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 금전을 제공했다면 제공한 금액 전부를 가액으로 본다.\nㄴ. 물품을 제공했다면 그 물품을 사는 데 든 비용으로 가액을 산정한다.\nㄷ. 임직원과 거래상대방이 함께한 접대는 전체 비용 중 거래상대방이 차지한 비율만큼을 가액으로 본다.\nㄹ. 재산상 이익을 제공한 내역은 1년 동안만 보관하면 된다.","o":["1개","2개","3개","4개"],"a":2,"c":"재산상 이익의 가액은 실제로 상대방에게 돌아간 몫을 기준으로 따져요. 금전은 그 금액, 물품은 구입 비용, 접대는 소요 비용이 기준이에요.","e":"옳은 것은 ㄱ, ㄴ, ㄷ, 3개예요. 재산상 이익을 제공하거나 받은 내역은 5년 이상 기록·보관해야 하므로 ㄹ이 틀렸어요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄴ(물품은 구입 비용)도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 기록 보관은 5년 이상이에요."],"k":"밥을 같이 먹었으면 상대가 먹은 몫만, 선물은 산 가격만 계산해요. \"얼마나 받았나\"를 실제 몫으로 따지는 거예요.","m":"금전=금액 · 물품=구입비 · 동석 접대=상대 몫 · 기록 5년","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"조사분석자료 작성·공표","q":"D증권 리서치센터의 조사분석자료 처리에 관한 설명으로 협회 규정상 가장 적절하지 않은 것은?","o":["발행회사에서 받은 자료를 인용할 때는 출처를 밝히고 신뢰도를 따로 검증해야 한다","금융투자분석사의 확인을 받지 못한 자료는 공표는 못 하지만 우수 고객 몇 명에게 미리 제공할 수는 있다","조사분석자료를 공표한 뒤 24시간이 지나기 전에는 D증권이 자기 계산으로 그 종목을 매매해서는 안 된다","외부 전문가가 작성한 보고서도 작성자의 성명을 적으면 D증권 이름으로 공표할 수 있다"],"a":1,"c":"조사분석자료는 많은 투자자가 믿고 쓰는 정보라서, 누가 썼는지와 근거가 분명해야 하고 분석사의 확인을 거쳐야 해요.","e":"금융투자분석사의 확인을 받지 않은 조사분석자료는 공표할 수 없을 뿐 아니라 특정인에게 제공하는 것도 금지돼요. 일부 고객에게만 먼저 주면 정보 격차로 불공정해져요.","w":["외부 자료는 출처 표시와 함께 신뢰도 검증까지 해야 해요.",null,"공표 후 24시간이 지나기 전에 회사가 그 종목을 자기 계산으로 매매하는 것은 금지돼요.","제3자가 작성한 자료도 그 제3자의 성명(법인이면 법인명)을 적으면 공표할 수 있어요."],"k":"검수 안 받은 리포트를 \"VIP한테만 살짝\" 주는 건 시험지 유출과 같아요. 공개도, 몰래 주기도 둘 다 안 돼요.","m":"분석사 확인 없으면: 공표 ✕ · 특정인 제공도 ✕","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"t":"투자광고 규제","q":"금융투자회사의 투자광고에 관한 설명으로 가장 적절하지 않은 것은?","o":["투자광고를 하기 전에 준법감시인의 사전 확인을 받아야 한다","손실을 보전해 주겠다는 표현은 일반투자자 대상 광고에서만 금지되고 전문투자자 대상 광고에서는 허용된다","과거 운용실적을 표시할 때는 미래 수익을 보장하지 않는다는 내용을 함께 표시해야 한다","투자광고는 원칙적으로 금융투자협회의 심사를 받아야 한다"],"a":1,"c":"투자광고는 많은 사람에게 동시에 영향을 주기 때문에 내부(준법감시인)와 외부(협회) 두 단계로 걸러요.","e":"손실보전이나 이익보장을 약속하는 표현은 투자자 유형과 관계없이 금지돼요.","w":["준법감시인 사전 확인이 필요해요.",null,"과거 실적이 미래를 보장하지 않는다는 표시가 필요해요.","협회 심사를 받는 것이 원칙이에요."],"k":"\"원금 보장!\" 같은 말은 상대가 전문가라도 쓰면 안 되는 금지어예요.","m":"투자광고: 준법감시인 확인 → 협회 심사 · 손실보전 표현은 누구에게나 X"},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"t":"재산상 이익 제공 한도","q":"금융투자회사의 재산상 이익 제공에 관한 협회 규정의 내용으로 가장 적절하지 않은 것은?","o":["재산상 이익 제공 시 준법감시인 보고 등 내부통제 절차를 거친다","제공 내역은 기록하고 일정 기간 보관한다","일정 금액을 넘으면 인터넷 홈페이지에 공시한다","거래상대방 1인당 연간 500만원의 한도가 적용된다"],"a":3,"c":"재산상 이익 제공 규제는 금액 한도 대신 내부통제 절차와 공시를 강화하는 방식으로 바뀌었어요.","e":"거래상대방 1인당 연간 한도 규제는 폐지되었어요. 대신 내부통제 절차, 기록·보관, 공시로 관리해요.","w":["내부통제 절차를 거쳐요.","기록·보관해요.","일정 금액 초과 시 공시해요.",null],"k":"\"얼마까지만\"이 아니라 \"얼마를 줬는지 투명하게\"로 바뀌었어요.","m":"재산상 이익: 한도 폐지 → 내부통제 · 기록 · 공시"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"재산상 이익에서 제외되는 것","q":"증권사가 거래처에 준 다음 것 가운데 협회 규정상 재산상 이익 제공으로 보지 않는 것은?","o":["거래상대방에게 준 현금","거래상대방에게 제공한 고가 골프 접대","회사 리서치센터가 직접 만든 분석 보고서","거래상대방에게 준 고가 상품권"],"a":2,"c":"재산상 이익은 거래상대방에게 경제적 가치를 주는 것이지만, 업무상 통상적인 정보 제공은 제외해요.","e":"금융투자회사가 자체적으로 작성한 조사분석자료는 재산상 이익으로 보지 않아요.","w":["현금은 재산상 이익이에요.","고가 접대는 재산상 이익이에요.",null,"상품권은 재산상 이익이에요."],"k":"회사가 직접 만든 리포트를 주는 건 정상적인 정보 제공이에요.","m":"재산상 이익 아님: 자체 조사분석자료 등"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"상","rev":0,"t":"배타적 사용권 침해 배제","q":"증권회사가 자체 개발한 상품으로 배타적 사용권을 받았는데 다른 회사가 사실상 같은 상품을 내놓았다. 침해 배제 신청이 접수되면 위원회는 접수일부터 며칠 이내에 심의해야 하는가?","o":["3영업일","7영업일","15영업일","30영업일"],"a":1,"c":"배타적 사용권은 새로운 상품을 개발한 회사에 일정 기간 독점 판매권을 주는 제도예요.","e":"침해 배제 신청이 접수되면 위원장은 접수일부터 7영업일 이내에 위원회를 소집해 심의해요.","w":["기간이 너무 짧아요.",null,"기간이 너무 길어요.","기간이 너무 길어요."],"k":"신상품 아이디어를 베꼈다는 신고가 들어오면 일주일 남짓 안에 심의해요.","m":"배타적 사용권 침해배제 신청 → 7영업일 이내 심의"},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"t":"펀드 투자광고의 목표수익률","q":"공모펀드 투자광고 심의에서 허용되지 않는 표현은?","o":["펀드의 투자 대상과 전략 설명","\"3년 동안 연 7% 안팎의 수익이 기대됩니다\"라는 목표수익률 제시","주요 투자위험 안내","수수료와 보수 안내"],"a":1,"c":"펀드 광고는 미래 수익을 약속하는 것처럼 보이는 표현을 엄격히 제한해요.","e":"집합투자증권 투자광고에서 장래의 목표수익률을 제시하는 것은 허용되지 않아요.","w":["투자 대상·전략 설명은 가능해요.",null,"위험 안내는 필요해요.","수수료 안내는 필요해요."],"k":"\"연 7% 기대\" 같은 문구는 약속처럼 들려서 쓰면 안 돼요.","m":"펀드 광고: 목표수익률 제시 X"},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"t":"펀드 운용실적 광고 요건","q":"펀드의 운용실적을 투자광고에 표시하기 위한 요건으로 가장 적절한 것은?","o":["설정일부터 6개월 이상, 순자산 50억원 이상","설정일부터 1년 이상, 순자산 100억원 이상","설정일부터 3년 이상, 순자산 500억원 이상","설정 기간과 규모에 관계없이 표시할 수 있다"],"a":1,"c":"운용 기간이 짧거나 규모가 작은 펀드의 실적은 우연일 수 있어 광고에 쓰지 못하게 해요.","e":"기준일 현재 설정일부터 1년 이상 지나고 순자산총액이 100억원 이상이어야 운용실적을 광고할 수 있어요.","w":["요건보다 낮아요.",null,"요건보다 높아요.","요건이 있어요."],"k":"최소 1년, 100억 이상은 돼야 \"실력\"이라고 말할 수 있어요.","m":"운용실적 광고: 설정 1년 이상 + 순자산 100억 이상"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"연계 판매 시 투자권유 자격","q":"예금과 묶어 펀드를 판매하는 등 펀드를 다른 상품 판매와 연계하는 경우, 펀드 투자권유를 할 수 있는 사람은?","o":["해당 지점의 모든 직원","펀드투자권유자문인력으로 등록된 사람","예금 담당 창구 직원","본사 마케팅 담당자"],"a":1,"c":"펀드는 원본손실 가능성이 있는 상품이라 자격을 갖춘 사람만 권유할 수 있어요.","e":"연계 판매의 경우에도 펀드 투자권유는 펀드투자권유자문인력으로 등록된 사람만 할 수 있어요.","w":["자격이 필요해요.",null,"예금 업무 담당자도 자격이 있어야 해요.","자격 등록이 필요해요."],"k":"펀드 이야기는 펀드 자격증 있는 사람만 할 수 있어요.","m":"펀드 권유 = 펀드투자권유자문인력만"},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"t":"금융투자분석사의 매매 제한","q":"금융투자분석사의 개인 매매에 관한 협회 규정의 내용으로 가장 적절한 것은?","o":["조사분석자료 공표 직후 바로 반대 방향으로 매매할 수 있다","조사분석자료 공표 후 7일 동안은 그 투자의견과 같은 방향으로만 매매할 수 있다","자기 계산으로 하는 매매에는 아무 제한이 없다","조사분석자료를 공표하기 전에 미리 매매해 두는 것이 허용된다"],"a":1,"c":"분석사가 자기 리포트를 이용해 이익을 보면 투자자를 해칠 수 있어서 매매를 제한해요.","e":"조사분석자료 공표 후 24시간이 지나기 전에는 매매할 수 없고, 공표 후 7일 동안은 투자의견과 같은 방향으로만 매매할 수 있어요.","w":["반대 방향 매매는 금지돼요.",null,"자기 매매에 제한이 있어요.","공표 전 매매는 금지돼요."],"k":"\"사라\"고 써 놓고 본인은 팔면 안 돼요.","m":"분석사 매매: 공표 후 24시간 금지 · 7일간 같은 방향만"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"금융투자분석사와 기업금융부서","q":"금융투자분석사의 이해상충 방지에 관한 설명으로 가장 적절한 것은?","o":["조사분석자료에 관해 기업금융 부서와 자유롭게 협의할 수 있다","기업금융 부서와의 협의는 원칙적으로 제한되지만, 준법감시부서를 통해 자료를 주고받는 등 일정 요건을 갖추면 가능하다","분석사는 기업금융 업무를 겸할 수 있다","분석사의 보수는 기업금융 수익과 연동해야 한다"],"a":1,"c":"기업금융 부서는 고객 회사와 거래 관계가 있어 분석사의 의견을 왜곡하게 만들 수 있어요.","e":"기업금융 부서와 협의하는 것은 원칙적으로 제한되지만, 준법감시부서를 거치고 입회하는 등 요건을 갖추면 할 수 있어요.","w":["협의는 원칙적으로 제한돼요.",null,"겸직은 이해상충을 키워요.","기업금융 연동 보수는 금지돼요."],"k":"분석사와 기업금융 부서 사이에는 \"감독관(준법감시부서)\"이 있어야 해요.","m":"분석사-기업금융 협의: 원칙 제한 · 준법감시부서 경유 시 가능"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"상","rev":0,"t":"불성실 수요예측 참여자 제재","q":"협회 규정상 기업공개 수요예측에 불성실하게 참여한 기관투자자에 대한 제재로 가장 적절한 것은?","o":["제재금만 부과할 수 있다","제재금을 부과하면서 고유재산에 한해 수요예측 참여 제한을 함께 부과할 수 있다","어떤 제재도 할 수 없다","형사처벌만 할 수 있다"],"a":1,"c":"수요예측은 공모가격을 정하는 중요한 절차라 허수 청약 등 불성실 참여를 제재해요.","e":"불성실 수요예측 참여자에게 제재금을 부과하면서, 고유재산에 한해 수요예측 참여 제한을 함께 부과할 수 있어요.","w":["참여 제한을 함께 부과할 수 있어요.",null,"제재가 가능해요.","협회 자율 제재예요."],"k":"약속을 안 지킨 참여자에게 벌금도 물리고 일정 기간 참여도 막을 수 있어요.","m":"불성실 수요예측: 제재금 + (고유재산) 참여 제한 병과"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"대표주관계약 신고","q":"기업공개를 위한 주식 인수를 의뢰받은 금융투자회사가 발행인과 대표주관계약을 맺은 경우 협회에 신고해야 하는 기한은?","o":["계약 체결일부터 5영업일 이내","계약 체결일부터 1개월 이내","상장일 이후","신고 의무 없음"],"a":0,"c":"기업공개 절차를 투명하게 관리하기 위해 대표주관계약 체결 사실을 협회에 알리도록 해요.","e":"대표주관계약 체결일부터 5영업일 이내에 협회에 신고해야 해요.","w":[null,"기한이 너무 길어요.","상장 전에 신고해야 해요.","신고 의무가 있어요."],"k":"계약하면 일주일(5영업일) 안에 협회에 알려요.","m":"대표주관계약 → 5영업일 이내 협회 신고"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"투자자 성향과 권유 범위","q":"협회의 표준투자권유준칙에 따른 투자권유에 관한 설명으로 가장 적절한 것은?","o":["투자자 성향보다 위험이 높은 상품도 직원 판단으로 적극 권유할 수 있다","투자자 정보를 파악해 투자자 성향을 분류하고, 그 성향에 맞는 상품을 권유한다","투자자 정보는 파악하지 않아도 된다","모든 투자자에게 같은 상품을 권유한다"],"a":1,"c":"표준투자권유준칙은 적합성 원칙을 실무에서 구체적으로 적용하는 방법을 정해요.","e":"투자자 정보를 파악해 위험 성향을 분류하고, 그 성향에 맞는 위험등급의 상품을 권유해요.","w":["성향보다 위험한 상품은 권유하지 않아요.",null,"정보 파악이 출발점이에요.","투자자마다 맞는 상품이 달라요."],"k":"고객 \"체력\"을 재고, 그 체력에 맞는 운동(상품)만 권해요.","m":"정보 파악 → 성향 분류 → 성향에 맞는 상품 권유"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"펀드 판매 시 설명 사항","q":"집합투자증권을 판매할 때 투자자에게 설명해야 할 사항으로 가장 거리가 먼 것은?","o":["판매보수와 판매수수료","환매 방법과 환매수수료","투자위험","판매 직원의 개인 투자 실적"],"a":3,"c":"펀드는 비용과 환매 조건, 위험을 알아야 제대로 판단할 수 있어요.","e":"판매보수·수수료, 환매 방법·수수료, 투자위험 등은 설명 사항이에요. 판매 직원의 개인 투자 실적은 설명 사항이 아니에요.","w":["비용 설명이 필요해요.","환매 조건 설명이 필요해요.","위험 설명이 필요해요.",null],"k":"\"얼마 들고, 언제 어떻게 빼고, 얼마나 위험한지\"를 알려 줘야 해요.","m":"펀드 설명: 보수·수수료 · 환매 · 위험"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","rev":0,"t":"신상품 배타적 사용권","q":"금융투자협회 규정상 새로운 금융투자상품을 개발한 회사에 부여하는 배타적 사용권에 관한 설명으로 가장 적절한 것은?","o":["독창성·국내 최초성 등을 심사해 일정 기간(3개월 이상 6개월 이내) 다른 회사의 같은 상품 판매를 제한한다","영구적으로 독점 판매권을 준다","모든 신상품에 자동으로 부여된다","배타적 사용권 기간에도 다른 회사가 자유롭게 같은 상품을 판매할 수 있다"],"a":0,"c":"협회는 금융투자회사의 상품 개발을 장려하기 위해 신상품 보호 제도를 운영해요.","e":"신상품 심의위원회가 독창성, 국내 최초성, 고객 편익 등을 심사해 3개월 이상 6개월 이내의 배타적 사용권을 부여해요.","w":[null,"기간이 정해져 있어요.","심사를 거쳐 부여해요.","그 기간 동안 다른 회사 판매가 제한돼요."],"k":"처음 만든 회사가 몇 달 동안은 혼자 팔 수 있어요.","m":"배타적 사용권 = 신상품 심의 · 3~6개월"},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"금융투자전문인력 등록과 보수교육","q":"금융투자전문인력 관리에 관한 협회 규정의 내용으로 틀린 것은?","o":["이미 다른 회사 소속 전문인력으로 올라가 있는 사람은 협회가 등록을 거부할 수 있다","등록의 효력이 정지된 기간에는 해당 전문인력 업무를 맡길 수 없다","보수교육은 2년에 1회 이상 이수하면 된다","퇴직은 등록 말소 사유이므로 회사는 퇴직 사실을 협회에 보고해야 한다"],"a":2,"c":"금융투자전문인력은 협회에 등록해야 업무를 할 수 있어요. 바뀌는 제도와 상품을 따라가도록 해마다 보수교육을 받아야 해요.","e":"보수교육은 매년 1회 이상 이수해야 해요. 예전에는 2년마다였지만 규정 개정으로 매년으로 바뀌었어요.","w":["맞는 설명이에요. 이미 다른 회사 전문인력으로 등록된 경우는 등록 거부 사유예요.","맞는 설명이에요. 효력정지 기간에는 그 업무를 수행하게 할 수 없어요.",null,"맞는 설명이에요. 퇴직은 등록 말소 사유이고 회사는 이를 협회에 보고해요."],"k":"운전면허처럼 한 번 따고 끝이 아니라, 해마다 안전교육을 받아야 계속 운전대를 잡을 수 있는 셈이에요.","m":"\"보수교육: 매년 1회↑ (예전 2년 → 지금 매년)\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","t":"조사분석자료 공표 금지 대상","q":"W증권의 주식 보유 현황이 다음과 같을 때, 협회 규정상 W증권이 조사분석자료를 공표할 수 없는 대상은?","o":["W증권이 발행주식 총수의 3%를 보유한 갑사의 주식","W증권이 발행주식 총수의 0.5%를 보유한 을사의 주식","W증권이 발행주식 총수의 6%를 보유한 병사의 주식","W증권이 주식을 전혀 보유하지 않은 정사의 주식"],"a":2,"c":"리서치를 내는 회사가 분석 대상 회사 주식을 많이 갖고 있으면 투자의견이 한쪽으로 기울 수 있어요. 그래서 지분이 크면 아예 공표를 막고, 중간이면 알리게 해요. 자신이 발행한 금융투자상품도 공표 금지 대상이에요.","e":"금융투자회사는 발행주식 총수의 5% 이상을 보유한 법인의 주식에 대해서는 조사분석자료를 공표할 수 없어요. 1% 이상 5% 미만이면 이해관계를 밝히고 공표할 수 있어요.","w":["1% 이상 5% 미만이면 그 이해관계를 자료에 밝히고 공표할 수 있어요.","1% 미만이면 보유 비율로는 이해관계 고지 대상도 아니에요.",null,"보유 지분이 없으면 지분 때문에 공표가 제한되지 않아요."],"k":"심사위원이 참가자의 큰 주주라면 아예 심사에서 빠지고, 작은 주주라면 '저 주주예요'라고 밝히고 심사하는 거예요.","m":"\"조사분석: 1%↑ 고지 후 공표 · 5%↑ 공표 금지 · 자기 발행 상품 공표 금지\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"FX마진거래의 대상과 증거금","q":"개인투자자가 FX마진거래(유사해외통화선물거래)를 시작하려 한다. 협회 규정 등에 비추어 옳은 것은?","o":["원화와 미국달러 사이의 환율도 거래 대상이 될 수 있다","투자자 명의로 해외 딜러와 직접 계약해 거래한다","기준통화 10만 단위당 미화 1만달러 이상의 위탁증거금을 예탁해야 한다","자본시장법상 장외파생상품에 속한다"],"a":2,"c":"FX마진거래는 적은 증거금으로 큰 금액의 외국 통화끼리 환율 차익을 노리는 고위험 거래예요. 그래서 거래 대상, 명의, 증거금을 엄격히 정해 뒀어요.","e":"FX마진거래는 기준통화 10만 단위를 1계약으로 하고, 1계약당 미화 1만달러 이상의 위탁증거금을 받아야 해요.","w":["원화가 들어간 통화쌍은 대상이 아니에요. 원화를 뺀 이종통화끼리만 거래해요.","거래는 금융투자회사 명의로 하고, 손익은 투자자에게 돌아가요(투자자 계산).",null,"해외 파생상품시장 거래로 보아 장내파생상품으로 분류돼요."],"k":"1만달러를 맡기고 10만 단위를 굴리는 '10배 확대경' 거래예요. 조금만 움직여도 손익이 크게 보여요.","m":"\"FX마진: 원화 제외 이종통화 · 회사 명의 + 투자자 계산 · 10만 단위당 1만달러 · 장내파생\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"집합투자증권 판매 시 금지행위","q":"Y증권 지점의 펀드 판매 관련 행위 중 협회 규정상 허용되는 것은?","o":["펀드를 많이 팔아 준 대가로 운용사에 그 펀드의 주식 매매주문을 Y증권에 몰아 달라고 요청했다","특별한 이유 없이 공모펀드의 판매를 거부했다","계열 운용사의 펀드를 권유하면서 그 운용사가 Y증권의 계열회사라는 사실을 알렸다","투자자 이익과 관계없이 판매보수가 높다는 이유로 특정 펀드를 우선 권유했다"],"a":2,"c":"펀드 판매회사는 투자자와 운용사 사이에 서 있어요. 그래서 운용사와 뒷거래를 하거나, 회사 이익 때문에 권유를 비틀지 못하게 금지행위를 정해 둬요.","e":"계열회사가 운용하는 펀드를 권할 때는 '우리 계열사 펀드'라는 점을 알려야 해요. 알린 것은 규정을 지킨 거예요.","w":["판매 대가로 집합투자재산의 매매주문을 자기 회사에 달라고 요구하는 것은 금지돼요.","정당한 사유 없이 공모펀드 판매를 거절하는 것은 금지돼요.",null,"판매보수가 많다는 이유로 투자자 이익과 무관하게 특정 펀드를 권유하면 안 돼요."],"k":"중개인이 '많이 팔아 줬으니 다른 일감도 달라'고 운용사에 손 벌리거나, 수수료 많은 상품만 밀면 손님은 뒷전이 되겠죠?","m":"\"판매사 금지: 매매주문 배정 요구 · 정당한 사유 없는 판매 거부 · 보수 많은 펀드 우선 권유 / 계열사면 알리기\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":2,"lv":"중","t":"약관의 보고와 사전신고","q":"금융투자회사의 약관에 관한 협회 규정의 내용으로 가장 적절한 것은?","o":["외국 집합투자증권 매매거래 표준약관은 회사 사정에 맞게 고쳐 쓸 수 있다","금융투자업 관련 표준약관은 금융감독원장이 정한다","투자자 권리에 중대한 영향을 주는 약관 변경도 시행 후 보고하면 된다","약관을 제정·변경하면 원칙적으로 그 후 7일 이내에 협회에 보고한다"],"a":3,"c":"약관은 회사와 투자자가 맺는 계약의 틀이에요. 협회가 표준약관을 만들고, 회사가 약관을 바꾸면 보고하거나 미리 신고해서 투자자에게 불리한 조항을 걸러요.","e":"약관을 만들거나 고치면 원칙적으로 7일 안에 협회에 보고해요. 투자자 권리·의무에 중대한 영향을 줄 수 있으면 시행예정일보다 10영업일 앞서 미리 신고해야 해요.","w":["외국 집합투자증권 매매거래 표준약관은 수정해서 쓸 수 없어요.","표준약관은 한국금융투자협회가 정해요.","중대한 영향이 있으면 시행예정일보다 10영업일 앞서 신고해야 해요.",null],"k":"학교 교칙을 바꾸면 교육청에 알려야 하는데, 학생 권리에 큰 영향을 주는 교칙은 바꾸기 전에 미리 검사를 받는 것과 같아요.","m":"\"약관: 표준약관은 협회 · 사후보고 7일 · 중대하면 10영업일 전 사전신고\"","rev":0},{"s":3,"sec":"한국금융투자협회규정","star":1,"lv":"하","t":"금융투자전문인력의 종류별 업무","q":"금융투자전문인력의 종류와 업무를 짝지은 것으로 가장 적절한 것은?","o":["조사분석인력 – 조사분석자료를 작성만 하고 심사·승인 업무는 할 수 없음","투자상담관리인력 – 투자권유대행인과 투자권유자문인력의 업무를 관리·감독","위험관리전문인력 – 일반사무관리회사에서 펀드 재산을 계산","투자운용인력 – 일반투자자를 상대로 펀드 투자를 권유"],"a":1,"c":"금융투자전문인력은 하는 일에 따라 투자권유자문인력, 투자상담관리인력, 투자운용인력, 조사분석인력, 위험관리전문인력 등으로 나뉘어요. 협회에 등록해야 해당 업무를 할 수 있어요.","e":"투자상담관리인력은 지점·영업소의 투자권유대행인과 투자권유자문인력을 관리·감독해요.","w":["조사분석인력은 조사분석자료 작성과 함께 심사·승인 업무도 해요.",null,"장외파생상품을 다루는 회사의 위험관리는 위험관리전문인력이 맡아요. 펀드 재산 계산은 집합투자재산계산전문인력의 업무예요.","투자운용인력은 펀드·신탁·투자일임 재산을 운용해요. 권유는 투자권유자문인력의 몫이에요."],"k":"병원으로 치면 진료(권유), 수간호사(관리·감독), 수술(운용), 검사 판독(분석), 감염관리(위험관리)처럼 역할이 정해져 있어요.","m":"\"투자상담관리 = 자문인력·대행인 감독 · 운용인력 = 재산 운용 · 분석인력 = 작성+심사·승인\"","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"상","t":"CPPI 위험자산 배분","q":"〈보기〉와 같이 고정비율 포트폴리오 보험(CPPI) 전략을 실행할 때, 지금 위험자산과 안전자산에 배분할 금액을 순서대로 짝지은 것은?\n• 펀드 평가액: 220억원\n• 1년 뒤 만기 보장액: 212억원\n• 무위험이자율: 연 6%\n• 승수: 4","o":["20억원 — 200억원","32억원 — 188억원","140억원 — 80억원","80억원 — 140억원"],"a":3,"c":"CPPI는 만기에 보장할 금액의 현재가치(최저보장가치)를 지키고, 그 위의 여유분(쿠션)에 승수를 곱한 만큼만 위험자산에 투자하는 전략이에요.","e":"최저보장가치 = 212 ÷ 1.06 = 200억원. 쿠션 = 220 − 200 = 20억원. 위험자산 = 4 × 20 = 80억원, 안전자산 = 220 − 80 = 140억원.","f":"위험자산 = 승수 × (평가액 − 보장액의 현재가치)","w":["승수를 빠뜨리고 쿠션 20억원을 그대로 위험자산으로 봤어요.","보장액 212억원을 할인하지 않고 쿠션을 8억원으로 잡았어요(4 × 8 = 32).","위험자산과 안전자산을 뒤바꿨어요.",null],"k":"꼭 지켜야 할 돈(200억)은 안전하게 두고, 남는 여윳돈(20억)의 4배까지만 주식에 거는 방식이에요.","m":"CPPI: 보장액 할인 → 쿠션 → × 승수","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"전술적 자산배분","q":"전술적 자산배분에 관한 설명으로 가장 적절하지 않은 것은?","o":["시장 가격이 내재가치에서 벗어나는 것을 이용해 자산 비중을 조정한다","시장이 효율적이라고 보고 장기 자산구성 목표를 정한 뒤 중단기에는 비중을 바꾸지 않는다","실행 도구로 가치평가모형, 기술적 분석, 포뮬러 플랜 등을 쓴다","저평가된 자산을 사고 고평가된 자산을 파는 역투자전략의 성격을 가진다"],"a":1,"c":"전략적 자산배분은 장기 목표 비중을 정하는 것이고, 전술적 자산배분은 그 비중에서 잠시 벗어나 시장의 일시적 가격 왜곡을 이용하는 것이에요.","e":"장기 목표를 정하고 중단기에 바꾸지 않는 것은 전략적 자산배분이에요. 전술적 자산배분은 시장이 단기적으로 비효율적이라고 보고 비중을 조정해요.","w":["내재가치 이탈을 이용하는 것이 전술적 자산배분이에요.",null,"가치평가모형·기술적 분석·포뮬러 플랜이 대표 도구예요.","역투자전략이 핵심이에요."],"k":"전략적은 \"1년 식단표\", 전술적은 \"오늘 세일하는 재료로 메뉴를 살짝 바꾸는 것\"이에요.","m":"전략적 = 장기 목표 · 전술적 = 단기 이탈 이용(역투자)"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"전략적 자산배분의 실행 순서","q":"〈보기〉의 전략적 자산배분 실행 단계를 순서대로 바르게 나열한 것은?\nㄱ. 자산집단별 기대수익과 위험 추정\nㄴ. 투자자의 투자목적과 제약조건 파악\nㄷ. 최적 자산구성 결정\nㄹ. 투자할 자산집단 선정","o":["ㄴ → ㄹ → ㄱ → ㄷ","ㄹ → ㄴ → ㄱ → ㄷ","ㄴ → ㄱ → ㄹ → ㄷ","ㄱ → ㄴ → ㄹ → ㄷ"],"a":0,"c":"자산배분은 \"누구를 위해(투자자) → 무엇에(자산집단) → 얼마나 벌고 위험한지(추정) → 얼마씩(최적 구성)\"의 순서로 진행해요.","e":"투자자의 목적·제약 파악 → 자산집단 선정 → 기대수익·위험 추정 → 최적 자산구성 결정 순이에요.","w":[null,"투자자 파악이 가장 먼저예요.","자산집단을 정해야 그 자산의 수익과 위험을 추정할 수 있어요.","무엇에 투자할지 정하기 전에 추정부터 할 수는 없어요."],"k":"여행 계획처럼 \"누가 가나 → 어디 갈 후보 → 각 후보 비용·재미 따져 보기 → 최종 일정\"이에요.","m":"자산배분 순서: 투자자 → 자산집단 → 추정 → 최적화"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"인덱스펀드 구성 방법","q":"〈보기〉에서 설명하는 인덱스펀드 구성 방법으로 가장 적절한 것은?\n〈보기〉 벤치마크에 포함된 대형주는 모두 편입하고, 중소형주는 일부 종목만 골라 대표성을 갖도록 편입한다.","o":["완전복제법","최적화법","표본추출법","포뮬러 플랜"],"a":2,"c":"인덱스펀드는 벤치마크를 얼마나 똑같이 따라가느냐에 따라 완전복제법, 표본추출법, 최적화법으로 나눠요.","e":"대형주는 모두 담고 중소형주는 표본으로 일부만 담는 것은 표본추출법이에요. 거래비용을 줄이면서 추적오차를 관리하는 방법이에요.","w":["완전복제법은 벤치마크의 모든 종목을 그 비중대로 담아요.","최적화법은 수리 모형으로 추적오차가 최소가 되도록 포트폴리오를 짜요.",null,"포뮬러 플랜은 전술적 자산배분 도구예요."],"k":"큰 종목은 다 담고 작은 종목은 \"대표 선수\"만 뽑는 방식이에요.","m":"완전복제 = 전부 · 표본추출 = 대형주 전부+소형주 일부 · 최적화 = 수리모형"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"효율적 시장가설","q":"효율적 시장가설에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 약형 효율적 시장에서는 과거 주가 정보를 이용한 기술적 분석으로 초과수익을 얻기 어렵다.\nㄴ. 준강형 효율적 시장에서는 공개된 재무정보를 분석해도 초과수익을 얻기 어렵다.\nㄷ. 강형 효율적 시장에서는 내부자 정보로도 초과수익을 얻기 어렵다.\nㄹ. 효율적 시장가설은 액티브 운용을 지지하는 논거로 쓰인다.","o":["1개","2개","3개","4개"],"a":2,"c":"효율적 시장가설은 주가에 정보가 얼마나 반영돼 있는지에 따라 약형(과거 가격), 준강형(공개 정보), 강형(모든 정보)으로 나눠요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. 시장이 효율적이면 초과수익을 내기 어렵기 때문에 효율적 시장가설은 패시브(인덱스) 운용을 지지하는 논거가 돼요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","강형에 대한 ㄷ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 효율적 시장가설은 패시브 운용의 논거예요."],"k":"시장이 이미 모든 걸 알고 있다면 \"남보다 똑똑하게 고르기\"가 소용없으니, 그냥 시장 전체를 사는 게 낫다는 생각이에요.","m":"약형 = 과거 가격 · 준강형 = 공개정보 · 강형 = 내부정보까지 → 패시브 지지"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"가치투자와 성장투자 스타일","q":"주식 운용 스타일에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 가치투자는 PER·PBR이 낮은 종목을 주로 산다.\nㄴ. 가치투자자는 앞으로 이익이 정상 수준으로 회복될 것으로 기대한다.\nㄷ. 성장투자는 높은 이익 성장률을 위해 높은 PER을 감수한다.\nㄹ. 성장투자의 주된 위험은 기대한 이익 성장이 나타나지 않는 것이다.","o":["1개","2개","3개","4개"],"a":3,"c":"가치투자는 \"싸게 사기\", 성장투자는 \"빨리 크는 회사 사기\"예요. 각각 기대가 어긋날 때 손실 위험이 있어요.","e":"ㄱ~ㄹ 모두 옳아 4개예요. 가치투자는 저평가 종목의 이익 회복을, 성장투자는 높은 이익 성장을 기대하고, 성장이 꺾이면 높은 PER이 무너지는 위험이 있어요.","w":["네 개 모두 옳아요.","ㄴ과 ㄹ도 옳은 설명이에요.","빠진 하나도 옳은 설명이에요.",null],"k":"가치투자는 \"세일 중인 명품\", 성장투자는 \"비싸도 쑥쑥 크는 새싹\"을 사는 거예요.","m":"가치 = 저PER·이익 회복 · 성장 = 고PER 감수·성장 꺾이면 위험"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"전략적 자산배분 실행 방법","q":"전략적 자산배분의 실행 방법으로 가장 거리가 먼 것은?","o":["위험-수익 최적화 방법","다른 기관투자자의 자산배분 참고","저평가 자산을 사고 고평가 자산을 파는 역투자 방법","시장가치 접근법"],"a":2,"c":"전략적 자산배분은 시장 구성, 최적화 모형, 투자자 특수 상황, 다른 기관 사례 등을 바탕으로 장기 비중을 정해요.","e":"저평가 자산을 사고 고평가 자산을 파는 역투자는 전술적 자산배분의 실행 방법이에요.","w":["평균-분산 최적화로 비중을 정해요.","유사 기관의 배분을 참고해요.",null,"시장 전체 구성 비율을 따르는 방법이에요."],"k":"장기 식단은 \"영양 균형\"으로 정하지, \"오늘 세일\"로 정하지 않아요.","m":"전략적 실행: 시장가치 · 최적화 · 특수상황 · 기관 모방"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"포뮬러 플랜 정률법","q":"주식과 채권 비율을 50 : 50으로 유지하기로 하고, 주가가 올라 주식 비중이 커지면 주식 일부를 팔아 다시 50 : 50으로 맞추는 방법은?","o":["추세추종법","정액법","정률법","변수법"],"a":2,"c":"포뮬러 플랜은 미리 정한 공식에 따라 기계적으로 매매하는 방법으로, 정액법·정률법·변수법이 있어요.","e":"주식과 채권의 비율을 일정하게 유지하는 것은 정률법이에요. 주가가 오르면 팔고 내리면 사는 역투자 성격이에요.","w":["추세추종은 반대로 오르면 더 사요.","정액법은 주식 투자 \"금액\"을 일정하게 유지해요.",null,"변수법은 주가 수준에 따라 비율 자체를 바꿔요."],"k":"\"항상 반반\"으로 맞추면 자연스럽게 비쌀 때 팔고 쌀 때 사게 돼요.","m":"정률법 = 비율 유지 · 정액법 = 금액 유지 · 변수법 = 비율 변경"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"포뮬러 플랜 정액법","q":"주식에 투자하는 금액을 항상 1억원으로 유지하고, 주가가 올라 1억원을 넘으면 초과분을 팔고 내리면 부족분을 사는 방법은?","o":["정액법","정률법","변수법","CPPI"],"a":0,"c":"포뮬러 플랜은 감정을 배제하고 정해진 공식대로 매매해요.","e":"주식 투자 금액을 일정하게 유지하는 것은 정액법이에요.","w":[null,"정률법은 비율을 일정하게 유지해요.","변수법은 주가 수준에 따라 비율을 바꿔요.","CPPI는 하락할 때 주식을 줄이는 포트폴리오 보험 전략이에요."],"k":"\"주식 지갑에는 늘 1억\"을 지키는 방법이에요.","m":"정액법 = 주식 금액 일정"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"최적화법","q":"인덱스펀드 구성 방법 가운데 최적화법에 관한 설명으로 가장 적절한 것은?","o":["벤치마크 종목을 모두 그대로 보유한다","모형 오류 위험이 전혀 없다","계량 모형을 이용해 주어진 조건에서 추적오차가 최소가 되도록 포트폴리오를 구성한다","업종 대표 종목을 표본으로 골라 업종 비중을 맞춘다"],"a":2,"c":"최적화법은 통계 모형으로 벤치마크와 비슷하게 움직이는 종목 조합을 찾아요.","e":"계량 모형으로 추적오차를 최소화하는 포트폴리오를 만들어요. 다만 과거 자료와 모형에 의존하므로 모형이 틀릴 위험이 있어요.","w":["완전복제법이에요.","모형 위험이 있어요.",null,"표본추출법이에요."],"k":"컴퓨터에게 \"지수랑 제일 비슷하게 움직이는 조합\"을 찾게 하는 방법이에요.","m":"최적화법 = 계량모형 · 추적오차 최소화 · 모형위험"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"인덱스펀드 추적오차의 원인","q":"인덱스펀드의 추적오차가 생기는 원인으로 가장 거리가 먼 것은?","o":["매매에 따른 거래비용","펀드 운용 보수","펀드가 일부 보유하는 현금","벤치마크 지수 자체의 높은 변동성"],"a":3,"c":"추적오차는 펀드 수익률이 벤치마크 수익률과 달라지는 정도예요.","e":"벤치마크 자체가 많이 흔들려도 펀드가 그대로 따라가면 추적오차는 생기지 않아요. 거래비용·보수·현금 보유·불완전 복제가 원인이에요.","w":["거래비용 때문에 수익률이 벌어져요.","보수만큼 수익률이 낮아져요.","현금은 지수와 다르게 움직여요.",null],"k":"지수가 출렁여도 똑같이 출렁이면 오차가 아니에요. \"따라가는 과정의 비용\"이 오차를 만들어요.","m":"추적오차 원인: 거래비용 · 보수 · 현금 · 불완전 복제"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"주가가중 지수","q":"구성 종목의 주가를 단순 평균해 산출하는 주가가중 방식의 주가지수로 가장 적절한 것은?","o":["코스피(KOSPI)","코스피200","다우존스산업평균지수","S&P500"],"a":2,"c":"주가지수는 시가총액가중, 주가가중, 동일가중 등 방식에 따라 성격이 달라요.","e":"다우존스산업평균지수(그리고 니케이225)는 주가를 단순 평균하는 주가가중 방식이에요. 코스피·코스피200·S&P500은 시가총액 방식이에요.","w":["시가총액 방식이에요.","시가총액 방식이에요.",null,"시가총액 방식이에요."],"k":"다우지수는 \"주가가 비싼 종목\"이 지수에 더 큰 영향을 줘요.","m":"주가가중 = 다우·니케이225 / 시가총액 = 코스피·S&P500"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"시가총액가중 지수의 특징","q":"시가총액가중 방식 주가지수에 관한 설명으로 가장 적절하지 않은 것은?","o":["시가총액이 큰 종목일수록 지수에 미치는 영향이 크다","주식 분할을 해도 지수를 조정할 필요가 거의 없다","시장 전체의 가치 변화를 잘 반영한다","시가총액과 관계없이 주가가 높은 종목일수록 영향이 크다"],"a":3,"c":"시가총액 방식은 주가 × 주식 수(시가총액) 비중으로 지수를 계산해요.","e":"주가가 높을수록 영향이 큰 것은 주가가중 방식의 특징이에요. 시가총액 방식은 시가총액이 큰 종목의 영향이 커요.","w":["대형주 영향이 커요.","분할해도 시가총액은 변하지 않아요.","시장 전체 가치를 반영해요.",null],"k":"시가총액 방식에서는 \"몸집(시가총액)\"이 큰 회사가 지수를 움직여요.","m":"시가총액가중 = 시총 큰 종목 영향↑ · 주가가중 = 주가 높은 종목 영향↑"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"동일가중 지수","q":"모든 구성 종목에 같은 비중을 주는 동일가중 지수에 관한 설명으로 가장 적절한 것은?","o":["주기적으로 비중을 다시 맞출 필요가 없다","시가총액가중 지수와 항상 같은 수익률을 낸다","소형주의 영향력이 상대적으로 커진다","대형주의 영향력이 시가총액가중 지수보다 커진다"],"a":2,"c":"동일가중은 종목 크기와 관계없이 똑같은 비중을 줘요.","e":"시가총액이 작은 종목도 같은 비중을 받으므로 소형주의 영향력이 커져요. 가격이 변하면 비중이 달라져 주기적으로 리밸런싱해야 해요.","w":["비중이 변하므로 재조정이 필요해요.","구성 비중이 달라 수익률도 달라요.",null,"대형주 영향력은 줄어요."],"k":"반 친구들 키와 상관없이 모두에게 똑같은 투표권을 주는 셈이에요.","m":"동일가중 = 소형주 영향↑ · 리밸런싱 필요"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"가치함정","q":"가치투자의 위험으로 거론되는 \"가치함정(value trap)\"에 관한 설명으로 가장 적절한 것은?","o":["저평가된 주식이 금방 제 가치를 찾아 급등하는 현상","싸 보이는 주식이 실제로는 실적이 회복되지 않아 계속 싸게 머무르거나 더 떨어지는 현상","성장주가 기대 이상으로 성장하는 현상","배당이 갑자기 늘어나는 현상"],"a":1,"c":"가치투자는 싸게 산 주식이 제 가치로 돌아온다는 기대에 기대요.","e":"싸 보이는 데에는 이유가 있을 수 있어요. 실적이 회복되지 않으면 주가가 계속 싸게 머무르거나 더 떨어지는 가치함정에 빠져요.","w":["가치투자가 성공한 경우예요.",null,"성장투자의 성공이에요.","가치함정과 관계없어요."],"k":"세일 상품이 사실은 \"고장 난 물건\"이었던 경우예요.","m":"가치함정 = 싼 이유가 있어 회복 안 됨"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"PEG 비율","q":"PER이 20배이고 주당순이익(EPS) 성장률이 연 25%인 기업의 PEG 비율은?","o":["0.8","1.25","5.0","45"],"a":0,"c":"PEG는 PER을 이익성장률로 나눈 값으로, 성장을 고려한 주가 수준을 보여 줘요. 합리적 가격의 성장주(GARP) 투자에서 써요.","e":"PEG = 20 ÷ 25 = 0.8이에요. 1보다 작으면 성장에 비해 주가가 싸다고 봐요.","w":[null,"분자와 분모를 바꿨어요(25 ÷ 20 = 1.25).","두 값을 뺐어요(25 − 20 = 5). PEG는 PER을 성장률로 나눠요.","두 값을 더했어요."],"k":"비싸 보여도(PER 20) 그만큼 빨리 크면(25%) 사실은 싼 편이에요.","m":"PEG = PER ÷ EPS 성장률(%)","f":"20 ÷ 25 = 0.8"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"약형 효율적 시장의 검증","q":"약형 효율적 시장가설이 성립한다면 나타나는 현상으로 가장 적절한 것은?","o":["과거 주가 흐름으로 미래 주가를 예측할 수 있다","주가 변화가 서로 독립적으로 무작위하게 움직인다","내부자 정보로도 초과수익을 낼 수 없다","공시 정보를 분석하면 초과수익을 낼 수 있다는 것이 증명된다"],"a":1,"c":"약형 효율적 시장에서는 과거 가격 정보가 이미 주가에 반영되어 있어요.","e":"과거 가격 정보가 모두 반영되어 있으면 주가는 무작위(랜덤워크)로 움직여 과거 흐름으로 예측할 수 없어요.","w":["약형이 성립하면 예측할 수 없어요.",null,"강형 효율적 시장의 내용이에요.","약형 성립과 무관한 주장이에요."],"k":"과거 차트를 아무리 봐도 다음 동전 던지기는 맞힐 수 없어요.","m":"약형 → 랜덤워크 · 기술적 분석 무력"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"준강형 효율적 시장의 검증","q":"준강형 효율적 시장가설을 검증하는 방법으로 가장 적절한 것은?","o":["과거 주가의 자기상관 분석","기업 공시 등 사건 발표 직후 주가가 얼마나 빨리 반영되는지 보는 사건연구","내부자 거래의 수익률 분석","주가 차트 패턴 분석"],"a":1,"c":"준강형 효율적 시장에서는 공개된 모든 정보가 즉시 주가에 반영돼요.","e":"공시나 발표 같은 사건 직후 주가가 즉시 반영되는지 보는 사건연구로 준강형을 검증해요.","w":["약형 검증 방법이에요.",null,"강형 검증 방법이에요.","약형(기술적 분석)과 관련돼요."],"k":"뉴스가 나오자마자 주가에 바로 반영되면 준강형 효율적이에요.","m":"약형 = 자기상관·런테스트 · 준강형 = 사건연구 · 강형 = 내부자 수익"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"시장 이례현상","q":"효율적 시장가설로 설명하기 어려운 시장 이례현상(anomaly)으로 가장 거리가 먼 것은?","o":["1월 효과","소형주 효과","저PER 효과","공시 직후 주가가 즉시 새 정보를 반영하는 현상"],"a":3,"c":"이례현상은 효율적 시장가설과 맞지 않게 반복적으로 나타나는 수익률 패턴이에요.","e":"공시 직후 주가가 즉시 반영되는 것은 오히려 준강형 효율적 시장을 지지하는 현상이에요.","w":["1월에 수익률이 높은 이례현상이에요.","소형주가 위험 대비 높은 수익을 내는 이례현상이에요.","저PER주가 초과수익을 내는 이례현상이에요.",null],"k":"\"달력·크기·싼 정도\"로 꾸준히 이길 수 있다면 시장이 완전히 효율적이지 않다는 증거예요.","m":"이례현상: 1월·소형주·저PER·주말 효과 등"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"이벤트 드리븐 전략","q":"기업 인수합병, 분할, 자사주 매입 같은 특정 사건 전후의 가격 비효율을 이용하는 주식 운용 전략은?","o":["이벤트 드리븐 전략","인덱스 전략","포뮬러 플랜","전략적 자산배분"],"a":0,"c":"기업에 큰 사건이 생기면 시장이 정보를 정확히 반영하기 전까지 가격 차이가 생길 수 있어요.","e":"특정 사건 전후의 가격 비효율을 노리는 것은 이벤트 드리븐 전략이에요.","w":[null,"지수를 따라가는 전략이에요.","규칙에 따른 기계적 매매예요.","장기 자산 비중을 정하는 일이에요."],"k":"\"사건이 있는 곳에 기회가 있다\"는 전략이에요.","m":"이벤트 드리븐 = 합병·분할·자사주 등 사건 이용"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"CPPI 승수의 효과","q":"CPPI 전략에서 승수가 클 때의 특징으로 가장 적절한 것은?","o":["위험자산 비중이 작아져 상승장에서 이익이 줄어든다","위험자산 비중이 커져 상승장 이익이 크지만, 급락 시 최저보장가치에 빨리 가까워진다","승수는 성과에 영향을 주지 않는다","승수가 클수록 최저보장가치가 높아진다"],"a":1,"c":"승수는 쿠션의 몇 배를 위험자산에 넣을지 정하는 값이에요.","e":"승수가 크면 위험자산 비중이 커져 상승장 이익이 커지지만, 급락하면 쿠션이 빨리 줄어 바닥에 가까워지는 위험이 커요.","w":["위험자산 비중이 커져요.",null,"승수가 결과를 크게 좌우해요.","최저보장가치는 승수와 별개로 정해져요."],"k":"지렛대를 길게 잡으면 크게 벌 수도 있지만 크게 흔들려요.","m":"승수↑ → 위험자산↑ · 상승 이익↑ · 하락 시 바닥 접근↑"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"OBPI와 CPPI","q":"포트폴리오 보험 전략 가운데 OBPI(옵션 기반)와 CPPI를 비교한 설명으로 가장 적절한 것은?","o":["CPPI는 옵션을 직접 사서 운용한다","CPPI는 블랙-숄즈 옵션모형이 반드시 필요하다","OBPI는 주식 보유와 풋옵션 매수 등 옵션을 이용해 최저 가치를 보장한다","OBPI는 투자기간을 정하지 않아도 된다"],"a":2,"c":"포트폴리오 보험은 하락 위험은 제한하고 상승 이익은 일부 누리려는 전략이에요.","e":"OBPI는 주식 + 풋옵션(또는 채권 + 콜옵션)으로 최저 가치를 보장해요. CPPI는 옵션 없이 단순한 규칙(승수 × 쿠션)으로 운용해 옵션모형이 필요 없어요.","w":["CPPI는 옵션 없이 비중을 조절해요.","CPPI는 옵션모형 없이 운용해요.",null,"OBPI는 옵션 만기에 맞춘 투자기간이 필요해요."],"k":"OBPI는 \"보험(풋)을 사는 방식\", CPPI는 \"규칙대로 비중을 조절하는 방식\"이에요.","m":"OBPI = 옵션 이용 · 만기 필요 / CPPI = 승수 × 쿠션 · 옵션모형 불필요"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"포트폴리오 보험의 매매 방향","q":"포트폴리오 보험 전략의 매매 방식으로 가장 적절하지 않은 것은?","o":["위험자산 가격이 오르면 위험자산 비중을 늘린다","위험자산 가격이 내리면 위험자산 비중을 줄인다","추세추종(모멘텀)적 매매 성격이 있다","위험자산 가격이 내리면 저평가로 보고 위험자산 비중을 늘린다"],"a":3,"c":"포트폴리오 보험은 바닥(최저 가치)을 지키기 위해 하락할수록 위험자산을 줄여요.","e":"가격이 내리면 위험자산 비중을 줄여야 최저 가치를 지킬 수 있어요. 내릴 때 더 사는 것은 역투자 전략이에요.","w":["오르면 비중을 늘려요.","내리면 비중을 줄여요.","추세추종 성격이에요.",null],"k":"바닥을 지켜야 하니 떨어질수록 위험한 것을 덜어 내요.","m":"포트폴리오 보험 = 추세추종(오르면 사고 내리면 팜)"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"TIPP 전략","q":"CPPI를 변형해 포트폴리오 가치가 오르면 최저보장가치도 함께 끌어올리는 전략은?","o":["OBPI","완전복제법","정률법","TIPP"],"a":3,"c":"CPPI는 최저보장가치가 정해져 있지만, 이익이 나면 그 이익 일부를 지키고 싶을 수 있어요.","e":"TIPP는 포트폴리오 가치가 상승하면 최저보장가치를 일정 비율로 올려(래칫) 이미 얻은 이익을 보호해요.","w":["옵션을 이용하는 포트폴리오 보험이에요.","인덱스펀드 구성 방법이에요.","포뮬러 플랜의 한 종류예요.",null],"k":"산을 오르면서 안전 로프의 고정점도 같이 위로 옮기는 방식이에요.","m":"TIPP = 가치 상승 시 최저보장가치도 상향"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"완전공분산모형의 한계","q":"마코위츠의 완전공분산모형으로 많은 종목의 포트폴리오를 구성할 때의 한계로 가장 적절한 것은?","o":["분산투자 효과를 반영하지 못한다","종목 간 상관관계를 무시한다","추정해야 할 공분산이 종목 수에 따라 급격히 늘어난다","기대수익률을 추정할 필요가 없다"],"a":2,"c":"완전공분산모형은 모든 종목 쌍의 공분산을 직접 추정해야 해요.","e":"종목 수가 n이면 공분산만 n(n−1)/2개라 종목이 많아질수록 추정 부담이 급격히 늘어요. 단일지표모형은 이를 줄이려고 나왔어요.","w":["분산효과를 가장 직접적으로 반영해요.","상관관계를 모두 반영해요.",null,"기대수익률도 추정해야 해요."],"k":"반 친구 모든 짝꿍 관계를 다 조사하려면 사람이 늘수록 일이 폭발해요.","m":"완전공분산 = 공분산 n(n−1)/2개 추정 부담"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"스타일 박스","q":"주식 펀드의 운용 스타일을 분류하는 스타일 박스의 두 기준으로 가장 적절한 것은?","o":["기업 규모(대형·중형·소형)와 가치·성장 성향","국가와 통화","배당과 이자","부채비율과 유동비율"],"a":0,"c":"스타일 박스는 주식 펀드가 어떤 종류의 주식에 주로 투자하는지 한눈에 보여 주는 3 × 3 표예요.","e":"세로축은 기업 규모(대형·중형·소형), 가로축은 가치·혼합·성장 성향으로 나눠요.","w":[null,"스타일 박스 기준이 아니에요.","스타일 박스 기준이 아니에요.","재무비율이지 스타일 기준이 아니에요."],"k":"\"큰 회사냐 작은 회사냐 × 싼 주식이냐 크는 주식이냐\"로 9칸을 나눠요.","m":"스타일 박스 = 규모 × 가치/성장"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"투자정책서의 제약조건","q":"투자정책서(IPS)에 담는 투자자의 제약조건으로 가장 거리가 먼 것은?","o":["유동성 필요","투자기간","세금과 법규","기대 초과수익률"],"a":3,"c":"투자정책서는 투자 목표(수익·위험)와 제약조건을 정리한 운용의 기준 문서예요.","e":"제약조건은 유동성, 투자기간, 세금, 법규, 고유 상황 등이에요. 기대 초과수익률은 제약조건이 아니라 목표나 결과에 해당해요.","w":["언제 돈이 필요한지는 제약조건이에요.","투자기간은 제약조건이에요.","세금과 법규는 제약조건이에요.",null],"k":"\"언제까지, 얼마나 꺼내 써야, 어떤 규칙 안에서\"가 제약조건이에요.","m":"제약조건: 유동성 · 투자기간 · 세금 · 법규 · 고유 상황"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"롱숏 시장중립 전략","q":"저평가 주식을 사고 고평가 주식을 공매도해 시장 전체 방향의 영향을 줄이는 전략으로 가장 적절한 것은?","o":["포트폴리오 보험 전략","바이앤홀드 전략","롱숏 시장중립 전략","인덱스 전략"],"a":2,"c":"시장중립 전략은 매수와 매도를 함께 해 시장이 오르든 내리든 영향을 줄이고 종목 선택 능력으로 수익을 내요.","e":"저평가 종목 매수와 고평가 종목 공매도로 시장 위험(베타)을 상쇄하는 것이 롱숏 시장중립 전략이에요.","w":["하락 위험을 제한하는 전략이에요.","사서 계속 보유하는 전략이에요.",null,"시장 전체를 따라가는 전략이에요."],"k":"\"이 둘 중 누가 더 잘할까?\"에만 거는 상대평가 전략이에요.","m":"롱숏 시장중립 = 매수 + 공매도로 β 상쇄"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"섹터 로테이션","q":"경기 국면 변화를 예상해 그 국면에서 유리한 업종의 비중을 늘리고 불리한 업종은 줄이는 운용 방법은?","o":["섹터 로테이션","완전복제법","정액법","면역전략"],"a":0,"c":"업종마다 경기 국면별로 실적이 좋은 시기가 달라요.","e":"경기 흐름에 맞춰 유리한 업종으로 비중을 옮기는 것은 섹터 로테이션이에요. 액티브 운용 방식이에요.","w":[null,"인덱스 복제 방법이에요.","포뮬러 플랜이에요.","채권 운용 전략이에요."],"k":"계절마다 잘 팔리는 상품으로 진열대를 바꾸는 것과 같아요.","m":"섹터 로테이션 = 경기 국면별 업종 비중 조정(액티브)"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"자산집단의 요건","q":"자산배분에서 쓰는 자산집단(asset class)이 갖춰야 할 요건으로 가장 거리가 먼 것은?","o":["같은 자산집단 안의 자산들은 성격이 비슷해야 한다","서로 다른 자산집단은 겹치지 않아야 한다","분산투자 효과가 있어야 한다","자산집단 안의 개별 자산 수가 적을수록 좋다"],"a":3,"c":"자산집단은 자산배분의 기본 단위라서 동질성, 배타성, 분산 가능성, 충분한 규모를 갖춰야 해요.","e":"자산집단은 투자할 수 있을 만큼 충분히 크고 종목이 많아야 해요. 개별 자산이 적으면 충분히 투자하기 어려워요.","w":["동질성이 필요해요.","배타성이 필요해요.","분산 가능성이 필요해요.",null],"k":"\"비슷한 것끼리, 서로 안 겹치게, 충분히 크게\" 묶어야 좋은 자산집단이에요.","m":"자산집단 요건: 동질성 · 배타성 · 분산가능성 · 충분한 규모"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"자산배분의 중요성","q":"장기 투자 성과에 관한 일반적인 실증 결과로 가장 적절한 것은?","o":["종목 선택이 성과 변동의 대부분을 설명한다","자산배분이 포트폴리오 성과 변동의 대부분을 설명한다","시장 타이밍이 성과 변동의 대부분을 설명한다","성과는 운에 의해서만 결정된다"],"a":1,"c":"연구에 따르면 장기 포트폴리오 수익률의 변동은 어떤 종목을 골랐는지보다 자산군 비중을 어떻게 나눴는지로 대부분 설명돼요.","e":"자산배분이 포트폴리오 성과 변동의 대부분을 설명한다는 것이 일반적인 실증 결과예요. 그래서 자산배분을 가장 중요한 의사결정으로 봐요.","w":["종목 선택의 설명력은 상대적으로 작아요.",null,"시장 타이밍의 설명력은 상대적으로 작아요.","체계적 의사결정이 성과를 좌우해요."],"k":"어떤 반찬 브랜드를 고르느냐보다 \"밥·반찬·과일 비율\"이 건강을 더 좌우해요.","m":"장기 성과 = 자산배분이 대부분 결정"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"바이앤홀드 전략","q":"바이앤홀드(매수 후 보유) 전략에 관한 설명으로 가장 적절한 것은?","o":["처음 구성한 포트폴리오를 매매하지 않고 계속 보유한다","가격이 오르면 팔고 내리면 산다","자산 비중을 매일 원래대로 맞춘다","하락할 때마다 위험자산을 줄인다"],"a":0,"c":"바이앤홀드는 가장 단순한 소극적 전략으로, 처음 산 포트폴리오를 그대로 들고 가요.","e":"매매 없이 계속 보유하므로 거래비용이 거의 없고, 시간이 지나면 오른 자산의 비중이 자연스럽게 커져요.","w":[null,"역투자(정률법 등)예요.","리밸런싱이에요.","포트폴리오 보험이에요."],"k":"한번 사면 \"그냥 둔다\"가 원칙이에요.","m":"바이앤홀드 = 매수 후 보유 · 거래비용 최소"},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"리밸런싱 허용 범위","q":"전략적 자산배분에서 목표 비중을 정하고, 실제 비중이 일정 범위를 벗어날 때만 재조정하는 방법의 장점으로 가장 적절한 것은?","o":["거래비용을 줄이면서 목표 비중에서 크게 벗어나는 것을 막는다","매일 재조정해 비중을 완벽히 유지한다","목표 비중을 정할 필요가 없다","시장 예측 능력으로 초과수익을 극대화한다"],"a":0,"c":"매번 비중을 맞추면 거래비용이 커지고, 전혀 맞추지 않으면 위험이 목표와 달라져요.","e":"허용 범위(밴드)를 벗어날 때만 재조정하면 거래비용을 아끼면서 목표 비중에서 크게 벗어나는 것을 막을 수 있어요.","w":[null,"매일 재조정은 비용이 커요.","목표 비중이 기준이에요.","예측이 아니라 규칙 기반 관리예요."],"k":"조금 틀어진 건 그냥 두고, 많이 틀어졌을 때만 바로잡아요.","m":"밴드 리밸런싱 = 거래비용 절감 + 위험 관리"},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"상","t":"OBPI 주식 배분과 변동성","q":"옵션모형을 이용한 포트폴리오 보험(OBPI)으로 운용하는 펀드의 평가액은 400억원이며, 편입 주식에 대한 풋옵션 델타가 −0.45로 나왔다. (ㄱ) 지금 주식에 배분할 금액과 (ㄴ) 이후 주가가 오를 때 주식 편입비중의 변화를 순서대로 짝지은 것은?","o":["220억원 — 낮아진다","220억원 — 높아진다","180억원 — 낮아진다","180억원 — 높아진다"],"a":1,"c":"OBPI는 '주식 + 풋옵션 매수(방어적 풋)'와 같은 결과를 내도록 주식 비중을 1 − |풋 델타|(= 콜 델타)에 맞추는 전략이에요.","e":"주식 배분액 = 400 × (1 − 0.45) = 220억원이고, 나머지 180억원은 채권에 둬요. 주가가 오르면 풋옵션 델타의 절댓값은 작아지고 콜옵션 델타는 커지므로 주식 비중을 높여요. 오를 때 사고 내릴 때 파는 추세추종 매매예요.","w":["주가가 오르면 풋 델타의 절댓값이 작아지므로 주식 비중은 오히려 높아져요.",null,"180억원은 |델타| 0.45를 그대로 곱한 채권 쪽 금액이고, 비중 변화의 방향도 반대예요.","비중 변화 방향은 맞지만, 180억원은 주식이 아니라 채권 쪽 금액이에요."],"k":"주가가 올라 바닥(최저 보장선)에서 멀어지면 보험을 덜 들어도 되니, 주식을 더 담게 돼요.","m":"OBPI 주식 = 평가액 × (1 − |풋델타|)","f":"주식 배분액 = 평가액 × (1 − |풋 델타|) = 평가액 × 콜 델타","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"포트폴리오 보험의 한계","q":"포트폴리오 보험 전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["합성 풋옵션 전략은 주식과 채권의 비중을 계속 바꿔 가며 주식 보유 + 풋옵션 매수의 성과를 흉내 낸다","보장하려는 최저수익률이 무위험수익률을 넘으면 전략 자체가 성립하지 않는다","주가가 짧은 시간에 폭락하면 비중 조정이 따라가지 못해 보장 수준이 깨질 수 있다","주가가 오르는 구간에서는 처음부터 주식에 모두 투자한 경우보다 높은 수익을 낸다"],"a":3,"c":"포트폴리오 보험은 바닥(최소보장수준)을 지키는 대신 상승장에서 이익 일부를 포기하는 전략이에요. 옵션을 직접 사지 않고 비중 조정으로 풋을 복제하는 것이 합성 풋 전략이에요.","e":"보험료처럼 하락 보호 비용이 들기 때문에 상승장에서는 주식에 전부 투자한 것보다 수익이 낮아요. 1987년 미국 증시 폭락 때처럼 가격이 한꺼번에 빠지면 재조정이 늦어 보장이 깨지는 한계도 있어요.","w":["합성 풋은 보험 기법 중 역사가 가장 긴 방식이고, 방어적 풋의 성과를 비중 조정으로 재현해요.","무위험자산에 전부 넣어도 무위험수익률밖에 못 얻으니, 그보다 높은 보장은 지킬 방법이 없어요.","1987년 폭락 때 실제로 드러난 한계예요.",null],"k":"보험에 들면 사고는 막아 주지만 매달 보험료가 나가는 것처럼, 오를 때 수익이 조금 줄어요.","m":"보험: 바닥 보장 ↔ 상승 이익 일부 포기","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"CPPI 바닥과 승수","q":"CPPI(고정비율 포트폴리오 보험) 전략에 대한 설명으로 가장 적절하지 않은 것은?","o":["최저보장가치는 시간이 흐르면서 무위험이자율만큼 커져 만기에는 보장액과 같아진다","쿠션이 0이 되면 승수와 관계없이 위험자산 투자액은 0이 된다","옵션처럼 만기가 꼭 필요하지 않아 투자기간을 정하지 않고도 운용할 수 있다","승수는 시장 금리와 남은 기간을 넣으면 공식으로 하나의 값만 나오므로 운용자가 고를 수 없다"],"a":3,"c":"CPPI는 위험자산 = 승수 × (평가액 − 최저보장가치)로 운용해요. 최저보장가치는 보장액의 현재가치라 시간이 갈수록 커져요.","e":"승수는 운용자가 위험 선호와 시장 상황을 보고 정하는 값이에요. 승수가 클수록 상승장 이익은 커지지만 급락 때 바닥에 빨리 닿아요.","w":["보장액을 할인한 값이라 만기에 가까워질수록 할인 폭이 줄어 보장액에 다가가요.","위험자산 = 승수 × 0 = 0이라 전액 안전자산이 돼요.","선형 규칙만 쓰므로 옵션모형도, 정해진 만기도 꼭 필요하지 않아요.",null],"k":"얼마나 과감하게 걸지(승수)는 운전자가 정하는 속도 같은 거예요. 공식이 정해 주지 않아요.","m":"CPPI 승수 = 운용자가 선택, 쿠션 0 → 위험자산 0","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"상","t":"전술적 배분과 보험의 수익곡선","q":"전술적 자산배분과 포트폴리오 보험 전략의 수익구조를 비교한 설명으로 가장 적절한 것은?","o":["전술적 자산배분은 자산가격이 랜덤워크를 따를수록 고평가·저평가를 가리기 쉬워 성과가 좋아진다","전술적 자산배분에서 비중을 바꿔 생긴 성과의 책임은 운용자가 아니라 투자자가 진다","두 전략 모두 오르는 자산을 더 사는 추세추종형이라 수익곡선이 아래로 볼록하다","전술적 자산배분은 주가가 오를수록 주식을 덜어내므로 펀드 수익이 위로 볼록하게, 포트폴리오 보험은 오를수록 주식을 늘리므로 아래로 볼록하게 나타난다"],"a":3,"c":"전술적 자산배분은 투자자가 정보에 과잉반응해 가격이 내재가치에서 벗어났다가 돌아온다(평균반전)고 보고 역으로 매매해요. 포트폴리오 보험은 그 반대인 추세추종이에요.","e":"오르면 팔고 내리면 사는 역투자는 상승 이익이 점점 덜 늘어나 위로 볼록(오목)한 모양이 되고, 오르면 사고 내리면 파는 보험은 아래로 볼록한 모양이 돼요.","w":["가격이 랜덤워크라면 평균반전이 없어 역투자로 돈을 벌 수 없어요.","전략적 배분에서 벗어나 비중을 바꾼 결과는 운용자의 판단이므로 운용자가 책임을 져요.","전술적 자산배분은 역투자예요. 추세추종은 포트폴리오 보험 쪽이에요.",null],"k":"전술적 배분은 '싸게 사서 비싸게 파는 장사꾼', 보험은 '분위기 따라가는 안전 운전자'예요.","m":"전술적 = 역투자 = 위로 볼록 / 보험 = 추세추종 = 아래로 볼록","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"상","t":"새 자산 편입과 샤프비율","q":"현재 포트폴리오의 샤프비율은 0.6이다. 새로 편입을 검토하는 자산집단 K의 샤프비율은 0.4이고, 현재 포트폴리오와 K의 상관계수는 0.6이다. 판단으로 가장 적절한 것은?","o":["K의 샤프비율이 기존보다 낮아 편입 시 전체 샤프비율이 반드시 떨어진다","K의 샤프비율 0.4가 기준값 0.36보다 높으므로 편입하면 포트폴리오 샤프비율이 좋아진다","K의 샤프비율 0.4가 기준값 0.67보다 낮으므로 편입하면 안 된다","상관계수가 양(+)이면 분산효과가 없으므로 판단할 수 없다"],"a":1,"c":"새 자산의 샤프비율이 '기존 포트폴리오 샤프비율 × 상관계수'보다 크면, 그 자산을 조금 편입할 때 포트폴리오 샤프비율이 올라가요.","e":"기준값 = 0.6 × 0.6 = 0.36이에요. K의 샤프비율 0.4가 이보다 크므로 편입하면 샤프비율이 개선돼요.","w":["상관계수가 1보다 낮으면 분산효과 덕분에 샤프비율이 낮은 자산도 도움이 될 수 있어요.",null,"0.4 ÷ 0.6으로 나눈 잘못된 기준이에요. 기준은 곱해서 구해요.","상관계수가 1보다 작기만 하면 분산효과는 있어요."],"k":"혼자서는 덜 뛰어나도, 팀과 엇박자로 움직이는 선수가 팀 전체 성적을 올릴 수 있어요.","m":"편입 조건: 새 SR > 기존 SR × ρ","f":"새 자산 샤프비율 > 기존 포트폴리오 샤프비율 × 상관계수","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"핵심-위성 전략","q":"다음 펀드 가운데 핵심-위성(core-satellite) 전략으로 운용되는 것으로 가장 적절한 것은?","o":["코스피200 종목을 모두 담되 일부 종목 비중만 살짝 조정해 지수를 소폭 웃돌려는 펀드","재무 점수 상위 종목만 기계적으로 골라 전체 포트폴리오를 짜는 펀드","자산의 70%는 코스피200 인덱스펀드로 채우고, 30%는 운용역이 고른 소수 성장주에 투자하는 펀드","액티브 운용을 하면서 업종 쏠림만 지수선물로 줄여 두는 펀드"],"a":2,"c":"핵심-위성 전략은 자산의 큰 몫(핵심)을 저비용 패시브로 시장수익률을 확보하고, 나머지(위성)로 액티브 운용을 해 초과수익을 노리는 혼합전략이에요.","e":"패시브(핵심)는 벤치마크 수익률을 낮은 비용으로 따라가고, 액티브(위성)는 종목 선택으로 벤치마크를 이기려 해요. 둘을 나눠 담은 것이 핵심-위성 전략이에요.","w":["지수 비중을 소폭만 조정하는 것은 인핸스드 인덱스(준액티브) 방식이에요.","계량모형으로 전체를 짜는 것은 퀀트형 액티브 운용이에요.",null,"액티브 운용에 선물로 노출만 조정한 것이라 핵심-위성 구조가 아니에요."],"k":"밥(핵심)은 든든하게 기본으로 먹고, 반찬(위성)으로 입맛을 내는 식단이에요.","m":"핵심 = 패시브(저비용), 위성 = 액티브(초과수익)","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"하","t":"자산·스타일·종목 결정 순서","q":"보험회사 자산운용팀이 내년 운용계획을 세우며 다음 세 가지를 결정해야 한다. 일반적인 의사결정 순서로 가장 적절한 것은?\nA. 주식 담당 자금을 대형주와 중소형주에 얼마씩 나눌지 정한다.\nB. 전체 자금을 주식 35%, 채권 50%, 대체투자 15%로 나눈다.\nC. 대형주 몫으로 살 개별 종목과 수량을 확정한다.","o":["A → B → C","B → C → A","B → A → C","C → A → B"],"a":2,"c":"운용은 큰 결정에서 작은 결정으로 내려가요. 자산배분 → 스타일배분 → 증권선택 순서예요.","e":"B는 자산군 비중을 정하는 자산배분, A는 주식 안에서 규모·스타일을 나누는 스타일배분, C는 개별 종목을 고르는 증권선택이에요.","w":["스타일배분을 자산배분보다 먼저 할 수는 없어요. 주식에 얼마를 둘지부터 정해야 해요.","종목을 먼저 고르고 스타일을 나중에 정하면 순서가 거꾸로예요.",null,"가장 작은 결정(종목)부터 시작해 순서가 정반대예요."],"k":"이사 갈 때 집(자산배분) → 방 배치(스타일) → 가구 고르기(종목) 순서로 정해요.","m":"자산배분 → 스타일배분 → 증권선택","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"주식 포트폴리오 구축 순서","q":"주식 포트폴리오를 만들어 운용하는 과정을 순서대로 바르게 나열한 것은?\nㄱ. 실제 포트폴리오를 짜고 매매를 실행한다\nㄴ. 성과와 위험을 점검해 리밸런싱한다\nㄷ. 투자 가능한 종목군(유니버스)을 정한다\nㄹ. 목표로 삼을 모델 포트폴리오를 만든다","o":["ㄷ → ㄹ → ㄱ → ㄴ","ㄹ → ㄷ → ㄱ → ㄴ","ㄷ → ㄱ → ㄹ → ㄴ","ㄷ → ㄹ → ㄴ → ㄱ"],"a":0,"c":"주식 운용은 크게 계획 → 실행 → 성과평가의 흐름이에요. 그 안에서 유니버스 선정 → 모델 포트폴리오 → 실제 포트폴리오 구축 → 점검·리밸런싱 순서로 진행해요.","e":"먼저 투자할 종목 범위를 정하고(ㄷ), 그 안에서 이상적인 모델 포트폴리오를 만든 뒤(ㄹ), 실제로 매매해 포트폴리오를 구축하고(ㄱ), 마지막으로 성과를 점검해 조정해요(ㄴ).","w":[null,"종목 범위(유니버스)를 정하지 않으면 모델 포트폴리오를 만들 재료가 없어요.","실제 매매는 목표가 되는 모델 포트폴리오를 만든 다음에 해요.","리밸런싱은 실제 포트폴리오를 만든 뒤에야 할 수 있어요."],"k":"장보기 목록(유니버스) → 레시피(모델) → 실제 요리(구축) → 맛보고 간 맞추기(리밸런싱)예요.","m":"유니버스 → 모델 → 실제 구축 → 점검·리밸런싱","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"하향식과 상향식","q":"주식 종목 선정의 하향식(Top-down)과 상향식(Bottom-up) 접근에 관한 설명으로 가장 적절하지 않은 것은?","o":["하향식은 경제 전망에서 출발해 유망 산업을 고르고 그 안에서 기업을 고른다","하향식은 개별 종목보다 섹터·산업·테마 선택을 더 중요하게 본다","상향식은 개별 기업의 내재가치 분석이 중심이고, 산업이나 국가 요인은 부차적으로 다룬다","하향식은 섹터를 촘촘하게 나눌수록 분석 부담이 줄어 마지막 종목 확정이 간단해진다"],"a":3,"c":"하향식은 '큰 그림 → 작은 그림'(경제 → 산업 → 기업), 상향식은 '개별 기업부터' 보는 방식이에요.","e":"하향식에서 섹터를 잘게 나눌수록 비교하고 판단해야 할 조각이 늘어나 종목을 고르기가 오히려 어려워져요.","w":["하향식의 기본 순서예요.","하향식은 무엇보다 어느 섹터에 비중을 둘지를 중시해요.","상향식은 좋은 회사를 먼저 찾고, 업종이나 국가는 뒤따르는 요소로 봐요.",null],"k":"하향식은 지도를 넓게 보고 동네를 고르는 것, 상향식은 마음에 드는 집부터 찾는 거예요.","m":"하향식: 경제 → 산업 → 기업 / 상향식: 기업 먼저","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"하","t":"사회책임투자(SRI)","q":"사회책임투자(SRI)와 ESG 투자에 관한 설명으로 가장 적절하지 않은 것은?","o":["담배·도박·무기 같은 업종을 투자대상에서 빼는 네거티브 스크리닝을 쓴다","특정 업종을 빼면 포트폴리오가 시장 전체와 다른 성장주·중소형주 편향을 가질 수 있다","ESG는 환경·사회·지배구조 같은 비재무적 요소로 기업을 평가하는 틀이다","장기 수익을 중시하는 연기금 같은 공적 기금은 사회적 가치를 따지지 않아 SRI를 거의 요구하지 않는다"],"a":3,"c":"SRI는 수익뿐 아니라 사회적 가치도 함께 고려하는 투자예요. 문제 업종이나 지배구조가 나쁜 기업을 걸러 내는 방식이 대표적이에요.","e":"공적 연기금은 장기 투자자이고 사회적 책임도 크기 때문에 오히려 SRI·ESG 투자를 적극적으로 요구하는 편이에요.","w":["네거티브(배제) 스크리닝은 SRI의 가장 기본적인 방법이에요.","걸러 낸 업종만큼 시장과 구성이 달라져 스타일 편향이 생길 수 있어요.","ESG는 재무제표 숫자가 아닌 비재무 정보를 봐요.",null],"k":"착한 가게만 골라 장을 보면, 일반 장바구니와 구성이 조금 달라지는 것과 같아요.","m":"SRI = 배제 스크리닝, 연기금이 주요 수요자","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"상","t":"포트폴리오 구성 모형","q":"주식 포트폴리오 구성에 쓰는 계량 모형에 관한 설명으로 가장 적절한 것은?","o":["2차함수 최적화모형은 기대수익률과 공분산을 오차 없이 추정하므로 추정오차 문제가 없다","다중요인모형은 개별 기업 고유의 사건만으로 주식의 위험을 나눠 분석한다","선형계획모형은 업종별 한도나 회전율 같은 제약을 지키면서 기대수익률이 가장 큰 종목 조합을 찾는다","이런 모형은 초과수익을 노리는 액티브 운용에서만 쓰이고 인덱스 운용에는 쓰이지 않는다"],"a":2,"c":"다중요인(다중지표)모형은 시장 민감도·기업 규모·성장성·업종 같은 공통 요인으로 위험을 분해하고, 선형계획모형은 제약조건 아래에서 목표(기대수익률)를 최대화해요.","e":"선형계획모형은 여러 제약을 만족하는 조합 가운데 기대수익률을 최대로 하는 해를 찾아요. 이런 모형은 인덱스펀드의 추적오차를 줄이는 최적화법처럼 패시브 운용에도 쓰여요.","w":["기대수익과 위험은 추정치라 오차가 생기고, 이 오차가 결과를 크게 흔드는 것이 이 모형의 약점이에요.","다중요인모형은 시장·규모·산업처럼 여러 종목에 공통으로 작용하는 체계적 요인을 써요.",null,"최적화법 인덱스펀드처럼 패시브 운용에서도 써요."],"k":"선형계획모형은 '예산과 칼로리 한도 안에서 가장 맛있는 식단'을 찾아 주는 계산기예요.","m":"선형계획 = 제약 속 기대수익 최대화","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"인핸스드 인덱스 판별","q":"다음 네 펀드의 최근 1년 성과 가운데 인핸스드 인덱스(준액티브) 펀드로 보기에 가장 알맞은 것은? (정보비율 = 초과수익률 ÷ 추적오차)\n• 갑: 초과수익률 0.1%, 추적오차 0.3%\n• 을: 초과수익률 4.0%, 추적오차 7.5%\n• 병: 초과수익률 1.2%, 추적오차 1.5%\n• 정: 초과수익률 −0.5%, 추적오차 2.0%","o":["갑","을","병","정"],"a":2,"c":"인핸스드 인덱스는 추적오차를 작게 묶어 두면서 벤치마크보다 조금 높은 수익을 꾸준히 내는 운용이에요. 그래서 추적오차가 작고 정보비율이 높게 나와요.","e":"병은 추적오차 1.5%로 작으면서 정보비율이 1.2 ÷ 1.5 = 0.8로 가장 높아요. 갑은 초과수익이 거의 없는 순수 인덱스, 을은 추적오차가 큰 액티브에 가까워요.","w":["추적오차와 초과수익이 모두 아주 작아 지수를 그대로 따라가는 인덱스펀드에 가까워요.","정보비율은 약 0.53이지만 추적오차 7.5%로 위험을 크게 진 액티브 운용이에요.",null,"초과수익이 음(−)이라 벤치마크를 밑돌았어요."],"k":"정해진 차선 안에서만 살짝 앞질러 가는 운전이 인핸스드 인덱스예요.","m":"인핸스드 = 작은 추적오차 + 높은 정보비율","f":"정보비율 = 초과수익률 ÷ 추적오차","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"혼합·규모·가치 스타일 판별","q":"다음 세 운용역의 종목 선정 방식을 액티브 운용 스타일로 바르게 짝지은 것은?\n• 갑: 종목을 가치주·성장주로 나누는 절차가 없다. 업종과 관계없이 스스로 계산한 적정주가보다 싸게 거래되는 종목이면 산다.\n• 을: 시가총액 순위로 중형주에 해당하는 종목만 골라 담는다.\n• 병: 지금은 이익이 부진하지만 정상 수준으로 돌아올 것으로 보고 PBR이 낮고 배당을 많이 주는 종목을 산다.","o":["갑 가치투자 — 을 혼합투자 — 병 성장투자","갑 혼합투자 — 을 시장가치(규모) — 병 가치투자","갑 성장투자 — 을 시장가치(규모) — 병 혼합투자","갑 혼합투자 — 을 가치투자 — 병 성장투자"],"a":1,"c":"액티브 운용 스타일은 가치투자, 성장투자, 혼합투자, 그리고 기업 규모로 나누는 시장가치 스타일로 구분해요. 혼합투자는 가치·성장 분류 없이 적정가치 대비 저평가 여부만 봐요.","e":"갑은 분류 없이 적정가치보다 싼지만 따지므로 혼합투자, 을은 시가총액 크기로 고르므로 시장가치(규모) 스타일, 병은 이익이 평균으로 돌아온다는 전제에서 PER·PBR이 낮고 배당수익률이 높은 종목을 사므로 가치투자예요. 가치투자의 고유 위험은 기대한 기간 안에 저평가가 풀리지 않는 것이에요.","w":["'적정가치보다 싸다'는 말만 보고 가치투자로 고르기 쉬워요. 갑은 저PER·저PBR 같은 특정 지표를 쓰지 않아요.",null,"갑은 이익 성장률을 기준으로 삼지 않아 성장투자가 아니고, 병은 저PBR·고배당이라는 지표가 분명한 가치투자예요.","을은 PER·PBR이 아니라 시가총액으로 고르므로 가치투자가 아니에요. 병의 저PBR·고배당은 성장주와 정반대 특징이에요."],"k":"옷을 고를 때 '브랜드 상관없이 정가보다 싸면 산다'는 사람이 혼합형, '중간 사이즈만 산다'는 사람이 규모형, '철 지난 할인 상품을 노린다'는 사람이 가치형이에요.","m":"분류 없이 적정가치 비교 = 혼합, 시가총액 = 시장가치, 저PER·저PBR·고배당 = 가치","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"맞춤형 인덱스와 준액티브의 세부","q":"인덱스 운용과 준액티브 운용에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 완전복제법은 벤치마크 종목을 모두 그 비중대로 담아 추적오차를 가장 작게 할 수 있지만, 매매할 종목이 많아 거래비용이 크고 보수 때문에 펀드 수익률은 벤치마크보다 조금 낮게 나온다.\nㄴ. 맞춤형 인덱스펀드는 투자자 요구에 맞춰 기존과 다른 기준으로 지수를 새로 짜거나, 저평가 종목 비중을 조금 늘리거나, 회전율을 낮춰 비용을 줄이는 방식으로 운용한다.\nㄷ. 준액티브 운용에서는 아직 분석하지 못해 판단을 미룬 종목도 벤치마크에서의 비중만큼은 그대로 보유한다.\nㄹ. 준액티브 운용은 잔차위험 한도를 두지 않고, 크게 오를 몇 종목에 집중해 초과수익을 최대로 키우는 것을 목표로 한다.","o":["1개","2개","3개","4개"],"a":2,"c":"준액티브(인핸스드 인덱스)는 인덱스를 기본으로 두고 추적오차를 일정 범위 안에서 관리하며 소폭의 초과수익을 노려요. 큰 한 방보다 작은 초과수익을 낼 종목을 여럿 찾는 데 초점을 둬요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. ㄹ은 잔차위험 제약 없이 초과수익 극대화를 노리는 순수 액티브 운용의 설명이에요. 준액티브는 늘어난 잔차위험을 보상하고도 남을 만큼의 초과수익이 있어야 의미가 있어요. 참고로 액티브펀드는 패시브펀드보다 잔차위험이 훨씬 높은 수준에서 넓게 퍼져 있어요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄷ도 옳아요. 모르는 종목은 벤치마크 비중대로 들고 가야 추적오차가 커지지 않아요.",null,"ㄹ은 틀렸어요. 추적오차 한도 없이 큰 초과수익을 노리는 것은 액티브 운용이에요."],"k":"준액티브는 시험 범위를 대부분 교과서대로 공부하고 자신 있는 몇 문제만 조금 더 파는 방식이에요. 모르는 부분은 남들처럼 기본대로 해 둬요.","m":"완전복제: 추적오차↓ 비용↑, 준액티브: 판단 보류 종목은 벤치마크 비중 유지","rev":0},{"s":3,"sec":"주식투자운용/투자전략","star":2,"lv":"중","t":"세 자산배분 전략의 성격","q":"전략적 자산배분, 전술적 자산배분, 보험자산배분의 성격을 비교한 설명 중 가장 적절하지 않은 것은?","o":["장기 비중을 정하는 전략적 자산배분은 시장을 효율적으로 보는 소극적 전략이며, 투자자의 위험 선호가 잠깐 흔들려도 장기 비중에 반영하지 않는다","전술적 자산배분은 시장의 일시적 비효율을 이용해 벤치마크를 웃도는 성과를 노리는 적극적 전략이다","보험자산배분은 앞날 주가를 내다보지 않고, 이미 벌어진 가격 움직임에 맞춰 아주 짧은 주기로 비중을 바꾼다","보험자산배분은 시장 예측력을 최대한 활용하는 적극적 전략이라 만기 목표수익률이 정해지지 않은 자금에 알맞다"],"a":3,"c":"전략적 자산배분은 장기 비중을 정하는 소극적 전략, 전술적 자산배분은 가격 착오를 이용하는 적극적 전략, 보험자산배분은 최소보장수준을 지키는 데 가장 큰 비중을 두는 수동적 전략이에요.","e":"보험자산배분은 예측 없이 실현된 가격 변화만 반영하는 수동적 전략이고, 정해진 기간 안에 목표수익률을 꼭 지켜야 하는 자금에 쓰여요. 앞날을 내다보고 초과수익을 겨냥하는 쪽은 전술적 자산배분이에요.","w":["장기 비중을 정하는 의사결정의 주체는 원칙적으로 투자자이고, 단기 위험 선호 변화는 반영하지 않아요.","가격 착오를 이용하므로 적극적 전략으로 분류해요.","오를 때 위험자산을 더 사고 내릴 때 덜어내는 추세순응형 매매를 매우 짧은 간격으로 반복해요.",null],"k":"전략적 배분은 1년 식단표, 전술적 배분은 그날 시장 가격을 보고 메뉴를 살짝 바꾸는 것, 보험 배분은 '통장 잔고가 바닥 밑으로는 안 내려가게'만 지키는 가계부예요.","m":"전략적 = 소극, 전술적 = 적극, 보험 = 수동·초단기·최소보장","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","t":"듀레이션과 볼록성","q":"〈보기〉의 채권에서 만기수익률이 3.5%로 0.5%p 하락할 때, (ㄱ) 수정듀레이션으로 추정한 가격 변화율과 (ㄴ) 이 추정치가 실제 가격 상승폭에 비해 어떤지를 순서대로 짝지은 것은?\n• 맥컬리 듀레이션: 5.2년\n• 현재 만기수익률: 연 4%(연 1회 이자 지급)","o":["+2.60%, 과대평가","+2.50%, 과소평가","+2.50%, 과대평가","+2.60%, 과소평가"],"a":1,"c":"수정듀레이션은 금리가 1%p 움직일 때 채권가격이 몇 % 움직이는지 보여 줘요. 다만 직선으로 추정하므로 휘어진(볼록한) 실제 가격 곡선과 차이가 나요.","e":"수정듀레이션 = 5.2 ÷ 1.04 = 5.0. 가격변동률 ≈ −5.0 × (−0.5%p) = +2.50%. 가격-수익률 곡선이 원점에 대해 볼록해서 금리가 내려갈 때 실제 상승폭은 2.50%보다 커요. 그래서 듀레이션 추정치는 상승폭을 과소평가해요.","f":"수정듀레이션 = 맥컬리 듀레이션 ÷ (1 + 만기수익률) · 가격변동률 ≈ −수정듀레이션 × 수익률 변화","w":["맥컬리 듀레이션 5.2를 그대로 써서 2.60%가 나왔고, 평가 방향도 반대예요.",null,"값은 맞지만 볼록성 때문에 실제 상승폭이 더 크므로 과소평가예요.","맥컬리 듀레이션을 (1 + 수익률)로 나누지 않았어요."],"k":"듀레이션은 곡선을 직선 자로 재는 것과 같아요. 볼록한 곡선이라 금리가 오르든 내리든 실제 가격은 자로 잰 것보다 늘 위에 있어요.","m":"맥컬리 ÷ (1+y) = 수정 · 듀레이션은 가격 상승은 작게, 하락은 크게 추정","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"내재선도이자율 계산","q":"1년 만기 현물이자율이 연 3%, 2년 만기 현물이자율이 연 4%이다. 불편기대이론에 따를 때 1년 후부터 1년간 적용될 것으로 기대되는 이자율에 가장 가까운 것은?","o":["3.5%","4.0%","5.0%","7.0%"],"a":2,"c":"불편기대이론에서는 장기 금리가 미래 단기 금리 기대치의 평균이에요. 그래서 1년짜리를 두 번 굴린 것과 2년짜리 한 번이 같아야 해요.","e":"(1.04)² = 1.03 × (1 + f) → 1 + f = 1.0816 ÷ 1.03 ≈ 1.0501, f ≈ 5.0%예요.","w":["두 금리를 단순 평균했어요.","2년 현물이자율을 그대로 썼어요.",null,"두 금리를 더했어요."],"k":"2년 동안 4%씩 받는 것과, 첫해 3% 받고 둘째 해 x% 받는 게 같아야 해요. 첫해가 낮으니 둘째 해는 더 높아야 해요(약 5%).","m":"(1 + r₂)² = (1 + r₁)(1 + f)","f":"f = 1.04² ÷ 1.03 − 1 ≈ 5.0%"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"소극적 채권운용 전략","q":"소극적 채권운용 전략에 해당하지 않는 것은?","o":["만기보유전략","채권면역전략","사다리형 만기운용전략","수익률곡선타기전략"],"a":3,"c":"소극적 운용은 금리를 예측하지 않고 정해진 규칙대로 운용해요. 적극적 운용은 금리나 수익률곡선 변화를 예측해 초과수익을 노려요.","e":"수익률곡선타기(롤링)전략은 수익률곡선의 모양을 이용해 만기 전에 팔아 차익을 노리는 적극적 전략이에요.","w":["만기까지 들고 가는 대표적인 소극적 전략이에요.","금리 변화 영향을 상쇄하는 소극적 전략이에요.","만기를 고르게 나눠 담는 소극적 전략이에요.",null],"k":"\"예측 안 하고 규칙대로\"면 소극적, \"앞으로 금리가 이렇게 될 테니 이렇게 하자\"면 적극적이에요.","m":"소극적: 만기보유·사다리·면역·현금흐름일치·인덱싱 / 적극적: 금리예측·롤링·스프레드"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"경상수익률 계산","q":"액면가 10,000원, 표면이율 연 6%(연 1회 후급)인 이표채를 9,600원에 샀다. 이 채권의 경상수익률로 가장 적절한 것은?","o":["5.76%","6.00%","6.25%","10.42%"],"a":2,"c":"경상수익률은 지금 낸 가격 대비 매년 받는 이자의 비율이에요. 만기 때 생기는 차익은 반영하지 않아요.","e":"연 이자 = 10,000 × 6% = 600원. 경상수익률 = 600 ÷ 9,600 = 6.25%예요.","w":["가격 9,600원에 표면이율 6%를 곱한 576원을 액면 10,000원으로 나눴어요. 경상수익률은 연 이자 600원을 가격으로 나눠요.","표면이율을 그대로 썼어요. 가격이 액면과 다르면 경상수익률도 달라요.",null,"연 이자 600원에 만기 차익 400원까지 더해 9,600원으로 나눴어요(1,000 ÷ 9,600). 경상수익률에는 만기 차익을 넣지 않아요."],"k":"9,600원 내고 매년 600원 받으니, 내 돈 대비 6.25%를 받는 셈이에요.","m":"경상수익률 = 연 이자 ÷ 현재 가격","f":"600 ÷ 9,600 = 6.25%"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"듀레이션의 성질","q":"채권의 듀레이션에 관한 설명으로 가장 적절하지 않은 것은? (다른 조건은 같다)","o":["만기가 길수록 듀레이션은 길어진다","표면이율이 높을수록 듀레이션은 짧아진다","만기수익률이 높을수록 듀레이션은 짧아진다","무이표채의 듀레이션은 만기보다 짧다"],"a":3,"c":"듀레이션은 채권 현금흐름이 들어오는 시점의 가중평균이에요. 돈이 늦게, 한꺼번에 들어올수록 길어져요.","e":"무이표채는 만기에 한 번만 현금이 들어오므로 듀레이션이 만기와 같아요.","w":["만기가 길면 현금이 늦게 들어와 듀레이션이 길어요.","이자를 많이 주면 돈이 일찍 들어와 짧아져요.","수익률이 높으면 먼 현금흐름의 현재가치 비중이 줄어 짧아져요.",null],"k":"중간에 이자를 안 주는 채권은 \"만기 날 한 번에 받기\"라서 평균 회수 시점이 바로 만기예요.","m":"듀레이션↑: 만기↑ · 표면이율↓ · 수익률↓ / 무이표채 D = 만기"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"맥컬리 듀레이션 계산","q":"액면 100원, 만기 2년, 표면이율 연 10%(연 1회 후급)인 채권의 만기수익률이 연 10%이다. 이 채권의 맥컬리 듀레이션에 가장 가까운 것은?","o":["1.50년","1.82년","1.91년","2.00년"],"a":2,"c":"맥컬리 듀레이션은 각 현금흐름의 현재가치를 가중치로 쓴 \"평균 회수 기간\"이에요.","e":"1년 차 현금 10의 현재가치 9.09, 2년 차 현금 110의 현재가치 90.91, 가격 100이에요. D = (1 × 9.09 + 2 × 90.91) ÷ 100 ≈ 1.91년이에요.","w":["현금흐름 가중치를 반영하지 않았어요.","만기 2년을 (1 + 수익률)로 나눈 값(2 ÷ 1.1 ≈ 1.82)이에요. 참고로 수정듀레이션은 1.91 ÷ 1.1 ≈ 1.74예요.",null,"무이표채라면 2년이지만 1년 차 이자가 있어 짧아요."],"k":"2년 동안 받는 돈 대부분이 2년 차에 몰려 있어서 2년에 조금 못 미치는 1.91년이에요.","m":"D = Σ(t × CF의 현재가치) ÷ 가격","f":"(1 × 9.09 + 2 × 90.91) ÷ 100 ≈ 1.91년"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"볼록성을 반영한 가격 변화","q":"수정듀레이션이 5, 볼록성이 50인 채권의 만기수익률이 1%p 오를 때, 듀레이션과 볼록성을 함께 반영한 가격 변화율에 가장 가까운 것은?","o":["−4.50%","−4.75%","−5.00%","−5.25%"],"a":1,"c":"듀레이션은 가격 변화를 직선으로 근사하고, 볼록성은 그 오차를 보정해 줘요. 볼록성 효과는 금리 방향과 관계없이 항상 플러스예요.","e":"듀레이션 효과 = −5 × 0.01 = −5%, 볼록성 효과 = ½ × 50 × (0.01)² = +0.25%. 합계 −4.75%예요.","w":["볼록성 효과를 두 배로 잡았어요.",null,"볼록성 효과를 빠뜨렸어요.","볼록성 효과를 빼 버렸어요."],"k":"듀레이션만 보면 5% 떨어지지만, 볼록성 덕분에 실제로는 조금 덜(4.75%) 떨어져요.","m":"ΔP/P ≈ −MD × Δy + ½ × C × (Δy)²","f":"−0.05 + 0.5 × 50 × 0.0001 = −4.75%"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"포트폴리오 듀레이션","q":"듀레이션 3년인 채권에 60억원, 듀레이션 8년인 채권에 40억원을 투자했다. 포트폴리오의 듀레이션은?","o":["4.0년","5.0년","5.5년","11.0년"],"a":1,"c":"포트폴리오 듀레이션은 각 채권 듀레이션을 투자 비중으로 가중평균해 구해요.","e":"0.6 × 3 + 0.4 × 8 = 1.8 + 3.2 = 5.0년이에요.","w":["짧은 채권 쪽으로 너무 치우친 값이에요. 가중평균을 다시 계산해 보세요.",null,"단순 평균했어요.","듀레이션을 그냥 더했어요."],"k":"돈을 많이 넣은 쪽(3년)에 더 가까운 평균이 나와요.","m":"D(포트) = Σ 비중 × D","f":"0.6 × 3 + 0.4 × 8 = 5.0년"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"채권면역전략","q":"채권면역전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["포트폴리오 듀레이션을 투자기간과 일치시킨다","금리 변동에 따른 가격위험과 재투자위험이 서로 상쇄되도록 한다","시간이 지나고 금리가 변하면 듀레이션을 다시 맞추는 재조정이 필요하다","처음 한 번 듀레이션을 맞추면 만기까지 재조정할 필요가 없다"],"a":3,"c":"면역전략은 금리가 오르든 내리든 목표 투자기간에 일정한 수익을 확보하려는 소극적 전략이에요.","e":"시간이 흐르면 듀레이션과 남은 투자기간이 같은 속도로 줄지 않고, 금리도 변해요. 그래서 주기적으로 재조정해야 면역 상태가 유지돼요.","w":["듀레이션 = 투자기간이 핵심이에요.","가격위험과 재투자위험이 상쇄돼요.","재조정이 필요해요.",null],"k":"균형 잡힌 시소도 시간이 지나면 기울어요. 그래서 계속 다시 맞춰야 해요.","m":"면역: D = 투자기간 · 가격위험 ↔ 재투자위험 상쇄 · 재조정 필요"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"현금흐름일치전략","q":"부채의 현금 유출 시점과 금액에 맞추어 채권의 현금 유입(이자·원금)이 발생하도록 포트폴리오를 짜는 전략으로 가장 적절한 것은?","o":["현금흐름일치전략","수익률곡선타기전략","바벨형 전략","금리예측전략"],"a":0,"c":"연기금이나 보험사처럼 미래에 갚을 돈이 정해진 기관은 그 시점에 맞춰 채권 현금흐름을 짤 수 있어요.","e":"부채의 현금흐름에 채권 현금흐름을 그대로 맞추는 것이 현금흐름일치전략이에요. 소극적 전략에 속해요.","w":[null,"수익률곡선타기는 만기 전 매도 차익을 노리는 적극적 전략이에요.","바벨형은 단기·장기에 집중하는 만기 구성 전략이에요.","금리예측전략은 금리를 예측해 듀레이션을 조절하는 적극적 전략이에요."],"k":"\"매달 갚을 돈\"에 맞춰 \"매달 들어올 돈\"을 짜 두는 방법이에요.","m":"현금흐름일치 = 부채 CF에 채권 CF 맞추기(소극적)"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"금리예측전략","q":"〈보기〉의 ( ) 안에 들어갈 말을 순서대로 바르게 나열한 것은?\n〈보기〉 금리 하락이 예상되면 포트폴리오의 듀레이션을 ( ㄱ ), 금리 상승이 예상되면 듀레이션을 ( ㄴ ).","o":["ㄱ 늘리고 – ㄴ 줄인다","ㄱ 줄이고 – ㄴ 늘린다","ㄱ 늘리고 – ㄴ 늘린다","ㄱ 줄이고 – ㄴ 줄인다"],"a":0,"c":"듀레이션이 길수록 금리 변화에 가격이 크게 반응해요. 금리가 내려갈 때는 크게 오르는 쪽, 오를 때는 덜 떨어지는 쪽이 유리해요.","e":"금리 하락 예상 시 장기채를 늘려 듀레이션을 늘리고, 금리 상승 예상 시 단기채로 바꿔 듀레이션을 줄여요.","w":[null,"방향이 반대예요.","금리 상승 예상 시에는 줄여야 해요.","금리 하락 예상 시에는 늘려야 해요."],"k":"금리가 내려갈 것 같으면 \"가격이 많이 오르는 긴 채권\"을 사요.","m":"금리↓ 예상 → D↑ / 금리↑ 예상 → D↓"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"신용스프레드 운용","q":"경기 회복으로 회사채와 국채의 신용스프레드가 줄어들 것으로 예상될 때 적절한 전략은?","o":["현금 비중을 늘리고 채권을 모두 판다","국채를 사고 회사채를 판다","회사채를 사고 국채를 판다","회사채와 국채를 모두 판다"],"a":2,"c":"신용스프레드는 회사채 수익률과 국채 수익률의 차이예요. 스프레드가 줄면 회사채 수익률이 상대적으로 내려가 회사채 가격이 상대적으로 올라요.","e":"스프레드 축소가 예상되면 회사채를 사고 국채를 팔아 상대 가격 변화에서 이익을 얻어요.","w":["스프레드 변화를 이용하지 못해요.","스프레드 확대가 예상될 때의 전략이에요.",null,"스프레드 전략이 아니라 전체 매도예요."],"k":"경기가 좋아지면 회사들이 덜 위험해 보여 회사채 값이 상대적으로 올라요.","m":"스프레드 축소 예상 → 회사채 매수 + 국채 매도"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"말킬의 채권가격정리","q":"말킬의 채권가격정리에 관한 설명으로 가장 적절하지 않은 것은?","o":["채권 가격과 수익률은 반대로 움직인다","만기가 길수록 같은 수익률 변화에 대한 가격 변동폭이 크다","같은 폭의 수익률 변화라면 수익률 하락 시 가격 상승폭이 수익률 상승 시 가격 하락폭보다 크다","표면이율이 높을수록 같은 수익률 변화에 대한 가격 변동률이 크다"],"a":3,"c":"말킬의 정리는 채권 가격이 수익률·만기·표면이율에 따라 어떻게 움직이는지 정리한 5가지 법칙이에요.","e":"표면이율이 낮을수록 가격 변동률이 커요. 이자를 적게 줄수록 만기 원금 비중이 커져 듀레이션이 길기 때문이에요.","w":["가격과 수익률은 역관계예요.","만기가 길수록 변동폭이 커요.","볼록성 때문에 상승폭이 더 커요.",null],"k":"이자를 적게 주는 채권일수록 \"만기에 몰빵\"이라 금리에 더 민감해요.","m":"말킬: 역관계 · 만기↑ 변동↑(체감) · 상승폭 > 하락폭 · 표면이율↓ 변동↑"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"만기와 가격 변동폭의 관계","q":"말킬의 채권가격정리에 따를 때, 만기가 길어짐에 따라 채권 가격 변동폭이 커지는 정도에 관한 설명으로 가장 적절한 것은?","o":["만기가 길어질수록 변동폭의 증가율은 점점 커진다(체증)","만기가 길어질수록 변동폭은 커지지만 그 증가율은 점점 작아진다(체감)","만기와 변동폭은 관계가 없다","만기가 길어질수록 변동폭은 줄어든다"],"a":1,"c":"만기가 길수록 가격이 더 크게 움직이지만, 1년 늘어날 때마다 추가로 커지는 정도는 점점 줄어요.","e":"만기가 길어질수록 가격 변동폭은 커지되, 그 증가율은 체감해요.","w":["증가율은 체증이 아니라 체감해요.",null,"만기가 길수록 변동폭이 커요.","만기가 길수록 변동폭이 커져요."],"k":"30년과 31년의 차이는 1년과 2년의 차이보다 훨씬 작아요.","m":"만기↑ → 변동폭↑, 증가율은 체감"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"시장분할이론","q":"채권시장이 만기별로 서로 분리되어 있고, 각 만기 시장의 수요와 공급에 따라 수익률이 결정된다고 보는 이론은?","o":["불편기대이론","유동성프리미엄이론","시장분할이론","선호영역이론"],"a":2,"c":"이자율 기간구조 이론은 만기별 수익률이 왜 다른지를 설명해요.","e":"만기별 시장이 완전히 분리되어 각자의 수급으로 수익률이 결정된다고 보는 것은 시장분할이론이에요.","w":["불편기대이론은 미래 단기금리 기대로 장기금리를 설명해요.","유동성프리미엄이론은 기대에 유동성 프리미엄을 더해요.",null,"선호영역이론은 선호 만기가 있지만 보상이 있으면 이동한다고 봐요."],"k":"단기 시장과 장기 시장이 서로 다른 동네처럼 따로 움직인다는 생각이에요.","m":"시장분할 = 만기별 분리 수급 · 선호영역 = 보상 있으면 이동"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"유동성프리미엄이론 계산","q":"1년 만기 현물이자율이 3%, 1년 후 1년 만기 이자율의 기대치가 3.5%, 2년 만기 채권의 유동성 프리미엄이 0.4%이다. 유동성프리미엄이론에 따른 2년 만기 이자율에 가장 가까운 것은? (산술평균으로 근사한다)","o":["3.25%","3.65%","3.90%","4.05%"],"a":1,"c":"유동성프리미엄이론은 장기금리 = 미래 단기금리 기대치의 평균 + 유동성 프리미엄이라고 봐요.","e":"(3% + 3.5%) ÷ 2 + 0.4% = 3.25% + 0.4% = 3.65%예요.","w":["유동성 프리미엄을 더하지 않았어요.",null,"2년 차 기대 이자율 3.5%에 프리미엄만 더했어요(3.5 + 0.4).","평균 3.25%에 프리미엄을 두 번 더했어요(3.25 + 0.8)."],"k":"기대 금리 평균(3.25%)에 \"오래 묶이는 대가\" 0.4%를 얹어 줘요.","m":"장기금리 ≈ 기대 단기금리 평균 + 유동성 프리미엄","f":"(3 + 3.5) ÷ 2 + 0.4 = 3.65%"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"이표채 가격 계산","q":"액면 10,000원, 만기 2년, 표면이율 연 6%(연 1회 후급)인 채권의 만기수익률이 연 5%일 때 가격에 가장 가까운 것은?","o":["9,816원","10,000원","10,186원","10,200원"],"a":2,"c":"이표채 가격은 매년 받는 이자와 만기 원금을 각각 만기수익률로 할인해 더한 값이에요.","e":"600 ÷ 1.05 + 10,600 ÷ 1.05² = 571.4 + 9,614.5 ≈ 10,186원이에요. 표면이율이 만기수익률보다 높아 액면보다 비싸게(할증) 거래돼요.","w":["할인 거래로 잘못 계산했어요.","표면이율과 만기수익률이 같을 때의 가격이에요.",null,"할인하지 않고 이자 차이만 더했어요."],"k":"시장보다 이자를 더 주는 채권이라 액면보다 조금 비싸요.","m":"P = Σ 이자 ÷ (1 + r)ᵗ + 원금 ÷ (1 + r)ⁿ","f":"600 ÷ 1.05 + 10,600 ÷ 1.1025 ≈ 10,186원"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"복리채 만기 상환금액","q":"액면 10,000원, 표면이율 연 4%, 만기 3년인 연 복리채의 만기 상환금액에 가장 가까운 것은?","o":["10,400원","11,200원","11,249원","11,699원"],"a":2,"c":"복리채는 중간에 이자를 주지 않고 이자에 이자가 붙어 만기에 한꺼번에 받아요.","e":"만기 상환금액 = 10,000 × (1.04)³ = 10,000 × 1.124864 ≈ 11,249원이에요.","w":["1년 치 이자만 붙였어요.","단리로 계산했어요.",null,"4년 복리로 계산했어요."],"k":"이자가 다시 이자를 낳아서 단리(11,200원)보다 조금 더 받아요.","m":"복리채 만기금액 = 액면 × (1 + 표면이율)ⁿ","f":"10,000 × 1.04³ ≈ 11,249원"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"할인 거래 채권의 수익률 관계","q":"시장에서 액면보다 낮은 가격에 거래되는 이표채의 표면이율, 경상수익률, 만기수익률의 크기를 바르게 나타낸 것은?","o":["경상수익률 < 표면이율 < 만기수익률","만기수익률 < 경상수익률 < 표면이율","표면이율 < 경상수익률 < 만기수익률","세 값이 모두 같다"],"a":2,"c":"가격이 액면보다 낮으면, 같은 이자를 더 싼 값에 받고(경상수익률↑), 만기에 차익까지 생겨요(만기수익률↑).","e":"할인 거래 채권은 표면이율 < 경상수익률 < 만기수익률 순이에요. 할증 거래 채권은 순서가 반대예요.","w":["경상수익률이 표면이율보다 커요.","할증 거래 채권의 순서예요.",null,"액면에 거래될 때만 셋이 같아요."],"k":"싸게 사면 이자율도 높아지고(경상), 만기 차익까지 붙어 더 높아져요(만기수익률).","m":"할인채권: 표면 < 경상 < 만기 / 할증채권: 반대"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"실효수익률","q":"채권의 실효수익률에 관한 설명으로 가장 적절한 것은?","o":["만기수익률과 항상 같다","중간에 받은 이자를 어떤 수익률로 재투자하느냐에 따라 달라진다","무이표채에서는 재투자수익률에 따라 크게 달라진다","표면이율과 항상 같다"],"a":1,"c":"만기수익률은 중간 이자를 만기수익률로 재투자한다고 가정해요. 실제로 재투자한 수익률을 반영한 것이 실효수익률이에요.","e":"실효수익률은 실제 재투자수익률에 따라 달라져요. 재투자수익률이 만기수익률보다 낮으면 실효수익률도 낮아져요.","w":["재투자수익률이 다르면 달라져요.",null,"무이표채는 중간 이자가 없어 재투자 영향이 없어요.","표면이율과는 다른 개념이에요."],"k":"받은 이자를 얼마에 다시 굴렸는지까지 따진 \"진짜\" 수익률이에요.","m":"실효수익률 = 실제 재투자수익률 반영"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"전환가치와 괴리율","q":"액면 10,000원, 전환가격 10,000원인 전환사채의 시장가격이 13,000원이고 주가는 12,000원이다. 전환가치와 괴리율로 가장 적절한 것은?","o":["전환가치 12,000원, 괴리율 약 8.3%","전환가치 10,000원, 괴리율 30%","전환가치 12,000원, 괴리율 약 −7.7%","전환가치 13,000원, 괴리율 0%"],"a":0,"c":"전환가치(패리티 가격)는 지금 주식으로 바꾸면 받는 가치이고, 괴리율은 전환사채 시장가격이 전환가치보다 얼마나 비싼지 보여 줘요.","e":"전환주식 수 = 10,000 ÷ 10,000 = 1주, 전환가치 = 12,000원. 괴리율 = (13,000 − 12,000) ÷ 12,000 ≈ 8.3%예요.","w":[null,"액면을 전환가치로 잘못 썼어요.","괴리율 분모를 시장가격으로 잡고 부호도 반대로 썼어요.","시장가격을 전환가치로 잘못 썼어요."],"k":"지금 바꾸면 12,000원짜리인데 13,000원에 팔리니, 약 8% 웃돈이 붙은 거예요.","m":"전환가치 = 주가 × 전환주식 수 · 괴리율 = (CB가격 − 전환가치) ÷ 전환가치","f":"(13,000 − 12,000) ÷ 12,000 ≈ 8.3%"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"전환사채와 신주인수권부사채","q":"전환사채(CB)와 신주인수권부사채(BW)에 관한 설명으로 가장 적절하지 않은 것은?","o":["CB는 권리를 행사하면 사채가 소멸하고 주식으로 바뀐다","BW는 권리를 행사할 때 별도로 주금을 납입해야 한다","분리형 BW는 신주인수권을 행사해도 사채는 남는다","CB도 전환권을 행사할 때 추가로 주금을 납입해 회사에 새 자금이 들어온다"],"a":3,"c":"CB는 채권을 주식으로 \"바꾸는\" 것이고, BW는 채권은 그대로 두고 주식을 \"추가로 살 권리\"가 붙은 것이에요.","e":"CB는 사채 원금이 주식으로 바뀌는 것이라 추가 납입이 없어요. 새 자금이 들어오는 것은 BW의 신주인수권 행사 때예요.","w":["CB는 전환하면 사채가 사라져요.","BW는 행사 시 주금을 납입해요.","분리형 BW는 사채가 남아요.",null],"k":"CB는 \"채권 → 주식 교환\", BW는 \"채권 + 주식 살 쿠폰\"이에요.","m":"CB: 사채 소멸·추가 납입 X / BW: 추가 납입·사채 존속"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"교환사채","q":"교환사채(EB)에 관한 설명으로 가장 적절한 것은?","o":["발행회사가 새로 발행하는 신주로 교환해 준다","발행회사가 보유한 다른 회사의 주식 등으로 교환해 준다","교환하면 발행회사의 자본금이 늘어난다","교환 시 투자자가 별도로 대금을 납입해야 한다"],"a":1,"c":"교환사채는 발행회사가 이미 가지고 있는 주식(주로 다른 회사 주식)으로 바꿔 주는 사채예요.","e":"교환 대상은 발행회사가 보유한 상장주식 등이에요. 교환하면 발행회사의 자산(보유 주식)과 부채(사채)가 함께 줄고 자본금은 변하지 않아요.","w":["신주로 바꿔 주는 것은 전환사채예요.",null,"신주를 발행하지 않으므로 자본금이 늘지 않아요.","추가 납입이 없어요."],"k":"회사 금고에 있던 남의 회사 주식을 채권 대신 내주는 거예요.","m":"EB = 보유 주식으로 교환 · 자본금 변동 X"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"수의상환채권과 수의상환청구채권","q":"수의상환채권(callable bond)과 수의상환청구채권(putable bond)에 관한 설명으로 가장 적절하지 않은 것은?","o":["수의상환채권은 발행자가 만기 전에 상환할 권리를 가진다","수의상환채권은 금리가 떨어지면 조기상환될 가능성이 커진다","수의상환청구채권은 투자자가 만기 전 상환을 요구할 권리를 가진다","수의상환청구채권은 투자자에게 불리하므로 일반 채권보다 수익률이 높다"],"a":3,"c":"권리를 가진 쪽이 유리해요. 발행자에게 권리가 있으면 투자자는 더 높은 수익률을, 투자자에게 권리가 있으면 더 낮은 수익률을 받아들여요.","e":"수의상환청구채권은 투자자에게 유리한 권리가 붙어 있어 일반 채권보다 수익률이 낮아요.","w":["콜 권리는 발행자에게 있어요.","금리가 내리면 발행자가 싸게 다시 빌리려고 상환해요.","풋 권리는 투자자에게 있어요.",null],"k":"\"내가 언제든 돌려 달라고 할 수 있는 채권\"은 안전한 만큼 이자가 적어요.","m":"콜(발행자 권리) → 수익률↑ / 풋(투자자 권리) → 수익률↓"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"변동금리부채권(FRN)","q":"변동금리부채권(FRN)에 관한 설명으로 가장 적절한 것은?","o":["표면이율이 발행 때 고정되어 만기까지 바뀌지 않는다","기준금리에 가산금리를 더해 이자율을 주기적으로 다시 정하므로 금리 변동에 따른 가격위험이 작다","같은 만기의 고정금리채보다 듀레이션이 길다","기준금리가 오르면 받는 이자가 줄어든다"],"a":1,"c":"FRN은 시장금리에 맞춰 이자율을 계속 다시 정하는 채권이에요. 그래서 가격이 액면 근처에서 크게 벗어나지 않아요.","e":"이자율이 기준금리 + 가산금리로 주기적으로 재설정되므로 금리위험이 작고 듀레이션도 다음 재설정일까지로 짧아요.","w":["고정금리채의 특징이에요.",null,"재설정 덕분에 듀레이션이 짧아요.","기준금리가 오르면 이자도 늘어요(역변동금리채는 반대)."],"k":"금리가 바뀌면 이자도 따라 바뀌니까, 채권 값이 크게 흔들릴 이유가 없어요.","m":"FRN = 기준금리 + 가산금리 · 주기적 재설정 · 금리위험 작음"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"MBS의 조기상환위험","q":"주택저당증권(MBS)에 관한 설명으로 가장 적절한 것은?","o":["금리가 떨어지면 조기상환이 줄어든다","원리금이 만기에 한꺼번에 지급된다","금리가 떨어지면 대출자들이 조기상환을 늘려 투자자는 낮은 금리로 재투자해야 하는 위험을 진다","조기상환위험이 없어 일반 채권보다 수익률이 낮다"],"a":2,"c":"MBS는 주택담보대출을 묶어 만든 증권이라 대출자가 대출을 일찍 갚으면 투자자도 원금을 일찍 돌려받아요.","e":"금리가 떨어지면 대출자들이 더 싼 대출로 갈아타며 조기상환이 늘어요. 투자자는 돌려받은 돈을 낮은 금리로 재투자해야 해요.","w":["금리가 떨어지면 조기상환이 늘어요.","대출 상환 구조를 따라 매월 원리금이 지급되는 경우가 많아요.",null,"조기상환위험 때문에 수익률이 더 높은 편이에요."],"k":"금리가 내려 다들 대출을 갈아타면, 비싼 이자를 기대한 MBS 투자자는 손해를 봐요.","m":"MBS: 금리↓ → 조기상환↑ → 재투자위험"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"신용등급과 채권 가격","q":"회사채의 신용등급이 하향 조정될 때 나타나는 현상으로 가장 적절한 것은?","o":["무위험이자율이 올라 국채 가격도 함께 내린다","신용스프레드는 변하지 않고 가격만 내린다","신용스프레드가 커지고 채권 가격이 내린다","신용스프레드가 줄어들고 채권 가격이 오른다"],"a":2,"c":"신용등급이 낮아지면 부도 위험이 커졌다고 보고 투자자들이 더 높은 수익률을 요구해요.","e":"요구수익률이 오르면서 국채 대비 신용스프레드가 커지고, 채권 가격은 내려가요.","w":["국채 금리와는 직접 관계가 없어요.","스프레드가 커지는 것이 가격 하락의 원인이에요.",null,"반대 방향이에요."],"k":"믿음이 떨어진 회사에 돈을 빌려주려면 더 높은 이자를 받아야 하니, 기존 채권 값은 떨어져요.","m":"등급↓ → 스프레드↑ → 가격↓"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"수익률곡선 역전","q":"장기 국채 수익률이 단기 국채 수익률보다 낮아지는 수익률곡선 역전 현상에 관한 일반적인 해석으로 가장 적절한 것은?","o":["유동성 프리미엄이 커졌다는 신호로 본다","향후 경기 확장과 금리 상승을 예상하는 신호로 본다","향후 경기 둔화와 금리 하락을 예상하는 신호로 본다","수익률곡선 모양은 경기와 관계가 없다"],"a":2,"c":"불편기대이론에 따르면 장기금리는 미래 단기금리 기대를 반영해요. 장기금리가 단기금리보다 낮다는 것은 앞으로 금리가 내려갈 것으로 본다는 뜻이에요.","e":"수익률곡선 역전은 시장이 앞으로 경기 둔화와 금리 인하를 예상한다는 신호로 해석돼요.","w":["유동성 프리미엄이 커지면 곡선이 더 가팔라져요.","우상향(가파른) 곡선의 해석이에요.",null,"경기 예측 지표로 널리 쓰여요."],"k":"\"앞으로 금리가 내려갈 거야\" = \"경기가 나빠질 거야\"라는 시장의 신호예요.","m":"역전(우하향) = 경기 둔화·금리 하락 예상"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"사다리형 만기 전략","q":"사다리형 만기 운용 전략에 관한 설명으로 가장 적절한 것은?","o":["보유 채권의 만기를 단기와 장기 두 곳에만 집중한다","보유 채권을 만기별로 고르게 나누어 보유하고, 만기가 된 채권은 가장 긴 만기로 다시 투자한다","금리 예측에 따라 만기를 수시로 바꾸는 적극적 전략이다","특정 시점 하나에 만기를 모두 맞춘다"],"a":1,"c":"사다리형은 사다리 칸처럼 만기를 고르게 배치해 금리 변화의 영향을 평균화하는 소극적 전략이에요.","e":"만기를 고르게 나누고, 만기가 돌아온 채권은 가장 긴 만기로 재투자해 구조를 유지해요. 관리가 쉽고 금리 예측이 필요 없어요.","w":["바벨형이에요.",null,"사다리형은 예측하지 않는 소극적 전략이에요.","불릿형이에요."],"k":"1년·2년·3년·4년·5년짜리를 골고루 들고 있다가, 1년짜리가 끝나면 5년짜리를 새로 사는 방식이에요.","m":"사다리형 = 만기 균등 분산 · 만기분은 최장기로 재투자"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"채권 인덱싱 전략","q":"채권 인덱싱 전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["채권지수의 수익률을 따라가는 것을 목표로 한다","소극적 채권운용 전략에 속한다","추적오차를 줄이는 것이 중요하다","금리 변화를 예측해 지수보다 높은 초과수익을 노린다"],"a":3,"c":"인덱싱은 시장 평균(채권지수)을 따라가는 전략이에요. 예측을 하지 않으니 비용이 적어요.","e":"금리를 예측해 초과수익을 노리는 것은 적극적 전략이에요. 인덱싱은 지수 수익률 복제가 목표예요.","w":["지수 수익률 추종이 목표예요.","소극적 전략이에요.","추적오차 관리가 핵심이에요.",null],"k":"\"시장 평균만큼만 벌자\"는 전략이라 예측은 하지 않아요.","m":"인덱싱 = 지수 추종 · 소극적 · 추적오차 관리"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"역변동금리채","q":"기준금리가 오르면 이자율이 내려가는 역변동금리채에 관한 설명으로 가장 적절한 것은?","o":["금리 상승기에 투자자에게 유리하다","같은 만기의 고정금리채보다 금리 변화에 대한 가격 민감도가 크다","변동금리부채권과 금리위험 특성이 같다","기준금리와 이자율이 같은 방향으로 움직인다"],"a":1,"c":"역변동금리채는 금리가 오르면 이자가 줄고 할인율도 높아져, 가격이 이중으로 떨어져요.","e":"금리 변화가 이자와 할인율 양쪽에 같은 방향의 손실을 주므로 가격 민감도(듀레이션)가 고정금리채보다 커요.","w":["금리 상승기에 불리해요.",null,"변동금리부채권과 반대로 금리위험이 커요.","반대 방향으로 움직여요."],"k":"금리가 오르면 \"이자도 줄고, 값도 떨어지는\" 이중 타격을 받는 채권이에요.","m":"역변동금리채: 금리↑ → 이자↓ · 듀레이션 큼"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"물가연동국채","q":"물가연동국채에 관한 설명으로 가장 적절한 것은?","o":["물가가 오르면 원금이 줄어든다","인플레이션위험이 일반 국채보다 크다","물가가 오르면 원금이 물가에 연동해 늘어난다","이자율이 물가와 반대로 움직인다"],"a":2,"c":"물가연동국채는 원금을 물가지수에 연동해 조정하므로 물가 상승에도 실질 구매력을 지켜 줘요.","e":"물가가 오르면 원금이 물가상승률만큼 늘어나고, 이자도 늘어난 원금에 표면이율을 곱해 지급해요.","w":["물가가 오르면 원금이 늘어요.","인플레이션위험을 줄여 주는 채권이에요.",null,"표면이율은 고정이고 원금이 조정돼요."],"k":"물가가 오르면 원금도 같이 올라서 \"돈 가치가 떨어지는 걱정\"이 줄어요.","m":"물가연동국채 = 원금이 물가에 연동 · 인플레이션 방어"},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"국내 채권 이자 지급 관행","q":"국내 채권의 이자 지급 방식과 발행 관행에 관한 설명으로 가장 적절하지 않은 것은?","o":["국고채는 보통 6개월마다 이자를 주는 이표채로 발행된다","국민주택채권 1종은 복리채로 발행되어 만기에 원금과 이자를 한꺼번에 받는다","만기 1년 이하의 통화안정증권은 할인 방식으로 발행하는 경우가 많다","보증사채와 무보증사채는 이자를 지급하는 방법에 따라 나눈 분류이다"],"a":3,"c":"이자 지급 방법에 따라 채권은 이표채, 할인채, 복리채(단리채)로 나눠요. 회사채는 보통 3개월마다 이자를 주는 이표채예요.","e":"보증사채·무보증사채는 보증기관 같은 제3자가 원리금 상환을 책임지는지로 나눈 분류예요. 이자 지급 방법과는 관계가 없어요.","w":["국고채의 이자 지급 주기는 6개월이에요.","국민주택채권 1종은 대표적인 복리채예요.","1년 이하 통안증권은 할인해서 발행하고 만기에 액면을 줘요.",null],"k":"보증채냐 아니냐는 '누가 뒷배를 서 주느냐'이고, 이표채·할인채·복리채는 '이자를 언제 어떻게 받느냐'예요.","m":"국고채 6개월·회사채 3개월 이표 / 통안 할인 / 국민주택1종 복리","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"상","t":"스프레드지수와 대응","q":"회사채 A와 국고채 사이의 신용스프레드가 과거 평균 60bp, 표준편차 10bp였는데 지금은 85bp까지 벌어졌다. 운용자는 스프레드지수가 ±2를 벗어나면 정상 수준으로 돌아온다고 보고 포지션을 잡는다. (ㄱ) 스프레드지수와 (ㄴ) 적절한 대응을 짝지은 것은?","o":["2.5 — 회사채 A를 사고 국고채를 판다","2.5 — 국고채를 사고 회사채 A를 판다","0.4 — 구간 안이므로 포지션을 잡지 않는다","2.5 — 구간 안이므로 포지션을 잡지 않는다"],"a":0,"c":"스프레드 운용전략은 두 채권의 수익률 차이가 일시적으로 벌어졌다가 평균으로 돌아오는 성질을 이용하는 적극적 전략이에요.","e":"스프레드지수 = (85 − 60) ÷ 10 = 2.5로 +2를 벗어났어요. 스프레드가 줄어들 것으로 보므로, 상대적으로 수익률이 높은(가격이 싼) 회사채 A를 사고 국고채를 팔아요.","w":[null,"스프레드가 더 벌어질 때 이익이 나는 포지션이라 방향이 반대예요.","25 ÷ 60처럼 잘못 나눈 값이에요. 평균과의 차이를 표준편차로 나눠야 해요.","2.5는 ±2 구간 밖이라 포지션을 잡을 신호예요."],"k":"고무줄이 평소보다 많이 늘어나면 곧 줄어들 거라 보고 미리 자리를 잡는 거예요.","m":"스프레드지수 = (현재 − 평균) ÷ 표준편차","f":"스프레드지수 = (현재 스프레드 − 평균 스프레드) ÷ 스프레드 표준편차","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"채권 교체전략의 종류","q":"채권 교체(스왑)전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["동종채권 교체는 조건이 거의 같은 두 채권에 일시적으로 다른 가격이 붙었을 때 싼 쪽으로 갈아타는 것이다","이종채권 교체는 경기에 따라 넓어지고 좁아지는 채권 사이 스프레드를 이용한다","적극적 전략이라 시장이 효율적일 때는 남보다 나은 성과를 내기 힘들다","수익률 획득 교체(Yield pick-up swap)는 신용위험을 줄이려고 수익률이 더 낮은 우량채로 갈아타는 것이다"],"a":3,"c":"채권 교체전략은 가격이 잘못 매겨진 채권이나 스프레드 변화를 이용해 보유 채권을 바꾸는 적극적 전략이에요.","e":"Yield pick-up swap은 이름 그대로 수익률을 더 얻기 위해 수익률이 높은 채권으로 바꾸는 교체예요. 낮은 수익률의 우량채로 옮기는 것과는 반대예요.","w":["같은 성격의 채권 사이 일시적 가격 차이를 이용하는 것이 동종채권 교체예요.","국채와 회사채처럼 다른 종류 채권 간 스프레드 변화를 노려요.","적극적 전략은 시장의 비효율성을 전제로 해요.",null],"k":"pick-up은 '더 줍는다'는 뜻이라, 이자를 더 주는 채권으로 옮기는 거예요.","m":"Yield pick-up = 더 높은 수익률로 교체","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"채권 발행방식","q":"채권 발행방식에 관한 설명으로 가장 적절하지 않은 것은?","o":["복수가격(Conventional) 경매에서는 낙찰자마다 자신이 써낸 수익률이 적용되어 발행조건이 여러 개 생긴다","단일가격(Dutch) 경매에서는 낙찰된 수익률 가운데 가장 높은 수익률로 모든 낙찰자의 조건을 통일한다","총액인수는 인수기관이 발행물량을 모두 사들인 뒤 투자자에게 팔기 때문에 팔리지 않는 위험을 인수기관이 진다","무보증사채는 대부분 발행회사가 인수기관 없이 투자자에게 직접 판매하는 방식으로 발행된다"],"a":3,"c":"채권 발행은 발행자가 직접 파는 직접발행과 인수기관을 거치는 간접발행으로 나뉘어요. 회사채는 주로 간접발행 가운데 총액인수 방식을 써요.","e":"무보증사채는 증권회사 같은 인수기관이 물량을 모두 떠안는 총액인수(간접발행)로 발행되는 것이 대부분이에요.","w":["각자 써낸 수익률대로 낙찰되므로 조건이 여러 개예요.","가장 높은 낙찰 수익률 하나로 통일해요.","미매각 위험을 인수기관이 부담하는 것이 총액인수의 특징이에요.",null],"k":"회사채는 도매상(증권사)이 한꺼번에 사서 소매로 파는 구조라고 생각하면 돼요.","m":"Conventional = 복수 조건 / Dutch = 최고 낙찰수익률 하나 / 회사채 = 총액인수","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","t":"기간구조 이론 비교","q":"이자율 기간구조 이론에 관한 〈보기〉의 설명 가운데 옳은 것만을 모두 고른 것은?\nㄱ. 유동성프리미엄이론에서는 미래 단기금리가 지금과 같을 것으로 예상되어도 수익률곡선이 우상향할 수 있다.\nㄴ. 유동성프리미엄은 만기가 길수록 커지지만 커지는 폭은 점점 줄어든다.\nㄷ. 선호영역이론에서는 각 만기 구간의 기간프리미엄이 음(−)이 될 수도 있다.\nㄹ. 시장분할이론에서는 충분한 보상만 주어지면 투자자가 언제든 다른 만기 시장으로 옮겨 간다.","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1,"c":"불편기대이론은 장단기채가 완전 대체관계이고 투자자가 위험중립적이라고 봐요. 유동성프리미엄이론은 장기채에 프리미엄(+)이 붙는다고 보고, 선호영역이론은 투자자가 선호 구간을 갖되 보상이 충분하면 다른 구간으로 옮긴다고 봐요.","e":"ㄱ, ㄴ, ㄷ이 옳아요. ㄹ은 선호영역이론의 설명이에요. 시장분할이론은 만기별 시장이 완전히 분리되어 투자자가 다른 만기로 옮겨 가지 않는다고 봐요.","w":["ㄷ도 옳아요. 선호영역이론의 기간프리미엄은 양(+)일 수도 음(−)일 수도 있어요.",null,"ㄹ은 시장분할이론이 아니라 선호영역이론의 내용이에요.","ㄴ은 옳고 ㄹ은 틀렸어요."],"k":"시장분할은 '각자 자기 동네에서만 장보기', 선호영역은 '단골 동네가 있지만 할인이 크면 옆 동네도 간다'예요.","m":"유동성P = 항상 +, 체감 / 선호영역 = ± 가능, 이동 가능 / 시장분할 = 이동 없음","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"롤링효과와 숄더효과","q":"수익률곡선타기 전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["오른쪽 위로 올라가는 수익률곡선 모양이 투자기간 동안 크게 변하지 않는다고 가정한다","잔존만기가 줄면서 수익률이 내려가 생기는 자본이익을 롤링효과라 한다","곡선이 가파른 단기 구간에서 만기가 짧아질 때 수익률이 크게 떨어져 생기는 이익을 숄더효과라 한다","불편기대이론이 맞는 시장이라도 롤링효과를 이용하면 확실한 초과수익을 얻을 수 있다"],"a":3,"c":"수익률곡선타기는 우상향 곡선에서 채권을 사서 만기가 짧아질 때 수익률이 떨어지는(가격이 오르는) 효과를 노리고 만기 전에 파는 적극적 전략이에요.","e":"불편기대이론이 맞다면 우상향 곡선은 미래 금리 상승을 예상한다는 뜻이라, 곡선이 그대로 유지되지 않아 초과수익을 얻을 수 없어요.","w":["곡선 모양이 유지되어야 만기가 짧아질 때 수익률이 내려가요.","장기채를 보유하는 동안 만기가 줄며 생기는 이익이 롤링효과예요.","단기 구간처럼 곡선이 꺾이는 어깨(shoulder) 부분에서 생기는 이익이 숄더효과예요.",null],"k":"내리막 미끄럼틀(우상향 곡선)이 그대로 있어야 타고 내려오며 속도(이익)가 붙어요.","m":"롤링 = 장기 구간, 숄더 = 단기 구간, 불편기대 성립 시 초과수익 없음","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"볼록성 결정 요인","q":"다른 조건이 같을 때 채권의 볼록성에 관한 설명으로 가장 적절하지 않은 것은?","o":["쿠폰(표면이율)이 작을수록 볼록성은 커진다","만기수익률이 낮을수록 볼록성이 크다","듀레이션이 커지면 볼록성은 그보다 더 빠르게(체증적으로) 커진다","만기가 먼 채권일수록 가격-수익률 곡선이 펴져 볼록성이 줄어든다"],"a":3,"c":"볼록성은 가격-수익률 곡선이 휘어진 정도예요. 듀레이션을 길게 만드는 조건(긴 만기, 낮은 표면이율, 낮은 수익률)이 볼록성도 키워요.","e":"만기가 길수록 듀레이션이 길어지고 볼록성은 그보다 더 빠르게 커져요. 그래서 만기가 먼 채권일수록 볼록성이 커요.","w":["이자를 적게 줄수록 현금흐름이 뒤쪽에 몰려 볼록성이 커요.","수익률이 낮을 때 곡선이 더 휘어져요.","볼록성은 대략 듀레이션의 제곱에 비례해 늘어나요.",null],"k":"멀리 날아가는 공일수록 궤적이 더 크게 휘는 것처럼, 만기가 길수록 곡선이 더 휘어요.","m":"볼록성↑: 만기 길수록, 표면이율 낮을수록, 수익률 낮을수록","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","t":"반기 이표채 수정듀레이션","q":"이자를 연 2회 지급하는 채권의 만기수익률이 연 6%이고 맥컬리 듀레이션이 4.12년이다. 이 채권의 (ㄱ) 수정듀레이션과 (ㄴ) 만기수익률이 0.5%p 오를 때 수정듀레이션으로 추정한 가격변동률을 순서대로 짝지은 것은?","o":["4.00 — −2.00%","3.89 — −1.94%","4.12 — −2.06%","4.00 — +2.00%"],"a":0,"c":"수정듀레이션 = 맥컬리 듀레이션 ÷ (1 + 만기수익률 ÷ 연간 이자지급 횟수)예요. 이자를 1년에 여러 번 주면 수익률을 횟수로 나눠서 써요.","e":"수정듀레이션 = 4.12 ÷ (1 + 0.06 ÷ 2) = 4.12 ÷ 1.03 = 4.00이에요. 가격변동률 ≈ −4.00 × 0.5%p = −2.00%예요.","w":[null,"연 2회 지급인데 1.06으로 나눠 반기 조정을 빠뜨렸어요.","맥컬리 듀레이션을 그대로 써서 수정하지 않았어요.","금리가 오르면 채권 가격은 내려가므로 부호가 틀렸어요."],"k":"이자를 반년마다 받으면 한 번에 쓰는 할인율도 반으로 쪼개서 계산해요.","m":"MD = D ÷ (1 + y/n)","f":"수정듀레이션 = 맥컬리 듀레이션 ÷ (1 + y ÷ n), 가격변동률 ≈ −MD × Δy","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"전환사채 패리티","q":"액면 10,000원, 전환가격 8,000원인 전환사채가 있고 전환대상 주식의 현재 주가는 9,200원이다. 이 전환사채의 (ㄱ) 패리티와 (ㄴ) 액면 1매당 전환가치를 순서대로 짝지은 것은?","o":["92% — 9,200원","115% — 11,500원","115% — 9,200원","125% — 12,500원"],"a":1,"c":"패리티는 주가가 전환가격의 몇 %인지 보여 주는 값이에요. 전환가치는 전환해서 받는 주식의 시가 총액이에요.","e":"패리티 = 9,200 ÷ 8,000 = 115%예요. 전환주식 수 = 10,000 ÷ 8,000 = 1.25주이므로 전환가치 = 1.25 × 9,200 = 11,500원(= 액면 × 패리티)이에요.","w":["주가를 액면(10,000원)으로 나눠 92%로 잘못 계산했고, 전환가치도 주식 1주 값만 적었어요. 패리티는 주가를 전환가격으로 나눠요.",null,"패리티는 맞지만 전환가치를 주식 1주 값으로 착각했어요.","액면 ÷ 전환가격(1.25)을 패리티로 잘못 봤어요."],"k":"패리티 115%는 '전환하면 액면보다 15% 더 값어치 있는 주식을 받는다'는 뜻이에요.","m":"패리티 = 주가 ÷ 전환가격","f":"패리티 = 주가 ÷ 전환가격 × 100, 전환가치 = 액면 × 패리티","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"상","t":"잔존 1년 미만 할인채 관행 계산","q":"만기수익률 연 8%, 액면 10,000원인 할인채의 잔존기간이 2년 219일이다. 국내 관행(1년 미만 기간은 단리로 할인)에 따라 계산한 가격에 가장 가까운 것은? (1년은 365일로 계산한다)","o":["8,573원","8,278원","8,181원","7,938원"],"a":2,"c":"국내 채권시장에서는 잔존기간 중 1년 단위 기간은 복리로, 남은 1년 미만 기간은 단리로 할인하는 관행식을 써요.","e":"219일 ÷ 365일 = 0.6년이에요. 가격 = 10,000 ÷ [(1.08)² × (1 + 0.08 × 0.6)] = 10,000 ÷ (1.1664 × 1.048) ≈ 8,181원이에요.","w":["남은 219일을 빼고 2년만 할인했어요.","전체 기간을 단리로 할인했어요(10,000 ÷ 1.208).",null,"잔존기간을 3년으로 올려서 할인했어요."],"k":"꽉 찬 해는 이자에 이자가 붙는 복리로, 자투리 날짜는 단순 이자로 계산하는 셈이에요.","m":"할인채 = 액면 ÷ [(1+r)^n × (1 + r × d/365)]","f":"가격 = 액면 ÷ [(1 + r)ⁿ × (1 + r × d/365)]","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"옵션부사채 가치와 행사","q":"옵션이 붙은 채권에 관한 설명으로 가장 적절하지 않은 것은?","o":["수의상환채권은 발행자가 가진 콜옵션 가치만큼 같은 조건 일반채권보다 싸다","수의상환청구채권은 투자자가 가진 풋옵션 가치만큼 같은 조건 일반채권보다 비싸다","전환사채·신주인수권부사채·교환사채는 주식 관련 권리가 붙어 같은 조건 일반사채보다 표면이율이 낮게 발행된다","수의상환청구채권 보유자는 시장금리가 내려가 채권값이 오를 때 상환을 청구하는 것이 유리하다"],"a":3,"c":"수의상환채권은 발행자가 콜옵션을, 수의상환청구채권은 투자자가 풋옵션을 가진 채권이에요. 투자자에게 유리한 권리가 붙으면 표면이율이 낮아져요.","e":"시장금리가 올라 채권값이 떨어질 때 액면으로 돌려받는 것이 유리하므로, 상환 청구 유인은 금리 상승기에 커져요.","w":["발행자가 가진 콜옵션만큼 투자자에게 불리하니 가치에서 빼요.","투자자가 가진 풋옵션만큼 가치가 더해져요.","주식으로 바꿀 권리라는 덤이 있어 이자를 덜 줘도 팔려요.",null],"k":"풋옵션은 '값이 떨어지면 정가에 되돌려 줄 수 있는 환불권'이라 값이 떨어질 때 써요.","m":"콜러블 = 일반 − 콜 / 풋터블 = 일반 + 풋(금리↑ 때 행사)","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"채권 투자 위험의 종류","q":"채권 투자 위험에 관한 〈보기〉의 설명 가운데 옳은 것은 모두 몇 개인가?\nㄱ. 할인채를 만기까지 보유해도 중간 이자의 재투자 문제 때문에 실현수익률이 만기수익률과 달라질 수 있다.\nㄴ. 수의상환채권 투자자는 금리가 떨어지면 조기상환을 당해 낮은 금리로 재투자해야 하는 위험을 진다.\nㄷ. 매수호가와 매도호가의 차이가 클수록 유동성위험이 크다.\nㄹ. 물가가 올라 돌려받을 돈의 구매력이 떨어지는 위험을 구매력위험이라 한다.","o":["1개","2개","3개","4개"],"a":2,"c":"채권 위험에는 금리(가격·재투자)위험, 채무불이행위험, 중도상환위험, 유동성위험, 구매력(인플레이션)위험 등이 있어요.","e":"ㄴ, ㄷ, ㄹ이 옳아 3개예요. 할인채는 중간에 받는 이자가 없으므로 만기까지 보유하면 재투자위험이 없고 만기수익률이 그대로 실현돼요.","w":["ㄴ, ㄷ, ㄹ은 모두 옳아요.","ㄷ의 호가 차이와 ㄹ의 구매력위험도 맞는 설명이에요.",null,"ㄱ은 틀렸어요. 할인채는 재투자할 이자가 없어요."],"k":"할인채는 중간에 용돈(이자)을 안 주니, 그 용돈을 어디에 굴릴지 고민할 일도 없어요.","m":"할인채 만기 보유 = 재투자위험 없음","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"이표채 이자 귀속과 매매손익","q":"〈보기〉의 국고채와 매매에 관한 설명 중 가장 적절하지 않은 것은?\n• 발행일 2024년 3월 10일, 만기일 2029년 3월 10일, 액면 10,000원\n• 표면이율 연 3.0%, 6개월마다 이자 후급\n• 투자자 정은 2025년 1월 15일 만기수익률 3.6%에 사서 2026년 6월 20일 만기수익률 2.8%에 팔았다.","o":["이자지급일마다 받는 이자는 1회에 150원이다","정이 보유 기간에 받은 이자는 2025년 3월 10일분을 포함해 모두 3회이다","정은 액면보다 싸게 사서 액면보다 비싸게 팔았으므로 매매차익을 얻었다","시장 만기수익률이 3.6%에서 2.8%로 바뀌었으므로 정이 받는 1회 이자 금액도 그에 맞춰 줄어든다"],"a":3,"c":"이표채의 이자 금액은 액면 × 표면이율로 발행 때 정해져요. 만기수익률은 시장에서 가격을 매길 때 쓰는 할인율일 뿐 지급 이자를 바꾸지 않아요.","e":"이자는 10,000 × 3.0% ÷ 2 = 150원으로 고정돼요. 이자지급일은 매년 3월 10일과 9월 10일이므로 보유 중 2025년 3월 10일, 2025년 9월 10일, 2026년 3월 10일 3회를 받아요. 살 때는 만기수익률(3.6%)이 표면이율보다 높아 할인 가격, 팔 때는 2.8%로 표면이율보다 낮아 할증 가격이었으니 매매차익이 나요.","f":"1회 이자 = 액면 × 표면이율 ÷ 연 지급 횟수","w":["10,000 × 3% ÷ 2 = 150원이 맞아요.","매입일 뒤 처음 오는 지급일부터 투자자에게 귀속되고, 매도일 전까지 3번이에요.","만기수익률이 내려가면 가격이 올라요. 표면이율 기준으로 할인→할증이 됐어요.",null],"k":"적금 이자율은 가입할 때 정해져서, 나중에 은행 금리가 바뀌어도 내 통장에 들어오는 이자는 그대로예요.","m":"이자 = 액면 × 표면이율, YTM은 가격만 바꿔요","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"상","t":"실제 변동률로 볼록성 역산","q":"수정듀레이션이 6.0인 채권의 만기수익률이 0.8%p 오르자 가격이 실제로 4.48% 떨어졌다. (ㄱ) 이 채권의 볼록성과 (ㄴ) 같은 볼록성에서 만기수익률이 0.8%p 내릴 때의 예상 가격변동률을 순서대로 짝지은 것은? (가격변동률 ≈ −MD·Δy + 0.5·C·(Δy)²로 계산한다. MD는 수정듀레이션, C는 볼록성)","o":["100 — +5.12%","50 — +5.12%","100 — +4.48%","50 — +4.48%"],"a":0,"c":"듀레이션만으로 구한 추정치와 실제 변동률의 차이가 볼록성 효과예요. (Δy)²은 늘 양수라서 볼록성 효과는 금리가 오르든 내리든 가격에 (+)로 더해져요.","e":"듀레이션 효과 = −6.0 × 0.008 = −4.80%예요. 볼록성 효과 = −4.48% − (−4.80%) = +0.32%이므로 ½ × C × 0.008² = 0.0032, C = 100이에요. 금리가 0.8%p 내리면 +4.80% + 0.32% = +5.12%예요. 같은 폭이라도 상승폭(5.12%)이 하락폭(4.48%)보다 커서, 듀레이션이 같다면 볼록성이 큰 채권이 투자자에게 유리해요.","f":"볼록성 = 2 × (실제 변동률 + MD × Δy) ÷ (Δy)²","w":[null,"½을 빠뜨리고 0.0032 ÷ 0.000064로 계산했어요.","금리가 내릴 때도 볼록성 효과를 빼서 상승폭을 하락폭과 같게 봤어요.","½ 누락과 부호 실수가 함께 있어요."],"k":"직선 자(듀레이션)로 잰 길이와 실제 굽은 길의 차이를 보고, 길이 얼마나 굽었는지(볼록성)를 거꾸로 알아내는 거예요.","m":"실제 − 듀레이션 추정 = ½ × C × Δy², 볼록성 효과는 늘 (+)","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"중","t":"영구채 맥컬리·수정듀레이션","q":"만기 없이 매년 같은 이자를 계속 지급하는 영구채의 만기수익률이 연 8%이다. 이 채권의 (ㄱ) 맥컬리 듀레이션과 (ㄴ) 수정듀레이션으로 바르게 짝지은 것은?","o":["13.5년 — 12.5","12.5년 — 11.57","13.5년 — 14.58","12.5년 — 13.5"],"a":0,"c":"영구채는 만기가 무한해도 듀레이션은 유한해요. 맥컬리 듀레이션은 (1 + y) ÷ y, 수정듀레이션은 이를 (1 + y)로 나눈 1 ÷ y예요.","e":"맥컬리 듀레이션 = 1.08 ÷ 0.08 = 13.5년이에요. 수정듀레이션 = 13.5 ÷ 1.08 = 1 ÷ 0.08 = 12.5예요.","f":"D = (1 + y) ÷ y, MD = D ÷ (1 + y) = 1 ÷ y","w":[null,"1 ÷ y(12.5)를 맥컬리 듀레이션으로 보고 다시 1.08로 나눴어요.","수정듀레이션을 구할 때 1.08로 나누지 않고 곱했어요.","두 값의 자리를 서로 바꿨어요."],"k":"끝이 없는 연금이라도 먼 미래 돈은 할인되어 거의 0이 되므로, 돈이 들어오는 '평균 시점'은 유한하게 나와요.","m":"영구채: D = (1+y)/y, MD = 1/y","rev":0},{"s":3,"sec":"채권투자운용/투자전략","star":2,"lv":"하","t":"장내·장외 채권 거래 방식","q":"국내 채권 유통시장에 관한 설명 중 가장 적절하지 않은 것은?","o":["국내 채권 거래는 장외시장 비중이 압도적으로 크다","장외거래는 증권회사 등을 통해 매도자와 매수자가 1대1로 가격을 협상하는 상대매매 방식이다","장내시장에서는 여러 주문의 호가가 모여 경쟁매매로 체결된다","거래소에 상장된 채권은 장외시장에서 사고팔 수 없고, 장외에서는 비상장채권만 거래된다"],"a":3,"c":"두 시장은 상장됐는지로 나뉘는 게 아니라 어떻게 체결하느냐로 나뉘어요. 장내는 경쟁매매, 장외는 1대1 상대매매예요.","e":"장외에서는 거래소 상장 여부와 상관없이 어떤 채권이든 사고팔 수 있어요. 국채는 장내 국채전문유통시장에서도 활발히 거래되지만, 전체로 보면 채권 거래의 대부분은 장외에서 이루어져요.","w":["채권은 종목이 많고 거래 단위가 커서 장외 비중이 훨씬 커요.","장외는 상대매매가 원칙이에요.","장내는 경쟁매매로 체결돼요.",null],"k":"같은 중고차라도 경매장(장내)에서 팔 수도 있고, 딜러와 직접 흥정(장외)해서 팔 수도 있어요. 차가 등록돼 있는지와는 상관없어요.","m":"장내 = 경쟁매매, 장외 = 상대매매(상장·비상장 모두)","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"하","t":"옵션의 내재가치와 시간가치","q":"주가지수가 312.00포인트일 때 행사가격 320.00포인트인 풋옵션의 프리미엄이 10.50포인트이다. 이 풋옵션의 시간가치와 현재 Moneyness를 순서대로 바르게 짝지은 것은? (단위: 포인트)","o":["8.00 — 내가격","8.00 — 외가격","2.50 — 외가격","2.50 — 내가격"],"a":3,"c":"옵션 프리미엄은 지금 바로 행사하면 얻는 내재가치와, 남은 기간 동안 더 유리해질 가능성인 시간가치로 나뉘어요.","e":"풋의 내재가치 = max(320.00 − 312.00, 0) = 8.00. 시간가치 = 10.50 − 8.00 = 2.50. 기초자산가격이 행사가격보다 낮은 풋이라 내가격(ITM)이에요.","f":"풋 내재가치 = max(행사가격 − 기초자산가격, 0) · 시간가치 = 프리미엄 − 내재가치","w":["8.00은 시간가치가 아니라 내재가치예요.","8.00은 내재가치예요. 그리고 지수가 행사가격보다 낮은 풋은 외가격이 아니라 내가격이에요.","시간가치는 맞지만, 지수가 행사가격보다 낮은 풋은 내가격이에요.",null],"k":"풋은 \"비싸게 팔 권리\"예요. 지금 312짜리를 320에 팔 수 있으니 8만큼 이미 이득(내가격)이고, 나머지 2.5는 앞으로의 기대값이에요.","m":"풋 내재 = 행사 − 지수 · 시간 = 프리미엄 − 내재","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"하","rev":0,"t":"선물 추가증거금 계산","q":"선물 1계약의 개시증거금이 100, 유지증거금이 70이다. 일일정산 후 증거금 잔액이 60이 되었을 때 납부해야 할 추가증거금은?","o":["10","30","40","60"],"a":2,"c":"증거금이 유지증거금 아래로 떨어지면 마진콜이 발생하고, 이때는 유지증거금이 아니라 개시증거금 수준까지 채워 넣어야 해요.","e":"잔액 60이 유지증거금 70보다 낮으므로 개시증거금 100까지 채워야 해요. 추가증거금 = 100 − 60 = 40이에요.","w":["유지증거금까지만 채운 값이에요.","개시증거금과 유지증거금의 차이예요.",null,"잔액 자체를 답으로 고른 경우예요."],"k":"자동차 연료 경고등이 켜지면 경고선(70)까지가 아니라 가득(100)까지 채워야 하는 셈이에요.","m":"마진콜 → 개시증거금 수준까지 채움","f":"100 − 60 = 40"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"스트래들 매도의 이익 구간","q":"행사가격 100인 콜옵션을 프리미엄 4에, 같은 행사가격의 풋옵션을 프리미엄 3에 각각 1계약 매도하여 스트래들 매도 포지션을 만들었다. 만기에 이익이 나는 기초자산 가격 범위로 가장 적절한 것은?","o":["96 < S < 104","97 < S < 103","93 < S < 107","S < 93 또는 S > 107"],"a":2,"c":"스트래들 매도는 기초자산 가격이 크게 움직이지 않을 때 이익을 내는 전략이에요. 받은 프리미엄 합계가 최대 이익이에요.","e":"받은 프리미엄 합계는 4 + 3 = 7이에요. 손익분기점은 100 − 7 = 93과 100 + 7 = 107이므로, 93 < S < 107에서 이익이 나요.","w":["콜 프리미엄만 반영했어요.","풋 프리미엄만 반영했어요.",null,"스트래들 매수의 이익 구간이에요."],"k":"\"가격이 별로 안 움직일 것\"에 거는 전략이에요. 받은 7만큼의 여유 안에서 움직이면 이익이에요.","m":"스트래들 매도 이익 구간: 행사가 ± 프리미엄 합계","f":"100 ± (4 + 3) → 93 ~ 107"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"콜·풋 매수에서 모두 양(+)인 민감도","q":"콜옵션 매수 포지션과 풋옵션 매수 포지션에서 모두 양(+)의 값을 갖는 민감도 지표끼리 짝지은 것은?","o":["감마, 베가","델타, 쎄타","쎄타, 베가","델타, 감마"],"a":0,"c":"옵션을 사면 변동성이 커지거나 가격이 크게 움직일 때 유리해져요. 그래서 매수 포지션은 콜·풋 모두 감마와 베가가 양(+)이에요.","e":"감마와 베가는 콜·풋 매수 모두 양(+)이에요. 델타는 콜 매수(+)와 풋 매수(−)가 반대이고, 쎄타는 매수 포지션에서 음(−)이에요.","w":[null,"델타는 풋 매수에서 음(−)이고, 쎄타는 콜·풋 매수 모두 음(−)이에요.","쎄타는 매수 포지션에서 음(−)이에요.","델타는 풋 매수에서 음(−)이에요."],"k":"옵션을 산 사람은 \"크게 흔들릴수록(감마·베가) 좋고, 시간이 흐를수록(쎄타) 손해\"예요.","m":"매수 포지션: 감마 + · 베가 + · 쎄타 − (델타는 콜+ 풋−)","f":null},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"하","rev":0,"t":"감마의 정의","q":"기초자산 가격이 변할 때 델타 자체가 얼마나 변하는지를 나타내는 지표는?","o":["감마","쎄타","베가","로"],"a":0,"c":"델타는 기초자산 가격에 따라 계속 변해요. 그 델타의 변화 속도를 따로 재는 지표가 있어요.","e":"델타의 변화율이 감마예요. 감마가 크면 델타가 빠르게 변해 헤지를 자주 조정해야 해요.","w":[null,"쎄타는 시간에 대한 민감도예요.","베가는 변동성에 대한 민감도예요.","로는 금리에 대한 민감도예요."],"k":"델타가 \"속도\"라면 감마는 \"가속도\"예요.","m":"감마 = 델타의 변화율(볼록성)"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"로(rho)의 부호","q":"다른 조건이 같을 때 무위험이자율이 오르면 옵션 가격은 어떻게 변하는가?","o":["콜과 풋 모두 오른다","콜은 오르고 풋은 내린다","콜은 내리고 풋은 오른다","콜과 풋 모두 내린다"],"a":1,"c":"금리가 오르면 미래에 낼 행사가격의 현재가치가 작아져요. 사는 권리(콜)에는 유리하고 파는 권리(풋)에는 불리해요.","e":"금리 상승 시 콜 가격은 오르고(로 +), 풋 가격은 내려요(로 −).","w":["풋은 내려요.",null,"방향이 반대예요.","콜은 올라요."],"k":"나중에 낼 돈(행사가격)의 지금 가치가 줄면 \"살 권리\"가 더 매력적이에요.","m":"금리↑ → 콜↑ 풋↓"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"델타의 범위","q":"옵션 델타에 관한 설명으로 가장 적절하지 않은 것은?","o":["콜옵션 매수의 델타는 0과 1 사이에 있다","풋옵션 매수의 델타는 −1과 0 사이에 있다","등가격 콜옵션의 델타는 대략 0.5이다","깊은 내가격 콜옵션의 델타는 0에 가깝다"],"a":3,"c":"델타는 기초자산이 1 움직일 때 옵션 가격이 얼마나 움직이는지예요. 행사 가능성이 높을수록 절댓값이 1에 가까워요.","e":"깊은 내가격 콜은 거의 확실히 행사되므로 기초자산과 거의 똑같이 움직여 델타가 1에 가까워요. 0에 가까운 것은 깊은 외가격 콜이에요.","w":["콜 매수 델타는 0~1이에요.","풋 매수 델타는 −1~0이에요.","등가격 콜은 약 0.5예요.",null],"k":"\"거의 확실히 행사될 콜\"은 주식을 들고 있는 것과 비슷해서 델타가 1에 가까워요.","m":"콜 델타 0~1 · 풋 −1~0 · 등가격 ≈ ±0.5 · 깊은 ITM ≈ ±1"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"감마가 큰 경우","q":"옵션의 감마가 가장 크게 나타나는 경우로 가장 적절한 것은?","o":["깊은 외가격이고 만기가 많이 남은 옵션","깊은 내가격이고 만기가 많이 남은 옵션","등가격 근처이고 만기가 임박한 옵션","행사가격과 관계없이 감마는 항상 같다"],"a":2,"c":"감마는 델타가 얼마나 빨리 변하는지예요. 행사될지 말지가 가장 불확실한 등가격 근처에서 델타가 가장 크게 변해요.","e":"등가격 근처이면서 만기가 임박하면 작은 가격 변화에도 행사 여부가 뒤바뀌어 감마가 가장 커요.","w":["깊은 외가격은 델타가 거의 0에 머물러 감마가 작아요.","깊은 내가격은 델타가 거의 1에 머물러 감마가 작아요.",null,"감마는 옵션 상태에 따라 크게 달라요."],"k":"시험 커트라인 바로 근처 점수일 때 한 문제로 합불이 갈리듯, 등가격 근처에서 델타가 가장 많이 흔들려요.","m":"감마 최대 = 등가격 + 만기 임박"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"매도 포지션의 민감도 부호","q":"옵션 매도 포지션의 민감도에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 콜옵션 매도의 델타는 음(−)이다.\nㄴ. 풋옵션 매도의 델타는 양(+)이다.\nㄷ. 옵션 매도의 감마는 콜·풋 모두 음(−)이다.\nㄹ. 옵션 매도의 쎄타는 콜·풋 모두 음(−)이다.","o":["1개","2개","3개","4개"],"a":2,"c":"매도 포지션의 민감도는 매수 포지션과 부호가 정반대예요. 매수자는 시간이 갈수록 손해(쎄타 −), 매도자는 이득(쎄타 +)이에요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. 옵션 매도자는 시간가치 소멸로 이익을 보므로 쎄타가 양(+)이에요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄷ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 매도 포지션의 쎄타는 양(+)이에요."],"k":"옵션을 판 사람은 시간이 지날수록 \"받은 프리미엄\"이 굳어져서 좋아요.","m":"매도: 감마 − · 베가 − · 쎄타 + / 델타는 콜매도 − · 풋매도 +"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"델타 중립 헤지","q":"델타가 0.4인 콜옵션 100계약을 매도한 투자자가 기초자산으로 델타 중립을 만들려면? (옵션 1계약 = 기초자산 1단위로 가정한다)","o":["기초자산 40단위 매도","기초자산 60단위 매수","기초자산 100단위 매수","기초자산 40단위 매수"],"a":3,"c":"델타 중립은 포지션 전체의 델타를 0으로 맞춰 기초자산 가격의 작은 변화에 영향을 받지 않게 하는 거예요.","e":"콜 100계약 매도의 델타 = −0.4 × 100 = −40이에요. 기초자산 40단위를 사서(+40) 0으로 맞춰요.","w":["매도하면 델타가 −80이 돼요.","1 − 0.4로 잘못 계산했어요.","델타를 반영하지 않았어요.",null],"k":"콜을 팔면 주가가 오를 때 손해예요. 그만큼(40단위) 주식을 사 두면 상쇄돼요.","m":"헤지 수량 = 옵션 수량 × 델타 (부호 반대로)","f":"−0.4 × 100 = −40 → 기초자산 +40"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"옵션 가격 결정 요인","q":"다른 조건이 같을 때 옵션 가격 변화의 방향으로 가장 적절하지 않은 것은?","o":["기초자산 가격이 오르면 콜 가격은 오르고 풋 가격은 내린다","행사가격이 높을수록 콜 가격은 낮고 풋 가격은 높다","기초자산 변동성이 커지면 풋 가격은 내린다","배당이 커지면 콜 가격은 내리고 풋 가격은 오른다"],"a":2,"c":"옵션 가격은 기초자산 가격, 행사가격, 변동성, 잔존기간, 금리, 배당에 따라 움직여요.","e":"변동성이 커지면 크게 유리해질 가능성이 커지므로 콜과 풋 모두 가격이 올라요.","w":["기초자산 가격 상승은 콜에 유리하고 풋에 불리해요.","행사가격이 높으면 콜은 불리, 풋은 유리해요.",null,"배당은 주가를 낮추므로 콜에 불리, 풋에 유리해요."],"k":"옵션은 \"크게 흔들릴수록\" 값어치가 올라가요. 콜이든 풋이든요.","m":"변동성↑ → 콜↑·풋↑ / 배당↑ → 콜↓·풋↑"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"하","rev":0,"t":"블랙-숄즈 모형의 입력 변수","q":"블랙-숄즈 모형으로 유러피언 콜옵션 가격을 계산할 때 필요하지 않은 정보는?","o":["기초자산의 현재 가격","기초자산의 기대수익률","무위험이자율","기초자산 수익률의 변동성"],"a":1,"c":"블랙-숄즈 모형은 기초자산 가격, 행사가격, 잔존기간, 무위험이자율, 변동성 다섯 가지로 옵션 가격을 구해요.","e":"위험중립 가정을 쓰기 때문에 기초자산의 기대수익률은 필요하지 않아요.","w":["기초자산 가격은 꼭 필요해요.",null,"무위험이자율은 필요해요.","변동성은 필요해요."],"k":"\"주식이 얼마나 오를 것 같으냐\"는 블랙-숄즈에 넣지 않아요. 흔들림(변동성)만 넣어요.","m":"B-S 입력: 주가 · 행사가 · 잔존기간 · 무위험이자율 · 변동성"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"블랙-숄즈 모형의 가정","q":"블랙-숄즈 옵션가격결정모형의 가정으로 가장 적절하지 않은 것은?","o":["만기에만 행사할 수 있는 유러피언 옵션이다","무위험이자율은 만기까지 일정하다","거래비용과 세금이 없다","기초자산의 변동성은 시간에 따라 변한다"],"a":3,"c":"블랙-숄즈 모형은 계산을 위해 몇 가지 단순한 가정을 둬요. 실제 시장과 다른 부분이 모형의 한계가 돼요.","e":"블랙-숄즈 모형은 변동성이 만기까지 일정하다고 가정해요.","w":["유러피언 옵션을 가정해요.","무위험이자율 일정을 가정해요.","거래비용·세금이 없다고 가정해요.",null],"k":"모형은 \"흔들리는 정도는 늘 같다\"고 단순하게 가정해요. 실제로는 그렇지 않아서 한계가 있어요.","m":"B-S 가정: 유러피언 · 이자율·변동성 일정 · 거래비용 X · 로그정규"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"풋-콜 패리티 계산","q":"기초자산 가격 100, 행사가격 100, 만기 1년, 무위험이자율 연 5%이고 같은 조건의 유러피언 콜옵션 가격이 10이다. 풋-콜 패리티에 따른 풋옵션 가격에 가장 가까운 것은?","o":["4.76","5.24","10.00","15.00"],"a":1,"c":"풋-콜 패리티는 같은 행사가격·만기의 콜과 풋, 기초자산, 무위험채권 사이에 성립하는 가격 관계예요.","e":"C − P = S − K ÷ (1 + r) → P = 10 − 100 + 100 ÷ 1.05 = 10 − 100 + 95.24 = 5.24예요.","w":["행사가격과 그 현재가치의 차이(100 − 95.24 = 4.76)를 답으로 골랐어요.",null,"콜과 풋 가격이 같다고 봤어요.","주가와 행사가격 현재가치의 부호를 바꿔 10 + 100 − 95.24 ≈ 14.76으로 계산했어요. 풋은 C − S + PV(K)예요."],"k":"콜 − 풋 = 주가 − 행사가격의 현재가치. 퍼즐처럼 하나를 모르면 나머지로 구해요.","m":"C − P = S − K ÷ (1 + r)ᵀ","f":"P = 10 − 100 + 95.24 = 5.24"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"풋옵션의 복제","q":"풋-콜 패리티를 이용해 풋옵션 매수 포지션을 복제한 것으로 가장 적절한 것은?","o":["콜 매도 + 기초자산 매도 + 무위험채권 매도","콜 매도 + 기초자산 매수 + 무위험채권 매수","콜 매수 + 기초자산 매수 + 무위험채권 매도","콜 매수 + 기초자산 매도 + 무위험채권(행사가격의 현재가치) 매수"],"a":3,"c":"풋-콜 패리티(C − P = S − PV(K))를 P에 대해 정리하면 풋을 다른 상품으로 만들 수 있어요.","e":"P = C − S + PV(K)이므로 콜 매수 + 기초자산 매도 + 무위험채권(행사가격의 현재가치) 매수예요.","w":["기초자산 매도는 맞지만, 콜은 매수하고 무위험채권도 매수해야 해요.","콜 방향이 반대예요.","기초자산과 채권의 방향이 반대예요.",null],"k":"식을 정리하면 P = C − S + PV(K). 더하기는 사고, 빼기는 팔면 돼요.","m":"풋 매수 = 콜 매수 + 주식 매도 + 채권 매수","f":null},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"보호적 풋의 최대 손실","q":"주가 100원에 주식을 사면서 행사가격 95원 풋옵션을 프리미엄 3원에 매수했다. 만기 시 최대 손실은?","o":["3원","5원","8원","무한대"],"a":2,"c":"보호적 풋은 주식을 들고 있으면서 풋을 사서 주가 하락 손실에 바닥을 깔아 두는 전략이에요.","e":"주가가 95원 아래로 내려가도 95원에 팔 수 있으므로 주식 손실은 최대 5원이고, 여기에 프리미엄 3원을 더해 최대 손실은 8원이에요.","w":["프리미엄만 반영했어요.","프리미엄을 빠뜨렸어요.",null,"풋 덕분에 손실이 제한돼요."],"k":"보험료(3원)를 내고 \"95원 아래로는 안 떨어지게\" 보험을 든 거예요.","m":"보호적 풋 최대손실 = (매입가 − 행사가) + 프리미엄","f":"(100 − 95) + 3 = 8원"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"커버드 콜의 최대 이익","q":"주가 100원에 주식을 사면서 행사가격 110원 콜옵션을 프리미엄 4원에 매도했다. 만기 시 최대 이익은?","o":["4원","10원","14원","무한대"],"a":2,"c":"커버드 콜은 주식을 들고 콜을 팔아 프리미엄을 받는 전략이에요. 대신 주가가 크게 올라도 이익은 행사가격에서 막혀요.","e":"주가가 110원 이상이면 110원에 넘겨야 하므로 주식 이익은 최대 10원이고, 받은 프리미엄 4원을 더해 최대 이익은 14원이에요.","w":["프리미엄만 반영했어요.","프리미엄을 빠뜨렸어요.",null,"콜을 팔았으므로 이익이 제한돼요."],"k":"\"110원 넘게 오르면 넘겨 줄게\"라고 약속하고 4원을 미리 받은 거예요.","m":"커버드 콜 최대이익 = (행사가 − 매입가) + 프리미엄","f":"(110 − 100) + 4 = 14원"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"강세 콜 스프레드","q":"행사가격 100인 콜을 6에 매수하고 행사가격 110인 콜을 2에 매도해 강세 콜 스프레드를 만들었다. 만기 시 최대 이익과 손익분기점을 바르게 짝지은 것은?","o":["최대 이익 6, 손익분기점 104","최대 이익 10, 손익분기점 104","최대 이익 6, 손익분기점 106","최대 이익 4, 손익분기점 110"],"a":0,"c":"강세 콜 스프레드는 낮은 행사가격 콜을 사고 높은 행사가격 콜을 팔아, 비용을 줄이는 대신 이익 상한을 두는 전략이에요.","e":"순비용 = 6 − 2 = 4. 최대 이익 = 행사가격 차이 10 − 4 = 6, 손익분기점 = 100 + 4 = 104예요.","w":[null,"순비용을 빼지 않았어요.","손익분기점에 매수 프리미엄만 더했어요.","최대 손실(4)과 혼동했어요."],"k":"오를 거라고 보지만 \"많이는 안 오를 것\" 같을 때, 위쪽 이익을 팔아 비용을 줄여요.","m":"최대이익 = 행사가 차이 − 순비용 · BEP = 낮은 행사가 + 순비용","f":"10 − (6 − 2) = 6 · 100 + 4 = 104"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"변동성 확대 시 이익 포지션","q":"〈보기〉 중 기초자산 가격 변동성이 커질수록 이익이 커지는 포지션은 모두 몇 개인가?\nㄱ. 스트래들 매수\nㄴ. 스트랭글 매수\nㄷ. 콜옵션 매도\nㄹ. 버터플라이 매수","o":["1개","2개","3개","4개"],"a":1,"c":"옵션을 사는 포지션(특히 콜과 풋을 함께 사는 것)은 가격이 크게 움직일수록 유리해요.","e":"스트래들 매수와 스트랭글 매수, 2개예요. 콜 매도는 변동성이 커지면 불리하고, 버터플라이 매수는 가격이 가운데 머물 때 이익이 나는 변동성 축소 전략이에요.","w":["스트랭글 매수도 해당해요.",null,"콜 매도와 버터플라이 매수는 해당하지 않아요.","네 개 모두는 아니에요."],"k":"\"어느 쪽이든 크게 움직여라!\"에 거는 것이 스트래들·스트랭글 매수예요.","m":"변동성↑ 이익: 스트래들·스트랭글 매수 / 변동성↓ 이익: 매도·버터플라이 매수"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"버터플라이 매수","q":"버터플라이 매수 전략이 가장 큰 이익을 내는 경우로 가장 적절한 것은?","o":["만기 때 기초자산 가격이 크게 오를 때","만기 때 기초자산 가격이 크게 내릴 때","만기 때 기초자산 가격이 가운데 행사가격 근처에 머물 때","변동성이 크게 확대될 때"],"a":2,"c":"버터플라이 매수는 낮은·높은 행사가격 옵션을 사고 가운데 행사가격 옵션을 2개 파는 전략이에요.","e":"만기 때 기초자산 가격이 가운데 행사가격에 머물면 최대 이익이 나요. 가격이 크게 움직이지 않을 것으로 볼 때 써요.","w":["크게 오르면 이익이 거의 없어요.","크게 내려도 이익이 거의 없어요.",null,"변동성이 줄 것으로 볼 때 쓰는 전략이에요."],"k":"나비 몸통(가운데 행사가격)에 정확히 앉을수록 이익이 커요.","m":"버터플라이 매수 = 가운데 머물면 최대 이익(변동성 축소 예상)"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"시간가치의 특성","q":"옵션의 시간가치에 관한 설명으로 가장 적절하지 않은 것은?","o":["만기가 다가올수록 줄어든다","만기가 가까워질수록 줄어드는 속도가 빨라진다","만기일에는 0이 된다","깊은 내가격 옵션에서 가장 크다"],"a":3,"c":"시간가치는 남은 기간 동안 더 유리해질 가능성의 값이에요. 그 가능성이 가장 불확실한 곳에서 가장 커요.","e":"시간가치는 등가격 옵션에서 가장 커요. 깊은 내가격이나 깊은 외가격에서는 결과가 거의 정해져 있어 작아요.","w":["만기가 다가올수록 줄어요.","만기 직전에 감소 속도가 빨라져요.","만기일에는 내재가치만 남아요.",null],"k":"결과가 가장 불확실한 등가격일 때 \"기대값\"이 가장 커요.","m":"시간가치 최대 = 등가격 · 만기 임박 시 빠르게 소멸"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"주가지수선물 이론가격","q":"현물지수 300pt, 무위험이자율 연 4%, 배당수익률 연 1%, 잔존기간 3개월일 때 보유비용모형에 따른 선물 이론가격에 가장 가까운 것은? (단리로 계산한다)","o":["300.00pt","302.25pt","303.00pt","309.00pt"],"a":1,"c":"보유비용모형에서 선물 이론가격은 현물을 지금 사서 만기까지 들고 있는 비용(이자)에서 받는 수익(배당)을 뺀 만큼 현물보다 높아요.","e":"F = 300 × [1 + (0.04 − 0.01) × 3/12] = 300 × 1.0075 = 302.25pt예요.","w":["보유비용을 반영하지 않았어요.",null,"배당수익률을 빼지 않았어요.","1년 치로 계산했어요."],"k":"지금 사서 3개월 들고 있으면 이자 비용은 들고 배당은 받아요. 그 차이만큼 선물이 비싸요.","m":"F = S × [1 + (r − d) × T]","f":"300 × (1 + 0.03 × 0.25) = 302.25pt"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"매수차익거래","q":"주가지수선물의 시장가격이 이론가격보다 높게 거래될 때 할 수 있는 차익거래로 가장 적절한 것은?","o":["선물 매수 + 현물 매도","선물 매도 + 현물 매수","선물 매수 + 현물 매수","선물 매도 + 현물 매도"],"a":1,"c":"차익거래는 비싼 것을 팔고 싼 것을 사서 가격 차이를 무위험으로 얻는 거래예요.","e":"선물이 고평가되어 있으므로 선물을 팔고 현물을 사요. 이것을 매수차익거래(현물 매수 기준)라고 해요.","w":["선물이 저평가일 때의 매도차익거래예요.",null,"양쪽을 모두 사면 차익거래가 아니에요.","양쪽을 모두 팔면 차익거래가 아니에요."],"k":"비싼 선물은 팔고, 싼 현물은 사서 만기에 가격이 맞춰질 때 차익을 챙겨요.","m":"선물 고평가 → 선물 매도 + 현물 매수(매수차익거래)"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"매도헤지와 베이시스","q":"주식 현물을 보유하고 주가지수선물을 매도해 헤지한 투자자가 있다. 헤지 기간 동안 이 투자자에게 이익이 생기는 경우는? (베이시스 = 선물가격 − 현물가격)","o":["베이시스가 확대될 때","베이시스가 축소될 때","베이시스가 변하지 않을 때","베이시스 변화와 관계없이 손익은 항상 0이다"],"a":1,"c":"헤지를 해도 선물과 현물이 똑같이 움직이지 않으면 손익이 남아요. 이 위험을 베이시스 위험이라고 해요.","e":"현물 매수 + 선물 매도의 손익 = 현물 변화 − 선물 변화 = −(베이시스 변화)예요. 그래서 베이시스가 축소될 때 이익이 나요.","w":["베이시스 확대는 매도헤지에 손실이에요.",null,"이 경우 손익은 0이에요.","베이시스가 변하면 손익이 생겨요."],"k":"선물을 판 사람은 선물이 현물보다 \"상대적으로 싸지면(차이 축소)\" 이익이에요.","m":"매도헤지 → 베이시스 축소 시 이익 / 매수헤지 → 확대 시 이익"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"매도헤지와 매수헤지","q":"3개월 뒤 받을 자금으로 주식을 사려는 연기금이 그 사이 주가 상승 위험에 대비하는 방법으로 가장 적절한 것은?","o":["주가지수선물 매수(매수헤지)","주가지수선물 매도(매도헤지)","풋옵션 매도","아무 거래도 하지 않는다"],"a":0,"c":"앞으로 살 예정인 사람은 가격이 오르는 것이 위험이고, 이미 가진 사람은 가격이 내리는 것이 위험이에요.","e":"미래에 매수할 예정이므로 지금 선물을 사서 매수 가격을 고정하는 매수헤지가 적절해요.","w":[null,"보유 자산 가격 하락에 대비할 때 쓰는 매도헤지예요.","풋 매도는 하락 위험을 지는 포지션이라 상승 헤지가 아니에요.","위험이 그대로 남아요."],"k":"\"나중에 살 거면 지금 사 두는 약속(선물 매수)\"을 해 두면 가격이 올라도 걱정이 없어요.","m":"미래 매수 예정 → 매수헤지 / 보유 자산 → 매도헤지"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"주가지수선물 헤지 계약 수","q":"〈보기〉의 연기금이 보유 주식의 가격 하락 위험을 주가지수선물로 모두 없애려 한다. 필요한 선물 거래는?\n• 보유 주식: 100억원, 베타 1.2\n• 선물가격: 250pt, 1pt당 25만원","o":["120계약 매도","160계약 매도","192계약 매도","192계약 매수"],"a":2,"c":"주가지수선물 헤지 계약 수는 포트폴리오 금액을 선물 1계약 금액으로 나누고 베타를 곱해 구해요.","e":"선물 1계약 금액 = 250 × 25만원 = 6,250만원. 계약 수 = 1.2 × 100억 ÷ 6,250만 = 192계약 매도예요.","w":["베타 1.2는 곱했지만 1계약 금액을 잘못 잡은 값이에요. 1계약 금액은 250 × 25만원 = 6,250만원이에요.","베타를 곱하지 않았어요.",null,"보유 주식의 하락을 막으려면 매도해야 해요."],"k":"주식이 시장보다 1.2배 더 움직이니 선물도 1.2배 더 팔아야 해요.","m":"N = β × 포트 금액 ÷ (선물가격 × 승수)","f":"1.2 × 100억 ÷ 6,250만 = 192계약"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"베타 조정","q":"베타 1.2인 100억원 포트폴리오의 베타를 0.6으로 낮추려 한다. 선물 1계약 금액이 6,250만원일 때 필요한 선물 거래는?","o":["96계약 매도","96계약 매수","192계약 매도","48계약 매도"],"a":0,"c":"선물로 포트폴리오 베타를 원하는 수준으로 바꿀 수 있어요. 베타를 낮추려면 선물을 팔고, 높이려면 사요.","e":"N = (목표 베타 − 현재 베타) × 포트 금액 ÷ 선물 1계약 금액 = (0.6 − 1.2) × 100억 ÷ 6,250만 = −96, 즉 96계약 매도예요.","w":[null,"베타를 낮추려면 매도해야 해요.","완전 헤지(베타 0)일 때의 수량이에요.","줄일 베타(0.6)의 절반만 반영한 값이에요. (0.6 − 1.2) × 100억 ÷ 6,250만 = −96이에요."],"k":"완전히 없애려면 192계약, 절반(1.2 → 0.6)만 줄이려면 96계약을 팔면 돼요.","m":"N = (β목표 − β현재) × P ÷ F","f":"(0.6 − 1.2) × 100억 ÷ 6,250만 = −96"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"t":"선도거래와 선물거래","q":"선도거래와 선물거래를 비교한 설명으로 가장 적절하지 않은 것은?","o":["선물거래는 거래소에서 표준화된 조건으로 거래된다","선물거래는 일일정산과 증거금 제도가 있다","선도거래는 당사자끼리 조건을 맞춰 장외에서 거래한다","선도거래도 거래소가 일일정산을 해 주므로 거래상대방 위험이 없다"],"a":3,"c":"선물은 거래소가 중간에서 결제를 보증하는 표준화 계약이고, 선도는 당사자끼리 맞춤으로 맺는 장외 계약이에요.","e":"선도거래는 장외 계약이라 일일정산이 없고, 상대방이 약속을 지키지 않을 위험(거래상대방 위험)이 있어요.","w":["선물은 거래소에서 표준화 거래돼요.","선물은 일일정산과 증거금이 있어요.","선도는 장외 맞춤 계약이에요.",null],"k":"선물은 \"거래소가 보증하는 정찰제\", 선도는 \"둘이 맺는 맞춤 계약\"이에요.","m":"선물 = 거래소·표준화·일일정산 / 선도 = 장외·맞춤·상대방위험"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"이자율평형 선물환율","q":"원/달러 현물환율 1,350원, 원화 금리 연 2%, 달러 금리 연 4%일 때 금리평가이론으로 구한 1년 선물환율에 가장 가까운 것은?","o":["1,324원","1,350원","1,377원","1,404원"],"a":0,"c":"이자율평형이론은 두 통화의 금리 차이만큼 선물환율이 현물환율과 달라져야 차익이 없다고 봐요.","e":"F = 1,350 × (1.02 ÷ 1.04) ≈ 1,324원이에요. 원화 금리가 낮으므로 달러 선물환은 할인돼요.","w":[null,"금리 차이를 반영하지 않았어요.","원화 금리만 곱했어요(1,350 × 1.02). 달러 금리로 나누는 과정이 빠졌어요.","달러 금리만 곱했어요."],"k":"달러를 예금하면 이자를 더 받으니, 그만큼 나중에 달러를 싸게 사야 공평해요.","m":"F = S × (1 + r원화) ÷ (1 + r달러)","f":"1,350 × 1.02 ÷ 1.04 ≈ 1,324원"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"선물환 차익거래 방향","q":"이자율평형으로 구한 1년 선물환율이 1,324원인데 시장 선물환율이 1,340원이다. 차익거래로 가장 적절한 것은?","o":["달러를 빌려 원화로 바꿔 예금하고, 달러 선물환을 매수한다","달러 선물환만 매수한다","원화를 빌려 달러를 현물로 사서 달러로 예금하고, 달러 선물환을 매도한다","차익거래 기회가 없다"],"a":2,"c":"시장 선물환율이 이론가보다 높으면 달러 선물환이 고평가된 거예요. 고평가된 선물환을 팔고, 현물로 달러를 마련해 두면 돼요.","e":"원화 차입 → 현물로 달러 매수 → 달러 예금 → 1년 뒤 달러를 선물환 1,340원에 매도하면 이론가 1,324원과의 차이만큼 무위험 이익이 생겨요.","w":["선물환이 저평가일 때의 방향이에요.","선물환이 고평가라 매수는 불리해요.",null,"이론가와 시장가가 달라 기회가 있어요."],"k":"비싸게 팔 수 있는 약속(선물환 매도)을 해 두고, 달러는 지금 싸게 마련해 두는 거예요.","m":"시장 선물환 > 이론가 → 선물환 매도 + 현물 달러 매수(원화 차입)"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"하","rev":0,"t":"옵션과 선물의 손익 구조","q":"옵션 매수와 선물 매수의 손익 구조를 비교한 설명으로 가장 적절한 것은?","o":["선물 매수의 손실은 증거금으로 한정된다","옵션 매수의 손실은 지급한 프리미엄으로 한정된다","두 포지션 모두 손익 구조가 대칭이다","옵션 매수는 선물 매수보다 항상 이익이 크다"],"a":1,"c":"선물은 오르면 그만큼 벌고 내리면 그만큼 잃는 대칭 구조예요. 옵션 매수는 유리할 때만 행사하므로 손실이 프리미엄으로 제한되는 비대칭 구조예요.","e":"옵션 매수자의 최대 손실은 지급한 프리미엄이에요.","w":["선물 손실은 증거금을 넘어 계속 커질 수 있어요.",null,"옵션은 비대칭 구조예요.","프리미엄을 낸 만큼 이익이 줄어요."],"k":"옵션은 \"보험료만 내면 최악을 피할 수 있는\" 권리예요.","m":"옵션 매수 = 비대칭(손실 = 프리미엄 한정) · 선물 = 대칭"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","rev":0,"t":"이항모형 위험중립확률","q":"주가가 100원이고 1기간 뒤 120원 또는 90원이 된다. 1기간 무위험이자율이 5%일 때 위험중립확률(상승 확률)과 행사가격 100원 콜옵션의 가치를 바르게 짝지은 것은?","o":["0.5, 약 9.52원","0.5, 10원","0.6, 약 11.43원","0.4, 약 7.62원"],"a":0,"c":"이항모형은 위험중립확률로 만기 가치의 기대값을 구한 뒤 무위험이자율로 할인해 옵션 가격을 구해요.","e":"위험중립확률 p = (1.05 − 0.9) ÷ (1.2 − 0.9) = 0.5. 콜 가치 = (0.5 × 20 + 0.5 × 0) ÷ 1.05 ≈ 9.52원이에요.","w":[null,"할인을 하지 않았어요.","확률을 잘못 구했어요.","확률을 잘못 구했어요."],"k":"\"공정한 동전\"처럼 오를 확률을 맞춘 뒤, 기대 보상을 지금 가치로 바꾸면 옵션 값이에요.","m":"p = (1 + r − d) ÷ (u − d) · C = [p × Cu + (1 − p) × Cd] ÷ (1 + r)","f":"p = 0.15 ÷ 0.3 = 0.5 · C = 10 ÷ 1.05 ≈ 9.52"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","rev":0,"t":"금리스왑","q":"금리스왑에 관한 설명으로 가장 적절하지 않은 것은?","o":["고정금리와 변동금리 이자를 서로 교환한다","고정금리 지급 포지션은 금리 상승 시 이익을 본다","명목원금을 기준으로 이자를 계산한다","금리스왑은 만기에 명목원금을 서로 교환한다"],"a":3,"c":"금리스왑은 같은 통화로 고정금리 이자와 변동금리 이자를 주고받는 계약이에요.","e":"금리스왑은 같은 통화의 이자만 교환하고 명목원금은 교환하지 않아요. 원금을 교환하는 것은 통화스왑이에요.","w":["고정↔변동 이자 교환이 핵심이에요.","고정을 내고 변동을 받으면 금리 상승 시 유리해요.","이자는 명목원금 기준으로 계산해요.",null],"k":"같은 원화끼리 \"이자만\" 바꾸는 계약이라 원금은 오가지 않아요.","m":"금리스왑 = 이자만 교환 · 통화스왑 = 원금도 교환"},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"만기 간 강세 스프레드","q":"같은 주가지수선물의 근월물과 원월물을 이용한 강세 스프레드에 관한 설명으로 가장 적절한 것은?","o":["원월물을 사고 근월물을 팔아 구성한다","원월물과 근월물의 가격 차이가 더 벌어질 것으로 볼 때 쓴다","근월물을 사고 원월물을 팔며, '원월물 − 근월물' 가격 차이가 좁혀질 것으로 볼 때 쓴다","서로 다른 기초자산의 선물을 짝지은 상품 간 스프레드에 해당한다"],"a":2,"c":"만기 간(캘린더) 스프레드는 같은 품목의 만기가 다른 두 선물을 동시에 사고파는 거래예요. 선물가격이 현물보다 높은 정상시장을 콘탱고, 반대를 백워데이션이라 해요.","e":"강세 스프레드는 근월물을 사고 원월물을 팔아요. 오를 때는 근월물이 더 오르고, 내릴 때는 근월물이 덜 내려 '원월물 − 근월물' 차이가 줄어들면 이익이 나요.","w":["매수·매도가 거꾸로인 약세 스프레드예요.","가격 차이가 벌어질 것으로 볼 때는 약세 스프레드를 써요.",null,"같은 품목의 만기만 다른 것이라 상품 간 스프레드가 아니에요."],"k":"가까운 달 선물이 더 힘차게 오를 거라 보고, 그쪽에 올라타고 먼 달은 파는 거예요.","m":"강세 = 근월 매수 + 원월 매도","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","t":"컨버전과 리버설","q":"기초자산 가격 100, 행사가격 100인 유럽식 콜옵션이 6, 같은 조건 풋옵션이 2에 거래되고 있다. 행사가격의 현재가치가 98일 때 무위험 차익거래 방법과 현재가치 기준 이익으로 가장 적절한 것은? (거래비용은 없다)","o":["컨버전: 콜 매도 + 풋 매수 + 기초자산 매수, 이익 2","리버설: 콜 매수 + 풋 매도 + 기초자산 공매도, 이익 2","컨버전: 콜 매수 + 풋 매도 + 기초자산 공매도, 이익 2","차익거래 기회가 없다"],"a":0,"c":"풋-콜 패리티는 C + PV(K) = P + S예요. 콜 매수 + 풋 매도는 합성선물 매수, 콜 매도 + 풋 매수는 합성선물 매도예요.","e":"C + PV(K) = 6 + 98 = 104가 P + S = 2 + 100 = 102보다 커서 콜 쪽이 비싸요. 비싼 콜을 팔고 풋을 사(합성선물 매도) 기초자산을 사는 컨버전으로 104 − 102 = 2의 이익을 얻어요.","w":[null,"리버설은 콜이 상대적으로 쌀 때(C + PV(K) < P + S) 쓰는 반대 거래예요.","합성선물 매수 + 기초자산 공매도는 리버설의 구성이라 이름과 내용이 맞지 않아요.","104와 102로 패리티가 깨져 있어 차익거래 기회가 있어요."],"k":"같은 물건(만기 손익)이 두 가게에서 값이 다르면, 비싼 쪽에 팔고 싼 쪽에서 사는 거예요.","m":"C + PV(K) > P + S → 컨버전(합성매도 + 현물매수)","f":"차익 = (C + PV(K)) − (P + S)","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"옵션 이용 포트폴리오 보험 유형","q":"옵션 원리를 이용한 포트폴리오 보험 전략과 그 구성에 관한 설명으로 가장 적절하지 않은 것은?","o":["방어적 풋은 주식을 보유하면서 풋옵션을 매수한다","이자추출전략은 대부분을 채권에 넣고 이자에 해당하는 금액으로 콜옵션을 매수한다","동적헤징은 주식을 보유하면서 주가지수선물 매도 규모를 계속 조정한다","동적자산배분은 주가가 오르면 콜옵션 델타가 작아지므로 주식 비중을 줄인다"],"a":3,"c":"동적자산배분은 주식 편입비율을 콜옵션 델타에 맞춰 콜옵션 매수를 복제하는 전략이에요. 옵션을 직접 사지 않아 프리미엄이 들지 않아요.","e":"주가가 오르면 콜 델타가 커지므로 주식을 더 사고, 내리면 팔아요. 이런 추세추종 매매를 양(+)의 피드백(positive feedback) 방식이라고 해요.","w":["주식 + 풋 매수 = 바닥이 있는 콜 매수와 같은 손익이에요.","채권 + 콜 매수로 원금은 지키고 상승 이익에 참여해요.","선물 매도 비율을 조정해 풋을 복제하는 방식이에요.",null],"k":"콜옵션 델타는 주가가 오를수록 1에 가까워지니, 오를수록 주식을 더 담는 거예요.","m":"동적자산배분: 주식비중 = 콜델타, 오르면 매수","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"변동성 스큐","q":"옵션 변동성에 관한 설명으로 가장 적절하지 않은 것은?","o":["내재변동성은 현재 시장의 옵션 가격에서 거꾸로 계산한 미래 변동성에 대한 기대치이다","역사적 변동성은 과거에 실제로 나타난 가격 변화로 계산한다","내재변동성이 높아지면 콜과 풋의 가격이 모두 오른다","1987년 블랙먼데이 이후 행사가격이 낮은 쪽 옵션의 내재변동성이 더 높게 형성되는 비대칭 모양을 변동성 스마일이라 한다"],"a":3,"c":"행사가격별 내재변동성이 등가격에서 낮고 양쪽 끝에서 높아 웃는 얼굴처럼 대칭이면 변동성 스마일, 한쪽으로 기울어 비대칭이면 변동성 스큐(smirk)라고 해요.","e":"블랙먼데이 이후 폭락 대비 수요로 외가격 풋(낮은 행사가격) 쪽 내재변동성이 높아진 비대칭 모양은 변동성 스큐예요.","w":["옵션 가격에 담긴 미래 변동성 기대가 내재변동성이에요.","이미 지나간 실제 가격 움직임으로 구한 값이에요.","변동성이 크면 콜·풋 모두 크게 유리해질 가능성이 커져요.",null],"k":"양쪽 입꼬리가 똑같이 올라가면 스마일, 한쪽만 올라가 삐뚤어지면 스큐예요.","m":"대칭 = 스마일 / 블랙먼데이 이후 비대칭 = 스큐","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"베가·쎄타·로의 크기","q":"옵션 민감도 지표의 크기에 관한 설명으로 가장 적절하지 않은 것은?","o":["베가는 만기까지 남은 기간이 길수록 크다","쎄타의 절댓값은 등가격 근처에서 가장 크고 만기가 다가올수록 커진다","콜옵션의 로는 내가격 > 등가격 > 외가격 순으로 크다","베가는 만기가 임박한 등가격 옵션에서 가장 크다"],"a":3,"c":"델타는 기초자산 가격, 감마는 델타의 변화, 쎄타는 시간 경과, 베가는 변동성, 로는 금리에 대한 옵션 가격의 민감도예요.","e":"남은 기간이 길수록 변동성이 가격에 영향을 줄 시간이 많아 베가가 커요. 만기 임박 등가격 옵션에서 가장 큰 것은 감마와 쎄타(절댓값)예요.","w":["시간이 많이 남을수록 변동성 변화의 영향이 커요.","시간가치가 가장 큰 등가격에서, 만기 직전에 시간가치가 빨리 줄어요.","내가격일수록 행사가능성이 높아 금리 영향이 커요.",null],"k":"시간이 넉넉할수록 날씨(변동성)가 결과를 바꿀 여지가 커서 베가가 커요.","m":"베가↑ 만기 길수록 / 감마·쎄타 = 만기 임박 등가격","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"상","t":"최소분산 헤지비율","q":"항공사가 항공유 구매 가격 상승에 대비해 원유선물로 헤지하려 한다. 항공유 현물가격 변화율의 표준편차는 4%, 원유선물가격 변화율의 표준편차는 5%, 두 변화율의 상관계수는 0.75이다. 최소분산 헤지비율은?","o":["0.48","0.60","0.75","0.80"],"a":1,"c":"현물과 선물이 정확히 같지 않은 교차헤지에서는 헤지 후 위험(분산)을 가장 작게 만드는 비율을 써요. 상관계수에 두 변동성의 비를 곱해 구해요.","e":"헤지비율 = 0.75 × (4% ÷ 5%) = 0.75 × 0.8 = 0.60이에요.","w":["표준편차 대신 분산의 비(0.0016 ÷ 0.0025)를 곱했어요.",null,"상관계수만 쓰고 변동성 비율을 빠뜨렸어요.","변동성 비율만 쓰고 상관계수를 빠뜨렸어요."],"k":"선물이 현물보다 더 크게 출렁이고 완전히 같이 움직이지도 않으니, 그만큼 덜 걸어 둬요.","m":"h = ρ × σS ÷ σF","f":"최소분산 헤지비율 = 상관계수 × (현물 표준편차 ÷ 선물 표준편차)","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"델타 계산과 헤지 수량","q":"기초자산 가격이 320pt에서 324pt로 오르는 동안 어떤 콜옵션 가격은 5.0pt에서 6.4pt로 올랐다. (ㄱ) 이 콜옵션의 델타와 (ㄴ) 기초자산 70단위 보유분을 이 콜옵션으로 델타중립으로 만들기 위한 거래를 짝지은 것은? (옵션 1개 = 기초자산 1단위)","o":["0.35 — 콜옵션 200개 매도","0.35 — 콜옵션 24.5개 매도","0.35 — 콜옵션 200개 매수","2.86 — 콜옵션 24.5개 매도"],"a":0,"c":"델타는 기초자산 가격이 1 움직일 때 옵션 가격이 움직이는 크기예요. 기초자산을 헤지할 옵션 수는 '헤지할 수량 ÷ 델타'예요.","e":"델타 = (6.4 − 5.0) ÷ (324 − 320) = 1.4 ÷ 4 = 0.35예요. 기초자산 70단위의 델타 +70을 없애려면 콜을 70 ÷ 0.35 = 200개 팔아야 해요.","w":[null,"70 × 0.35로 곱해 버렸어요. 콜 1개가 0.35단위만큼만 움직이니 나눠야 해요.","콜을 사면 델타가 더 커져 헤지가 아니라 위험이 늘어요.","가격 변화를 거꾸로 나눴고(4 ÷ 1.4), 수량 계산도 틀렸어요."],"k":"콜 하나가 주식 0.35주만큼만 움직이니, 70주를 막으려면 그 3배 가까이 많은 200개가 필요해요.","m":"델타 = ΔC ÷ ΔS, 헤지 옵션 수 = 수량 ÷ 델타","f":"델타 = 옵션가격 변화 ÷ 기초자산가격 변화, 헤지 옵션 수 = 보유 수량 ÷ 델타","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"상","t":"강세 풋 스프레드 손익","q":"행사가격 280pt 풋옵션을 7.0pt에 매도하고, 행사가격 270pt 풋옵션을 3.0pt에 매수했다. 만기에 기초자산이 274pt로 끝났을 때 (ㄱ) 순손익과 (ㄴ) 이 포지션의 손익분기점을 짝지은 것은?","o":["+2pt — 276pt","−2pt — 276pt","−2pt — 284pt","−6pt — 274pt"],"a":1,"c":"높은 행사가격 풋을 팔고 낮은 행사가격 풋을 사는 것은 강세 풋 스프레드예요. 처음에 프리미엄 차액을 받고, 이익과 손실이 모두 제한돼요. 반대로 높은 풋을 사고 낮은 풋을 팔면 약세 풋 스프레드예요.","e":"받은 순프리미엄 = 7 − 3 = 4pt. 만기 274pt에서 매도 풋 손실 = 280 − 274 = 6pt, 매수 풋은 행사 안 됨(0). 순손익 = 4 − 6 = −2pt. 손익분기점 = 280 − 4 = 276pt예요.","w":["순손익의 부호를 반대로 봤어요. 받은 프리미엄 4pt보다 매도 풋 손실 6pt가 커서 2pt 손실이에요.",null,"손익분기점을 높은 행사가격에 순프리미엄을 더해 구했어요. 풋 매도 쪽이니 빼야 해요.","받은 프리미엄 4pt를 빼먹었고, 274pt는 손익분기점이 아니라 만기 기초자산 가격이에요."],"k":"보험(풋)을 팔아 보험료를 받았는데, 가격이 조금 내려가 보상해 준 돈이 보험료보다 컸어요.","m":"강세 풋: 손익분기 = 높은 K − 순수취 프리미엄","f":"순손익 = 순수취 프리미엄 − max(K높음 − S, 0) + max(K낮음 − S, 0)","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"상","t":"NDF 차액 결제","q":"계약금액 50만 달러, 계약 선물환율 1달러당 1,380원인 차액결제선물환(NDF)의 만기 지정환율이 1달러당 1,350원으로 결정되었다. 만기 결제 금액과 방향으로 가장 적절한 것은?","o":["1,500만원, 매도자 → 매입자","약 10,870달러, 매입자 → 매도자","약 11,111달러, 매도자 → 매입자","약 11,111달러, 매입자 → 매도자"],"a":3,"c":"NDF는 만기에 원금을 주고받지 않고, 계약환율과 지정환율의 차이만 달러로 정산하는 선물환이에요.","e":"달러를 1,380원에 사기로 한 매입자는 시세 1,350원보다 비싸게 산 셈이라 손해예요. 결제액 = (1,380 − 1,350) × 50만 ÷ 1,350 ≈ 11,111달러를 매입자가 매도자에게 지급해요.","w":["원화 금액 자체는 1,500만원이지만 방향이 반대이고, NDF는 보통 달러로 정산해요.","달러 환산할 때 계약환율(1,380원)로 나눴어요. 지정환율로 나눠야 해요.","환율이 내려 매입자가 손해이므로 방향이 반대예요.",null],"k":"비싸게 사기로 약속한 사람이 그 차액만 현금으로 물어 주는 거예요.","m":"NDF 결제액 = (계약환율 − 지정환율) × 금액 ÷ 지정환율","f":"결제 달러 = |계약환율 − 지정환율| × 계약금액 ÷ 지정환율","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"이항모형 헤지비율","q":"현재 50,000원인 무배당 주식이 1기간 뒤 60,000원 또는 40,000원이 된다. 행사가격 45,000원인 1기간 콜옵션 1개를 매도하고 주식을 사서 무위험 포트폴리오를 만들려면 몇 주를 사야 하는가?","o":["0.25주","0.50주","0.75주","1.33주"],"a":2,"c":"주식 Δ주 매수 + 콜 1개 매도로 어떤 상태에서도 값이 같은 무위험 포트폴리오를 만들 수 있어요. 이때 Δ가 옵션의 델타(헤지비율)예요.","e":"상승 시 콜 가치 = 60,000 − 45,000 = 15,000원, 하락 시 0원이에요. Δ = (15,000 − 0) ÷ (60,000 − 40,000) = 0.75주예요.","w":["하락 시 주가와 행사가격의 차이(5,000)를 썼어요.","주가 변화만 보고 옵션 가치 차이를 반영하지 않았어요.",null,"분자와 분모를 거꾸로 나눴어요(20,000 ÷ 15,000)."],"k":"콜 하나의 출렁임(15,000)이 주식 한 주의 출렁임(20,000)의 3/4이라 주식 0.75주로 상쇄해요.","m":"Δ = (Cu − Cd) ÷ (Su − Sd)","f":"헤지비율 Δ = (Cu − Cd) ÷ (Su − Sd)","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"풋-콜 패리티와 합성채권","q":"같은 행사가격·만기의 유럽식 옵션을 이용할 때, 만기에 기초자산 가격과 관계없이 항상 행사가격만큼의 금액이 되는 포지션으로 가장 적절한 것은?","o":["기초자산 매수 + 풋 매수 + 콜 매도","기초자산 매수 + 풋 매도 + 콜 매수","기초자산 공매도 + 풋 매수 + 콜 매도","기초자산 공매도 + 풋 매도 + 콜 매수"],"a":0,"c":"풋-콜 패리티 S + P − C = PV(K)에서, 기초자산 매수 + 풋 매수 + 콜 매도는 무위험채권(행사가격의 현재가치) 매수와 같아요.","e":"만기에 S가 K보다 높으면 콜 매도로 K에 넘기고, 낮으면 풋으로 K에 팔아요. 어느 쪽이든 K를 받으므로 채권 매수와 같은 손익이에요.","w":[null,"콜 매수 + 풋 매도는 합성선물 매수라, 기초자산까지 더하면 상승 노출이 두 배가 돼요(만기 가치 2S − K).","풋 매수 + 콜 매도는 합성선물 매도라, 기초자산 공매도까지 더하면 하락 쪽 노출이 두 배가 돼요(만기 가치 K − 2S).","공매도와 합성선물 매수가 상쇄되어 만기에 늘 K를 내야 하는 채권 매도(차입)와 같아요. K를 받는 구조가 아니에요."],"k":"올라가도 콜이 막고, 내려가도 풋이 받쳐 줘서 늘 같은 돈이 남는 '옵션으로 만든 채권'이에요.","m":"S + P − C = 채권(PV(K))","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"하","t":"청산소와 미결제약정","q":"장내 선물거래에 관한 설명으로 가장 적절하지 않은 것은?","o":["청산소가 매수자와 매도자 사이에서 거래상대방이 되어 결제를 보증하므로 거래상대방 위험이 거의 없다","포지션은 매일 정산가격으로 손익을 계산해 증거금 잔액에 반영한다","미결제약정은 반대매매나 만기로 청산되지 않고 남아 있는 계약 수를 말한다","미결제약정은 하루 동안 체결된 매수 계약과 매도 계약을 합한 값이라 항상 거래량의 두 배이다"],"a":3,"c":"선물은 증거금, 일일정산, 청산소의 결제 보증으로 신용위험을 없애요. 투자자는 시장위험(가격 변동 위험)만 부담해요.","e":"미결제약정은 아직 청산되지 않고 남은 계약 수예요. 매수 1계약과 매도 1계약이 만나 1계약이 되므로 거래량의 두 배와는 관계가 없어요.","w":["청산소가 모든 거래의 상대방이 되어 결제를 보증해요.","일일정산으로 손익을 매일 증거금에 반영해요.","장 마감 때 남아 있는 계약 수가 미결제약정이에요.",null],"k":"청산소는 모든 거래에 끼어드는 믿을 만한 중개인이라, 상대가 도망갈 걱정이 없어요.","m":"선물 = 청산소 보증, 미결제약정 = 남은 계약 수","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"수직·수평 스프레드와 약세 스프레드","q":"옵션 스프레드 전략에 관한 〈보기〉의 설명 가운데 옳은 것을 모두 고른 것은?\nㄱ. 만기는 같고 행사가격만 다른 두 옵션을 묶은 것을 수직 스프레드라 한다.\nㄴ. 행사가격은 같고 만기만 다른 두 옵션을 묶은 것을 수평(시간) 스프레드라 한다.\nㄷ. 행사가격이 낮은 콜을 팔고 높은 콜을 사면 기초자산이 내릴 때 이익이 나는 약세 콜 스프레드가 된다.\nㄹ. 행사가격이 낮은 풋을 사고 높은 풋을 팔면 하락을 예상할 때 쓰는 약세 풋 스프레드가 된다.","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1,"c":"같은 만기·다른 행사가격은 수직, 같은 행사가격·다른 만기는 수평(시간), 둘 다 다르면 대각 스프레드예요. 낮은 행사가격을 사면 강세, 낮은 행사가격을 팔면 약세 스프레드예요.","e":"ㄱ, ㄴ, ㄷ이 옳아요. ㄹ처럼 낮은 풋을 사고 높은 풋을 팔면 프리미엄을 순수취하며 기초자산이 오를 때 이익이 나는 강세 풋 스프레드예요. 약세 풋 스프레드는 높은 행사가격 풋을 사고 낮은 행사가격 풋을 팔아요.","w":["ㄷ도 옳아요. 낮은 콜 매도 + 높은 콜 매수는 약세 전략이에요.",null,"ㄴ은 옳고 ㄹ은 틀렸어요. ㄹ은 강세 풋 스프레드예요.","ㄱ도 옳고 ㄹ은 틀렸어요."],"k":"콜이든 풋이든 '낮은 가격표를 사면 오를 때 웃고, 낮은 가격표를 팔면 내릴 때 웃는다'고 기억하면 돼요.","m":"수직 = 행사가격 차이, 수평 = 만기 차이, 낮은 행사가 매수 = 강세","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"스트랭글 매수의 손익분기점","q":"행사가격 330pt인 풋옵션을 2.5pt에, 행사가격 345pt인 콜옵션을 3.5pt에 각각 1계약씩 매수했다(만기 동일). 만기에 이익이 나는 기초자산 가격(S)의 범위로 가장 적절한 것은?","o":["S < 324 또는 S > 351","324 < S < 351","S < 327.5 또는 S > 348.5","S < 336 또는 S > 339"],"a":0,"c":"스트랭글 매수는 행사가격이 다른 외가격 풋과 콜을 함께 사서, 방향과 상관없이 크게 움직이면 이익을 보는 변동성 매수 전략이에요. 최대 손실은 낸 프리미엄 합계로 한정돼요.","e":"총 프리미엄 = 2.5 + 3.5 = 6pt예요. 아래쪽 손익분기점 = 330 − 6 = 324pt, 위쪽 = 345 + 6 = 351pt예요. 두 점 바깥으로 벗어나야 이익이에요.","f":"손익분기점 = 풋 행사가격 − 총 프리미엄, 콜 행사가격 + 총 프리미엄","w":[null,"두 손익분기점 사이는 스트랭글 매도의 이익 구간이에요.","풋 프리미엄과 콜 프리미엄을 따로따로 반영했어요. 두 개를 합친 6pt를 써야 해요.","프리미엄을 안쪽으로 더하고 빼서 방향이 거꾸로 됐어요."],"k":"양쪽 문에 보험을 하나씩 사 둔 셈이라, 어느 쪽이든 크게 터져야 보험료 두 장 값을 뽑아요.","m":"스트랭글 매수 BEP = 풋K − 합계, 콜K + 합계, 바깥이 이익","rev":0},{"s":3,"sec":"파생상품투자운용/투자전략","star":2,"lv":"중","t":"베이시스 위험과 교차헤지","q":"선물·선도를 이용한 헤지에 관한 설명 중 가장 적절하지 않은 것은? (베이시스 = 선물가격 − 현물가격)","o":["보유비용모형에서 베이시스는 자금조달 이자비용에서 보유로 얻는 배당수익을 뺀 순보유비용에 해당한다","헤지를 시작할 때와 끝낼 때의 베이시스가 달라 헤지 손익이 흔들리는 것을 베이시스 위험이라 한다","장외 선도·스왑 거래에서는 은행 같은 딜러가 시장조성자(Warehouse)로 고객의 상대방이 되어 1대1로 계약을 맺는 경우가 많다","보유 현물과 선물의 기초자산이 다른 교차헤지라도 선물 만기를 헤지 종료일에 맞추면 베이시스 위험은 사라진다"],"a":3,"c":"베이시스는 만기에 가까워질수록 0으로 수렴하지만, 헤지 종료 시점의 베이시스를 미리 알 수 없어 위험이 남아요. 현물과 선물의 기초자산이 다르면 두 가격의 움직임이 늘 일치하지도 않아요.","e":"교차헤지는 그 자체로 베이시스 위험의 원인이에요. 만기를 맞춰도 헤지 대상 자산과 선물 기초자산의 가격 움직임이 달라 위험이 남아요.","w":["베이시스 = 이자비용 − 배당수익(순보유비용)이에요.","시작과 종료 시점의 베이시스 차이가 헤지 성과를 바꿔요.","장외 맞춤형 계약은 딜러가 상대방이 되는 일대일 거래가 일반적이에요.",null],"k":"항공유 가격을 원유 선물로 막는 것은 쌍둥이가 아닌 사촌으로 대신 사진을 찍는 셈이라, 닮았어도 완전히 같지는 않아요.","m":"교차헤지 = 베이시스 위험 남음, 베이시스 → 만기에 0","rev":0},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"젠센의 알파 계산","q":"〈보기〉의 자료로 계산한 펀드의 젠센 알파로 가장 적절한 것은?\n• 펀드 수익률: 12%\n• 무위험이자율: 3%\n• 펀드 베타: 1.2\n• 시장 수익률: 9%","o":["1.8%","3.0%","7.2%","−1.8%"],"a":0,"c":"젠센의 알파는 펀드가 CAPM으로 기대되는 수익률보다 얼마나 더 벌었는지를 보여 줘요. 양(+)이면 운용을 잘한 거예요.","e":"CAPM 기대수익률 = 3% + 1.2 × (9% − 3%) = 10.2%. 알파 = 12% − 10.2% = 1.8%예요.","w":[null,"베타를 무시하고 시장수익률(9%)만 뺐어요.","시장위험프리미엄 × 베타(7.2%)를 답으로 골랐어요.","부호를 반대로 계산했어요."],"k":"베타만큼의 위험이면 10.2%는 벌어야 하는데 12%를 벌었으니, 1.8%는 운용 실력이에요.","m":"젠센 α = Rp − [Rf + β(Rm − Rf)]","f":"12 − [3 + 1.2 × 6] = 1.8%"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","rev":0,"t":"시간가중수익률과 금액가중수익률","q":"펀드 수익률 측정 방법에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 금액가중수익률은 내부수익률(IRR)과 같은 개념이다.\nㄴ. 금액가중수익률은 투자자금의 유출입 크기와 시점에 영향을 받는다.\nㄷ. 시간가중수익률은 펀드매니저가 통제할 수 없는 자금 유출입의 영향을 없앤다.\nㄹ. 펀드매니저의 운용 능력을 평가할 때는 금액가중수익률이 더 적합하다.","o":["1개","2개","3개","4개"],"a":2,"c":"금액가중수익률은 투자자가 실제로 번 수익률이고, 시간가중수익률은 운용자의 실력만 보여 주는 수익률이에요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. 운용자는 자금이 언제 얼마나 들어오고 나갈지 통제할 수 없으므로, 운용 능력 평가에는 시간가중수익률이 적합해요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄷ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 운용 능력 평가는 시간가중수익률이 적합해요."],"k":"손님이 언제 돈을 넣고 빼는지는 요리사 실력과 상관없어요. 요리사(운용자)는 시간가중으로 평가해요.","m":"금액가중 = IRR = 투자자 성과 · 시간가중 = 운용자 성과"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"샤프비율과 트레이너비율의 용도","q":"샤프비율과 트레이너비율에 관한 설명으로 가장 적절한 것은?","o":["샤프비율은 체계적 위험만 고려한다","트레이너비율은 총위험을 기준으로 한다","투자자 자산 전체를 하나의 펀드에 맡긴 경우에는 샤프비율이 적합하다","두 지표는 항상 같은 순위를 준다"],"a":2,"c":"샤프비율은 총위험(표준편차), 트레이너비율은 체계적 위험(베타)을 기준으로 해요.","e":"자산 전체를 한 펀드에 맡기면 비체계적 위험까지 투자자가 지므로 총위험을 쓰는 샤프비율이 적합해요. 잘 분산된 여러 펀드 중 일부를 평가할 때는 트레이너비율이 적합해요.","w":["샤프비율은 총위험을 써요.","트레이너비율은 베타를 써요.",null,"위험 기준이 달라 순위가 다를 수 있어요."],"k":"\"이 펀드가 내 전부\"면 샤프, \"여러 펀드 중 하나\"면 트레이너예요.","m":"샤프 = 총위험(σ) · 트레이너 = 체계적 위험(β)"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"샤프비율로 펀드 비교","q":"무위험이자율이 3%일 때, 샤프비율로 평가한 결과로 가장 적절한 것은?\n• A펀드: 수익률 15%, 표준편차 20%\n• B펀드: 수익률 12%, 표준편차 12%","o":["A펀드 0.60, B펀드 0.75로 B펀드가 우수하다","A펀드 0.75, B펀드 1.00으로 B펀드가 우수하다","수익률이 높은 A펀드가 우수하다","두 펀드의 샤프비율은 같다"],"a":0,"c":"수익률이 높다고 성과가 좋은 것이 아니에요. 감수한 위험 대비 얼마나 벌었는지를 봐야 해요.","e":"A = (15 − 3) ÷ 20 = 0.60, B = (12 − 3) ÷ 12 = 0.75예요. 위험 대비 성과는 B펀드가 우수해요.","w":[null,"무위험이자율을 빼지 않았어요.","위험을 고려하지 않은 판단이에요.","계산하면 서로 달라요."],"k":"A는 더 벌었지만 더 크게 흔들렸어요. 흔들림 대비로는 B가 잘했어요.","m":"샤프비율이 클수록 위험 대비 성과 우수","f":"A 12/20 = 0.6 · B 9/12 = 0.75"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"젠센 알파의 의미","q":"젠센의 알파에 관한 설명으로 가장 적절하지 않은 것은?","o":["CAPM으로 기대되는 수익률보다 실제로 더 번 수익률이다","양(+)이면 위험을 감안해도 초과성과를 냈다는 뜻이다","종목 선택 능력을 평가하는 데 쓰인다","총위험(표준편차)을 기준으로 계산한다"],"a":3,"c":"젠센의 알파는 펀드의 베타 수준에서 CAPM이 예상한 수익률과 실제 수익률의 차이예요.","e":"젠센의 알파는 베타(체계적 위험)를 기준으로 계산해요. 총위험을 쓰는 것은 샤프비율이에요.","w":["CAPM 기대수익 대비 초과수익이에요.","양수면 초과성과예요.","종목 선택 능력 평가에 써요.",null],"k":"\"이 정도 위험(베타)이면 이만큼 벌어야 하는데 더 벌었다\"를 재는 지표예요.","m":"젠센 α = Rp − [Rf + β(Rm − Rf)] · 베타 기준"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"정보비율 계산","q":"펀드 수익률이 9%, 벤치마크 수익률이 7%, 추적오차가 4%일 때 정보비율은?","o":["0.25","0.5","2.0","1.75"],"a":1,"c":"정보비율은 벤치마크 대비 초과수익을 그 초과수익의 변동성(추적오차)으로 나눈 값이에요.","e":"정보비율 = (9% − 7%) ÷ 4% = 0.5예요.","w":["계산이 맞지 않아요. 초과수익 2%를 추적오차 4%로 나눠야 해요.",null,"분자와 분모를 바꿨어요.","벤치마크 수익률(7%)을 추적오차(4%)로 나눴어요."],"k":"벤치마크를 이긴 정도(2%)를 그 들쭉날쭉함(4%)으로 나눈 \"꾸준한 실력\" 점수예요.","m":"정보비율 = (Rp − Rb) ÷ 추적오차","f":"2 ÷ 4 = 0.5"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"절대적 위험과 상대적 위험","q":"다음 위험 지표 가운데 벤치마크와 비교하지 않는 절대적 위험 지표는?","o":["베타","추적오차","표준편차","잔차위험"],"a":2,"c":"위험 지표는 펀드 자체의 변동을 보는 절대적 위험과, 벤치마크(시장) 대비 위험을 보는 상대적 위험으로 나뉘어요.","e":"표준편차는 펀드 수익률 자체의 변동성이라 절대적 위험 지표예요. 베타·추적오차·잔차위험은 벤치마크(시장)와 비교한 상대적 위험이에요.","w":["시장 대비 민감도라 상대적 위험이에요.","벤치마크 대비 차이라 상대적 위험이에요.",null,"시장으로 설명되지 않는 부분이라 상대적 위험으로 봐요."],"k":"혼자서 얼마나 흔들렸나(표준편차) vs 비교 대상과 얼마나 달랐나(베타·추적오차)예요.","m":"절대적 = 표준편차·VaR / 상대적 = 베타·추적오차·잔차위험"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","rev":0,"t":"기하평균 수익률","q":"첫해 +50%, 둘째 해 −50%인 투자의 연평균 기하수익률에 가장 가까운 것은?","o":["0%","−13.4%","−25.0%","+25.0%"],"a":1,"c":"산술평균은 단순히 더해 나누지만, 기하평균은 복리로 실제 자산 변화를 반영해요. 변동이 클수록 둘의 차이가 커요.","e":"(1.5 × 0.5)^(1/2) − 1 = √0.75 − 1 ≈ 0.866 − 1 = −13.4%예요. 실제로 100이 75가 됐으니 손실이에요.","w":["산술평균이에요. 실제 자산은 줄었어요.",null,"2년 전체 손실률이에요.","부호가 반대예요."],"k":"100원이 50% 올라 150원, 다시 50% 내려 75원! 평균 0%가 아니라 손해예요.","m":"기하평균 = [Π(1 + Rₜ)]^(1/n) − 1","f":"√(1.5 × 0.5) − 1 ≈ −13.4%"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"기준지표의 바람직한 특성","q":"성과 평가를 위한 기준지표(벤치마크)의 바람직한 특성으로 가장 거리가 먼 것은?","o":["구성 종목과 비중이 명확해야 한다","실제로 투자할 수 있어야 한다","수익률을 측정할 수 있어야 한다","운용 성과가 나온 뒤에 사후적으로 정해야 한다"],"a":3,"c":"기준지표는 운용자를 평가하는 잣대라서 공정하고 미리 정해져 있어야 해요.","e":"기준지표는 운용을 시작하기 전에 미리 정해야 해요. 사후에 정하면 결과에 맞춰 유리한 잣대를 고를 수 있어요.","w":["명확성은 바람직한 특성이에요.","투자 가능성은 바람직한 특성이에요.","측정 가능성은 바람직한 특성이에요.",null],"k":"시험 끝나고 채점 기준을 정하면 공정하지 않아요.","m":"기준지표: 명확성 · 투자가능성 · 측정가능성 · 적합성 · 사전 결정"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"생존계정 편의","q":"동류집단(Peer group) 비교나 운용사 평균 수익률 계산에서 성과가 나빠 사라진 펀드를 제외하고 남은 펀드만으로 계산할 때 생기는 문제로 가장 적절한 것은?","o":["평균 성과가 실제보다 낮게 나타난다","평균 성과가 실제보다 높게 나타난다","평균 성과에 영향이 없다","위험이 실제보다 크게 나타난다"],"a":1,"c":"성과가 나쁜 펀드는 청산·합병으로 사라지는 경우가 많아요. 살아남은 펀드만 보면 평균이 좋아 보여요.","e":"생존계정 편의(survivorship bias) 때문에 평균 성과가 실제보다 높게(과대평가) 나타나요.","w":["반대 방향이에요.",null,"성과가 나쁜 펀드가 빠져 평균이 올라가요.","주로 수익률이 부풀려지는 문제예요."],"k":"살아남은 선수 기록만 보면 그 팀이 다 잘한 것처럼 보여요.","m":"생존계정 편의 → 성과 과대평가"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"t":"성과 요인 분해","q":"벤치마크 대비 초과수익 가운데, 주식과 채권 같은 자산군 비중을 벤치마크와 다르게 가져간 데서 생긴 부분을 무엇이라 하는가?","o":["종목선택효과","자산배분효과","시장타이밍 오차","추적오차"],"a":1,"c":"초과수익은 크게 자산배분효과(어디에 얼마나)와 종목선택효과(그 안에서 무엇을)로 나눠 분석해요.","e":"자산군 비중을 벤치마크와 다르게 해서 생긴 성과는 자산배분효과예요.","w":["종목선택효과는 같은 자산군 안에서 어떤 종목을 골랐는지에서 생겨요.",null,"시장타이밍은 시점 선택 능력을 뜻하는 별도 개념이에요.","추적오차는 초과수익의 변동성이에요."],"k":"\"주식을 더 담을지(배분)\"와 \"어떤 주식을 담을지(선택)\"를 나눠 보는 거예요.","m":"초과수익 = 자산배분효과 + 종목선택효과"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"운용사 평균 수익률 계산의 주의점","q":"운용회사의 평균적인 운용 성과를 계산할 때 주의할 점으로 가장 거리가 먼 것은?","o":["성과가 나빠 사라진 계정도 포함해야 한다","규모가 큰 계정과 작은 계정을 어떻게 가중할지 일관된 기준이 필요하다","성과가 좋은 대표 계정만 골라 평균을 내도 된다","평가 기간과 계산 방법을 미리 정해야 한다"],"a":2,"c":"운용사 평균 수익률은 고객이 운용사를 고르는 근거가 되므로 왜곡 없이 계산해야 해요.","e":"성과가 좋은 계정만 골라 내면 대표계정 편의가 생겨 성과가 부풀려져요. 모든 계정을 포함해야 해요.","w":["생존계정 편의를 막기 위해 포함해야 해요.","가중 기준을 일관되게 정해야 해요.",null,"기간과 방법을 미리 정해야 해요."],"k":"반 평균을 낼 때 잘한 학생 점수만 넣으면 안 돼요.","m":"운용사 평균: 모든 계정 포함 · 생존·대표계정 편의 주의"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"펀드 회계처리","q":"집합투자기구의 회계처리에 관한 설명으로 가장 적절하지 않은 것은?","o":["매매는 체결일(거래일)을 기준으로 인식한다","이자·배당 등은 발생주의로 인식한다","보유 자산은 공정가치로 평가한다","매매는 현금 결제일이 되어야 장부에 인식한다"],"a":3,"c":"펀드는 매일 기준가격을 계산하므로 거래와 수익을 빠르고 정확하게 반영해야 해요.","e":"펀드는 매매가 체결된 날(거래일)을 기준으로 인식해요. 결제일 기준으로 하면 기준가격이 실제 상황을 늦게 반영해요.","w":["체결일 기준이 원칙이에요.","발생주의로 인식해요.","공정가치로 평가해요.",null],"k":"물건을 산 날 장부에 적어야지, 돈 낸 날까지 기다리면 가격표가 틀려요.","m":"펀드 회계: 체결일 기준 · 발생주의 · 공정가치"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"수익률의 연환산","q":"3개월 수익률이 3%인 투자를 같은 수익률로 1년 동안 복리로 이어 간다고 할 때 연환산 수익률에 가장 가까운 것은?","o":["9.00%","12.00%","12.55%","13.00%"],"a":2,"c":"짧은 기간 수익률을 연 수익률로 바꿀 때 복리를 반영하면 단순히 곱한 값보다 커져요.","e":"(1.03)⁴ − 1 ≈ 1.1255 − 1 = 12.55%예요.","w":["3배만 했어요.","단리로 4배 했어요.",null,"계산이 맞지 않아요."],"k":"3%씩 4번 불리면 이자에 이자가 붙어 12%보다 조금 더 돼요.","m":"연환산 = (1 + 기간수익률)^(1년/기간) − 1","f":"1.03⁴ − 1 ≈ 12.55%"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"상","rev":0,"t":"마켓 타이밍 능력","q":"펀드매니저의 마켓 타이밍 능력이 뛰어나다면 나타나는 모습으로 가장 적절한 것은?","o":["시장과 관계없이 베타를 0으로 유지한다","시장 상승기와 하락기에 펀드 베타가 항상 같다","시장 상승기에는 베타를 낮추고 하락기에는 높인다","시장 상승기에는 베타를 높이고 하락기에는 베타를 낮춘다"],"a":3,"c":"마켓 타이밍은 시장 방향을 예측해 시장 노출(베타)을 조절하는 능력이에요.","e":"타이밍 능력이 있으면 오를 때 베타를 높여 더 벌고, 내릴 때 베타를 낮춰 덜 잃어요.","w":["시장 중립 전략이지 타이밍이 아니에요.","베타가 일정하면 타이밍 능력이 드러나지 않아요.","반대로 하면 손해를 봐요.",null],"k":"비 올 땐 우산 펴고(베타↓), 맑을 땐 우산 접는(베타↑) 감각이에요.","m":"타이밍 능력 = 상승기 β↑ · 하락기 β↓"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"내부수익률(금액가중수익률)","q":"금액가중수익률(내부수익률)에 관한 설명으로 가장 적절한 것은?","o":["자금 유출입 시점과 규모의 영향을 받지 않는다","투자자 관점에서 실제로 얻은 성과를 보여 준다","펀드매니저의 운용 능력만을 평가하기에 가장 적합하다","각 기간 수익률을 단순히 곱해 구한다"],"a":1,"c":"금액가중수익률은 투자금이 언제 얼마나 들어오고 나갔는지까지 반영한 내부수익률(IRR)이에요.","e":"투자자가 실제로 넣고 뺀 돈을 반영하므로 투자자 관점의 성과를 보여 줘요.","w":["자금 흐름의 영향을 받아요.",null,"운용자 평가는 시간가중수익률이 적합해요.","기간 수익률을 곱하는 것은 시간가중수익률이에요."],"k":"\"내가 넣은 돈 기준으로 실제 몇 % 벌었나\"가 금액가중이에요.","m":"금액가중 = IRR · 투자자 관점 / 시간가중 = 운용자 관점"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","rev":0,"t":"금액가중과 시간가중의 차이","q":"어느 펀드의 1년 차 수익률이 +20%, 2년 차 수익률이 −10%였다. 투자자가 1년 차 말에 큰 금액을 추가로 넣었다면 두 수익률의 관계로 가장 적절한 것은?","o":["금액가중수익률이 시간가중수익률보다 높다","금액가중수익률이 시간가중수익률보다 낮다","두 수익률은 항상 같다","시간가중수익률이 자금 추가에 따라 낮아진다"],"a":1,"c":"시간가중수익률은 돈이 얼마나 들어왔는지와 무관하지만, 금액가중수익률은 큰돈이 투자된 기간의 성과에 더 큰 영향을 받아요.","e":"큰돈이 수익률이 나쁜 2년 차(−10%)에 투자되었으므로 금액가중수익률이 시간가중수익률보다 낮아져요.","w":["반대 방향이에요.",null,"자금 흐름이 있으면 달라질 수 있어요.","시간가중수익률은 자금 흐름의 영향을 받지 않아요."],"k":"하필 많이 넣은 해에 떨어졌으니 \"내 돈 기준\" 성과가 나빠요.","m":"큰 자금이 나쁜 기간에 투자 → 금액가중 < 시간가중"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"스타일 분석","q":"펀드 수익률이 여러 스타일 지수(대형가치, 대형성장, 소형가치 등)와 얼마나 비슷하게 움직였는지를 회귀분석으로 추정해 운용 스타일을 파악하는 방법은?","o":["보유종목 기반 스타일 분석","수익률 기반 스타일 분석","동류집단 비교","정상포트폴리오 분석"],"a":1,"c":"펀드의 운용 스타일은 실제 보유 종목을 보거나, 과거 수익률 움직임을 스타일 지수와 비교해 파악할 수 있어요.","e":"수익률을 스타일 지수들로 회귀분석해 스타일 구성을 추정하는 것은 수익률 기반 스타일 분석이에요.","w":["보유 종목의 특성을 직접 보는 방법이에요.",null,"비슷한 펀드들과 성과를 비교하는 방법이에요.","평소 투자 종목으로 기준지표를 만드는 방법이에요."],"k":"어떤 반찬을 담았는지 직접 보지 않고, \"맛(수익률)\"으로 재료를 맞히는 방법이에요.","m":"수익률 기반 = 회귀로 추정 · 보유종목 기반 = 실제 종목 분석"},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","rev":0,"t":"샤프와 트레이너의 평가 차이","q":"무위험이자율 4%일 때 〈보기〉의 두 펀드를 평가한 결과로 가장 적절한 것은?\n• X펀드: 수익률 14%, 표준편차 20%, 베타 1.2\n• Y펀드: 수익률 10%, 표준편차 10%, 베타 0.8","o":["샤프비율로는 Y, 트레이너비율로는 X가 우수하다","샤프비율과 트레이너비율 모두 X가 우수하다","샤프비율과 트레이너비율 모두 Y가 우수하다","샤프비율로는 X, 트레이너비율로는 Y가 우수하다"],"a":0,"c":"총위험과 체계적 위험 중 무엇을 기준으로 하느냐에 따라 평가 순위가 달라질 수 있어요.","e":"샤프: X = 10 ÷ 20 = 0.5, Y = 6 ÷ 10 = 0.6 → Y 우수. 트레이너: X = 10 ÷ 1.2 ≈ 8.3, Y = 6 ÷ 0.8 = 7.5 → X 우수예요.","w":[null,"샤프비율로는 Y가 높아요.","트레이너비율로는 X가 높아요.","방향이 반대예요."],"k":"X는 비체계적 위험(종목 고유 흔들림)이 많아서 총위험 기준으로는 손해를 봐요.","m":"샤프(σ)와 트레이너(β)는 순위가 다를 수 있음","f":"샤프 X 0.5 · Y 0.6 / 트레이너 X 8.3 · Y 7.5"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"성과평가의 단위 기간","q":"펀드 수익률을 계산할 때 평가 단위 기간에 관한 설명으로 가장 적절한 것은?","o":["단위 기간이 길수록 자금 유출입의 영향이 정확히 제거된다","단위 기간을 짧게(예: 일별) 잡을수록 시간가중수익률을 더 정확하게 계산할 수 있다","단위 기간은 성과 계산에 영향을 주지 않는다","단위 기간은 1년으로만 정해야 한다"],"a":1,"c":"시간가중수익률은 자금이 들어오고 나갈 때마다 기간을 끊어 계산해야 정확해요.","e":"단위 기간을 짧게(일별 평가) 잡을수록 자금 유출입 시점을 정확히 반영해 시간가중수익률을 정확하게 구할 수 있어요.","w":["기간이 길면 오히려 자금 흐름 영향이 섞여요.",null,"단위 기간에 따라 결과가 달라질 수 있어요.","평가 목적에 따라 달리 정할 수 있어요."],"k":"자주 찍은 사진일수록 움직임을 정확히 알 수 있어요.","m":"단위 기간↓(일별) → 시간가중수익률 정확도↑"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","rev":0,"t":"성과평가와 성과분석","q":"펀드 성과평가와 성과분석에 관한 설명으로 가장 적절한 것은?","o":["성과평가는 성과의 원인을 분해하는 것이다","성과분석은 성과가 좋았는지 나빴는지 판단하는 것이다","성과평가는 성과의 좋고 나쁨을 판단하고, 성과분석은 그 원인을 찾는다","둘은 같은 개념이다"],"a":2,"c":"성과 관리는 \"잘했나?\"를 판단하는 평가와 \"왜 그랬나?\"를 찾는 분석으로 나뉘어요.","e":"성과평가는 위험조정 성과 등으로 좋고 나쁨을 판단하고, 성과분석은 자산배분·종목선택 효과 등으로 원인을 찾아요.","w":["원인 분해는 성과분석이에요.","좋고 나쁨 판단은 성과평가예요.",null,"목적이 달라요."],"k":"성적표(평가)와 오답노트(분석)의 차이예요.","m":"성과평가 = 좋고 나쁨 · 성과분석 = 원인"},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"소르티노비율","q":"수익률 분포가 정규분포가 아닌 헤지펀드를 평가하려 한다. 〈보기〉로 구한 소르티노비율은?\n• 펀드 수익률: 9%\n• 무위험수익률: 2%\n• 최소수용가능수익률(MAR): 3%\n• 표준편차: 12%\n• 하락편차: 4%","o":["0.50","0.58","1.50","1.75"],"a":2,"c":"소르티노비율은 (수익률 − 최소수용가능수익률) ÷ 하락편차예요. 목표에 못 미친 나쁜 쪽 변동만 위험으로 봐요. 하락편차는 MAR 아래, 반편차는 평균 아래로 떨어진 부분만 계산해요.","e":"소르티노비율 = (9% − 3%) ÷ 4% = 1.5예요.","w":["분모에 하락편차 대신 표준편차를 썼어요.","무위험수익률과 표준편차를 써서 샤프비율을 구했어요.",null,"분자에 MAR 대신 무위험수익률을 썼어요."],"k":"위로 튀는 건 반가운 일이니 빼고, 목표 밑으로 떨어진 것만 위험으로 세는 성적표예요.","m":"소르티노 = (R − MAR) ÷ 하락편차","f":"소르티노비율 = (수익률 − 최소수용가능수익률) ÷ 하락편차","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"왜도와 첨도","q":"수익률 분포의 정규성을 판단하는 왜도와 첨도에 관한 설명으로 가장 적절한 것은?","o":["왜도는 분포가 얼마나 뾰족한지를 재는 값으로, 정규분포일 때 3이다","왜도가 음(−)이면 오른쪽 꼬리가 길게 늘어진 분포이다","정규분포의 첨도는 3이며, 3보다 크면 봉우리가 뾰족하고 꼬리가 두껍다","정규분포의 왜도는 1이다"],"a":2,"c":"왜도는 분포의 비대칭 정도(정규분포 0), 첨도는 봉우리가 뾰족한 정도(정규분포 3)예요.","e":"첨도가 3보다 크면 정규분포보다 뾰족하고 꼬리가 두꺼워(fat tail) 극단적인 손익이 더 자주 나와요. 헤지펀드처럼 정규분포에서 벗어난 수익률을 평가할 때 중요해요.","w":["뾰족한 정도는 첨도이고, 3이라는 값도 첨도의 기준이에요.","왜도가 음(−)이면 왼쪽(손실 쪽) 꼬리가 길어요.",null,"좌우 대칭인 정규분포의 왜도는 0이에요."],"k":"왜도는 '어느 쪽으로 기울었나', 첨도는 '얼마나 뾰족한가'예요.","m":"정규분포: 왜도 0, 첨도 3","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"GIPS 수익률 기준","q":"GIPS(글로벌 투자성과 기준)의 수익률 산출·공시 기준에 관한 설명으로 가장 적절하지 않은 것은?","o":["평가손익과 실현손익을 함께 넣은 총수익률로 계산하고, 기간별 수익률은 기하적으로 연결한다","1년이 안 되는 기간의 수익률은 연환산해서 제시하면 안 된다","컴포지트와 벤치마크의 3년 연환산 사후 표준편차를 함께 제시해야 한다","투자자 자금 유출입의 효과까지 반영하도록 금액가중수익률을 원칙으로 쓴다"],"a":3,"c":"GIPS는 운용사끼리 성과를 공정하게 비교하도록 만든 국제 기준이에요. 수익률은 매매비용을 뺀 뒤 계산하고, 운용자가 통제할 수 없는 자금 유출입 영향을 없애는 시간가중수익률을 원칙으로 해요.","e":"금액가중수익률은 투자자의 자금 넣고 빼기에 따라 달라져 운용 능력 비교에 맞지 않아요. GIPS는 시간가중수익률을 원칙으로 써요.","w":["총수익률과 기하적 연결은 GIPS의 기본 규칙이에요.","짧은 기간 수익률을 연환산하면 성과가 부풀려질 수 있어서 금지해요.","위험 정보로 3년 연환산 사후 표준편차를 공시해요.",null],"k":"모든 선수가 같은 규칙의 경기장에서 뛰게 하는 국제 경기 규칙 같은 거예요.","m":"GIPS: 시간가중·기하연결·매매비용 차감·1년 미만 연환산 금지","rev":0},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","t":"스타일효과와 종목선택효과","q":"펀드 수익률(P)을 시장지수 수익률(M), 스타일효과(S = B − M), 종목선택효과(A = P − B)의 합으로 나눈다(B: 기준지표 수익률). 펀드 수익률 12%, 기준지표(스타일지수) 수익률 8.5%, 시장지수 수익률 7%일 때 스타일효과와 종목선택효과를 순서대로 짝지은 것은?","o":["1.5%p — 3.5%p","3.5%p — 1.5%p","5.0%p — 3.5%p","1.5%p — 5.0%p"],"a":0,"c":"시장을 이긴 몫(P − M)은 어떤 스타일을 택했느냐(S)와 그 스타일 안에서 종목을 잘 골랐느냐(A)로 나눌 수 있어요.","e":"스타일효과 = 8.5% − 7% = 1.5%p, 종목선택효과 = 12% − 8.5% = 3.5%p예요. 인덱스펀드라면 A가 0에 가깝고, 기준지표가 시장지수와 같으면 S가 0이에요.","w":[null,"두 효과를 뒤바꿨어요.","5.0%p는 시장 대비 전체 초과수익(P − M)이에요.","종목선택효과에 시장 대비 전체 초과수익을 넣었어요."],"k":"달리기에서 '어느 코스를 골랐나'(스타일)와 '그 코스에서 얼마나 잘 뛰었나'(종목선택)를 나눠 보는 거예요.","m":"S = B − M, A = P − B","f":"스타일효과 = 기준지표 − 시장지수, 종목선택효과 = 펀드 − 기준지표","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"마켓 타이밍 측정 모형","q":"펀드매니저가 시장 방향을 예측해 베타를 바꾼 능력과 저평가 종목을 고른 능력을 따로 측정하려 할 때 쓰기에 가장 적절한 모형끼리 짝지은 것은?","o":["샤프비율, 트레이너비율","트레이너-마주이 모형, 헨릭슨-머튼 모형","젠센의 알파, 정보비율","소르티노비율, 샤프비율"],"a":1,"c":"트레이너-마주이 모형은 시장 초과수익률의 제곱 항을 넣어, 헨릭슨-머튼 모형은 상승장과 하락장의 베타를 따로 추정해 타이밍 능력을 측정해요. 남은 절편으로 종목선택 능력을 봐요.","e":"타이밍 능력이 있으면 오를 때 베타를 높이고 내릴 때 낮춰요. 두 모형은 이 효과를 따로 떼어 내 종목선택(알파)과 구분해 줘요.","w":["둘 다 위험 한 단위당 성과를 한 숫자로 보여 줄 뿐 두 능력을 나누지 못해요.",null,"젠센의 알파는 베타가 일정하다고 보고 구해서 타이밍 효과가 섞여요.","하락위험이나 총위험 대비 성과만 보여 줘요."],"k":"'언제 달렸나'와 '얼마나 잘 달렸나'를 따로 재 주는 측정기예요.","m":"타이밍 측정: 트레이너-마주이(제곱 항), 헨릭슨-머튼(상승·하락 베타)","rev":0},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"상","t":"전략적 배분 수익률과 배분효과","q":"어느 연기금의 1년 운용 자료가 다음과 같다. (ㄱ) 전략적 자산배분 수익률과 (ㄴ) 비중 조절에 따른 자산배분효과를 순서대로 짝지은 것은? (자산군은 셋뿐이다)\n• 전략적 비중: 주식 50%, 채권 40%, 현금 10%\n• 실제 비중: 주식 65%, 채권 30%, 현금 5%\n• 자산군별 기준지표 수익률: 주식 10%, 채권 4%, 현금 2%\n• 실제 자산군별 수익률: 주식 9%, 채권 4.5%, 현금 2.2%","o":["7.31% — +0.51%p","6.80% — +0.51%p","6.80% — +1.00%p","7.80% — +1.00%p"],"a":2,"c":"전략적 자산배분 수익률은 전략적 비중에 기준지표 수익률을 곱해 구해요. 자산배분효과는 실제 비중을 기준지표 수익률에 적용한 값에서 전략적 배분 수익률을 뺀 값이에요.","e":"전략적 배분 수익률 = 0.5 × 10 + 0.4 × 4 + 0.1 × 2 = 6.80%예요. 실제 비중 × 기준지표 = 0.65 × 10 + 0.3 × 4 + 0.05 × 2 = 7.80%이므로 자산배분효과 = 7.80 − 6.80 = +1.00%p예요. 실제 수익률 7.31%와의 차이(−0.49%p)는 종목선택효과예요.","w":["7.31%는 실제 포트폴리오 수익률이고, 0.51%p는 전체 초과수익이에요.","0.51%p는 자산배분효과와 종목선택효과를 합친 전체 초과수익이에요.",null,"7.80%는 실제 비중에 기준지표 수익률을 곱한 값이에요."],"k":"원래 계획표(전략적 비중)대로만 했으면 얻었을 점수가 전략적 배분 수익률이에요.","m":"전략적 수익률 = Σ 전략비중 × 기준지표수익률","f":"전략적 배분 수익률 = Σ(전략적 비중 × 기준지표 수익률), 자산배분효과 = Σ(실제 비중 × 기준지표 수익률) − 전략적 배분 수익률","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"샤프비율 연율화","q":"월평균 펀드 수익률이 1.8%, 월평균 무위험수익률이 0.3%, 월간 수익률 표준편차가 5%이다. 연율화한 샤프비율에 가장 가까운 것은? (√12 = 3.46으로 계산한다)","o":["0.30","0.09","1.04","3.60"],"a":2,"c":"월간 샤프비율을 연간으로 바꿀 때 초과수익률은 12배, 표준편차는 √12배가 되므로 월간 샤프비율에 √12를 곱해요.","e":"월간 샤프비율 = (1.8% − 0.3%) ÷ 5% = 0.3이에요. 연율화 = 0.3 × 3.46 ≈ 1.04예요.","w":["연율화하지 않은 월간 샤프비율이에요.","√12를 곱하지 않고 나눴어요.",null,"초과수익률만 12배로 늘리고 표준편차는 늘리지 않아 12를 곱한 값이에요. 표준편차는 √12배로 커져요."],"k":"수익은 시간에 비례해 쌓이지만 위험은 시간의 제곱근만큼만 커져요.","m":"연 샤프 = 월 샤프 × √12","f":"연율화 샤프비율 = 월간 샤프비율 × √12","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"하","t":"내부평가와 외부평가","q":"펀드 성과평가를 내부평가와 외부평가로 나눌 때의 설명으로 가장 적절하지 않은 것은?","o":["외부평가는 비슷한 유형의 펀드를 묶은 동류그룹 안에서 상대 순위를 매기는 방식을 많이 쓴다","운용사 안에서 평가하는 사람은 목표·전략·보유 종목을 자세히 알고 평가한다","내부평가는 정보가 부족하므로 동류그룹 순위만 보고, 성과 원인 분석은 하지 않는다","외부평가자는 공개된 수익률 등 제한된 정보만으로 평가한다"],"a":2,"c":"내부평가는 운용회사나 기금 내부에서 상세 정보를 바탕으로 하고, 외부평가는 평가회사 등이 공개 정보를 바탕으로 해요.","e":"내부평가자는 정보가 가장 풍부해서 성과요인 분석까지 깊이 할 수 있어요. 정보가 부족해 동류그룹 비교, 정보비율, 젠센의 알파 같은 사후 지표에 기대는 쪽은 외부평가예요.","w":["외부평가는 비슷한 펀드끼리 묶어 순위를 매겨요.","내부평가자는 운용 내용을 속속들이 알아요.",null,"외부에서는 상세 매매정보를 보기 어려워요."],"k":"내부평가는 담임 선생님, 외부평가는 성적표만 보는 입시 학원 같은 거예요.","m":"내부 = 상세정보·요인분석 / 외부 = 제한정보·동류그룹","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"펀드 유형별 기준지표 고르기","q":"펀드 유형과 그 펀드에 알맞은 기준지표(벤치마크)를 짝지은 것 중 가장 적절하지 않은 것은?","o":["주식 60%, 채권 40%를 담는 혼합형 펀드 — 주식지수와 채권지수를 운용 비율대로 섞은 합성지수","2차전지 업종에만 투자하는 펀드 — 해당 업종의 섹터지수","포트폴리오 보험처럼 일반 지수로 평가하기 어려운 특수 전략 펀드 — 맞춤형 포트폴리오","투자 범위에 별다른 제한이 없는 일반 주식형 펀드 — 운용자가 평소 담는 종목과 평균 비중으로 만든 정상포트폴리오"],"a":3,"c":"기준지표는 펀드의 운용 방식에 맞춰 골라요. 제약이 없으면 시장지수, 혼합형이면 합성지수, 특정 업종이면 섹터지수, 특수 전략이면 맞춤형 포트폴리오를 써요.","e":"투자 범위 제한이 없는 펀드에는 시장 전체를 대표하는 시장지수가 표준이에요. 정상포트폴리오는 운용자의 평소 투자 대상과 평균 비중으로 만들어 스타일을 가장 잘 반영하지만, 만들고 관리하기 어렵고 외부에서 명확히 확인하기 힘들어 주로 운용자 능력 평가에 써요.","w":["여러 시장지수를 운용 비율대로 결합한 것이 합성지수예요.","한 업종 집중 펀드는 그 업종 섹터지수와 비교해야 공정해요.","일반 지수로 평가가 어려운 특수 펀드에 맞춤형 포트폴리오를 써요.",null],"k":"마라톤 선수는 마라톤 기록과, 단거리 선수는 100m 기록과 비교해야 공정하듯, 펀드도 같은 종목끼리 비교할 잣대가 필요해요.","m":"제약 없음 = 시장지수, 혼합 = 합성, 업종 = 섹터, 특수 = 맞춤형","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"상","t":"반편차·하락편차·상대VaR","q":"투자위험 지표에 관한 〈보기〉의 설명 가운데 옳은 것을 모두 고른 것은?\nㄱ. 추적오차는 펀드와 벤치마크 수익률 차이의 표준편차로, 벤치마크와 비교하는 상대적 위험지표이다.\nㄴ. 미리 정한 목표(최소수용가능수익률 등)보다 낮은 수익률만 골라 계산하는 것이 하락편차이다.\nㄷ. 반편차는 무위험수익률보다 낮은 수익률이 나온 경우만을 대상으로 측정한다.\nㄹ. 5% 유의수준의 상대VaR은 1.65 × 순자산액 × 펀드 수익률의 표준편차로 구한다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ"],"a":0,"c":"위험지표는 절대적 위험(표준편차, 절대VaR 등)과 벤치마크 대비 상대적 위험(추적오차, 상대VaR 등)으로 나눠요. 하락 쪽만 보는 지표로는 하락편차와 반편차가 있어요.","e":"ㄱ, ㄴ이 옳아요. ㄷ은 틀렸어요. 반편차의 기준선은 평균수익률이라, 평균보다 낮게 나온 기간만 계산에 넣어요. 목표수익률 같은 별도 기준 아래를 보는 것은 하락편차예요. ㄹ의 상대VaR은 표준편차가 아니라 잔차위험(추적오차)을 써서 1.65 × 순자산액 × 잔차위험으로 구해요.","f":"상대VaR(5%) = 1.65 × 순자산액 × 잔차위험","w":[null,"ㄷ은 틀렸어요. 반편차의 기준은 평균수익률이에요.","ㄱ도 옳고, ㄹ은 표준편차 대신 잔차위험을 써야 해요.","ㄹ은 틀렸어요. 상대VaR은 잔차위험을 써요."],"k":"반편차는 '내 평균보다 못한 날', 하락편차는 '목표보다 못한 날'만 세는 성적표예요. 상대VaR은 '반 평균보다 얼마나 뒤처질 수 있나'를 재요.","m":"반편차 = 평균 아래, 하락편차 = 목표 아래, 상대VaR = 1.65 × 순자산 × 잔차위험","rev":0},{"s":3,"sec":"투자운용결과분석","star":2,"lv":"중","t":"스타일 분석 기법과 운용사수익률","q":"펀드 스타일 분석과 그룹수익률(운용사수익률)에 대한 설명 중 가장 적절하지 않은 것은?","o":["보유 종목을 직접 살펴 스타일을 판단하면 포트폴리오 기초 분석, 펀드 수익률이 어떤 스타일지수와 닮았는지로 추정하면 수익률 기초 분석이다","채권형 펀드는 담고 있는 채권들의 신용등급 평균과 만기 평균으로 스타일을 나눈다","가치주 펀드의 성과는 종합주가지수보다 가치주 스타일지수와 비교해야 공정하다","운용사수익률은 회사 전체 실적이므로 핵심 펀드매니저가 다른 회사로 옮겨 가도 이직 전후 기록을 끊김 없는 한 줄의 실적으로 봐도 무방하다"],"a":3,"c":"스타일 분석은 펀드가 실제로 어떤 성격의 자산에 투자했는지 확인해 알맞은 잣대로 평가하려는 작업이에요. 운용사수익률은 같은 유형의 펀드를 모두 모아 계산해 대표펀드 선택이나 생존계정 문제를 줄여요.","e":"펀드 성과에는 매니저 본인의 실력과 회사의 운용 철학·리서치 역량이 함께 녹아 있어요. 그래서 핵심 매니저가 옮기면 그 전후의 운용사수익률을 같은 성과로 이어 보기 어려워요.","w":["보유 종목 기준이면 포트폴리오 기초, 수익률 회귀분석이면 수익률(요인) 기초예요.","채권형은 신용등급과 만기로 스타일을 분류해요.","스타일이 다른 지수와 비교하면 운용 능력을 잘못 판단해요.",null],"k":"맛집 셰프가 다른 식당으로 옮기면, 예전 식당의 별점을 새 식당 별점으로 그대로 옮겨 붙일 수 없는 것과 같아요.","m":"보유 종목 = 포트폴리오 기초, 수익률 = 수익률 기초, 채권형 = 신용등급·만기","rev":0},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"유동성함정","q":"유동성함정에 관한 설명으로 가장 거리가 먼 것은?","o":["이자율이 매우 낮아 화폐수요가 이자율에 대해 무한히 탄력적인 상태이다","통화정책보다 재정정책의 효과가 상대적으로 크다","통화량을 늘려도 이자율이 크게 떨어져 투자와 국민소득이 크게 늘어난다","LM곡선이 수평에 가까워진다"],"a":2,"c":"유동성함정은 금리가 이미 너무 낮아서 사람들이 돈을 그냥 들고 있으려는 상태예요. 그래서 돈을 더 풀어도 금리가 더 내려가지 않아요.","e":"유동성함정에서는 통화량을 늘려도 이자율이 더 떨어지지 않아 투자와 소득이 늘지 않아요. 통화정책이 무력해져요.","w":["화폐수요가 무한 탄력적인 상태가 유동성함정이에요.","재정정책은 구축효과가 거의 없어 효과가 커요.",null,"LM곡선이 수평이 돼요."],"k":"이미 바닥인 금리는 물을 더 부어도 더 내려가지 않아요. 그래서 \"돈 풀기\"보다 \"정부 지출\"이 먹혀요.","m":"유동성함정: LM 수평 · 통화정책 무력 · 재정정책 유효"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"경제활동참가율과 실업률","q":"15세 이상 인구 가운데 취업자 54명, 실업자 6명, 비경제활동인구 40명이 있다. 경제활동참가율과 실업률을 바르게 짝지은 것은?","o":["60%, 10%","60%, 6%","54%, 10%","40%, 11%"],"a":0,"c":"경제활동인구는 취업자와 실업자를 합친 것이에요. 비경제활동인구(학생, 주부 등)는 실업률 계산에서 빠져요.","e":"경제활동인구 = 54 + 6 = 60명, 참가율 = 60 ÷ 100 = 60%, 실업률 = 6 ÷ 60 = 10%예요.","w":[null,"실업률 분모를 15세 이상 인구로 잡았어요.","고용률(54%)과 혼동했어요.","40%는 비경제활동인구 비율이고, 11%는 실업자를 취업자(54명)로 나눈 값이에요. 실업률 분모는 경제활동인구예요."],"k":"실업률은 \"일하려는 사람(경제활동인구) 중 일자리를 못 구한 사람\" 비율이에요.","m":"참가율 = 경제활동인구 ÷ 15세↑ · 실업률 = 실업자 ÷ 경제활동인구","f":"참가율 60 ÷ 100 = 60% · 실업률 6 ÷ 60 = 10%"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"실업의 유형","q":"자연실업률을 구성하는 실업으로 가장 적절하게 묶은 것은?","o":["경기적 실업, 마찰적 실업","경기적 실업만","마찰적 실업, 구조적 실업","경기적 실업, 구조적 실업"],"a":2,"c":"실업은 직장을 옮기는 과정의 마찰적 실업, 산업 구조 변화로 생기는 구조적 실업, 경기 침체로 생기는 경기적 실업으로 나뉘어요.","e":"경기가 정상일 때도 존재하는 마찰적 실업과 구조적 실업을 합친 것이 자연실업률이에요.","w":["경기적 실업은 자연실업률에 포함되지 않아요.","경기적 실업은 자연실업률이 아니에요.",null,"경기적 실업은 경기 변동 때문에 생겨요."],"k":"경기가 좋아도 이직 중인 사람(마찰)과 기술이 안 맞는 사람(구조)은 늘 있어요.","m":"자연실업 = 마찰적 + 구조적 (경기적 제외)"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"GNI 계산","q":"어느 나라의 GDP가 2,000조원이고, 국외에서 받은 요소소득이 50조원, 국외로 지급한 요소소득이 80조원이다. 이 나라의 GNI는?","o":["1,970조원","2,000조원","2,030조원","2,130조원"],"a":0,"c":"GDP는 나라 안에서 생산한 것, GNI는 그 나라 국민이 벌어들인 소득이에요. 둘의 차이는 국외순수취요소소득이에요.","e":"GNI = GDP + 국외수취요소소득 − 국외지급요소소득 = 2,000 + 50 − 80 = 1,970조원이에요.","w":[null,"국외 소득 흐름을 반영하지 않았어요.","부호를 반대로 썼어요.","두 요소소득을 모두 더했어요."],"k":"국내에서 2,000을 벌었지만 외국인에게 80을 주고 외국에서 50을 받아 와서 1,970이에요.","m":"GNI = GDP + 국외순수취요소소득","f":"2,000 + 50 − 80 = 1,970조원"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"GDP 포함 여부","q":"GDP에 포함되는 것으로 가장 적절한 것은?","o":["중고 자동차의 매매 가격","주부의 가사 노동","자기 집에 사는 사람의 귀속 임대료","정부의 실업수당 지급"],"a":2,"c":"GDP는 일정 기간 국내에서 새로 생산된 최종 재화와 서비스의 시장가치예요.","e":"자기 집에 살아도 그 주거 서비스의 가치(귀속 임대료)는 GDP에 포함해요. 중고품 거래는 새 생산이 아니고, 가사 노동은 시장거래가 아니며, 실업수당은 이전지출이라 제외돼요.","w":["중고품은 새로 생산된 것이 아니에요(중개 수수료만 포함).","시장에서 거래되지 않아 제외돼요.",null,"생산 없이 돈만 옮기는 이전지출이에요."],"k":"내 집에 살아도 \"월세를 나에게 낸 셈\"으로 쳐서 GDP에 넣어요.","m":"GDP 포함: 귀속임대료·중개수수료 / 제외: 중고품·가사노동·이전지출"},{"s":3,"sec":"거시경제","star":2,"lv":"하","rev":0,"t":"GDP 디플레이터","q":"명목 GDP가 1,100조원, 실질 GDP가 1,000조원일 때 GDP 디플레이터는?","o":["90.9","100","110","1,100"],"a":2,"c":"GDP 디플레이터는 명목 GDP를 실질 GDP로 나눈 값에 100을 곱한 물가지수예요.","e":"GDP 디플레이터 = 1,100 ÷ 1,000 × 100 = 110이에요.","w":["분자와 분모를 바꿨어요.","물가 변화가 없을 때의 값이에요.",null,"100을 곱하지 않고 명목 GDP를 그대로 썼어요."],"k":"같은 물건을 지금 가격으로 재면 10% 더 비싸졌다는 뜻이에요.","m":"GDP 디플레이터 = 명목 GDP ÷ 실질 GDP × 100","f":"1,100 ÷ 1,000 × 100 = 110"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"화폐유통속도","q":"통화량이 200조원이고 명목 GDP가 1,000조원일 때 교환방정식(MV = PY)에 따른 화폐유통속도는?","o":["0.2","2","5","1,200"],"a":2,"c":"교환방정식은 통화량 × 유통속도 = 물가 × 실질생산량(명목 GDP)이에요.","e":"V = PY ÷ M = 1,000 ÷ 200 = 5예요. 돈 한 단위가 1년에 다섯 번 거래에 쓰였다는 뜻이에요.","w":["분자와 분모를 바꿨어요.","계산이 맞지 않아요.",null,"두 값을 더했어요."],"k":"200조원이 다섯 바퀴 돌아서 1,000조원어치 거래를 만든 거예요.","m":"MV = PY → V = PY ÷ M","f":"1,000 ÷ 200 = 5"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"리카도 등가정리","q":"리카도 등가정리에 관한 설명으로 가장 적절한 것은?","o":["정부가 국채를 발행해 세금을 깎으면 소비가 크게 늘어난다","합리적인 경제주체는 국채 발행 감세를 미래 증세로 예상해 저축을 늘리므로 소비가 변하지 않는다","재정적자는 항상 이자율을 크게 올린다","정부지출 재원 조달 방법에 따라 경제 효과가 크게 달라진다"],"a":1,"c":"리카도 등가정리는 정부지출을 세금으로 충당하든 국채로 충당하든 효과가 같다는 이론이에요.","e":"국채로 세금을 깎아 줘도 사람들이 미래에 세금이 오를 것을 알고 그만큼 저축하므로 소비와 총수요가 변하지 않아요.","w":["리카도 등가정리는 소비가 변하지 않는다고 봐요.",null,"저축이 늘어 이자율 영향이 거의 없다고 봐요.","조달 방법과 관계없이 효과가 같다고 봐요."],"k":"\"지금 세금 깎아 줄게, 나중에 더 걷을게\"라면 똑똑한 사람은 그 돈을 쓰지 않고 모아 둬요.","m":"리카도 등가: 국채 감세 → 미래 증세 예상 → 저축↑ → 소비 불변"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"정책무력성 정리","q":"합리적 기대학파의 정책무력성 정리에 관한 설명으로 가장 거리가 먼 것은?","o":["경제주체는 이용 가능한 모든 정보로 기대를 형성한다","예상된 통화정책은 실질 산출에 영향을 주지 못한다","예상하지 못한 통화정책은 단기적으로 실물에 영향을 줄 수 있다","예상된 통화정책도 장기적으로 실업률을 계속 낮출 수 있다"],"a":3,"c":"합리적 기대학파는 사람들이 정책을 미리 예상해 행동하므로 예상된 정책은 효과가 없다고 봐요.","e":"예상된 통화정책은 물가만 올릴 뿐 실업률이나 산출에 영향을 주지 못한다는 것이 정책무력성 정리예요.","w":["합리적 기대의 정의예요.","정책무력성의 핵심이에요.","예상 못 한 정책만 단기 효과가 있어요.",null],"k":"모두가 \"돈 푼다\"는 걸 알면, 가격만 올리고 실제 경제는 그대로예요.","m":"예상된 정책 → 실물효과 X(물가만↑) · 예상 못 한 정책만 단기 효과"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"IS곡선의 기울기","q":"IS곡선의 기울기에 관한 설명으로 가장 적절한 것은?","o":["투자의 이자율 탄력성이 클수록 IS곡선은 가팔라진다","투자의 이자율 탄력성이 클수록 IS곡선은 완만해진다","IS곡선은 항상 수직이다","IS곡선 기울기는 투자와 관계없다"],"a":1,"c":"IS곡선은 재화시장 균형을 이루는 이자율과 국민소득의 조합이에요. 이자율이 변할 때 투자가 얼마나 변하는지가 기울기를 정해요.","e":"투자가 이자율에 민감할수록 이자율이 조금만 내려도 소득이 크게 늘어 IS곡선이 완만해져요.","w":["반대 방향이에요.",null,"투자가 이자율에 전혀 반응하지 않을 때만 수직이에요.","투자의 이자율 민감도가 기울기를 결정해요."],"k":"금리에 민감한 투자는 금리 조금 바뀌어도 크게 반응해서 곡선이 눕혀져요.","m":"투자 이자율탄력성↑ → IS 완만"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"LM곡선의 기울기","q":"LM곡선의 기울기에 관한 설명으로 가장 적절한 것은?","o":["화폐수요의 이자율 탄력성이 클수록 LM곡선은 완만해진다","화폐수요의 이자율 탄력성이 클수록 LM곡선은 가팔라진다","유동성함정에서 LM곡선은 수직이다","LM곡선 기울기는 화폐수요와 관계없다"],"a":0,"c":"LM곡선은 화폐시장 균형을 이루는 이자율과 국민소득의 조합이에요.","e":"화폐수요가 이자율에 민감할수록 소득이 늘어도 이자율이 조금만 올라 LM곡선이 완만해요. 극단적인 경우(유동성함정)에는 수평이 돼요.","w":[null,"반대 방향이에요.","유동성함정에서 LM곡선은 수평이에요.","화폐수요의 이자율 민감도가 기울기를 결정해요."],"k":"사람들이 금리에 따라 돈 보유를 쉽게 바꾸면 금리가 크게 움직일 필요가 없어요.","m":"화폐수요 이자율탄력성↑ → LM 완만(극단 = 수평, 유동성함정)"},{"s":3,"sec":"거시경제","star":2,"lv":"하","rev":0,"t":"공개시장조작","q":"중앙은행이 시중 통화량을 늘리기 위한 공개시장조작으로 가장 적절한 것은?","o":["국공채를 매각한다","국공채를 매입한다","지급준비율을 올린다","기준금리를 올린다"],"a":1,"c":"공개시장조작은 중앙은행이 채권을 사고팔아 시중 통화량을 조절하는 수단이에요.","e":"중앙은행이 국공채를 사면 대금이 시중에 풀려 통화량이 늘어요.","w":["매각하면 시중 돈을 거둬들여 통화량이 줄어요.",null,"지급준비율 인상은 통화량을 줄여요.","기준금리 인상은 긴축 정책이에요."],"k":"중앙은행이 채권을 사 주면 그 대금만큼 돈이 시장에 풀려요.","m":"통화량↑: 국공채 매입 · 지준율↓ · 기준금리↓"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"경상수지와 이자율","q":"〈보기〉의 ( ) 안에 들어갈 말을 순서대로 바르게 나열한 것은? (다른 조건은 일정하다)\n〈보기〉 경상수지 흑자가 계속되면 국내로 외화가 들어와 국내 통화공급이 ( ㄱ )하고, 시장이자율은 ( ㄴ )한다.","o":["ㄱ 증가 – ㄴ 하락","ㄱ 증가 – ㄴ 상승","ㄱ 감소 – ㄴ 상승","ㄱ 감소 – ㄴ 하락"],"a":0,"c":"경상수지 흑자는 수출로 벌어 온 외화가 국내로 들어오는 것이에요. 이 외화가 원화로 바뀌면 시중 통화가 늘어요.","e":"경상수지 흑자 → 외화 유입 → 국내 통화공급 증가 → 시장이자율 하락이에요.","w":[null,"통화가 늘면 이자율은 내려가요.","흑자면 통화가 늘어요.","흑자면 통화가 늘어요."],"k":"수출로 번 돈이 들어와 시중에 돈이 많아지면 돈의 값(금리)이 내려가요.","m":"경상수지 흑자 → 통화↑ → 금리↓ / 적자 → 통화↓ → 금리↑"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"환율 상승의 영향","q":"원/달러 환율이 크게 오를 때(원화 약세) 나타나는 일반적인 영향으로 가장 적절한 것은?","o":["수출 가격 경쟁력이 떨어진다","수입 물가가 내려간다","수출 가격 경쟁력이 높아지고 수입 물가가 오른다","외채 상환 부담이 줄어든다"],"a":2,"c":"환율이 오르면 같은 달러로 원화를 더 많이 받을 수 있어 수출에 유리하고, 수입품은 원화로 더 비싸져요.","e":"원화 약세는 수출 가격 경쟁력을 높이고, 수입 물가를 올려 국내 물가 상승 압력이 돼요.","w":["수출 가격 경쟁력이 높아져요.","수입 물가가 올라요.",null,"달러 빚을 갚을 원화가 더 많이 필요해져요."],"k":"달러가 비싸지면 우리 물건은 해외에서 싸지고, 수입품은 우리나라에서 비싸져요.","m":"환율↑(원화 약세) → 수출↑ · 수입물가↑ · 외채부담↑"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"필립스곡선","q":"필립스곡선에 관한 설명으로 가장 적절한 것은?","o":["인플레이션과 실업률은 항상 같은 방향으로 움직인다","장기 필립스곡선은 수평이다","단기에는 인플레이션과 실업률 사이에 상충 관계가 있다","장기에도 인플레이션을 높이면 실업률을 계속 낮출 수 있다"],"a":2,"c":"필립스곡선은 인플레이션과 실업률의 관계를 보여 줘요. 단기와 장기의 모습이 달라요.","e":"단기에는 물가가 오를 때 실업률이 낮아지는 상충 관계가 있어요. 장기에는 기대가 조정되어 자연실업률에서 수직이 돼요.","w":["단기에는 반대 방향으로 움직여요.","장기 필립스곡선은 수직이에요.",null,"장기에는 실업률이 자연실업률로 돌아가요."],"k":"잠깐은 \"물가 조금 올리고 일자리 늘리기\"가 되지만, 오래가면 물가만 오르고 일자리는 제자리예요.","m":"단기 필립스: 우하향(상충) · 장기: 자연실업률에서 수직"},{"s":3,"sec":"거시경제","star":2,"lv":"하","rev":0,"t":"인플레이션의 유형","q":"원유 등 원자재 가격이 급등해 기업의 생산 비용이 올라 물가가 상승하는 것은?","o":["수요견인 인플레이션","비용인상 인플레이션","디플레이션","디스인플레이션"],"a":1,"c":"인플레이션은 원인에 따라 수요가 늘어서 생기는 것과 비용이 올라서 생기는 것으로 나눠요.","e":"원자재 가격 상승처럼 생산 비용이 올라 물가가 오르는 것은 비용인상 인플레이션이에요. 경기 침체와 함께 오면 스태그플레이션이 될 수 있어요.","w":["수요가 공급보다 많아 생기는 인플레이션이에요.",null,"물가가 지속적으로 하락하는 현상이에요.","물가 상승률이 낮아지는 현상이에요."],"k":"재료값이 올라서 물건값을 올리는 게 비용인상 인플레이션이에요.","m":"수요견인 = 수요↑ · 비용인상 = 원가↑"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"t":"정부지출 승수","q":"한계소비성향이 0.8인 단순 케인즈 모형에서 정부지출을 10조원 늘리면 국민소득은 얼마나 늘어나는가?","o":["40조원","10조원","50조원","8조원"],"a":2,"c":"정부지출이 늘면 그 돈을 받은 사람이 다시 소비하는 과정이 반복되어 소득이 지출보다 더 크게 늘어요(승수효과).","e":"정부지출 승수 = 1 ÷ (1 − 0.8) = 5, 소득 증가 = 10조원 × 5 = 50조원이에요.","w":["조세승수(4)를 곱했어요.","승수효과를 반영하지 않았어요.",null,"한계소비성향만 곱했어요."],"k":"10조원을 쓰면 그 80%가 다시 쓰이고, 또 그 80%가 쓰여서 모두 합하면 50조원이에요.","m":"정부지출 승수 = 1 ÷ (1 − MPC)","f":"1 ÷ 0.2 × 10 = 50조원"},{"s":3,"sec":"거시경제","star":3,"lv":"상","rev":0,"t":"조세 승수","q":"한계소비성향이 0.8인 단순 케인즈 모형에서 세금을 10조원 줄이면 국민소득은 얼마나 늘어나는가?","o":["8조원","40조원","50조원","10조원"],"a":1,"c":"세금을 줄이면 가처분소득이 늘지만, 그중 일부만 소비되므로 처음 효과가 정부지출보다 작아요.","e":"조세승수 = MPC ÷ (1 − MPC) = 0.8 ÷ 0.2 = 4, 소득 증가 = 10조원 × 4 = 40조원이에요.","w":["첫 단계 소비만 반영했어요.",null,"정부지출 승수(5)를 썼어요.","승수효과를 반영하지 않았어요."],"k":"세금을 깎아 줘도 사람들은 그 돈의 80%만 쓰니까, 정부가 직접 쓰는 것보다 효과가 조금 작아요.","m":"조세승수 = MPC ÷ (1 − MPC)","f":"0.8 ÷ 0.2 × 10 = 40조원"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"구매력평가설","q":"구매력평가설에 따를 때 A국의 물가상승률이 B국보다 높으면 나타나는 현상으로 가장 적절한 것은?","o":["A국 통화 가치가 B국 통화 대비 오른다","A국 통화 가치가 B국 통화 대비 내린다","두 나라 환율은 변하지 않는다","A국 금리가 반드시 내려간다"],"a":1,"c":"구매력평가설은 같은 물건은 어느 나라에서나 같은 가격이어야 한다는 일물일가 법칙으로 환율을 설명해요.","e":"물가가 더 많이 오른 나라의 통화는 구매력이 떨어지므로 그 가치가 내려가요(환율 상승).","w":["반대 방향이에요.",null,"물가 차이만큼 환율이 변해요.","금리는 이 이론의 직접 결론이 아니에요."],"k":"물가가 많이 오른 나라 돈으로는 살 수 있는 게 줄어드니 그 돈의 값어치가 떨어져요.","m":"물가상승률↑ 국가 → 통화가치↓"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"통화지표 M1과 M2","q":"통화지표에 관한 설명으로 가장 적절한 것은?","o":["M1에는 만기 2년 미만 정기예금이 포함된다","M1은 현금통화와 요구불예금, 수시입출식 저축성예금으로 구성된다","M2는 M1보다 좁은 개념의 통화지표이다","M2에는 현금통화가 포함되지 않는다"],"a":1,"c":"통화지표는 돈으로 얼마나 쉽게 쓸 수 있는지(유동성)에 따라 M1(협의통화), M2(광의통화) 등으로 나눠요.","e":"M1은 바로 쓸 수 있는 현금통화, 요구불예금, 수시입출식 저축성예금으로 구성돼요. M2는 여기에 만기 2년 미만 정기예적금 등을 더한 더 넓은 지표예요.","w":["정기예금은 M2에 포함돼요.",null,"M2가 M1보다 넓어요.","M2는 M1을 포함하므로 현금통화도 들어가요."],"k":"지갑 속 현금과 언제든 꺼낼 수 있는 통장 = M1, 여기에 짧은 적금까지 = M2예요.","m":"M1 = 현금 + 요구불 + 수시입출식 / M2 = M1 + 2년 미만 정기예적금 등"},{"s":3,"sec":"거시경제","star":2,"lv":"중","rev":0,"t":"테일러 준칙","q":"테일러 준칙에 관한 설명으로 가장 적절한 것은?","o":["인플레이션율이 목표보다 높으면 정책금리를 내려야 한다","인플레이션 갭과 산출 갭에 따라 정책금리를 조정하는 준칙이다","정책금리는 경기와 무관하게 고정한다","실업률만 보고 정책금리를 정한다"],"a":1,"c":"테일러 준칙은 중앙은행이 금리를 정할 때 참고하는 공식으로, 물가와 경기 상황을 함께 반영해요.","e":"인플레이션이 목표보다 높거나(인플레이션 갭 +) 산출이 잠재 수준보다 높으면(산출 갭 +) 정책금리를 올리도록 해요.","w":["인플레이션이 높으면 금리를 올려야 해요.",null,"경기와 물가에 따라 조정해요.","물가와 산출을 함께 봐요."],"k":"물가가 너무 오르거나 경기가 과열되면 금리를 올리는 \"자동 규칙\"이에요.","m":"테일러 준칙: 인플레이션 갭·산출 갭 → 정책금리 조정"},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"피구효과","q":"〈보기〉에서 설명하는 효과로 가장 적절한 것은?\n〈보기〉 깊은 불황으로 물가가 크게 떨어지면 사람들이 가진 화폐의 구매력이 커져 실질 부가 늘어난다. 그러면 소비가 늘어 IS곡선이 오른쪽으로 이동하므로, 유동성함정에 빠져도 경제가 스스로 벗어날 수 있다.","o":["피셔효과","구축효과","피구효과(실질잔고효과)","리카도 등가정리"],"a":2,"c":"피구효과는 물가 하락 → 실질 부(화폐의 실질가치) 증가 → 소비 증가로 이어지는 효과예요. 고전학파가 유동성함정 탈출 논리로 내세웠어요.","e":"물가가 떨어져 가진 돈의 실질가치가 커지면 사람들이 더 부자가 됐다고 느껴 소비를 늘려요. 이것이 피구효과(실질잔고효과)예요.","w":["피셔효과는 기대인플레이션이 명목이자율에 반영되는 현상이에요.","구축효과는 정부지출이 이자율을 올려 민간투자를 줄이는 현상이에요.",null,"리카도 등가정리는 국채를 발행해 세금을 깎아 줘도 사람들이 미래 증세를 대비해 저축하므로 소비가 늘지 않는다는 이론이에요."],"k":"지갑 속 만 원이 그대로인데 물건값이 반으로 떨어지면, 갑자기 부자가 된 기분이라 더 쓰게 돼요.","m":"피구효과: 물가↓ → 실질부↑ → 소비↑","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"유동성·소득·피셔효과","q":"중앙은행이 통화공급을 크게 늘린 뒤 명목이자율이 움직이는 경로를 시간 순서대로 바르게 나열한 것은?","o":["피셔효과 → 유동성효과 → 소득효과","소득효과 → 유동성효과 → 피셔효과","유동성효과 → 소득효과 → 피셔효과","유동성효과 → 피셔효과 → 소득효과"],"a":2,"c":"통화량이 늘면 먼저 돈이 흔해져 금리가 내려가요(유동성효과). 이어 소득이 늘어 화폐수요가 커지며 금리가 오르고(소득효과), 결국 물가와 기대인플레이션이 올라 명목금리가 더 올라요(피셔효과).","e":"단기에는 유동성효과로 금리가 떨어지고, 시간이 지나면 소득효과와 피셔효과로 금리가 다시 오르는 순서예요. 피셔 방정식은 명목이자율 = 실질이자율 + 기대인플레이션율이에요.","w":["피셔효과는 물가와 기대가 바뀐 뒤 장기에 나타나요.","통화량이 늘면 가장 먼저 금리가 떨어지는 유동성효과가 나타나요.",null,"소득이 먼저 늘고 물가 기대는 그 뒤에 바뀌어요."],"k":"수돗물(돈)을 틀면 처음엔 물값이 싸지지만, 쓰는 사람이 늘고 물가까지 오르면 결국 다시 비싸져요.","m":"통화↑ → 유동성효과(↓) → 소득효과(↑) → 피셔효과(↑)","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"화폐수요의 동기","q":"유동성선호설(케인즈)이 설명하는 화폐수요와 이자율에 대한 내용으로 가장 적절하지 않은 것은?","o":["거래 목적으로 들고 있는 돈(거래적 동기)은 소득이 늘수록 많아진다","갑작스러운 지출에 대비해 돈을 들고 있으려는 것은 예비적 동기이다","중앙은행이 통화량을 정하므로 화폐공급은 이자율과 무관하고 공급곡선은 수직이다","투기적 동기의 화폐수요는 이자율이 오를수록 늘어난다"],"a":3,"c":"케인즈는 화폐의 수요와 공급(저량)으로 이자율이 정해진다고 봤어요(유동성선호설). 고전학파는 이자율을 저축과 투자(유량)가 정하는 실물 현상으로 봤어요.","e":"이자율이 오르면 채권값이 싸지고 돈을 들고 있는 기회비용이 커지므로 투기적 화폐수요는 줄어들어요. 투기적 화폐수요는 이자율의 감소함수예요.","w":["소득이 늘면 거래가 많아져 돈이 더 필요해요.","예상치 못한 지출 대비가 예비적 동기예요.","중앙은행이 정하므로 이자율과 관계없이 수직이에요.",null],"k":"이자를 많이 주는 때에 현금을 쥐고만 있으면 손해라, 금리가 오르면 현금 보유를 줄여요.","m":"투기적 화폐수요 = 이자율의 감소함수","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"실질GDI와 교역조건","q":"국민소득 지표에 관한 설명으로 가장 적절하지 않은 것은?","o":["GNI = GDP + 국외순수취요소소득이다","생산·분배·지출 측면에서 잰 국민소득은 이론적으로 같다","교역조건이 바뀌어 생긴 실질무역손익을 실질GDP에 반영한 것이 실질GDI이다","교역조건이 나빠지면 같은 양을 생산해도 실질GDI는 실질GDP보다 더 빠르게 늘어난다"],"a":3,"c":"실질GDP는 생산량을, 실질GDI는 그 생산으로 벌어들인 소득의 실제 구매력을 보여 줘요. 둘의 차이가 교역조건이 바뀌어 생긴 무역손익(실질무역손익)이에요.","e":"수출품 가격에 비해 수입품 가격이 올라 교역조건이 나빠지면, 같은 양을 수출해도 살 수 있는 수입품이 줄어 실질GDI 증가율이 실질GDP보다 낮아져요.","w":["국민이 해외에서 받은 소득에서 외국인에게 준 소득을 뺀 것을 더해요.","국민소득 3면 등가의 원칙이에요.","교역조건 효과를 반영한 것이 실질GDI예요.",null],"k":"같은 양의 쌀을 팔아도 수입 기름값이 오르면 실제로 살 수 있는 게 줄어드는 셈이에요.","m":"교역조건 악화 → 실질GDI < 실질GDP 증가율","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"경기 선행·동행·후행 지표","q":"통계청 경기종합지수에서 선행종합지수 구성지표로만 묶은 것은?\nㄱ. 건설수주액\nㄴ. 기계류내수출하지수\nㄷ. 소매판매액지수\nㄹ. 재고순환지표\nㅁ. 생산자제품재고지수","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄷ, ㄹ, ㅁ","ㄴ, ㄹ, ㅁ"],"a":1,"c":"선행지수는 앞으로의 경기를 미리 보여 주는 지표(기계류내수출하, 건설수주, 재고순환, 코스피 등), 동행지수는 현재 경기(광공업생산, 소매판매 등), 후행지수는 뒤따라 확인하는 지표(생산자제품재고, 취업자수 등)예요.","e":"기계류내수출하지수, 건설수주액, 재고순환지표가 선행지수 구성지표예요. 소매판매액지수는 동행지수, 생산자제품재고지수는 후행지수에 들어가요.","w":["소매판매액지수(ㄷ)는 현재 경기를 보여 주는 동행지수예요.",null,"소매판매액(동행)과 생산자제품재고(후행)가 섞여 있어요.","생산자제품재고지수(ㅁ)는 후행지수예요."],"k":"기계 주문과 건설 수주는 '앞으로 공장을 돌리겠다'는 예고편이라 선행지표예요.","m":"선행: 기계류내수출하·건설수주·재고순환·코스피 / 소매판매=동행 / 제품재고=후행","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"경기종합지수와 확산지수","q":"CI(경기종합지수)와 DI(경기확산지수)에 대한 설명으로 가장 적절하지 않은 것은?","o":["DI는 구성지표 가운데 전월보다 좋아진 지표의 비율로 구하며 50을 기준으로 본다","DI가 전월보다 낮아져도 50보다 크면 경기는 확장 국면으로 본다","CI는 경기 변동의 방향뿐 아니라 변동의 크기도 보여 준다","DI는 경기 변동의 방향과 함께 진폭까지 정확하게 알려 준다"],"a":3,"c":"CI는 구성지표의 변화율을 합성해 경기의 방향과 크기(속도)를 보여 주고, DI는 좋아진 지표가 몇 %인지로 경기 변화가 얼마나 넓게 퍼졌는지(방향)만 보여 줘요.","e":"DI는 좋아진 지표의 '개수 비율'만 보므로 경기 변동의 폭이나 속도는 알 수 없어요.","w":["좋아진 지표 비율이 50을 넘으면 확장, 밑돌면 수축으로 봐요.","50 이상이면 여전히 좋아지는 지표가 더 많다는 뜻이에요.","CI는 변화율을 종합하므로 크기까지 보여 줘요.",null],"k":"DI는 '반 친구 중 몇 명이 성적이 올랐나', CI는 '반 평균 점수가 얼마나 올랐나'예요.","m":"CI = 방향 + 크기 / DI = 방향(확산 정도)만, 기준 50","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"기업경기실사지수 계산","q":"기업 250개사를 조사한 결과 80개사가 경기 호전, 120개사가 경기 악화, 50개사가 변화 없음으로 응답했다. 기업경기실사지수(BSI)와 그 판단으로 가장 적절한 것은?","o":["84 — 경기 확장 국면","−16 — 경기 수축 국면","116 — 경기 확장 국면","84 — 경기 수축 국면"],"a":3,"c":"BSI는 (긍정 응답 업체 수 − 부정 응답 업체 수) ÷ 전체 응답 업체 수 × 100 + 100으로 구해요. 100보다 크면 확장, 작으면 수축 국면으로 봐요.","e":"BSI = (80 − 120) ÷ 250 × 100 + 100 = −16 + 100 = 84예요. 100보다 작으므로 경기 수축 국면으로 판단해요.","w":["84는 100보다 작아 수축 국면이에요.","마지막에 100을 더하지 않았어요.","긍정과 부정을 바꿔 계산했어요.",null],"k":"100을 기준선으로 두고, 좋다는 기업보다 나쁘다는 기업이 많으면 100 밑으로 내려가요.","m":"BSI = (긍정 − 부정) ÷ 전체 × 100 + 100","f":"BSI = (긍정 응답 수 − 부정 응답 수) ÷ 전체 응답 수 × 100 + 100","rev":0},{"s":3,"sec":"거시경제","star":3,"lv":"상","t":"구직단념자와 고용 지표","q":"어느 나라의 15세 이상 인구(군인·재소자 제외)는 2,000만명이다. 취업자는 1,140만명, 실업자는 60만명이고, 나머지는 비경제활동인구이며 그 가운데 30만명은 구직단념자이다. 실업률과 고용률을 순서대로 짝지은 것은?","o":["7.3% — 57.0%","5.0% — 57.0%","5.0% — 95.0%","3.0% — 60.0%"],"a":1,"c":"구직단념자는 일할 뜻은 있지만 지난 4주간 구직활동을 하지 않아 실업자로 세지 않고 비경제활동인구에 넣어요. 실업률은 경제활동인구 대비, 고용률은 15세 이상 인구 대비로 구해요.","e":"경제활동인구 = 1,140 + 60 = 1,200만명, 실업률 = 60 ÷ 1,200 = 5.0%예요. 고용률 = 1,140 ÷ 2,000 = 57.0%예요.","w":["구직단념자 30만명을 실업자로 넣어 계산했어요(90 ÷ 1,230).",null,"고용률을 경제활동인구로 나눴어요. 고용률은 15세 이상 인구로 나눠요.","실업률을 15세 이상 인구로 나눴고, 60%는 경제활동참가율이에요."],"k":"일을 찾다 지쳐 쉬고 있는 사람은 통계상 '구직 중'이 아니라 '쉬는 사람'으로 세요.","m":"구직단념자 = 비경제활동인구, 고용률 = 취업자 ÷ 15세 이상 인구","f":"실업률 = 실업자 ÷ 경제활동인구, 고용률 = 취업자 ÷ 15세 이상 인구","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"상","t":"완전한 피셔효과의 반론","q":"명목이자율이 기대인플레이션만큼 정확히 오른다는 완전한 피셔효과에 관한 설명 중 가장 적절하지 않은 것은?","o":["오쿤은 사람들이 기대인플레이션에 완전히 적응하지 못해 그 크기가 명목이자율에 다 반영되지 않는다고 봤다","먼델-토빈은 인플레이션이 실질화폐잔고를 줄여 저축이 줄고, 그 결과 실질이자율이 올라 명목이자율이 기대인플레이션보다 더 크게 오른다고 봤다","섬머스는 위험과 유동성이 비슷한 대체 투자처를 찾기 어려운 시장의 불완전성을 근거로 들었다","피셔방정식에 따르면 명목이자율 = 실질이자율 + 기대인플레이션이다"],"a":1,"c":"피셔방정식은 명목이자율 = 실질이자율 + 기대인플레이션이에요. 현실에서는 명목금리가 기대인플레이션만큼 다 오르지 않는다는 반론이 여럿 있어요.","e":"먼델-토빈 효과는 인플레이션으로 실질잔고가 줄면 사람들이 소비를 줄이고 저축을 늘려 실질이자율이 내려간다는 주장이에요. 실질금리가 내려가니 명목금리는 기대인플레이션만큼 다 오르지 못해 완전한 피셔효과가 성립하지 않아요.","w":["오쿤의 '기대 적응 부족' 논거예요.",null,"섬머스의 '시장 불완전성' 논거예요.","명목 = 실질 + 기대인플레이션이 피셔방정식이에요."],"k":"물가가 오른다고 해서 이자가 물가 오른 만큼 딱 맞춰 붙지는 않아요. 사람들이 늦게 알아채거나, 저축이 늘어 진짜 금리가 내려가기도 하거든요.","m":"먼델-토빈: 실질잔고↓ → 저축↑ → 실질금리↓","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"하","t":"진폭·순환주기·비대칭성","q":"경기순환에 관한 설명 중 가장 적절하지 않은 것은?","o":["경기가 가장 높았던 때와 가장 낮았던 때의 수준 차이를 진폭(심도)이라 부른다","저점에서 다음 저점까지, 또는 정점에서 다음 정점까지를 한 번의 순환주기라 한다","보통 경기가 좋아지는 기간이 나빠지는 기간보다 오래가며, 이렇게 두 국면 길이가 서로 다른 성질을 비대칭성이라 한다","순환마다 주기와 진폭이 거의 똑같이 되풀이되므로 다음 정점이 언제 올지 미리 정확히 알 수 있다"],"a":3,"c":"경기는 회복·확장·후퇴·수축 국면을 반복하고, 저점에서 정점까지가 확장국면, 정점에서 저점까지가 수축국면이에요.","e":"경기순환의 주기와 진폭은 순환마다 달라 일정하지 않아요. 그래서 경기 전환점은 여러 지표를 보고 추정할 뿐 미리 정확히 알 수 없어요.","w":["높이 차이를 진폭(심도)이라 해요.","저점→저점 또는 정점→정점이 한 주기예요.","확장이 수축보다 긴 것이 일반적이고, 이를 비대칭성이라 해요.",null],"k":"파도는 늘 오르내리지만 파도마다 높이와 간격이 달라서, 다음 큰 파도가 정확히 언제 올지는 알 수 없어요.","m":"진폭 = 정점−저점 높이, 주기 = 저점→저점, 확장 > 수축(비대칭)","rev":0},{"s":3,"sec":"거시경제","star":2,"lv":"중","t":"IS·LM곡선 이동과 구축효과","q":"IS-LM 모형에 관한 〈보기〉의 설명 가운데 옳은 것을 모두 고른 것은? (IS곡선 우하향, LM곡선 우상향)\nㄱ. 물가가 오르면 실질통화량이 줄어 LM곡선이 왼쪽으로 이동하고 균형국민소득이 감소한다.\nㄴ. 소득세율을 올리면 가처분소득이 줄지만 IS곡선은 오른쪽으로 이동한다.\nㄷ. 정부지출과 조세는 IS곡선 위의 점을 움직이는 내생변수가 아니라 곡선 자체를 옮기는 외생변수이다.\nㄹ. 확대재정정책으로 이자율이 올라 민간투자가 줄어드는 구축효과는 LM곡선이 가파를수록 커진다.","o":["ㄱ, ㄴ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":1,"c":"IS곡선을 따라 움직이는 변수는 소득과 이자율뿐이에요. 정부지출·조세·소비 같은 요인은 IS곡선을, 통화량·물가는 LM곡선을 통째로 옮겨요.","e":"ㄱ, ㄷ, ㄹ이 옳아요. ㄴ은 방향이 반대예요. 세율 인상은 소비를 줄여 IS곡선을 왼쪽으로 옮기고 국민소득을 줄여요. 반대로 정부지출 증가와 감세는 IS곡선을, 통화량 증가는 LM곡선을 오른쪽으로 옮겨 소득을 늘려요. 구축효과가 클수록 재정정책 효과는 작아지고, 이자율이 움직이지 않는 유동성함정에서는 구축효과가 거의 없어요.","w":["ㄴ은 틀렸고, ㄷ과 ㄹ이 빠졌어요.",null,"ㄴ은 틀렸어요. 세율 인상은 IS곡선을 왼쪽으로 옮겨요.","ㄴ은 틀렸어요."],"k":"정부가 돈을 더 쓰면 금리가 올라 기업이 투자를 덜 하는데, 돈줄(LM)이 빡빡할수록 금리가 더 뛰어 밀려나는 투자가 커져요.","m":"물가↑·통화량↓ → LM 왼쪽, 세율↑ → IS 왼쪽, LM 가파를수록 구축효과↑","rev":0},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"CAPM으로 과대·과소평가 판단","q":"〈보기〉의 정보로 A주식의 요구수익률을 CAPM으로 구하고 투자 판단을 할 때 가장 적절한 것은?\n• 무위험이자율: 3%\n• 시장포트폴리오 기대수익률: 9%\n• A주식 베타: 1.5\n• A주식의 예상수익률: 14%","o":["요구수익률 12%, 과대평가되어 있으므로 매도","요구수익률 16.5%, 과대평가되어 있으므로 매도","요구수익률 12%, 과소평가되어 있으므로 매수","요구수익률 9%, 과소평가되어 있으므로 매수"],"a":2,"c":"CAPM은 베타만큼의 위험에 대해 요구되는 수익률을 알려 줘요. 예상수익률이 요구수익률보다 높으면 그 주식은 싸게(과소평가) 거래되는 거예요.","e":"요구수익률 = 3% + 1.5 × (9% − 3%) = 12%. 예상수익률 14%가 이보다 높으므로 SML 위에 있는 과소평가 주식이고 매수가 적절해요.","w":["예상수익률이 요구수익률보다 높으면 과소평가예요.","시장위험프리미엄(6%) 대신 시장수익률(9%)에 베타를 곱했어요.",null,"베타를 반영하지 않고 시장 기대수익률을 그대로 썼어요."],"k":"받아야 할 몫(12%)보다 더 줄 것 같으면(14%) 지금 가격이 싼 거예요.","m":"요구수익률 = Rf + β(Rm − Rf) · 예상 > 요구 → 과소평가 → 매수","f":"E(R) = 3% + 1.5 × (9% − 3%) = 12%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"최소분산 포트폴리오 비중","q":"〈보기〉의 두 자산으로 최소분산 포트폴리오를 만들 때 A자산의 투자비중으로 가장 적절한 것은?\n• A자산 표준편차: 10%\n• B자산 표준편차: 20%\n• 두 자산의 상관계수: 0","o":["20%","50%","67%","80%"],"a":3,"c":"두 자산으로 위험을 가장 작게 만들려면 위험(분산)이 작은 자산을 더 많이 담아야 해요. 상관계수가 0이면 계산이 간단해져요.","e":"상관계수가 0이면 wA = σB² ÷ (σA² + σB²) = 400 ÷ (100 + 400) = 80%예요.","w":["B자산의 비중(20%)과 바꿔 읽었어요.","두 자산 위험이 다른데 똑같이 나누면 최소분산이 아니에요.","표준편차 비율(20 ÷ 30)로 계산했어요. 분산으로 계산해야 해요.",null],"k":"덜 흔들리는 자산(A)을 더 많이 담아야 전체가 덜 흔들려요. 표준편차가 아니라 \"제곱(분산)\"으로 비교하는 게 포인트예요.","m":"상관 0이면 wA = σB² ÷ (σA² + σB²)","f":"wA = 20² ÷ (10² + 20²) = 400 ÷ 500 = 80%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"SML과 CML","q":"증권시장선(SML)과 자본시장선(CML)에 관한 설명으로 가장 적절하지 않은 것은?","o":["SML은 베타(체계적 위험)와 기대수익률의 관계를 나타낸다","CML은 표준편차(총위험)와 기대수익률의 관계를 나타낸다","SML은 개별 자산과 비효율적 포트폴리오에도 적용된다","CML은 개별 주식을 포함한 모든 자산의 기대수익률을 설명한다"],"a":3,"c":"CML은 효율적 포트폴리오(무위험자산 + 시장포트폴리오)만 위에 놓이는 선이고, SML은 모든 자산의 기대수익률을 베타로 설명해요.","e":"CML은 효율적 포트폴리오에만 적용돼요. 개별 주식처럼 비체계적 위험이 남아 있는 자산은 CML 아래에 놓여요.","w":["SML의 가로축은 베타예요.","CML의 가로축은 표준편차예요.","SML은 모든 자산에 적용돼요.",null],"k":"CML은 \"잘 분산된 포트폴리오 전용 도로\", SML은 \"모든 자산이 다니는 도로\"예요.","m":"SML = β · 모든 자산 / CML = σ · 효율적 포트폴리오만"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"CAPM의 가정","q":"CAPM의 가정으로 가장 적절하지 않은 것은?","o":["모든 투자자는 평균-분산 기준으로 투자한다","무위험이자율로 무제한 차입과 대출이 가능하다","세금과 거래비용이 없다","투자자마다 자산의 기대수익률과 위험에 대한 기대가 서로 다르다"],"a":3,"c":"CAPM은 시장 균형을 단순하게 설명하려고 여러 이상적인 가정을 둬요.","e":"CAPM은 모든 투자자가 기대수익률·위험·상관관계에 대해 같은 기대(동질적 기대)를 한다고 가정해요.","w":["평균-분산 기준이 가정이에요.","무위험 차입·대출이 가정이에요.","세금·거래비용이 없다고 가정해요.",null],"k":"모두가 같은 안경을 쓰고 시장을 본다고 가정해요.","m":"CAPM 가정: 동질적 기대 · 무위험 차입·대출 · 세금·비용 X · 단일기간"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"상관계수 −1일 때 포트폴리오 위험","q":"표준편차가 10%인 A자산에 60%, 20%인 B자산에 40%를 투자했다. 두 자산의 상관계수가 −1일 때 포트폴리오 표준편차는?","o":["0%","2%","10%","14%"],"a":1,"c":"상관계수가 −1이면 두 자산이 정반대로 움직여 위험이 크게 상쇄돼요. 비중을 잘 맞추면 위험을 0으로 만들 수도 있어요.","e":"σp = |0.6 × 10% − 0.4 × 20%| = |6% − 8%| = 2%예요.","w":["비중을 맞추면 0이 가능하지만 이 비중에서는 2%예요.",null,"상관계수가 0일 때의 값(√(6² + 8²) = 10%)이에요.","상관계수 1일 때의 값이에요."],"k":"시소의 양쪽처럼 반대로 움직여서 흔들림이 거의 다 사라져요.","m":"ρ = −1 → σp = |wAσA − wBσB|","f":"|6 − 8| = 2%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"하","rev":0,"t":"체계적 위험과 비체계적 위험","q":"분산투자로 줄일 수 있는 위험으로 가장 적절한 것은?","o":["경기 변동 위험","금리 변동 위험","개별 기업의 경영진 교체나 소송 같은 기업 고유 위험","인플레이션 위험"],"a":2,"c":"총위험은 시장 전체에 영향을 주는 체계적 위험과 개별 기업에만 생기는 비체계적 위험으로 나뉘어요.","e":"기업 고유의 사건에서 오는 비체계적 위험은 여러 종목에 나눠 투자하면 서로 상쇄되어 줄어요.","w":["경기 변동은 모든 기업에 영향을 주는 체계적 위험이에요.","금리 변동은 체계적 위험이에요.",null,"인플레이션은 체계적 위험이에요."],"k":"한 회사의 사고는 다른 회사로 상쇄되지만, 경기·금리 같은 \"날씨\"는 피할 수 없어요.","m":"분산 가능 = 비체계적(기업 고유) / 불가능 = 체계적(시장)"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"지배원리","q":"〈보기〉의 네 자산 가운데 지배원리에 따라 투자 대상에서 제외되는 자산을 모두 고른 것은?\n• A: 기대수익률 10%, 표준편차 15%\n• B: 기대수익률 12%, 표준편차 15%\n• C: 기대수익률 12%, 표준편차 20%\n• D: 기대수익률 8%, 표준편차 10%","o":["A","A, C","C, D","A, C, D"],"a":1,"c":"지배원리는 같은 위험이면 수익률이 높은 것, 같은 수익률이면 위험이 낮은 것을 고르는 원칙이에요.","e":"A는 같은 위험(15%)에서 수익률이 더 높은 B에, C는 같은 수익률(12%)에서 위험이 더 낮은 B에 지배돼요. D는 위험이 가장 낮아 지배되지 않아요.","w":["C도 B에 지배돼요.",null,"D는 위험이 가장 낮아 다른 자산에 지배되지 않아요.","D는 제외되지 않아요."],"k":"같은 값이면 더 맛있는 것, 같은 맛이면 더 싼 것을 고르는 원리예요.","m":"같은 σ → 높은 E / 같은 E → 낮은 σ"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"자본배분선의 기울기","q":"위험자산 포트폴리오의 기대수익률이 10%, 표준편차가 20%, 무위험이자율이 2%일 때 자본배분선(CAL)의 기울기는?","o":["0.1","0.4","0.5","2.5"],"a":1,"c":"무위험자산과 위험자산을 섞을 때 생기는 직선이 자본배분선이고, 그 기울기는 위험 한 단위당 초과수익(샤프비율)이에요.","e":"기울기 = (10% − 2%) ÷ 20% = 0.4예요.","w":["계산이 맞지 않아요.",null,"무위험이자율을 빼지 않았어요.","분자와 분모를 바꿨어요."],"k":"위험 1만큼 더 지면 초과수익을 0.4만큼 더 받는다는 뜻이에요.","m":"CAL 기울기 = (E(R) − Rf) ÷ σ","f":"(10 − 2) ÷ 20 = 0.4"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"무위험자산과 위험자산의 결합","q":"기대수익률 10%·표준편차 20%인 위험자산 포트폴리오에 60%, 수익률 2%인 무위험자산에 40%를 투자했다. 전체 포트폴리오의 기대수익률과 표준편차는?","o":["6.8%, 12%","6.8%, 20%","10%, 12%","6.0%, 8%"],"a":0,"c":"무위험자산은 표준편차가 0이고 다른 자산과 상관관계도 없어요. 그래서 위험은 위험자산 비중만큼만 남아요.","e":"E = 0.6 × 10% + 0.4 × 2% = 6.8%, σ = 0.6 × 20% = 12%예요.","w":[null,"표준편차를 줄이지 않았어요.","기대수익률을 줄이지 않았어요.","계산이 맞지 않아요."],"k":"위험한 자산을 60%만 담으면 흔들림도 60%만 남아요.","m":"σp = w(위험) × σ(위험)","f":"E = 6 + 0.8 = 6.8% · σ = 0.6 × 20 = 12%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"APT의 특징","q":"차익거래가격결정이론(APT)에 관한 설명으로 가장 적절하지 않은 것은?","o":["여러 공통 요인으로 기대수익률을 설명할 수 있다","차익거래 기회가 없는 균형 상태를 전제로 한다","요인의 종류와 개수를 이론이 미리 정해 주지 않는다","시장포트폴리오가 효율적이어야만 성립한다"],"a":3,"c":"APT는 차익거래가 불가능하다는 조건만으로 기대수익률과 여러 요인의 관계를 설명해요. CAPM보다 가정이 적어요.","e":"APT는 시장포트폴리오의 존재나 효율성을 가정하지 않아요. 그것이 필요한 것은 CAPM이에요.","w":["다요인 모형이 가능해요.","무차익 균형이 핵심 전제예요.","어떤 요인을 쓸지는 실증적으로 정해요.",null],"k":"APT는 \"공짜 점심(차익)은 없다\"만 믿으면 성립해요.","m":"APT: 다요인 · 무차익 균형 · 시장포트폴리오 불필요"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"다요인 APT 계산","q":"무위험이자율 3%이고, 요인1의 위험프리미엄이 4%, 요인2의 위험프리미엄이 2%이다. 요인1 민감도 1.2, 요인2 민감도 0.5인 주식의 APT 기대수익률은?","o":["7.8%","8.8%","9.0%","10.4%"],"a":1,"c":"APT 기대수익률은 무위험이자율에 각 요인 민감도 × 요인 위험프리미엄을 더해 구해요.","e":"E(R) = 3% + 1.2 × 4% + 0.5 × 2% = 3% + 4.8% + 1% = 8.8%예요.","w":["요인2를 빠뜨렸어요.",null,"민감도를 곱하지 않고 위험프리미엄(4% + 2%)만 더했어요.","계산이 맞지 않아요. 요인별로 민감도 × 위험프리미엄을 구해 더해야 해요."],"k":"기본 3%에 요인별 \"보너스\"를 민감도만큼 얹어 줘요.","m":"E(R) = Rf + Σ bₖ × λₖ","f":"3 + 1.2 × 4 + 0.5 × 2 = 8.8%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"단일요인 차익거래","q":"단일요인모형이 성립하고 A자산과 B자산의 요인 민감도가 모두 1이다. A의 기대수익률이 10%, B의 기대수익률이 8%일 때 차익거래 방법은?","o":["A 매수, B 공매도","A 공매도, B 매수","A, B 모두 매수","차익거래 기회가 없다"],"a":0,"c":"요인 민감도가 같으면 위험이 같으므로 기대수익률도 같아야 해요. 다르면 차익거래 기회가 생겨요.","e":"같은 위험에 수익률이 높은 A를 사고 낮은 B를 공매도하면 위험 없이 2%p 차익을 얻을 수 있어요.","w":[null,"방향이 반대예요.","둘 다 사면 위험이 상쇄되지 않아요.","민감도가 같은데 수익률이 달라 기회가 있어요."],"k":"똑같은 물건이 다른 가격이면 싼 데서 사서 비싼 데 팔아요. 여기선 \"수익률 높은 A\"가 싼 거예요.","m":"같은 β·다른 E(R) → 높은 쪽 매수 + 낮은 쪽 공매도"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"단일지표모형의 위험 분해","q":"단일지표모형에서 주식 i의 베타가 1.2, 시장수익률 표준편차가 20%, 잔차 표준편차가 15%이다. 주식 i의 총분산 중 체계적 위험이 차지하는 비중에 가장 가까운 것은?","o":["약 28%","약 56%","약 72%","약 100%"],"a":2,"c":"단일지표모형은 총분산을 시장 때문에 생기는 체계적 분산(β²σm²)과 기업 고유의 잔차 분산으로 나눠요.","e":"체계적 분산 = 1.2² × 20² = 576, 잔차 분산 = 15² = 225, 총분산 = 801. 체계적 비중 = 576 ÷ 801 ≈ 72%예요.","w":["비체계적 비중이에요.","계산이 맞지 않아요.",null,"잔차 분산이 있어 100%가 아니에요."],"k":"흔들림 801 중 576은 \"시장 탓\", 225는 \"회사 탓\"이에요.","m":"σᵢ² = βᵢ²σm² + σ²(e)","f":"576 ÷ (576 + 225) ≈ 72%"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"단일지표모형의 추정 변수 수","q":"100개 종목으로 포트폴리오를 구성할 때 단일지표모형에서 필요한 추정치의 수는? (개별 종목마다 알파·베타·잔차분산, 시장의 기대수익률·분산을 추정한다)","o":["102개","202개","302개","5,150개"],"a":2,"c":"마코위츠 모형은 모든 종목 쌍의 공분산이 필요해 추정치가 매우 많아요. 단일지표모형은 이를 크게 줄여 줘요.","e":"단일지표모형 추정치 = 3n + 2 = 3 × 100 + 2 = 302개예요.","w":["종목당 1개로 계산했어요.","종목당 2개로 계산했어요.",null,"마코위츠 모형의 추정치 수예요."],"k":"모든 짝꿍 관계를 다 재는 대신, 각자 \"시장과의 관계\"만 재면 돼요.","m":"단일지표 3n + 2 · 마코위츠 n(n + 3)/2","f":"3 × 100 + 2 = 302"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"기대수익률 추정 방법","q":"자산배분을 위해 주식·채권 등 자산군별로 앞으로의 수익률을 예상할 때 쓰는 방법이 아닌 것은?","o":["추세분석법","시나리오분석법","펀더멘털 분석법","최소분산법"],"a":3,"c":"자산배분을 하려면 각 자산집단의 기대수익률을 먼저 추정해야 해요.","e":"기대수익률 추정 방법은 추세분석법, 시나리오분석법, 펀더멘털 분석법, 시장공동예측치 사용법이에요. 최소분산법은 포트폴리오 구성 방법이에요.","w":["과거 추세를 연장하는 방법이에요.","경제 시나리오별 수익률을 확률로 가중해요.","과거 자료와 위험프리미엄 구조를 이용해요.",null],"k":"\"앞으로 얼마 벌까?\"를 추정하는 4가지 방법에 최소분산은 없어요.","m":"기대수익률 추정: 추세 · 시나리오 · 펀더멘털 · 시장공동예측치"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"시나리오별 기대수익률","q":"〈보기〉의 시나리오에 따른 주식의 기대수익률은?\n• 호황(확률 30%): 수익률 20%\n• 보통(확률 50%): 수익률 10%\n• 불황(확률 20%): 수익률 −10%","o":["6.7%","9.0%","10.0%","13.0%"],"a":1,"c":"기대수익률은 각 시나리오 수익률에 그 확률을 곱해 모두 더한 값이에요.","e":"0.3 × 20% + 0.5 × 10% + 0.2 × (−10%) = 6% + 5% − 2% = 9%예요.","w":["확률을 반영하지 않고 단순 평균했어요.",null,"보통 시나리오 수익률을 그대로 썼어요.","불황의 음수를 양수로 계산했어요."],"k":"날씨별 매출에 날씨 확률을 곱해 더하면 평균 매출이 나와요.","m":"E(R) = Σ pᵢRᵢ","f":"6 + 5 − 2 = 9%"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"시나리오별 표준편차","q":"〈보기〉의 시나리오에서 주식의 기대수익률이 9%일 때 표준편차에 가장 가까운 것은?\n• 호황(확률 30%): 20%\n• 보통(확률 50%): 10%\n• 불황(확률 20%): −10%","o":["약 9.0%","약 10.4%","약 12.6%","약 109.0%"],"a":1,"c":"분산은 각 시나리오 수익률이 기대수익률에서 벗어난 정도를 제곱해 확률로 가중평균한 값이고, 그 제곱근이 표준편차예요.","e":"분산 = 0.3 × 11² + 0.5 × 1² + 0.2 × 19² = 36.3 + 0.5 + 72.2 = 109, 표준편차 = √109 ≈ 10.4%예요.","w":["기대수익률과 혼동했어요.",null,"계산이 맞지 않아요.","분산을 표준편차로 착각했어요."],"k":"평균에서 얼마나 떨어져 있는지를 제곱해 평균 낸 뒤 루트를 씌워요.","m":"σ² = Σ pᵢ(Rᵢ − E)²","f":"√(36.3 + 0.5 + 72.2) = √109 ≈ 10.4%"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"변동계수","q":"A주식(기대수익률 8%, 표준편차 10%)과 B주식(기대수익률 15%, 표준편차 15%)을 변동계수로 비교한 설명으로 가장 적절한 것은?","o":["A의 변동계수가 더 작아 위험 대비 수익이 더 좋다","B의 변동계수가 1.0으로 A(1.25)보다 작아 단위 수익당 위험이 더 작다","두 주식의 변동계수는 같다","변동계수는 클수록 좋다"],"a":1,"c":"변동계수는 표준편차를 기대수익률로 나눈 값으로, 수익 1단위당 위험이 얼마인지 보여 줘요. 작을수록 좋아요.","e":"A = 10 ÷ 8 = 1.25, B = 15 ÷ 15 = 1.0이에요. B의 변동계수가 더 작아 단위 수익당 위험이 작아요.","w":["A의 변동계수가 더 커요.",null,"1.25와 1.0으로 달라요.","작을수록 좋아요."],"k":"수익 1원을 벌기 위해 감수하는 흔들림이 작을수록 좋아요.","m":"변동계수 = σ ÷ E(R) · 작을수록 효율적","f":"A 1.25 · B 1.0"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"포트폴리오 수익률과 위험의 성질","q":"두 위험자산으로 만든 포트폴리오에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 포트폴리오 기대수익률은 개별 기대수익률의 가중평균이다.\nㄴ. 포트폴리오 표준편차는 개별 표준편차의 가중평균보다 크지 않다.\nㄷ. 상관계수가 1이면 포트폴리오 표준편차는 개별 표준편차의 가중평균과 같다.\nㄹ. 위험자산 수를 무한히 늘리면 포트폴리오 총위험은 0이 된다.","o":["1개","2개","3개","4개"],"a":2,"c":"수익률은 가중평균이지만, 위험(표준편차)은 상관관계 때문에 가중평균보다 작거나 같아요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. 종목 수를 아무리 늘려도 체계적 위험은 남으므로 총위험이 0이 되지는 않아요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄷ도 옳은 설명이에요.",null,"ㄹ은 틀렸어요. 체계적 위험은 남아요."],"k":"종목을 아무리 늘려도 \"시장 전체의 날씨(체계적 위험)\"는 피할 수 없어요.","m":"E(Rp) = 가중평균 · σp ≤ 가중평균 · 체계적 위험은 남음"},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"t":"토빈의 분리정리","q":"토빈의 분리정리에 관한 설명으로 가장 적절한 것은?","o":["위험회피도에 따라 위험자산 포트폴리오의 종목 구성이 달라진다","투자자마다 서로 다른 위험자산 포트폴리오를 보유한다","최적 위험자산 포트폴리오 선택과 무위험자산과의 배분 결정은 서로 분리된다","무위험자산은 투자자 선택에 영향을 주지 않는다"],"a":2,"c":"무위험자산이 있으면 투자 결정이 두 단계로 나뉘어요. 먼저 최적 위험자산 포트폴리오를 정하고, 그다음 무위험자산과의 비율을 정해요.","e":"최적 위험자산 포트폴리오(시장포트폴리오)는 모든 투자자에게 같고, 위험 성향은 무위험자산과의 배분 비율에만 반영돼요.","w":["종목 구성은 같고 비율만 달라요.","모든 투자자가 같은 위험자산 포트폴리오를 가져요.",null,"무위험자산이 있어야 분리가 성립해요."],"k":"모두 같은 \"펀드\"를 사고, 그 펀드와 예금 비율만 사람마다 달라요.","m":"분리정리: 위험자산 구성 동일 · 무위험자산 비율만 다름"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"베타 계산","q":"주식 i와 시장 수익률의 공분산이 0.024이고, 시장 수익률의 표준편차가 0.2일 때 주식 i의 베타는?","o":["0.12","0.48","0.6","1.2"],"a":2,"c":"베타는 개별 주식이 시장과 함께 움직이는 정도(공분산)를 시장 자체의 변동(분산)으로 나눈 값이에요.","e":"β = Cov(i, m) ÷ σm² = 0.024 ÷ 0.04 = 0.6이에요.","w":["분산(0.04) 대신 표준편차(0.2)로 나눴어요.","계산이 맞지 않아요. 시장 분산 0.04로 나눠야 해요.",null,"계산이 맞지 않아요. 0.024 ÷ 0.04 = 0.6이에요."],"k":"시장 분산(0.2² = 0.04)으로 나누는 게 포인트예요.","m":"β = Cov(i, m) ÷ σm²","f":"0.024 ÷ 0.04 = 0.6"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"상관계수 계산","q":"A자산과 B자산 수익률의 공분산이 0.006이고, 표준편차가 각각 0.1과 0.2이다. 두 자산의 상관계수는?","o":["0.03","0.3","0.6","3.0"],"a":1,"c":"상관계수는 공분산을 두 자산 표준편차의 곱으로 나눠 −1과 1 사이로 표준화한 값이에요.","e":"ρ = 0.006 ÷ (0.1 × 0.2) = 0.006 ÷ 0.02 = 0.3이에요.","w":["B의 표준편차(0.2) 하나로만 나눴어요.",null,"표준편차의 곱 대신 A의 분산(0.1² = 0.01)으로 나눴어요.","상관계수는 1을 넘을 수 없어요."],"k":"공분산은 단위가 제각각이라, 표준편차로 나눠 −1~1 점수로 바꿔요.","m":"ρ = Cov ÷ (σA × σB)","f":"0.006 ÷ 0.02 = 0.3"},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","rev":0,"t":"최소분산 비중(상관계수 0.5)","q":"A자산 표준편차 20%, B자산 표준편차 30%, 두 자산의 상관계수가 0.5일 때 최소분산 포트폴리오의 A자산 비중에 가장 가까운 것은?","o":["60%","69%","86%","100%"],"a":2,"c":"최소분산 포트폴리오 비중은 두 자산의 분산과 공분산으로 구해요.","e":"Cov = 0.5 × 20 × 30 = 300. wA = (σB² − Cov) ÷ (σA² + σB² − 2Cov) = (900 − 300) ÷ (400 + 900 − 600) = 600 ÷ 700 ≈ 86%예요.","w":["표준편차 비율로 계산했어요.","상관계수 0일 때의 값이에요.",null,"두 자산 모두를 섞어야 위험이 가장 작아요."],"k":"A가 덜 흔들려서 A를 훨씬 많이 담아야 해요. 공분산까지 고려하면 약 86%예요.","m":"wA = (σB² − Cov) ÷ (σA² + σB² − 2Cov)","f":"(900 − 300) ÷ 700 ≈ 86%"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"평균-분산 효용 계산","q":"투자자 효용함수가 U = E(R) − ½ × A × σ²이고 위험회피계수 A가 4이다. 기대수익률 10%, 표준편차 20%인 포트폴리오의 효용(확실성등가수익률)은?","o":["2%","6%","8%","10%"],"a":0,"c":"평균-분산 효용함수는 기대수익률에서 위험에 대한 불만(위험회피계수 × 분산)을 빼서 만족도를 구해요.","e":"U = 0.10 − 0.5 × 4 × 0.2² = 0.10 − 0.08 = 0.02, 즉 2%예요.","w":[null,"½ × A를 곱하지 않고 분산(0.04)만 뺐어요.","위험회피계수 A(4)를 곱하지 않고 ½ × 0.04 = 0.02만 뺐어요.","위험 차감을 하지 않았어요."],"k":"10%를 벌지만 흔들림 때문에 겁 많은 사람에게는 \"확실한 2%\"와 같은 만족이에요.","m":"U = E(R) − ½Aσ²","f":"0.10 − 0.5 × 4 × 0.04 = 0.02"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"시장포트폴리오","q":"CAPM에서 시장포트폴리오에 관한 설명으로 가장 적절하지 않은 것은?","o":["모든 위험자산을 시가총액 비중대로 포함한다","CML과 효율적 투자선이 접하는 점의 포트폴리오이다","시장포트폴리오의 베타는 1이다","시장포트폴리오에는 비체계적 위험이 가장 많이 남아 있다"],"a":3,"c":"시장포트폴리오는 모든 위험자산을 시가총액대로 담은, 가장 잘 분산된 포트폴리오예요.","e":"시장포트폴리오는 완전히 분산되어 비체계적 위험이 사라지고 체계적 위험만 남아요.","w":["시가총액 비중대로 모든 위험자산을 담아요.","접점 포트폴리오예요.","정의상 베타는 1이에요.",null],"k":"시장 전체를 다 담으면 개별 회사 사고는 서로 상쇄돼 사라져요.","m":"시장포트폴리오: 시가총액 가중 · β = 1 · 비체계적 위험 0"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","rev":0,"t":"하방위험 측정","q":"투자 위험을 측정하는 지표 가운데 평균보다 낮은 수익률(손실 쪽)만을 고려하는 것은?","o":["표준편차","하방편차(하방위험)","베타","상관계수"],"a":1,"c":"표준편차는 위·아래로 벗어나는 것을 모두 위험으로 보지만, 투자자는 보통 손실 쪽만 걱정해요.","e":"평균(또는 목표)보다 낮은 수익률만 고려하는 지표가 하방편차(하방위험)예요.","w":["위아래 변동을 모두 위험으로 봐요.",null,"베타는 시장 대비 민감도예요.","상관계수는 두 자산이 함께 움직이는 정도예요."],"k":"올라가는 흔들림은 반갑지만 떨어지는 흔들림만 걱정하는 지표예요.","m":"하방위험 = 손실 쪽 변동만 측정"},{"s":3,"sec":"분산투자기법","star":2,"lv":"상","rev":0,"t":"CML을 이용한 기대수익률","q":"무위험이자율 3%, 시장포트폴리오 기대수익률 9%, 시장포트폴리오 표준편차 15%이다. 표준편차가 10%인 효율적 포트폴리오의 CML상 기대수익률은?","o":["5%","6%","7%","9%"],"a":2,"c":"CML은 무위험자산과 시장포트폴리오를 섞은 효율적 포트폴리오의 기대수익률과 표준편차 관계예요.","e":"E(R) = 3% + (9% − 3%) ÷ 15% × 10% = 3% + 4% = 7%예요.","w":["계산이 맞지 않아요.","계산이 맞지 않아요.",null,"시장포트폴리오 수익률이에요."],"k":"위험 1%당 0.4%의 보상을 받으니, 위험 10%면 4%를 더 받아요.","m":"CML: E(R) = Rf + [(Rm − Rf) ÷ σm] × σp","f":"3 + 0.4 × 10 = 7%"},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"증권특성선","q":"증권특성선(SCL)에 관한 설명으로 가장 적절하지 않은 것은?","o":["시장 초과수익률을 독립변수, 개별 증권 초과수익률을 종속변수로 회귀분석해 구한 직선이다","직선의 기울기는 그 증권의 베타를 나타낸다","직선의 절편은 시장과 무관하게 얻은 초과성과인 알파를 나타낸다","회귀선 주변에 흩어진 잔차의 분산은 체계적 위험을 나타낸다"],"a":3,"c":"증권특성선은 개별 증권 수익률이 시장 수익률에 어떻게 반응하는지 보여 주는 회귀직선이에요. 기울기는 베타, 절편은 알파예요.","e":"잔차는 시장으로 설명되지 않는 부분이므로 잔차분산은 비체계적(기업 고유) 위험을 나타내요. 체계적 위험은 베타로 재요.","w":["최소자승법(OLS) 회귀로 구한 직선이에요.","시장이 1 움직일 때 증권이 움직이는 정도가 기울기(베타)예요.","시장 초과수익이 0일 때의 성과가 알파예요.",null],"k":"시장이라는 바람에 얼마나 흔들리나는 기울기, 혼자 흔들리는 몫은 잔차예요.","m":"SCL: 기울기 = 베타, 절편 = 알파, 잔차분산 = 비체계적 위험","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"변동비율법과 평균분할투자","q":"포뮬러 플랜과 관련 투자방법에 관한 설명으로 가장 적절하지 않은 것은?","o":["불변금액법(정액법)은 주식 투자금액을 일정하게 유지하도록 주식과 채권을 사고판다","불변비율법(정률법)은 주식과 채권 평가액의 비율을 일정하게 유지한다","변동비율법(변수법)은 주가 상승 때 주식 비율을 끌어올리고 하락 때 끌어내린다","평균분할투자는 정해진 시기마다 같은 금액으로 사므로, 주가가 낮을 때 더 많은 주식을 사게 된다"],"a":2,"c":"포뮬러 플랜은 미리 정한 규칙대로 주가 상승 때 덜어 내고 하락 때 사들이는 역투자 기법이에요. 평균분할투자(정액분할투자)는 시장을 예측하지 않는 소극적 전략이에요.","e":"변동비율법은 주가가 오를수록 주식 비율을 낮추고, 내릴수록 높이는 역투자 방식이에요. 오를수록 늘리는 것은 추세추종이라 포뮬러 플랜과 정반대예요.","w":["주식 금액이 정해진 금액을 넘으면 팔고 모자라면 사요.","예를 들어 5 : 5 비율을 계속 지키는 방식이에요.",null,"같은 금액으로 사면 쌀 때 더 많은 주식을 사게 되어 평균 매입단가가 낮아지는 효과가 있어요."],"k":"포뮬러 플랜은 '비쌀 땐 덜, 쌀 땐 더' 사는 알뜰 장보기 규칙이에요.","m":"포뮬러 플랜 = 역투자 / 변수법: 주가↑ → 주식비율↓","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"자본시장선의 구조","q":"CML(자본시장선)에 대한 설명으로 가장 적절하지 않은 것은?","o":["시장포트폴리오(M) 왼쪽 구간은 자금 일부를 무위험자산에 빌려준 대출 포트폴리오이다","시장포트폴리오(M) 오른쪽 구간은 무위험이자율로 돈을 빌려 M을 더 산 차입 포트폴리오이다","무위험자산에서 그은 자본배분선 중 기울기(위험보상비율)가 가장 큰 것이 CML이다","투자자가 위험을 싫어할수록 자본시장선의 기울기가 더 가팔라진다"],"a":3,"c":"CML은 무위험자산과 시장포트폴리오를 결합한 효율적 포트폴리오들의 선이에요. 기울기 (E(Rm) − Rf) ÷ σm은 시장에서 정해지는 위험의 가격이에요.","e":"CML의 기울기는 시장 전체에서 하나로 정해지므로 투자자의 위험 성향과 관계없어요. 위험 성향은 CML 위의 어느 점을 고르느냐(대출·차입 비율)에만 영향을 줘요.","w":["무위험자산에 일부를 넣은 구간이에요.","돈을 빌려 시장포트폴리오에 더 투자한 구간이에요.","시장포트폴리오와 접하는 선이 가장 가파른 자본배분선이에요.",null],"k":"CML은 모두가 같이 쓰는 고속도로이고, 투자자는 각자 내릴 출구만 다르게 고르는 거예요.","m":"CML 기울기 = 시장 위험의 가격(모두에게 같음)","rev":0},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","t":"트레이너-블랙 모형 비중","q":"트레이너-블랙 모형으로 적극적 포트폴리오를 구성한다. 분석한 두 종목의 자료가 다음과 같을 때 적극적 포트폴리오에서 A종목의 투자비중에 가장 가까운 것은?\n• A종목: 알파 2%, 잔차분산 0.04\n• B종목: 알파 3%, 잔차분산 0.12","o":["40.0%","66.7%","33.3%","75.0%"],"a":1,"c":"트레이너-블랙 모형은 소수 종목의 알파로 초과수익을 노리면서 시장지수와 결합해 비체계적 위험을 줄이는 적극적 전략이에요. 각 종목 비중은 평가비율(알파 ÷ 잔차분산)에 비례해요.","e":"A의 평가비율 = 0.02 ÷ 0.04 = 0.5, B = 0.03 ÷ 0.12 = 0.25예요. A 비중 = 0.5 ÷ (0.5 + 0.25) ≈ 66.7%예요. 알파가 같다면 잔차위험이 작은 종목을 더 담아요.","w":["알파 크기만으로 비중을 나눴어요(2 ÷ 5).",null,"B종목의 비중이에요.","잔차분산 비율로 나눠 위험이 큰 쪽을 더 담는 거꾸로 된 계산이에요."],"k":"성적(알파)은 좋으면서 기복(잔차위험)이 작은 선수에게 더 많은 출전 시간을 주는 방식이에요.","m":"TB 비중 ∝ 알파 ÷ 잔차분산","f":"평가비율 = 알파 ÷ 잔차분산, 비중 = 개별 평가비율 ÷ 평가비율 합계","rev":0},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","t":"상관계수 −1과 무위험 포트폴리오","q":"표준편차가 12%인 A주식과 28%인 B주식의 상관계수가 −1이다. 공매도 없이 두 주식으로 위험이 0인 포트폴리오를 만들려면 A주식에 얼마를 투자해야 하는가?","o":["30%","50%","70%","84.5%"],"a":2,"c":"상관계수가 −1이면 두 자산이 정반대로 움직여, 특정 비중에서 위험을 완전히 없앨 수 있어요. 변동성이 작은 자산을 더 많이 담아야 해요.","e":"σp = wA × 12 − (1 − wA) × 28 = 0이 되려면 wA = 28 ÷ (12 + 28) = 70%예요.","w":["B주식 비중(12 ÷ 40)을 A로 착각했어요.","표준편차가 다르면 반반으로는 위험이 0이 되지 않아요.",null,"분산(제곱)으로 나눈 값으로, 상관계수 0일 때의 최소분산 공식이에요."],"k":"시소의 무거운 쪽(변동성 큰 B)은 짧게, 가벼운 쪽(A)은 길게 앉아야 균형이 맞아요.","m":"ρ = −1: wA = σB ÷ (σA + σB)","f":"wA = σB ÷ (σA + σB)","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"하","t":"효용함수의 모양","q":"투자자의 위험 성향과 효용함수에 관한 설명으로 가장 적절하지 않은 것은?","o":["위험회피형의 효용함수는 원점에 대해 오목하고, 부가 늘수록 효용 증가분이 줄어든다","위험선호형의 효용함수는 원점에 대해 볼록하고, 부가 늘수록 효용 증가분이 커진다","위험중립형은 효용이 기대수익에 비례하므로 위험은 따지지 않는다","위험회피형은 기댓값이 같다면 확실한 금액보다 불확실한 도박을 더 좋아한다"],"a":3,"c":"위험회피형은 같은 기댓값이면 확실한 쪽을 좋아하고, 위험을 지려면 추가 보상을 요구해요. 위험회피 성향이 강할수록 무차별곡선 기울기가 가팔라요.","e":"기댓값이 같을 때 불확실한 도박을 더 좋아하는 것은 위험선호형이에요. 위험회피형은 확실한 금액을 더 좋아해요.","w":["한계효용이 줄어드는 오목한 모양이에요.","한계효용이 커지는 볼록한 모양이에요.","직선 모양이라 기대수익만 보고 결정해요.",null],"k":"위험회피형은 '확실한 만 원'을 '반반 확률로 2만 원 또는 0원'보다 좋아해요.","m":"회피 = 오목(무차별곡선 가파름), 선호 = 볼록, 중립 = 직선","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"산술평균과 기하평균","q":"어느 주식의 연도별 수익률이 +30%, −20%, +10%였다. 이 기간의 평균수익률에 관한 설명으로 가장 적절한 것은?","o":["산술평균은 약 6.7%, 기하평균은 약 4.6%이며, 수익률 등락이 클수록 두 값의 차이가 커진다","산술평균과 기하평균은 모두 약 6.7%로 같다","기하평균이 약 6.7%로 산술평균 약 4.6%보다 크다","산술평균은 약 6.7%이고 복리 효과를 반영하므로 실제 누적성과를 가장 잘 보여 준다"],"a":0,"c":"산술평균은 수익률을 단순 평균한 값이고, 기하평균은 복리로 연결한 연평균 성과예요. 기하평균은 산술평균보다 크지 않고, 변동이 클수록 차이가 커져요.","e":"산술평균 = (30 − 20 + 10) ÷ 3 ≈ 6.7%예요. 기하평균 = (1.3 × 0.8 × 1.1)^(1/3) − 1 = 1.144^(1/3) − 1 ≈ 4.6%예요.","w":[null,"수익률이 해마다 다르면 두 값은 달라요.","기하평균은 산술평균보다 클 수 없어요.","복리 효과를 반영해 실제 누적성과를 보여 주는 것은 기하평균이에요."],"k":"30% 올랐다 20% 내리면 제자리가 아니라 손해가 나듯, 등락이 클수록 실제 성과(기하평균)는 단순 평균보다 낮아요.","m":"기하평균 ≤ 산술평균, 변동↑ → 차이↑","f":"기하평균 = [(1 + r₁)(1 + r₂)(1 + r₃)]^(1/3) − 1","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"베타의 성질","q":"베타에 관한 설명으로 가장 적절하지 않은 것은?","o":["시장포트폴리오 자신의 베타는 1이다","CAPM이 성립하면 베타가 0인 자산의 기대수익률은 무위험이자율과 같다","시장 상승이 예상될 때 고베타 종목을, 하락이 예상될 때 저베타 종목을 담는 것이 베타를 이용한 종목 교체이다","베타가 높은 종목은 언제나 총위험(표준편차)도 더 크다"],"a":3,"c":"베타는 시장 변동에 대한 민감도로 체계적 위험만 재요. 총위험 = 체계적 위험 + 비체계적 위험이에요.","e":"베타가 높아도 비체계적 위험이 작으면 총위험은 더 작을 수 있어요. 베타가 크다고 표준편차가 반드시 큰 것은 아니에요.","w":["시장이 자기 자신과 움직이는 정도라 1이에요.","SML에서 베타 0이면 위험 프리미엄이 없어요.","오를 땐 많이 따라 오르는 종목, 내릴 땐 덜 내리는 종목을 담는 거예요.",null],"k":"베타는 '파도(시장)에 얼마나 출렁이나'만 재고, 배 자체가 흔들리는 것(개별 위험)은 따로예요.","m":"베타 = 체계적 위험만, 총위험과는 별개","rev":0},{"s":3,"sec":"분산투자기법","star":3,"lv":"상","t":"상관계수로 구한 베타와 균형수익률","q":"무위험이자율 2%, 시장포트폴리오 기대수익률 10%, 시장 수익률 표준편차 20%이다. K주식의 표준편차는 30%이고 시장과의 상관계수는 0.6이다. CAPM에 따른 K주식의 균형기대수익률은?","o":["6.8%","9.2%","10.0%","14.0%"],"a":1,"c":"베타 = 상관계수 × (개별 표준편차 ÷ 시장 표준편차)로도 구할 수 있어요. 공분산 ÷ 시장분산과 같은 값이에요.","e":"베타 = 0.6 × 30 ÷ 20 = 0.9예요. 균형기대수익률 = 2% + 0.9 × (10% − 2%) = 9.2%예요.","w":["상관계수 0.6을 그대로 베타로 써서 2% + 0.6 × 8%로 계산한 값이에요.",null,"시장포트폴리오 기대수익률 그대로예요. 베타가 1일 때만 이렇게 돼요.","상관계수를 빼고 표준편차 비율(30 ÷ 20 = 1.5)만 베타로 써서 계산한 값이에요."],"k":"베타는 '얼마나 같이 움직이나(상관계수)'와 '얼마나 크게 움직이나(변동성 비율)'를 곱한 값이에요.","m":"β = ρ × σi ÷ σm","f":"β = ρ × σi ÷ σm = 0.9, E(R) = 2% + 0.9 × 8% = 9.2%","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"하","t":"리밸런싱과 업그레이딩의 구분","q":"〈보기〉의 ( ) 안에 들어갈 말을 순서대로 바르게 나열한 것은?\n〈보기〉 구성 종목의 가격이 변해 달라진 투자비율을 처음 비율로 되돌리는 것을 ( ㄱ )이라 하고, 새 정보를 반영해 위험 대비 기대수익이 더 나은 종목으로 바꿔 넣는 것을 ( ㄴ )이라 한다.","o":["ㄱ 업그레이딩 – ㄴ 리밸런싱","ㄱ 리밸런싱 – ㄴ 업그레이딩","ㄱ 리밸런싱 – ㄴ 시장투자적기포착","ㄱ 포뮬러 플랜 – ㄴ 업그레이딩"],"a":1,"c":"리밸런싱은 원래 포트폴리오의 성격을 지키는 활동이고, 업그레이딩은 더 나은 종목으로 바꿔 포트폴리오의 질을 높이는 활동이에요.","e":"비율을 처음대로 되돌리는 것은 리밸런싱, 위험 대비 기대수익이 좋아지도록 종목을 교체하는 것은 업그레이딩이에요.","w":["두 용어를 거꾸로 짝지었어요.",null,"시장투자적기포착은 주식펀드와 무위험자산의 비율을 시장 전망에 따라 바꾸는 전략이에요.","포뮬러 플랜은 정해진 규칙대로 주식·채권 비중을 바꾸는 기법이에요."],"k":"리밸런싱은 흐트러진 책상 정리, 업그레이딩은 낡은 물건을 더 좋은 것으로 바꾸는 거예요.","m":"리밸런싱 = 비율 원위치 / 업그레이딩 = 종목 교체","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"공분산 범위와 무차별곡선 기울기","q":"포트폴리오 선택의 기초 개념에 관한 〈보기〉의 설명 중 옳은 것은 모두 몇 개인가?\nㄱ. 공분산은 값의 범위가 정해져 있지 않지만, 공분산을 두 표준편차의 곱으로 나눈 상관계수는 −1과 +1 사이의 값을 가진다.\nㄴ. 두 자산의 상관계수가 0이어도 1보다 작으므로 분산투자 효과가 나타난다.\nㄷ. 보수적인 투자자일수록 위험을 한 단위 더 질 때 요구하는 추가 수익이 커서 무차별효용곡선의 기울기가 가파르다.\nㄹ. 효율적 투자선과 무차별효용곡선이 엇갈리며 만나는(교차하는) 지점이 그 투자자에게 가장 좋은 포트폴리오이다.","o":["1개","2개","3개","4개"],"a":2,"c":"효율적 투자선은 지배원리를 만족하는 포트폴리오의 집합이고, 그 위에서 어느 점을 고를지는 투자자의 무차별효용곡선이 정해요. 그래서 최적 포트폴리오는 투자자마다 달라요.","e":"ㄱ, ㄴ, ㄷ이 옳아 3개예요. ㄹ은 틀렸어요. 최적 포트폴리오는 두 곡선이 접하는 점이에요. 교차점에서는 더 위쪽 무차별곡선에 닿는 조합이 남아 있어 효용을 더 높일 수 있어요. 분산효과가 전혀 없는 것은 상관계수가 +1일 때뿐이에요.","w":["ㄱ, ㄴ, ㄷ 세 개가 옳아요.","ㄴ과 ㄷ도 옳아요.",null,"ㄹ은 틀렸어요. 교차가 아니라 접점이에요."],"k":"겁 많은 사람은 위험을 조금만 더 져도 보상을 많이 달라고 해서, 무차별곡선이 가파르게 솟아요.","m":"상관계수 −1~+1, ρ < 1이면 분산효과, 보수적일수록 무차별곡선 가파름, 최적 = 접점","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"상","t":"균형에서 베타 역산과 포트폴리오 베타","q":"CAPM이 성립하고 차익거래 기회가 없는 시장에서 무위험수익률은 2.5%이다. 자산 X의 베타는 0.9, 기대수익률은 8.8%이다. (ㄱ) 기대수익률이 11.6%인 자산 Y의 베타와 (ㄴ) X에 40%, Y에 35%, 무위험자산에 25%를 투자한 포트폴리오의 베타를 순서대로 짝지은 것은?","o":["1.66 — 1.065","1.66 — 0.815","1.30 — 0.815","1.30 — 1.065"],"a":2,"c":"균형에서는 모든 자산의 '위험프리미엄 ÷ 베타'(위험보상비율)가 같아요. 포트폴리오 베타는 구성 자산 베타의 가중평균이고, 무위험자산의 베타는 0이에요.","e":"위험보상비율 = (8.8% − 2.5%) ÷ 0.9 = 7.0%예요. Y의 베타 = (11.6% − 2.5%) ÷ 7.0% = 1.30이에요. 포트폴리오 베타 = 0.4 × 0.9 + 0.35 × 1.30 + 0.25 × 0 = 0.36 + 0.455 = 0.815예요.","f":"β_Y = (E(R_Y) − Rf) ÷ [(E(R_X) − Rf) ÷ β_X], β_P = Σ w × β","w":["무위험수익률 차감 누락과 무위험자산 베타 오류가 함께 있어요.","Y의 기대수익률에서 무위험수익률을 빼지 않고 11.6 ÷ 7.0으로 나눴어요.",null,"무위험자산의 베타를 1로 봐서 0.25를 더했어요. 무위험자산의 베타는 0이에요."],"k":"같은 시장에서는 위험 한 단위에 주는 값이 모두 같아서, 한 자산의 '시세'를 알면 다른 자산의 위험 크기를 거꾸로 알 수 있어요.","m":"균형: (E(R) − Rf) ÷ β 동일, 무위험자산 β = 0","rev":0},{"s":3,"sec":"분산투자기법","star":2,"lv":"중","t":"운용전략의 액티브·패시브 분류","q":"운용전략을 액티브·패시브와 자산배분·증권선택 기준으로 분류한 것 중 가장 적절하지 않은 것은?","o":["처음 산 종목을 매매하지 않고 계속 보유하는 단순매입·보유(바이앤홀드) — 패시브 운용","주가 등락과 상관없이 매달 같은 금액씩 사 모으는 평균분할투자 — 시장 평균을 이기려는 액티브 증권선택 전략","시장 국면 예상에 따라 주식펀드와 무위험자산의 비중을 조절하는 시장투자적기포착 — 액티브 자산배분 전략","기업의 내재가치를 추정해 잘못 매겨진 종목을 찾는 방법 — 액티브 증권선택 전략"],"a":1,"c":"시장 평균보다 나은 성과를 노리면 액티브, 평균을 그대로 따르면 패시브예요. 비중을 조절하는 대상이 주식·채권 같은 자산군이면 자산배분, 개별 종목이면 증권선택이에요. 통합적 포트폴리오 관리는 자산배분 → 증권선택 → 시점선택 순으로 진행해요.","e":"평균분할투자는 주가를 예측하지 않고 정해진 시기마다 같은 금액을 기계적으로 넣는 방법이라 패시브 운용에 속해요. 같은 금액으로 사므로 주가가 낮을 때 더 많은 주식을 사게 돼요.","w":["매매 없이 보유해 거래비용이 거의 없는 패시브 전략이에요.",null,"시장 흐름을 예측해 자산군 비중을 바꾸므로 액티브 자산배분이에요.","저평가 종목을 찾아 시장을 이기려는 액티브 증권선택이에요."],"k":"매달 같은 돈으로 사과를 사면 쌀 때 더 많이 사게 되지만, 이건 시세를 읽은 게 아니라 규칙대로 산 것뿐이에요.","m":"평균분할·바이앤홀드 = 패시브, 적기포착 = 액티브 자산배분","rev":0},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"국세 부과처분에 불복하는 납세자가 이의신청을 거치지 않고 바로 심사청구를 하려고 한다. 심사청구를 제기하는 곳과 그 기한을 바르게 짝지은 것은?","o":["국세청 – 처분이 있음을 안 날부터 90일 이내","조세심판원 – 처분이 있음을 안 날부터 90일 이내","국세청 – 처분이 있음을 안 날부터 180일 이내","관할 세무서 – 처분이 있음을 안 날부터 30일 이내"],"a":0,"c":"조세불복은 이의신청(선택), 심사청구 또는 심판청구(택일), 행정소송 순서예요. 절차마다 맡는 기관이 달라요. 이의신청은 세무서나 지방국세청, 심사청구는 국세청, 심판청구는 조세심판원이 맡아요.","e":"심사청구는 국세청에 제기하고, 처분이 있음을 안 날(처분 통지를 받은 날)부터 90일 이내에 해야 해요.","w":[null,"조세심판원에 내는 것은 심판청구예요. 심사청구는 국세청이 맡아요.","불복 청구기간은 180일이 아니라 90일이에요.","심사청구는 세무서가 아니라 국세청에 제기하고, 기한도 30일이 아니라 90일이에요."],"m":"이의신청 = 세무서·지방국세청 · 심사청구 = 국세청 · 심판청구 = 조세심판원 · 모두 안 날부터 90일","t":"심사청구의 제기 기관과 기한","k":"같은 불만이라도 어느 창구에 내느냐가 정해져 있어요. 심사는 국세청 창구, 심판은 조세심판원 창구이고, 마감은 둘 다 90일이에요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"소득세법상 배당소득으로 과세되지 않는 것은?","o":["경영에 참여하지 않고 출자만 한 공동사업자가 받는 손익분배금","직장공제회에서 받은 초과반환금","국내 적격 집합투자기구로부터 받은 이익","법인이 감자를 하면서 주주에게 준 금전이 주식 취득가액을 넘는 금액(의제배당)"],"a":1,"c":"이름에 '배당'이나 '이익'이 들어가는지보다 그 소득이 무엇에서 생겼는지가 기준이에요. 회사·펀드에 출자해서 받는 몫은 배당소득, 돈을 맡기거나 빌려주고 받는 대가는 이자소득이에요.","e":"직장공제회 초과반환금은 회원이 낸 돈보다 더 돌려받는 금액으로, 돈을 맡기고 받는 대가라서 이자소득이에요. 그래서 무조건 분리과세되는 이자소득으로 분류해요.","w":["출자만 하고 경영에 참여하지 않는 출자공동사업자의 손익분배금은 배당소득이에요.",null,"적격 집합투자기구(펀드)로부터 받은 이익은 배당소득이에요.","감자·해산·합병 등으로 생기는 의제배당은 배당소득이에요."],"m":"직장공제회 초과반환금 = 이자소득(무조건 분리과세) · 출자공동사업자 분배금·의제배당·펀드 이익 = 배당소득","t":"배당소득과 이자소득의 구분","k":"공제회는 회원이 맡긴 돈을 불려서 돌려주는 곳이라 은행 이자처럼 봐요. 회사 주인 몫을 나눠 받는 배당과는 달라요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"거주자가 국내 적격 집합투자기구(펀드)로부터 받는 이익을 계산할 때, 과세 대상 이익에서 빠지는 것은?","o":["펀드가 보유한 채권에서 받은 이자","펀드가 상장 채권을 팔아 얻은 매매차익","펀드가 비상장주식을 팔아 얻은 차익","펀드가 상장주식을 기초자산으로 하는 장내파생상품(주식선물 등)을 거래해 얻은 이익"],"a":3,"c":"펀드 이익은 원칙적으로 모두 배당소득으로 과세하지만, 개인이 직접 투자했어도 과세되지 않았을 손익은 빼고 계산해요. 증권시장에 상장된 증권(채권 등은 제외), 그 증권을 기초로 하는 장내파생상품, 벤처기업 주식의 매매·평가손익이 여기에 해당해요.","e":"상장증권을 대상으로 하는 장내파생상품의 거래이익은 상장주식 매매차익처럼 과세 대상 이익에서 빠져요.","w":["채권 이자는 펀드 이익에 포함되어 배당소득으로 과세돼요.","상장 채권의 매매차익은 제외 대상에서 빠져 있어서 과세 대상 이익에 들어가요.","비상장주식 매매차익은 제외 대상이 아니라서 과세 대상 이익에 들어가요.",null],"m":"펀드 이익에서 제외: 상장증권(채권 등 제외)·그 증권을 기초로 한 장내파생상품·벤처기업 주식의 매매·평가손익 / 포함: 이자·배당·채권 매매차익·비상장주식 차익","t":"적격 집합투자기구 이익의 과세 범위","k":"직접 샀어도 세금이 없었을 이익(상장주식 차익, 그와 연결된 장내파생 이익)은 펀드를 통해 벌어도 세금을 매기지 않아요."},{"s":1,"sec":"세제관련 법규/세무전략","star":3,"lv":"중","rev":0,"q":"2026년 거주자의 양도소득에 적용되는 세율(지방소득세 제외)을 바르게 연결한 것은?","o":["국내 장내파생상품(코스피200 선물 등)의 양도차익 – 10%","중소기업 외 법인의 대주주가 1년 미만 보유한 주식을 판 경우 – 20%","중소기업 주식을 장외에서 판 소액주주 – 20%","중소기업 외 법인의 비상장주식을 판 소액주주 – 10%"],"a":0,"c":"주식 양도소득세율은 대주주 여부, 중소기업 여부, 보유기간에 따라 달라요. 파생상품은 법정 기본세율 20%이지만 시행령에서 탄력세율 10%를 적용해요.","e":"파생상품 양도소득은 기본세율이 20%이지만 탄력세율 10%가 적용돼요.","w":[null,"중소기업 외 법인의 대주주가 1년 미만 보유한 주식을 팔면 30%예요.","중소기업 주식을 판 소액주주는 10%예요.","중소기업 외 법인 주식을 판 소액주주는 20%예요."],"m":"소액주주: 중소기업 10% · 그 외 20% / 대주주: 중소기업 외 1년 미만 30% · 그 밖에는 과세표준 3억 이하 20%·초과 25% / 파생상품: 탄력세율 10%(기본 20%)","t":"주식·파생상품 양도소득세율","k":"작은 회사 주식을 조금 가진 사람은 10%, 큰 회사 주식은 20%, 큰손이 짧게 사고팔면 30%예요. 파생상품은 법에는 20%라고 써 있지만 실제로는 10%만 매겨요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"의제배당의 수입시기를 바르게 연결한 것은?","o":["법인 해산으로 생긴 의제배당 – 해산을 결의한 날","감자로 생긴 의제배당 – 자본 감소를 결의한 날","합병으로 생긴 의제배당 – 합병계약을 맺은 날","분할로 생긴 의제배당 – 분할계획서를 작성한 날"],"a":1,"c":"의제배당은 법적으로는 배당이 아니지만 실질이 배당과 같아 배당으로 보는 소득이에요. 수입시기는 그 소득을 받을 권리가 확정되는 날로 정해요.","e":"감자로 생긴 의제배당은 자본 감소를 결의한 날이 수입시기예요.","w":["해산 의제배당은 해산 결의일이 아니라 잔여재산의 가액이 확정된 날이 수입시기예요.",null,"합병 의제배당은 합병계약일이 아니라 합병등기를 한 날이 수입시기예요.","분할 의제배당은 분할등기를 한 날이 수입시기예요."],"m":"의제배당 수입시기: 감자·잉여금 자본전입 = 결의일 · 해산 = 잔여재산가액 확정일 · 합병·분할 = 등기일","t":"의제배당의 수입시기","k":"자본을 줄이는 건 주주총회에서 정하는 순간 권리가 생기고, 회사 문을 닫는 건 남은 재산이 얼마인지 정해져야 몫을 알 수 있어요."},{"s":1,"sec":"세제관련 법규/세무전략","star":2,"lv":"중","rev":0,"q":"국세 납부의무에 관한 설명으로 가장 적절하지 않은 것은?","o":["납부할 국세를 환급금과 상계(충당)하면 그 범위에서 납부의무가 소멸한다","국세징수권의 소멸시효가 완성되면 납부의무가 소멸한다","국세를 부과할 수 있는 제척기간이 끝나면 납부의무가 소멸한다","세무서장이 독촉장을 보내 납부를 재촉하면 그 국세의 납부의무가 소멸한다"],"a":3,"c":"납부의무 소멸 사유는 납부·충당·부과 취소·제척기간 만료·징수권 소멸시효 완성이에요. 반면 납부고지·독촉·교부청구·압류는 소멸시효를 처음부터 다시 진행시키는 중단 사유예요.","e":"독촉(납부 재촉)은 소멸시효를 중단시키는 사유일 뿐이에요. 납부의무가 사라지기는커녕 시효가 처음부터 다시 진행돼요.","w":["환급금을 체납세액에 충당하면 그만큼 납부한 것과 같아서 소멸 사유예요.","징수권 소멸시효가 완성되면 납부의무가 소멸해요.","부과 제척기간이 끝나면 더 이상 부과할 수 없어 납부의무가 소멸해요.",null],"m":"소멸 \"납·충·취·제·시\" / 시효 중단 \"고·독·교·압\"(납부고지·독촉·교부청구·압류) — 독촉은 소멸이 아니라 중단","t":"소멸시효 중단 사유와 소멸 사유의 구분","k":"세무서가 '세금 내세요' 하고 다시 재촉하면 빚이 없어지는 게 아니라 시계가 0으로 돌아가요."},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"q":"ISA(개인종합자산관리계좌)의 운용 유형에 관한 설명으로 가장 적절하지 않은 것은?","o":["중개형 ISA에서도 은행 정기예금에 투자할 수 있다","중개형 ISA는 투자자가 국내 상장주식을 직접 사고팔 수 있다","일임형 ISA는 금융회사가 제시한 모델 포트폴리오에 따라 운용을 맡긴다","신탁형 ISA는 투자자가 상품을 직접 지시하며, 예금을 담을 수 있다"],"a":0,"c":"ISA는 운용 방식에 따라 신탁형·일임형·중개형으로 나뉘어요. 유형마다 담을 수 있는 상품이 달라요.","e":"중개형 ISA는 증권사 계좌에서 주식·펀드·ETF 등을 직접 고르는 방식이라 예금을 담을 수 없어요. 예금을 담으려면 신탁형을 골라야 해요.","w":[null,"중개형은 국내 상장주식을 직접 매매할 수 있는 유형이에요.","일임형은 금융회사가 모델 포트폴리오로 운용해 줘요.","신탁형은 투자자가 상품을 지정하고, 예금도 편입할 수 있어요."],"m":"ISA 유형: 신탁형(직접 지시·예금 O) · 일임형(모델 포트폴리오 위탁) · 중개형(직접 매매·국내주식 O·예금 X)","t":"ISA 유형별 편입 상품","k":"중개형 ISA는 증권사 매장이라 예금 코너가 없어요. 예금을 사려면 신탁형 매장으로 가야 해요."},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"q":"증권회사에 맡긴 다음 돈 가운데 예금자보호법에 따른 보호 대상이 아닌 것은?","o":["주식을 사려고 위탁계좌에 넣어 두고 아직 쓰지 않은 현금 예탁금","공모주 청약을 하려고 증권사에 미리 넣어 둔 청약자예수금","증권사 IRP(개인형 퇴직연금) 계좌에 운용 지시 없이 현금으로 남아 있는 적립금","증권사 연금저축 계좌에 매수 대기로 남아 있는 현금"],"a":1,"c":"증권회사에서는 고객 계좌에 현금으로 남아 있는 투자자예탁금 등이 보호 대상이에요. 다만 청약자예수금·제세금예수금·선물옵션 예수금처럼 법령에서 따로 뺀 예수금은 보호하지 않아요.","e":"청약자예수금은 예금자보호법에서 보호 대상에서 따로 뺀 예수금이에요. 같은 증권사 현금이라도 청약용으로 넣어 둔 돈은 보호받지 못해요.","w":["위탁계좌에 현금으로 남아 있는 투자자예탁금은 보호 대상이에요.",null,"퇴직연금 계좌에 현금으로 남아 있는 적립금은 보호 대상이에요.","연금저축 계좌 안에 현금으로 남아 있는 돈도 보호 대상이에요."],"m":"증권사 보호 O: 현금 투자자예탁금 · 퇴직연금·연금저축 계좌 안의 현금 / X: 청약자예수금 · 제세금예수금 · 선물옵션 예수금 · RP · ELS · 펀드","t":"증권회사 예수금의 예금자보호","k":"증권 계좌에 놀고 있는 현금은 보호받지만, 청약하려고 따로 넣어 둔 돈은 보호 바구니 밖에 있어요."},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"q":"주식워런트증권(ELW)의 거래소 매매제도에 관한 설명으로 가장 적절한 것은?","o":["유동성공급자(LP)를 두지 않고 투자자끼리만 호가를 낸다","투자자는 시장가 주문으로도 매매할 수 있다","1증권 단위로 사고팔 수 있다","가격 변동성이 커서 가격제한폭을 적용하지 않는다"],"a":3,"c":"ELW는 거래소에 상장되어 주식처럼 사고팔지만, 가격이 크게 움직이는 상품이라 별도의 매매 규칙이 있어요.","e":"ELW는 적은 돈으로 큰 손익이 나는 상품이라 가격이 크게 출렁여요. 그래서 가격제한폭을 적용하지 않아요.","w":["ELW는 종목마다 유동성공급자(LP)가 매수·매도 호가를 내서 거래가 이뤄지게 도와요.","ELW는 지정가 주문만 허용되고 시장가 주문은 낼 수 없어요.","거래단위는 1증권이 아니라 10증권이에요.",null],"m":"ELW 매매: 10증권 단위 · 지정가 주문만 · 가격제한폭 없음 · LP 호가 제시","t":"ELW의 매매제도","k":"ELW는 롤러코스터 같은 상품이라 속도 제한(가격제한폭)이 없어요. 대신 가격을 꼭 정해서 주문해야 하고, 10장 묶음으로만 사고팔아요."},{"s":1,"sec":"금융상품","star":3,"lv":"중","rev":0,"q":"만 57세인 거주자 정은 연금저축계좌에서 연금을 받고 있으며 올해가 연금수령연차 2년차이다. 올해 1월 1일 현재 계좌 평가액이 1억 8,000만원일 때 올해의 연금수령한도는?","o":["2,000만원","2,160만원","2,400만원","2,700만원"],"a":2,"c":"연금계좌에서 한도 안에서 꺼내야 연금수령으로 인정되어 낮은 연금소득세율이 적용돼요. 한도는 연금수령연차가 늘수록 커지고, 11년차부터는 한도가 없어요.","e":"1억 8,000만원 ÷ (11 − 2) × 120% = 2,400만원이에요. 이 금액을 넘겨 꺼낸 부분은 연금외수령으로 봐요.","w":["120%를 곱하지 않은 값이에요(1억 8,000만 ÷ 9).","분모를 연차와 관계없이 10으로 잡은 값이에요(1억 8,000만 ÷ 10 × 120%).",null,"분모를 (11 − 연차 − 1) = 8로 잘못 잡은 값이에요."],"m":"연금수령한도 = 평가액 ÷ (11 − 연금수령연차) × 120% · 11년차부터 한도 없음","t":"연금수령한도 계산","k":"연금 금고에서 한 해에 꺼낼 수 있는 양을 '남은 해 수'로 나누고 20%를 덤으로 얹어 줘요. 해가 갈수록 나누는 수가 작아져 한도가 커져요.","f":"1억 8,000만 ÷ (11 − 2) × 1.2 = 2,000만 × 1.2 = 2,400만원"},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"q":"한국주택금융공사의 주택연금에서 가입자가 받을 수 있는 대출한도(월지급금 규모)를 정하는 핵심 요소로 가장 적절한 것은?","o":["담보 주택의 가격과 가입자의 연령","가입자의 연소득과 신용등급","가입자의 부양가족 수","담보 주택을 보유해 온 기간"],"a":0,"c":"주택연금은 소득 심사를 하는 대출이 아니라, 집을 담보로 평생 연금을 주는 역모기지예요. 그래서 담보 가치와 앞으로 연금을 얼마나 오래 줄지가 핵심이에요.","e":"대출한도는 주택가격과 가입자 연령(부부 중 나이가 적은 사람 기준)으로 정해요. 집값이 높을수록, 나이가 많을수록 월지급금이 커져요.","w":[null,"주택연금은 소득이나 신용으로 한도를 정하지 않아요.","부양가족 수는 한도와 관계없어요.","주택을 얼마나 오래 가졌는지는 한도를 정하는 요소가 아니에요."],"m":"주택연금 한도 = 주택가격 + 가입자 연령(부부 중 연소자) · 소득·신용 심사 X · 비소구","t":"주택연금 지급액의 결정 요인","k":"집값이 비쌀수록, 그리고 연금을 받을 날이 짧게 남은(나이 많은) 사람일수록 한 달에 받는 돈이 커져요."},{"s":1,"sec":"금융상품","star":2,"lv":"중","rev":0,"q":"금전신탁을 특정금전신탁과 불특정금전신탁으로 나누는 기준으로 가장 적절한 것은?","o":["신탁 기간이 1년 이상인지 여부","위탁자가 신탁재산의 운용방법을 지정하는지 여부","수익자가 위탁자 자신인지 다른 사람인지 여부","맡기는 재산이 금전인지 금전 이외의 재산인지 여부"],"a":1,"c":"금전신탁은 맡긴 돈을 누가 어떻게 굴릴지를 정하는 방식에 따라 나뉘어요.","e":"위탁자가 운용방법을 지정하면 특정금전신탁, 지정하지 않고 수탁자에게 맡기면 불특정금전신탁이에요.","w":["신탁 기간은 두 신탁을 나누는 기준이 아니에요.",null,"수익자가 누구인지는 자익신탁과 타익신탁을 나누는 기준이에요.","금전인지 아닌지는 금전신탁과 재산신탁을 나누는 기준이에요."],"m":"특정 = 위탁자가 운용방법 지정 / 불특정 = 수탁자 재량 · 자익·타익 = 수익자 기준 · 금전·재산신탁 = 맡긴 재산 기준","t":"특정금전신탁과 불특정금전신탁의 구분 기준","k":"식당에서 메뉴를 내가 고르면 특정, '알아서 주세요' 하면 불특정이에요."},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"q":"부동산 등기의 효력에 관한 설명으로 가장 적절한 것은?","o":["가등기만 해 두어도 그때 바로 소유권이 이전된다","본등기에는 순위를 정하는 효력이 없고 가등기에만 있다","우리 법은 등기의 공신력을 인정하므로 등기부를 믿고 산 사람은 언제나 소유권을 얻는다","가등기를 한 뒤 본등기를 하면 본등기의 순위는 가등기를 한 때를 기준으로 정해진다"],"a":3,"c":"등기는 정식으로 권리 변동을 일으키는 본등기와, 나중의 본등기 순위를 미리 확보해 두는 가등기로 나뉘어요.","e":"가등기는 순위를 지켜 주는 효력(순위보전적 효력)이 있어요. 나중에 본등기를 하면 그 순위가 가등기를 한 때로 올라가요.","w":["가등기만으로는 물권 변동이 일어나지 않아요. 본등기를 해야 소유권이 넘어가요.","본등기에도 순위확정적 효력이 있어요. 가등기의 고유한 효력은 순위보전이에요.","우리 법은 등기의 공신력을 인정하지 않아요. 등기부가 실제와 다르면 믿고 산 사람도 보호받지 못할 수 있어요.",null],"m":"본등기: 물권변동·순위확정·대항력 등 / 가등기: 순위보전적 효력(본등기 시 가등기 때로 순위 소급) · 등기 공신력 X","t":"가등기와 본등기의 효력","k":"가등기는 식당 대기표예요. 대기표만으로 밥을 먹을 순 없지만, 나중에 자리에 앉을 때 받은 순서대로 앉게 해 줘요."},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"q":"어느 부동산 개발사업의 미래 현금유입 현재가치 합계가 88억원이고 수익성지수(PI)가 1.1이다. 이 사업의 초기 투자액과 순현재가치(NPV)를 바르게 짝지은 것은?","o":["초기 투자액 80억원 – NPV 8억원","초기 투자액 80억원 – NPV 88억원","초기 투자액 96.8억원 – NPV −8.8억원","초기 투자액 8억원 – NPV 80억원"],"a":0,"c":"수익성지수는 현금유입의 현재가치를 초기 투자액(현금유출의 현재가치)으로 나눈 값이에요. 그래서 둘 중 두 값을 알면 나머지 하나를 거꾸로 구할 수 있어요.","e":"초기 투자액 = 88억 ÷ 1.1 = 80억원이고, NPV = 88억 − 80억 = 8억원이에요. PI가 1보다 크니 NPV도 양수예요.","w":[null,"투자액은 맞지만 NPV를 현금유입 현재가치 그대로 적었어요.","PI로 나누지 않고 곱했어요(88 × 1.1 = 96.8).","투자액과 NPV를 뒤바꿔 적었어요."],"m":"PI = 유입 PV ÷ 투자액 → 투자액 = 유입 PV ÷ PI · NPV = 유입 PV − 투자액","t":"수익성지수로 초기 투자액 역산","k":"88억을 돌려받는데 그게 낸 돈의 1.1배라면, 낸 돈은 80억이고 8억이 남는 장사예요.","f":"투자액 = 88 ÷ 1.1 = 80억원 · NPV = 88 − 80 = 8억원"},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"q":"주택저당증권(MBS)의 위험에 관한 설명으로 가장 적절한 것은?","o":["시장금리가 오르면 차입자들이 대출을 서둘러 갚아 조기상환이 늘어난다","시장금리가 떨어지면 차입자들이 더 싼 대출로 갈아타 조기상환이 늘고, 투자자는 조기상환위험에 노출된다","조기상환이 늘면 투자자는 받은 원금을 더 높은 금리로 다시 굴릴 수 있어 유리하다","MBS의 현금흐름은 국채처럼 만기까지 확정되어 있다"],"a":1,"c":"MBS는 주택담보대출의 원리금으로 투자자에게 돈을 줘요. 차입자는 언제든 대출을 미리 갚을 수 있어서 투자자가 받는 현금흐름이 바뀔 수 있어요.","e":"금리가 떨어지면 차입자들이 낮은 금리로 대출을 갈아타면서 기존 대출을 일찍 갚아요. 투자자는 원금을 예상보다 일찍 돌려받아 더 낮은 금리로 다시 굴려야 해요.","w":["금리가 오르면 갈아탈 이유가 없어 조기상환은 오히려 줄어요.",null,"조기상환은 주로 금리가 낮을 때 늘어나서, 투자자는 받은 돈을 더 낮은 금리로 다시 굴려야 해요.","조기상환 때문에 MBS 현금흐름은 불확실해요."],"m":"MBS: 금리↓ → 대환 → 조기상환↑ → 재투자위험 · 현금흐름 불확실 → 국채보다 높은 수익률","t":"MBS의 조기상환위험과 금리","k":"대출 금리가 내려가면 사람들이 비싼 옛 대출을 갚고 싼 새 대출로 바꿔요. 그러면 MBS 투자자는 이자를 오래 받으려던 계획이 깨져요."},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"q":"국토계획법상 특별시장·광역시장·시장·군수의 개발행위허가를 받지 않아도 되는 것은? (도시·군계획사업에 따른 행위는 아니다)","o":["건축물을 새로 짓는 행위","토석을 채취하는 행위","녹지지역에 물건을 1개월 이상 쌓아 두는 행위","경작을 위해 토지의 형질을 변경하는 행위"],"a":3,"c":"개발행위허가는 계획 없는 개발을 막으려는 제도예요. 건축물 건축·공작물 설치, 토지 형질변경, 토석 채취, 토지 분할, 일정 지역의 물건 적치가 허가 대상이에요. 다만 경작을 위한 형질변경처럼 영향이 작은 행위는 빠져요.","e":"토지 형질변경은 허가 대상이지만, 경작을 위한 형질변경은 예외라서 허가 없이 할 수 있어요.","w":["건축물의 건축은 개발행위허가 대상이에요.","토석 채취는 개발행위허가 대상이에요.","녹지·관리·자연환경보전지역에 물건을 1개월 이상 쌓아 두려면 허가를 받아야 해요.",null],"m":"개발행위허가 대상: 건축·공작물 · 형질변경(경작용 제외) · 토석채취 · 토지분할 · 물건 적치 / 예외: 경작용 형질변경 · 도시·군계획사업","t":"개발행위허가가 필요 없는 행위","k":"밭을 갈려고 흙을 고르는 정도는 농사일이라 허락 없이 해도 되지만, 건물을 짓거나 흙을 퍼 가는 건 허락이 필요해요."},{"s":1,"sec":"부동산관련 상품","star":3,"lv":"중","rev":0,"q":"〈보기〉에서 설명하는 지주공동사업 방식으로 가장 적절한 것은?\n〈보기〉 토지 소유자는 토지 소유권을 그대로 가진 채 개발업자에게 기획·설계·시공·임대 등 사업 전반을 맡기고 수수료를 준다. 개발업자는 완공된 건물을 통째로 빌려 운영하면서 토지 소유자에게 일정한 임대료를 보장해 준다.","o":["사업수탁방식","토지신탁방식","등가교환방식","차지방식"],"a":0,"c":"지주공동사업은 토지 소유자가 개발업자·신탁회사 등과 손잡고 땅을 개발하는 방식이에요. 소유권을 누가 갖는지, 이익을 어떻게 나누는지로 방식을 구분해요.","e":"토지 소유자가 소유권을 유지하고 개발업자가 사업을 대행하며, 완공 후 건물을 일괄 임차해 사업수지를 사실상 보증하는 것은 사업수탁방식이에요.","w":[null,"토지신탁방식은 토지를 신탁회사에 신탁해 소유권이 신탁회사로 넘어가요.","등가교환방식은 토지와 건축비를 낸 비율대로 완공된 부동산을 나눠 가져요.","차지방식은 토지를 빌려주고 지대를 받는 방식으로, 개발업자가 건물을 소유해요."],"m":"사업수탁 = 소유권 유지 + 개발업자 대행·수수료 + 일괄 임차로 수지 보증 · 등가교환 = 비율대로 나눔 · 토지신탁 = 신탁사로 소유권 이전 · 차지 = 땅 빌려주고 지대","t":"지주공동사업의 사업수탁방식","k":"땅 주인은 '내 땅은 그대로 두고 알아서 지어서 운영해 줘, 월세만 꼬박꼬박 보장해 줘'라고 맡기는 셈이에요."},{"s":1,"sec":"부동산관련 상품","star":2,"lv":"중","rev":0,"q":"국토계획법상 도시지역 안의 용도지역별 용적률 최대한도가 높은 것부터 바르게 나열한 것은?","o":["주거지역 > 상업지역 > 공업지역 > 녹지지역","상업지역 > 주거지역 > 공업지역 > 녹지지역","상업지역 > 공업지역 > 주거지역 > 녹지지역","상업지역 > 주거지역 > 녹지지역 > 공업지역"],"a":1,"c":"용적률은 대지면적에 대한 건축물 지상층 연면적의 비율이에요. 도심 기능이 강한 지역일수록 높게, 자연을 지켜야 하는 지역일수록 낮게 정해요.","e":"법상 최대한도는 상업지역 1,500%, 주거지역 500%, 공업지역 400%, 녹지지역 100%라서 상업 > 주거 > 공업 > 녹지 순이에요.","w":["상업지역이 주거지역보다 높아요.",null,"주거지역(500%)이 공업지역(400%)보다 높아요.","공업지역(400%)이 녹지지역(100%)보다 높아요."],"m":"용적률 최대한도: 상업 1,500% > 주거 500% > 공업 400% > 녹지 100% (\"상·주·공·녹\")","t":"용도지역 대분류별 용적률 순서","k":"사람이 가장 많이 모이는 도심 상가가 가장 높이 쌓고, 숲과 들을 지키는 녹지가 가장 낮게 지어요."},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"다음 중 대안투자상품으로 보기 어려운 것은?","o":["실물 부동산이나 부동산 대출에 투자하는 부동산펀드","단기 국공채·어음 등에 투자하는 MMF(단기금융집합투자기구)","금·원유 같은 실물 상품이나 상품선물에 투자하는 일반상품펀드","비상장 기업 지분을 사들여 가치를 높인 뒤 되파는 PEF"],"a":1,"c":"대안투자는 주식·채권·현금성 자산 같은 전통 자산 밖의 투자예요. 부동산, 일반상품(원자재), 헤지펀드, PEF, 인프라 등이 대표적이에요.","e":"MMF는 만기가 짧은 국공채·어음·예금 등에 투자하는 단기금융상품이라 전통적인 현금성 자산 운용에 속해요. 대안투자상품이 아니에요.","w":["부동산펀드는 대표적인 대안투자상품이에요.",null,"원자재 같은 일반상품에 투자하는 펀드도 대안투자예요.","PEF는 사모 형태의 대표적인 대안투자예요."],"m":"대안투자 = 부동산 · 일반상품 · 헤지펀드 · PEF · 인프라 / MMF는 전통(현금성) 자산","t":"대안투자상품의 범위","k":"MMF는 '잠깐 맡겨 두는 지갑'이고, 대안투자는 '전통 자산 밖의 오래 묵히는 투자'예요."},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"어느 상가건물에서 해마다 얻는 순영업소득이 6억원이고, 시장에서 쓰는 자본환원율은 연 7.5%이다. 직접환원법으로 구한 이 건물의 수익가치는?","o":["45억원","74억원","80억원","86억원"],"a":2,"c":"직접환원법은 한 해의 순수익을 자본환원율(환원이율)로 나눠 부동산의 수익가치를 구해요.","e":"수익가치 = 6억원 ÷ 0.075 = 80억원이에요. 자본환원율이 낮을수록(같은 순수익이면) 수익가치는 높아져요.","w":["순영업소득에 자본환원율 숫자 7.5를 곱했어요. 나눠야 해요.","80억원에서 한 해 순수익 6억원을 뺐어요. 나눈 값 그대로가 수익가치예요.",null,"80억원에 한 해 순수익 6억원을 더했어요. 나눈 값 그대로가 수익가치예요."],"m":"수익가치 = 순영업소득 ÷ 자본환원율 · Cap rate↓ → 가치↑","t":"직접환원법 수익가치 계산","k":"해마다 6억원을 주는 건물이 7.5% 수익률에 맞으려면 값이 80억원이어야 해요.","f":"6 ÷ 0.075 = 80억원"},{"s":2,"sec":"대안투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"부동산 프로젝트 파이낸싱(PF)의 일반적인 구조에 관한 설명으로 가장 적절한 것은?","o":["대출 심사는 사업주의 신용과 담보 가치만 보고, 사업 자체의 수익성은 따지지 않는다","사업이 실패하면 대주는 사업주의 다른 재산 전부에 대해 제한 없이 상환을 청구할 수 있다","대출금은 그 사업에서 나올 미래 현금흐름으로 갚으며, 원칙적으로 출자자에게 상환을 청구하지 못하는 비소구(또는 제한소구) 금융이다","PF 대출은 반드시 사업주 회사의 재무상태표에 부채로 잡혀 사업주의 부채비율을 높인다"],"a":2,"c":"PF는 특정 개발사업을 따로 떼어 내 그 사업의 현금흐름을 상환 재원으로 삼는 금융이에요. 보통 사업을 위한 별도 회사(SPC)를 세워 돈을 빌려요.","e":"PF 대주는 사업에서 나올 분양대금·임대료 같은 미래 현금흐름을 보고 돈을 빌려줘요. 그래서 출자자나 사업주에게는 원칙적으로 상환을 청구할 수 없거나 일부만 청구할 수 있어요(비소구·제한소구).","w":["PF는 사업주 신용보다 사업 자체의 현금흐름과 사업성을 중심으로 심사해요.","무제한 상환청구는 일반 기업대출의 특징이에요. PF는 비소구 또는 제한소구가 원칙이에요.",null,"별도 회사(SPC)가 차입하므로 사업주 재무상태표에 잡히지 않는 부외금융 효과가 있어요."],"m":"PF = 사업 현금흐름으로 상환 · 비소구·제한소구 · 사업성 심사 · 부외금융","t":"부동산 PF의 비소구 구조","k":"PF는 '이 건물이 벌 돈'을 믿고 빌려주는 돈이라, 건물주 개인 지갑까지 뒤지지는 못해요."},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"q":"무상증자 이벤트 전략에 관한 설명으로 가장 적절하지 않은 것은?","o":["권리락일에 주가가 이론상 조정된 가격보다 높게 형성되는 착시 현상을 노린다","주식을 빌려 보유 물량을 늘려 두었다가 권리락일에 주가가 오르면 빌린 물량까지 함께 판다","신주를 받는 날에 받은 신주로 빌린 주식을 갚는다","무상증자 비율이 낮을수록 권리락일 착시에 따른 주가 상승 효과가 커진다"],"a":3,"c":"무상증자를 하면 권리락일에 주식 수가 늘어난 만큼 기준가격이 낮아져요. 이때 주가가 싸 보이는 착시로 이론가격보다 높게 거래되는 경우가 많은데, 이를 이용하는 이벤트 전략이에요.","e":"무상증자 비율이 높을수록 권리락으로 기준가격이 크게 낮아져 '싸 보이는' 착시가 커지고, 권리락일 주가 상승 효과도 커지는 경향이 있어요.","w":["권리락일 착시에 따른 초과 상승이 이 전략의 수익원이에요.","빌린 주식까지 팔아 권리락일 상승분을 더 크게 얻어요.","나중에 받는 신주로 빌린 주식을 갚아 포지션을 정리해요.",null],"m":"무상증자 이벤트: 권리락일 착시 상승 이용 · 대차로 물량 확대 → 권리락일 매도 → 신주로 상환 · 증자비율↑ → 착시↑","t":"무상증자 이벤트 전략","k":"1만원짜리가 무상증자로 5천원으로 바뀌면 '반값 세일'처럼 보여 사람들이 몰려요. 할인 폭이 클수록 더 몰려요."},{"s":2,"sec":"대안투자운용/투자전략","star":2,"lv":"중","rev":0,"q":"전환사채 차익거래 전략에서 상대적으로 선호하는 전환사채로 가장 적절한 것은?","o":["전환프리미엄이 높게 붙어 있는 전환사채","발행 당시 내재변동성이 낮게 책정되어 옵션 가치에 비해 싸게 살 수 있는 전환사채","배당을 많이 주는 주식으로 바꿀 수 있는 전환사채","거래가 드물어 유동성이 낮은 전환사채"],"a":1,"c":"전환사채 차익거래는 저평가된 전환사채를 사고 기초주식을 공매도해, 주가 방향 위험은 줄이고 가격 차이와 변동성에서 수익을 얻는 전략이에요.","e":"전환사채에 들어 있는 전환권(옵션)이 낮은 내재변동성으로 값이 매겨져 발행되면, 실제 변동성 대비 옵션을 싸게 사는 셈이라 차익거래자에게 유리해요.","w":["전환프리미엄이 높으면 주식 가치보다 웃돈을 많이 얹어 사야 해서 불리해요. 낮을수록 선호해요.",null,"공매도한 주식의 배당은 공매도자가 물어줘야 하므로 배당이 낮은 주식을 선호해요.","포지션을 쉽게 정리할 수 있도록 유동성이 높은 전환사채를 선호해요."],"m":"CB 차익 선호: 낮은 내재변동성 발행 · 낮은 전환프리미엄 · 저배당 · 고유동성 · 높은 볼록성","t":"전환사채 차익거래와 내재변동성","k":"옵션이 '할인 가격표(낮은 내재변동성)'를 달고 나왔을 때 사 두는 게 이득이에요."},{"s":2,"sec":"해외증권투자운용/투자전략","star":2,"lv":"중","rev":0,"q":"국제분산투자의 위험 감소 효과에 관한 설명으로 가장 적절한 것은?","o":["투자 국가 수를 충분히 늘리면 포트폴리오 위험을 0까지 낮출 수 있다","한 나라 안에서 생기는 체계적 위험은 국제분산으로도 전혀 줄일 수 없다","여러 나라에 나눠 투자해도 세계 경기 침체처럼 모든 시장에 함께 영향을 주는 세계 공통 위험은 없앨 수 없다","국가 간 수익률 상관관계가 높을수록 국제분산의 위험 감소 효과가 커진다"],"a":2,"c":"국내 분산투자로는 국내 시장 전체에 영향을 주는 체계적 위험이 남아요. 국제분산은 이 국내 체계적 위험의 일부를 다른 나라 자산으로 줄여 줘요.","e":"국제분산으로 나라별 고유 위험은 줄일 수 있지만, 세계 시장에 공통으로 영향을 주는 위험은 아무리 나라를 늘려도 남아요.","w":["세계 공통 위험이 남기 때문에 위험이 0이 되지는 않아요.","한 나라의 체계적 위험도 다른 나라 시장에서는 고유 위험이라 국제분산으로 일부 줄일 수 있어요.",null,"상관관계가 낮을수록 분산효과가 커요."],"m":"국제분산: 국가 고유 위험·국내 체계적 위험 일부↓ · 세계 공통 위험은 제거 불가 · 상관↓ → 효과↑","t":"국제분산투자로 줄일 수 없는 위험","k":"한 동네 소나기는 다른 동네로 피하면 되지만, 온 세상에 오는 장마는 피할 곳이 없어요."},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"q":"그랜빌의 이동평균선 매매법칙에서 매입신호에 해당하는 것은?","o":["상승하던 이동평균선이 보합으로 꺾이는 가운데 주가가 이동평균선을 위에서 아래로 뚫는다","하락하는 이동평균선 아래에 있던 주가가 이동평균선 근처까지 올랐다가 뚫지 못하고 다시 내린다","상승하는 이동평균선 위에서 주가가 이동평균선과 크게 벌어지며 급등한다","하락하는 이동평균선 아래에 있던 주가가 이동평균선에서 크게 멀어지며 급락한다"],"a":3,"c":"그랜빌은 주가와 이동평균선의 위치·방향 관계로 매입신호 4가지와 매도신호 4가지를 정리했어요. 주가가 이동평균선에서 지나치게 멀어지면 다시 이동평균선 쪽으로 돌아오려는 성질도 신호로 써요.","e":"하락하는 이동평균선 아래에서 주가가 이동평균선과 크게 벌어지며 급락하면, 이동평균선 쪽으로 되돌아오는 반등을 기대할 수 있어 매입신호로 봐요.","w":["이동평균선이 꺾이며 주가가 아래로 뚫는 것은 대표적인 매도신호예요.","하락 이동평균선이 저항선 역할을 해 주가가 다시 밀리는 것은 매도신호예요.","상승 이동평균선 위에서 지나치게 급등해 이격이 커지면 되돌림을 예상하는 매도신호예요.",null],"m":"그랜빌: 이평선 아래 급락(이격 과대) → 매입 · 이평선 위 급등(이격 과대) → 매도","t":"그랜빌의 매입신호","k":"고무줄을 너무 당기면(이격 과대) 다시 돌아와요. 아래로 많이 당겨졌으면 위로 튈 차례예요."},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"q":"상승 추세의 끝에서 몸통은 작고 위꼬리가 몸통보다 훨씬 길게 나타난 캔들의 이름과 의미로 옳은 것은?","o":["유성형 – 하락 반전 신호","망치형 – 상승 반전 신호","역망치형 – 상승 추세 지속 신호","도지형 – 추세 지속 확정 신호"],"a":0,"c":"캔들 하나로 된 반전 신호는 꼬리의 방향과 나타난 위치(고점·바닥)로 구분해요.","e":"고점에서 위꼬리가 길게 달린 작은 몸통 캔들은 유성형이에요. 장중에 크게 올랐다가 매도세에 밀려 되돌아온 모양이라 하락 반전을 예고해요.","w":[null,"망치형은 아래꼬리가 긴 모양으로 하락 추세의 바닥에서 나타나요.","역망치형은 유성형과 모양이 비슷하지만 바닥에서 나타나 상승 반전을 예고해요.","도지형은 시가와 종가가 거의 같아 몸통이 없는 십자 모양이에요."],"m":"유성형(고점·긴 위꼬리) = 하락 반전 · 망치형(바닥·긴 아래꼬리) = 상승 반전 · 역망치형(바닥·긴 위꼬리) = 상승 반전","t":"유성형 캔들","k":"하늘 높이 올라갔다가 떨어지는 별똥별(유성)처럼, 고점에서 치솟다 밀려 내려온 흔적이에요."},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"q":"거래량 지표에 관한 설명으로 가장 적절한 것은?","o":["OBV선이 오르면 매입세력이 흩어지고 있다는 뜻이다","주가지수로 OBV를 구하면 값싼 주식의 대량 거래가 시장 전체 거래량 흐름을 왜곡할 수 있다","VR은 상승일 거래량은 더하고 하락일 거래량은 빼서 누적한 값이다","VR이 450%를 넘으면 단기 바닥권으로 보고 매수 신호로 해석한다"],"a":1,"c":"OBV는 상승일 거래량을 더하고 하락일 거래량을 빼서 누적한 지표이고, VR은 상승일 거래량을 하락일 거래량과 비율로 비교한 지표예요.","e":"저가주는 주가가 낮아 같은 금액으로도 거래되는 주식 수가 많아요. 그래서 지수 OBV에서는 저가주 대량 거래가 시장 전체 거래량을 부풀려 왜곡할 수 있어요.","w":["OBV 상승은 매입세력의 집중(매집), 하락은 분산을 뜻해요.",null,"상승일 거래량을 더하고 하락일 거래량을 빼서 누적하는 것은 OBV예요. VR은 두 거래량의 비율이에요.","VR이 450%를 넘으면 단기 과열 경계 신호이고, 70% 이하가 바닥권 매수 시점이에요."],"m":"OBV: 상승일 +, 하락일 − 누적 · OBV↑ = 매집 · 저가주 대량거래로 왜곡 가능 · VR 450%↑ = 과열 경계 · 70%↓ = 바닥","t":"OBV·VR 지표의 해석","k":"값싼 동전 수백 개가 지폐 몇 장보다 '개수'로는 많아 보이는 것처럼, 저가주 거래가 거래량을 부풀려요."},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"q":"포터의 다이아몬드 모형에 관한 설명으로 가장 적절한 것은?","o":["관련·지원산업은 정부와 함께 간접 요인에 속한다","수요조건은 우발적 요인과 함께 간접 요인으로 분류한다","정부와 우발적 요인은 네 가지 직접 요인 모두에 영향을 주는 간접 요인이다","산업경쟁력은 새로 쌓은 경쟁자산보다 원래 가진 경쟁자원의 양이 결정한다고 본다"],"a":2,"c":"다이아몬드 모형은 요소조건, 수요조건, 관련·지원산업, 기업전략·경쟁여건의 네 가지 직접 요인과 정부·우발적 요인이라는 두 가지 간접 요인으로 산업경쟁력을 설명해요.","e":"정부와 우발적 요인(전쟁, 기술 대변혁 등)은 네 가지 직접 요인 전체에 영향을 주는 간접 요인이에요.","w":["관련·지원산업은 네 가지 직접 요인 중 하나예요.","수요조건도 직접 요인이에요.",null,"산업경쟁력 분석모형은 원래 가진 경쟁자원의 양보다 혁신과 투자로 쌓은 경쟁자산의 축적을 더 중요하게 봐요."],"m":"다이아몬드 직접 4: 요소조건 · 수요조건 · 관련·지원산업 · 기업전략·경쟁 / 간접 2: 정부 · 우발적 요인","t":"포터 다이아몬드 모형의 요인 구분","k":"네 기둥(직접 요인)이 다이아몬드를 받치고, 정부와 우연은 그 바깥에서 기둥 전체를 흔드는 바람이에요."},{"s":2,"sec":"투자분석기법","star":3,"lv":"중","rev":0,"q":"A산업은 몇 해째 매출이 시장 평균보다 느리게 늘거나 줄고 있고, 손실을 내는 업체가 늘자 많은 기업이 다른 업종으로 사업을 넓히고 있다. 산업 수명주기상 A산업이 속한 단계는?","o":["도입기","성장기","성숙기","쇠퇴기"],"a":3,"c":"산업은 도입기 → 성장기 → 성숙기 → 쇠퇴기를 거쳐요. 단계마다 매출 성장, 수익성, 기업 행동이 달라요.","e":"매출 증가율이 시장 평균에 못 미치거나 감소하고, 이익률 하락으로 적자 기업이 늘며, 업종 다각화에 나서는 기업이 많아지는 것은 쇠퇴기의 특징이에요.","w":["도입기는 제품이 처음 나와 인지도가 낮고 적자 기업이 많지만, 매출이 줄지는 않아요.","성장기는 매출이 빠르게 늘고 신규 진입이 활발해요.","성숙기는 수요가 포화되어 성장이 둔화되지만 시장 지배 기업은 안정적인 이익을 내요.",null],"m":"쇠퇴기: 매출 증가율 시장 평균↓·감소 · 적자기업↑ · 업종 다각화↑","t":"산업 라이프사이클 쇠퇴기","k":"손님이 줄어드는 가게 주인들이 하나둘 다른 장사를 겸하기 시작하면, 그 업종은 저무는 중이에요."},{"s":2,"sec":"투자분석기법","star":2,"lv":"중","rev":0,"q":"보상비율에 관한 설명으로 가장 적절하지 않은 것은?","o":["고정비용보상비율이 낮을수록 고정 재무비용 부담이 가벼워 재무적으로 여유가 있다는 뜻이다","이자보상비율은 영업이익을 이자비용으로 나눠 이자를 몇 번 갚을 수 있는지 본다","고정비용보상비율은 이자와 리스료 같은 고정 재무비용을 이익으로 감당할 수 있는 정도를 본다","고정비용보상비율이 지나치게 높다면 부채를 이용한 레버리지 효과를 충분히 활용하지 못하고 있을 수 있다"],"a":0,"c":"보상비율은 기업이 지금 짊어진 이자·고정 재무비용을 벌어들인 이익으로 감당할 수 있는지 보는 비율이에요.","e":"고정비용보상비율이 낮다는 것은 이익에 비해 고정 재무비용이 크다는 뜻이라 부담이 무거운 상태예요. 반대로 너무 높으면 안전하지만 부채를 거의 쓰지 않아 레버리지 효과를 덜 누리고 있을 수 있어요.","w":[null,"이자보상비율 = 영업이익 ÷ 이자비용이에요.","고정비용보상비율은 이자에 리스료 같은 고정비용까지 넣어 감당 능력을 봐요.","비율이 지나치게 높으면 부채 활용이 적어 레버리지 효과를 덜 누리고 있다고 해석할 수 있어요."],"m":"보상비율↓ = 고정 재무비용 부담 과중 · 보상비율↑ 지나침 = 레버리지 미활용","t":"고정비용보상비율의 해석","k":"월급으로 대출 이자를 몇 번 낼 수 있나예요. 너무 빠듯하면 위험하고, 너무 넉넉하면 빚을 지렛대로 안 쓰는 셈이에요."},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"q":"B운용사는 급히 현금이 필요해 보유한 비상장 회사채를 팔려 했지만 사려는 곳이 거의 없어, 평가가격보다 크게 낮은 값에 처분했다. B사가 겪은 재무위험으로 가장 적절한 것은?","o":["신용위험","유동성위험","운영위험","법적위험"],"a":1,"c":"재무위험은 시장위험, 신용위험, 유동성위험, 운영위험, 법적위험 등으로 나눠요.","e":"자산을 팔려 할 때 살 사람이 없어 불리한 가격에 처분해야 하는 위험은 유동성위험이에요.","w":["신용위험은 거래상대방이 돈을 갚지 못해 생기는 위험이에요.",null,"운영위험은 내부 절차·인력·시스템 실패나 외부 사건에서 생기는 위험이에요.","법적위험은 계약을 법적으로 집행할 수 없어 생기는 위험이에요."],"m":"유동성위험 = 팔고 싶을 때 제값에 못 파는 위험 · 신용 = 상대방 불이행 · 운영 = 내부 실패 · 법적 = 계약 집행 불가","t":"유동성위험의 식별","k":"급하게 집을 팔아야 하는데 사겠다는 사람이 없으면 헐값에 넘기게 돼요. 그게 유동성위험이에요."},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"q":"몬테카를로 시뮬레이션으로 주식 포지션의 VaR를 구할 때에 관한 설명으로 가장 적절하지 않은 것은?","o":["주가가 움직이는 경로를 만들어 내는 확률모형으로 기하 브라운 운동(GBM)을 흔히 쓴다","시나리오마다 포지션 가치를 다시 계산하는 완전가치평가법이다","과거에 실제로 일어난 가격 변화만 그대로 다시 적용하므로 확률모형을 따로 정할 필요가 없다","확률모형이나 모수를 잘못 정하면 VaR도 틀리게 나오는 모형위험이 있다"],"a":2,"c":"몬테카를로 시뮬레이션은 위험요인의 확률모형을 정하고 난수로 수많은 가격 경로를 만든 뒤, 경로마다 포지션을 다시 평가해 손익 분포에서 VaR를 구해요.","e":"과거 실제 가격 변화를 그대로 적용하는 것은 역사적 시뮬레이션이에요. 몬테카를로는 기하 브라운 운동 같은 확률모형을 먼저 정해야 해요.","w":["주가 시나리오는 주로 기하 브라운 운동 모형으로 만들어요.","경로마다 가치를 새로 계산하는 완전가치평가법이라 옵션 같은 비선형 포지션도 반영돼요.",null,"모형에 의존하므로 모형위험이 있고 계산량도 많아요."],"m":"몬테카를로: 확률모형(GBM) 설정 · 완전가치평가 · 비선형 반영 · 계산량↑ · 모형위험","t":"몬테카를로 시뮬레이션의 특징","k":"주사위 규칙(확률모형)을 먼저 정하고 수만 번 굴려 보는 방법이에요. 규칙이 틀리면 결과도 틀려요."},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"q":"스트레스 검증(위기상황분석)에 관한 설명으로 가장 적절한 것은?","o":["결과에 발생 확률이 함께 제시되므로 VaR를 대신하는 측정 방법으로 쓸 수 있다","여러 위험요인 사이의 상관관계를 정교하게 반영하는 데 강점이 있다","과거 관측 자료가 충분히 쌓인 상품에만 적용할 수 있다","포트폴리오 가치가 소수의 위험요인에 크게 좌우될 때 특히 쓸모가 있다"],"a":3,"c":"스트레스 검증은 금리 급등, 주가 폭락 같은 극단적 시나리오를 정해 그때 포트폴리오 가치가 얼마나 변하는지 보는 방법이에요.","e":"시나리오를 몇 개의 위험요인 변화로 짜기 때문에, 포트폴리오가 소수의 위험요인에 크게 의존할 때 특히 유용해요.","w":["시나리오는 분석자가 정하므로 발생 확률을 알려 주지 못해요. VaR를 대신하지 않고 보완해요.","위험요인 간 상관관계를 제대로 반영하지 못하는 것이 약점이에요.","가상 시나리오를 쓰므로 과거 자료가 없는 상품에도 적용할 수 있어요.",null],"m":"스트레스 검증: 극단 시나리오 · 소수 위험요인 의존 시 유용 · 확률 X · 상관관계 반영 약함 · VaR 보완","t":"스트레스 검증의 쓰임","k":"'금리가 3%p 뛰면?'처럼 몇 가지 큰 변수만 세게 흔들어 보는 시험이라, 그 몇 가지에 운명이 걸린 포트폴리오에 잘 맞아요."},{"s":2,"sec":"리스크관리","star":3,"lv":"중","rev":0,"q":"200억원을 연 3% 이자를 주는 국채에 투자했다. 이 국채의 수정듀레이션은 2.5, 만기수익률 일간 변화의 표준편차는 0.05%p이다. 95% 신뢰수준(z = 1.65)으로 1일 VaR를 구하고, 1년을 250영업일로 보아 √250 ≈ 15.8을 곱해 연간 VaR로 바꿀 때, RAROC(연간 수익 ÷ 연간 VaR)에 가장 가까운 것은?","o":["약 5.8%","약 92%","약 152%","약 1,455%"],"a":1,"c":"RAROC는 위험 한 단위당 수익이에요. 채권 포지션은 1일 VaR를 구해 연간으로 늘린 뒤, 연간 수익을 그 값으로 나눠요.","e":"1일 VaR = 200억 × 2.5 × 0.0005 × 1.65 = 0.4125억원, 연간 VaR = 0.4125 × 15.8 ≈ 6.52억원이에요. 연간 수익은 200억 × 3% = 6억원이므로 RAROC = 6 ÷ 6.52 ≈ 92%예요.","w":["연간 VaR를 구할 때 √250 대신 250을 곱했어요.",null,"신뢰수준 z값 1.65를 곱하지 않았어요(6 ÷ 3.95).","1일 VaR를 연간으로 바꾸지 않고 그대로 나눴어요."],"m":"RAROC = 연간 수익 ÷ 연간 VaR · 채권 VaR = 금액 × 수정듀레이션 × z × 금리 변동성 · 연간 = 1일 × √영업일수","t":"연간 VaR로 구하는 RAROC","k":"1년 동안 벌 6억원을, 1년 동안 각오해야 할 최대 손실 약 6.5억원과 견주는 거예요.","f":"1일 VaR = 200 × 2.5 × 0.0005 × 1.65 = 0.4125억 → 연간 ≈ 6.52억 → 6 ÷ 6.52 ≈ 92%"},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"q":"전문금융소비자인 법인 A사가 B은행과 대출성 상품 계약을 맺고 5일 뒤 청약을 철회하겠다고 알려 왔다. 금융소비자보호법상 B은행의 판단으로 가장 적절한 것은?","o":["청약철회권은 일반금융소비자에게만 인정되므로 B은행은 철회 요청을 받아들일 법적 의무가 없다","대출성 상품의 철회기간 14일 안이므로 B은행은 반드시 철회를 받아들여야 한다","철회를 받아들이되, 철회에 따른 위약금은 A사에 청구할 수 있다","전문금융소비자는 철회기간이 7일로 짧아지므로 5일째인 이번 요청은 받아들여야 한다"],"a":0,"c":"청약철회권은 계약을 맺은 뒤 일정 기간 안에 소비자가 이유를 묻지 않고 계약을 물릴 수 있는 권리예요. 정보와 협상력이 부족한 소비자를 위한 장치라서 누가 행사할 수 있는지가 정해져 있어요.","e":"청약철회권은 일반금융소비자만 행사할 수 있어요. 전문금융소비자인 A사는 기간 안이라도 법상 철회권이 없어요. 일반금융소비자라면 보장성·투자성·대출성 상품에서 행사할 수 있고, 판매업자는 위약금이나 손해배상을 청구할 수 없어요.","w":[null,"14일은 일반금융소비자가 대출성 상품을 철회할 때의 기간이에요. 전문금융소비자에게는 철회권 자체가 없어요.","철회를 이유로 위약금이나 손해배상을 청구하는 것은 금지돼요. 게다가 이 사례는 철회권이 없는 경우예요.","전문금융소비자에게 짧은 철회기간이 따로 있는 것이 아니에요. 철회권 자체가 일반금융소비자에게만 있어요."],"m":"청약철회 = 일반금융소비자만 · 보장성·투자성·대출성 · 위약금 X","t":"청약철회권의 행사 주체","k":"철회권은 '잘 모르고 샀을 수 있는 사람'을 위한 반품 제도예요. 스스로 판단할 힘이 있다고 보는 전문소비자에게는 주지 않아요."},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"q":"금융소비자보호법상 영업행위 규제 중 전문금융소비자를 상대할 때에도 지켜야 하는 것을 〈보기〉에서 모두 고른 것은?\n\n〈보기〉\nㄱ. 불공정영업행위 금지\nㄴ. 부당권유행위 금지\nㄷ. 허위·과장광고 금지\nㄹ. 적합성 원칙\nㅁ. 설명의무","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㅁ","ㄱ, ㄴ, ㄷ, ㄹ, ㅁ"],"a":1,"c":"6대 판매원칙 가운데 소비자 상황을 파악하고 맞춰 주는 원칙(적합성·적정성·설명의무)은 일반금융소비자를 보호하려는 것이에요. 반면 불공정하거나 속이는 행위를 막는 규제는 상대가 누구든 지켜야 해요.","e":"불공정영업행위 금지, 부당권유행위 금지, 광고 규제(허위·과장광고 금지)는 일반·전문금융소비자 모두에게 적용돼요. 적합성 원칙, 적정성 원칙, 설명의무는 일반금융소비자에게만 적용돼요.","w":["ㄷ도 들어가요. 광고 규제는 소비자 유형을 가리지 않아요.",null,"ㅁ 설명의무는 일반금융소비자에게만 적용되고, ㄱ 불공정영업행위 금지가 빠졌어요.","ㄹ 적합성 원칙과 ㅁ 설명의무는 전문금융소비자에게 적용되지 않아요."],"m":"공통 = 불공정 · 부당권유 · 광고 / 일반만 = 적합성 · 적정성 · 설명","t":"일반·전문 공통 영업행위 규제","k":"상대가 전문가라도 '속이거나 억지로 끼워 파는 것'은 안 돼요. 다만 '이 상품이 맞는지 살펴 주고 자세히 설명해 주는 것'은 일반 고객에게만 해 주면 돼요."},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"q":"금융위원회가 C증권의 위법행위를 확인했다. 자본시장법상 금융위원회가 할 수 있는 조치에 관한 설명으로 가장 적절하지 않은 것은?","o":["C증권의 업무 전부 또는 일부를 6개월 이내의 기간 동안 정지할 수 있다","C증권의 금융투자업 인가를 취소할 수 있다","위법행위에 관여한 C증권 직원에 대해 면직·정직·감봉 등의 조치를 C증권에 요구할 수 있다","제재는 회사와 임원만을 대상으로 하므로, 직원에 대한 조치는 C증권의 자체 징계에 맡겨야 한다"],"a":3,"c":"금융위원회는 금융투자업자가 법을 어기면 회사 자체뿐 아니라 그 일을 한 사람에게도 책임을 묻는 감독 수단을 가지고 있어요.","e":"금융위원회는 회사에 대한 인가·등록 취소, 6개월 이내 업무 정지 등은 물론, 임원뿐 아니라 직원에 대해서도 면직·정직·감봉·견책 등의 조치를 회사에 요구할 수 있어요.","w":["할 수 있어요. 6개월 이내 업무 전부 또는 일부 정지는 회사에 대한 조치예요.","할 수 있어요. 인가·등록 취소는 가장 무거운 회사 제재예요.","할 수 있어요. 직원 조치는 회사에 요구하는 방식으로 이뤄져요.",null],"m":"금융위 제재: 회사(인가취소·6개월 업무정지 등) + 임원 + 직원(면직~견책 요구)","t":"금융위원회의 금융투자업자·임직원 제재","k":"경기에서 반칙이 나오면 구단에 벌금을 매길 뿐 아니라 반칙한 선수도 징계하는 것과 같아요. 직원이라고 빠지지 않아요."},{"s":3,"sec":"직무윤리","star":2,"lv":"중","rev":0,"q":"중소형 금융투자회사 준법감시팀이 금융소비자보호 내부통제위원회에 관해 정리한 〈보기〉 중 옳은 것은 모두 몇 개인가?\n\n〈보기〉\nㄱ. 위원회는 매 반기마다 1회 이상 의무적으로 열어야 한다.\nㄴ. 위원회 개최 결과는 이사회에 보고해야 한다.\nㄷ. 위원회 관련 기록은 5년 이상 유지해야 한다.\nㄹ. 금융상품판매업자라면 회사 규모 등과 관계없이 예외 없이 위원회를 설치해야 한다.","o":["1개","2개","3개","4개"],"a":2,"c":"금융소비자보호 내부통제위원회는 소비자보호 관련 내부통제를 회사 차원에서 점검·의결하는 기구예요. 정기적으로 열고 결과를 남기도록 운영 기준이 정해져 있어요.","e":"ㄱ·ㄴ·ㄷ이 옳아요. 위원회는 반기마다 1회 이상 열고, 결과를 이사회에 보고하며, 기록을 5년 이상 유지해요. 다만 일정 요건에 해당하는 회사는 설치 의무가 면제되므로 모든 회사가 반드시 두는 것은 아니에요(ㄹ).","w":["ㄱ·ㄴ·ㄷ 세 개가 옳아요.","옳은 것을 하나 덜 셌어요. 개최 주기, 이사회 보고, 기록 유지는 모두 맞는 설명이에요.",null,"ㄹ은 틀렸어요. 일정 요건을 갖추면 설치 의무가 면제돼요."],"m":"소비자보호 내부통제위원회: 반기 1회↑ · 이사회 보고 · 기록 5년↑ · 일정 요건 시 설치 면제","t":"금융소비자보호 내부통제위원회","k":"학교 안전위원회처럼 '한 학기에 한 번은 꼭 모이고, 결과는 이사회에 올리고, 회의록은 5년 보관'이에요. 다만 아주 작은 학교는 따로 위원회를 두지 않아도 되는 것과 같아요."},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"q":"D증권 준법감시팀장이 신입사원 교육에서 한 설명이다. 내부통제 관련 기준에 비추어 가장 적절하지 않은 것은?","o":["금융사고 위험이 큰 업무를 맡은 직원에게는 회사가 휴가를 명령하고, 그동안 그 직원의 업무가 적정했는지 점검한다","여러분은 회사가 정한 준법서약서를 작성해 준법감시인에게 제출해야 한다","내부제보로 큰 금융사고를 막은 직원이라도, 제보자 보호를 위해 인사상·금전적 혜택은 줄 수 없다","비밀정보인지 애매한 정보는 준법감시인이 확인하기 전까지 비밀정보로 다룬다"],"a":2,"c":"준법감시체제는 위법행위를 미리 막고 일찍 찾아내기 위한 여러 장치로 이뤄져요. 휴가 명령, 준법서약, 내부제보, 비밀정보 관리 등이 대표적이에요.","e":"내부제보 제도는 제보자의 신분을 보호하고 불이익을 금지할 뿐 아니라, 제보가 우수한 사람에게 인사상 또는 금전적 혜택을 줄 수 있어요. 혜택을 금지한다는 설명은 틀렸어요.","w":["맞는 설명이에요. 명령휴가제도로 업무 적정성을 점검해요.","맞는 설명이에요. 준법서약서는 준법감시인에게 제출해요.",null,"맞는 설명이에요. 확인 전까지는 비밀정보로 분류·관리해요."],"m":"준법감시 수단: 명령휴가 · 준법서약서 · 내부제보(우수자 보상 O) · 애매하면 비밀정보","t":"준법감시체제 운영 수단","k":"불이 난 걸 먼저 알린 사람에게 상을 주면 다음에도 빨리 알리겠죠? 내부제보도 보호와 함께 보상으로 북돋워요."},{"s":3,"sec":"직무윤리","star":3,"lv":"중","rev":0,"q":"금융회사의 지배구조에 관한 법률상 과태료 상한이 나머지 셋과 다른 위반행위는?","o":["내부통제기준을 마련하지 않은 경우","준법감시인을 두지 않은 경우","이사회 의결을 거치지 않고 준법감시인을 임면한 경우","준법감시인에 대한 별도의 보수지급 및 평가 기준을 마련·운영하지 않은 경우"],"a":3,"c":"지배구조법은 내부통제 체계의 뼈대를 갖추지 않은 위반을 더 무겁게, 운영 기준을 지키지 않은 위반을 상대적으로 가볍게 과태료로 제재해요.","e":"준법감시인의 별도 보수·평가기준을 마련·운영하지 않으면 3천만원 이하의 과태료 대상이에요. 나머지 셋은 내부통제 체계 자체를 갖추지 않은 경우라 1억원 이하의 과태료 대상이에요.","w":["1억원 이하 과태료 대상이에요.","1억원 이하 과태료 대상이에요.","1억원 이하 과태료 대상이에요.",null],"m":"1억 이하: 기준 미마련 · 준법감시인 미선임 · 이사회 의결 없는 임면 / 3천만 이하: 보수·평가기준 미마련 · 금지 업무 겸직","t":"지배구조법 과태료 구분","k":"집에 소화기(내부통제기준)나 관리인(준법감시인) 자체가 없으면 큰 벌금, 관리인 월급 기준을 제대로 안 정해 두면 그보다 작은 벌금이에요."},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"금융투자업자 E사의 위험액이 〈자료〉와 같을 때, 순자본비율 산정에 쓰는 시장위험액과 총위험액을 순서대로 바르게 짝지은 것은?\n\n〈자료〉\n• 주식위험액: 50억원\n• 금리위험액: 30억원\n• 외환위험액: 20억원\n• 신용위험액: 40억원\n• 운영위험액: 10억원","o":["100억원 — 150억원","140억원 — 150억원","100억원 — 140억원","150억원 — 150억원"],"a":0,"c":"총위험액은 시장위험액, 신용위험액, 운영위험액을 더한 값이에요. 시장위험액은 주가·금리·환율 같은 시장 가격이 움직여 생기는 손실 위험이라 주식·금리·외환위험액 등을 더해 구해요.","e":"시장위험액 = 주식 50 + 금리 30 + 외환 20 = 100억원이에요. 총위험액 = 시장위험액 100 + 신용위험액 40 + 운영위험액 10 = 150억원이에요. 신용위험액은 거래상대방이 돈을 못 갚을 위험이라 시장위험액에 들어가지 않아요.","w":[null,"신용위험액 40억원을 시장위험액에 넣었어요. 신용위험액은 총위험액의 별도 구성 요소예요.","총위험액에서 운영위험액 10억원을 빠뜨렸어요.","시장위험액에 신용위험액과 운영위험액까지 넣었어요."],"m":"총위험액 = 시장(주식·금리·외환 등) + 신용 + 운영","t":"총위험액의 구성","k":"시장위험은 '시세가 움직여서' 잃는 돈, 신용위험은 '상대가 안 갚아서' 잃는 돈, 운영위험은 '사고·실수로' 잃는 돈이에요.","f":"시장위험액 = 50 + 30 + 20 = 100억원 · 총위험액 = 100 + 40 + 10 = 150억원"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"F증권은 투자자예탁금을 증권금융회사에 예치해 두었다. 자본시장법상 예치기관이 그 예탁금을 투자자에게 우선하여 지급해야 하는 사유로 가장 거리가 먼 것은?","o":["F증권의 금융투자업 인가가 취소된 경우","F증권이 해산을 결의한 경우","F증권이 파산선고를 받은 경우","F증권의 순자본비율이 50% 미만으로 떨어져 경영개선요구를 받은 경우"],"a":3,"c":"투자자예탁금 별도예치 제도의 목적은 증권회사가 영업을 계속할 수 없게 되었을 때 투자자 돈을 먼저 돌려주는 거예요. 그래서 우선지급은 영업이 끝나거나 끝날 상황에 연결돼 있어요.","e":"예치기관은 예치 금융투자업자가 인가 취소, 해산 결의, 파산선고, 투자매매·중개업 전부 양도·폐지 승인 등의 상황이 되면 투자자에게 예탁금을 우선 지급해요. 순자본비율 악화에 따른 경영개선요구는 적기시정조치일 뿐 우선지급 사유가 아니에요.","w":["우선지급 사유예요.","우선지급 사유예요.","우선지급 사유예요.",null],"m":"예탁금 우선지급: 인가취소 · 해산결의 · 파산선고 · 업무 전부 양도·폐지 등 / 순자본비율 악화 X","t":"투자자예탁금 우선지급 사유","k":"가게가 아예 문을 닫을 때 맡겨 둔 손님 돈을 먼저 돌려주는 거예요. 가게 형편이 나빠져 경고를 받은 단계에서는 아직 아니에요."},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"다음 발행인 가운데 자본시장법상 사업보고서를 제출하지 않아도 되는 자는? (모두 해당 증권을 증권시장에 상장했다고 가정한다)","o":["전환사채권을 상장한 회사","파생결합증권을 상장한 증권회사","투자신탁의 수익증권을 상장한 발행인","주권을 상장한 회사"],"a":2,"c":"사업보고서는 상장 증권 등을 발행한 회사가 1년 동안의 사업과 재무 상황을 알리는 정기공시예요. 다만 펀드처럼 다른 공시 체계로 정보가 제공되는 증권의 발행인은 대상에서 빠져요.","e":"집합투자증권(투자신탁 수익증권 등)의 발행인은 사업보고서 제출이 면제돼요. 펀드는 자산운용보고서, 수시공시 등 별도의 공시 체계를 따르기 때문이에요. 주권, 전환사채권, 파생결합증권 등을 상장한 발행인은 제출 대상이에요.","w":["전환사채권 같은 주권 관련 사채권 발행인은 제출 대상이에요.","파생결합증권 발행인도 제출 대상이에요.",null,"주권상장법인은 대표적인 제출 대상이에요."],"m":"사업보고서 면제 = 집합투자증권(투자신탁 수익증권) 발행인","t":"사업보고서 제출 면제 발행인","k":"펀드는 이미 '운용 성적표'를 따로 내고 있어서 회사용 연간 성적표(사업보고서)를 또 낼 필요가 없어요."},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"투자일임업자 G사가 고객과 맺으려는 투자일임계약서 조항 가운데 자본시장법상 허용되지 않는 것은?","o":["고객이 운용방법 변경이나 계약 해지를 요구하면 정당한 사유가 없는 한 이에 응한다","일임재산을 예탁할 투자중개업자를 G사가 필요할 때 다른 회사로 바꿀 수 있도록 고객이 G사에 위임한다","일반적인 거래조건에 비추어 일임재산에 유리한 경우에 한해 이해관계인의 고유재산과 거래할 수 있다","일임재산은 고객별로 구분하여 운용한다"],"a":1,"c":"투자일임업자는 고객 대신 투자판단을 하지만 고객 재산을 직접 보관하지는 않아요. 그래서 재산을 어디에 맡길지 같은 사항까지 넘겨받아 고객 재산을 사실상 쥐는 것을 막아요.","e":"일임재산을 예탁하는 투자매매업자·투자중개업자 등을 지정하거나 변경하는 권한을 위임받는 것은 금지돼요. 투자일임업자가 재산 보관처까지 좌우하면 고객 재산을 마음대로 옮길 위험이 생기기 때문이에요.","w":["허용돼요. 오히려 정당한 사유 없이 응하지 않는 것이 금지 행위예요.",null,"허용돼요. 이해관계인 거래는 원칙 금지지만 일임재산에 유리한 거래는 예외예요.","허용돼요. 고객별 구분 운용이 원칙이고, 여러 고객 재산을 모아 운용하는 것이 금지돼요."],"m":"투자일임 금지: 예탁처 지정·변경 위임 X · 의결권 위임 X · 집합운용 X · 금전 직접 보관 X","t":"투자일임업자의 불건전 영업행위","k":"운전을 맡긴 대리기사에게 차 열쇠 보관 장소까지 마음대로 바꾸게 하면 안 되는 것과 같아요."},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"상장법인 H사가 오전 9시에 중요한 계약 체결 사실을 금융위원회가 운영하는 전자공시시스템을 통해 공시했다. 자본시장법령상 이 정보가 '공개된 정보'로 인정되는 시점은?","o":["공시한 즉시(오전 9시)","공시 후 3시간이 지난 때(낮 12시)","공시 후 6시간이 지난 때(오후 3시)","공시한 다음 날 0시"],"a":1,"c":"미공개중요정보 규제는 투자자가 정보를 알 수 있게 된 뒤에야 풀려요. 그래서 공개 방법마다 시장에 퍼지는 데 걸리는 시간을 정해 두고, 그 시간이 지나야 공개된 것으로 봐요.","e":"금융위원회나 거래소가 설치·운영하는 전자전달매체로 공개한 정보는 공개된 때부터 3시간이 지나야 공개된 정보로 봐요. 오전 9시 공시라면 낮 12시가 지나야 해요. 그 전에 내부자가 이 정보로 매매하면 규제 대상이에요.","w":["공시 직후에는 아직 투자자들이 정보를 접할 시간이 없어서 공개된 것으로 보지 않아요.",null,"6시간은 방송 등 다른 매체로 공개할 때의 기준이에요.","전자전달매체 공개는 다음 날까지 기다리지 않아요."],"m":"전자전달매체(전자공시) 공개 → 3시간 경과 후 공개된 정보","t":"미공개중요정보의 공개 시점","k":"공지사항을 게시판에 붙였다고 바로 모두가 본 건 아니에요. 사람들이 볼 시간(3시간)을 준 뒤에야 '다 아는 정보'로 쳐요.","f":"09:00 + 3시간 = 12:00 이후 공개된 정보"},{"s":3,"sec":"자본시장 관련 법규","star":3,"lv":"중","rev":0,"q":"공모 집합투자기구에 관한 자본시장법상 설명으로 〈보기〉에서 옳은 것만 모두 고른 것은?\n\n〈보기〉\nㄱ. 부동산·특별자산·혼합자산 집합투자기구는 원칙적으로 환매금지형으로 설정·설립해야 한다.\nㄴ. 환매금지형 투자신탁은 환금성 보장을 위한 별도 방법을 정하지 않았다면 집합투자증권을 최초로 발행한 날부터 90일 이내에 증권시장에 상장해야 한다.\nㄷ. 집합투자업자가 산정한 기준가격이 적정한지는 일반사무관리회사가 확인한다.\nㄹ. 투자자 과반수가 동의하면 집합투자재산으로 환매대금을 지급할 수 있다.\nㅁ. 투자신탁 수익증권은 신탁원본 전액이 납입되어야 발행할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄴ, ㅁ","ㄴ, ㄷ, ㄹ","ㄱ, ㄷ, ㄹ, ㅁ"],"a":1,"c":"공모펀드는 투자자 보호를 위해 설정 형태, 상장, 가격 검증, 환매 방법, 증권 발행 시점까지 법으로 정해 둬요. 특히 가격 검증과 재산 감시는 운용사와 분리된 신탁업자가 맡아요.","e":"ㄱ·ㄴ·ㅁ이 옳아요. 공모펀드 기준가격의 적정성은 재산을 보관·감시하는 신탁업자가 확인해요(ㄷ). 금전 대신 집합투자재산 자체로 환매대금을 주려면 투자자 전원의 동의가 필요해요(ㄹ).","w":["ㅁ도 옳아요. 신탁원본이 모두 들어와야 수익증권을 발행해요.",null,"ㄷ·ㄹ은 틀렸어요. 기준가격 확인은 신탁업자, 현물 지급은 전원 동의예요. ㄱ·ㅁ도 빠졌어요.","ㄷ·ㄹ은 틀렸어요. 기준가격 확인은 신탁업자가 하고, 현물 지급은 투자자 전원이 동의해야 해요."],"m":"환매금지형 의무: 부동산·특별자산·혼합자산 · 최초 발행일부터 90일 내 상장 / 기준가격 확인 = 신탁업자 / 현물환매 = 전원 동의 / 수익증권 = 원본 전액 납입 후","t":"환매금지형·수익증권·기준가격·현물환매","k":"돈을 뺄 수 없는 펀드는 대신 시장에서 팔 수 있게 상장해 주고, 가격표는 운용사가 아닌 금고지기(신탁업자)가 검산해요."},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"q":"일반투자자 박씨가 처음으로 다음 거래를 하려 한다. 협회 규정상 거래 전에 거쳐야 할 절차를 바르게 연결한 것은?","o":["신용융자거래 — 협회가 인정하는 사전교육 이수","주식워런트증권(ELW) — 핵심설명서 추가 교부","ETN — 이미 위탁매매 계좌가 있다면 매매의사를 따로 확인할 필요 없음","주식워런트증권(ELW) — 협회가 인정하는 교육을 사전에 이수"],"a":3,"c":"위험이 큰 거래일수록 처음 거래하기 전에 투자자가 구조와 위험을 알도록 절차를 둬요. 상품에 따라 요약 설명서를 더 주기도 하고, 교육을 먼저 받게 하기도 해요.","e":"ELW는 핵심설명서 교부 대상이 아니라 협회가 인정하는 교육을 미리 이수해야 하는 상품이에요. 신용융자거래는 핵심설명서를 추가로 교부하고, ETN은 기존 계좌가 있어도 처음 매매할 때 서명 등으로 매매의사를 따로 확인해요.","w":["신용융자거래는 사전교육이 아니라 핵심설명서 추가 교부 대상이에요.","ELW는 핵심설명서 교부 대상이 아니에요. 사전교육 대상이에요.","ETN은 기존 위탁계좌가 있어도 최초 매매 시 서명 등으로 매매의사를 별도로 확인해요.",null],"m":"신용융자 = 핵심설명서 · ELW·레버리지 ETF/ETN = 사전교육 · ETN 최초 매매 = 의사 별도 확인","t":"매매 전 절차: 핵심설명서와 사전교육","k":"빚내서 주식 사기는 '요약 안내서'를 더 받고, ELW처럼 구조가 복잡한 상품은 '운전 연수'를 먼저 받아야 해요."},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"q":"I증권 금융투자분석사 갑이 J사에 대한 조사분석자료를 공표하려 한다. 협회 규정상 가장 적절한 것은?","o":["갑이 보유한 J사 관련 금융투자상품과 주식매수선택권의 보유가액 합계가 300만원 이하라면 재산적 이해관계 고지를 생략할 수 있다","갑이 J사 주식을 조금이라도 보유하고 있으면 금액과 관계없이 반드시 그 사실을 고지해야 한다","목표가격을 제시하면 충분하고, 목표가격과 실제 주가의 괴리율은 적지 않아도 된다","I증권이 J사 발행주식 총수의 1% 이상을 보유하고 있으면 고지를 하더라도 공표할 수 없다"],"a":0,"c":"조사분석자료는 많은 투자자가 판단 근거로 삼아요. 그래서 작성자와 회사의 이해관계를 알리게 하고, 목표가격의 신뢰도를 점검할 수 있는 정보도 함께 싣게 해요.","e":"금융투자분석사의 금융투자상품과 주식매수선택권 보유가액 합계가 300만원 이하라면 재산적 이해관계 고지를 생략할 수 있어요. 목표가격을 쓰면 실제 주가와의 괴리율도 표기해야 하고, 회사가 1% 이상 보유한 경우는 고지하고 공표할 수 있어요(5% 이상이면 공표 금지).","w":[null,"보유가액 합계가 300만원 이하라면 고지를 생략할 수 있어요.","목표가격을 제시할 때는 실제 주가와의 괴리율도 함께 표기해야 해요.","1% 이상은 이해관계를 고지하면 공표할 수 있어요. 공표 자체가 금지되는 것은 5% 이상 보유한 경우예요."],"m":"분석사 보유 300만원 이하 → 고지 생략 가능 · 목표가 쓰면 괴리율도 · 회사 1%↑ 고지 · 5%↑ 금지","t":"조사분석자료의 이해관계 고지와 괴리율","k":"심판이 선수 굿즈 몇 개 가진 정도(300만원 이하)는 굳이 밝히지 않아도 되지만, 예상 점수를 냈다면 실제 점수와 얼마나 달랐는지는 보여 줘야 해요."},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"q":"J자산운용이 공모펀드 신문광고 시안을 만들고 있다. 협회 규정상 이 광고에 반드시 들어가야 하는 내용은?","o":["환매수수료에 관한 사항","원금이 보장된다는 문구와 그 보장 방법","조기상환 조건","다른 운용사 MMF와 비교한 운용실적"],"a":0,"c":"펀드 투자광고는 투자자가 비용과 위험을 오해하지 않도록 꼭 넣어야 할 내용과 넣어서는 안 될 내용을 함께 정해 둬요.","e":"공모펀드 투자광고에는 환매수수료에 관한 사항을 반드시 표시해야 해요. 펀드는 실적배당 상품이라 원금보장 표시는 금지되고, 다른 회사 MMF와의 운용실적 비교도 금지돼요. 조기상환 조건은 투자권유 때 설명할 사항이지 광고 필수 항목이 아니에요.","w":[null,"펀드는 실적배당 상품이라 원금보장을 표시할 수 없어요.","조기상환 조건은 광고 필수 표시 항목이 아니에요.","다른 회사 MMF와의 운용실적 비교는 출처를 밝혀도 금지돼요."],"m":"펀드 광고: 환매수수료 필수 / 원금보장·타사 MMF 비교 금지 / 조기상환은 필수 아님","t":"공모펀드 투자광고 필수표시","k":"중도에 빼면 내는 위약금(환매수수료)은 꼭 알려야 하지만, '원금 걱정 없어요' 같은 말은 펀드에선 할 수 없어요."},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"q":"K증권 준법감시부서가 재산상 이익 제공 관리 기준을 점검하고 있다. 금융투자업규정 및 협회 규정상 가장 적절하지 않은 것은?","o":["재산상 이익을 제공하거나 받은 경우 그 목적과 내용 등을 5년 이상 기록·보관한다","동일한 거래상대방에게 이사회가 정한 금액을 넘는 재산상 이익을 주려면 이사회의 사전승인을 받는다","특정 거래상대방에게 최근 5개 사업연도 합산 10억원을 넘게 제공하면 그 내용을 인터넷 홈페이지 등에 공시한다","재산상 이익 제공현황과 적정성 점검 결과는 3년마다 한 번 이사회에 보고하면 된다"],"a":3,"c":"재산상 이익 제공은 금액 한도 대신 기록, 이사회 통제, 공시로 관리해요. 이사회가 정기적으로 현황을 들여다보는 것이 핵심이에요.","e":"재산상 이익의 제공현황과 적정성 점검 결과 등은 매년 이사회에 보고해야 해요. 3년에 한 번으로는 부족해요.","w":["맞는 설명이에요. 기록·보관 기간은 5년 이상이에요.","맞는 설명이에요. 이사회가 정한 금액을 넘으면 사전승인이 필요해요.","맞는 설명이에요. 5개 사업연도 합산 10억원 초과 시 공시해요.",null],"m":"재산상 이익: 기록 5년↑ · 이사회 기준 초과 시 사전승인 · 매년 이사회 보고 · 10억 초과 공시","t":"재산상 이익 제공의 내부 보고","k":"회사 '접대비 장부'는 5년 보관하고, 큰 금액은 이사회 허락을 먼저 받고, 1년에 한 번은 이사회에 전체 현황을 보고해요."},{"s":3,"sec":"한국금융투자협회규정","star":3,"lv":"중","rev":0,"q":"L증권이 거래상대방에게 다음을 제공했다. 협회 규정상 재산상 이익에 해당하는 것은?","o":["L증권이 자체 개발해 제공한 매매분석 소프트웨어","거래상대방 가족 경조사에 보낸 15만원짜리 화환","회사 로고를 새긴 4만 5천원짜리 기념품","연말에 나눠 준 2만원짜리 탁상달력"],"a":2,"c":"재산상 이익 규제는 거래상대방에게 경제적 가치를 주는 행위를 관리해요. 다만 업무상 자연스러운 정보 제공이나 사회 통념상 작은 금액의 물품·경조사 비용은 제외해요.","e":"물품은 3만원 이하일 때만 재산상 이익에서 빠지므로, 4만 5천원짜리 기념품은 재산상 이익이에요. 자체 작성 조사분석자료나 자체 개발 소프트웨어, 20만원 이하의 경조비·화환, 3만원 이하 물품은 재산상 이익으로 보지 않아요.","w":["자체 개발한 소프트웨어는 재산상 이익으로 보지 않아요.","20만원 이하의 경조사 화환은 재산상 이익에서 빠져요.",null,"3만원 이하 물품은 재산상 이익으로 보지 않아요."],"m":"재산상 이익 제외: 자체 리포트·소프트웨어 · 물품 3만원 이하 · 경조 화환 20만원 이하","t":"재산상 이익에 해당하는지 여부","k":"명절 달력이나 작은 화환은 인사치레지만, 3만원을 넘는 선물부터는 '관리해야 할 혜택'으로 봐요."},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"마코위츠의 평균-분산 모형에서 말하는 효율적 투자기회선(효율적 투자선)을 가장 바르게 설명한 것은?","o":["모든 위험자산을 시가총액 비중대로 담은 단 하나의 포트폴리오","무위험자산과 시장포트폴리오를 섞어 만든 직선","같은 위험에서 기대수익률이 가장 높고, 같은 기대수익률에서 위험이 가장 낮은 포트폴리오들을 위험-수익 평면에 이어 놓은 선","투자자에게 똑같은 만족을 주는 기대수익률과 위험의 조합을 이은 곡선"],"a":2,"c":"지배원리를 통과한 포트폴리오를 효율적 포트폴리오라 하고, 이들을 위험(표준편차)-기대수익률 평면에 이어 놓은 것이 효율적 투자기회선이에요.","e":"효율적 투자기회선은 지배원리(같은 위험이면 고수익, 같은 수익이면 저위험)를 만족하는 효율적 포트폴리오들의 집합이에요. 그 위의 어느 점을 고를지는 투자자의 무차별곡선이 정해요.","w":["시장포트폴리오 설명이에요. 효율적 투자기회선 위의 한 점일 뿐 선 자체가 아니에요.","자본시장선(CML) 설명이에요. 무위험자산을 넣어야 생기는 직선이에요.",null,"무차별(효용)곡선 설명이에요. 투자자의 선호를 나타내요."],"m":"효율적 투자기회선 = 효율적 포트폴리오들을 이은 선","t":"효율적 투자기회선의 정의","k":"같은 값이면 가장 좋은 물건만 골라 진열한 '베스트 상품 진열대'가 효율적 투자기회선이에요."},{"s":3,"sec":"주식투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"자산배분 과정에서 쓰는 추정 기법과 그 용도를 짝지은 것으로 가장 적절하지 않은 것은?","o":["추세분석법 — 과거 장기 수익률 흐름을 미래로 연장해 기대수익률을 추정한다","시나리오분석법 — 경제 상황별 수익률에 발생 확률을 곱해 기대수익률을 추정한다","펀더멘털분석법 — 무위험이자율에 자산별 위험프리미엄을 더하는 식으로 기대수익률을 추정한다","GARCH 모형 — 자산집단의 기대수익률을 추정하는 대표적인 방법이다"],"a":3,"c":"자산집단의 기대수익률은 추세분석법, 시나리오분석법, 펀더멘털분석법, 시장공동예측치 사용법으로 추정해요. 위험(변동성)을 추정하는 기법은 따로 있어요.","e":"GARCH는 시간에 따라 변하는 변동성(위험)을 추정하는 모형이에요. 기대수익률 추정방법이 아니에요.","w":["과거 추세를 연장하는 기대수익률 추정법이 맞아요.","상황별 수익률을 확률로 가중하는 추정법이 맞아요.","과거 자료에 위험프리미엄 구조를 더해 추정하는 방법이 맞아요.",null],"m":"기대수익률 추정: 추세·시나리오·펀더멘털·시장공동예측치 / GARCH = 변동성","t":"기대수익률 추정과 변동성 추정의 구분","k":"수익을 '얼마나 벌까'와 '얼마나 흔들릴까'는 다른 계산기로 재요. GARCH는 흔들림을 재는 계산기예요."},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"액면 20,000원, 만기 3년, 표면이율 연 5%이고 3개월마다 이자를 주는 이표채를 만기까지 보유했다. 만기일에 받는 금액은?","o":["20,000원","20,250원","21,000원","23,000원"],"a":1,"c":"이표채는 정해진 날마다 이자를 나눠 주고, 만기일에는 액면금액과 그날 지급할 마지막 이자를 함께 줘요.","e":"3개월마다 받는 이자 = 20,000 × 5% ÷ 4 = 250원이에요. 만기일에는 액면 20,000원과 마지막 이자 250원을 받아 20,250원이에요.","w":["액면만 넣고 만기일에 함께 받는 마지막 이자를 빠뜨렸어요.",null,"1년 치 이자(1,000원)를 만기일에 받는다고 봤어요. 이자는 3개월마다 250원씩 나눠 받아요.","3년 치 이자를 만기에 한꺼번에 받는 단리채처럼 계산했어요. 이표채는 중간에 이자를 이미 받았어요."],"m":"이표채 만기 = 액면 + 마지막 1회분 이자","t":"이표채 만기 현금흐름","k":"월급처럼 이자를 꼬박꼬박 받아 왔으니, 마지막 날에는 원금과 마지막 한 번의 이자만 남아요.","f":"만기 현금흐름 = 20,000 + 20,000 × 5% ÷ 4 = 20,250원"},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"앞으로 시장금리가 크게 떨어질 것으로 예상하는 운용자가 신용등급이 같은 다음 채권 가운데 하나를 사려 한다. 가장 유리한 것은?","o":["잔존만기 2년, 표면이율 6%","잔존만기 2년, 표면이율 2%","잔존만기 10년, 표면이율 6%","잔존만기 10년, 표면이율 2%"],"a":3,"c":"금리예측전략에서는 금리가 내릴 것으로 보면 듀레이션을 늘려 가격 상승폭을 키워요. 만기가 길고 표면이율이 낮을수록 듀레이션이 길어요.","e":"잔존만기가 길고 표면이율이 낮은 채권이 듀레이션이 가장 길어서, 금리가 떨어질 때 가격이 가장 많이 올라요. 반대로 금리 상승이 예상되면 단기·고쿠폰 채권으로 듀레이션을 줄여요.","w":["만기가 짧고 표면이율이 높아 듀레이션이 가장 짧아요. 금리 상승을 예상할 때 고를 채권이에요.","표면이율은 낮지만 만기가 짧아 가격 상승폭이 작아요.","만기는 길지만 표면이율이 높아 같은 만기 저쿠폰채보다 듀레이션이 짧아요.",null],"m":"금리↓ 예상 → 장기·저쿠폰(듀레이션↑) / 금리↑ 예상 → 단기·고쿠폰","t":"금리 하락 예상 시 채권 선택","k":"금리가 내려갈 때는 '가장 멀리, 가장 늦게 돈을 돌려받는' 채권이 가격이 제일 크게 뛰어요."},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"자산유동화증권(ABS)의 현금수취방식에 관한 설명으로 가장 적절한 것은?","o":["Pass-through 방식은 상환 순서가 다른 여러 트랜치로 나누어 발행하는 데 알맞다","Pay-through 방식은 기초자산의 현금흐름을 재구성해 만기와 상환 우선순위가 다른 여러 종류의 증권으로 발행할 수 있다","Pass-through 증권은 발행기관(SPC)의 부채가 되는 채권형 증권이다","Pay-through 방식에서는 기초자산에서 나온 원리금이 아무 조정 없이 투자자에게 그대로 넘어간다"],"a":1,"c":"Pass-through는 기초자산 묶음의 지분을 파는 방식(지분이전형)이고, Pay-through는 그 현금흐름을 바탕으로 SPC가 채권을 발행하는 방식(채권형)이에요.","e":"Pay-through는 기초자산 현금흐름을 다시 짜서 만기·우선순위가 다른 다단계(트랜치) 증권을 발행할 수 있어요. Pass-through는 원리금을 그대로 넘겨 주는 단일 구조라 투자자가 조기상환위험을 그대로 져요.","w":["다단계 트랜치 발행은 Pay-through 방식의 특징이에요.",null,"Pass-through는 투자자가 기초자산 지분을 갖는 지분형이에요. 채권형은 Pay-through예요.","원리금을 그대로 넘기는 것은 Pass-through 방식이에요."],"m":"Pass-through = 지분형·그대로 전달 / Pay-through = 채권형·다단계 트랜치","t":"ABS 현금수취방식","k":"Pass-through는 받은 택배를 그대로 전달하는 것, Pay-through는 내용물을 다시 포장해 여러 상자로 나눠 보내는 거예요."},{"s":3,"sec":"채권투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"잔존만기가 3년 남은 복리채(만기에 원리금 일시 지급)와 잔존만기 3년·표면이율 연 4%(연 1회 지급)인 이표채의 맥컬리 듀레이션을 비교한 설명으로 가장 적절한 것은?","o":["복리채는 3년, 이표채는 3년보다 짧다","두 채권 모두 3년이다","복리채는 3년보다 짧고, 이표채는 3년이다","복리채는 이자가 복리로 불어나므로 3년보다 길다"],"a":0,"c":"맥컬리 듀레이션은 현금흐름이 들어오는 시점을 현재가치로 가중평균한 값이에요. 중간에 받는 돈이 없으면 듀레이션은 잔존만기와 같아요.","e":"복리채는 중간 현금흐름 없이 만기에 원리금을 한 번에 받으므로 듀레이션이 잔존만기 3년과 같아요. 이표채는 중간에 이자를 받으므로 3년보다 짧아요.","w":[null,"이표채는 1·2년 차에 이자를 받으므로 듀레이션이 만기보다 짧아요.","두 채권의 성질을 뒤바꿨어요. 만기 일시 지급인 복리채가 잔존만기와 같아요.","듀레이션은 현금흐름 시점의 평균이라 잔존만기를 넘을 수 없어요."],"m":"복리채·할인채(무이표) D = 잔존만기 / 이표채 D < 잔존만기","t":"복리채와 이표채의 듀레이션","k":"돈을 마지막 날 한 번에 받으면 '평균적으로 돈 받는 날'도 바로 그 마지막 날이에요."},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"파생상품에 관한 설명으로 가장 적절하지 않은 것은?","o":["스왑은 대부분 장외에서 당사자끼리 맺는 계약으로 거래된다","선도거래는 계약 조건이 당사자마다 달라서 같은 조건의 선물거래보다 유동성이 낮다","장내파생상품은 거래소가 정한 표준화된 조건으로 거래된다","신용위험은 눈에 보이는 상품이 아니므로 파생상품의 기초자산이 될 수 없다"],"a":3,"c":"파생상품은 기초자산 가격에 따라 가치가 정해지는 계약이에요. 거래소에서 표준 조건으로 거래하면 장내, 당사자끼리 맞춤 계약을 하면 장외예요.","e":"신용위험도 기초자산이 될 수 있어요. 신용부도스왑(CDS) 같은 신용파생상품은 신용위험 자체를 사고팔아요.","w":["스왑은 대표적인 장외파생상품이에요.","맞춤형 계약이라 사고팔 상대를 찾기 어려워 유동성이 낮아요.","거래소 상품은 계약 단위·만기 등이 표준화돼 있어요.",null],"m":"기초자산 = 금융상품·일반상품·신용위험 등 / 선도 = 장외·유동성 낮음","t":"파생상품의 기초자산과 거래 형태","k":"보험처럼 '부도가 날 위험' 자체도 사고팔 수 있는 상품이 될 수 있어요."},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"코스피200 현물지수가 352.0pt이고 같은 시점 최근월물 선물가격이 350.5pt이다. (ㄱ) 베이시스와 (ㄴ) 시장 상태를 순서대로 짝지은 것은? (베이시스 = 선물가격 − 현물가격)","o":["+1.5pt — 콘탱고","−1.5pt — 콘탱고","−1.5pt — 백워데이션","+1.5pt — 백워데이션"],"a":2,"c":"베이시스는 선물가격과 현물가격의 차이예요. 선물가격이 현물보다 높은 정상시장을 콘탱고, 현물이 선물보다 높은 역조시장을 백워데이션이라고 해요.","e":"베이시스 = 350.5 − 352.0 = −1.5pt예요. 현물가격이 선물가격보다 높으므로 백워데이션(역조시장)이에요.","w":["빼는 순서를 바꿨고, 시장 상태도 반대예요.","베이시스는 맞지만 현물이 더 비싸면 콘탱고가 아니라 백워데이션이에요.",null,"시장 상태는 맞지만 베이시스 부호가 반대예요. 선물가격에서 현물가격을 빼요."],"m":"베이시스 = F − S / F > S 콘탱고, S > F 백워데이션","t":"베이시스와 백워데이션","k":"보통은 나중 물건(선물)이 보관비만큼 더 비싼데, 지금 물건(현물)이 더 비싸면 '거꾸로 된' 백워데이션이에요.","f":"베이시스 = 350.5 − 352.0 = −1.5pt"},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"주가지수선물을 이용한 헤지에 관한 설명으로 가장 적절한 것은? (베이시스 = 선물가격 − 현물가격)","o":["헤지 기간 중 베이시스가 변해도 헤지 포지션 전체 손익은 언제나 0이다","선물 만기일에 현물과 선물 포지션을 함께 청산하면 베이시스가 0이 되어 제로 베이시스 헤지가 된다","선물 만기보다 일찍 청산할수록 베이시스가 0에 가까워져 헤지가 완벽해진다","제로 베이시스 헤지는 헤지를 시작할 때 베이시스가 0인 경우에만 가능하다"],"a":1,"c":"선물가격은 만기에 현물가격과 같아지므로 베이시스는 만기에 0으로 수렴해요. 만기 전에 청산하면 그때의 베이시스를 미리 알 수 없어 베이시스 위험이 남아요.","e":"선물 만기 시점에 두 포지션을 함께 청산하면 청산 시 베이시스가 0이라 처음 정한 선물가격이 그대로 확보돼요. 이것이 제로 베이시스 헤지예요.","w":["베이시스가 변하면 헤지 손익이 생겨요. 이것이 베이시스 위험이에요.",null,"만기 전에 청산하면 오히려 청산 시점의 베이시스가 불확실해요.","시작 시 베이시스와 상관없이 만기에 청산하면 달성돼요."],"m":"제로 베이시스 헤지 = 선물 만기에 함께 청산","t":"제로 베이시스 헤지","k":"약속한 날(만기)에 맞춰 정산하면 두 가격이 딱 맞아떨어져 오차가 남지 않아요."},{"s":3,"sec":"파생상품투자운용/투자전략","star":3,"lv":"중","rev":0,"q":"〈보기〉의 옵션 포지션 가운데 옵션이 행사되면 행사가격에 기초자산을 '사게' 되는 것만 모두 고른 것은?\nㄱ. 콜옵션 매수\nㄴ. 콜옵션 매도\nㄷ. 풋옵션 매수\nㄹ. 풋옵션 매도","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":1,"c":"콜은 살 권리, 풋은 팔 권리예요. 권리를 산 쪽이 행사하면, 권리를 판 쪽은 그 반대 거래를 해 줘야 해요.","e":"콜 매수자는 행사하면 기초자산을 사요(ㄱ). 풋 매수자가 행사하면 기초자산을 팔고, 상대인 풋 매도자는 그것을 사 줘야 해요(ㄹ). 콜 매도자와 풋 매수자는 기초자산을 팔게 돼요.","w":["풋 매수자는 행사하면 기초자산을 '팔아요'.",null,"두 포지션 모두 행사되면 기초자산을 파는 쪽이에요.","콜 매도자는 행사되면 기초자산을 넘겨줘야 해서 파는 쪽이에요."],"m":"행사 시 사는 쪽: 콜 매수·풋 매도 / 파는 쪽: 콜 매도·풋 매수","t":"옵션 행사 시 기초자산 매매 방향","k":"풋을 판 사람은 '떨어져도 정가에 사 줄게'라고 약속한 사람이라, 행사되면 사야 해요."},{"s":3,"sec":"투자운용결과분석","star":3,"lv":"중","rev":0,"q":"시장 수익률이 −10%가 될 때, 다음 주식 가운데 수익률이 가장 높을 것으로 예상되는 것은? (무위험이자율 0%, 잔차는 무시한다)\n• 갑: 베타 1.3\n• 을: 베타 0.4\n• 병: 베타 −0.3\n• 정: 베타 −0.8","o":["갑","을","병","정"],"a":3,"c":"베타는 시장이 움직일 때 그 주식이 얼마나, 어느 방향으로 움직이는지 보여 줘요. 베타가 음(−)이면 시장과 반대로 움직여요.","e":"예상 수익률 ≈ 베타 × 시장 수익률이에요. 갑 −13%, 을 −4%, 병 +3%, 정 +8%예요. 시장이 내릴 때는 음의 베타이면서 절댓값이 가장 큰 정이 가장 많이 올라요.","w":["베타가 커서 시장보다 더 많이 떨어져요(약 −13%).","베타가 작아 덜 떨어질 뿐 여전히 손실이에요(약 −4%).","오르기는 하지만 절댓값이 작아 상승폭이 정보다 작아요(약 +3%).",null],"m":"시장 하락 시: 음의 베타 + 절댓값 클수록 수익↑","t":"음의 베타와 시장 하락기 수익","k":"다들 미끄럼틀을 내려갈 때, 반대 방향 시소에 탄 사람(음의 베타)은 올라가요. 시소 팔이 길수록(절댓값↑) 더 높이 올라가요.","f":"예상 수익률 = 베타 × (−10%) → 정: −0.8 × (−10%) = +8%"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"q":"이자율 기간구조 이론에 관한 설명으로 가장 적절하지 않은 것은?","o":["불편기대이론은 장단기 채권을 완전한 대체재로 보고, 장기금리를 예상 단기금리들의 평균으로 설명한다","유동성프리미엄이론은 장기금리를 예상 단기금리의 평균에 유동성 프리미엄을 더한 값으로 본다","특정시장선호이론은 장기금리를 예상 단기금리의 평균에 기간프리미엄을 더한 값으로 보며, 이 프리미엄은 음(−)이 될 수도 있다","시장분할이론은 장단기 채권이 불완전한 대체관계라서 금리 차이가 충분하면 투자자가 다른 만기로 옮겨 간다고 본다"],"a":3,"c":"기간구조 이론은 장단기 채권을 서로 바꿔 살 수 있다고 보는지(대체관계)와, 장기금리에 덧붙는 프리미엄이 있는지로 구분해요.","e":"시장분할이론은 만기별 시장이 완전히 나뉘어 장단기 채권 사이에 대체관계가 없다고 봐요. 보상이 충분하면 다른 만기로 옮겨 간다고 보는 것은 특정시장선호이론이에요.","w":["불편기대이론의 핵심 가정과 결론이에요.","유동성 프리미엄은 만기가 길수록 커지는 양(+)의 값이에요.","선호하는 만기를 벗어나게 하려면 기간프리미엄이 필요하고, 그 부호는 상황에 따라 달라요.",null],"m":"불편기대 = 완전대체·평균 / 유동성P = 평균 + 유동성P / 특정시장선호 = 평균 + 기간P(±) / 시장분할 = 대체 없음","t":"이자율 기간구조 이론 비교","k":"시장분할이론은 '단기 동네·장기 동네가 담으로 막혀 있다', 특정시장선호이론은 '단골 동네는 있지만 할인이 크면 옆 동네도 간다'예요."},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"q":"현재 1년 만기 이자율은 2.0%이고, 1년 후와 2년 후의 1년 만기 이자율은 각각 2.5%, 3.0%로 예상된다. 3년 만기 채권의 이자율이 3.5%일 때 유동성프리미엄이론에 따른 3년 만기 채권의 유동성 프리미엄은? (산술평균으로 근사한다)","o":["0.5%","1.0%","1.5%","2.5%"],"a":1,"c":"유동성프리미엄이론에서 장기금리는 예상 단기금리의 평균에 유동성 프리미엄을 더한 값이에요. 그래서 유동성 프리미엄은 장기금리에서 그 평균을 빼서 구해요.","e":"예상 단기금리 평균 = (2.0 + 2.5 + 3.0) ÷ 3 = 2.5%예요. 유동성 프리미엄 = 3.5% − 2.5% = 1.0%예요.","w":["마지막 해의 예상 금리(3.0%)만 뺐어요. 세 기간의 평균을 빼야 해요.",null,"현재 1년 금리(2.0%)만 뺐어요. 앞으로 예상되는 금리까지 평균해야 해요.","예상 단기금리의 평균(2.5%)을 프리미엄으로 착각했어요."],"m":"유동성 프리미엄 = 장기금리 − 예상 단기금리 평균","t":"유동성 프리미엄 역산","k":"3년 동안 평균 2.5%면 충분한데 3.5%를 준다면, 남는 1%가 '오래 묶이는 대가'예요.","f":"3.5 − (2.0 + 2.5 + 3.0) ÷ 3 = 1.0%"},{"s":3,"sec":"거시경제","star":3,"lv":"중","rev":0,"q":"합리적 기대를 전제로 한 새고전학파의 견해로 가장 적절하지 않은 것은?","o":["경제주체가 정책 규칙을 알고 있으면 예상된 통화량 증가는 물가만 올리고 산출은 바꾸지 못한다","예상하지 못한 통화량 증가는 일시적으로 산출을 늘릴 수 있다","중앙은행이 예상 밖 통화 충격을 자주 반복해도 그 효과는 꾸준히 유지되므로 경기 안정화 수단으로 쓸 만하다","중앙은행 정책의 신뢰가 높을수록 물가를 낮추는 과정의 산출 손실이 작아진다"],"a":2,"c":"합리적 기대 가설에서는 사람들이 쓸 수 있는 모든 정보로 미래를 예상해요. 그래서 정책은 '예상하지 못했을 때'만 실물에 영향을 줘요.","e":"화폐 충격을 자주 쓰면 민간이 그 패턴을 학습해 미리 예상하게 되므로 더 이상 '예상 밖'이 아니에요. 그러면 효과가 사라져 물가만 올라가요.","w":["예상된 정책은 물가에만 반영된다는 정책무력성 정리예요.","예상 밖의 충격만 단기적으로 실물에 영향을 줘요.",null,"사람들이 정책을 믿으면 기대인플레이션이 바로 낮아져 비용이 작아져요."],"m":"예상 밖 화폐충격만 효과 → 자주 쓰면 예상되어 효과 소멸","t":"반복된 화폐충격의 효과","k":"깜짝 파티도 매주 열면 아무도 놀라지 않아요."},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"q":"많은 종목으로 잘 분산된 포트폴리오의 위험에 관한 설명으로 가장 적절한 것은?","o":["개별 종목이 포트폴리오 위험에 기여하는 크기는 그 종목 자체의 분산이 결정한다","종목 수가 충분히 많아지면 포트폴리오 분산은 종목들 사이의 평균 공분산에 가까워진다","종목 수를 계속 늘리면 포트폴리오 분산은 0으로 수렴한다","n개 종목으로 마코위츠 모형을 쓰려면 서로 다른 공분산 n²개를 추정해야 한다"],"a":1,"c":"포트폴리오 분산은 개별 분산 항과 공분산 항으로 이루어져요. 종목이 늘수록 개별 분산 항의 비중은 줄고 공분산 항이 대부분을 차지해요.","e":"종목 수를 늘리면 개별 분산의 영향은 사라지고 평균 공분산만 남아요. 그래서 한 종목이 포트폴리오 위험에 미치는 영향은 그 종목의 분산이 아니라 다른 종목들과의 공분산이 정해요.","w":["잘 분산된 포트폴리오에서 개별 종목의 기여를 정하는 것은 다른 종목들과의 공분산이에요.",null,"공분산으로 남는 체계적 위험은 분산투자로 없앨 수 없어요.","서로 다른 공분산은 n(n − 1) ÷ 2개예요."],"m":"분산된 포트폴리오 위험 → 평균 공분산 / 개별 기여 = 공분산","t":"포트폴리오 위험과 공분산","k":"사람이 많은 합창단에서는 한 명의 목소리 크기보다 다 같이 얼마나 맞춰 부르느냐(공분산)가 전체 소리를 정해요."},{"s":3,"sec":"분산투자기법","star":3,"lv":"중","rev":0,"q":"A주식에 60%, B주식에 40%를 투자했다. 〈보기〉의 시나리오로 구한 포트폴리오 기대수익률은?\n• 호황(확률 40%): A 20%, B 5%\n• 불황(확률 60%): A −5%, B 10%","o":["6.5%","6.2%","7.5%","8.8%"],"a":1,"c":"먼저 시나리오 확률로 종목별 기대수익률을 구하고, 그다음 투자비중으로 가중평균해 포트폴리오 기대수익률을 구해요.","e":"E(A) = 0.4 × 20% + 0.6 × (−5%) = 5%, E(B) = 0.4 × 5% + 0.6 × 10% = 8%예요. 포트폴리오 = 0.6 × 5% + 0.4 × 8% = 6.2%예요.","w":["종목별 기대수익률(5%, 8%)을 투자비중 없이 단순 평균했어요.",null,"시나리오 확률을 무시하고 두 상황 수익률을 단순 평균했어요.","시나리오 확률(40 : 60)과 투자비중(60 : 40)을 서로 바꿔 넣었어요."],"m":"확률로 종목 E(R) → 투자비중으로 가중평균","t":"시나리오별 포트폴리오 기대수익률","k":"날씨별 매출로 가게마다 평균 매출을 먼저 내고, 내가 가진 지분만큼 나눠 받는 셈이에요.","f":"E(A) = 5%, E(B) = 8% → 0.6 × 5 + 0.4 × 8 = 6.2%"}],"unitOrder":["세제관련 법규/세무전략","금융상품","부동산관련 상품","대안투자운용/투자전략","해외증권투자운용/투자전략","투자분석기법","리스크관리","직무윤리","자본시장 관련 법규","한국금융투자협회규정","주식투자운용/투자전략","채권투자운용/투자전략","파생상품투자운용/투자전략","투자운용결과분석","거시경제","분산투자기법"],"bankVer":"2026-11-800c"});
